def _batched_host_scalar_values(values: Sequence[torch.Tensor]) -> tuple[float, ...]:
    """Read an ordered group of device scalars through one host transfer.

    Each input reduction has already run in a common dtype.  Stacking before ``cpu()`` replaces one
    stream-draining read per scalar with one ordered batch read, without launching one cast kernel
    per scalar.  Callers deliberately keep their Python-float EMA arithmetic unchanged.
    """

    if not values:
        return ()
    first = values[0]
    if not torch.is_tensor(first) or first.numel() != 1:
        raise ValueError("batched host scalar read requires scalar tensors")
    scalars = []
    first_dtype = first.dtype
    first_device = first.device
    for value in values:
        if not torch.is_tensor(value) or value.numel() != 1:
            raise ValueError("batched host scalar read requires scalar tensors")
        if value.dtype != first_dtype or value.device != first_device:
            raise ValueError(
                "batched host scalar read requires one common dtype and device"
            )
        scalars.append(value.detach().reshape(()))
    return tuple(float(value) for value in torch.stack(scalars).cpu().tolist())


def _action_ball_validate_tensor_predicate(
    predicate: torch.Tensor,
    message: str,
    *,
    async_validate: bool,
) -> None:
    """Keep diagnostic invariants on device without weakening formal failure boundaries.

    The formal/default path deliberately retains its immediate synchronous exception.  An
    explicitly unauthorized diagnostic run may queue the same scalar assertion on CUDA instead:
    stream ordering keeps it ahead of all dependent state writes, while the next ordinary trainer
    synchronization still fails the run.  CPU remains the precise-message negative-control oracle.
    """

    if type(async_validate) is not bool:
        raise TypeError("ActionBall async_validate must be an exact boolean")
    if not torch.is_tensor(predicate):
        raise TypeError("ActionBall tensor validation requires a tensor predicate")
    scalar = torch.all(predicate)
    if async_validate and scalar.device.type == "cuda":
        assert_fn = getattr(torch, "_assert_async", None)
        if not callable(assert_fn):  # pragma: no cover - older than the supported Pod torch
            raise RuntimeError(
                "torch._assert_async is required for diagnostic ActionBall validation"
            )
        assert_fn(scalar)
        return
    if not bool(scalar):
        raise RuntimeError(message)


def _action_ball_diagnostic_host_packet(
    *,
    orphan_exact: torch.Tensor,
    identity_drift: torch.Tensor,
    exact_any: torch.Tensor,
    metric_scalars: Sequence[torch.Tensor] = (),
) -> tuple[bool, bool, bool, tuple[float, ...]]:
    """Transfer diagnostic step predicates and already-reduced metrics in one ordered packet."""

    telemetry = tuple(metric_scalars)
    packet_dtype = telemetry[0].dtype if telemetry else torch.float32
    packet = _batched_host_scalar_values(
        (
            orphan_exact.to(dtype=packet_dtype),
            identity_drift.to(dtype=packet_dtype),
            exact_any.to(dtype=packet_dtype),
            *telemetry,
        )
    )
    return (
        bool(packet[0]),
        bool(packet[1]),
        bool(packet[2]),
        tuple(packet[3:]),
    )


def _action_ball_host_bool_packet(
    predicates: Sequence[torch.Tensor],
) -> tuple[bool, ...]:
    """Read ordered scalar boolean predicates through one host transfer."""

    values = tuple(predicates)
    if not values:
        return ()
    first = values[0]
    if (
        not torch.is_tensor(first)
        or first.numel() != 1
        or first.dtype != torch.bool
    ):
        raise ValueError(
            "ActionBall predicate packet requires scalar boolean tensors"
        )
    first_device = first.device
    scalars = []
    for value in values:
        if (
            not torch.is_tensor(value)
            or value.numel() != 1
            or value.dtype != torch.bool
            or value.device != first_device
        ):
            raise ValueError(
                "ActionBall predicate packet requires one device of scalar "
                "boolean tensors"
            )
        scalars.append(value.detach().reshape(()))
    return tuple(
        bool(value)
        for value in torch.stack(scalars).cpu().tolist()
    )


def _action_ball_pack_diagnostic_install_rows(
    *,
    receipts: Sequence[object],
    counter_rally_identities: Sequence[object] | None,
    dtype: torch.dtype,
    device: torch.device | str,
) -> torch.Tensor:
    """Materialize one diagnostic reset batch with exactly one host-to-device copy.

    Receipts are already immutable, fully validated host objects.  The formal path keeps its
    individually materialized tensors; an explicitly unauthorized diagnostic run packs the same
    ordered values on the host and transfers one rectangular tensor before taking device views.
    Column 30 is the receipt-owned initial time-to-contact.  Optional counter-rally columns follow
    it in the order return-direction XY, target baseline speed.
    """

    identity_rows = (
        None
        if counter_rally_identities is None
        else tuple(counter_rally_identities)
    )
    receipt_rows = tuple(receipts)
    if identity_rows is not None and len(identity_rows) != len(receipt_rows):
        raise RuntimeError(
            "diagnostic ActionBall install counter-rally batch length mismatch"
        )
    host_rows = []
    for index, receipt in enumerate(receipt_rows):
        row = (
            *receipt.ball_contact_w_m,
            *receipt.racket_site_target_w_m,
            *receipt.base_goal_w_m,
            *receipt.racket_face_center_velocity_w_mps,
            *receipt.racket_site_velocity_w_mps,
            *receipt.racket_command_quat_wxyz,
            *receipt.racket_normal_w,
            *receipt.incoming_velocity_w_mps,
            *receipt.incoming_spin_w_radps,
            *receipt.landing_aim_w_xy_m,
            float(receipt.time_to_contact_s),
        )
        if identity_rows is not None:
            identity = identity_rows[index]
            row = (
                *row,
                *identity.return_direction_env_xy,
                float(identity.target_baseline_speed_mps),
            )
        host_rows.append(row)
    host_tensor = torch.tensor(host_rows, dtype=dtype, device="cpu")
    return host_tensor.to(device=device)


