def _assert_task_first_recipe_is_coherent(cfg) -> None:
    """Fail closed on task producers and actor defects that would split one atomic task.

    ``action_one_hot`` is currently the live local clip slot.  Until that identity rides in the
    same delayed/noisy tuple as position, velocity, face and base, task-first refuses every actor
    defect and planner-revision path.  Defaults remain untouched for every other target mode.
    """

    if str(getattr(cfg, "target_mode", "")) != "task_first":
        return
    failures = []

    def _off(name, value, expected):
        if value != expected:
            failures.append(f"{name}={value!r} (required {expected!r})")

    _off("question_bank", str(getattr(cfg, "question_bank", "") or ""), "")
    _off(
        "question_bank_allow_legacy",
        bool(getattr(cfg, "question_bank_allow_legacy", False)),
        False,
    )
    _off("cq_anchor_bank", str(getattr(cfg, "cq_anchor_bank", "") or ""), "")
    _off("exam_bank", str(getattr(cfg, "exam_bank", "") or ""), "")
    _off("achieved_target_mix_prob", float(getattr(cfg, "achieved_target_mix_prob", 0.0)), 0.0)
    _off("midswing_resample_prob", float(getattr(cfg, "midswing_resample_prob", 0.0)), 0.0)
    _off("virtual_ball", bool(getattr(cfg, "virtual_ball", False)), False)
    _off("vb_metrics_only", bool(getattr(cfg, "vb_metrics_only", False)), False)
    _off("physical_ball", bool(getattr(cfg, "physical_ball", False)), False)
    _off("shadow_ball", bool(getattr(cfg, "shadow_ball", False)), False)
    _off("shadow_table", bool(getattr(cfg, "shadow_table", False)), False)
    _off("planner_revision_enabled", bool(getattr(cfg, "planner_revision_enabled", False)), False)
    _off("target_delay_steps", int(getattr(cfg, "target_delay_steps", 0)), 0)
    _off("target_delay_tts_mode", str(getattr(cfg, "target_delay_tts_mode", "live")), "live")
    for name in (
        "target_jitter_pos_per_s",
        "target_jitter_vel_per_s",
        "target_noise_white",
        "target_noise_ar1_sigma",
        "target_dropout_prob",
        "target_post_strike_dropout_s",
        "target_bias_per_swing",
    ):
        _off(name, float(getattr(cfg, name, 0.0)), 0.0)
    if not bool(getattr(cfg, "face_command", False)):
        failures.append("face_command=False (required True)")
    if str(getattr(cfg, "face_command_pairing", "shared_plus_y")) != "shared_plus_y":
        failures.append(
            "face_command_pairing must be 'shared_plus_y' so demanded and measured faces share "
            "the raw +Y/A frame"
        )
    names = tuple(str(name) for name in (getattr(cfg, "clip_names_per_clip", ()) or ()))
    if not names:
        failures.append("clip_names_per_clip is empty (task-first needs one ordered action per clip)")
    manifest_path = str(getattr(cfg, "task_first_manifest_path", "") or "")
    manifest_sha = str(getattr(cfg, "task_first_manifest_sha256", "") or "")
    if not manifest_path:
        failures.append("task_first_manifest_path is empty")
    if (
        len(manifest_sha) != 64
        or manifest_sha != manifest_sha.lower()
        or any(character not in "0123456789abcdef" for character in manifest_sha)
    ):
        failures.append(
            "task_first_manifest_sha256 must be exactly 64 lowercase hexadecimal characters"
        )
    threshold = getattr(cfg, "task_first_base_success_thresh_m", 0.0)
    if (
        isinstance(threshold, bool)
        or type(threshold) not in (int, float)
        or not math.isfinite(float(threshold))
        or float(threshold) <= 0.0
    ):
        failures.append("task_first_base_success_thresh_m must be a finite positive number")
    if failures:
        raise ValueError(
            "target_mode='task_first' has an incoherent launch recipe:\n  - "
            + "\n  - ".join(failures)
        )


def _assert_action_ball_recipe_is_coherent(cfg) -> None:
    """Fail closed on half-configured action-conditioned ball-first launches.

    This is deliberately a separate guard from ``task_first``.  The legacy task-first mode keeps
    its ball-free contract; ``action_ball`` is the explicit action -> incoming ball -> fixed-action
    solve mode and may use the same virtual ball that was installed with its solved task.
    """

    target_mode = str(getattr(cfg, "target_mode", ""))
    reference_guard_mode = getattr(
        cfg, "reference_guard_mode", "phase_gated"
    )
    if type(reference_guard_mode) is not str or reference_guard_mode not in (
        "phase_gated",
        "metrics_only",
    ):
        raise ValueError(
            "reference_guard_mode must be exactly one of "
            "('phase_gated', 'metrics_only'); "
            f"got {reference_guard_mode!r}"
        )
    if target_mode == "action_ball_full_mdp":
        # The fresh task has a different construction owner.  In particular,
        # it must not be admitted by (or rejected for failing) the legacy
        # manifest/sampler/analytic-ball launch recipe below.
        return
    if target_mode != "action_ball":
        if reference_guard_mode != "phase_gated":
            raise ValueError(
                "reference_guard_mode='metrics_only' is ActionBall-only; "
                f"target_mode={target_mode!r}"
            )
        return
    failures = []

    def _off(name, value, expected):
        if value != expected:
            failures.append(f"{name}={value!r} (required {expected!r})")

    # There is exactly one producer.  Bank/CQ/HER/refinement/transport paths would otherwise
    # overwrite only part of the atomically solved ball/task tuple.
    _off("question_bank", str(getattr(cfg, "question_bank", "") or ""), "")
    _off(
        "question_bank_allow_legacy",
        bool(getattr(cfg, "question_bank_allow_legacy", False)),
        False,
    )
    _off("cq_anchor_bank", str(getattr(cfg, "cq_anchor_bank", "") or ""), "")
    _off("exam_bank", str(getattr(cfg, "exam_bank", "") or ""), "")
    _off(
        "achieved_target_mix_prob",
        float(getattr(cfg, "achieved_target_mix_prob", 0.0)),
        0.0,
    )
    _off(
        "midswing_resample_prob",
        float(getattr(cfg, "midswing_resample_prob", 0.0)),
        0.0,
    )
    _off(
        "planner_revision_enabled",
        bool(getattr(cfg, "planner_revision_enabled", False)),
        False,
    )
    _off("target_delay_steps", int(getattr(cfg, "target_delay_steps", 0)), 0)
    _off(
        "target_delay_tts_mode",
        str(getattr(cfg, "target_delay_tts_mode", "live")),
        "live",
    )
    for name in (
        "target_jitter_pos_per_s",
        "target_jitter_vel_per_s",
        "target_noise_white",
        "target_noise_ar1_sigma",
        "target_dropout_prob",
        "target_post_strike_dropout_s",
        "target_bias_per_swing",
    ):
        _off(name, float(getattr(cfg, name, 0.0)), 0.0)

    # The analytic virtual ball is allowed because action_ball installs its exact incoming state.
    # The two PhysX ball drivers still have their own lifecycle and cannot yet consume the immutable
    # action-ball receipt, so enabling either would silently serve a different question.
    _off("physical_ball", bool(getattr(cfg, "physical_ball", False)), False)
    _off(
        "physical_ball_impulse",
        bool(getattr(cfg, "physical_ball_impulse", False)),
        False,
    )
    _off("shadow_ball", bool(getattr(cfg, "shadow_ball", False)), False)
    _off("shadow_table", bool(getattr(cfg, "shadow_table", False)), False)
    if not (
        bool(getattr(cfg, "virtual_ball", False))
        or bool(getattr(cfg, "vb_metrics_only", False))
    ):
        failures.append(
            "virtual_ball=False and vb_metrics_only=False (one authoritative virtual scorer "
            "must close every installed action-ball attempt)"
        )

    if not bool(getattr(cfg, "face_command", False)):
        failures.append("face_command=False (required True)")
    if str(getattr(cfg, "face_command_pairing", "shared_plus_y")) != "shared_plus_y":
        failures.append(
            "face_command_pairing must be 'shared_plus_y' so the fixed-action solver and "
            "runtime reward grade the same raw +Y/A-frame face"
        )
    if not bool(getattr(cfg, "action_ball_fixed_direction", False)):
        failures.append(
            "action_ball_fixed_direction=False (required True; free-direction solve changes "
            "the selected action into a hidden selector)"
        )

    names = tuple(
        str(name)
        for name in (getattr(cfg, "clip_names_per_clip", ()) or ())
    )
    if not names:
        failures.append(
            "clip_names_per_clip is empty (action_ball needs one ordered action per clip)"
        )
    manifest_path = str(
        getattr(cfg, "action_ball_manifest_path", "") or ""
    ).strip()
    if not manifest_path:
        failures.append("action_ball_manifest_path is empty")
    diagnostic = getattr(
        cfg, "action_ball_diagnostic_unauthorized", False
    )
    if type(diagnostic) is not bool:
        failures.append(
            "action_ball_diagnostic_unauthorized must be an exact boolean"
        )
        diagnostic = False
    for field in (
        "action_ball_manifest_sha256",
        "action_ball_policy_contract_sha256",
    ):
        digest = str(getattr(cfg, field, "") or "")
        if (
            len(digest) != 64
            or digest != digest.lower()
            or any(character not in "0123456789abcdef" for character in digest)
        ):
            failures.append(
                f"{field} must be exactly 64 lowercase hexadecimal characters"
            )
    if not diagnostic:
        evaluator_receipt_path = str(
            getattr(
                cfg,
                "action_ball_evaluator_launch_receipt_path",
                "",
            )
            or ""
        ).strip()
        if not evaluator_receipt_path:
            failures.append(
                "action_ball_evaluator_launch_receipt_path is empty"
            )
        for field in (
            "action_ball_sidecar_launch_receipt_path",
            "action_ball_drain_reset_launch_receipt_path",
        ):
            if not str(getattr(cfg, field, "") or "").strip():
                failures.append(f"{field} is empty")
        for field in (
            "action_ball_evaluator_launch_receipt_file_sha256",
            "action_ball_sidecar_launch_receipt_file_sha256",
            "action_ball_drain_reset_launch_receipt_file_sha256",
        ):
            digest = str(getattr(cfg, field, "") or "")
            if (
                len(digest) != 64
                or digest != digest.lower()
                or any(
                    character not in "0123456789abcdef"
                    for character in digest
                )
            ):
                failures.append(
                    f"{field} must be exactly 64 lowercase hexadecimal "
                    "characters"
                )
        inbox_root = str(
            getattr(cfg, "action_ball_evaluation_inbox_root", "") or ""
        ).strip()
        if not inbox_root or not Path(inbox_root).is_absolute():
            failures.append(
                "action_ball_evaluation_inbox_root must be an absolute path"
            )
        for field in (
            "action_ball_evaluation_owner_id",
            "action_ball_evaluation_run_id",
        ):
            value = str(getattr(cfg, field, "") or "").strip()
            if (
                not value
                or len(value) > 128
                or any(
                    character
                    not in (
                        "abcdefghijklmnopqrstuvwxyz"
                        "ABCDEFGHIJKLMNOPQRSTUVWXYZ"
                        "0123456789_.-"
                    )
                    for character in value
                )
            ):
                failures.append(
                    f"{field} must be a safe 1-128 character identifier"
                )
        interval = getattr(
            cfg, "action_ball_frozen_eval_interval_updates", None
        )
        if type(interval) is not int or interval < 1:
            failures.append(
                "action_ball_frozen_eval_interval_updates must be a "
                "positive plain integer"
            )
    seed = getattr(cfg, "action_ball_seed", None)
    if type(seed) is not int or not 0 <= seed < (1 << 63):
        failures.append("action_ball_seed must be a plain integer in [0, 2**63)")
    if type(
        getattr(cfg, "action_ball_initial_center_single_question", None)
    ) is not bool:
        failures.append(
            "action_ball_initial_center_single_question must be an exact boolean"
        )
    refill = getattr(cfg, "action_ball_pool_refill_rows", None)
    if type(refill) is not int or refill <= 0:
        failures.append("action_ball_pool_refill_rows must be a positive plain integer")
    for field in ("cq_n_iters", "cq_max_redraw_rounds", "vb_rollout_steps"):
        value = getattr(cfg, field, None)
        if type(value) is not int or value <= 0:
            failures.append(f"{field} must be a positive plain integer")
    for field in (
        "cq_tol_m",
        "cq_speed_budget",
        "vb_rollout_h",
        "vb_capture_radius",
    ):
        value = getattr(cfg, field, None)
        if (
            type(value) not in (int, float)
            or not math.isfinite(float(value))
            or float(value) <= 0.0
        ):
            failures.append(f"{field} must be a finite positive number")
    overdraw = getattr(cfg, "cq_overdraw", None)
    if (
        type(overdraw) not in (int, float)
        or not math.isfinite(float(overdraw))
        or float(overdraw) < 1.0
    ):
        failures.append("cq_overdraw must be a finite number >= 1")
    approach = getattr(cfg, "vb_min_approach_speed", None)
    if (
        type(approach) not in (int, float)
        or not math.isfinite(float(approach))
        or float(approach) < 0.0
    ):
        failures.append("vb_min_approach_speed must be a finite non-negative number")
    if failures:
        raise ValueError(
            "target_mode='action_ball' has an incoherent launch recipe:\n  - "
            + "\n  - ".join(failures)
        )


def _assert_action_ball_racket_site_contract(cfg, contact_geometry) -> None:
    """Bind live ActionBall FK to the reviewed exact-face geometry."""

    expected_racket_body = "pingpang_red_Link"
    expected_wrist_body = "right_wrist_yaw_Link"
    expected_offset = tuple(
        float(value) for value in contact_geometry.RACKET_SITE_OFFSET_WRIST_M
    )
    expected_quat = (1.0, 0.0, 0.0, 0.0)
    abs_tol = 1.0e-12
    failures = []

    if str(getattr(cfg, "racket_body_name", "")) != expected_racket_body:
        failures.append(
            "racket_body_name must be "
            f"{expected_racket_body!r}"
        )
    if str(getattr(cfg, "wrist_body_name", "")) != expected_wrist_body:
        failures.append(
            "wrist_body_name must be "
            f"{expected_wrist_body!r}"
        )

    def _checked_tuple(name, expected):
        raw = getattr(cfg, name, None)
        if (
            isinstance(raw, (str, bytes))
            or not isinstance(raw, Sequence)
            or len(raw) != len(expected)
        ):
            failures.append(
                f"{name} must be one length-{len(expected)} numeric sequence"
            )
            return
        try:
            actual = tuple(float(value) for value in raw)
        except (TypeError, ValueError):
            failures.append(f"{name} must contain only finite numbers")
            return
        if any(not math.isfinite(value) for value in actual):
            failures.append(f"{name} must contain only finite numbers")
            return
        if any(
            not math.isclose(
                value,
                reference,
                rel_tol=0.0,
                abs_tol=abs_tol,
            )
            for value, reference in zip(actual, expected)
        ):
            failures.append(
                f"{name}={actual!r} differs from reviewed {expected!r} "
                f"(absolute tolerance {abs_tol:.1e})"
            )

    _checked_tuple("mount_offset", expected_offset)
    _checked_tuple("mount_quat", expected_quat)

    normal_axis = getattr(cfg, "mount_normal_axis", None)
    if type(normal_axis) is not int or normal_axis != 1:
        failures.append(
            "mount_normal_axis must be plain integer 1 "
            "(official racket-local raw-A/+Y axis)"
        )
    if failures:
        raise ValueError(
            "action-ball live racket-site geometry contract mismatch:\n  - "
            + "\n  - ".join(failures)
        )


def _action_ball_canonical_sha256(value: object) -> str:
    """Hash one JSON contract with the same encoding used by the receipt modules."""

    encoded = json.dumps(
        value,
        sort_keys=True,
        separators=(",", ":"),
        ensure_ascii=True,
        allow_nan=False,
    ).encode("ascii")
    return hashlib.sha256(encoded).hexdigest()


def _action_ball_frozen_eval_receipt(
    *,
    kind: str,
    content: object,
) -> dict:
    """Create one immutable JSON receipt for the proposal-level evaluator.

    The evaluator receipts deliberately do not reuse the training
    ``ActionBirthReceipt``/``ActionBallTaskReceipt`` schema.  Training has two
    independently scheduled component strata (birth and swing); formal
    evaluation has one outer stratum and exactly one selected frontier arm.
    Sharing the old type would therefore either forge its schedule or perturb
    a second arm.
    """

    if type(kind) is not str or not kind.startswith(
        "action_ball_frozen_evaluation_"
    ):
        raise ValueError("frozen-evaluation receipt kind is invalid")
    try:
        normalized = json.loads(
            json.dumps(
                content,
                sort_keys=True,
                separators=(",", ":"),
                ensure_ascii=True,
                allow_nan=False,
            )
        )
    except (TypeError, ValueError) as error:
        raise ValueError(
            "frozen-evaluation receipt content is not finite JSON"
        ) from error
    envelope = {
        "schema_version": 1,
        "kind": kind,
        "content": normalized,
    }
    return {
        **envelope,
        "receipt_sha256": _action_ball_canonical_sha256(envelope),
    }


def _action_ball_assert_frozen_eval_receipt(
    receipt: object,
    *,
    kind: str,
    expected_content: object,
) -> str:
    """Re-bind a receipt to live proposal/task source fields.

    Re-hashing alone is insufficient because a caller could change a TTC
    tick, ball vector or teacher rate and re-hash the forged row.  This helper
    first checks the self-hash and then requires byte-equivalent canonical
    content against values rebuilt from the frozen sampler and solver result.
    """

    if not isinstance(receipt, dict) or set(receipt) != {
        "schema_version",
        "kind",
        "content",
        "receipt_sha256",
    }:
        raise ValueError("frozen-evaluation receipt has invalid keys")
    if receipt["schema_version"] != 1 or receipt["kind"] != kind:
        raise ValueError("frozen-evaluation receipt identity drifted")
    envelope = {
        "schema_version": receipt["schema_version"],
        "kind": receipt["kind"],
        "content": receipt["content"],
    }
    digest = _action_ball_canonical_sha256(envelope)
    if receipt["receipt_sha256"] != digest:
        raise ValueError("frozen-evaluation receipt self-hash failed")
    expected = _action_ball_frozen_eval_receipt(
        kind=kind,
        content=expected_content,
    )
    if receipt != expected:
        raise ValueError(
            "frozen-evaluation receipt differs from live proposal/task source"
        )
    return digest


def _action_ball_sha256_file(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as stream:
        for chunk in iter(lambda: stream.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def _action_ball_strict_json_bytes(raw: bytes, *, name: str) -> dict:
    """Decode one UTF-8 JSON object while rejecting duplicate keys at every depth."""

    def _object(pairs):
        result = {}
        for key, value in pairs:
            if key in result:
                raise ValueError(f"{name} repeats JSON key {key!r}")
            result[key] = value
        return result

    try:
        value = json.loads(
            raw.decode("utf-8"),
            object_pairs_hook=_object,
            parse_constant=lambda token: (_ for _ in ()).throw(
                ValueError(f"{name} contains non-finite JSON number {token}")
            ),
        )
    except (UnicodeDecodeError, json.JSONDecodeError) as error:
        raise ValueError(f"{name} is not strict UTF-8 JSON") from error
    if not isinstance(value, dict):
        raise ValueError(f"{name} must contain one JSON object")
    return value


def _action_ball_read_tracked_regular_file(
    *,
    repo_root: Path,
    relative_path: str,
    expected_file_sha256: str,
    name: str,
) -> tuple[Path, str, bytes]:
    """Read one non-symlink regular file under the trusted repository root."""

    if type(relative_path) is not str or not relative_path.strip():
        raise ValueError(f"{name} path must be non-empty")
    if Path(relative_path).is_absolute():
        raise ValueError(f"{name} path must be repository-relative")
    expected = str(expected_file_sha256)
    if (
        len(expected) != 64
        or expected != expected.lower()
        or any(character not in "0123456789abcdef" for character in expected)
    ):
        raise ValueError(
            f"{name} file SHA must be 64 lowercase hexadecimal characters"
        )
    root = Path(repo_root).resolve(strict=True)
    lexical = Path(
        os.path.abspath(os.fspath(root / Path(relative_path)))
    )
    try:
        normalized = lexical.relative_to(root)
    except ValueError as error:
        raise ValueError(f"{name} path escapes the trusted repository root") from error
    cursor = root
    for component in normalized.parts:
        cursor /= component
        if cursor.is_symlink():
            raise ValueError(f"{name} path traverses a symbolic link")
    resolved = lexical.resolve(strict=True)
    try:
        canonical_relative = resolved.relative_to(root).as_posix()
    except ValueError as error:
        raise ValueError(f"{name} path escapes the trusted repository root") from error
    metadata = resolved.stat()
    if not stat.S_ISREG(metadata.st_mode):
        raise ValueError(f"{name} path is not a regular file")
    raw = resolved.read_bytes()
    actual = hashlib.sha256(raw).hexdigest()
    if actual != expected:
        raise ValueError(
            f"{name} file SHA mismatch: expected={expected}, actual={actual}"
        )
    return resolved, canonical_relative, raw


def _action_ball_load_evaluator_authority(
    *,
    cfg,
    repo_root: Path,
    curriculum_contract_sha256: str,
    profile_order: Sequence,
    arm_catalog_sha256: str,
    scheduler_contract_sha256: str,
    sampler_sha256: str,
    solver_sha256: str,
) -> tuple[object, dict]:
    """Re-open and bind the exact code-trusted frozen-evaluator launch receipt."""

    from whole_body_tracking.tasks.tracking.mdp import (
        action_ball_evaluation as evaluation,
    )

    _path, relative, raw = _action_ball_read_tracked_regular_file(
        repo_root=repo_root,
        relative_path=str(
            cfg.action_ball_evaluator_launch_receipt_path
        ).strip(),
        expected_file_sha256=(
            cfg.action_ball_evaluator_launch_receipt_file_sha256
        ),
        name="action-ball evaluator launch receipt",
    )
    document = _action_ball_strict_json_bytes(
        raw, name="action-ball evaluator launch receipt"
    )
    exact_keys = {
        "schema_version",
        "kind",
        "authority_contract_sha256",
        "curriculum_contract_sha256",
        "profile_order",
        "arm_catalog_sha256",
        "scheduler_contract_sha256",
        "sampler_sha256",
        "solver_sha256",
        "policy_contract_sha256",
        "attempt_source_contract_sha256",
        "attempt_source_path",
        "attempt_source_sha256",
    }
    if set(document) != exact_keys:
        raise ValueError(
            "action-ball evaluator launch receipt must have exactly the "
            f"13 frozen keys: {sorted(exact_keys)}"
        )
    canonical_sha256 = _action_ball_canonical_sha256(document)
    authority = evaluation.FrozenEvaluatorAuthority.from_trusted_launch_receipt(
        document
    )
    authority.assert_binding(
        curriculum_contract_sha256=curriculum_contract_sha256,
        profile_order=profile_order,
        arm_catalog_sha256=arm_catalog_sha256,
        scheduler_contract_sha256=scheduler_contract_sha256,
        sampler_sha256=sampler_sha256,
        solver_sha256=solver_sha256,
        policy_contract_sha256=cfg.action_ball_policy_contract_sha256,
    )
    # The launch receipt pins an executable attempt source.  Re-open those
    # exact bytes under the same trusted repository root before authority is
    # allowed to enter curriculum state.
    _action_ball_read_tracked_regular_file(
        repo_root=repo_root,
        relative_path=document["attempt_source_path"],
        expected_file_sha256=document["attempt_source_sha256"],
        name="action-ball evaluator attempt source",
    )
    binding = authority.binding_document()
    if binding.get("launch_receipt_sha256") != canonical_sha256:
        raise RuntimeError(
            "action-ball evaluator authority binding lost its canonical launch pin"
        )
    return authority, {
        "path": relative,
        "file_sha256": hashlib.sha256(raw).hexdigest(),
        "document": document,
        "launch_receipt_canonical_sha256": canonical_sha256,
        "authority_binding": binding,
        "authority_state_owner_sha256": authority.state_owner_sha256,
    }


def _action_ball_load_frozen_evaluation_runtime(
    *,
    cfg,
    repo_root: Path,
    curriculum_contract_sha256: str,
    profile_order: Sequence,
    arm_catalog_sha256: str,
    scheduler_contract_sha256: str,
    sampler_sha256: str,
    solver_sha256: str,
) -> tuple[object, object, object, dict]:
    """Load the formal V4 authority, append-only source and trainer coordinator.

    Schema-3 authority receipts intentionally remain readable through the
    legacy helper above for historical checkpoint diagnostics, but they
    cannot enter this production runtime: only a code-pinned schema-4 launch
    whose attempt source is the append-only inbox can advance the curriculum.
    """

    from whole_body_tracking.tasks.tracking.mdp import (
        action_ball_evaluation as evaluation,
        action_ball_evaluation_inbox as inbox_protocol,
        action_ball_runtime as runtime,
    )

    _path, relative, raw = _action_ball_read_tracked_regular_file(
        repo_root=repo_root,
        relative_path=str(
            cfg.action_ball_evaluator_launch_receipt_path
        ).strip(),
        expected_file_sha256=(
            cfg.action_ball_evaluator_launch_receipt_file_sha256
        ),
        name="action-ball V4 evaluator launch receipt",
    )
    document = _action_ball_strict_json_bytes(
        raw, name="action-ball V4 evaluator launch receipt"
    )
    exact_keys = {
        "schema_version",
        "kind",
        "authority_contract_sha256",
        "curriculum_contract_sha256",
        "profile_order",
        "arm_catalog_sha256",
        "scheduler_contract_sha256",
        "sampler_sha256",
        "solver_sha256",
        "policy_contract_sha256",
        "attempt_source_contract_sha256",
        "attempt_source_path",
        "attempt_source_sha256",
        "window_contract",
    }
    if set(document) != exact_keys:
        raise ValueError(
            "formal action-ball evaluator launch must be the exact V4 "
            f"document: {sorted(exact_keys)}"
        )
    if (
        document["schema_version"] != evaluation.V4_SCHEMA_VERSION
        or document["kind"]
        != "action_ball_frozen_evaluator_v4_launch"
        or document["attempt_source_contract_sha256"]
        != inbox_protocol.FROZEN_EVALUATION_INBOX_ATTEMPT_SOURCE_CONTRACT_SHA256
        or document["attempt_source_path"]
        != inbox_protocol.FROZEN_EVALUATION_INBOX_ATTEMPT_SOURCE_PATH
    ):
        raise ValueError(
            "formal action-ball evaluator is not the V4 inbox attempt source"
        )
    _action_ball_read_tracked_regular_file(
        repo_root=repo_root,
        relative_path=document["attempt_source_path"],
        expected_file_sha256=document["attempt_source_sha256"],
        name="action-ball V4 inbox attempt source",
    )

    inbox_root = Path(
        os.path.abspath(
            os.path.expanduser(
                str(cfg.action_ball_evaluation_inbox_root).strip()
            )
        )
    )
    if not inbox_root.is_absolute():
        raise ValueError(
            "action_ball_evaluation_inbox_root must be absolute"
        )
    owner_id = str(cfg.action_ball_evaluation_owner_id).strip()
    run_id = str(cfg.action_ball_evaluation_run_id).strip()
    queue = inbox_protocol.EvaluationInbox(inbox_root)
    queue.initialize()

    sidecar_path, sidecar_relative, sidecar_raw = (
        _action_ball_read_tracked_regular_file(
            repo_root=repo_root,
            relative_path=str(
                cfg.action_ball_sidecar_launch_receipt_path
            ).strip(),
            expected_file_sha256=(
                cfg.action_ball_sidecar_launch_receipt_file_sha256
            ),
            name="action-ball sidecar launch receipt",
        )
    )
    sidecar_document = _action_ball_strict_json_bytes(
        sidecar_raw, name="action-ball sidecar launch receipt"
    )
    sidecar_content = sidecar_document.get("content")
    if not isinstance(sidecar_content, dict):
        raise ValueError(
            "action-ball sidecar launch receipt has no content mapping"
        )
    script = (
        repo_root
        / "hope_training"
        / "whole_body_tracking"
        / "scripts"
        / "action_ball_frozen_eval_sidecar.py"
    ).resolve(strict=True)
    sidecar_code_sha256 = _action_ball_sha256_file(script)
    inbox_protocol.validate_sidecar_launch_document(
        sidecar_document,
        actual_sidecar_code_sha256=sidecar_code_sha256,
        backend_contract_sha256=(
            inbox_protocol.FORMAL_ISAAC_BACKEND_CONTRACT_SHA256
        ),
        require_trust=True,
    )

    source = inbox_protocol.FrozenSidecarInboxAttemptSource(
        inbox=queue,
        owner_id=owner_id,
        run_id=run_id,
        runtime_module=runtime,
    )
    authority = evaluation.FrozenEvaluatorV4Authority.from_trusted_launch_receipt(
        document,
        attempt_source=source,
    )
    authority.assert_binding(
        curriculum_contract_sha256=curriculum_contract_sha256,
        profile_order=profile_order,
        arm_catalog_sha256=arm_catalog_sha256,
        scheduler_contract_sha256=scheduler_contract_sha256,
        sampler_sha256=sampler_sha256,
        solver_sha256=solver_sha256,
        policy_contract_sha256=cfg.action_ball_policy_contract_sha256,
    )
    coordinator = inbox_protocol.FrozenEvaluationInboxCoordinator(
        inbox=queue,
        owner_id=owner_id,
        run_id=run_id,
        sidecar_launch_sha256=sidecar_document["content_sha256"],
        consumer_code_sha256=_action_ball_sha256_file(
            Path(__file__).resolve()
        ),
        evaluator_authority=authority,
    )
    metadata = {
        "schema_version": evaluation.V4_SCHEMA_VERSION,
        "path": relative,
        "file_sha256": hashlib.sha256(raw).hexdigest(),
        "document": document,
        "launch_receipt_canonical_sha256": (
            _action_ball_canonical_sha256(document)
        ),
        "authority_binding": authority.binding_document(),
        "authority_state_owner_sha256": authority.state_owner_sha256,
        "attempt_source_state_owner_sha256": source.state_owner_sha256,
        "inbox_root": str(queue.root),
        "inbox_owner_id": owner_id,
        "inbox_run_id": run_id,
        "coordinator_state_owner_sha256": coordinator.state_owner_sha256,
        "sidecar_launch_receipt_path": sidecar_relative,
        "sidecar_launch_receipt_file_sha256": hashlib.sha256(
            sidecar_raw
        ).hexdigest(),
        "sidecar_launch_receipt_content_sha256": sidecar_document[
            "content_sha256"
        ],
        "sidecar_code_path": str(script.relative_to(repo_root)),
        "sidecar_code_sha256": sidecar_code_sha256,
    }
    del sidecar_path
    return authority, source, coordinator, metadata


