class _ActionBallDrainResetRuntimeSource:
    """Racket-owned source for one fenced global domain publication."""

    def __init__(
        self,
        owner: object,
        *,
        runtime_source_path: str,
        runtime_source_sha256: str,
    ) -> None:
        self._owner = owner
        self._runtime_source_path = runtime_source_path
        self._runtime_source_sha256 = runtime_source_sha256
        self._fence = None
        self._consumed = []
        self._global_reset_generation = 0

    def binding_document(self) -> dict:
        return {
            "runtime_source_contract_sha256": (
                _ACTION_BALL_DRAIN_RUNTIME_SOURCE_CONTRACT_SHA256
            ),
            "runtime_source_path": self._runtime_source_path,
            "runtime_source_sha256": self._runtime_source_sha256,
            "broker_contract_sha256": (
                _ACTION_BALL_DRAIN_BROKER_CONTRACT_SHA256
            ),
            "attempt_pool_contract_sha256": (
                _ACTION_BALL_DRAIN_ATTEMPT_POOL_CONTRACT_SHA256
            ),
            "task_receipt_pool_contract_sha256": (
                _ACTION_BALL_DRAIN_TASK_POOL_CONTRACT_SHA256
            ),
            "env_reset_contract_sha256": (
                _ACTION_BALL_DRAIN_ENV_RESET_CONTRACT_SHA256
            ),
        }

    def _snapshot(self) -> dict:
        getter = getattr(
            self._owner, "_action_ball_drain_runtime_snapshot", None
        )
        if not callable(getter):
            raise RuntimeError(
                "Racket command lacks drain runtime snapshot"
            )
        return getter(
            reset_generation=self._global_reset_generation + 1
        )

    def capture_drain_reset(self, request: Mapping[str, object]) -> dict:
        if self._fence is not None:
            raise RuntimeError("action-ball drain/reset fence already held")
        snapshot = self._snapshot()
        fence_id = _action_ball_canonical_sha256(
            {
                "request": dict(request),
                "snapshot": snapshot,
                "consumed_count": len(self._consumed),
            }
        )
        result = {
            "schema_version": 1,
            "kind": "action_ball_global_pre_reset_snapshot",
            "request_sha256": _action_ball_canonical_sha256(
                dict(request)
            ),
            "old_global_state_root_sha256": request[
                "old_global_state_root_sha256"
            ],
            "target_global_state_root_sha256": request[
                "target_global_state_root_sha256"
            ],
            "published_domain_set_root_sha256": request[
                "published_domain_set_root_sha256"
            ],
            "release_set_root_sha256": request[
                "release_set_root_sha256"
            ],
            "evidence_set_root_sha256": request[
                "evidence_set_root_sha256"
            ],
            "policy_checkpoint_sha256": request[
                "policy_checkpoint_sha256"
            ],
            "policy_generation": request["policy_generation"],
            **snapshot,
            "fence_id_sha256": fence_id,
        }
        if (
            result["active_attempts"] != 0
            or result["reserved_attempts"] != 0
            or result["active_births"] != 0
            or result["pending_task_receipts"] != 0
            or result["reset_count"] != result["env_count"]
            or result["reset_participant_ids"]
            != list(range(result["env_count"]))
            or len(
                {
                    result["broker_reset_generation"],
                    result["attempt_pool_reset_generation"],
                    result["task_receipt_pool_reset_generation"],
                    result["env_reset_generation"],
                }
            )
            != 1
        ):
            return result
        self._fence = {
            "fence_id_sha256": fence_id,
            "snapshot": json.loads(
                json.dumps(
                    result,
                    sort_keys=True,
                    separators=(",", ":"),
                    ensure_ascii=True,
                    allow_nan=False,
                )
            ),
        }
        setattr(self._owner, "_action_ball_drain_fence_active", True)
        return result

    def _assert_fence(self, token: Mapping[str, object]) -> dict:
        if self._fence is None:
            raise RuntimeError("action-ball drain/reset fence is absent")
        snapshot = self._snapshot()
        frozen = self._fence["snapshot"]
        if (
            token["fence_id_sha256"]
            != self._fence["fence_id_sha256"]
        ):
            raise RuntimeError("action-ball drain/reset fence changed")
        for field in (
            "broker_reset_generation",
            "attempt_pool_reset_generation",
            "task_receipt_pool_reset_generation",
            "env_reset_generation",
            "active_attempts",
            "reserved_attempts",
            "active_births",
            "pending_task_receipts",
            "reset_count",
            "env_count",
            "reset_participant_ids",
            "reset_bitmap_sha256",
            "broker_state_root_sha256",
            "attempt_pool_state_root_sha256",
            "task_receipt_pool_state_root_sha256",
            "env_reset_state_root_sha256",
        ):
            if frozen[field] != snapshot[field] or token[field] != snapshot[
                field
            ]:
                raise RuntimeError(
                    f"action-ball drain/reset {field} changed under fence"
                )
        return snapshot

    def commit_drain_reset(
        self,
        token: Mapping[str, object],
        publish_noexcept: object,
    ) -> dict:
        snapshot = self._assert_fence(token)
        if not callable(publish_noexcept):
            raise TypeError("publish_noexcept must be callable")
        publish_noexcept()
        self._global_reset_generation = snapshot[
            "env_reset_generation"
        ]
        self._consumed.append(dict(token))
        self._fence = None
        setattr(self._owner, "_action_ball_drain_fence_active", False)
        return {
            "schema_version": 1,
            "kind": "action_ball_drain_reset_commit",
            "token_sha256": token["token_sha256"],
            "fence_id_sha256": token["fence_id_sha256"],
            "published": True,
        }

    def abort_drain_reset(self, token: Mapping[str, object]) -> dict:
        self._assert_fence(token)
        self._fence = None
        setattr(self._owner, "_action_ball_drain_fence_active", False)
        return {
            "schema_version": 1,
            "kind": "action_ball_drain_reset_abort",
            "token_sha256": token["token_sha256"],
            "fence_id_sha256": token["fence_id_sha256"],
            "aborted": True,
        }

    def assert_consumed_drain_reset(
        self, ordered_token_documents: Sequence[Mapping[str, object]]
    ) -> bool:
        return list(ordered_token_documents) == self._consumed

    def state_dict(self) -> dict:
        if self._fence is not None:
            raise RuntimeError(
                "cannot checkpoint action-ball with a live drain fence"
            )
        result = {
            "schema_version": 1,
            "binding": self.binding_document(),
            "global_reset_generation": self._global_reset_generation,
            "consumed": list(self._consumed),
        }
        result["state_sha256"] = _action_ball_canonical_sha256(result)
        return result

    def load_state_dict(self, state: object) -> None:
        expected = {
            "schema_version",
            "binding",
            "global_reset_generation",
            "consumed",
            "state_sha256",
        }
        if not isinstance(state, dict) or set(state) != expected:
            raise ValueError("action-ball drain source state keys mismatch")
        unsigned = dict(state)
        digest = unsigned.pop("state_sha256")
        if (
            type(digest) is not str
            or _action_ball_canonical_sha256(unsigned) != digest
            or state["schema_version"] != 1
            or state["binding"] != self.binding_document()
            or type(state["global_reset_generation"]) is not int
            or state["global_reset_generation"] < 0
            or not isinstance(state["consumed"], list)
        ):
            raise ValueError("action-ball drain source state mismatch")
        self._global_reset_generation = state[
            "global_reset_generation"
        ]
        self._consumed = json.loads(
            json.dumps(
                state["consumed"],
                sort_keys=True,
                separators=(",", ":"),
                ensure_ascii=True,
                allow_nan=False,
            )
        )
        self._fence = None
        setattr(self._owner, "_action_ball_drain_fence_active", False)


def _action_ball_load_drain_reset_authority(
    *,
    cfg,
    repo_root: Path,
    curriculum_contract_sha256: str,
    profile_order: Sequence,
    arm_catalog_sha256: str,
    scheduler_contract_sha256: str,
    sampler_sha256: str,
    solver_sha256: str,
    runtime_owner: object,
) -> tuple[object, _ActionBallDrainResetRuntimeSource, dict]:
    from whole_body_tracking.tasks.tracking.mdp import (
        action_ball_curriculum as curriculum_module,
    )

    _path, relative, raw = _action_ball_read_tracked_regular_file(
        repo_root=repo_root,
        relative_path=str(
            cfg.action_ball_drain_reset_launch_receipt_path
        ).strip(),
        expected_file_sha256=(
            cfg.action_ball_drain_reset_launch_receipt_file_sha256
        ),
        name="action-ball drain/reset launch receipt",
    )
    document = _action_ball_strict_json_bytes(
        raw, name="action-ball drain/reset launch receipt"
    )
    source_relative = Path(__file__).resolve().relative_to(
        repo_root
    ).as_posix()
    source_sha = _action_ball_sha256_file(Path(__file__).resolve())
    source = _ActionBallDrainResetRuntimeSource(
        runtime_owner,
        runtime_source_path=source_relative,
        runtime_source_sha256=source_sha,
    )
    authority = (
        curriculum_module.DrainResetAuthority.from_trusted_launch_receipt(
            document,
            runtime_source=source,
        )
    )
    authority.assert_binding(
        curriculum_contract_sha256=curriculum_contract_sha256,
        profile_order=profile_order,
        arm_catalog_sha256=arm_catalog_sha256,
        scheduler_contract_sha256=scheduler_contract_sha256,
        sampler_sha256=sampler_sha256,
        solver_sha256=solver_sha256,
        policy_contract_sha256=cfg.action_ball_policy_contract_sha256,
    )
    return authority, source, {
        "path": relative,
        "file_sha256": hashlib.sha256(raw).hexdigest(),
        "document": document,
        "launch_receipt_canonical_sha256": (
            _action_ball_canonical_sha256(document)
        ),
        "runtime_source_binding": source.binding_document(),
        "authority_state_owner_sha256": authority.state_owner_sha256,
    }


def action_ball_physics_profile_contract(
    cfg,
    prm,
    *,
    repo_root: Path,
    surface_z: float,
    net_x: float,
    net_top_z: float,
    opponent_near_x: float,
    opponent_far_x: float,
    table_half_width: float,
) -> dict:
    """Build the versioned physics/scorer receipt from live runtime truth.

    The manifest is only allowed to *match* this receipt.  It cannot mint the receipt by declaring
    a digest of its own choosing.
    """

    source = Path(prm.source_path).expanduser().resolve(strict=True)
    root = Path(repo_root).resolve(strict=True)
    try:
        relative = source.relative_to(root).as_posix()
    except ValueError as error:
        raise ValueError(
            "action-ball venue physics source must be a regular file inside the trusted repo root"
        ) from error
    if not source.is_file():
        raise ValueError("action-ball venue physics source is not a regular file")
    payload = {
        "schema_version": _ACTION_BALL_PHYSICS_PROFILE_SCHEMA_VERSION,
        "kind": "whole_body_tracking.action_ball.physics_and_scorer",
        "venue_source": {
            "path": relative,
            "file_sha256": _action_ball_sha256_file(source),
        },
        "virtual_ball_params": {
            name: float(getattr(prm, name))
            for name in _ACTION_BALL_VIRTUAL_BALL_PARAM_NAMES
        },
        "geometry_and_grading": {
            "table_surface_z_m": float(cfg.vb_table_surface_z),
            "ball_center_surface_z_m": float(surface_z),
            "opponent_near_x_m": float(opponent_near_x),
            "net_x_m": float(net_x),
            "ball_center_net_top_z_m": float(net_top_z),
            "opponent_far_x_m": float(opponent_far_x),
            "table_half_width_m": float(table_half_width),
            "minimum_landing_depth_m": float(cfg.vb_min_landing_depth),
            "capture_radius_m": float(cfg.vb_capture_radius),
            "minimum_approach_speed_mps": float(cfg.vb_min_approach_speed),
        },
        "scorer_integrator": {
            "h_s": float(cfg.vb_rollout_h),
            "n_steps": int(cfg.vb_rollout_steps),
        },
    }
    return {
        "payload": payload,
        "sha256": _action_ball_canonical_sha256(payload),
    }


def action_ball_declared_solver_knobs(cfg) -> dict:
    """The executable solver knobs, in exactly the words the profile payload uses.

    人话:这五个数既要**写进 pin 的 payload**,也要**真的喂给求解器**。它们只在
    这里算一次:``action_ball_solver_profile_contract`` 把它写进 payload,
    ``action_ball_assert_solver_runtime_matches_declaration`` 拿它去对活值。
    期望值不允许出现第三份手抄 —— 手抄的那份迟早和代码分家,而分家的那一天
    没有任何门会响。
    """

    return {
        "n_iters": int(cfg.cq_n_iters),
        "tol_m": float(cfg.cq_tol_m),
        "global_speed_budget_mps": float(cfg.cq_speed_budget),
        "max_external_proposal_rounds": int(cfg.cq_max_redraw_rounds),
        "external_overdraw_multiplier": float(cfg.cq_overdraw),
    }


def action_ball_solver_cfg_from_declaration(cfg, continuous_question_cfg_type):
    """Build the live ``ContinuousQuestionCfg`` from the declared knobs, nothing else.

    人话:这是"把钉住的旋钮交给求解器"的**唯一一处映射**。它以前长在
    ``_initialize_action_ball_runtime`` 那 1700 多行接线里,而那个函数以
    "只是选绑哪种题源"为由被排除在语义面之外 —— 于是
    ``tol_m=float(cfg.cq_tol_m) * 0.5`` 这种改法改得动答案却动不了 pin。
    映射搬到这里、并进覆盖面,改一个字 pin 就动。
    """

    knobs = action_ball_declared_solver_knobs(cfg)
    return continuous_question_cfg_type(
        tol_m=knobs["tol_m"],
        n_iters=knobs["n_iters"],
        speed_budget=knobs["global_speed_budget_mps"],
        max_redraw_rounds=knobs["max_external_proposal_rounds"],
        fixed_direction=_ACTION_BALL_SOLVER_FIXED_DIRECTION,
    )


def action_ball_live_answer_input_digest(
    *, prototypes, reference_normal_rows
) -> dict:
    """Digest the exact answer-bearing tensors the solver is about to be handed.

    人话:这份摘要每次都**从活张量重算**。加载时算过一次的那份
    (``derived_sha256``)对 JSON 记录取,不是对活张量取,所以任何"加载之后再原地
    改一下"的写法它都看不见 —— 而 ``protos`` 和 ``ref_normal`` 都是入参,逐符号
    指纹同样看不见。

    只做一次主机传输:所有列先在设备上拼成一条 float64 向量再取回,不然一次补池就
    要多几十次 GPU 同步。float32/long/bool 转 float64 都是精确的,所以"省同步"没有
    换来"少看见一个比特"。
    """

    columns = []
    layout = []
    for name in _ACTION_BALL_ANSWER_INPUT_PROTOTYPE_COLUMNS:
        tensor = getattr(prototypes, name)
        layout.append([str(name), [int(size) for size in tensor.shape]])
        columns.append(tensor.reshape(-1).to(torch.float64))
    layout.append(
        [
            "reference_normal_raw_w_per_clip",
            [int(size) for size in reference_normal_rows.shape],
        ]
    )
    columns.append(reference_normal_rows.reshape(-1).to(torch.float64))
    values = torch.cat(columns).detach().cpu().tolist()
    payload = {
        "schema_version": _ACTION_BALL_ANSWER_INPUT_SCHEMA_VERSION,
        "kind": "whole_body_tracking.action_ball.live_answer_inputs",
        "layout": layout,
        "motion_ids": [str(value) for value in prototypes.motion_ids],
        "families": [str(value) for value in prototypes.families],
        "values": [float(value) for value in values],
    }
    return {
        "sha256": _action_ball_canonical_sha256(payload),
        "layout": layout,
        "reference_normal_row_count": int(reference_normal_rows.shape[0]),
    }


def action_ball_answer_input_contract(
    *,
    prototypes,
    reference_normal_rows,
    manifest_prototype_sha256: str,
    manifest_prototype_scope: str,
    manifest_families,
    manifest_face_signs,
    global_speed_budget_mps: float,
) -> dict:
    """Seal the solver's answer-bearing inputs, and anchor what the manifest anchors.

    人话:两件事,一件也不能少。

    1. **锚**:原型表里有几列的正确值是 manifest 说了算的(每个动作的家族、
       击球面符号、以及"这个动作还开着")。这几条检查以前长在那条被排除的接线里,
       删掉一行没人知道;现在它们在覆盖面里,删一个字 pin 就动。
       ``face_sign`` 尤其要紧 —— 把每个答案的物理拍面翻过来只要一句
       ``face_sign.neg_()``,而 manifest 里逐动作写着它应该是 +1 还是 -1。
    2. **封**:把活张量此刻的摘要连同它的出处(原型文件 SHA、JSON 记录摘要、
       scope)一起封住,交给三个入口点每次出题前重算比对。

    锚管"封之前就被改过",封管"封之后又被改过"。两者都不管的那一块 ——
    ``stroke_prototypes_torch.load_stroke_prototype_tensors`` 自己怎么把 JSON 变成
    张量 —— 不在语义面里,这是一个**具名的开口**,别当它已经关上了。
    """

    families = tuple(str(value) for value in manifest_families)
    if tuple(str(value) for value in prototypes.families) != families:
        raise ValueError(
            "action-ball prototype family order differs from manifest: "
            f"prototype={tuple(prototypes.families)!r}, manifest={families!r}"
        )
    if not bool(prototypes.enabled.all()):
        raise ValueError(
            "action-ball manifest contains a disabled solver prototype"
        )
    live_signs = tuple(
        int(round(float(value)))
        for value in prototypes.face_sign.detach().cpu().tolist()
    )
    expected_signs = tuple(int(value) for value in manifest_face_signs)
    if live_signs != expected_signs:
        raise ValueError(
            f"action-ball prototype face signs differ: prototype={live_signs}, "
            f"manifest={expected_signs}"
        )
    if bool(
        (
            prototypes.speed_min
            > float(global_speed_budget_mps) + 1.0e-9
        ).any()
    ):
        raise ValueError(
            "action-ball prototype speed_min exceeds cq_speed_budget; the global "
            "deploy speed cap leaves that action no feasible fixed-direction "
            "speed interval"
        )
    if str(prototypes.file_sha256) != str(manifest_prototype_sha256):
        raise ValueError(
            "action-ball prototype file sha256 differs from the manifest: "
            f"loaded={prototypes.file_sha256}, "
            f"manifest={manifest_prototype_sha256}"
        )
    live = action_ball_live_answer_input_digest(
        prototypes=prototypes,
        reference_normal_rows=reference_normal_rows,
    )
    payload = {
        "schema_version": _ACTION_BALL_ANSWER_INPUT_SCHEMA_VERSION,
        "kind": "whole_body_tracking.action_ball.sealed_answer_inputs",
        "prototype_file_sha256": str(manifest_prototype_sha256),
        "prototype_derived_sha256": str(prototypes.derived_sha256),
        "prototype_scope": str(manifest_prototype_scope),
        "manifest_face_signs": list(expected_signs),
        "manifest_families": list(families),
        "live_digest_sha256": str(live["sha256"]),
        "layout": live["layout"],
        "reference_normal_row_count": int(live["reference_normal_row_count"]),
    }
    return {
        "payload": payload,
        "sha256": _action_ball_canonical_sha256(payload),
    }


def action_ball_assert_solver_adapter_binds_these_entry_points(
    *, adapter, expected: dict, call_site: str, required: bool
) -> dict:
    """Refuse unless the pool is about to call exactly these bound methods.

    人话:这道断言补的是**内容指纹的固有边界**。pin 能证明"这三个函数体没变",
    证明不了"跑的就是这三个函数体"。接线在被排除的那段里把
    ``_ActionBallPoolSolverAdapter`` 的 ``solve=``/``solve_many=`` 改绑到一个
    未覆盖、不跑自检的方法,语义面指纹**纹丝不动**(那个新方法只被排除区引用,
    闭包门够不着它)。把覆盖面越扩越大解决不了这件事,所以改成**运行时自证身份**:
    覆盖面里的入口点当场问适配器一句"你手里握的是不是我",不是就拒。

    这半边管"改绑之后还假装调我";另外半边(改绑之后干脆不调我)由语义面的
    ``POOL_SOLVER_BINDINGS`` 静态门管 —— 一个没跑的函数没法自己举手。

    ``required=False`` 只用在两个也会在不可变题带 / 题库题源下跑的入口点上:
    那两种题源根本不构造这个适配器,它们的身份由自己的 tape/bank SHA 钉住。
    """

    holder = getattr(adapter, "action_ball_bound_entry_points", None)
    if holder is None:
        if required:
            raise RuntimeError(
                "action-ball pool solver cannot state which callables it holds "
                f"(checked at {call_site}); this entry point only runs on the "
                "online-solver path, where the pool solver must be the exact "
                "adapter that binds it"
            )
        return {
            "kind": (
                "whole_body_tracking.action_ball.solver_adapter_binding_check"
            ),
            "call_site": str(call_site),
            "attested": False,
            "attested_slots": [],
        }
    bound = holder()
    drift = []
    if set(bound) != set(expected):
        drift.append(
            "slot set: bound=%r expected=%r"
            % (sorted(bound), sorted(expected))
        )
    for name in sorted(expected):
        want = expected[name]
        got = bound.get(name)
        # Identity first, then "the same bound method of the same object".
        # Comparing only ``__func__``/``__self__`` would silently pass for any
        # pair of plain objects (both attributes are absent, so both read
        # ``None``), which is exactly the shape a smuggled callable has.
        same = got is want or (
            getattr(got, "__func__", None) is not None
            and getattr(got, "__func__", None)
            is getattr(want, "__func__", None)
            and getattr(got, "__self__", None)
            is getattr(want, "__self__", None)
        )
        if not same:
            drift.append(f"{name}: bound={got!r} expected={want!r}")
    if drift:
        raise RuntimeError(
            "action-ball pool solver adapter does not hold the covered entry "
            f"points (checked at {call_site}). The per-symbol pin proves these "
            "function BODIES are unchanged; it cannot prove they are what runs, "
            "because the binding lives in excluded wiring. This is that "
            "proof:\n  " + "\n  ".join(drift)
        )
    return {
        "kind": "whole_body_tracking.action_ball.solver_adapter_binding_check",
        "call_site": str(call_site),
        "attested": True,
        "attested_slots": sorted(expected),
    }


def action_ball_assert_solver_runtime_matches_declaration(
    *,
    solver_declaration: dict,
    physics_declaration: dict,
    answer_input_declaration: dict,
    expected_solver_profile_sha256: str,
    expected_prototype_file_sha256: str,
    prototypes,
    reference_normal_rows,
    solver_cfg,
    prm,
    planes,
    rollout_h,
    rollout_steps,
    overdraw=None,
    maximum_rounds=None,
    diagnostic_unauthorized: bool = False,
    call_site: str,
) -> dict:
    """Refuse unless every number the sealed profiles declare is the number the solver gets.

    人话:pin 封的是"**声明的数字**";这个函数检查"**真正喂进求解器的数字**"和
    声明一致。两者之间的传递线本身不在覆盖面里(它们住在那条 1700 多行的接线
    函数里,而把整条接线塞进覆盖面会让每次改接线都作废题库),所以静态指纹读不出
    ``fixed_direction=True -> False`` / ``tol_m * 0.5`` / ``speed_budget * 2``
    这类改动。这里逐字段比,不等就 fail-closed。

    这个函数本身**在覆盖面里**,三个入口点也在覆盖面里:删掉调用、放宽比较、
    少比一个字段,任何一种都会动 pin,manifest 立刻对不上。

    **它自己也要被验一次身份。** 以前这里只看 ``kind`` 和 ``schema_version``,
    从不重算 ``_action_ball_canonical_sha256(solver_declaration)`` 去和
    ``manifest.solver_profile_sha256`` 对。于是接线只要在铸造之后**同时**改
    payload 和活 cfg(两行),四个调用点全部放行 —— 29 个字段照过。现在两份
    payload 各自重算摘要:solver 的对 manifest(内容寻址、由 launcher 的
    ``action_ball_manifest_sha256`` 钉住),physics 的对 solver payload 里自陈的
    ``physics_profile_sha256``。改 payload 就必须连 manifest 一起伪造。

    ``protos`` 和 ``ref_normal`` 也在比对表里,而且摘要是**从活张量重算**的:
    这两个是 ``solve_proposals`` 的入参,以前两份 payload 都没声明它们、29 项
    自检也没比过它们,于是 ``speed_max.mul_(1.5)`` / ``face_sign.neg_()`` /
    一个保范数的 ``v_hat_b`` 旋转全都能静默改答案。

    ``overdraw`` / ``maximum_rounds`` 只有 ``_action_ball_refill_pool_many``
    这条路会用(另外两个入口点一次解完,不重抽),传 ``None`` 表示"本调用点不
    使用它",返回的收据里会自陈到底比了哪几个字段。

    Returns a small self-describing receipt: which call site ran the check, how
    many fields it compared, and their names.  A gate that only reports a count
    is a gate nobody can audit later.
    """

    from whole_body_tracking.tasks.tracking.mdp.continuous_questions import (
        BALL_BIRTH_NET_MARGIN_M,
        CONTACT_NORMAL_SPEED_MAX_MPS,
        CONTACT_NORMAL_SPEED_MIN_MPS,
    )

    if (
        not isinstance(solver_declaration, dict)
        or not isinstance(physics_declaration, dict)
        or not isinstance(answer_input_declaration, dict)
    ):
        raise RuntimeError(
            "action-ball solver runtime cross-check needs all three sealed "
            "payloads"
        )
    if (
        answer_input_declaration.get("kind")
        != "whole_body_tracking.action_ball.sealed_answer_inputs"
        or int(answer_input_declaration.get("schema_version", -1))
        != _ACTION_BALL_ANSWER_INPUT_SCHEMA_VERSION
    ):
        raise RuntimeError(
            "action-ball solver runtime cross-check was handed a payload that "
            "is not the schema v"
            f"{_ACTION_BALL_ANSWER_INPUT_SCHEMA_VERSION} sealed answer inputs: "
            f"kind={answer_input_declaration.get('kind')!r}, "
            f"schema_version={answer_input_declaration.get('schema_version')!r}"
        )
    if (
        solver_declaration.get("kind")
        != "whole_body_tracking.continuous_questions.solve_proposals"
        or int(solver_declaration.get("schema_version", -1))
        != _ACTION_BALL_SOLVER_PROFILE_SCHEMA_VERSION
    ):
        raise RuntimeError(
            "action-ball solver runtime cross-check was handed a payload that is "
            "not the schema v"
            f"{_ACTION_BALL_SOLVER_PROFILE_SCHEMA_VERSION} solver profile: "
            f"kind={solver_declaration.get('kind')!r}, "
            f"schema_version={solver_declaration.get('schema_version')!r}"
        )
    if (
        physics_declaration.get("kind")
        != "whole_body_tracking.action_ball.physics_and_scorer"
    ):
        raise RuntimeError(
            "action-ball solver runtime cross-check was handed a payload that is "
            "not the physics/scorer profile: "
            f"kind={physics_declaration.get('kind')!r}"
        )
    solve = solver_declaration["solve"]
    acceptance = solver_declaration["acceptance"]
    fit = acceptance["contact_normal_speed_fit"]
    geometry = physics_declaration["geometry_and_grading"]
    diagnostic = bool(diagnostic_unauthorized)
    surface_z, net_x, net_top_z = planes
    live_answer_inputs = action_ball_live_answer_input_digest(
        prototypes=prototypes,
        reference_normal_rows=reference_normal_rows,
    )
    # (name, what the sealed payload declares, what the solver is about to get)
    comparisons = [
        # The gate's own identity.  Without these two rows the whole comparison
        # is "does this payload agree with itself", which a two-line wiring edit
        # satisfies trivially.
        ("solver.payload.canonical_sha256",
         str(expected_solver_profile_sha256),
         _action_ball_canonical_sha256(solver_declaration)),
        ("physics.payload.canonical_sha256",
         str(solver_declaration["physics_profile_sha256"]),
         _action_ball_canonical_sha256(physics_declaration)),
        # The two solver arguments no payload used to declare at all.
        ("answer_inputs.prototype_file_sha256",
         str(expected_prototype_file_sha256), str(prototypes.file_sha256)),
        ("answer_inputs.sealed_prototype_file_sha256",
         str(expected_prototype_file_sha256),
         str(answer_input_declaration["prototype_file_sha256"])),
        ("answer_inputs.prototype_derived_sha256",
         str(answer_input_declaration["prototype_derived_sha256"]),
         str(prototypes.derived_sha256)),
        ("answer_inputs.live_digest_sha256",
         str(answer_input_declaration["live_digest_sha256"]),
         str(live_answer_inputs["sha256"])),
        ("answer_inputs.reference_normal_row_count",
         int(answer_input_declaration["reference_normal_row_count"]),
         int(live_answer_inputs["reference_normal_row_count"])),
        ("solver.fixed_direction", bool(solver_declaration["fixed_direction"]),
         bool(solver_cfg.fixed_direction)),
        ("solver.solve.n_iters", int(solve["n_iters"]), int(solver_cfg.n_iters)),
        ("solver.solve.tol_m", float(solve["tol_m"]), float(solver_cfg.tol_m)),
        ("solver.solve.global_speed_budget_mps",
         float(solve["global_speed_budget_mps"]), float(solver_cfg.speed_budget)),
        ("solver.solve.max_external_proposal_rounds",
         int(solve["max_external_proposal_rounds"]),
         int(solver_cfg.max_redraw_rounds)),
        ("solver.acceptance.landing.tol_m",
         float(acceptance["landing"]["tol_m"]), float(solver_cfg.tol_m)),
        ("solver.acceptance.net.ball_center_net_top_z_m",
         float(acceptance["net"]["ball_center_net_top_z_m"]), float(net_top_z)),
        ("solver.acceptance.contact_normal_speed_fit.minimum_mps_inclusive",
         float(fit["minimum_mps_inclusive"]), float(CONTACT_NORMAL_SPEED_MIN_MPS)),
        ("solver.acceptance.contact_normal_speed_fit.maximum_mps_inclusive",
         float(fit["maximum_mps_inclusive"]), float(CONTACT_NORMAL_SPEED_MAX_MPS)),
        ("solver.acceptance.incoming_birth.net_margin_m",
         float(acceptance["incoming_birth"]["net_margin_m"]),
         float(BALL_BIRTH_NET_MARGIN_M)),
        ("solver.integrator.h_s",
         float(solver_declaration["integrator"]["h_s"]), float(rollout_h)),
        ("solver.integrator.n_steps",
         int(solver_declaration["integrator"]["n_steps"]), int(rollout_steps)),
        ("physics.scorer_integrator.h_s",
         float(physics_declaration["scorer_integrator"]["h_s"]), float(rollout_h)),
        ("physics.scorer_integrator.n_steps",
         int(physics_declaration["scorer_integrator"]["n_steps"]),
         int(rollout_steps)),
        ("physics.geometry_and_grading.ball_center_surface_z_m",
         float(geometry["ball_center_surface_z_m"]), float(surface_z)),
        ("physics.geometry_and_grading.net_x_m",
         float(geometry["net_x_m"]), float(net_x)),
        ("physics.geometry_and_grading.ball_center_net_top_z_m",
         float(geometry["ball_center_net_top_z_m"]), float(net_top_z)),
    ]
    declared_params = physics_declaration["virtual_ball_params"]
    for name in _ACTION_BALL_VIRTUAL_BALL_PARAM_NAMES:
        comparisons.append(
            (
                "physics.virtual_ball_params.%s" % name,
                float(declared_params[name]),
                float(getattr(prm, name)),
            )
        )
    if overdraw is not None:
        # A diagnostic (unauthorized) run is allowed exactly one departure from
        # the declaration, and it is a named constant, not a free expression.
        comparisons.append(
            (
                "solver.solve.external_overdraw_multiplier",
                1.0 if diagnostic else float(solve["external_overdraw_multiplier"]),
                float(overdraw),
            )
        )
    if maximum_rounds is not None:
        # A diagnostic run is allowed to raise the redraw budget to the named
        # constant, so under that brand the effective bound may be either the
        # declared one or that constant -- and nothing else.  A formal run has
        # no exemption at all.
        allowed_rounds = (
            (
                int(solve["max_external_proposal_rounds"]),
                _ACTION_BALL_DIAGNOSTIC_MAX_EXTERNAL_PROPOSAL_ROUNDS,
            )
            if diagnostic
            else (int(solve["max_external_proposal_rounds"]),)
        )
        if int(maximum_rounds) in allowed_rounds:
            effective_rounds_declared = int(maximum_rounds)
        else:
            effective_rounds_declared = allowed_rounds[0]
        comparisons.append(
            (
                "solver.solve.max_external_proposal_rounds.effective",
                effective_rounds_declared,
                int(maximum_rounds),
            )
        )
    drift = [
        (name, declared, actual)
        for name, declared, actual in comparisons
        if type(declared) is not type(actual) or declared != actual
    ]
    if drift:
        raise RuntimeError(
            "action-ball solver runtime does not match the sealed profile it was "
            f"admitted under (checked at {call_site}, "
            f"diagnostic_unauthorized={diagnostic}, "
            f"{len(drift)} of {len(comparisons)} fields drifted). The pin seals "
            "the DECLARED numbers; this gate compares them to the numbers the "
            "solver is actually handed, because the wiring in between is not "
            "part of the semantic surface:\n  "
            + "\n  ".join(
                f"{name}: declared={declared!r} actual={actual!r}"
                for name, declared, actual in drift
            )
        )
    return {
        "kind": "whole_body_tracking.action_ball.solver_runtime_declaration_check",
        "call_site": str(call_site),
        "diagnostic_unauthorized": diagnostic,
        "compared_field_count": len(comparisons),
        "compared_fields": [name for name, _declared, _actual in comparisons],
    }


def action_ball_solver_profile_contract(
    cfg,
    *,
    physics_profile_sha256: str,
    semantic_surface: dict,
    source_sha256: dict,
    contact_geometry_contract: dict,
    net_top_z: float,
    counter_rally_objective_profile_sha256: str | None = None,
    counter_rally_venue_physics_sha256: str | None = None,
) -> dict:
    """Build the versioned fixed-action solver receipt from executable knobs and code.

    ``semantic_surface`` is the sealed per-symbol surface built by
    ``action_ball_solver_semantic_surface.semantic_surface_contract``.  It, not a
    whole-file digest, is what this profile binds for the five adjudicated solver
    sources plus ``strike_spec_torch.py``.

    ``source_sha256`` is still required, but only the counter-rally pair enters
    the payload from it: those two files have never had a symbol-level
    adjudication, so they stay on the coarse whole-file pin and say so under
    ``unadjudicated_whole_file_sha256``.
    """

    counter_rally = counter_rally_objective_profile_sha256 is not None
    if counter_rally != (counter_rally_venue_physics_sha256 is not None):
        raise ValueError(
            "counter-rally solver contract requires objective and venue-physics "
            "SHA together"
        )
    surface_payload = semantic_surface["payload"]
    if (
        surface_payload["kind"]
        != "whole_body_tracking.action_ball.solver_semantic_surface"
    ):
        raise ValueError(
            "action-ball solver profile requires the solver semantic surface"
        )
    unadjudicated_names = (
        ("counter_rally.py", "counter_rally_torch.py") if counter_rally else ()
    )
    # This declaration and the producer's numeric tuple are both covered by
    # the one solver semantic surface.  Active refill compares the declared
    # prefix to the live producer tuple before drawing, so an old/self-
    # consistent profile still cannot reinterpret codes 8/9.
    rejection_reasons = [
        "no_landing",
        "resid_gt_tol",
        "speed_over_cap",
        "speed_under_min",
        "dir_cone_exceeded",
        "net_not_cleared",
        "face_not_opponent_facing",
        "contact_normal_speed_out_of_fit",
        "lm_solve_info_nonzero",
        "lm_solve_nonfinite",
        "teacher_site_rate_geometry_unsolved",
        "teacher_rate_out_of_bounds",
        "pre_swing_wait_out_of_bounds",
        "cycle_exceeds_episode_horizon",
        "ball_birth_not_beyond_net",
    ]
    if counter_rally:
        from whole_body_tracking.tasks.tracking.mdp.counter_rally import (
            COUNTER_RALLY_SOLVER_REJECTION_REASON_SCHEMA,
        )

        rejection_reasons.extend(
            COUNTER_RALLY_SOLVER_REJECTION_REASON_SCHEMA
        )
    declared_knobs = action_ball_declared_solver_knobs(cfg)
    payload = {
        "schema_version": _ACTION_BALL_SOLVER_PROFILE_SCHEMA_VERSION,
        "kind": "whole_body_tracking.continuous_questions.solve_proposals",
        "semantic_surface": {
            "kind": str(surface_payload["kind"]),
            "schema_version": int(surface_payload["schema_version"]),
            "symbol_digest_algorithm": str(
                surface_payload["symbol_digest_algorithm"]
            ),
            "sha256": str(semantic_surface["sha256"]),
            "pinned_sources": [
                str(name)
                for name in surface_payload["coverage_policy"]["pinned_sources"]
            ],
            "covered_symbol_count": sum(
                len(symbols) for symbols in surface_payload["covered"].values()
            ),
        },
        "unadjudicated_whole_file_sha256": {
            name: str(source_sha256[name]) for name in unadjudicated_names
        },
        "physics_profile_sha256": str(physics_profile_sha256),
        "contact_geometry": dict(contact_geometry_contract),
        "fixed_direction": _ACTION_BALL_SOLVER_FIXED_DIRECTION,
        "batch_semantics": {
            "row_separable": True,
            "required_parity": (
                "bitwise_equal_per_row_for_full_single_permuted_and_chunked_batches"
            ),
            "resume_replay_grouping": "arbitrary_pending_receipt_batch",
        },
        "solve": dict(declared_knobs),
        "integrator": {
            "h_s": float(cfg.vb_rollout_h),
            "n_steps": int(cfg.vb_rollout_steps),
        },
        "acceptance": {
            "action_identity": "episode_frozen_action_uid_and_dense_slot",
            "direction": "exact_selected_prototype_v_hat_b_rotated_by_birth_base_quat",
            "speed": {
                "lower": "selected_prototype_speed_min_inclusive",
                "upper": (
                    "min_selected_prototype_speed_max_and_global_speed_budget_inclusive"
                ),
            },
            "face": {
                "task_output_frame": "runtime_raw_plus_y_A",
                "raw_alignment": "dot(solved_raw_A_face,reference_raw_plus_y_A)>0",
                "physical_face_mapping": (
                    "physical_B_face=solved_raw_A_face*selected_prototype_face_sign"
                ),
            },
            "position_points": {
                "solver_input_and_flight_origin": "ball_center_at_contact",
                "installed_policy_target": "official_racket_site",
                "mapping": (
                    "exact selected face centre plus ball radius under full "
                    "minimal-rotation command quaternion"
                ),
                "legacy_site_ball_colocation_allowed": False,
            },
            "velocity_points": {
                "contact_law": "selected_physical_face_center_velocity",
                "installed_policy_target": "official_racket_site_velocity",
                "mapping": (
                    "v_site=v_face_center-(rate*rotated_reference_omega)"
                    "_cross_r_face_center_from_site"
                ),
                "teacher_rate": (
                    "unique verified positive quadratic root satisfying "
                    "rate=norm(v_site)/reference_site_speed"
                ),
            },
            "contact_normal_speed_fit": {
                "definition": (
                    "-dot(v_ball_in-v_racket,selected_physical_B_face_normal)"
                ),
                # These three stay literal on purpose: the offline pinner mints
                # this payload from a git revision's source text, so a builder
                # that imported the live constants would mint a pin the pinned
                # revision does not describe.  The declaration is instead held
                # honest at runtime -- ``action_ball_assert_solver_runtime_
                # matches_declaration`` compares each of them to the live
                # constant before a question is drawn, and refuses on drift.
                "minimum_mps_inclusive": 1.4,
                "maximum_mps_inclusive": 7.2,
                "rejection_reason": "contact_normal_speed_out_of_fit",
            },
            "landing": {
                "predicate": "finite_first_descending_crossing_and_l2_error_strictly_below_tol",
                "tol_m": declared_knobs["tol_m"],
            },
            "net": {
                "predicate": "finite_positive_x_crossing_and_ball_center_z_strictly_above_top",
                "ball_center_net_top_z_m": float(net_top_z),
            },
            "incoming_birth": {
                "predicate": (
                    "contact_x_w_plus_abs_v_in_x_times_ttc_linear_lower_"
                    "bound_at_or_beyond_net_plane_plus_margin"
                ),
                # Literal for the same reason as the contact-fit bounds above,
                # and cross-checked against BALL_BIRTH_NET_MARGIN_M at runtime.
                "net_margin_m": 0.05,
                "rejection_reason": "ball_birth_not_beyond_net",
            },
            "solver_rejection_is_policy_attempt": False,
            "internal_sampling_or_redraw": False,
            "ordered_rejection_reason_schema": rejection_reasons,
        },
    }
    if counter_rally:
        payload["counter_rally"] = {
            "mode": "exact_n1_fixed_action_reverse_ray",
            "objective_profile_sha256": str(
                counter_rally_objective_profile_sha256
            ),
            "venue_physics_sha256": str(
                counter_rally_venue_physics_sha256
            ),
            "precheck_before_ordinary_solver": True,
            "selector_or_action_switching": False,
        }
    return {
        "payload": payload,
        "sha256": _action_ball_canonical_sha256(payload),
    }


def action_ball_domain_authority_contract(
    *,
    manifest_sha256: str,
    adapter_contract_sha256: str,
    action_uids: Sequence[int],
    profile_sha256: Sequence[str],
    mobility_mode: str,
    curriculum_config: dict,
    policy_contract_sha256: str,
    source_sha256: dict,
) -> dict:
    """Pin the code/config that mints one curriculum-domain claim at each true reset.

    Mutable cursors and curriculum progress intentionally do not enter this immutable receipt;
    they belong to exact-resume state.  The receipt only fixes how those states are interpreted.
    """

    payload = {
        "schema_version": _ACTION_BALL_DOMAIN_AUTHORITY_SCHEMA_VERSION,
        "kind": "whole_body_tracking.action_ball.domain_claim_authority",
        "implementation_source_sha256": {
            name: str(source_sha256[name])
            for name in (
                "hope_commands.py",
                "action_ball_curriculum.py",
                "action_ball_runtime.py",
            )
        },
        "manifest_sha256": str(manifest_sha256),
        "adapter_contract_sha256": str(adapter_contract_sha256),
        "action_uids": [int(value) for value in action_uids],
        "profile_sha256": [str(value) for value in profile_sha256],
        "mobility_mode": str(mobility_mode),
        "curriculum_config": dict(curriculum_config),
        "policy_contract_sha256": str(policy_contract_sha256),
        "schedule": {
            "claim_barrier": "true_reset_only",
            "domain_source": "frozen_ActionBallCurriculum.expected_domains",
            "selection": "per_action_round_robin",
            "training_selector": False,
            "live_rollout_updates_curriculum": False,
        },
    }
    if len(payload["action_uids"]) != len(payload["profile_sha256"]):
        raise ValueError(
            "action-ball domain authority needs one profile SHA per action UID"
        )
    return {
        "payload": payload,
        "sha256": _action_ball_canonical_sha256(payload),
    }


def _task_first_face_cone_sample(
    center: torch.Tensor,
    half_angle_rad: torch.Tensor,
    unit_draw: torch.Tensor,
) -> torch.Tensor:
    """Area-uniform samples in spherical cones around unit ``center`` vectors.

    ``unit_draw`` is supplied by the caller so the sampler consumes exactly two random values per
    task and is easy to test.  A zero cone returns the center exactly (up to the final unit
    normalization), and the auxiliary axis switches near +Z to avoid a degenerate cross product.
    """

    if center.ndim != 2 or center.shape[-1] != 3:
        raise ValueError("task-first face centers must have shape (N, 3)")
    n = int(center.shape[0])
    if half_angle_rad.shape != (n,):
        raise ValueError("task-first cone angles must have shape (N,)")
    if unit_draw.shape != (n, 2):
        raise ValueError("task-first cone draws must have shape (N, 2)")
    center_norm = torch.norm(center, dim=-1, keepdim=True)
    if bool(torch.any(center_norm <= 1.0e-8)):
        raise ValueError("task-first face centers must be non-zero")
    center_u = center / center_norm
    angle = half_angle_rad.clamp(min=0.0, max=0.5 * math.pi)
    cos_max = torch.cos(angle)
    cos_theta = 1.0 - unit_draw[:, 0] * (1.0 - cos_max)
    sin_theta = torch.sqrt((1.0 - cos_theta * cos_theta).clamp(min=0.0))
    azimuth = 2.0 * math.pi * unit_draw[:, 1]
    z_axis = torch.zeros_like(center_u)
    z_axis[:, 2] = 1.0
    x_axis = torch.zeros_like(center_u)
    x_axis[:, 0] = 1.0
    helper = torch.where((torch.abs(center_u[:, 2]) < 0.9).unsqueeze(-1), z_axis, x_axis)
    tangent_1 = torch.cross(helper, center_u, dim=-1)
    tangent_1 = tangent_1 / torch.norm(tangent_1, dim=-1, keepdim=True).clamp(min=1.0e-8)
    tangent_2 = torch.cross(center_u, tangent_1, dim=-1)
    radial = (
        torch.cos(azimuth).unsqueeze(-1) * tangent_1
        + torch.sin(azimuth).unsqueeze(-1) * tangent_2
    )
    sampled = cos_theta.unsqueeze(-1) * center_u + sin_theta.unsqueeze(-1) * radial
    return sampled / torch.norm(sampled, dim=-1, keepdim=True).clamp(min=1.0e-8)


def _task_first_station_targets(
    origins: torch.Tensor,
    reference_racket: torch.Tensor,
    reference_base_xy: torch.Tensor,
    station_shift_xy: torch.Tensor,
    delta_position: torch.Tensor,
    delta_base_xy: torch.Tensor,
) -> tuple[torch.Tensor, torch.Tensor]:
    """Apply the task-first station/root-relative translation contract."""

    racket = origins + reference_racket + delta_position
    racket[:, :2] += station_shift_xy
    base = (
        origins[:, :2]
        + reference_base_xy
        + station_shift_xy
        + delta_position[:, :2]
        + delta_base_xy
    )
    return racket, base


def _face_command_pairing(cfg: "RacketTargetCommandCfg") -> str:
    """Return a validated face-command grading convention.

    ``getattr`` preserves the historical default for small test doubles and old serialized
    configuration objects; real environments also validate the field during command construction.
    """
    pairing = str(getattr(cfg, "face_command_pairing", "shared_plus_y"))
    if pairing not in _FACE_COMMAND_PAIRINGS:
        raise ValueError(
            "face_command_pairing must be one of "
            f"{_FACE_COMMAND_PAIRINGS}, got {pairing!r}"
        )
    return pairing


_ADAPTIVE_SIGMA_SOURCE_BALL_EXACT = "ball_exact_strike"
_ADAPTIVE_SIGMA_SOURCE_STAGE1_CLIP_SITE = "stage1_clip_site_full_phase_rms"
_ADAPTIVE_SIGMA_SOURCES = (
    _ADAPTIVE_SIGMA_SOURCE_BALL_EXACT,
    _ADAPTIVE_SIGMA_SOURCE_STAGE1_CLIP_SITE,
)
_ADAPTIVE_SIGMA_SOURCE_CODES = {
    name: index for index, name in enumerate(_ADAPTIVE_SIGMA_SOURCES)
}


def _adaptive_sigma_source(cfg: "RacketTargetCommandCfg") -> str:
    """Return the explicit error-ledger authority for adaptive reward widths."""

    source = str(
        getattr(cfg, "adaptive_sigma_source", _ADAPTIVE_SIGMA_SOURCE_BALL_EXACT)
    )
    if source not in _ADAPTIVE_SIGMA_SOURCES:
        raise ValueError(
            "adaptive_sigma_source must be one of "
            f"{_ADAPTIVE_SIGMA_SOURCES}, got {source!r}"
        )
    return source


def _validate_adaptive_sigma_cfg(cfg: "RacketTargetCommandCfg") -> None:
    """adaptive sigma 的附加语义必须搭在主开关上,半配置 fail-loud。

    人话:normal 通道复用 pos/vel 的同一个控制器与更新节拍
    (sigma_update_every / exact_success_decay / sigma_ema_scale)。默认源是 exact-strike;
    Stage-1 显式换成 full-phase clip-site RMS EMA。只开 normal 不开
    adaptive_sigma 时那套驱动根本不跑——sigma 永远不更新,却看起来"配置了自适应",
    这是典型的半配置静默失效,按 fail-loud 纪律在构造期就拒绝。
    """
    source = _adaptive_sigma_source(cfg)
    if getattr(cfg, "adaptive_sigma_normal", False) and not getattr(cfg, "adaptive_sigma", False):
        raise ValueError(
            "RacketTargetCommandCfg.adaptive_sigma_normal=True requires adaptive_sigma=True: "
                "the normal channel rides the pos/vel adaptive-sigma controller and cadence; "
            "enabled alone it would silently never update. Enable adaptive_sigma or drop "
            "adaptive_sigma_normal."
        )
    if getattr(cfg, "adaptive_sigma_monotonic", False) and not getattr(cfg, "adaptive_sigma", False):
        raise ValueError(
            "RacketTargetCommandCfg.adaptive_sigma_monotonic=True requires "
            "adaptive_sigma=True: monotonic contraction only changes an active adaptive-sigma "
            "update. Enable adaptive_sigma or drop adaptive_sigma_monotonic."
        )
    if source == _ADAPTIVE_SIGMA_SOURCE_STAGE1_CLIP_SITE:
        if not getattr(cfg, "adaptive_sigma", False):
            raise ValueError(
                "adaptive_sigma_source='stage1_clip_site_full_phase_rms' requires "
                "adaptive_sigma=True"
            )
        if not getattr(cfg, "adaptive_sigma_monotonic", False):
            raise ValueError(
                "adaptive_sigma_source='stage1_clip_site_full_phase_rms' requires "
                "adaptive_sigma_monotonic=True: Stage-1 may contract but never reopen its "
                "clip-site kernels"
            )
        if not getattr(cfg, "adaptive_sigma_normal", False):
            raise ValueError(
                "adaptive_sigma_source='stage1_clip_site_full_phase_rms' requires "
                "adaptive_sigma_normal=True: position, velocity, and signed face normal "
                "are one atomic Stage-1 controller"
            )


def _coupled_transport_mode(cfg: "RacketTargetCommandCfg") -> bool:
    """判定并校验"耦合传输"模式:planner 修订 + 目标延迟合并成一条 mocap→中继延迟流.

    人话:planner_revision_enabled 且 target_delay_steps=d>0 时,不再走旧的
    "只延迟 actor 观测"的 NO-LAUNCH 死路,而是把每步生成的修订元组(pos/vel/normal/tts,
    原子)压进在途环,d 步后才提交给相位调度器——接受记账、调度器看到的 desired_tts、
    actor 可见元组从此消费同一条延迟流(真实 mocap→relay 的语义)。

    fail-loud 的半配置组合:
    * ``target_delay_tts_mode='live'``——耦合传输里 tts 必须随元组一起延迟
      (调度器消费的就是元组里的 desired_tts),"元组晚到、时钟即时"是矛盾的传输语义;
      要么 source_timestamp_compensated(提交时按在途时长补偿,actor 时钟连续),
      要么 uncompensated(显式陈旧 tts 阴性对照)。
    d=0 时返回 False:一切走现役路径,逐字节不变。
    """
    coupled = bool(getattr(cfg, "planner_revision_enabled", False)) and (
        max(int(getattr(cfg, "target_delay_steps", 0)), 0) > 0
    )
    if coupled and _target_delay_tts_mode(cfg) == "live":
        raise ValueError(
            "planner revisions with target_delay_steps > 0 form ONE coupled transport tuple; "
            "target_delay_tts_mode='live' would deliver the tuple late but the clock instantly "
            "— incoherent. Use 'source_timestamp_compensated' (age-compensated at submission, "
            "continuous actor clock) or 'uncompensated' (explicit stale-TTS negative control)."
        )
    return coupled


def _target_delay_tts_mode(cfg: "RacketTargetCommandCfg") -> str:
    """Return the actor-visible time-to-strike delay convention.

    ``live`` is the historical behavior.  The other two modes put TTS in the same delayed planner
    tuple as position/velocity/normal/side; ``source_timestamp_compensated`` then advances the
    source value by the known transport age while ``uncompensated`` is the explicit stale-TTS
    negative control.
    """
    mode = str(getattr(cfg, "target_delay_tts_mode", "live"))
    if mode not in _TARGET_DELAY_TTS_MODES:
        raise ValueError(
            "target_delay_tts_mode must be one of "
            f"{_TARGET_DELAY_TTS_MODES}, got {mode!r}"
        )
    return mode


def face_tracking_pair(command: "RacketTargetCommand") -> tuple[torch.Tensor, torch.Tensor]:
    """Return the measured/target normals used by every face reward and success metric.

    Face-command targets always remain in the bank's A frame. ``shared_plus_y`` compares them to
    raw mount +Y, while the explicit diagnostic ``legacy_signed_vs_A`` reproduces the historical
    signed-measurement/A-target mismatch. Non-face tasks retain the signed clip-reference pair.
    Keeping the selection here makes rewards, privileged observations, and metrics grade the same
    convention.
    """
    if command.cfg.face_command:
        pairing = _face_command_pairing(command.cfg)
        if pairing == "shared_plus_y":
            return command.racket_normal_raw_w, command.target_normal_cmd
        return command.racket_normal_w, command.target_normal_cmd
    return command.racket_normal_w, command.racket_target_normal_w


def _peek_question_bank_clip_order(path) -> tuple:
    """Read a bank npz's own ``clip_order`` without loading it. () when it carries none (legacy).

    人话:题库自己知道它是按哪几个 clip 生成的。以前加载器把 clip 名默认写死成
    ("forehand","backhand"),于是任何别的动作集生成的题库**结构上就装不进来**,唯一的绕法是把
    一个反手 clip 改名叫 "forehand" —— 那会对下游每一个按家族分桶的消费者撒谎。所以这里先问题库。
    """
    try:
        import numpy as _np
        data = _np.load(str(path))
        if "meta_json" not in data:
            return ()
        meta = json.loads(bytes(_np.asarray(data["meta_json"], dtype=_np.uint8)).decode("utf-8"))
        return tuple(str(c) for c in (meta.get("clip_order") or ()))
    except Exception:
        return ()


#: Knobs that STOP DOING ANYTHING once a bank / inline solve produces the target. A run that sets
#: them looks like it is shaping the task while it is not, so setting one is a construction error.
#: NOTE ``racket_pos_range_per_clip`` is deliberately NOT here: under a solved target it is the
#: CONTINUOUS distribution the contact point (= the ball's arrival point) is drawn from, which is
#: still very much alive. Only the VELOCITY box dies, because the velocity is solved.
_DEAD_UNDER_SOLVED_TARGET = (
    ("racket_vel_range_per_clip", None, "the commanded velocity is SOLVED, not a box sample"),
    ("ref_vel_scale", 1.0, "the commanded velocity no longer comes from the reference clip"),
)
#: The reference-perturbation curriculum only has an effect in ``target_mode='reference_perturbed'``
#: — its cfg defaults are non-zero, so flagging it unconditionally would fire on every legal run.
_DEAD_UNDER_SOLVED_TARGET_IF_PERTURB_MODE = (
    ("ref_perturb_pos", (0.0, 0.0, 0.0)),
    ("ref_perturb_vel", (0.0, 0.0, 0.0)),
    ("ref_perturb_normal", 0.0),
    ("ref_perturb_curriculum_steps", 0),
)


def _assert_solved_target_recipe_is_coherent(cfg) -> None:
    """Every 'must be turned on' item in the launch recipe, as a fail-closed check.

    人话:一份必须靠人记住的发射清单本身就是缺陷。这里把清单里每一条变成"错组合当场炸,并且报错
    里直接写该设成什么"——以后哪次会话什么都没读,也照样不可能配错。
    """
    solved = bool(str(getattr(cfg, "question_bank", "") or "").strip()) or \
        str(getattr(cfg, "target_mode", "")) == "solved"
    if not solved:
        return

    # 1. FACE. Without face_command the inverse-solved face is computed, stored — and graded
    #    against by nothing, which is exactly how a system ends up lofting the ball upward
    #    instead of returning it flat while the landing reward notices nothing.
    if not bool(getattr(cfg, "face_command", False)):
        raise ValueError(
            "a solved/banked target computes a demanded racket FACE, but "
            "racket_target.face_command=False means nothing ever grades it — the face becomes a "
            "stored number with no consumer. Set racket.face_command: true (and, if you are "
            "adding the actor lane, racket.face_command_obs: true BEFORE any other observation "
            "term is attached — attaching it afterwards raises an override error that names the "
            "wrong term)."
        )
    pairing = str(getattr(cfg, "face_command_pairing", "shared_plus_y"))
    if pairing not in ("shared_plus_y", "legacy_signed_vs_A"):
        raise ValueError(
            f"racket_target.face_command_pairing={pairing!r} is not a known pairing; use "
            f"'shared_plus_y' (the A-frame convention every bank is generated in)"
        )

    # 2. FACE SIGN. A wrong sign silently inverts which PHYSICAL face is judged to strike.
    signs = tuple(getattr(cfg, "mount_normal_sign_per_clip", ()) or ())
    if not signs:
        raise ValueError(
            "a solved/banked target grades a signed physical face, so "
            "racket_target.mount_normal_sign_per_clip must be declared per clip (one +1/-1 per "
            "loaded clip, in motion_file order). It is absent, so every clip would fall back to "
            f"the scalar mount_normal_sign={getattr(cfg, 'mount_normal_sign', None)} — and a wrong "
            "sign silently inverts which physical rubber face is judged to strike."
        )
    bad = [(i, float(s)) for i, s in enumerate(signs) if float(s) not in (1.0, -1.0)]
    if bad:
        raise ValueError(
            f"racket_target.mount_normal_sign_per_clip entries must be +1 or -1, got {bad} as "
            f"(clip index, value)"
        )

    # 3. DEAD KNOBS. Setting one looks like shaping the task; it is not.
    checks = list(_DEAD_UNDER_SOLVED_TARGET)
    if str(getattr(cfg, "target_mode", "")) == "reference_perturbed":
        checks += [(n, v, "the reference-perturbation curriculum no longer shapes the target")
                   for n, v in _DEAD_UNDER_SOLVED_TARGET_IF_PERTURB_MODE]
    offenders = []
    for name, inert, why in checks:
        if not hasattr(cfg, name):
            continue
        value = getattr(cfg, name)
        if inert is None:
            live = value is not None
        elif isinstance(inert, tuple):
            live = tuple(float(v) for v in (value or inert)) != inert
        else:
            live = float(value) != float(inert)
        if live:
            offenders.append(f"{name}={value!r} ({why}; set it to {inert!r})")
    if offenders:
        raise ValueError(
            "these racket_target knobs are DEAD once a bank / inline solve produces the target, "
            "but this run sets them, so the yaml reads as if they were shaping the task:\n  - "
            + "\n  - ".join(offenders)
            + "\nRemove them (or set the inert value shown) so the config says what it does."
        )

    # 4. HER replay. The solved/banked override runs AFTER the HER block in _sample_targets_uniform,
    #    so every replayed target is clobbered — burned RNG and compute plus a lying
    #    achieved_replay_frac (the DeployParity yaml defaults the mix to 0.30).
    if float(getattr(cfg, "achieved_target_mix_prob", 0.0)) > 0.0:
        raise ValueError(
            f"racket_target.achieved_target_mix_prob={cfg.achieved_target_mix_prob} is "
            f"incompatible with a solved/banked target: the override runs AFTER the HER block in "
            f"_sample_targets_uniform, so every replayed target is clobbered. Set "
            f"racket.achieved_target_mix_prob: 0.0 in the task yaml."
        )
    if float(getattr(cfg, "midswing_resample_prob", 0.0)) > 0.0:
        raise ValueError(
            f"racket_target.midswing_resample_prob={cfg.midswing_resample_prob} is incompatible "
            f"with a solved/banked target: the mid-swing refinement path re-enters the samplers "
            f"(and therefore the solve seam) but never calls the shadow/physical ball's "
            f"on_resample, so the question would be swapped while the ball is still flying to the "
            f"old one. Set racket.midswing_resample_prob: 0.0."
        )

    # 5. CONTINUOUS-ONLY items. target_mode='solved' means the answer is produced INLINE from a
    #    continuous draw. 人话:开关只有这一个,剩下的必须自洽,否则当场炸并写清该设成什么。
    if str(getattr(cfg, "target_mode", "")) != "solved":
        return
    if str(getattr(cfg, "question_bank", "") or "").strip():
        raise ValueError(
            "racket_target.target_mode='solved' produces the target from a CONTINUOUS draw, but "
            "racket_target.question_bank is also set. Two producers cannot both own the atomic "
            "question/ball write. Pick one: drop question_bank (continuous training), or use "
            "target_mode 'uniform'/'reference_perturbed' with the bank. To keep a bank as the "
            "CONTRACT ANCHOR of a continuous run (validated, never trained on) put its path in "
            "racket.cq_anchor_bank instead."
        )
    if getattr(cfg, "cq_vel_range_per_clip", None) is None:
        raise ValueError(
            "racket_target.target_mode='solved' needs racket.cq_vel_range_per_clip — the "
            "INCOMING BALL's velocity box, one (x,y,z) lo/hi triple per loaded clip. That box IS "
            "the run's declared distribution; there is no shared fallback on purpose (a silent "
            "default would make every arm's task different from what its yaml says)."
        )
    if getattr(cfg, "racket_pos_range_per_clip", None) is None:
        raise ValueError(
            "racket_target.target_mode='solved' needs racket.racket_pos_range_per_clip — under a "
            "solved target it is the CONTACT-POINT DRAW BOX (the ball's arrival point), and its "
            "per-clip centre is also the pinned S2a base ready-anchor. It is not dead here; it is "
            "the only thing that says where the ball arrives."
        )
    # 5b. INCOMING BOX SANITY. vb_vel_range_per_clip 有 _assert_incoming_ball_boxes_are_sane 把关,
    #     但连续路径下那个框是死的、真正出球的是 cq_vel_range_per_clip —— 于是"球朝反方向飞"这个
    #     构造期错误在连续臂上完全没人看。同一套规则原样搬过来:-x 才是冲着机器人来。
    for clip_id, clip_rng in enumerate(tuple(cfg.cq_vel_range_per_clip)):
        (x_lo, x_hi), (y_lo, y_hi), (z_lo, z_hi) = clip_rng
        if float(x_hi) >= 0.0:
            raise ValueError(
                f"racket_target.cq_vel_range_per_clip: clip {clip_id} has x_hi={float(x_hi):.4f} "
                f">= 0, but the incoming ball travels toward the robot (-x). A non-negative "
                f"ceiling lets the draw launch a ball that flies AWAY, which no stroke can ever "
                f"answer — the solver would just reject them and the accept rate would crater."
            )
        for name, (lo, hi) in (("x", (x_lo, x_hi)), ("y", (y_lo, y_hi)), ("z", (z_lo, z_hi))):
            if float(lo) > float(hi):
                raise ValueError(
                    f"racket_target.cq_vel_range_per_clip: clip {clip_id} axis {name} has "
                    f"lo={float(lo):.4f} > hi={float(hi):.4f} — an empty box"
                )

    aim = getattr(cfg, "cq_aim_xy", None)
    if aim is not None and len(tuple(aim)) != 2:
        raise ValueError(
            f"racket_target.cq_aim_xy must be ONE (x, y) point, got {aim!r}. A per-env aim range "
            f"is refused on purpose: hope_rewards.virtual_landing, virtual_land_err_m and the "
            f"physical ball's return-flight target all grade against the single fixed "
            f"vb_target_x/vb_target_y, so a varying aim would solve for A and score at B with "
            f"nothing asserting. Make _vb_target_xy per-env first, then open this."
        )
    # 瞄点必须就是被打分的那个点。人话:解题时瞄 A、打分时按 B 量,中间只有 10 cm 的闭环回读兜底,
    # 偏 9 cm 也照训不误 —— 那正是"解出来的目标最后被别的东西打分"。所以直接钉死相等。
    if aim is not None:
        graded = (float(cfg.vb_target_x), float(cfg.vb_target_y))
        if tuple(float(v) for v in aim) != graded:
            raise ValueError(
                f"racket_target.cq_aim_xy={tuple(float(v) for v in aim)!r} is not the point this "
                f"run is GRADED at, vb_target_x/vb_target_y={graded!r}. The landing reward, "
                f"virtual_land_err_m and the physical ball's return flight all read vb_target_*, "
                f"so the solver would answer one question and the reward would mark a different "
                f"one. Either drop cq_aim_xy (it defaults to vb_target_*) or move vb_target_*."
            )
    # 契约锚题库:连续臂没有 npz 行可扫,于是 load_question_bank 的物理契约 SHA 和
    # _check_question_bank_face_frame 里的 validate_runtime_motion_contract 两道开机对账全都不跑。
    # 这正是老板说的"必须开的东西要变成默认"——所以它是必填项,不是可选项,不是一行 WARN。
    if not str(getattr(cfg, "cq_anchor_bank", "") or "").strip():
        raise ValueError(
            "racket_target.target_mode='solved' requires racket.cq_anchor_bank — a schema-v3 npz "
            "used ONLY as the contract anchor (never trained on, never installed as a target). "
            "Without it a continuous arm boots with NO physics-contract SHA check, NO runtime "
            "motion contract (motion SHA / seg_len / strike_phase) and NO on-machine "
            "continuous-vs-bank parity gate — the three checks every bank arm gets for free. Set "
            "racket.cq_anchor_bank: cfg/<your clip>_train.npz."
        )
    if float(getattr(cfg, "cq_overdraw", 1.0)) < 1.0:
        raise ValueError("racket_target.cq_overdraw must be >= 1.0 (it is a first-pass margin)")
    if int(getattr(cfg, "cq_buffer_rows", 0)) <= 0:
        raise ValueError("racket_target.cq_buffer_rows must be > 0")


class RacketTargetCommand(CommandTerm):
    """Samples desired racket/base targets and computes the actual racket state by FK."""

    cfg: RacketTargetCommandCfg

    # 类级默认 = 连续题目关。人话:仓库里有一批源码级/纯张量单测用 __new__ 造对象、只塞它们关心
    # 的那几个字段(以前的判据 _question_bank 就是这么塞的),不走 __init__。判据换成 _cq_enabled
    # 之后,那些测试会在读属性时直接 AttributeError —— 门不是失效,是炸掉,而炸掉的门等于没门。
    # 放一个类级 False 兜底,任何没经过 __init__ 的实例都读到"关",默认安全,且以后新增读点不必
    # 逐个记得写 getattr。
    _cq_enabled: bool = False
    # Counter-rally is installed only by the ActionBall runtime loader.  The
    # shared virtual-ball evaluator also serves reference/scene diagnostics,
    # so its disabled default must exist even when no ActionBall manifest was
    # loaded.
    _counter_rally_enabled: bool = False

    def __init__(self, cfg: RacketTargetCommandCfg, env: ManagerBasedRLEnv):
        # Validate even when face_command is currently disabled: a typo must fail at environment
        # construction instead of lying dormant until a later curriculum/override enables it.
        _face_command_pairing(cfg)
        _target_delay_tts_mode(cfg)
        _validate_adaptive_sigma_cfg(cfg)
        _assert_task_first_recipe_is_coherent(cfg)
        _assert_action_ball_recipe_is_coherent(cfg)
        super().__init__(cfg, env)
        _bind_disabled_time_resampling_fast_path(self)

        self.robot: Articulation = env.scene[cfg.asset_name]
        target_mode = str(getattr(cfg, "target_mode", ""))
        self._task_first_enabled = target_mode == "task_first"
        # The fresh full-MDP command is intentionally not an alias for the
        # legacy host/portable ActionBall producer.  It reuses only the
        # fixed-shape command tensors allocated by this CommandTerm; its
        # question, reset, reveal, drain and checkpoint authorities are the
        # construction-bound Device-R05 graph below.
        self._action_ball_enabled = target_mode == "action_ball"
        self._action_ball_full_mdp_enabled = (
            target_mode == "action_ball_full_mdp"
        )
        configured_strike_fact_device = bool(
            getattr(cfg, "action_ball_strike_fact_device_enabled", False)
        )
        # Fresh full-MDP R03 is a construction-owned child of this exact
        # Racket command.  It is not an optional YAML feature and it must not
        # be replaced by a second coordinator assembled by the runtime
        # factory.  The legacy ActionBall path retains its explicit flag.
        self._action_ball_strike_fact_device_enabled = (
            configured_strike_fact_device
            or self._action_ball_full_mdp_enabled
        )
        if (
            self._action_ball_strike_fact_device_enabled
            and not (
                self._action_ball_enabled
                or self._action_ball_full_mdp_enabled
            )
        ):
            raise ValueError(
                "action_ball_strike_fact_device_enabled is ActionBall-only"
            )
        if getattr(self, "_action_ball_full_mdp_enabled", False) is True:
            # These compatibility attributes are read by common reward/obs
            # code, but they carry no sampler authority in the fresh mode.
            self._action_ball_target_source = "device_r05"
            self._action_ball_target_recipe = "device_r05_selected_slice"
            self._action_ball_target_validity_mask = (True, True, True)
            self._action_ball_target_observation_noise = False
            self._action_ball_reuse_exact_question = False
        else:
            (
                self._action_ball_target_source,
                self._action_ball_target_recipe,
                self._action_ball_target_validity_mask,
                self._action_ball_target_observation_noise,
            ) = _action_ball_target_recipe_contract(cfg)
            self._action_ball_reuse_exact_question = (
                _action_ball_question_reuse_contract(
                    cfg,
                    source=self._action_ball_target_source,
                )
            )
        if not (
            self._action_ball_enabled
            or self._action_ball_full_mdp_enabled
        ) and (
            self._action_ball_target_source != "online_solver"
            or self._action_ball_target_recipe != "current_lm"
            or self._action_ball_target_validity_mask != (True, True, True)
            or not self._action_ball_target_observation_noise
            or self._action_ball_reuse_exact_question
        ):
            raise ValueError(
                "action_ball_target_* ablation fields may only be changed when "
                "target_mode='action_ball'"
            )

        # Resolve the racket FK source: prefer the racket body if it survived the physics import,
        # otherwise fall back to (wrist body pose) * (constant mount offset).
        # NOTE: Articulation.find_bodies() RAISES (resolve_matching_names) when a name matches no
        # body — it does not return []. So gate on body_names membership before calling it, or the
        # wrist-offset fallback below becomes unreachable.
        if cfg.racket_body_name in self.robot.body_names:
            self._racket_mode = "body"
            self._racket_body_index = self.robot.find_bodies(cfg.racket_body_name, preserve_order=True)[0][0]
            self._wrist_body_index = -1
        else:
            self._racket_mode = "wrist_offset"
            self._racket_body_index = -1
            if cfg.wrist_body_name not in self.robot.body_names:
                raise ValueError(
                    f"RacketTargetCommand: neither racket body '{cfg.racket_body_name}' nor wrist "
                    f"body '{cfg.wrist_body_name}' found on asset '{cfg.asset_name}'."
                )
            self._wrist_body_index = self.robot.find_bodies(cfg.wrist_body_name, preserve_order=True)[0][0]

        self._mount_offset = torch.tensor(cfg.mount_offset, dtype=torch.float32, device=self.device).repeat(
            self.num_envs, 1
        )
        # Fixed wrist->racket rotation (used only in wrist_offset fallback mode so the face normal is
        # taken in the racket frame, not the bare wrist frame). Identity for the A3 mount (all mount
        # joints are rpy=0); set non-identity if your mount tilts the paddle relative to the wrist.
        self._mount_quat = torch.tensor(cfg.mount_quat, dtype=torch.float32, device=self.device).repeat(
            self.num_envs, 1
        )

        # The motion command (resolved lazily on first update; not guaranteed to exist at __init__).
        self._motion_term: MotionCommand | None = None
        self._event_timing_bound = False
        # Per-env motion phase at the last target resample; used to detect clip wraps (new swings).
        # Stamped on every resample so a reset-time resample is not double-triggered next step.
        self._prev_motion_steps = torch.zeros(self.num_envs, dtype=torch.long, device=self.device)

        # Desired (sampled) targets, world frame.
        self.racket_target_pos_w = torch.zeros(self.num_envs, 3, device=self.device)
        self.racket_target_vel_w = torch.zeros(self.num_envs, 3, device=self.device)
        self.racket_target_normal_w = torch.zeros(self.num_envs, 3, device=self.device)
        self.racket_target_normal_w[:, 2] = 1.0
        self.base_target_pos_w = torch.zeros(self.num_envs, 2, device=self.device)
        # R10c 站位锚(franco 2026-07-09 拍板"planner 的 p_base 应该加进去:就算不需要移动,
        # 它也是一个锚")——世界系常数锚点 = env origin + cfg.station_anchor_offset_xy。
        # 固定点阶段 clip 已重落地(frame-0 root xy ≈ origin),所以这就是"出生点常数"。
        # 纯观测用(station_obs 旗标,读 station_anchor_err_b),不进任何奖励;和 base_target_pos_w
        # (带耦合+抖动的奖励目标)是两回事,别混。躯干漂移时这 2 维误差自己变大 = 策略始终有
        # 世界系位置基准(R9a 删缰绳后拍随躯干漂移挥空的任务通道解法)。
        self.station_anchor_pos_w = torch.zeros(self.num_envs, 2, device=self.device)
        self.swing_sign = torch.ones(self.num_envs, device=self.device)

        # --- Stage-1 question bank (fixed contact point / inverse-solved face+velocity answers) ----
        # cfg.question_bank non-empty -> per-swing targets are OVERRIDDEN by a bank row (see
        # _apply_question_bank_targets); empty (default) -> the sampling paths below are untouched.
        # target_normal_cmd ALWAYS exists (zeros when off) so the face-command obs/reward reads are
        # unconditionally safe; it is only ever written when the bank is active.
        self.target_normal_cmd = torch.zeros(self.num_envs, 3, device=self.device)
        self._question_bank = None
        # --- CONTINUOUS producer (target_mode: "solved") -------------------------------------
        # 人话:这不是题库。这是一个生产者-消费者缓冲——一次批量解一大批题,游标**不放回**地发,
        # 每道题只发一次、发完就丢,发空了再解一批。统计上和"每次 reset 现场解一次"完全等价,
        # 没有任何一道题被重放;之所以批量,是因为求解成本按调用计(48 行要花 8192 行的 63%),
        # 所以正确的省法是让调用变稀,不是让调用变小。
        # 谁要是把它改成有放回抽取,它就退化成一张 8192 行的滚动题库 —— 也就是 owner 明确否掉的
        # 那个东西 —— 而且没有任何断言会响。别改。
        self._cq_enabled = str(getattr(cfg, "target_mode", "")) == "solved"
        self._cq = None                 # 缓冲状态(懒建:参考拍面/venue 参数在 __init__ 还不存在)
        self._cq_cfg = None
        self._cq_gen = None
        self._cq_anchor = None
        self._cq_boot_gate_done = False
        self._cq_last_exhausted_frac = 0.0
        # clip→题库族查表缓存((nseg,) long;forehand 族=0/backhand 族=1)。只有配了
        # cfg.motion.clip_family_per_clip(6-clip 变速列表)才会建;缺席 = None = 现役行为
        # 逐字节不变(clip_id 直接当题库下标)。见 _qb_bank_family_table。
        self._qb_family_table = None
        # face_command without a bank would leave target_normal_cmd all-zero: the re-anchored
        # racket_normal reward reads cos = <n_fk, 0> = 0 -> a CONSTANT kernel, i.e. the face reward
        # silently dead while looking configured. Loud error instead.
        # The predicate is "will target_normal_cmd actually be WRITTEN", not "is there an npz
        # path". Those two used to be the same sentence, and the difference deadlocked the
        # continuous path: this guard demanded a bank for face_command, while
        # _assert_solved_target_recipe_is_coherent demanded face_command for a solved target, so
        # target_mode='solved' with no npz was structurally unlaunchable.
        if cfg.face_command and not (
            cfg.question_bank
            or self._cq_enabled
            or self._task_first_enabled
            or self._action_ball_enabled
            or self._action_ball_full_mdp_enabled
        ):
            raise ValueError(
                "RacketTargetCommandCfg.face_command=True requires a producer that WRITES "
                "target_normal_cmd — question_bank (npz path), target_mode='solved' (continuous "
                "inline solve), target_mode='task_first', or target_mode='action_ball'. Without "
                "one, target_normal_cmd stays zeros and the re-anchored racket_normal reward is "
                "silently dead."
            )
        # (The continuous producer cannot collide with hitter_pure: both live in target_mode, so
        # 'solved' and 'hitter_pure' are mutually exclusive by construction. The seam is also not
        # called from _sample_targets_hitter_pure, which is why the bank is refused here.)
        if cfg.question_bank and cfg.target_mode == "hitter_pure":
            raise ValueError(
                "RacketTargetCommandCfg.question_bank is incompatible with "
                "target_mode='hitter_pure': HitterPure samples a station-relative target, while "
                "the Stage-1 bank defines a fixed contact point and an atomic incoming-ball/answer "
                "row. Use target_mode='uniform' or 'reference_perturbed' for the bank."
            )
        if (cfg.question_bank or self._cq_enabled) and float(cfg.midswing_resample_prob) > 0.0:
            raise ValueError(
                "a solved/banked racket target (question_bank, or target_mode='solved') is "
                "incompatible with midswing_resample_prob>0: a redraw would replace the "
                "incoming-ball/answer pair without rescheduling the physical/shadow ball (the "
                "on_resample hooks only exist in _resample_command). Disable mid-swing redraws."
            )
        # GATE: every "you must remember to set this" item in the launch recipe.
        # 人话:靠人记住的清单迟早会漏。凡是"必须打开才对"的开关,要么变成默认值,要么把错误的
        # 组合当场拒掉并把该设什么写进报错里。下面这一坨就是把整张清单变成后者。
        _assert_solved_target_recipe_is_coherent(cfg)
        # GATE: landing/net rewards with NO solved answer behind the command.
        # 人话:虚拟球的 landing/pass_net 奖励只有在"命令的速度确实能把球送上台"时才和回球率同向。
        # 命令速度来自 uniform 球箱、又没有题库(逆解答案)时,两者是反的——实测 88% 的成功反手
        # 击球没通过速度阈值,因为它们靠"违抗命令速度"才把球打回去。这不是超参,是任务构造错误,
        # 所以当场拒绝,除非显式 allow_unbanked_landing_rewards=True(做对照臂时用)。
        # 判据是"命令的速度是不是被逆解出来的",不是"有没有 npz 路径"。连续臂天然满足,所以它
        # 不必征用 allow_unbanked_landing_rewards —— 那个旗标保住它原本"负对照臂"的含义。
        if (
            bool(cfg.virtual_ball)
            and not str(cfg.question_bank or "").strip()
            and not self._cq_enabled
            and not (
                self._action_ball_enabled
                or self._action_ball_full_mdp_enabled
            )
            and not bool(getattr(cfg, "allow_unbanked_landing_rewards", False))
        ):
            raise ValueError(
                "racket_target.virtual_ball=True pays the landing/net reward terms "
                "(hope_rewards.virtual_landing / virtual_pass_net) but no question_bank is "
                "loaded, so the COMMANDED racket velocity is a uniform box sample that was never "
                "solved to land the ball. That construction makes obeying the velocity command "
                "anti-correlated with returning the ball. Load a question bank, or set "
                "racket_target.target_mode: solved (continuous inline solve), or set "
                "racket_target.allow_unbanked_landing_rewards=True to run it deliberately as a "
                "control arm."
            )
        if cfg.question_bank:
            # CLIP NAMES COME FROM THE BANK. The loader defaults clip_names to exactly
            # ("forehand","backhand"), which makes a bank built over any other clip set
            # STRUCTURALLY UNLOADABLE — and the only "workaround" is renaming a backhand clip to
            # "forehand", which then lies to every family-scoped consumer downstream. So: read the
            # bank's own clip_order, cross-check it against racket_target.clip_names_per_clip when
            # that is declared, and index the per-clip name map from it.
            _bank_order = _peek_question_bank_clip_order(cfg.question_bank)
            _declared = tuple(str(n) for n in (getattr(cfg, "clip_names_per_clip", ()) or ()))
            if _bank_order and _declared and tuple(_bank_order) != _declared:
                raise ValueError(
                    f"question bank {cfg.question_bank!r} was built over clips "
                    f"{list(_bank_order)} but racket_target.clip_names_per_clip declares "
                    f"{list(_declared)}. clip_index is positional — align them; do NOT rename a "
                    f"clip to make the loader happy (that lies to every family-scoped consumer)"
                )
            _names = tuple(_bank_order) if _bank_order else (
                _declared if _declared else ("forehand", "backhand"))
            if not _declared and _bank_order:
                # The bank is the authority when the YAML said nothing: adopt its clip order so
                # per-clip metric buckets are named after the clips actually being trained.
                self._metric_buckets_per_clip = len(_names) > 0
                self._clip_names = {i: n for i, n in enumerate(_names)}
                self._metric_bucket_rows_t = None
            self._question_bank = load_question_bank(
                cfg.question_bank,
                device=self.device,
                clip_names=_names,
                allow_legacy=bool(cfg.question_bank_allow_legacy),
                expected_split=(None if cfg.question_bank_allow_legacy else "train"),
            )
            self.metrics["question_difficulty_deg"] = torch.zeros(self.num_envs, device=self.device)
            # A-frame (+Y) guard runs lazily on the first bank application (the reference strike
            # state is unresolved at __init__) — see _check_question_bank_face_frame.
            self._qb_face_frame_checked = False
            if cfg.face_command:
                # Demanded-face tracking error (deg) in the face_command frame (raw +Y vs bank
                # target). racket_normal_error_deg cannot see the M3c 单翻病: it measures vs the
                # clip reference face and is flip-INVARIANT under the sign table (both sides carry
                # the sign). This metric closes that observation blind spot in the training ledger.
                self.metrics["face_cmd_normal_error_deg"] = torch.zeros(self.num_envs, device=self.device)
            # HER achieved-target replay is bank-incompatible: the bank override runs AFTER the HER
            # block in _sample_targets_uniform, so every replayed target would be clobbered — burned
            # RNG/compute and a lying achieved_replay_frac (the DeployParity yaml defaults the mix
            # to 0.30). Forced off, once, loudly; the HER block is also hard-gated on the bank.
            if float(cfg.achieved_target_mix_prob) > 0.0:
                raise ValueError(
                    f"racket_target.achieved_target_mix_prob={cfg.achieved_target_mix_prob} is "
                    f"incompatible with a question bank / solved target: the bank override runs "
                    f"AFTER the HER block in _sample_targets_uniform, so every replayed target is "
                    f"clobbered — burned RNG and compute plus a lying achieved_replay_frac. This "
                    f"used to be force-zeroed with a print, which meant a shipped task yaml could "
                    f"keep saying 0.30 forever. Set racket.achieved_target_mix_prob: 0.0 in the "
                    f"task yaml."
                )
            # S2a base pin: per-clip ready-anchor XY offset, evaluated ONCE from the bank's FIXED
            # contact point through the same coupling as the per-question path (built lazily in
            # _qb_base_anchor_off_xy — the reference reach offset needs the motion term, which is
            # unresolved at __init__).
            self._qb_base_anchor = None
            print(
                f"[RacketTargetCommand] stage-1 question bank {cfg.question_bank}: "
                f"questions per clip = {self._question_bank.counts.tolist()}",
                flush=True,
            )

        if self._cq_enabled:
            # Same metric buckets the bank path registers — question_difficulty_deg would otherwise
            # freeze at its init value and the reset-mean "question difficulty mix" readout becomes
            # a lie. The continuous path recomputes it as angle(demanded face, raw clip face), which
            # is the SAME quantity the bank stores (reproduced to <= 3.5 deg on the shipped banks).
            self.metrics["question_difficulty_deg"] = torch.zeros(self.num_envs, device=self.device)
            self.metrics["question_exhausted_frac"] = torch.zeros(self.num_envs, device=self.device)
            if cfg.face_command:
                self.metrics["face_cmd_normal_error_deg"] = torch.zeros(
                    self.num_envs, device=self.device)
            self._qb_base_anchor = None
            self._qb_face_frame_checked = True   # 连续路径没有 npz 行可扫,门在求解时就闭合了
            print(
                f"[RacketTargetCommand] CONTINUOUS questions ON (target_mode=solved): "
                f"buffer {int(cfg.cq_buffer_rows)} rows/clip, overdraw {float(cfg.cq_overdraw)}, "
                f"n_iters {int(cfg.cq_n_iters)}, tol {float(cfg.cq_tol_m)} m, "
                f"speed_budget {float(cfg.cq_speed_budget)} m/s (deploy pp_policy gate; the shipped "
                f"banks were generated at 4.0), spin_abs_max {float(cfg.cq_spin_abs_max)} rad/s, "
                f"exam_holdout={bool(cfg.cq_exam_holdout)}, "
                f"anchor_bank={cfg.cq_anchor_bank or '<none>'}",
                flush=True,
            )

        # Actual racket state, world frame (from FK).
        self.racket_pos_w = torch.zeros(self.num_envs, 3, device=self.device)
        self.racket_quat_w = torch.zeros(self.num_envs, 4, device=self.device)
        self.racket_quat_w[:, 0] = 1.0
        self.racket_lin_vel_w = torch.zeros(self.num_envs, 3, device=self.device)
        self.racket_normal_w = torch.zeros(self.num_envs, 3, device=self.device)
        # Raw (+Y, unsigned) twin of racket_normal_w — the face_command reward frame (_face_pair).
        # Same unit-+Z pre-FK init as the signed twin (both are overwritten by the first
        # _compute_racket_state; a degenerate zero "normal" would read as a silent 90°).
        self.racket_normal_raw_w = torch.zeros(self.num_envs, 3, device=self.device)
        self.racket_normal_raw_w[:, 2] = 1.0
        self.racket_normal_w[:, 2] = 1.0
        # The official site inherits the wrist frame, but physical butt->blade is the +X/+Z
        # diagonal rather than site-local +X.  Together with the signed face normal this makes
        # wrist twist observable.  It is overwritten by the first FK.
        self.racket_long_axis_w = torch.zeros(self.num_envs, 3, device=self.device)
        from . import racket_contact_geometry as contact_geometry

        self.racket_long_axis_w[:] = torch.tensor(
            contact_geometry.RACKET_BUTT_TO_BLADE_AXIS_LOCAL,
            device=self.device,
            dtype=self.racket_long_axis_w.dtype,
        )
        # Fresh ActionBall v2 keeps the ball-centre/face-centre tuple explicit
        # while the existing policy command buffers remain the official
        # URDF/MJCF racket *site*.  Legacy/task-first paths never read these.
        self._action_ball_ball_contact_target_w = torch.zeros(
            self.num_envs, 3, device=self.device
        )
        self._action_ball_face_center_velocity_target_w = torch.zeros(
            self.num_envs, 3, device=self.device
        )
        self._action_ball_racket_command_quat_w = torch.zeros(
            self.num_envs, 4, device=self.device
        )
        self._action_ball_racket_command_quat_w[:, 0] = 1.0
        # Previous control-sample selected-face state for ActionBall's
        # fail-closed swept contact predicate.  Identity latches prevent a
        # sample from one action/reset/swing being reused by its successor.
        self._action_ball_prev_racket_site_w = torch.zeros(
            self.num_envs, 3, device=self.device
        )
        self._action_ball_prev_racket_quat_w = torch.zeros(
            self.num_envs, 4, device=self.device
        )
        self._action_ball_prev_racket_quat_w[:, 0] = 1.0
        self._action_ball_prev_racket_site_velocity_w = torch.zeros(
            self.num_envs, 3, device=self.device
        )
        self._action_ball_prev_racket_angular_velocity_w = torch.zeros(
            self.num_envs, 3, device=self.device
        )
        self._action_ball_prev_attempt_action = torch.full(
            (self.num_envs,), -1, dtype=torch.long, device=self.device
        )
        self._action_ball_prev_reset_generation = torch.full(
            (self.num_envs,), -1, dtype=torch.long, device=self.device
        )
        self._action_ball_prev_swing_generation = torch.full(
            (self.num_envs,), -1, dtype=torch.long, device=self.device
        )
        self._action_ball_prev_contact_valid = torch.zeros(
            self.num_envs, dtype=torch.bool, device=self.device
        )

        # --- Tier-1 virtual incoming ball (rewardDesign.md): per-swing sampled incoming state and
        # the at-strike outcome caches read by the one-shot virtual_* reward terms. vb_fired is
        # recomputed EVERY step in _update_metrics (true only on a gated exact-strike frame), so the
        # cached outcome is consumed exactly once per swing. Buffers exist even when the feature is
        # off (all-zero / all-False) so the reward terms are safely inert.
        self.vb_vel_in_w = torch.zeros(self.num_envs, 3, device=self.device)
        self.vb_spin_in_w = torch.zeros(self.num_envs, 3, device=self.device)
        self.vb_fired = torch.zeros(self.num_envs, dtype=torch.bool, device=self.device)
        # Owner-side wiring for the device-resident same-transition strike
        # fact.  Legacy ActionBall keeps this optional; fresh full-MDP always
        # constructs exactly one R03 under this causal Racket writer.  Its
        # publication still fails before mutation until Device-R05 supplies
        # the exact current full-key/shot identity.
        self._action_ball_strike_fact_device_coordinator = None
        self._action_ball_strike_fact_task_key = None
        self._action_ball_strike_fact_key_ints = None
        self._action_ball_strike_fact_key_digests = None
        self._action_ball_strike_fact_source_step = None
        self._action_ball_strike_fact_exact_eligibility = None
        self._action_ball_strike_fact_target_validity = None
        self._action_ball_strike_fact_mutation_mask = None
        self._action_ball_strike_fact_expected_publish_step = None
        if self._action_ball_strike_fact_device_enabled:
            from .action_ball_strike_fact_device import (
                ActionBallStrikeFactDeviceCoordinator,
                DeviceActionTaskKey,
                OBSERVATION_PROJECTION_MODE_FRESH_FULL_MDP,
                OBSERVATION_PROJECTION_MODE_LEGACY_DIAGNOSTIC,
            )

            key_ints = {
                "env_id": torch.arange(
                    self.num_envs, dtype=torch.int64, device=self.device
                ),
                "reset_generation": torch.zeros(
                    self.num_envs, dtype=torch.int64, device=self.device
                ),
                "swing_generation": torch.full(
                    (self.num_envs,), -1, dtype=torch.int64, device=self.device
                ),
                "action_uid": torch.zeros(
                    self.num_envs, dtype=torch.int64, device=self.device
                ),
                "action_slot": torch.full(
                    (self.num_envs,), -1, dtype=torch.int64, device=self.device
                ),
            }
            key_digests = {
                name: torch.zeros(
                    (self.num_envs, 32),
                    dtype=torch.uint8,
                    device=self.device,
                )
                for name in (
                    "birth_sha256",
                    "sample_sha256",
                    "task_sha256",
                )
            }
            self._action_ball_strike_fact_key_ints = key_ints
            self._action_ball_strike_fact_key_digests = key_digests
            self._action_ball_strike_fact_task_key = DeviceActionTaskKey(
                **key_ints, **key_digests
            )
            self._action_ball_strike_fact_source_step = torch.full(
                (self.num_envs,), -1, dtype=torch.int64, device=self.device
            )
            self._action_ball_strike_fact_exact_eligibility = torch.zeros(
                self.num_envs, dtype=torch.bool, device=self.device
            )
            self._action_ball_strike_fact_target_validity = torch.full(
                (self.num_envs,),
                all(self._action_ball_target_validity_mask),
                dtype=torch.bool,
                device=self.device,
            )
            self._action_ball_strike_fact_mutation_mask = torch.zeros(
                self.num_envs, dtype=torch.bool, device=self.device
            )
            self._action_ball_strike_fact_device_coordinator = (
                ActionBallStrikeFactDeviceCoordinator(
                    num_envs=self.num_envs,
                    device=self.device,
                    dtype=self.racket_target_pos_w.dtype,
                    observation_projection_mode=(
                        OBSERVATION_PROJECTION_MODE_FRESH_FULL_MDP
                        if self._action_ball_full_mdp_enabled
                        else OBSERVATION_PROJECTION_MODE_LEGACY_DIAGNOSTIC
                    ),
                )
            )
        self.metrics["action_ball_target_face_compatible_at_strike"] = torch.zeros(
            self.num_envs, device=self.device
        )
        self.vb_landing_xy = torch.zeros(self.num_envs, 2, device=self.device)
        self.vb_landing_valid = torch.zeros(self.num_envs, dtype=torch.bool, device=self.device)
        self.vb_on_opponent = torch.zeros(self.num_envs, dtype=torch.bool, device=self.device)
        self.vb_depth_ok = torch.zeros(self.num_envs, dtype=torch.bool, device=self.device)
        self.vb_net_z = torch.zeros(self.num_envs, device=self.device)
        self.vb_net_clear = torch.zeros(self.num_envs, dtype=torch.bool, device=self.device)
        self.vb_net_crossed = torch.zeros(self.num_envs, dtype=torch.bool, device=self.device)
        self.vb_topspin = torch.zeros(self.num_envs, device=self.device)
        self.vb_spin_out_norm = torch.zeros(self.num_envs, device=self.device)
        self._vb_params = None  # lazy venue-yaml load on first evaluation
        # Derived table landmarks (env frame), from geometry.py ITTF constants.
        from whole_body_tracking.tasks.table_tennis import geometry as _tt_geom

        self._vb_net_x = float(cfg.vb_table_near_x) + _tt_geom.NET_X
        self._vb_far_x = float(cfg.vb_table_near_x) + _tt_geom.TABLE_LENGTH
        self._vb_half_w = _tt_geom.TABLE_WIDTH / 2.0
        self._vb_net_top_z = float(cfg.vb_table_surface_z) + _tt_geom.NET_HEIGHT
        self._vb_ball_r = _tt_geom.BALL_RADIUS
        self._vb_target_xy = torch.tensor(
            [float(cfg.vb_target_x), float(cfg.vb_target_y)], device=self.device
        )
        # Legacy/bank/CQ modes keep the historical single aim.  ``action_ball`` overwrites only the
        # selected rows with the exact aim carried by the installed task receipt, so the optional
        # virtual-ball scorer never grades a solved task against a different landing point.
        self._vb_target_xy_per_env = self._vb_target_xy.unsqueeze(0).repeat(
            self.num_envs, 1
        )
        # Sample-weighted EMA accumulators (same decay/min-count discipline as the exact-strike block).
        self._vb_exact_acc = 0.0
        self._vb_hit_acc = 0.0
        self._vb_net_acc = 0.0
        self._vb_land_valid_acc = 0.0
        self._vb_inb_acc = 0.0
        # Per-action accumulators are initialized after ``_clip_names`` is resolved below.  The
        # former literal ``{0, 1}`` crashed on the first exact strike of clip >=2.
        self._vb_exact_acc_c = {}
        self._vb_inb_acc_c = {}
        self._vb_hit_acc_c = {}

        # Reference racket state at the strike frame (CONSTANT per clip): pos (env-origin relative),
        # world linear velocity, and face normal, computed by the SAME FK as the actual racket
        # (_compute_racket_state) but fed the reference MOTION's body poses. Used by the
        # "reference_perturbed" target mode so a sampled target is one the imitated swing can actually
        # reach (a perfect imitator hits it exactly). Cached lazily on first resample, after the motion
        # term is resolved and its motion_file is loaded.
        self._ref_strike_cached = False
        # Unified multi-clip: per-clip strike phase as a [num_segments] tensor (built lazily once the
        # motion term is resolved). None until then; falls back to the scalar strike_phase.
        self._strike_phase_per_clip_t = None
        # 每 clip 的击球面符号表([num_segments] 张量,懒构建:第一次用到时按加载的 clip 数 fail-loud
        # 校验后落地)。None = cfg 表为空 = 全部 clip 用标量 mount_normal_sign(现役行为,逐位不变)。
        # 病根见 cfg.mount_normal_sign_per_clip 的注释:正反手用拍子相反的两面,单一符号钉死反手拍面。
        self._mount_sign_per_clip_t = None
        # 每 clip 的"是不是正手家族"bool 表([num_segments] 张量,懒构建:第一次查表时从 motion 术语的
        # cfg.clip_family_per_clip 解析,fail-loud;见 _clip_family_is_forehand)。None = 还没解析。
        # 用途(spdmix v2 硬绑定一):swing_sign / uniform 目标 y 侧 / 事件与考卷安装原来四处写死
        # ``clips == 0`` = 正手,6-clip 变速列表里正手 1.0/1.2 变体会被误判成反手;现在全部按这张表取。
        # 缺席配置时表按"单 clip 正手 / 恰 2 clip = (正手, 反手)"推导,与写死判断逐字节同值。
        self._family_is_forehand_t = None
        # 家族行号表([num_segments] long,0=正手族/1=反手族,懒构建自 _clip_family_is_forehand)。
        # 所有"按族分桶"的下标(HER 缓存、per-族指标、每族一行的框表展开)单一来源。
        self._clip_family_rows_t = None
        # cfg per-clip 框表按加载 clip 数对齐后的缓存(键 = cfg 键名;见 _per_clip_range_rows)。
        self._per_clip_range_rows_cache = {}
        # Per-clip reference paddle FACE NORMAL at the strike frame ([num_segments, 3], built lazily). In
        # uniform mode the target normal is set to the imitated swing's actual paddle normal (which the
        # policy can achieve) — NOT the racket-velocity direction, which is ~18-110 deg off the +Y blade
        # face and makes the normal goal (and thus the composite success metric) unsatisfiable.
        self._ref_normal_per_clip = None
        # Optional per-clip racket target-velocity boxes (uniform mode). Built ONCE from cfg; stays None
        # when the shared box is used (backward compatible). Shape (num_clips, 3, 2): [clip][x/y/z][lo/hi].
        self._vel_range_per_clip_t = None
        if self.cfg.racket_vel_range_per_clip is not None:
            self._vel_range_per_clip_t = torch.tensor(
                [[[float(lo), float(hi)] for (lo, hi) in clip_rng]
                 for clip_rng in self.cfg.racket_vel_range_per_clip],
                dtype=torch.float32,
                device=self.device,
            )
            self._assert_target_velocity_points_forward()
        # Optional per-clip racket target-POSITION boxes (uniform mode). Same shape/semantics as the
        # velocity one above; None -> shared pos box (backward compatible). (num_clips, 3, 2): [clip][x/y/z][lo/hi].
        self._pos_range_per_clip_t = None
        if self.cfg.racket_pos_range_per_clip is not None:
            self._pos_range_per_clip_t = torch.tensor(
                [[[float(lo), float(hi)] for (lo, hi) in clip_rng]
                 for clip_rng in self.cfg.racket_pos_range_per_clip],
                dtype=torch.float32,
                device=self.device,
            )
            for _clip_id, _clip_rng in enumerate(self.cfg.racket_pos_range_per_clip):
                self._assert_contact_clears_table(
                    _clip_id,
                    self._commanded_target_x_hi(float(_clip_rng[0][1])),
                    float(_clip_rng[2][0]),
                    "racket_pos_range_per_clip",
                )
        # PER-CLIP INCOMING-BALL regime (a block gets fast balls, a loop slow ones, same run). Same
        # (num_clips, 3, 2) shape as the racket boxes; None -> the shared vb_vel_*_range box.
        self._vb_vel_range_per_clip_t = None
        if getattr(self.cfg, "vb_vel_range_per_clip", None) is not None:
            self._vb_vel_range_per_clip_t = torch.tensor(
                [[[float(lo), float(hi)] for (lo, hi) in clip_rng]
                 for clip_rng in self.cfg.vb_vel_range_per_clip],
                dtype=torch.float32,
                device=self.device,
            )
            self._assert_incoming_ball_boxes_are_sane()
        self._vb_spin_abs_max_per_clip_t = None
        if getattr(self.cfg, "vb_spin_abs_max_per_clip", None) is not None:
            _spin_rows = tuple(float(s) for s in self.cfg.vb_spin_abs_max_per_clip)
            _bad_spin = [(i, s) for i, s in enumerate(_spin_rows) if not s >= 0.0]
            if _bad_spin:
                raise ValueError(
                    f"vb_spin_abs_max_per_clip must be non-negative (rad/s); got {_bad_spin} as "
                    f"(clip index, value)"
                )
            self._vb_spin_abs_max_per_clip_t = torch.tensor(
                _spin_rows, dtype=torch.float32, device=self.device
            )
        self._ref_racket_pos_rel = torch.zeros(3, device=self.device)
        self._ref_racket_vel_w = torch.zeros(3, device=self.device)
        self._ref_racket_normal_w = torch.zeros(3, device=self.device)
        # Reference base (root) XY at the strike + the base->racket horizontal offset. Used to COUPLE
        # base_target to racket_target so standing at base_target keeps the racket reachable.
        self._ref_base_pos_rel = torch.zeros(3, device=self.device)
        self._ref_reach_offset_xy = torch.zeros(2, device=self.device)
        self._ref_racket_pos_rel_per_clip = None
        self._ref_racket_vel_w_per_clip = None
        self._ref_racket_quat_w_per_clip = None
        self._ref_racket_ang_vel_w_per_clip = None
        self._ref_racket_normal_w_per_clip = None
        self._ref_racket_normal_raw_w_per_clip = None
        self._ref_base_pos_rel_per_clip = None
        self._ref_reach_offset_xy_per_clip = None

        # Success-gated curriculum: running perturbation scale, advanced only when the smoothed
        # exact-strike composite success clears the threshold (see _perturb_scale / _update_metrics).
        self._curr_perturb_scale = float(cfg.ref_perturb_curriculum_start)

        # Decayed accumulators for the CONDITIONAL exact-strike pass rates (see _update_metrics). The
        # logged strike_*_pass_exact / strike_composite_success_exact report the fraction of *exact-strike
        # samples* that clear each acceptance threshold — NOT a per-env value held over the long
        # non-strike portion of every episode (which diluted the old metric ~10x at reset-logging time).
        # Sample-weighted EMA: acc = decay*acc + this-step-count; rate = pass_acc / sample_acc.
        self._exact_n_acc = 0.0
        self._exact_pass_comp_acc = 0.0
        self._exact_pass_pos_acc = 0.0
        self._exact_pass_vel_acc = 0.0
        self._exact_pass_normal_acc = 0.0
        # 5 cm / 10 cm position-accuracy buckets on the SAME exact-strike mask + EMA denominator as the
        # pass metrics above (so they are comparable with the composite, unlike the old window-exit-held
        # strike_success_5cm/10cm which sampled the racket ~0.26 m past target).
        self._exact_pass_5cm_acc = 0.0
        self._exact_pass_10cm_acc = 0.0
        self._exact_composite_rate = 0.0
        # P2.3 adaptive-sigma driver: global decayed error-magnitude sums over exact-strike samples
        # (mean = sum / _exact_n_acc). Per-clip variants exist below; sigma needs one global signal.
        self._exact_pos_err_sum = 0.0
        self._exact_vel_err_sum = 0.0
        # 拍面(normal)通道的全局衰减误差和(弧度)——与 pos/vel 完全平行的第三路驱动。
        # 无条件累加(纯内部标量,不进任何输出),只有 adaptive_sigma_normal=True 时才被读。
        self._exact_nrm_err_sum = 0.0
        # Live adaptive sigmas (start at the cfg maxima = the hand-tuned YAML stds; only applied to
        # the reward terms when cfg.adaptive_sigma is on).
        self._adaptive_sigma_pos = float(cfg.sigma_pos_max)
        self._adaptive_sigma_vel = float(cfg.sigma_vel_max)
        # 第三通道(拍面法向)sigma:同样从 cfg 最大值起步(=YAML 手调 std 的 2x 验收宽度),
        # 只有 adaptive_sigma_normal=True 时才会被更新/落到奖励项上。
        self._adaptive_sigma_normal = float(getattr(cfg, "sigma_normal_max", 0.52))
        # Stage-1 state is allocated only for the explicit Stage-1 source.  Keeping
        # these names off legacy instances preserves their historical heuristic
        # checkpoint payload byte-for-byte when the new task is not selected.
        if _adaptive_sigma_source(cfg) == _ADAPTIVE_SIGMA_SOURCE_STAGE1_CLIP_SITE:
            self._stage1_sigma_pos_n_acc = 0.0
            self._stage1_sigma_vel_n_acc = 0.0
            self._stage1_sigma_nrm_n_acc = 0.0
            self._stage1_sigma_pos_err_sq_sum = 0.0
            self._stage1_sigma_vel_err_sq_sum = 0.0
            self._stage1_sigma_nrm_err_sq_sum = 0.0
            self._stage1_sigma_reset_exclusion = torch.zeros(
                self.num_envs, dtype=torch.bool, device=self.device
            )
            self._adaptive_sigma_source_code = _ADAPTIVE_SIGMA_SOURCE_CODES[
                _ADAPTIVE_SIGMA_SOURCE_STAGE1_CLIP_SITE
            ]
            self._adaptive_sigma_profile_pos_min = float(cfg.sigma_pos_min)
            self._adaptive_sigma_profile_pos_max = float(cfg.sigma_pos_max)
            self._adaptive_sigma_profile_vel_min = float(cfg.sigma_vel_min)
            self._adaptive_sigma_profile_vel_max = float(cfg.sigma_vel_max)
            self._adaptive_sigma_profile_nrm_min = float(cfg.sigma_normal_min)
            self._adaptive_sigma_profile_nrm_max = float(cfg.sigma_normal_max)
            self._adaptive_sigma_live_state_initialized = False
            self.exact_resume_state_dict = self._stage1_exact_resume_state_dict
            self.load_exact_resume_state_dict = (
                self._stage1_load_exact_resume_state_dict
            )

        # Per-clip (forehand=clip 0 / backhand=clip 1) breakdown of the exact-strike metrics, so wandb
        # shows each swing separately (the aggregate composite can hide one swing lagging). Same
        # sample-weighted EMA as the global accumulators above, but each clip's exact-strike samples are
        # accumulated separately (selected by the motion command's clip_id). Populated in multiseg only.
        # 键 = 指标桶行号(_metric_bucket_rows)。cfg.clip_names_per_clip 为空(现役所有在跑臂)
        # 时桶 = 家族行号(0=正手族, 1=反手族),legacy 2-clip 下与 clip_id 恒等,逐字节不变;
        # 配了 clip_names_per_clip 时桶 = clip_id,每个动作一个桶——否则 fh_loop 和 fh_block_syn
        # 共用一个桶,挡球的失败会藏在拉球的数字里(正手回球率 0.0000 藏在 45% 合计里的老病)。
        self._family_names = {0: "forehand", 1: "backhand"}
        _names_cfg = tuple(str(n) for n in (getattr(cfg, "clip_names_per_clip", ()) or ()))
        if _names_cfg and len(set(_names_cfg)) != len(_names_cfg):
            raise ValueError(
                f"racket_target.clip_names_per_clip has duplicate name(s) {_names_cfg} — the "
                f"names key per-clip metric buckets, so two clips sharing a name would silently "
                f"merge their return rates"
            )
        self._metric_buckets_per_clip = bool(_names_cfg)
        self._clip_names = (
            {i: n for i, n in enumerate(_names_cfg)} if _names_cfg else dict(self._family_names)
        )
        self._vb_exact_acc_c = {c: 0.0 for c in self._clip_names}
        self._vb_inb_acc_c = {c: 0.0 for c in self._clip_names}
        self._vb_hit_acc_c = {c: 0.0 for c in self._clip_names}
        self._metric_bucket_rows_t = None
        # Non-decayed, per-PPO-update eligibility ledger for sparse virtual-ball outcomes.  The
        # existing virtual_* rates are EMAs and deliberately suppress values before their
        # denominators warm up; they therefore cannot tell a milestone classifier whether a zero
        # means "failed" or "the reward was never eligible".  These integer counters book the
        # exact same masks as _vb_book_strike_step, globally and per action family, and are consumed
        # exactly once by MotionOnPolicyRunner.  They do not enter observations, rewards, resets or
        # sampling.
        _sparse_names = (
            _EXACT_STRIKE_TIMING_COUNTER,
            "strike_opportunity_count",
            "virtual_capture_count",
            "virtual_net_clear_count",
            "virtual_landing_valid_count",
            "virtual_legal_return_count",
            *_ACTION_BALL_CONTACT_REJECTION_COUNTERS,
        )
        self._sparse_reward_eligibility_counters = {
            name: torch.zeros((), dtype=torch.long, device=self.device)
            for name in _sparse_names
        }
        for _family in self._clip_names.values():
            for _name in _sparse_names:
                self._sparse_reward_eligibility_counters[f"{_name}_{_family}"] = torch.zeros(
                    (), dtype=torch.long, device=self.device
                )
        # Fixed diagnostic histogram edges are materialized exactly once per command instance.
        # The strike hot path reuses this tensor by identity; it never constructs or transfers a
        # fresh device tensor while collecting rollout evidence.
        self._exact_strike_paddle_ball_distance_bin_edges_m_t = torch.tensor(
            _EXACT_STRIKE_PADDLE_BALL_DISTANCE_BIN_EDGES_M,
            dtype=self.racket_target_pos_w.dtype,
            device=self.device,
        )
        # Exact per-PPO-update behavior ledger.  Event counters and ready-phase denominators are
        # integer, sums are float64, and nothing decays.  The runner consumes this transaction
        # together with the sparse strike ledger once per update, so two disjoint 100-update
        # windows can be reconstructed by summing their records (unlike the historical EMAs).
        self._exact_behavior_decision_counters = {}
        self._ensure_exact_behavior_decision_counters()
        self._exact_n_acc_c = {c: 0.0 for c in self._clip_names}
        self._exact_pass_pos_acc_c = {c: 0.0 for c in self._clip_names}
        self._exact_pass_vel_acc_c = {c: 0.0 for c in self._clip_names}
        self._exact_pass_normal_acc_c = {c: 0.0 for c in self._clip_names}
        self._exact_pass_comp_acc_c = {c: 0.0 for c in self._clip_names}
        self._exact_pos_err_sum_c = {c: 0.0 for c in self._clip_names}
        self._exact_vel_err_sum_c = {c: 0.0 for c in self._clip_names}
        self._exact_nrm_err_sum_c = {c: 0.0 for c in self._clip_names}

        # --- UNCONDITIONAL swing accounting (Phase A wandb fix) ------------------------------------
        # strike_composite_success_exact is CONDITIONAL: its denominator is exact-strike SAMPLES, so
        # an env that falls BEFORE the strike frame contributes nothing — composite ~1.0 coexists
        # with any pre-strike fall rate (exactly what happened in deploy). These accumulators count
        # every swing START (episode reset or clip wrap assigns a new swing) with the same EMA decay
        # as the exact accumulators, so:
        #   swing_completion_rate = exact_n_acc / swing_starts_acc   (unconditional; falls count)
        #   pre_strike_fall_rate  = pre-strike terminations / swing starts
        self._swing_starts_acc = 0.0
        self._swing_starts_acc_c = {c: 0.0 for c in self._clip_names}
        # --- Per-swing SAME-LEDGER rally accounting (metric-sync fix, 取证定案 2026-07-08) ----------
        # Disease: virtual_return_rate_rally's numerator (_vb_inb_acc) books at the exact-strike
        # frame and decays ONLY on strike-carrying steps (inside _vb_evaluate), while its
        # denominator (_swing_starts_acc) books at swing START and decays EVERY step — two ledgers
        # with different decay schedules plus a ~1-swing (~116-step) booking phase lag. When 4096
        # envs form a synchronized reset queue (same-instant resume + low fall rate -> mass
        # timeout; episode_length sawtooth 52->485), the ratio oscillates 0.31->1.48 and breaks 1.
        # Cure (per-swing 同刻入账): the exact-strike frame only LATCHES "this swing produced a
        # legal return" (_rally_returned); at the swing's END (wrap or true reset — i.e. inside
        # _count_swing_starts) the ended attempt books its start AND its returned flag TOGETHER,
        # into accumulators decayed TOGETHER once per step in _update_metrics. Paired bookings on
        # one ledger => returns can never outrun starts => the rate is <=1 by construction and
        # equals the true per-swing return rate under ANY reset synchronization. The old mixed-
        # ledger readout survives one transition period as *_legacy (cfg.rally_legacy_metrics)
        # for new/old comparison. 人话:改成"每拍打完才记账,回没回球和这一拍同时入同一本账"。
        self._rally_active = torch.zeros(self.num_envs, dtype=torch.bool, device=self.device)
        self._rally_returned = torch.zeros(self.num_envs, dtype=torch.bool, device=self.device)
        # Wrap-boundary parking latch (防御修 2026-07-09 取证副产品): a legal return whose strike
        # fires on the SAME step a clip wraps belongs to the swing STARTING at that wrap (the motion
        # term wraps before this term's metrics pass), but the OLD attempt is still unbooked at that
        # moment. _vb_book_strike_step parks such returns here; _count_swing_starts books the ended
        # attempt first, then hands the parked latch to the new attempt that owns it.
        self._rally_pending_return = torch.zeros(self.num_envs, dtype=torch.bool, device=self.device)
        self._rally_starts_acc = 0.0
        self._rally_returns_acc = 0.0
        self._rally_starts_acc_c = {c: 0.0 for c in self._clip_names}
        self._rally_returns_acc_c = {c: 0.0 for c in self._clip_names}
        # Exact decision-window swing ledger.  Starts and exact-strike opportunities occur at
        # different phases of an attempt, so their counts may legitimately straddle a PPO-window
        # boundary.  Latch completion during the attempt and book numerator+denominator together
        # only when that attempt closes (wrap or true reset).  This makes every independently
        # aggregated window satisfy completion <= outcome without clipping or boundary slack.
        self._exact_attempt_active = torch.zeros(
            self.num_envs, dtype=torch.bool, device=self.device
        )
        self._exact_attempt_completed = torch.zeros(
            self.num_envs, dtype=torch.bool, device=self.device
        )
        # A defensive wrap-step exact strike belongs to the newly starting attempt because Motion
        # has already advanced before this command's metrics pass.  Park it until close-out books
        # the old attempt, mirroring the legal-return rally latch above.
        self._exact_pending_completion = torch.zeros(
            self.num_envs, dtype=torch.bool, device=self.device
        )
        # The initial planner deadline belongs to the whole swing attempt, not to the live TTS
        # countdown.  Latch one bucket per attempt so its eventual close-out and sparse strike
        # outcomes can be compared without reconstructing state from EMA curves.  -1 means this is
        # a legacy/non-planner attempt and is deliberately absent from bucket denominators.
        self._exact_attempt_initial_tts_bucket = torch.full(
            (self.num_envs,), -1, dtype=torch.long, device=self.device
        )
        # A defensive exact strike may fire on the same step Motion wraps into the next clip,
        # before RacketTargetCommand samples that new task's initial TTS.  Park those three sparse
        # outcomes until _begin_same_ball_planner_task assigns the new bucket.
        self._exact_pending_timing_bucket_events = {
            name: torch.zeros(self.num_envs, dtype=torch.bool, device=self.device)
            for name in _TIMING_BUCKET_SPARSE_EVENTS
        }
        self._prestrike_fall_acc = 0.0
        # POST-strike falls (fall AFTER reaching the strike frame — the follow-through/recovery fall that
        # swing_completion_rate + pre_strike_fall_rate are both blind to; it was the actual backhand
        # deploy failure mode). Same swing-starts denominator as pre_strike_fall_rate.
        self._poststrike_fall_acc = 0.0
        # Per-clip fall attribution. NOTE: at reset time the MOTION command has already resampled
        # clip_id to the NEW swing (motion resets before racket_target), so falls are attributed via
        # _prev_clip_id — the clip snapshot taken at the END of the previous _update_command, i.e. the
        # clip the env was actually swinging when it fell.
        self._prestrike_fall_acc_c = {c: 0.0 for c in self._clip_names}
        self._poststrike_fall_acc_c = {c: 0.0 for c in self._clip_names}
        self._prev_clip_id = torch.zeros(self.num_envs, dtype=torch.long, device=self.device)
        # Post-wrap recovery latch: >=0 = the clip whose swing JUST finished while this env sits in the
        # post-wrap hold. A fall during that hold is physically the PREVIOUS swing's recovery fall, but
        # at the wrap the timing already describes the NEXT swing (pre_strike=True, clip_id=new random
        # clip) — without the latch such falls book as pre-strike falls of a 50%-wrong clip, which would
        # invert exactly the backhand-recovery diagnosis these metrics exist for. -1 = not recovering.
        self._recover_from_clip = torch.full((self.num_envs,), -1, dtype=torch.long, device=self.device)
        # True only while _resample_command is invoked from the intra-episode WRAP path (see
        # _update_command): wraps start a new swing but never count a pre-strike fall (a wrapped
        # env necessarily passed its strike frame alive).
        self._resample_is_wrap = False

        # --- Rally drift accounting (2026-07-07 continuous-rally upgrade) -------------------------
        # Deploy P7 failure mode: each walk-and-strike lunges forward; over consecutive swings the
        # displacement ACCUMULATES until a swing starts from an untrained stance and falls. These
        # track exactly that: per-swing base displacement (closed out at WRAPS = completed swings
        # only), its forward (x) component (drift is directional: forward), and the base->station
        # error at each swing start (how far the new station is when the swing begins — the recovery
        # debt the previous swing left behind). Same EMA decay/denominator discipline as the exact
        # accumulators; drift uses its own wrap-count denominator (resets don't close out a swing).
        self._swing_start_base_xy = torch.zeros(self.num_envs, 2, device=self.device)
        # Stamp lazily on the FIRST _update_metrics after a swing start: at reset time the cached
        # base_pos_w still holds the PRE-reset pose (events teleport the root after the snapshot),
        # so an eager stamp would book the teleport as drift of the episode's first swing.
        self._swing_start_pending = torch.zeros(self.num_envs, dtype=torch.bool, device=self.device)
        self._drift_n_acc = 0.0
        self._drift_sum_acc = 0.0
        self._drift_fwd_sum_acc = 0.0
        self._station_offset_start_sum_acc = 0.0
        self._heading_expiry_sum_acc = 0.0
        self._heading_expiry_n_acc = 0.0
        self._recovery_spawn_sum_acc = 0.0
        self._recovery_expiry_sum_acc = 0.0
        self._recovery_n_acc = 0.0
        # Diagnostic-only one-step staging for pure hold/recovery telemetry.  The next policy
        # step fuses these five reductions into the mandatory exact-any host packet; the final
        # rollout step is drained once at the PPO update boundary.
        self._diagnostic_hold_recovery_metric_scalars = ()
        self._previous_in_hold = torch.zeros(
            self.num_envs, dtype=torch.bool, device=self.device
        )
        self._hold_start_yaw = torch.zeros(self.num_envs, device=self.device)
        # A true reset can replace one held state with another without a boolean falling/rising
        # edge. Force a fresh stamp on the first metrics tick after every resample.
        self._hold_edge_pending = torch.zeros(
            self.num_envs, dtype=torch.bool, device=self.device
        )

        # --- HER-style achieved-target replay buffers (see RacketTargetCommandCfg) -----------------
        # Per-clip ring buffers of the racket state the policy ACTUALLY produced at exact-strike frames:
        # position env-origin-relative (world minus env origin), velocity world. Written in
        # _update_metrics on the exact_strike mask (alive envs only — terminated envs were reset before
        # the command computes); read in _sample_targets_uniform with prob achieved_target_mix_prob.
        _absize = max(int(cfg.achieved_buffer_size), 1)
        self._ach_pos = {c: torch.zeros(_absize, 3, device=self.device) for c in self._clip_names}
        self._ach_vel = {c: torch.zeros(_absize, 3, device=self.device) for c in self._clip_names}
        # R14: playback speed of the swing that PRODUCED each achieved state (1.0 when retiming off),
        # so replay can rescale the velocity to the replaying swing's own speed.
        self._ach_spd = {c: torch.ones(_absize, device=self.device) for c in self._clip_names}
        self._ach_fill = {c: 0 for c in self._clip_names}
        self._ach_ptr = {c: 0 for c in self._clip_names}
        # R14: one-shot exact-strike latch per swing (armed at every target resample). Only consulted
        # when retiming is active — the float clock's ~1e-4/swing double-fire guard.
        self._exact_fired = torch.zeros(self.num_envs, dtype=torch.bool, device=self.device)
        # Decayed counters for the logged replay fraction (same EMA timescale as the exact accumulators).
        self._resample_n_acc = 0.0
        self._replay_n_acc = 0.0

        # Live strike timing is the reward/critic/physics truth.  A separately materialized actor
        # TTS exists only in the two explicit atomic-planner-tuple modes below.
        self.time_to_strike = torch.zeros(self.num_envs, device=self.device)

        # Same-ball planner revisions.  Unlike the retired midswing redraw knob, this never
        # replaces the question row or physical ball.  It maintains one explicit
        # (control_epoch, task_id), emits strictly increasing revisions of one atomic actor tuple,
        # and asks MotionCommand's phase governor to meet the revised deadline.
        self.planner_revision_enabled = bool(
            getattr(cfg, "planner_revision_enabled", False)
        )
        self._planner_revision_profile: PhaseGovernorProfile | None = None
        self._planner_initial_tts_mixture: InitialTtsMixture | None = None
        if self.planner_revision_enabled:
            raw_profile = getattr(cfg, "planner_revision_profile", None)
            if not isinstance(raw_profile, dict):
                raise ValueError(
                    "planner_revision_enabled requires a complete planner_revision_profile mapping"
                )
            self._planner_revision_profile = PhaseGovernorProfile.from_mapping(raw_profile)
            if not cfg.face_command or self._question_bank is None:
                # DELIBERATE HARD BLOCK, continuous included. This one really does want npz ROWS
                # to reconcile against, not merely "a solved target", so it is not switched to
                # _solved_targets_active. 响亮的不可发射 >> 悄悄降级的可发射。
                raise ValueError(
                    "planner revisions require the formal signed-face question-bank task; "
                    "otherwise the atomic target normal has no defined contract. This includes "
                    "target_mode='solved': a continuously drawn ball has no bank row for the "
                    "revision contract to address."
                )
            if float(cfg.midswing_resample_prob) != 0.0:
                raise ValueError(
                    "planner revisions replace midswing_resample_prob; truth/question redraws "
                    "during one physical ball are forbidden"
                )
            initial_tts = tuple(
                float(value)
                for value in getattr(cfg, "planner_revision_initial_tts_range_s", ())
            )
            if (
                len(initial_tts) != 2
                or not (
                    self._planner_revision_profile.min_tts_s
                    <= initial_tts[0]
                    < initial_tts[1]
                    <= self._planner_revision_profile.max_tts_s
                )
            ):
                raise ValueError(
                    "planner_revision_initial_tts_range_s must be a non-degenerate ordered pair "
                    "inside the "
                    "profile TTS envelope"
                )
            raw_mixture = getattr(
                cfg, "planner_revision_initial_tts_mixture", None
            )
            if not isinstance(raw_mixture, dict):
                raise ValueError(
                    "planner_revision_enabled requires a complete "
                    "planner_revision_initial_tts_mixture mapping"
                )
            self._planner_initial_tts_mixture = InitialTtsMixture.from_mapping(
                raw_mixture
            )
            self._planner_initial_tts_mixture.validate_support(
                lo_s=initial_tts[0], hi_s=initial_tts[1]
            )
            self._planner_initial_tts_component_lo = torch.tensor(
                [component.lo_s for component in self._planner_initial_tts_mixture.components],
                dtype=torch.float32,
                device=self.device,
            )
            self._planner_initial_tts_component_hi = torch.tensor(
                [component.hi_s for component in self._planner_initial_tts_mixture.components],
                dtype=torch.float32,
                device=self.device,
            )
            self._planner_initial_tts_component_weight = torch.tensor(
                [component.weight for component in self._planner_initial_tts_mixture.components],
                dtype=torch.float64,
                device=self.device,
            )
            for name in (
                "planner_revision_position_std_m",
                "planner_revision_velocity_std_mps",
                "planner_revision_normal_std_rad",
                "planner_revision_tts_std_s",
            ):
                value = float(getattr(cfg, name, 0.0))
                if not math.isfinite(value) or value < 0.0:
                    raise ValueError(f"{name} must be finite and non-negative")
            n = self.num_envs
            self._planner_control_epoch = torch.zeros(n, dtype=torch.long, device=self.device)
            self._planner_task_id = torch.zeros(n, dtype=torch.long, device=self.device)
            self._planner_task_revision = torch.full(
                (n,), -1, dtype=torch.long, device=self.device
            )
            self._planner_visible_pos = self.racket_target_pos_w.clone()
            self._planner_visible_vel = self.racket_target_vel_w.clone()
            self._planner_visible_normal = self.target_normal_cmd.clone()
            self._planner_visible_tts = self.time_to_strike.clone()
            self._planner_visible_last_precontact = torch.zeros(
                n, dtype=torch.bool, device=self.device
            )
            # The planner-owned clock deliberately disables the legacy hold counters: preparation
            # time comes from the task deadline, not from a second frozen-reference clock.  Keep a
            # separate instrumentation-only identity latch so the exact behavior ledger can still
            # sample the robot once on the first metrics tick after every physical-ball task is
            # installed.  Without this, defining "ready" exclusively as ``motion.in_hold`` makes
            # every planner-revision run report a silent zero denominator even though the first
            # post-install state is observable.
            self._exact_ready_sampled_control_epoch = torch.zeros(
                n, dtype=torch.long, device=self.device
            )
            self._exact_ready_sampled_task_id = torch.zeros(
                n, dtype=torch.long, device=self.device
            )
            # Actor delivery is a different event from producer acceptance.  Keep the complete
            # task identity so a delayed ring cannot confuse revision 2 of two adjacent balls.
            self._planner_actor_control_epoch = torch.zeros(
                n, dtype=torch.long, device=self.device
            )
            self._planner_actor_task_id = torch.zeros(
                n, dtype=torch.long, device=self.device
            )
            self._planner_actor_task_revision = torch.full(
                (n,), -1, dtype=torch.long, device=self.device
            )
            self.metrics["planner_task_revision"] = torch.zeros(n, device=self.device)
            self.metrics["planner_same_task_revision_active"] = torch.zeros(n, device=self.device)

        # --- A1 target latency & time-variance (mocap->planner->runner realism) --------------------
        # MOTIVATION: training previously handed the actor a PERFECT, instantly-updated target; the
        # real loop (mocap -> planner -> runner) delivers it LATE (transport + planning latency),
        # NOISY (ball-prediction error that SHRINKS as the strike approaches — SMASH Eq. 14), and
        # REFINED mid-swing (the planner re-plans WHERE while the swing clock keeps running — PACE
        # injects sensor delays for the same reason). Without modeling this, the mocap-closed-loop
        # deployment faces out-of-distribution target dynamics. ALL knobs default OFF and the default
        # path is byte-identical: delay==0 & jitter==0 make the actor-visible views ALIAS the live
        # tensors (zero overhead, no extra RNG); midswing_resample_prob==0 short-circuits before any
        # RNG draw. Only the ACTOR-visible view is degraded — rewards, metrics, the privileged critic,
        # and the achieved-target-replay WRITE always use the TRUE live target.
        self._delay_steps = max(int(cfg.target_delay_steps), 0)
        self._delay_tts_mode = _target_delay_tts_mode(cfg)
        # 耦合传输(2026-07-25,取代旧 NO-LAUNCH 守卫):planner 修订 + 延迟时,延迟发生在
        # "提交"这道工序——每步生成的修订元组(pos/vel/normal/tts,原子)先进在途环压 d 步,
        # d 步后才提交给相位调度器。接受记账、调度器看到的 desired_tts、actor 可见元组因此
        # 消费同一条延迟流(mocap→relay 语义);actor 端不再叠观测延迟环(否则总延迟成 2d)。
        # 任务安装(begin)不是 mocap 流,保持即时。d=0 = 耦合不激活 = 现役路径逐字节不变。
        # 半配置组合(live tts 模式)在 _coupled_transport_mode 里 fail-loud;event timing 与
        # 耦合传输的交互未定义,在 _revise_same_ball_actor_tuple 运行期 fail-loud(motion 术语
        # 构造期还未解析,只能推迟到第一次使用)。
        self._coupled_transport = _coupled_transport_mode(cfg)
        self._delay_tts_active = self._delay_tts_mode != "live"
        self._atomic_tts_active = self._delay_tts_active or self.planner_revision_enabled
        # actor 观测端延迟环的步数:legacy 模式 = d(现役行为);耦合模式 = 0(提交已经晚了
        # d 步,actor 直接读被接受的 planner_visible 流,调度器/actor 同拍看到同一元组)。
        self._actor_ring_steps = 0 if self._coupled_transport else self._delay_steps
        if self._coupled_transport:
            # 在途环(长度 d,单指针):槽位 p 在第 t 步写入、第 t+d 步弹出提交。valid=False 的
            # 槽(当步没生成 / 新任务安装时被作废)不提交——中继丢弃已结束任务的消息。
            self._pend_ptr = 0
            self._pend_valid = torch.zeros(
                self._delay_steps, self.num_envs, dtype=torch.bool, device=self.device
            )
            self._pend_pos = torch.zeros(self._delay_steps, self.num_envs, 3, device=self.device)
            self._pend_vel = torch.zeros(self._delay_steps, self.num_envs, 3, device=self.device)
            self._pend_normal = torch.zeros(self._delay_steps, self.num_envs, 3, device=self.device)
            self._pend_tts = torch.zeros(self._delay_steps, self.num_envs, device=self.device)
        self._jitter_pos = max(float(cfg.target_jitter_pos_per_s), 0.0)
        self._jitter_vel = max(float(cfg.target_jitter_vel_per_s), 0.0)
        # Calibrated MEASUREMENT noise (ball_physics_venue.yaml `capture:` block, 2026-07-03 fit):
        # white + AR(1)-colored position error of the mocap link. Unlike the tts-scaled jitter above
        # (which models PREDICTION convergence), measurement noise does NOT shrink as the strike
        # approaches, so no tts scaling. rho is per POLICY step: venue 0.946/frame @300 Hz -> ^6 @50 Hz.
        self._mnoise_white = max(float(cfg.target_noise_white), 0.0)
        self._mnoise_ar1_sigma = max(float(cfg.target_noise_ar1_sigma), 0.0)
        self._mnoise_ar1_rho = min(max(float(cfg.target_noise_ar1_rho), 0.0), 0.9999)
        if self._mnoise_ar1_sigma > 0.0:
            self._mnoise_ar1_state = torch.zeros(self.num_envs, 3, device=self.device)
        self._drop_prob = max(float(cfg.target_dropout_prob), 0.0)
        self._post_strike_drop_steps = max(int(round(float(cfg.target_post_strike_dropout_s) * 50.0)), 0)
        self._bias_per_swing = max(float(cfg.target_bias_per_swing), 0.0)
        self._a1v2_active = self._drop_prob > 0.0 or self._post_strike_drop_steps > 0 or self._bias_per_swing > 0.0
        if self._a1v2_active:
            self._swing_bias = torch.zeros(self.num_envs, 3, device=self.device)
            self._drop_cd = torch.zeros(self.num_envs, dtype=torch.long, device=self.device)
            self._prev_pre_strike = torch.ones(self.num_envs, dtype=torch.bool, device=self.device)
            self._held_pos = torch.zeros(self.num_envs, 3, device=self.device)
            self._held_vel = torch.zeros(self.num_envs, 3, device=self.device)
            # A planner command is one atomic message.  A dropped frame must therefore hold the
            # face command and side selector together with position/velocity; holding only the
            # first two used to expose question N+1's normal/sign next to question N's target.
            self._held_normal = torch.zeros(self.num_envs, 3, device=self.device)
            self._held_sign = torch.ones(self.num_envs, device=self.device)
            if self._atomic_tts_active:
                self._held_tts = torch.zeros(self.num_envs, device=self.device)
            if self.planner_revision_enabled:
                self._held_planner_epoch = torch.zeros(
                    self.num_envs, dtype=torch.long, device=self.device
                )
                self._held_planner_task = torch.zeros(
                    self.num_envs, dtype=torch.long, device=self.device
                )
                self._held_planner_revision = torch.full(
                    (self.num_envs,), -1, dtype=torch.long, device=self.device
                )
                self._held_planner_last_precontact = torch.zeros(
                    self.num_envs, dtype=torch.bool, device=self.device
                )
        # The actor view is materialized (separate tensors) whenever latency OR jitter is on;
        # otherwise the delayed_* attributes ARE the live tensors (which are only ever index-assigned
        # after __init__, so the alias stays valid for the whole run).
        self._actor_view_active = (
            self.planner_revision_enabled
            or
            self._delay_steps > 0 or self._jitter_pos > 0.0 or self._jitter_vel > 0.0
            or self._mnoise_white > 0.0 or self._mnoise_ar1_sigma > 0.0
            or float(cfg.target_dropout_prob) > 0.0
            or float(cfg.target_post_strike_dropout_s) > 0.0
            or float(cfg.target_bias_per_swing) > 0.0
            or self._atomic_tts_active
        )
        if self._actor_ring_steps > 0:
            # Ring buffers (length delay+1) over the ACTOR-VISIBLE target quantities: the slot
            # written this step is read back `delay` pushes later (see _push_actor_target).
            # 耦合传输模式下 _actor_ring_steps==0:观测环不建,延迟由提交侧在途环承担。
            _L = self._actor_ring_steps + 1
            self._delay_buf_pos = torch.zeros(_L, self.num_envs, 3, device=self.device)
            self._delay_buf_vel = torch.zeros(_L, self.num_envs, 3, device=self.device)
            self._delay_buf_normal = torch.zeros(_L, self.num_envs, 3, device=self.device)
            self._delay_buf_sign = torch.ones(_L, self.num_envs, device=self.device)
            if self._atomic_tts_active:
                self._delay_buf_tts = torch.zeros(_L, self.num_envs, device=self.device)
            if self.planner_revision_enabled:
                self._delay_buf_planner_epoch = torch.zeros(
                    _L, self.num_envs, dtype=torch.long, device=self.device
                )
                self._delay_buf_planner_task = torch.zeros(
                    _L, self.num_envs, dtype=torch.long, device=self.device
                )
                self._delay_buf_planner_revision = torch.full(
                    (_L, self.num_envs), -1, dtype=torch.long, device=self.device
                )
                self._delay_buf_planner_last_precontact = torch.zeros(
                    _L, self.num_envs, dtype=torch.bool, device=self.device
                )
            self._delay_ptr = 0
        if self._actor_view_active:
            self.delayed_racket_target_pos_w = self.racket_target_pos_w.clone()
            self.delayed_racket_target_vel_w = self.racket_target_vel_w.clone()
            self.delayed_target_normal_cmd = self.target_normal_cmd.clone()
            self.delayed_swing_sign = self.swing_sign.clone()
            if self._atomic_tts_active:
                self.delayed_time_to_strike = self.time_to_strike.clone()
        else:
            # Flags off: zero-overhead aliases of the live tensors (byte-identical baseline).
            self.delayed_racket_target_pos_w = self.racket_target_pos_w
            self.delayed_racket_target_vel_w = self.racket_target_vel_w
            self.delayed_target_normal_cmd = self.target_normal_cmd
            self.delayed_swing_sign = self.swing_sign
        # A1 metrics: per-step per-env redraw indicator (wandb reset-mean = per-step mid-swing
        # refinement fraction) + the constant delay-in-effect broadcast (refreshed every step in
        # _update_metrics because CommandTerm.reset() zeros metric entries of resetting envs).
        self.metrics["midswing_resample_count"] = torch.zeros(self.num_envs, device=self.device)
        self.metrics["target_delay_steps_in_effect"] = torch.full(
            (self.num_envs,), float(self._delay_steps), device=self.device
        )
        self.metrics["actor_time_to_strike_s"] = torch.zeros(self.num_envs, device=self.device)

        # Strike timing / gating.
        self.pre_strike = torch.ones(self.num_envs, dtype=torch.bool, device=self.device)
        self.strike_window = torch.zeros(self.num_envs, dtype=torch.bool, device=self.device)
        # Wall/control-time recovery clock.  It cannot be reconstructed from the reference phase
        # under the planner governor because playback speed is time-varying.
        self._post_strike_elapsed_s = torch.zeros(
            self.num_envs, dtype=torch.float32, device=self.device
        )
        self._post_strike_elapsed_valid = torch.zeros(
            self.num_envs, dtype=torch.bool, device=self.device
        )
        self._post_strike_elapsed_last_step = -1
        # One-shot host-side handoff between CommandTerm's ordered metrics/update passes.
        # ``common_step_counter`` is an ordinary Python int, so this cache never reads a CUDA
        # scalar or introduces a device synchronization.  It is deliberately NOT a general
        # memoization of Motion timing: only the immediately following _update_command may consume
        # the metrics result.  Direct update calls, reset/resample, a changed token, and every
        # direct _compute_strike_timing call all recompute.
        self._strike_timing_metrics_step_token: int | None = None
        self._strike_timing_metrics_handoff_pending = False
        # 1c split windows: refreshed alongside strike_window in _compute_strike_timing. With the
        # cfg fields at their None defaults these are recomputed from strike_window_s each step,
        # i.e. numerically identical to strike_window (byte-identical default path).
        self.strike_window_pos = torch.zeros(self.num_envs, dtype=torch.bool, device=self.device)
        self.strike_window_wide = torch.zeros(self.num_envs, dtype=torch.bool, device=self.device)

        # --- R-b envelope-violation accounting (cfg.track_envelope_violation; default OFF) --------
        # Counts the tracking-envelope violations that no longer terminate under
        # terminations.envelope_as_penalty: tracking_loss_rate = violation RISING EDGES / swing
        # starts (same EMA timescale/denominator as pre_strike_fall_rate, per-clip variants too) +
        # envelope_violated_frac = per-step violation fraction (loafing/挂机 monitor). Cross-arm
        # bookkeeping: old-arm pre_strike_fall ≈ new-arm (fall + tracking_loss).
        self._envelope_track = bool(getattr(cfg, "track_envelope_violation", False))
        if self._envelope_track:
            self._envelope_body_idx: list[int] | None = None  # resolved lazily vs motion.cfg.body_names
            self._prev_envelope_viol = torch.zeros(self.num_envs, dtype=torch.bool, device=self.device)
            self._tracking_loss_acc = 0.0
            self._tracking_loss_acc_c = {c: 0.0 for c in self._clip_names}
            self.metrics["envelope_violated_frac"] = torch.zeros(self.num_envs, device=self.device)
            self.metrics["tracking_loss_rate"] = torch.zeros(self.num_envs, device=self.device)
            for _cname in self._clip_names.values():
                self.metrics[f"tracking_loss_rate_{_cname}"] = torch.zeros(self.num_envs, device=self.device)

        # Episode-wide tracking errors (instantaneous; averaged over terminating envs at reset).
        self.metrics["racket_pos_error"] = torch.zeros(self.num_envs, device=self.device)
        self.metrics["racket_vel_error"] = torch.zeros(self.num_envs, device=self.device)
        self.metrics["adaptive_sigma_pos"] = torch.full((self.num_envs,), float(cfg.sigma_pos_max), device=self.device)
        self.metrics["adaptive_sigma_vel"] = torch.full((self.num_envs,), float(cfg.sigma_vel_max), device=self.device)
        # 第三通道曲线只在旗标开启时注册:默认跑的 wandb 指标键集合逐字节不变。
        if getattr(cfg, "adaptive_sigma_normal", False):
            self.metrics["adaptive_sigma_normal"] = torch.full(
                (self.num_envs,), float(cfg.sigma_normal_max), device=self.device
            )
        if (
            _adaptive_sigma_source(cfg)
            == _ADAPTIVE_SIGMA_SOURCE_STAGE1_CLIP_SITE
        ):
            for channel in ("pos", "vel", "normal"):
                self.metrics[f"adaptive_sigma_{channel}_full_phase_count"] = torch.zeros(
                    self.num_envs, device=self.device
                )
                self.metrics[f"adaptive_sigma_{channel}_full_phase_error_rms"] = torch.zeros(
                    self.num_envs, device=self.device
                )
        self.metrics["racket_normal_error_deg"] = torch.zeros(self.num_envs, device=self.device)
        self.metrics["base_pos_error"] = torch.zeros(self.num_envs, device=self.device)
        # How far the (coupled) base target sits from spawn — i.e. how much repositioning is commanded.
        # ~0 when base_couple_blend=0; grows with the coupling toward far racket targets.
        self.metrics["base_target_offset_norm"] = torch.zeros(self.num_envs, device=self.device)
        # Strike-window metrics: hold the value from the MOST RECENT strike — these map directly to
        # the acceptance criteria (racket pos < 7.5 cm, vel < 0.5 m/s, normal < 15 deg AT strike) and
        # are the real "is the policy learning to hit" signal (the episode-wide ones above are diluted
        # by the long non-strike portion of each swing).
        self.metrics["racket_pos_error_at_strike"] = torch.zeros(self.num_envs, device=self.device)
        self.metrics["racket_vel_error_at_strike"] = torch.zeros(self.num_envs, device=self.device)
        self.metrics["racket_normal_error_deg_at_strike"] = torch.zeros(self.num_envs, device=self.device)
        self.metrics["strike_success"] = torch.zeros(self.num_envs, device=self.device)
        # Exact-strike metrics: sampled only on the nearest control frame to the configured strike
        # step. These avoid the "within-window" dilution from the +/- strike reward window.
        self.metrics["racket_pos_error_exact_strike"] = torch.zeros(self.num_envs, device=self.device)
        self.metrics["racket_vel_error_exact_strike"] = torch.zeros(self.num_envs, device=self.device)
        self.metrics["racket_normal_error_deg_exact_strike"] = torch.zeros(self.num_envs, device=self.device)
        self.metrics["strike_composite_success_exact"] = torch.zeros(self.num_envs, device=self.device)
        # Per-axis position error AT the exact strike frame (which axis is the miss?).
        self.metrics["racket_pos_error_x_exact_strike"] = torch.zeros(self.num_envs, device=self.device)
        self.metrics["racket_pos_error_y_exact_strike"] = torch.zeros(self.num_envs, device=self.device)
        self.metrics["racket_pos_error_z_exact_strike"] = torch.zeros(self.num_envs, device=self.device)
        self.metrics["exact_strike_hit_rate"] = torch.zeros(self.num_envs, device=self.device)
        # Conditional exact-strike pass rates (broadcast scalar; the trustworthy success signal). Each is
        # the fraction of exact-strike samples that clear that acceptance threshold, undiluted by the
        # non-strike steps that wrecked the old held metric. strike_composite_success_exact requires all
        # three (pos & vel & normal) and drives the success-gated perturbation curriculum.
        self.metrics["strike_pos_pass_exact"] = torch.zeros(self.num_envs, device=self.device)
        self.metrics["strike_vel_pass_exact"] = torch.zeros(self.num_envs, device=self.device)
        self.metrics["strike_normal_pass_exact"] = torch.zeros(self.num_envs, device=self.device)
        # Position-accuracy buckets + error distribution on the exact-strike sample (comparable w/ composite).
        self.metrics["exact_strike_pos_success_5cm"] = torch.zeros(self.num_envs, device=self.device)
        self.metrics["exact_strike_pos_success_10cm"] = torch.zeros(self.num_envs, device=self.device)
        self.metrics["exact_strike_pos_err_mean"] = torch.zeros(self.num_envs, device=self.device)
        self.metrics["exact_strike_pos_err_p90"] = torch.zeros(self.num_envs, device=self.device)
        # The physical exact-strike count remains the swing-completion denominator.  These separate
        # target denominators make an ablated column explicitly "not measured" (count 0) instead of
        # reporting it as a failed target.  Composite is eligible only for a complete 111 target.
        for _channel in ("pos", "vel", "normal", "composite"):
            self.metrics[
                f"strike_{_channel}_target_eligible_sample_count_decayed"
            ] = torch.zeros(self.num_envs, device=self.device)
        # Per-clip (forehand/backhand) versions of the exact-strike pass rates + errors (multiseg only;
        # stay 0 for a single-clip run). Updated in _update_metrics.
        for _cname in self._clip_names.values():
            for _key in (
                "strike_pos_pass_exact", "strike_vel_pass_exact", "strike_normal_pass_exact",
                "strike_composite_success_exact", "racket_pos_error_exact_strike",
                "racket_vel_error_exact_strike", "racket_normal_error_deg_exact_strike",
            ):
                self.metrics[f"{_key}_{_cname}"] = torch.zeros(self.num_envs, device=self.device)
            for _channel in ("pos", "vel", "normal", "composite"):
                self.metrics[
                    f"strike_{_channel}_target_eligible_sample_count_decayed_{_cname}"
                ] = torch.zeros(self.num_envs, device=self.device)
        self.metrics["exact_strike_sample_count_decayed"] = torch.zeros(self.num_envs, device=self.device)
        # Tier-1 virtual-ball outcome rates (broadcast sample-weighted EMAs, exact-strike denominator
        # for hit rate; hit (captured) denominator for the outcome rates). Logged when the virtual
        # ball is enabled for rewards (virtual_ball) OR as pure metrics (vb_metrics_only).
        # virtual_return_rate is the PRIMARY in-training curve (franco 2026-07-06): legal returns
        # per exact-strike sample (上台率); virtual_hit_rate (击球率) is the auxiliary;
        # strike_composite (三合格) is a diagnostic only. Canonical bookkeeping stays MuJoCo.
        if cfg.virtual_ball or cfg.vb_metrics_only:
            for _vk in (
                "virtual_return_rate", "virtual_return_rate_rally",
                "virtual_hit_rate", "virtual_net_clear_rate", "virtual_land_valid_rate",
                "virtual_land_inbounds_rate", "virtual_land_err_m", "virtual_topspin_revs",
                "virtual_approach_speed",
            ):
                self.metrics[_vk] = torch.zeros(self.num_envs, device=self.device)
            # Per-clip keys from the DECLARED clip names (default = forehand/backhand, so the
            # registered key set is byte-identical for every existing arm). The writers
            # (_vb_evaluate / _rally_report / legacy rally) iterate self._clip_names, so a
            # whole-library clip list (chingmu101, 73 uids) needs its keys registered here too.
            for _cname in self._clip_names.values():
                for _vk in ("virtual_return_rate", "virtual_hit_rate", "virtual_return_rate_rally"):
                    self.metrics[f"{_vk}_{_cname}"] = torch.zeros(self.num_envs, device=self.device)
            # Transition-period *_legacy rally curves: the OLD mixed-ledger readout (can spike >1
            # under synchronized reset queues — see the rally block in __init__) kept alongside the
            # fixed virtual_return_rate_rally* for new/old comparison. Drop by turning the cfg off.
            if cfg.rally_legacy_metrics:
                self.metrics["virtual_return_rate_rally_legacy"] = torch.zeros(
                    self.num_envs, device=self.device)
                for _cname in self._clip_names.values():
                    self.metrics[f"virtual_return_rate_rally_{_cname}_legacy"] = torch.zeros(
                        self.num_envs, device=self.device)
        # UNCONDITIONAL swing accounting (Phase A): completion_rate = exact-strike arrivals / swing
        # STARTS (falls count against it, unlike the conditional composite above); fall rate before
        # the strike frame. Broadcast scalars like the pass rates.
        self.metrics["swing_completion_rate"] = torch.zeros(self.num_envs, device=self.device)
        for _cname in self._clip_names.values():
            self.metrics[f"swing_completion_rate_{_cname}"] = torch.zeros(self.num_envs, device=self.device)
        self.metrics["pre_strike_fall_rate"] = torch.zeros(self.num_envs, device=self.device)
        # Post-strike (follow-through/recovery) falls + per-clip fall attribution: the multi-swing
        # episode's real recovery signal. pre_strike_fall_rate alone hides a policy that hits and THEN
        # falls (100% completion, 0% pre-strike falls — the actual backhand deploy failure signature).
        self.metrics["post_strike_fall_rate"] = torch.zeros(self.num_envs, device=self.device)
        for _cname in self._clip_names.values():
            self.metrics[f"pre_strike_fall_rate_{_cname}"] = torch.zeros(self.num_envs, device=self.device)
            self.metrics[f"post_strike_fall_rate_{_cname}"] = torch.zeros(self.num_envs, device=self.device)
        # HER-style achieved-target replay diagnostics: fraction of resampled targets drawn from the
        # achieved buffer (EMA; ~achieved_target_mix_prob once the buffers are filled) + per-clip fill.
        self.metrics["achieved_replay_frac"] = torch.zeros(self.num_envs, device=self.device)
        for _cname in self._clip_names.values():
            self.metrics[f"achieved_buffer_fill_{_cname}"] = torch.zeros(self.num_envs, device=self.device)
        self.metrics["strike_window_hit_rate"] = torch.zeros(self.num_envs, device=self.device)
        # Base-position error while the base target is active (pre-strike), held at its last value.
        self.metrics["base_pos_error_pre_strike"] = torch.zeros(self.num_envs, device=self.device)
        # Rally drift metrics (2026-07-07): EMA-broadcast per-swing drift + per-step recovery signals.
        self.metrics["base_drift_per_swing"] = torch.zeros(self.num_envs, device=self.device)
        self.metrics["base_drift_fwd_per_swing"] = torch.zeros(self.num_envs, device=self.device)
        self.metrics["base_station_offset_at_swing_start"] = torch.zeros(self.num_envs, device=self.device)
        self.metrics["base_heading_abs_at_swing_start"] = torch.zeros(self.num_envs, device=self.device)
        self.metrics["base_heading_hold_expiry_count"] = torch.zeros(self.num_envs, device=self.device)
        self.metrics["heading_recovery_spawn_yaw"] = torch.zeros(self.num_envs, device=self.device)
        self.metrics["heading_recovery_expiry_yaw"] = torch.zeros(self.num_envs, device=self.device)
        self.metrics["heading_recovery_count"] = torch.zeros(self.num_envs, device=self.device)
        self.metrics["post_strike_base_speed_xy"] = torch.zeros(self.num_envs, device=self.device)
        self.metrics["base_dist_from_origin"] = torch.zeros(self.num_envs, device=self.device)
        # Swing-quality detail at the most recent strike: actual paddle speed, per-axis position error,
        # and success at tighter/looser thresholds (5 cm / 10 cm) for a fuller accuracy distribution.
        self.metrics["racket_speed_at_strike"] = torch.zeros(self.num_envs, device=self.device)
        self.metrics["racket_target_speed_at_strike"] = torch.zeros(self.num_envs, device=self.device)
        self.metrics["racket_pos_error_x_at_strike"] = torch.zeros(self.num_envs, device=self.device)
        self.metrics["racket_pos_error_y_at_strike"] = torch.zeros(self.num_envs, device=self.device)
        self.metrics["racket_pos_error_z_at_strike"] = torch.zeros(self.num_envs, device=self.device)
        # DEPRECATED semantics: these hold the value at the WINDOW-EXIT frame (racket ~0.26 m past target),
        # NOT at contact, and use the diluting reset-mean denominator. Renamed so they stop reading as
        # "success". Use exact_strike_pos_success_5cm/10cm above for the real contact-frame accuracy.
        self.metrics["strike_success_5cm_window_exit"] = torch.zeros(self.num_envs, device=self.device)
        self.metrics["strike_success_10cm_window_exit"] = torch.zeros(self.num_envs, device=self.device)
        # Robot-health diagnostics (episode-wide, instantaneous) — logged here because this term already
        # holds ``self.robot``. Useful for sim2real: standing height, peak joint speed, actuator effort.
        self.metrics["base_height"] = torch.zeros(self.num_envs, device=self.device)
        self.metrics["base_upright"] = torch.zeros(self.num_envs, device=self.device)
        # Stability diagnostics (instability shows up here BEFORE a termination): absolute base roll/pitch
        # (deg; 0 = level — base_upright only gives the combined tilt), and foot contact + slip (a planted
        # foot should be ~still; horizontal foot speed while in contact = slip = the robot shuffling/sliding).
        self.metrics["base_roll_deg"] = torch.zeros(self.num_envs, device=self.device)
        self.metrics["base_pitch_deg"] = torch.zeros(self.num_envs, device=self.device)
        self.metrics["foot_contact_frac"] = torch.zeros(self.num_envs, device=self.device)
        self.metrics["foot_slip_speed"] = torch.zeros(self.num_envs, device=self.device)
        # Foot-slip magnitude (sum over feet of horizontal speed WHILE in contact) used by the
        # pre_strike_foot_slip reward. Recomputed each step in _update_metrics; stays 0 if the feet /
        # contact sensor cannot be resolved, so the reward is a safe no-op in that case.
        self.foot_slip_in_contact = torch.zeros(self.num_envs, device=self.device)
        # Fraction of feet in contact (mean over the 2 feet): 1.0 = both planted, 0.5 = one foot
        # unloaded, 0.0 = airborne. Clean attribute for the feet_contact stance reward (real_sensor
        # variant). Same value as metrics["foot_contact_frac"]; 0 (safe) if the sensor cannot resolve.
        self.feet_contact_frac = torch.zeros(self.num_envs, device=self.device)
        # ---- footwork-to-strike signals (base-FREE; reward/metric only, NEVER in the observation) ----
        # racket_target_distance = ||racket_FK - racket_target|| (frame-invariant, no base position).
        # racket_progress = prev_distance - current_distance (>0 = the WHOLE body moved the racket closer
        # to the target). This dense progress term is what drives footwork WITHOUT a base target.
        z = lambda: torch.zeros(self.num_envs, device=self.device)  # noqa: E731
        self.racket_target_distance = z()
        self.racket_progress = z()
        self._prev_racket_dist = z()
        self._progress_reset_mask = torch.ones(self.num_envs, dtype=torch.bool, device=self.device)
        # Diagnostic-only first-tick latch.  A true reset or natural clip wrap rearms its env;
        # the first subsequent strike-window tick books one racket-target distance and disarms it.
        # The latch deliberately survives PPO ledger consumption and is exact-resume state, so a
        # rollout-window/checkpoint boundary cannot count the same swing twice.
        if self._action_ball_enabled or self._action_ball_full_mdp_enabled:
            self._strike_window_entry_armed = torch.ones(
                self.num_envs, dtype=torch.bool, device=self.device
            )
            self._strike_window_entry_distance_bin_edges_m = torch.tensor(
                _STRIKE_WINDOW_ENTRY_DISTANCE_BIN_EDGES_M,
                dtype=torch.float32,
                device=self.device,
            )
        self.foot_slip_sq = z()  # sum_feet contact * ||foot_xy_vel||^2
        self.foot_vel_sq = z()  # sum_feet ||foot_vel||^2 (excessive/violent foot motion)
        self.foot_drag = z()  # sum_feet ||foot_xy_vel|| while the foot is LOW (near ground -> dragging)
        self.arm_overreach_frac = z()  # fraction of ARM joints within 10% of a position limit
        self.waist_twist = z()  # |waist_yaw - default| + |waist_roll - default| (anti twist-instead-of-step)
        self.proj_grav_xy = z()  # ||projected_gravity_xy|| = base tilt (strike-window stability)
        self.base_ang_vel_xy_norm = z()  # ||base_ang_vel_xy|| (strike-window stability)
        self.vertical_speed = z()  # |base_lin_vel_z| (vertical bob)
        self._drag_height = 0.10  # m: foot below this counts as "near ground" for the drag penalty
        self.metrics["joint_vel_abs_max"] = torch.zeros(self.num_envs, device=self.device)
        self.metrics["time_to_strike_s"] = torch.zeros(self.num_envs, device=self.device)
        self.metrics["pre_strike_flag"] = torch.zeros(self.num_envs, device=self.device)
        # P2.4 watch-metric: planar |v_base| during the approach (the base_decel_tracking reward's
        # subject). 0 outside pre_strike -> the reset-mean dilutes like the other *_prestrike metrics.
        self.metrics["base_speed_xy_prestrike"] = torch.zeros(self.num_envs, device=self.device)
        # Curriculum perturbation scale (reference_perturbed mode): 0 at start ramping to 1; lets you
        # watch the reachable target ball widen in wandb. Stays 0 in "uniform" mode.
        self.metrics["ref_perturb_scale"] = torch.zeros(self.num_envs, device=self.device)
        self._has_jpos_limits = hasattr(self.robot.data, "soft_joint_pos_limits") or hasattr(
            self.robot.data, "joint_pos_limits"
        )
        if self._has_jpos_limits:
            self.metrics["joint_pos_near_limit_frac"] = torch.zeros(self.num_envs, device=self.device)
        self._has_torque = hasattr(self.robot.data, "applied_torque")
        if self._has_torque:
            self.metrics["joint_torque_abs_mean"] = torch.zeros(self.num_envs, device=self.device)
            self.metrics["joint_torque_abs_max"] = torch.zeros(self.num_envs, device=self.device)
        # Policy action magnitude (saturation check for sim2real).
        self.metrics["action_abs_mean"] = torch.zeros(self.num_envs, device=self.device)
        self.metrics["action_abs_max"] = torch.zeros(self.num_envs, device=self.device)
        self.metrics["action_delta_abs_mean"] = torch.zeros(self.num_envs, device=self.device)
        self.metrics["action_delta_abs_max"] = torch.zeros(self.num_envs, device=self.device)
        for axis in ("x", "y"):
            self.metrics[f"base_pos_{axis}"] = torch.zeros(self.num_envs, device=self.device)
            self.metrics[f"base_pos_error_{axis}"] = torch.zeros(self.num_envs, device=self.device)
        for axis in ("x", "y", "z"):
            self.metrics[f"racket_pos_error_{axis}"] = torch.zeros(self.num_envs, device=self.device)
            self.metrics[f"racket_vel_error_{axis}"] = torch.zeros(self.num_envs, device=self.device)

        # --- SHADOW physical ball (+ optional table): flag-gated, METRICS-ONLY measurement --------
        # A real PhysX ball per env that flies the question in, takes the SAME contact model as the
        # reward path at a captured strike, and lands under engine integration — an online
        # engine-vs-analytic cross-check of the virtual-ball prediction. Zero coupling to rewards/
        # observations/bank-target logic (see shadow_ball.py's module docstring for the honesty
        # notes: linear cosmetic pre-strike path, no bounce-before-strike, engine-fidelity baseline
        # from scripts/isaac_ball_inloop_check.py). Default OFF = byte-identical (no driver, no
        # scene entity, no physics callback, no metrics keys).
        self._shadow = None
        # Mid-swing target refinement redraws the question without notifying a ball already in
        # flight.  Combining the two would make the truth instrument measure a target jump rather
        # than engine delivery, so fail before constructing either driver.
        if float(getattr(cfg, "midswing_resample_prob", 0.0)) > 0.0 and (
            cfg.shadow_ball or cfg.physical_ball
        ):
            raise ValueError(
                "RacketTargetCommandCfg.midswing_resample_prob > 0 cannot be combined with "
                "shadow_ball/physical_ball: the served ball would realize the old question."
            )
        if cfg.shadow_ball:
            # The shadow ball mirrors the virtual-ball question stream (per-swing incoming
            # velocity/spin + the capture gate live in the vb machinery) — without it there is
            # nothing to fly in and nothing to cross-check against. Loud error, not silent no-op.
            if not cfg.virtual_ball:
                raise ValueError(
                    "RacketTargetCommandCfg.shadow_ball=True requires virtual_ball=True: the "
                    "shadow ball flies the vb-sampled incoming ball and cross-checks the vb "
                    "landing prediction. Enable the virtual-ball task variant or drop shadow_ball."
                )
            from whole_body_tracking.tasks.tracking.mdp.shadow_ball import ShadowBallDriver

            self._shadow = ShadowBallDriver(self, env)

        # --- PHYSICAL ball + table (Phase A truth instrument): flag-gated, METRICS-ONLY ------------
        # A real PhysX ball per env + a real static table collider: each swing's question-bank
        # incoming ball is realized physically (reverse-integrated venue-model launch so it arrives
        # at the question contact point with the question incoming velocity exactly at the strike
        # frame), flies under the per-substep venue aero wrench, takes the CODE-DRIVEN fitted table
        # bounce, and passes THROUGH the robot (collider off — the fitted racket impulse is Phase B).
        # Zero coupling to rewards/observations/bank-target logic (see physical_ball.py docstring).
        # Default OFF = byte-identical (no manager, no scene entity, no physics callback, no metrics
        # keys, no RNG consumption — the serve is deterministic from the question).
        self._physical = None
        if not cfg.physical_ball and (
            getattr(cfg, "physical_ball_impulse", False)
            or int(getattr(cfg, "physical_ball_substep", 1)) != 1
        ):
            raise ValueError(
                "RacketTargetCommandCfg.physical_ball_impulse / physical_ball_substep require "
                "physical_ball=True; Phase B rides on the truth instrument."
            )
        if cfg.physical_ball:
            # The physical ball realizes the virtual-ball question stream (per-swing incoming
            # velocity/spin live in the vb machinery) — without it there is nothing to serve.
            if not cfg.virtual_ball:
                raise ValueError(
                    "RacketTargetCommandCfg.physical_ball=True requires virtual_ball=True: the "
                    "physical ball serves the vb-sampled incoming ball (contact point + incoming "
                    "velocity + spin). Enable the virtual-ball task variant or drop physical_ball."
                )
            from whole_body_tracking.tasks.tracking.mdp.physical_ball import PhysicalBallManager

            self._physical = PhysicalBallManager(self, env)

        # --- DEBUG: swing-through sign check + raw/gated reward kernels (cfg.debug_reward_logging) ---
        # err_minus uses the CURRENT (correct) swing-through form target - vel*t_to_strike; err_plus uses
        # the FLIPPED form target + vel*t_to_strike. In-window we expect err_minus < err_plus (sign OK) and
        # at the exact strike (t_to_strike~0) the two collapse together. raw/gated are written by the reward
        # terms in hope_rewards.py. All held over the relevant mask so the reset-mean is the in-window value.
        if self.cfg.debug_reward_logging:
            for _k in (
                "dbg_err_minus_win", "dbg_err_plus_win", "dbg_err_minus_exact", "dbg_err_plus_exact",
                "dbg_racket_pos_raw", "dbg_racket_pos_gated",
                "dbg_racket_vel_raw", "dbg_racket_vel_gated",
                "dbg_racket_normal_raw", "dbg_racket_normal_gated",
                "dbg_base_raw", "dbg_base_gated",
            ):
                self.metrics[_k] = torch.zeros(self.num_envs, device=self.device)

        if self._task_first_enabled:
            self._initialize_task_first_runtime()
        elif self._action_ball_enabled:
            # CommandManager constructs every term before assigning itself to
            # ``env.command_manager``.  ActionBall needs the already-built
            # motion term, so its cross-term binding must wait until the first
            # post-construction reset/update (or hard-contract query).
            self._action_ball_runtime_initialized = False
            self._action_ball_runtime_initializing = False
        elif self._action_ball_full_mdp_enabled:
            # No legacy manifest, sampler, host receipt graph, analytic ball,
            # portable R05 owner, or ActionBall exact-resume envelope is
            # constructed here.  The top owner binds the fresh device leaf
            # after every manager-owned tensor already exists.
            self._action_ball_runtime_initialized = False
            self._action_ball_runtime_initializing = False

    # ------------------------------------------------------------------ #
    # CommandTerm API
    # ------------------------------------------------------------------ #
    @property
    def command(self) -> torch.Tensor:
        """Raw desired-target vector (world frame): [pos(3), vel(3), normal(3), t_left(1), base_xy(2), swing(1)]."""
        return torch.cat(
            [
                self.racket_target_pos_w,
                self.racket_target_vel_w,
                self.racket_target_normal_w,
                self.time_to_strike.unsqueeze(-1),
                self.base_target_pos_w,
                self.swing_sign.unsqueeze(-1),
            ],
            dim=-1,
        )

    @property
    def base_pos_w(self) -> torch.Tensor:
        return self.robot.data.root_pos_w

    @property
    def base_quat_w(self) -> torch.Tensor:
        return self.robot.data.root_quat_w

    def _ensure_action_ball_runtime_initialized(self) -> None:
        if not self._action_ball_enabled or self._action_ball_runtime_initialized:
            return
        if self._action_ball_runtime_initializing:
            raise RuntimeError("re-entrant action-ball runtime initialization")
        if not hasattr(self._env, "command_manager"):
            raise RuntimeError(
                "action-ball runtime requested before CommandManager construction completed"
            )
        self._action_ball_runtime_initializing = True
        try:
            self._initialize_action_ball_runtime()
        except BaseException:
            raise
        else:
            self._action_ball_runtime_initialized = True
            try:
                self._motion().validate_action_ball_task_authority_binding()
            except BaseException:
                self._action_ball_runtime_initialized = False
                raise
        finally:
            self._action_ball_runtime_initializing = False

    def _motion(self) -> MotionCommand:
        if self._motion_term is None:
            self._motion_term = self._env.command_manager.get_term(self.cfg.motion_command_name)
        if (
            getattr(self._motion_term, "event_timing_enabled", False)
            and not self._event_timing_bound
            and hasattr(self, "_question_bank")
        ):
            self._bind_event_timing_contract()
        return self._motion_term

    @staticmethod
    def _task_first_file_sha256(path: Path) -> str:
        digest = hashlib.sha256()
        with path.open("rb") as stream:
            for chunk in iter(lambda: stream.read(1024 * 1024), b""):
                digest.update(chunk)
        return digest.hexdigest()

    @staticmethod
    def _task_first_repo_root(manifest_path: Path) -> Path:
        """Resolve the repository authority without trusting process cwd alone."""

        starts = (manifest_path.resolve().parent, Path(__file__).resolve().parent, Path.cwd().resolve())
        candidates = []
        for start in starts:
            for parent in (start, *start.parents):
                if (
                    (parent / "docs" / "START_HERE.md").is_file()
                    and (parent / "hope_training").is_dir()
                ):
                    candidates.append(parent.resolve())
                    break
        if not candidates:
            raise RuntimeError(
                "task-first runtime cannot locate the repository root containing "
                "docs/START_HERE.md and hope_training"
            )
        root = candidates[0]
        if any(candidate != root for candidate in candidates):
            raise RuntimeError(
                f"task-first runtime resolved conflicting repository roots: {candidates}"
            )
        return root

    def _assert_task_first_translation_invariant_imitation(self) -> None:
        """Ensure station shifts do not fight an absolute root-position imitation reward."""

        env_cfg = getattr(self._env, "cfg", None)
        rewards_cfg = getattr(env_cfg, "rewards", None)
        if rewards_cfg is None:
            raise RuntimeError(
                "task-first cannot verify translation-invariant imitation: env.cfg.rewards is absent"
            )
        if getattr(rewards_cfg, "motion_global_anchor_pos", None) is not None:
            raise ValueError(
                "task-first station_center_shift_xy_m requires "
                "rewards.motion_global_anchor_pos=None. Absolute reference-root position would pin "
                "the robot at the unshifted motion while the racket/base task moves the whole "
                "action. Body-shape imitation may remain enabled because MotionCommand anchors its "
                "relative body target on the live robot XY."
            )

    def _initialize_task_first_runtime(self) -> None:
        """Bind one authorized manifest to the exact live arbitrary-N motion library."""

        from whole_body_tracking.tasks.tracking.mdp.task_first_curriculum import (
            AXES,
            OutcomeCounts,
            TaskFirstCurriculum,
        )
        from whole_body_tracking.tasks.tracking.mdp.task_first_manifest import (
            load_task_first_manifest,
        )
        if tuple(AXES) != _TASK_FIRST_AXES:
            raise RuntimeError(
                f"task-first runtime axis order {_TASK_FIRST_AXES} disagrees with curriculum {AXES}"
            )

        loaded = load_task_first_manifest(
            self.cfg.task_first_manifest_path,
            expected_sha256=self.cfg.task_first_manifest_sha256,
            require_training_authorized=True,
        )
        manifest = loaded.manifest
        action_order = tuple(manifest.action_order)
        declared_order = tuple(
            str(name) for name in (self.cfg.clip_names_per_clip or ())
        )
        if declared_order != action_order:
            raise ValueError(
                "task-first manifest action_order must exactly equal "
                f"racket.clip_names_per_clip: manifest={action_order}, runtime={declared_order}"
            )

        motion_command = self._motion()
        motion = motion_command.motion
        runtime_files = tuple(
            Path(path).expanduser().resolve(strict=True)
            for path in getattr(motion_command, "_motion_files", ())
        )
        n_actions = len(action_order)
        if (
            len(runtime_files) != n_actions
            or int(motion.num_segments) != n_actions
            or len(self._clip_names) != n_actions
        ):
            raise ValueError(
                "task-first requires exactly one runtime motion file and one loaded segment per "
                f"action: actions={n_actions}, files={len(runtime_files)}, "
                f"segments={int(motion.num_segments)}, metric slots={len(self._clip_names)}"
            )
        repo_root = self._task_first_repo_root(loaded.source_path)
        for index, action in enumerate(manifest.actions):
            candidate = (repo_root / action.motion_path).resolve(strict=True)
            try:
                candidate.relative_to(repo_root)
            except ValueError as error:
                raise ValueError(
                    f"task-first action {action.action_id!r} motion_path resolves outside repo root"
                ) from error
            actual_sha = self._task_first_file_sha256(candidate)
            if actual_sha != action.motion_sha256:
                raise ValueError(
                    f"task-first action {action.action_id!r} motion SHA-256 mismatch: "
                    f"manifest={action.motion_sha256}, bytes={actual_sha}"
                )
            if candidate != runtime_files[index]:
                raise ValueError(
                    f"task-first action {action.action_id!r} motion path/order mismatch: "
                    f"manifest={candidate}, runtime={runtime_files[index]}"
                )
        phases_cfg = self._strike_phases_cfg(n_actions)
        phases = (
            tuple(float(value) for value in phases_cfg)
            if phases_cfg
            else tuple(float(self.cfg.strike_phase) for _ in range(n_actions))
        )
        manifest_phases = tuple(float(action.strike_phase) for action in manifest.actions)
        if phases != manifest_phases:
            raise ValueError(
                f"task-first strike phases differ: manifest={manifest_phases}, runtime={phases}"
            )
        segment_lengths = tuple(
            int(value) for value in motion.seg_len.tolist()
        )
        for index, (phase, segment_length) in enumerate(
            zip(phases, segment_lengths)
        ):
            strike_offset = round(float(phase) * (segment_length - 1))
            if (
                segment_length < 3
                or strike_offset <= 0
                or strike_offset >= segment_length - 1
            ):
                raise ValueError(
                    "task-first strike opportunity must resolve strictly inside "
                    f"its motion segment: action={action_order[index]!r}, "
                    f"phase={phase}, segment_length={segment_length}, "
                    f"strike_offset={strike_offset}"
                )
        signs_cfg = self._mount_signs_cfg(n_actions)
        signs = (
            tuple(int(value) for value in signs_cfg)
            if signs_cfg
            else tuple(int(self.cfg.mount_normal_sign) for _ in range(n_actions))
        )
        manifest_signs = tuple(int(action.mount_normal_sign) for action in manifest.actions)
        if signs != manifest_signs:
            raise ValueError(
                f"task-first mount-normal signs differ: manifest={manifest_signs}, runtime={signs}"
            )
        family_signs = tuple(
            1 if bool(value) else -1
            for value in self._clip_family_is_forehand().detach().cpu().tolist()
        )
        manifest_families = tuple(int(action.family_sign) for action in manifest.actions)
        if family_signs != manifest_families:
            raise ValueError(
                f"task-first family signs differ: manifest={manifest_families}, "
                f"runtime={family_signs}"
            )
        if not bool(getattr(motion_command.cfg, "balanced_clip_sampling", False)):
            raise ValueError(
                "task-first requires motion.balanced_clip_sampling=True so arbitrary-N actions "
                "receive balanced attempts"
            )
        balanced_seed = getattr(motion_command.cfg, "balanced_clip_sampling_seed", None)
        if type(balanced_seed) is not int or not 0 <= balanced_seed < (1 << 63):
            raise ValueError(
                "task-first requires motion.balanced_clip_sampling_seed in [0,2**63)"
            )
        if float(getattr(motion_command.cfg, "clip_switch_prob", 0.0)) != 0.0:
            raise ValueError(
                "task-first forbids motion.clip_switch_prob: changing action inside one "
                "latched task would corrupt prior-action outcome ownership"
            )
        speed_range = tuple(
            float(value)
            for value in (getattr(motion_command.cfg, "speed_scale_range", (1.0, 1.0)) or ())
        )
        speed_per_clip = getattr(motion_command.cfg, "speed_scale_per_clip", None)
        if speed_range != (1.0, 1.0) or (
            speed_per_clip is not None
            and any(float(value) != 1.0 for value in speed_per_clip)
        ):
            raise ValueError(
                "task-first v1 forbids motion retiming: speed_scale_range must be (1,1) and "
                "speed_scale_per_clip absent or all 1"
            )
        if bool(getattr(motion_command, "event_timing_enabled", False)) or bool(
            getattr(motion_command, "planner_revision_enabled", False)
        ) or str(getattr(motion_command.cfg, "event_timing_mode", "disabled")) != "disabled":
            raise ValueError(
                "task-first v1 forbids event timing and planner phase governance; task identity, "
                "t_hit and t_cycle must remain one interpretable native-motion contract"
            )
        env_cfg = getattr(self._env, "cfg", None)
        terminations_cfg = getattr(env_cfg, "terminations", None)
        if (
            not bool(getattr(env_cfg, "table_obstacle", False))
            or not str(getattr(env_cfg, "table_obstacle_prim", "") or "").strip()
            or getattr(terminations_cfg, "robot_hit_table", None) is None
        ):
            raise ValueError(
                "task-first requires the solid table obstacle and robot_hit_table termination. "
                "Otherwise table safety is structurally unobservable and unsafe_failures would "
                "report a false zero."
            )
        self._assert_task_first_translation_invariant_imitation()
        self._ensure_reference_strike_state()
        if (
            self._ref_racket_vel_w_per_clip is None
            or self._ref_racket_normal_raw_w_per_clip is None
            or self._ref_racket_pos_rel_per_clip is None
            or self._ref_base_pos_rel_per_clip is None
        ):
            raise RuntimeError("task-first reference strike-state initialization is incomplete")
        ref_speeds = torch.norm(self._ref_racket_vel_w_per_clip, dim=-1)
        for index, action in enumerate(manifest.actions):
            ref_position = self._ref_racket_pos_rel_per_clip[index]
            self._assert_contact_clears_table(
                index,
                float(ref_position[0])
                + float(action.station_center_shift_xy_m[0])
                + float(action.position_half_extent_m[0]),
                float(ref_position[2]) - float(action.position_half_extent_m[2]),
                "task-first full position envelope",
            )
            speed = float(ref_speeds[index])
            if not math.isfinite(speed) or speed <= 1.0e-6:
                raise ValueError(
                    f"task-first action {action.action_id!r} has invalid reference strike "
                    f"speed {speed}"
                )
            if float(action.speed_delta_mps) >= speed - 1.0e-6:
                raise ValueError(
                    f"task-first action {action.action_id!r} speed_delta_mps="
                    f"{action.speed_delta_mps} reaches a non-positive full lower bound around "
                    f"reference speed {speed}; reduce the declared scalar speed radius"
                )

        self._task_first_loaded_manifest = loaded
        self._task_first_manifest = manifest
        self._task_first_action_order = action_order
        self._task_first_action_uids = tuple(int(action.action_uid) for action in manifest.actions)
        self._task_first_curriculum = TaskFirstCurriculum(
            manifest_sha256=loaded.file_sha256,
            action_order=action_order,
            gate_config=manifest.gate,
        )
        self._task_first_outcome_type = OutcomeCounts
        self._task_first_window_counts = torch.zeros(
            len(_TASK_FIRST_OUTCOME_NAMES),
            n_actions,
            dtype=torch.long,
            device=self.device,
        )
        self._task_first_attempt_active = torch.zeros(
            self.num_envs, dtype=torch.bool, device=self.device
        )
        self._task_first_attempt_action = torch.full(
            (self.num_envs,), -1, dtype=torch.long, device=self.device
        )
        self._task_first_attempt_success = torch.zeros(
            self.num_envs, dtype=torch.bool, device=self.device
        )
        # A wrap ends the swing but not its safety obligation: the just-finished action owns the
        # complete post-wrap recovery hold.  Keep it out of the evidence window until that hold
        # expires; the newly sampled action becomes active only after the recovery transaction
        # commits.  This prevents a successful strike from being booked before a subsequent table
        # hit/fall and prevents that unsafe event from contaminating the next action.
        self._task_first_recovery_pending = torch.zeros(
            self.num_envs, dtype=torch.bool, device=self.device
        )
        self._task_first_recovery_action = torch.full(
            (self.num_envs,), -1, dtype=torch.long, device=self.device
        )
        self._task_first_recovery_success = torch.zeros(
            self.num_envs, dtype=torch.bool, device=self.device
        )
        self._task_first_restored_attempt_discard = torch.zeros(
            self.num_envs, dtype=torch.bool, device=self.device
        )
        self._task_first_restored_recovery_discard = torch.zeros(
            self.num_envs, dtype=torch.bool, device=self.device
        )
        self._task_first_last_rollout_step = None

        # Dynamic installation is deliberate: runner schema 3 sees explicit hooks only for
        # task-first. Legacy modes therefore retain the existing heuristic exact-resume capture
        # (achieved rings, adaptive sigmas and all historical accumulators).
        self.exact_resume_state_dict = self._task_first_exact_resume_state_dict
        self.load_exact_resume_state_dict = self._task_first_load_exact_resume_state_dict
        self.on_rollout_end = self._task_first_on_rollout_end

    def task_first_hard_contract(self) -> dict | None:
        """Return exactly the task-first contract assembled by ``scripts/train.py``."""

        if not self._task_first_enabled:
            return None
        from whole_body_tracking.tasks.tracking.mdp.task_first_manifest import (
            build_task_first_training_contract,
        )

        return build_task_first_training_contract(
            self._task_first_loaded_manifest,
            racket_cfg=self.cfg,
            motion_cfg=self._motion().cfg,
            env_cfg=self._env.cfg,
        )

    def _initialize_action_ball_runtime(self) -> None:
        """Bind the action -> ball -> fixed-action solve transaction to the live motion library."""

        from whole_body_tracking.tasks.tracking.mdp.action_ball_curriculum import (
            ARM_KEYS as CURRICULUM_ARM_KEYS,
            ARM_CATALOG_SHA256,
            ActionBallCurriculum,
            ActionProfileKey,
            ArmSchedulerConfig,
            BallOutcomeLedger,
        )
        from whole_body_tracking.tasks.tracking.mdp.action_ball_manifest import (
            load_action_ball_manifest,
        )
        from whole_body_tracking.tasks.tracking.mdp.action_ball_profile_adapter import (
            adapt_action_ball_manifest,
            build_curriculum_config,
        )
        from whole_body_tracking.tasks.tracking.mdp.action_ball_runtime import (
            ActionBinding,
            ActionBirthBroker,
            ActionDomainLevels,
            LazyActionTaskPool,
            RuntimePins,
            TASK_RECEIPT_TIMING_AUTHORITY,
        )
        from whole_body_tracking.tasks.tracking.mdp.action_ball_sampling import (
            ARM_KEYS as SAMPLER_ARM_KEYS,
            ActionBallSampler,
            DomainLevels,
            SamplingMixture,
        )
        from whole_body_tracking.tasks.tracking.mdp.continuous_questions import (
            ContinuousQuestionCfg,
        )
        from whole_body_tracking.tasks.tracking.mdp.counter_rally import (
            CounterRallyObjectiveProfile,
            VenueBallPhysics,
        )
        from whole_body_tracking.tasks.tracking.mdp.counter_rally_torch import (
            CounterRallyTorchBinding,
        )
        from whole_body_tracking.tasks.tracking.mdp import (
            racket_contact_geometry as contact_geometry,
        )
        from whole_body_tracking.tasks.tracking.mdp.stroke_prototypes_torch import (
            load_stroke_prototype_tensors,
        )
        from whole_body_tracking.tasks.tracking.action_ball_task_wait import (
            ActionBallTaskWaitHighwater,
            ActionBallTaskWaitSchedule,
        )

        _assert_action_ball_racket_site_contract(
            self.cfg,
            contact_geometry,
        )
        self._action_ball_task_receipt_timing_authority = (
            TASK_RECEIPT_TIMING_AUTHORITY
        )
        if tuple(CURRICULUM_ARM_KEYS) != tuple(SAMPLER_ARM_KEYS):
            raise RuntimeError(
                "action-ball sampler/curriculum signed-arm order drifted: "
                f"curriculum={tuple(CURRICULUM_ARM_KEYS)} "
                f"sampler={tuple(SAMPLER_ARM_KEYS)}"
            )

        manifest_path = Path(self.cfg.action_ball_manifest_path).expanduser().resolve(strict=True)
        repo_root = self._task_first_repo_root(manifest_path)
        loaded = load_action_ball_manifest(
            manifest_path,
            expected_sha256=self.cfg.action_ball_manifest_sha256,
            verify_referenced_assets=True,
            repo_root=repo_root,
            require_formal_admission=False,
        )
        manifest = loaded.manifest
        assets = loaded.referenced_assets
        if assets is None:
            raise RuntimeError("action-ball manifest load produced no referenced-asset receipt")
        action_order = tuple(manifest.action_order)
        declared_order = tuple(
            str(name) for name in (self.cfg.clip_names_per_clip or ())
        )
        if declared_order != action_order:
            raise ValueError(
                "action-ball manifest action_order must exactly equal "
                f"racket.clip_names_per_clip: manifest={action_order}, runtime={declared_order}"
            )

        motion_command = self._motion()
        motion = motion_command.motion
        n_actions = len(action_order)
        counter_rally_objective = None
        if manifest.counter_rally_objective is not None:
            if n_actions != 1:
                raise ValueError(
                    "counter-rally objective is an exact N=1 contract"
                )
            counter_rally_objective = (
                CounterRallyObjectiveProfile.from_mapping(
                    manifest.counter_rally_objective.to_mapping()
                )
            )
            if (
                counter_rally_objective.sha256
                != manifest.counter_rally_objective.sha256
            ):
                raise ValueError(
                    "counter-rally objective canonical identity drifted "
                    "between manifest admission and runtime"
                )
        runtime_files = tuple(
            Path(path).expanduser().resolve(strict=True)
            for path in getattr(motion_command, "_motion_files", ())
        )
        if (
            n_actions == 0
            or len(runtime_files) != n_actions
            or int(motion.num_segments) != n_actions
            or len(self._clip_names) != n_actions
        ):
            raise ValueError(
                "action-ball requires exactly one runtime motion segment per manifest action: "
                f"actions={n_actions}, files={len(runtime_files)}, "
                f"segments={int(motion.num_segments)}, metric_slots={len(self._clip_names)}"
            )
        for slot, (action, verified) in enumerate(zip(manifest.actions, assets.motions)):
            if (
                verified.relative_path != action.motion_path
                or verified.sha256 != action.motion_sha256
                or verified.resolved_path != runtime_files[slot]
            ):
                raise ValueError(
                    f"action-ball motion binding mismatch at slot {slot} ({action.action_id!r})"
                )

        phases_cfg = self._strike_phases_cfg(n_actions)
        phases = (
            tuple(float(value) for value in phases_cfg)
            if phases_cfg
            else tuple(float(self.cfg.strike_phase) for _ in range(n_actions))
        )
        manifest_phases = tuple(
            float(action.strike_phase) for action in manifest.actions
        )
        if phases != manifest_phases:
            raise ValueError(
                f"action-ball strike phases differ: manifest={manifest_phases}, runtime={phases}"
            )
        signs_cfg = self._mount_signs_cfg(n_actions)
        signs = (
            tuple(int(value) for value in signs_cfg)
            if signs_cfg
            else tuple(int(self.cfg.mount_normal_sign) for _ in range(n_actions))
        )
        manifest_signs = tuple(
            int(action.mount_normal_sign) for action in manifest.actions
        )
        if signs != manifest_signs:
            raise ValueError(
                "action-ball mount-normal signs differ: "
                f"manifest={manifest_signs}, runtime={signs}"
            )
        runtime_families = tuple(
            "forehand" if bool(value) else "backhand"
            for value in motion_command.clip_family_is_forehand().detach().cpu().tolist()
        )
        manifest_families = tuple(action.family for action in manifest.actions)
        if runtime_families != manifest_families:
            raise ValueError(
                "action-ball motion families differ: "
                f"manifest={manifest_families}, runtime={runtime_families}"
            )

        if not bool(getattr(motion_command.cfg, "balanced_clip_sampling", False)):
            raise ValueError(
                "action-ball requires motion.balanced_clip_sampling=True; the training action "
                "schedule is balanced capability collection, not a deployment selector"
            )
        balanced_seed = getattr(motion_command.cfg, "balanced_clip_sampling_seed", None)
        if type(balanced_seed) is not int or not 0 <= balanced_seed < (1 << 63):
            raise ValueError(
                "action-ball requires a plain motion.balanced_clip_sampling_seed in [0,2**63)"
            )
        if not bool(getattr(motion_command, "canonical_ready_mode", False)):
            raise ValueError("action-ball requires motion.canonical_ready_mode=True")
        if bool(getattr(motion_command.cfg, "wrap_teleport", False)):
            raise ValueError("action-ball requires motion.wrap_teleport=False")
        if float(getattr(motion_command.cfg, "clip_switch_prob", 0.0)) != 0.0:
            raise ValueError("action-ball forbids motion.clip_switch_prob")
        speed_range = tuple(
            float(value)
            for value in (getattr(motion_command.cfg, "speed_scale_range", (1.0, 1.0)) or ())
        )
        speed_per_clip = getattr(motion_command.cfg, "speed_scale_per_clip", None)
        if speed_range != (1.0, 1.0) or (
            speed_per_clip is not None
            and any(float(value) != 1.0 for value in speed_per_clip)
        ):
            raise ValueError(
                "action-ball forbids motion retiming; t_hit/t_cycle belong to the native clip"
            )
        legacy_time_owners = {
            "hold_steps_range": tuple(
                int(value)
                for value in getattr(
                    motion_command.cfg, "hold_steps_range", ()
                )
            ),
            "stand_start_min_hold": int(
                getattr(
                    motion_command.cfg, "stand_start_min_hold", -1
                )
            ),
            "post_swing_min_hold": int(
                getattr(
                    motion_command.cfg, "post_swing_min_hold", -1
                )
            ),
            "stagger_initial_clock": bool(
                getattr(
                    motion_command.cfg, "stagger_initial_clock", True
                )
            ),
        }
        if legacy_time_owners != {
            "hold_steps_range": (0, 0),
            "stand_start_min_hold": 0,
            "post_swing_min_hold": 0,
            "stagger_initial_clock": False,
        }:
            raise ValueError(
                "action-ball receipt timing must be the only Motion time "
                "owner; expected hold_steps_range=(0,0), "
                "stand_start_min_hold=0, post_swing_min_hold=0, and "
                "stagger_initial_clock=False, got "
                f"{legacy_time_owners}"
            )
        if (
            bool(getattr(motion_command, "event_timing_enabled", False))
            or bool(getattr(motion_command, "planner_revision_enabled", False))
            or str(getattr(motion_command.cfg, "event_timing_mode", "disabled"))
            != "disabled"
        ):
            raise ValueError(
                "action-ball forbids event timing and planner phase governance; every wrap "
                "must retain one native timing/generation contract"
            )
        env_cfg = getattr(self._env, "cfg", None)
        terminations_cfg = getattr(env_cfg, "terminations", None)
        if (
            not bool(getattr(env_cfg, "table_obstacle", False))
            or not str(getattr(env_cfg, "table_obstacle_prim", "") or "").strip()
            or getattr(terminations_cfg, "robot_hit_table", None) is None
        ):
            raise ValueError(
                "action-ball requires the solid table obstacle and robot_hit_table termination"
            )
        rewards_cfg = getattr(env_cfg, "rewards", None)
        if rewards_cfg is None or getattr(rewards_cfg, "motion_global_anchor_pos", None) is not None:
            raise ValueError(
                "action-ball base-spawn variation requires translation-invariant imitation "
                "(env.cfg.rewards.motion_global_anchor_pos=None)"
            )

        segment_lengths = tuple(int(value) for value in motion.seg_len.tolist())
        timing = []
        ready_yaw = []
        ready_quat = []
        ready_z = []
        contact_reference_z = []
        split_ready_teacher = bool(
            getattr(
                motion_command,
                "action_ball_diagnostic_split_ready_teacher",
                False,
            )
        )
        for slot, (phase, length) in enumerate(zip(phases, segment_lengths)):
            strike_offset = round(float(phase) * (length - 1))
            if length < 3 or strike_offset <= 0 or strike_offset >= length - 1:
                raise ValueError(
                    "action-ball strike opportunity must lie strictly inside its segment: "
                    f"action={action_order[slot]!r}, phase={phase}, length={length}"
                )
            timing.append(
                (
                    float(strike_offset * self._env.step_dt),
                    float((length - 1) * self._env.step_dt),
                )
            )
            start = int(motion.seg_start[slot])
            teacher_root_pos = (
                motion.body_pos_w[start, 0].detach().cpu().tolist()
            )
            if split_ready_teacher:
                root_pos = (
                    motion_command
                    ._action_ball_dynamic_ready_physical_root_pos_w_m[slot]
                    .detach()
                    .cpu()
                    .tolist()
                )
                root_quat = (
                    motion_command
                    ._action_ball_dynamic_ready_physical_root_quat_wxyz[slot]
                    .detach()
                    .cpu()
                    .tolist()
                )
            else:
                root_pos = teacher_root_pos
                root_quat = (
                    motion.body_quat_w[start, 0].detach().cpu().tolist()
                )
            norm = math.sqrt(sum(float(value) ** 2 for value in root_quat))
            if not math.isfinite(norm) or abs(norm - 1.0) > 1.0e-6:
                raise ValueError(f"action-ball ready quaternion {slot} is not unit length")
            w, x, y, z = (float(value) for value in root_quat)
            yaw = math.atan2(
                2.0 * (w * z + x * y),
                1.0 - 2.0 * (y * y + z * z),
            )
            yaw_only = (
                math.cos(0.5 * yaw),
                0.0,
                0.0,
                math.sin(0.5 * yaw),
            )
            # The birth/receipt frame is the YAW PROJECTION of the canonical ready
            # root, not the literal root quaternion Motion writes.  Real compiled
            # ready stances carry roll/pitch (measured 2026-07-28: fivebind shared
            # ready pitch ~-11.2 deg, ChingMu73 converts ~+8..12 deg), so demanding
            # a yaw-only root rejected every curated clip.  The receipt schema
            # (_assert_yaw_quaternion) binds base_quat_wxyz to R_z(base_yaw) and the
            # pinned solver rotates prototypes in that yaw frame; both are exactly
            # satisfied by the projection stored here (coordinator ruling 2026-07-28,
            # same family as the per-clip canonical-ready endpoint gate).
            ready_yaw.append(yaw)
            ready_quat.append(tuple(float(value) for value in yaw_only))
            ready_z.append(float(root_pos[2]))
            contact_reference_z.append(float(teacher_root_pos[2]))

        self._ensure_reference_strike_state()
        if int(self.cfg.mount_normal_axis) != 1:
            raise ValueError(
                "exact_face_contact_v2 requires the official racket local +Y "
                "raw-A axis (mount_normal_axis=1)"
            )
        if (
            self._ref_racket_normal_raw_w_per_clip is None
            or self._ref_racket_quat_w_per_clip is None
            or self._ref_racket_ang_vel_w_per_clip is None
        ):
            raise RuntimeError(
                "action-ball reference full racket orientation/angular state "
                "initialization is incomplete"
            )

        bundle = adapt_action_ball_manifest(
            manifest,
            ready_root_z_by_slot=tuple(float(value) for value in ready_z),
            contact_reference_root_z_by_slot=tuple(
                float(value) for value in contact_reference_z
            ),
        )
        policy_dt_s = float(self._env.step_dt)
        episode_steps = int(getattr(self._env, "max_episode_length", 0))
        if (
            not math.isfinite(policy_dt_s)
            or policy_dt_s <= 0.0
            or episode_steps <= 0
        ):
            raise ValueError(
                "action-ball requires a finite positive policy dt and episode length"
            )
        episode_length_s = float(episode_steps * policy_dt_s)
        task_wait_enabled = bool(
            getattr(self.cfg, "action_ball_task_wait_enabled", False)
        )
        if task_wait_enabled:
            configured_policy_dt_s = float(
                self.cfg.action_ball_task_wait_policy_dt_s
            )
            configured_horizon = int(
                self.cfg.action_ball_task_wait_episode_horizon_ticks
            )
            if not math.isclose(
                policy_dt_s,
                configured_policy_dt_s,
                rel_tol=0.0,
                abs_tol=1.0e-12,
            ):
                raise ValueError(
                    "ActionBall task-wait policy_dt differs from the frozen "
                    f"schedule: runtime={policy_dt_s}, "
                    f"schedule={configured_policy_dt_s}"
                )
            if episode_steps != configured_horizon:
                raise ValueError(
                    "ActionBall task-wait episode horizon differs from the "
                    f"frozen schedule: runtime={episode_steps}, "
                    f"schedule={configured_horizon}"
                )
            task_wait_schedule = ActionBallTaskWaitSchedule(
                seed=int(self.cfg.action_ball_task_wait_seed),
                min_wait_ticks=int(
                    self.cfg.action_ball_task_wait_min_wait_ticks
                ),
                max_wait_ticks=int(
                    self.cfg.action_ball_task_wait_max_wait_ticks
                ),
                episode_horizon_ticks=configured_horizon,
                required_active_ticks=int(
                    self.cfg.action_ball_task_wait_required_active_ticks
                ),
            )
            task_wait_highwater = ActionBallTaskWaitHighwater(
                task_wait_schedule
            )
        else:
            task_wait_schedule = None
            task_wait_highwater = None
        for slot, profile in enumerate(bundle.profiles):
            expected_z = ready_z[slot]
            z_contract = (
                float(profile.base_spawn_center_w_m[2]),
                float(profile.base_spawn_min_w_m[2]),
                float(profile.base_spawn_max_w_m[2]),
            )
            if any(
                not math.isclose(
                    value, expected_z, rel_tol=0.0, abs_tol=1.0e-7
                )
                for value in z_contract
            ) or any(
                float(value) != 0.0
                for value in (
                    profile.base_spawn_std_lower_initial_m[2],
                    profile.base_spawn_std_lower_max_m[2],
                    profile.base_spawn_std_upper_initial_m[2],
                    profile.base_spawn_std_upper_max_m[2],
                )
            ):
                raise ValueError(
                    "action-ball base-spawn Z must be the selected clip's exact canonical-ready "
                    f"root Z with zero variance: action={action_order[slot]!r}, "
                    f"ready_z={expected_z}, profile={z_contract}"
                )
            native_t_hit_s, native_t_cycle_s = timing[slot]
            if (
                not math.isclose(
                    profile.reference_t_hit_s,
                    native_t_hit_s,
                    rel_tol=0.0,
                    abs_tol=1.0e-7,
                )
                or not math.isclose(
                    profile.reference_t_cycle_s,
                    native_t_cycle_s,
                    rel_tol=0.0,
                    abs_tol=1.0e-7,
                )
            ):
                raise ValueError(
                    "action-ball profile reference timing differs from admitted native motion"
                )
            admitted_reference_speed = float(
                torch.linalg.norm(
                    self._ref_racket_vel_w_per_clip[slot]
                ).item()
            )
            if not math.isclose(
                profile.reference_racket_site_speed_mps,
                admitted_reference_speed,
                rel_tol=0.0,
                abs_tol=1.0e-6,
            ):
                raise ValueError(
                    "action-ball profile reference racket-site speed differs "
                    "from the admitted motion's point-consistent strike-site "
                    f"speed: action={action_order[slot]!r}, "
                    "profile="
                    f"{profile.reference_racket_site_speed_mps:.9g}, "
                    f"motion={admitted_reference_speed:.9g}"
                )
            maximum_cycle_end_s = (
                profile.time_to_contact_max_s
                + (
                    profile.reference_t_cycle_s
                    - profile.reference_t_hit_s
                )
                / profile.teacher_rate_min
                + policy_dt_s
            )
            if maximum_cycle_end_s > episode_length_s + 1.0e-12:
                raise ValueError(
                    "action-ball TTC/teacher-rate support cannot finish the scaled cycle "
                    "and deterministic close tick inside the episode horizon"
                )
            if task_wait_enabled:
                required_active_s = (
                    task_wait_schedule.required_active_ticks * policy_dt_s
                )
                if maximum_cycle_end_s > required_active_s + 1.0e-12:
                    raise ValueError(
                        "ActionBall task cannot close inside the frozen post-reveal "
                        "active budget: "
                        f"action={action_order[slot]!r}, "
                        f"required={maximum_cycle_end_s:.9g}s, "
                        f"budget={required_active_s:.9g}s"
                    )
        sampler = ActionBallSampler(
            bundle.profiles,
            seed=int(self.cfg.action_ball_seed),
            # Bind the production curriculum mixture explicitly.  Every
            # complete five-birth tape is center/interior/frontier=1/3/1
            # (20/60/20); constructor defaults are not launch authority.
            sampling_mixture=SamplingMixture(),
            contact_time_step_s=policy_dt_s,
            initial_center_single_question=(
                self.cfg.action_ball_initial_center_single_question
            ),
            diagnostic_unauthorized=(
                self.cfg.action_ball_diagnostic_unauthorized
            ),
        )
        prm = self._cq_prm()
        surface_z, net_x, net_top_z = self._cq_planes()
        counter_rally_venue_physics = None
        counter_rally_torch_binding = None
        if counter_rally_objective is not None:
            counter_rally_venue_physics = (
                VenueBallPhysics.from_venue_yaml(prm.source_path)
            )
            expected_geometry = {
                "table_near_x_env_m": float(
                    self.cfg.vb_table_near_x
                ),
                "table_length_m": float(
                    self._vb_far_x - self.cfg.vb_table_near_x
                ),
                "table_half_width_m": float(self._vb_half_w),
                "table_surface_z_env_m": float(
                    self.cfg.vb_table_surface_z
                ),
                "net_height_m": float(
                    self._vb_net_top_z
                    - self.cfg.vb_table_surface_z
                ),
                "opponent_baseline_x_env_m": float(
                    self._vb_far_x
                ),
            }
            geometry_drift = {
                name: (
                    float(getattr(counter_rally_objective, name)),
                    value,
                )
                for name, value in expected_geometry.items()
                if not math.isclose(
                    float(getattr(counter_rally_objective, name)),
                    value,
                    rel_tol=0.0,
                    abs_tol=1.0e-12,
                )
            }
            if geometry_drift:
                raise ValueError(
                    "counter-rally objective table geometry differs from "
                    f"the live scorer: {geometry_drift}"
                )
            if not math.isclose(
                counter_rally_venue_physics.ball_radius_m,
                float(self._vb_ball_r),
                rel_tol=0.0,
                abs_tol=1.0e-12,
            ):
                raise ValueError(
                    "counter-rally venue ball radius differs from live "
                    "table-tennis geometry"
                )
            counter_rally_torch_binding = (
                CounterRallyTorchBinding.from_mappings(
                    objective_profile=(
                        counter_rally_objective.to_mapping()
                    ),
                    venue_physics=(
                        counter_rally_venue_physics.to_mapping()
                    ),
                    expected_objective_profile_sha256=(
                        counter_rally_objective.sha256
                    ),
                    expected_venue_physics_sha256=(
                        counter_rally_venue_physics.sha256
                    ),
                )
            )
        physics_contract = action_ball_physics_profile_contract(
            self.cfg,
            prm,
            repo_root=repo_root,
            surface_z=surface_z,
            net_x=net_x,
            net_top_z=net_top_z,
            opponent_near_x=float(self.cfg.vb_table_near_x),
            opponent_far_x=self._vb_far_x,
            table_half_width=self._vb_half_w,
        )
        if physics_contract["sha256"] != manifest.physics_profile_sha256:
            raise ValueError(
                "action-ball physics profile SHA mismatch: "
                f"manifest={manifest.physics_profile_sha256}, "
                f"runtime={physics_contract['sha256']}"
            )
        contact_geometry_contract = {
            "payload": contact_geometry.GEOMETRY_SOURCE_PAYLOAD,
            "sha256": contact_geometry.GEOMETRY_SOURCE_SHA256,
        }
        module_dir = Path(__file__).resolve().parent
        runtime_source_names = [
            "hope_commands.py",
            "action_ball_curriculum.py",
            "action_ball_evaluation.py",
            "action_ball_manifest.py",
            "action_ball_profile_adapter.py",
            "action_ball_reference_guard.py",
            "action_ball_runtime.py",
            "action_ball_sampling.py",
            "continuous_questions.py",
            "racket_contact_geometry.py",
            "stroke_adapt_torch.py",
            "virtual_ball.py",
        ]
        if self._action_ball_reuse_exact_question:
            runtime_source_names.append("action_ball_question_cache.py")
        if counter_rally_objective is not None:
            runtime_source_names.extend(
                ("counter_rally.py", "counter_rally_torch.py")
            )
        if self._action_ball_target_source == "immutable_tape":
            runtime_source_names.append("action_ball_fixed_question_tape.py")
        elif self._action_ball_target_source == "banded_question_bank":
            runtime_source_names.extend(
                (
                    "action_ball_fixed_question_tape.py",
                    "action_ball_banded_question_bank.py",
                )
            )
        runtime_sources = {
            name: _action_ball_sha256_file(module_dir / name)
            for name in runtime_source_names
        }
        if task_wait_enabled:
            runtime_sources["../action_ball_task_wait.py"] = (
                _action_ball_sha256_file(
                    module_dir.parent / "action_ball_task_wait.py"
                )
            )
        solver_source_names = [
            "hope_commands.py",
            "continuous_questions.py",
            "racket_contact_geometry.py",
            "stroke_adapt_torch.py",
            "virtual_ball.py",
        ]
        if counter_rally_objective is not None:
            solver_source_names.extend(
                ("counter_rally.py", "counter_rally_torch.py")
            )
        solver_sources = {
            name: runtime_sources[name]
            for name in solver_source_names
        }
        # Fails closed on its own before the SHA is even compared: if a symbol in
        # a pinned solver source is neither covered nor explicitly excluded, or a
        # covered symbol started calling something unclassified, the surface
        # refuses to build.  A pin whose coverage is smaller than the semantics
        # it claims to protect is worse than no pin.
        solver_surface = solver_semantic_surface.semantic_surface_contract(
            solver_semantic_surface.source_reader_for_directory(module_dir)
        )
        solver_contract = action_ball_solver_profile_contract(
            self.cfg,
            physics_profile_sha256=physics_contract["sha256"],
            semantic_surface=solver_surface,
            source_sha256=solver_sources,
            contact_geometry_contract=contact_geometry_contract,
            net_top_z=net_top_z,
            counter_rally_objective_profile_sha256=(
                None
                if counter_rally_objective is None
                else counter_rally_objective.sha256
            ),
            counter_rally_venue_physics_sha256=(
                None
                if counter_rally_venue_physics is None
                else counter_rally_venue_physics.sha256
            ),
        )
        if solver_contract["sha256"] != manifest.solver_profile_sha256:
            surface_declaration = solver_contract["payload"]["semantic_surface"]
            raise ValueError(
                "action-ball solver profile SHA mismatch: "
                f"manifest={manifest.solver_profile_sha256}, "
                f"runtime={solver_contract['sha256']} "
                "(this profile is schema v"
                f"{_ACTION_BALL_SOLVER_PROFILE_SCHEMA_VERSION}: it binds a "
                "per-symbol semantic surface, not whole-file SHAs. Its live "
                f"surface is {surface_declaration['sha256']} over "
                f"{surface_declaration['covered_symbol_count']} symbols in "
                f"{len(surface_declaration['pinned_sources'])} sources. A "
                "manifest minted against schema v2 must be migrated with "
                "scripts/migrate_action_ball_solver_pin_to_semantic_surface.py, "
                "which records the before/after and proves question identity "
                "is unchanged.)"
            )
        # The mapping itself lives in a covered symbol on purpose: this used to be
        # an inline constructor inside this 1700-line wiring function, which the
        # semantic surface excludes, so `tol_m * 0.5` or `fixed_direction=False`
        # changed every answer while leaving the pin untouched.
        solver_cfg = action_ball_solver_cfg_from_declaration(
            self.cfg, ContinuousQuestionCfg
        )
        prototypes = load_stroke_prototype_tensors(
            assets.prototype.resolved_path,
            scope=manifest.prototype.scope,
            device=self.device,
            expected_sha256=manifest.prototype.sha256,
            expected_motion_ids=action_order,
        )
        # The manifest-anchored half of "the solver was handed the right
        # prototypes" lives in a covered symbol on purpose: these three checks
        # used to sit inline in this excluded wiring function, where deleting a
        # line -- or adding one that mutates the table afterwards -- moved no
        # pin at all.  It also seals the live tensors so the three covered solve
        # entry points can re-derive the digest and refuse on drift.
        answer_input_contract = action_ball_answer_input_contract(
            prototypes=prototypes,
            reference_normal_rows=self._ref_racket_normal_raw_w_per_clip,
            manifest_prototype_sha256=manifest.prototype.sha256,
            manifest_prototype_scope=manifest.prototype.scope,
            manifest_families=manifest_families,
            manifest_face_signs=manifest_signs,
            global_speed_budget_mps=float(self.cfg.cq_speed_budget),
        )
        proto_phases = tuple(
            float(value) for value in prototypes.strike_phase.detach().cpu().tolist()
        )
        proto_contact_frames = tuple(
            int(value)
            for value in prototypes.contact_frame.detach().cpu().tolist()
        )
        runtime_contact_frames = tuple(
            round(float(phase) * (segment_length - 1))
            for phase, segment_length in zip(phases, segment_lengths)
        )
        proto_phase_contact_frames = tuple(
            round(float(phase) * (segment_length - 1))
            for phase, segment_length in zip(
                proto_phases,
                segment_lengths,
            )
        )
        if (
            proto_contact_frames != runtime_contact_frames
            or proto_phase_contact_frames != proto_contact_frames
        ):
            raise ValueError(
                "action-ball prototype strike opportunity resolves to a "
                "different motion frame: "
                f"prototype_contact_frames={proto_contact_frames}, "
                f"prototype_phase_frames={proto_phase_contact_frames}, "
                f"runtime_contact_frames={runtime_contact_frames}, "
                f"prototype_phases={proto_phases}, runtime_phases={phases}"
            )
        profile_keys = tuple(
            ActionProfileKey(
                action_uid=uid,
                profile_sha256=profile_sha,
                mobility=manifest.mobility_mode,
            )
            for uid, profile_sha in zip(bundle.action_uids, bundle.profile_sha256)
        )
        curriculum_config = build_curriculum_config(manifest)
        scheduler_config = ArmSchedulerConfig()
        diagnostic_unauthorized = self.cfg.action_ball_diagnostic_unauthorized
        if type(diagnostic_unauthorized) is not bool:
            raise ValueError(
                "racket_target.action_ball_diagnostic_unauthorized must be an "
                "exact boolean"
            )
        self._action_ball_diagnostic_unauthorized = diagnostic_unauthorized
        self._action_ball_reference_guard_mode = _reference_guard_mode(
            self.cfg.reference_guard_mode
        )
        from whole_body_tracking.tasks.tracking.mdp.action_ball_reference_guard import (
            ActionBallReferenceGuardMetrics,
            REFERENCE_GUARD_HARD_REASONS,
        )
        if (
            tuple(REFERENCE_GUARD_HARD_REASONS)
            != _ACTION_BALL_HARD_TERMINATION_TERMS
        ):
            raise RuntimeError(
                "ActionBall reference metrics hard-reason contract drifted"
            )

        self._action_ball_reference_guard_metrics = (
            ActionBallReferenceGuardMetrics(
                num_envs=self.num_envs,
                device=self.device,
            )
            if self._action_ball_reference_guard_mode
            == _REFERENCE_GUARD_METRICS_ONLY
            else None
        )
        self._action_ball_reference_term_disabled_mask = (
            torch.zeros(
                self.num_envs, dtype=torch.bool, device=self.device
            )
            if self._action_ball_reference_guard_mode
            == _REFERENCE_GUARD_METRICS_ONLY
            else None
        )
        if diagnostic_unauthorized:
            # Franco 2026-07-28 approved bypass: bind a DIAGNOSTIC authority
            # (no code-pinned launch receipt).  It can never record or issue
            # formal windows, so promotion/formal grading stays impossible;
            # the brand below follows every artifact this run produces.
            from whole_body_tracking.tasks.tracking.mdp import (
                action_ball_evaluation as evaluation,
            )

            evaluator_authority = evaluation.FrozenEvaluatorAuthority(
                curriculum_contract_sha256=bundle.contract_sha256,
                profile_order=profile_keys,
                arm_catalog_sha256=ARM_CATALOG_SHA256,
                scheduler_contract_sha256=scheduler_config.contract_sha256,
                sampler_sha256=sampler.sampler_contract_sha256,
                solver_sha256=solver_contract["sha256"],
                policy_contract_sha256=(
                    self.cfg.action_ball_policy_contract_sha256
                ),
            )
            evaluator_launch = {
                "diagnostic_unauthorized": True,
                "path": "",
                "file_sha256": "0" * 64,
                "document": None,
                "launch_receipt_canonical_sha256": "0" * 64,
                "authority_binding": evaluator_authority.binding_document(),
                "authority_state_owner_sha256": (
                    evaluator_authority.state_owner_sha256
                ),
            }
            evaluator_source = None
            evaluator_coordinator = None
            drain_reset_authority = None
            drain_reset_source = None
            drain_reset_launch = {
                "diagnostic_unauthorized": True,
                "path": "",
                "file_sha256": "0" * 64,
                "document": None,
                "launch_receipt_canonical_sha256": "0" * 64,
            }
            print(
                "[RacketTargetCommand] WARN action-ball DIAGNOSTIC "
                "UNAUTHORIZED run: trust sets and certificate chain "
                "bypassed; nothing this run produces can authorize "
                "promotion, export, or formal grading",
                flush=True,
            )
        else:
            (
                evaluator_authority,
                evaluator_source,
                evaluator_coordinator,
                evaluator_launch,
            ) = (
                _action_ball_load_frozen_evaluation_runtime(
                    cfg=self.cfg,
                    repo_root=repo_root,
                    curriculum_contract_sha256=bundle.contract_sha256,
                    profile_order=profile_keys,
                    arm_catalog_sha256=ARM_CATALOG_SHA256,
                    scheduler_contract_sha256=(
                        scheduler_config.contract_sha256
                    ),
                    sampler_sha256=sampler.sampler_contract_sha256,
                    solver_sha256=solver_contract["sha256"],
                )
            )
            (
                drain_reset_authority,
                drain_reset_source,
                drain_reset_launch,
            ) = _action_ball_load_drain_reset_authority(
                cfg=self.cfg,
                repo_root=repo_root,
                curriculum_contract_sha256=bundle.contract_sha256,
                profile_order=profile_keys,
                arm_catalog_sha256=ARM_CATALOG_SHA256,
                scheduler_contract_sha256=(
                    scheduler_config.contract_sha256
                ),
                sampler_sha256=sampler.sampler_contract_sha256,
                solver_sha256=solver_contract["sha256"],
                runtime_owner=self,
            )
        curriculum = ActionBallCurriculum(
            contract_sha256=bundle.contract_sha256,
            profile_order=profile_keys,
            sampler_sha256=sampler.sampler_contract_sha256,
            solver_sha256=solver_contract["sha256"],
            policy_contract_sha256=self.cfg.action_ball_policy_contract_sha256,
            config=curriculum_config,
            scheduler_config=scheduler_config,
            # A diagnostic authority is deliberately NOT bound: the curriculum
            # then refuses every formal observe/update fail-loud, which is the
            # promotion-path enforcement of the diagnostic brand.
            evaluator_authority=(
                None if diagnostic_unauthorized else evaluator_authority
            ),
            drain_reset_authority=(
                None if diagnostic_unauthorized else drain_reset_authority
            ),
        )
        domain_authority_contract = action_ball_domain_authority_contract(
            manifest_sha256=loaded.file_sha256,
            adapter_contract_sha256=bundle.contract_sha256,
            action_uids=bundle.action_uids,
            profile_sha256=bundle.profile_sha256,
            mobility_mode=manifest.mobility_mode,
            curriculum_config=curriculum_config.as_dict(),
            policy_contract_sha256=self.cfg.action_ball_policy_contract_sha256,
            source_sha256=runtime_sources,
        )
        pins = RuntimePins(
            manifest_sha256=loaded.file_sha256,
            sampler_sha256=sampler.sampler_contract_sha256,
            domain_authority_sha256=domain_authority_contract["sha256"],
            physics_sha256=physics_contract["sha256"],
            solver_sha256=solver_contract["sha256"],
            counter_rally_objective_profile_sha256=(
                None
                if counter_rally_objective is None
                else counter_rally_objective.sha256
            ),
        )
        bindings = tuple(
            ActionBinding(
                action_uid=action.action_uid,
                action_slot=slot,
                motion_path=action.motion_path,
                motion_sha256=action.motion_sha256,
                profile_sha256=bundle.profile_sha256[slot],
            )
            for slot, action in enumerate(manifest.actions)
        )
        immutable_tape = None
        banded_question_bank = None
        if self._action_ball_target_source == "immutable_tape":
            if not diagnostic_unauthorized:
                raise ValueError(
                    "action_ball_target_source='immutable_tape' is diagnostic-only; "
                    "it cannot authorize curriculum, export, deployment or formal N73"
                )
            if n_actions != 1:
                raise ValueError("the immutable fixed-question tape is N=1-only")
            tape_path = str(
                getattr(self.cfg, "action_ball_immutable_tape_path", "") or ""
            ).strip()
            tape_sha256 = str(
                getattr(self.cfg, "action_ball_immutable_tape_sha256", "") or ""
            ).strip()
            if not tape_path or not tape_sha256:
                raise ValueError(
                    "immutable_tape requires action_ball_immutable_tape_path and "
                    "action_ball_immutable_tape_sha256"
                )
            from whole_body_tracking.tasks.tracking.mdp.action_ball_fixed_question_tape import (
                load_immutable_n1_tape,
            )

            immutable_tape = load_immutable_n1_tape(
                tape_path,
                expected_file_sha256=tape_sha256,
            )
            source_receipt = immutable_tape.source_receipt
            binding = bindings[0]
            expected_identity = (
                binding.action_uid,
                binding.action_slot,
                binding.profile_sha256,
                binding.motion_sha256,
                loaded.file_sha256,
                sampler.sampler_contract_sha256,
                physics_contract["sha256"],
                solver_contract["sha256"],
                manifest.mobility_mode,
            )
            actual_identity = (
                source_receipt.action_uid,
                source_receipt.action_slot,
                source_receipt.profile_sha256,
                source_receipt.motion_sha256,
                source_receipt.manifest_sha256,
                source_receipt.sampler_sha256,
                source_receipt.physics_sha256,
                source_receipt.solver_sha256,
                source_receipt.mobility_mode,
            )
            if actual_identity != expected_identity:
                raise ValueError(
                    "immutable fixed-question tape identity differs from the loaded "
                    f"ActionBall N1 contract: expected={expected_identity!r}, "
                    f"actual={actual_identity!r}"
                )
            lineage = immutable_tape.target_lineage(
                self._action_ball_target_recipe
            )
            if tuple(lineage["target_validity_mask"]) != tuple(
                self._action_ball_target_validity_mask
            ):
                raise ValueError(
                    "immutable tape target validity differs from the configured recipe"
                )
            if (
                str(
                    getattr(
                        self.cfg, "action_ball_banded_question_bank_path", ""
                    )
                    or ""
                ).strip()
                or str(
                    getattr(
                        self.cfg, "action_ball_banded_question_bank_sha256", ""
                    )
                    or ""
                ).strip()
            ):
                raise ValueError(
                    "immutable_tape must not carry a banded question bank path/SHA"
                )
        elif self._action_ball_target_source == "banded_question_bank":
            if not diagnostic_unauthorized:
                raise ValueError(
                    "action_ball_target_source='banded_question_bank' is "
                    "construction-only while cached question draw ranges and "
                    "future birth/base coverage remain unclosed; formal or "
                    "expanding-curriculum training must fail closed"
                )
            bank_path = str(
                getattr(
                    self.cfg, "action_ball_banded_question_bank_path", ""
                )
                or ""
            ).strip()
            bank_sha256 = str(
                getattr(
                    self.cfg, "action_ball_banded_question_bank_sha256", ""
                )
                or ""
            ).strip()
            if not bank_path or not bank_sha256:
                raise ValueError(
                    "banded_question_bank requires "
                    "action_ball_banded_question_bank_path and "
                    "action_ball_banded_question_bank_sha256"
                )
            if (
                str(
                    getattr(self.cfg, "action_ball_immutable_tape_path", "")
                    or ""
                ).strip()
                or str(
                    getattr(self.cfg, "action_ball_immutable_tape_sha256", "")
                    or ""
                ).strip()
            ):
                raise ValueError(
                    "banded_question_bank must not carry immutable_tape path/SHA"
                )
            from whole_body_tracking.tasks.tracking.mdp.action_ball_banded_question_bank import (
                load_banded_question_bank,
            )

            banded_question_bank = load_banded_question_bank(
                bank_path, expected_file_sha256=bank_sha256
            )
            binding_by_uid = {binding.action_uid: binding for binding in bindings}
            center_levels_sha256 = ActionDomainLevels().canonical_sha256
            center_uids = set()
            for block in banded_question_bank.blocks:
                key = block.key
                binding = binding_by_uid.get(key["action_uid"])
                if binding is None:
                    raise ValueError(
                        "banded question bank contains an action outside the manifest"
                    )
                expected = (
                    binding.action_slot,
                    binding.profile_sha256,
                    binding.motion_sha256,
                    loaded.file_sha256,
                    sampler.sampler_contract_sha256,
                    domain_authority_contract["sha256"],
                    ARM_CATALOG_SHA256,
                    physics_contract["sha256"],
                    solver_contract["sha256"],
                    manifest.mobility_mode,
                )
                actual = (
                    key["action_slot"],
                    key["profile_sha256"],
                    key["motion_sha256"],
                    key["manifest_sha256"],
                    key["sampler_sha256"],
                    key["domain_authority_sha256"],
                    key["arm_catalog_sha256"],
                    key["physics_sha256"],
                    key["solver_sha256"],
                    key["mobility_mode"],
                )
                if actual != expected:
                    raise ValueError(
                        "banded question block identity differs from the loaded "
                        "ActionBall runtime contract"
                    )
                if key["levels_sha256"] == center_levels_sha256:
                    center_uids.add(key["action_uid"])
            if center_uids != set(binding_by_uid):
                raise ValueError(
                    "banded question bank must contain one exact center block "
                    "for every manifest action"
                )
        else:
            if (
                str(getattr(self.cfg, "action_ball_immutable_tape_path", "") or "").strip()
                or str(
                    getattr(self.cfg, "action_ball_immutable_tape_sha256", "") or ""
                ).strip()
            ):
                raise ValueError(
                    "online_solver must not carry an immutable tape path/SHA"
                )
            if (
                str(
                    getattr(
                        self.cfg, "action_ball_banded_question_bank_path", ""
                    )
                    or ""
                ).strip()
                or str(
                    getattr(
                        self.cfg, "action_ball_banded_question_bank_sha256", ""
                    )
                    or ""
                ).strip()
            ):
                raise ValueError(
                    "online_solver must not carry a banded question bank path/SHA"
                )
        effective_pool_refill_rows = (
            1
            if diagnostic_unauthorized
            else int(self.cfg.action_ball_pool_refill_rows)
        )
        effective_cq_overdraw = (
            1.0
            if diagnostic_unauthorized
            else float(self.cfg.cq_overdraw)
        )
        effective_cq_max_redraw_rounds = (
            _ACTION_BALL_DIAGNOSTIC_MAX_EXTERNAL_PROPOSAL_ROUNDS
            if diagnostic_unauthorized
            else int(self.cfg.cq_max_redraw_rounds)
        )
        # Boot-time half of the declaration/actual cross-check.  The load-bearing
        # half runs inside the three covered solve entry points, so deleting this
        # call cannot open the hole -- but failing here means a bad wiring edit
        # dies at boot instead of at the first refill.
        solver_declaration_check = (
            action_ball_assert_solver_runtime_matches_declaration(
                solver_declaration=solver_contract["payload"],
                physics_declaration=physics_contract["payload"],
                answer_input_declaration=answer_input_contract["payload"],
                expected_solver_profile_sha256=manifest.solver_profile_sha256,
                expected_prototype_file_sha256=manifest.prototype.sha256,
                prototypes=prototypes,
                reference_normal_rows=(
                    self._ref_racket_normal_raw_w_per_clip
                ),
                solver_cfg=solver_cfg,
                prm=prm,
                planes=(surface_z, net_x, net_top_z),
                rollout_h=float(self.cfg.vb_rollout_h),
                rollout_steps=int(self.cfg.vb_rollout_steps),
                overdraw=effective_cq_overdraw,
                maximum_rounds=effective_cq_max_redraw_rounds,
                diagnostic_unauthorized=diagnostic_unauthorized,
                call_site="_initialize_action_ball_runtime",
            )
        )
        broker = ActionBirthBroker(
            bindings,
            pins,
            manifest.mobility_mode,
            diagnostic_unauthorized=diagnostic_unauthorized,
        )
        pool = LazyActionTaskPool(
            bindings,
            pins,
            manifest.mobility_mode,
            refill_size=effective_pool_refill_rows,
            diagnostic_unauthorized=diagnostic_unauthorized,
        )

        self._action_ball_loaded_manifest = loaded
        self._action_ball_manifest = manifest
        self._action_ball_repo_root = repo_root
        self._action_ball_bundle = bundle
        self._action_ball_sampler = sampler
        self._action_ball_domain_levels_type = DomainLevels
        self._action_ball_curriculum = curriculum
        self._action_ball_profile_keys = profile_keys
        self._action_ball_key_by_uid = {
            key.action_uid: key for key in profile_keys
        }
        self._action_ball_pins = pins
        self._action_ball_bindings = bindings
        self._action_ball_immutable_tape = immutable_tape
        self._action_ball_banded_question_bank = banded_question_bank
        if self._action_ball_reuse_exact_question:
            from whole_body_tracking.tasks.tracking.mdp.action_ball_question_cache import (
                ExactCurriculumQuestionCache,
            )

            self._action_ball_exact_question_cache = (
                ExactCurriculumQuestionCache(bundle.action_uids)
            )
        else:
            self._action_ball_exact_question_cache = None
        # The immutable N=1 diagnostic has a receipt-free reset data plane.
        # Keep its authority/counters separate from the legacy pool so online
        # and banded sources retain their exact pool/replay semantics.
        self._action_ball_fixed_view_enabled = False
        self._action_ball_fixed_view_identity_sha256 = None
        self._action_ball_fixed_view_template = None
        self._action_ball_fixed_view_install_row_device = None
        self._action_ball_fixed_view_observation_row_device = None
        self._action_ball_fixed_view_timing_row_device = None
        self._action_ball_fixed_view_pristine_pool_state = None
        self._action_ball_fixed_view_counter_rally_identity = None
        self._action_ball_fixed_view_counter_rally_row_device = None
        self._action_ball_effective_pool_refill_rows = (
            effective_pool_refill_rows
        )
        self._action_ball_effective_cq_overdraw = effective_cq_overdraw
        self._action_ball_effective_cq_max_redraw_rounds = (
            effective_cq_max_redraw_rounds
        )
        self._action_ball_broker = broker
        self._action_ball_pool = pool
        self._action_ball_prototypes = prototypes
        self._action_ball_answer_input_contract = answer_input_contract
        self._action_ball_solver_cfg = solver_cfg
        self._action_ball_solver_declaration_check = solver_declaration_check
        self._action_ball_prm = prm
        self._counter_rally_enabled = (
            counter_rally_objective is not None
        )
        self._counter_rally_objective = counter_rally_objective
        self._counter_rally_venue_physics = (
            counter_rally_venue_physics
        )
        self._counter_rally_torch_binding = (
            counter_rally_torch_binding
        )
        if self._counter_rally_enabled:
            # ``virtual_legal_return_count`` has a long-standing public
            # meaning: the first landing is legal on the opponent table.
            # Counter-rally acceptance is stricter (it additionally grades the
            # baseline direction/speed objective), so it owns a separate exact
            # sparse counter instead of silently changing the virtual-return
            # numerator.  Register it before the first PPO window so even a
            # zero-contact window has a stable schema.
            counter_name = "counter_rally_accepted_count"
            sparse = self._sparse_reward_eligibility_counters
            sparse[counter_name] = torch.zeros(
                (), dtype=torch.long, device=self.device
            )
            for family in self._clip_names.values():
                sparse[f"{counter_name}_{family}"] = torch.zeros(
                    (), dtype=torch.long, device=self.device
                )
        self._action_ball_planes = (surface_z, net_x, net_top_z)
        self._action_ball_timing = tuple(timing)
        self._action_ball_attempt_close_margin_s = policy_dt_s
        self._action_ball_episode_length_s = episode_length_s
        self._action_ball_task_wait_schedule = task_wait_schedule
        self._action_ball_task_wait_highwater = task_wait_highwater
        self._action_ball_task_valid = torch.ones(
            self.num_envs, dtype=torch.bool, device=self.device
        )
        self._action_ball_task_wait_total_ticks = torch.zeros(
            self.num_envs, dtype=torch.long, device=self.device
        )
        self._action_ball_task_wait_elapsed_ticks = torch.zeros(
            self.num_envs, dtype=torch.long, device=self.device
        )
        self._action_ball_task_wait_last_advance_step = -1
        self._action_ball_ready_yaw = tuple(ready_yaw)
        self._action_ball_ready_quat = tuple(ready_quat)
        self._action_ball_ready_z = tuple(ready_z)
        self._action_ball_physics_contract = physics_contract
        self._action_ball_solver_contract = solver_contract
        self._action_ball_contact_geometry_contract = (
            contact_geometry_contract
        )
        self._action_ball_mount_signs = tuple(manifest_signs)
        self._action_ball_cache_reference_host_rows()
        self._action_ball_domain_authority_contract = (
            domain_authority_contract
        )
        self._action_ball_evaluator_launch = evaluator_launch
        self._action_ball_evaluator_authority = evaluator_authority
        self._action_ball_evaluator_source = evaluator_source
        self._action_ball_evaluation_coordinator = evaluator_coordinator
        self._action_ball_drain_reset_authority = drain_reset_authority
        self._action_ball_drain_reset_source = drain_reset_source
        self._action_ball_drain_reset_launch = drain_reset_launch
        self._action_ball_drain_fence_active = False
        self._action_ball_eval_last_request_step = -1
        self._action_ball_eval_profile_cursor = 0
        self._action_ball_eval_next_kind_by_uid = {
            int(uid): "formal" for uid in bundle.action_uids
        }
        self._action_ball_runtime_source_sha256 = runtime_sources
        self._action_ball_outcome_type = BallOutcomeLedger
        self._action_ball_runtime_types = None
        self._action_ball_provider_births = {}
        self._action_ball_provider_history = {}
        self._action_ball_task_transcript_by_birth = {}
        self._action_ball_emitted_task_count_by_uid = {
            int(uid): 0 for uid in bundle.action_uids
        }
        self._action_ball_domain_cursor_by_uid = {
            int(uid): 0 for uid in bundle.action_uids
        }
        self._action_ball_reject_counts = {
            int(uid): {} for uid in bundle.action_uids
        }
        self._action_ball_birth_by_env = [None] * self.num_envs
        self._action_ball_task_by_env = [None] * self.num_envs
        self._action_ball_task_ref_by_env = [None] * self.num_envs
        self._counter_rally_task_identity_by_env = (
            [None] * self.num_envs
        )
        # Conservative before the first birth: reference-consistency
        # terminations stay enabled.  Each env replaces this bit only when a
        # true-reset birth transaction commits; wraps must retain the exact
        # episode latch even if another action publishes a new frontier.
        self._action_ball_reference_term_center_latch = torch.ones(
            self.num_envs,
            dtype=torch.bool,
            device=self.device,
        )
        self._action_ball_ledger = torch.zeros(
            len(_ACTION_BALL_LEDGER_NAMES),
            n_actions,
            dtype=torch.long,
            device=self.device,
        )
        self._action_ball_fixed_view_ledger = torch.zeros_like(
            self._action_ball_ledger
        )
        self._action_ball_action_uid = torch.full(
            (self.num_envs,), -1, dtype=torch.long, device=self.device
        )
        self._action_ball_action_slot = torch.full(
            (self.num_envs,), -1, dtype=torch.long, device=self.device
        )
        self._action_ball_reset_generation = torch.zeros(
            self.num_envs, dtype=torch.long, device=self.device
        )
        self._action_ball_swing_generation = torch.full(
            (self.num_envs,), -1, dtype=torch.long, device=self.device
        )
        self._action_ball_attempt_active = torch.zeros(
            self.num_envs, dtype=torch.bool, device=self.device
        )
        self._action_ball_attempt_action = torch.full(
            (self.num_envs,), -1, dtype=torch.long, device=self.device
        )
        self._action_ball_attempt_legal = torch.zeros(
            self.num_envs, dtype=torch.bool, device=self.device
        )
        self._action_ball_attempt_hit = torch.zeros(
            self.num_envs, dtype=torch.bool, device=self.device
        )
        # Data-only exact resume restores the old command graph before the runner's mandatory
        # first simulator reset.  These rows must be retired as X, never graded against the fresh
        # simulator state.  The latch is load-housekeeping (not checkpoint continuation state) and
        # is cleared by that first reset.
        self._action_ball_resume_reset_exclusion = torch.zeros(
            self.num_envs, dtype=torch.bool, device=self.device
        )
        self._counter_rally_return_direction_env_xy = torch.zeros(
            self.num_envs,
            2,
            dtype=self.racket_target_pos_w.dtype,
            device=self.device,
        )
        self._counter_rally_target_baseline_speed_mps = torch.zeros(
            self.num_envs,
            dtype=self.racket_target_pos_w.dtype,
            device=self.device,
        )
        self._counter_rally_reward_terms = torch.zeros(
            self.num_envs,
            5,
            dtype=self.racket_target_pos_w.dtype,
            device=self.device,
        )
        self._counter_rally_accepted = torch.zeros(
            self.num_envs,
            dtype=torch.bool,
            device=self.device,
        )
        self._counter_rally_legal_first_landing = torch.zeros(
            self.num_envs,
            dtype=torch.bool,
            device=self.device,
        )
        self._counter_rally_primary_reason_code = torch.full(
            (self.num_envs,),
            -1,
            dtype=torch.long,
            device=self.device,
        )
        self._action_ball_last_rollout_step = None
        self._action_ball_state_owner_sha256 = (
            _action_ball_canonical_sha256(
                {
                    "schema_version": _ACTION_BALL_SOLVER_STATE_SCHEMA_VERSION,
                    "kind": (
                        "whole_body_tracking.RacketTargetCommand."
                        "action_ball_mutable_state_owner"
                    ),
                    "action_uids": list(bundle.action_uids),
                    "sampler_contract_sha256": (
                        sampler.sampler_contract_sha256
                    ),
                    "domain_authority_contract_sha256": (
                        domain_authority_contract["sha256"]
                    ),
                    "solver_contract_sha256": solver_contract["sha256"],
                    "target_source": self._action_ball_target_source,
                    "target_recipe": self._action_ball_target_recipe,
                    "target_validity_mask": list(
                        self._action_ball_target_validity_mask
                    ),
                    "reuse_exact_question_until_semantics_change": (
                        self._action_ball_reuse_exact_question
                    ),
                    "immutable_tape_canonical_sha256": (
                        None
                        if immutable_tape is None
                        else immutable_tape.canonical_sha256
                    ),
                    "banded_question_bank_canonical_sha256": (
                        None
                        if banded_question_bank is None
                        else banded_question_bank.canonical_sha256
                    ),
                    "task_wait_schedule_canonical_sha256": (
                        None
                        if task_wait_schedule is None
                        else task_wait_schedule.canonical_sha256
                    ),
                }
            )
        )
        self._action_ball_domain_authority = (
            _ActionBallDomainAuthorityAdapter(
                domain_authority_contract_sha256=(
                    domain_authority_contract["sha256"]
                ),
                state_owner_sha256=self._action_ball_state_owner_sha256,
                claim=self._action_ball_claim_domain,
                claim_many=(
                    self._action_ball_claim_domains
                    if self._action_ball_diagnostic_unauthorized
                    else None
                ),
                domain_cursor_for=lambda uid: int(
                    self._action_ball_domain_cursor_by_uid[int(uid)]
                ),
                state_getter=self._action_ball_solver_mutable_state_dict,
                state_loader=self._action_ball_load_solver_mutable_state,
            )
        )
        self._action_ball_birth_provider = _ActionBallBirthProviderAdapter(
            sampler_contract_sha256=sampler.sampler_contract_sha256,
            state_owner_sha256=self._action_ball_state_owner_sha256,
            provide=self._action_ball_provide_birth,
            provide_many=(
                self._action_ball_provide_births
                if self._action_ball_diagnostic_unauthorized
                else None
            ),
            assert_issued_birth=self._action_ball_assert_issued_birth,
            birth_highwater_for=self._action_ball_sampler.birth_highwater_for,
            state_getter=self._action_ball_solver_mutable_state_dict,
            state_loader=self._action_ball_load_solver_mutable_state,
        )
        if banded_question_bank is not None:
            from whole_body_tracking.tasks.tracking.mdp.action_ball_banded_question_bank import (
                BandedQuestionBankSolver,
            )

            self._action_ball_pool_solver = BandedQuestionBankSolver(
                bank=banded_question_bank,
                solver_contract_sha256=solver_contract["sha256"],
            )
        elif immutable_tape is None:
            self._action_ball_pool_solver = _ActionBallPoolSolverAdapter(
                solver_contract_sha256=solver_contract["sha256"],
                state_owner_sha256=self._action_ball_state_owner_sha256,
                solve=self._action_ball_refill_pool,
                solve_many=self._action_ball_refill_pool_many,
                assert_emitted_sample=self._action_ball_assert_emitted_sample,
                assert_emitted_tasks=self._action_ball_assert_emitted_tasks,
                emitted_task_count_for=self._action_ball_emitted_task_count_for,
                task_transcript_for_birth=(
                    self._action_ball_task_transcript_for_birth
                ),
                assert_proposal_assignments=(
                    self._action_ball_assert_proposal_assignments
                ),
                sample_highwater_for=self._action_ball_sampler.sample_highwater_for,
                state_getter=self._action_ball_solver_mutable_state_dict,
                state_loader=self._action_ball_load_solver_mutable_state,
                # ``_action_ball_fixed_view_enabled`` is still False here and
                # cannot become True on this branch: fixed view is bound only by
                # the immutable-tape solver below.
                pool_owns_birth_task_transcripts=bool(
                    diagnostic_unauthorized
                ),
            )
        else:
            from whole_body_tracking.tasks.tracking.mdp.action_ball_fixed_question_tape import (
                FixedQuestionTapeSolver,
            )

            self._action_ball_pool_solver = FixedQuestionTapeSolver(
                tape=immutable_tape,
                target_recipe=self._action_ball_target_recipe,
                solver_contract_sha256=solver_contract["sha256"],
            )
            fixed_view_template = (
                self._action_ball_pool_solver.reset_batch_view(
                    batch_size=1
                )
            )
            fixed_counter_rally_payload = immutable_tape.question_payload[
                "counter_rally_task"
            ]
            if (fixed_counter_rally_payload is None) != (
                not self._counter_rally_enabled
            ):
                raise ValueError(
                    "immutable fixed-view counter-rally identity differs "
                    "from the loaded N1 manifest"
                )
            if fixed_counter_rally_payload is not None:
                from whole_body_tracking.tasks.tracking.mdp.action_ball_runtime import (
                    CounterRallyTaskIdentity,
                )

                fixed_counter_rally_identity = (
                    CounterRallyTaskIdentity.from_dict(
                        fixed_counter_rally_payload
                    )
                )
                if (
                    fixed_counter_rally_identity.objective_profile_sha256
                    != self._counter_rally_objective.sha256
                ):
                    raise ValueError(
                        "immutable fixed-view counter-rally objective differs "
                        "from the loaded N1 manifest"
                    )
            else:
                fixed_counter_rally_identity = None
            fixed_view_identity_sha256 = _action_ball_canonical_sha256(
                {
                    "schema_version": 1,
                    "kind": (
                        "whole_body_tracking.RacketTargetCommand."
                        "immutable_n1_fixed_reset_view"
                    ),
                    "diagnostic_unauthorized": True,
                    "target_source": self._action_ball_target_source,
                    "target_recipe": self._action_ball_target_recipe,
                    "lineage": dict(fixed_view_template.lineage),
                    "install_row": list(fixed_view_template.install_row),
                    "observation_row": list(
                        fixed_view_template.observation_row
                    ),
                    "timing_row": list(fixed_view_template.timing_row),
                    "counter_rally_task": (
                        None
                        if fixed_counter_rally_identity is None
                        else fixed_counter_rally_identity.to_dict()
                    ),
                }
            )
            fixed_dtype = self.racket_target_pos_w.dtype
            self._action_ball_fixed_view_template = fixed_view_template
            self._action_ball_fixed_view_identity_sha256 = (
                fixed_view_identity_sha256
            )
            self._action_ball_fixed_view_install_row_device = torch.tensor(
                fixed_view_template.install_row,
                dtype=fixed_dtype,
                device=self.device,
            ).reshape(1, -1)
            self._action_ball_fixed_view_observation_row_device = torch.tensor(
                fixed_view_template.observation_row,
                dtype=fixed_dtype,
                device=self.device,
            ).reshape(1, -1)
            self._action_ball_fixed_view_timing_row_device = torch.tensor(
                fixed_view_template.timing_row,
                dtype=fixed_dtype,
                device=self.device,
            ).reshape(1, -1)
            fixed_install = (
                self._action_ball_fixed_view_install_row_device
            )
            fixed_cache_checks = _action_ball_host_bool_packet(
                (
                    torch.isfinite(fixed_install).all(),
                    torch.all(
                        torch.abs(
                            torch.linalg.norm(
                                fixed_install[:, 19:22], dim=-1
                            )
                            - 1.0
                        )
                        <= 1.0e-6
                    ),
                    torch.all(
                        torch.abs(
                            torch.linalg.norm(
                                fixed_install[:, 15:19], dim=-1
                            )
                            - 1.0
                        )
                        <= 1.0e-6
                    ),
                    torch.all(fixed_install[:, 30] > 0.0),
                )
            )
            if not all(fixed_cache_checks):
                raise ValueError(
                    "immutable fixed-view cached install row is invalid"
                )
            self._action_ball_fixed_view_counter_rally_identity = (
                fixed_counter_rally_identity
            )
            self._action_ball_fixed_view_counter_rally_row_device = (
                None
                if fixed_counter_rally_identity is None
                else torch.tensor(
                    (
                        *fixed_counter_rally_identity.return_direction_env_xy,
                        fixed_counter_rally_identity.target_baseline_speed_mps,
                    ),
                    dtype=fixed_dtype,
                    device=self.device,
                ).reshape(1, 3)
            )
            self._action_ball_fixed_view_enabled = True

        broker.bind_domain_claim_authority(
            self._action_ball_domain_authority
        )
        broker.bind_provider(self._action_ball_birth_provider)
        pool.bind_solver(self._action_ball_pool_solver)
        if self._action_ball_fixed_view_enabled:
            # Capture the never-bound, never-used legacy-pool identity once.
            # Its authority SHA is deliberately null: fixed resets never
            # register births or tasks with this compatibility object.
            self._action_ball_fixed_view_pristine_pool_state = (
                pool.state_dict()
            )
        pool.bind_birth_authority(broker)
        motion_command.bind_action_ball_birth_broker(
            broker, trusted_repo_root=repo_root
        )
        motion_command.bind_action_ball_task_authority(
            task_ref_for_env=self.action_ball_task_ref_for_env,
            resolve_task_ref=self.action_ball_resolve_task_ref,
            shared_state_sha256=self.action_ball_shared_state_sha256,
        )
        if self._action_ball_fixed_view_enabled:
            motion_command.bind_action_ball_fixed_view_timing(
                fixed_view_identity_sha256=(
                    self._action_ball_fixed_view_identity_sha256
                ),
                timing_row=self._action_ball_fixed_view_template.timing_row,
                broker_exact_state=(
                    self._action_ball_fixed_view_broker_state_dict
                ),
            )

        # Runner exact-resume hooks are installed only for this explicit mode.  Legacy and old
        # task-first checkpoints retain their own state shape.
        self.exact_resume_state_dict = self._action_ball_exact_resume_state_dict
        self.validate_exact_resume_state_dict = (
            self._action_ball_validate_exact_resume_state_dict
        )
        self.load_exact_resume_state_dict = self._action_ball_load_exact_resume_state_dict
        self.on_rollout_end = self._action_ball_on_rollout_end
        print(
            "[RacketTargetCommand] action-ball runtime bound: "
            f"actions={n_actions}, mobility={manifest.mobility_mode}, "
            f"manifest={loaded.file_sha256}, sampler={sampler.sampler_contract_sha256}, "
            f"solver={solver_contract['sha256']}, physics={physics_contract['sha256']}, "
            f"target_source={self._action_ball_target_source}, "
            f"target_recipe={self._action_ball_target_recipe}",
            flush=True,
        )
        if (
            self._action_ball_reference_guard_mode
            == _REFERENCE_GUARD_METRICS_ONLY
        ):
            print(
                "[RacketTargetCommand] reference_guard_mode=metrics_only: "
                "anchor_pos/anchor_ori/ee_body_pos are metrics-only; "
                "base/table/q_des/actual-joint hard guards remain terminal",
                flush=True,
            )

    def action_ball_hard_contract(self) -> dict | None:
        """Return the complete preflight identity without exposing mutable private objects."""

        if not self._action_ball_enabled:
            return None
        self._ensure_action_ball_runtime_initialized()
        motion = self._motion()
        try:
            manifest_relative_path = self._action_ball_loaded_manifest.source_path.resolve(
                strict=True
            ).relative_to(self._action_ball_repo_root).as_posix()
        except (OSError, ValueError) as error:
            raise RuntimeError(
                "action-ball manifest escaped the trusted repository root after admission"
            ) from error
        if self._action_ball_diagnostic_unauthorized:
            evaluator_authority_contract = {
                "diagnostic_unauthorized": True,
                "formal_authority_available": False,
                "formal_launch_requires_code_pinned_receipt": True,
                "runtime_or_manifest_may_self_authorize": False,
                "authority_binding": (
                    self._action_ball_evaluator_launch["authority_binding"]
                ),
                "authority_state_owner_sha256": (
                    self._action_ball_evaluator_launch[
                        "authority_state_owner_sha256"
                    ]
                ),
            }
        else:
            evaluator_authority_contract = {
                "authority_contract_sha256": __import__(
                    "whole_body_tracking.tasks.tracking.mdp.action_ball_evaluation",
                    fromlist=[
                        "FROZEN_EVALUATOR_V4_AUTHORITY_CONTRACT_SHA256"
                    ],
                ).FROZEN_EVALUATOR_V4_AUTHORITY_CONTRACT_SHA256,
                "trusted_launch_receipt_sha256": sorted(
                    __import__(
                        "whole_body_tracking.tasks.tracking.mdp.action_ball_evaluation",
                        fromlist=[
                            "TRUSTED_FROZEN_EVALUATOR_V4_LAUNCH_RECEIPT_SHA256"
                        ],
                    ).TRUSTED_FROZEN_EVALUATOR_V4_LAUNCH_RECEIPT_SHA256
                ),
                "evaluator_launch_receipt_path": (
                    self._action_ball_evaluator_launch["path"]
                ),
                "evaluator_launch_receipt_file_sha256": (
                    self._action_ball_evaluator_launch["file_sha256"]
                ),
                "evaluator_launch_receipt": (
                    self._action_ball_evaluator_launch["document"]
                ),
                "launch_receipt_canonical_sha256": (
                    self._action_ball_evaluator_launch[
                        "launch_receipt_canonical_sha256"
                    ]
                ),
                "authority_binding": (
                    self._action_ball_evaluator_launch["authority_binding"]
                ),
                "authority_state_owner_sha256": (
                    self._action_ball_evaluator_launch[
                        "authority_state_owner_sha256"
                    ]
                ),
                "attempt_source_state_owner_sha256": (
                    self._action_ball_evaluator_launch[
                        "attempt_source_state_owner_sha256"
                    ]
                ),
                "coordinator_state_owner_sha256": (
                    self._action_ball_evaluator_launch[
                        "coordinator_state_owner_sha256"
                    ]
                ),
                "inbox_root": self._action_ball_evaluator_launch[
                    "inbox_root"
                ],
                "inbox_owner_id": self._action_ball_evaluator_launch[
                    "inbox_owner_id"
                ],
                "inbox_run_id": self._action_ball_evaluator_launch[
                    "inbox_run_id"
                ],
                "sidecar_launch_receipt_path": (
                    self._action_ball_evaluator_launch[
                        "sidecar_launch_receipt_path"
                    ]
                ),
                "sidecar_launch_receipt_file_sha256": (
                    self._action_ball_evaluator_launch[
                        "sidecar_launch_receipt_file_sha256"
                    ]
                ),
                "sidecar_launch_receipt_content_sha256": (
                    self._action_ball_evaluator_launch[
                        "sidecar_launch_receipt_content_sha256"
                    ]
                ),
                "sidecar_code_path": self._action_ball_evaluator_launch[
                    "sidecar_code_path"
                ],
                "sidecar_code_sha256": self._action_ball_evaluator_launch[
                    "sidecar_code_sha256"
                ],
                "drain_reset": self._action_ball_drain_reset_launch,
                "evaluation_interval_updates": int(
                    self.cfg.action_ball_frozen_eval_interval_updates
                ),
                "formal_authority_available": True,
                "formal_launch_requires_code_pinned_receipt": True,
                "runtime_or_manifest_may_self_authorize": False,
            }
        from whole_body_tracking.tasks.tracking.mdp.action_ball_reference_guard import (
            REFERENCE_GUARD_CONTRACT_PAYLOAD,
            REFERENCE_GUARD_CONTRACT_SHA256,
        )

        payload = {
            "schema_version": 1,
            "kind": "whole_body_tracking.RacketTargetCommand.action_ball_hard_contract",
            "manifest": {
                "path": manifest_relative_path,
                "file_sha256": self._action_ball_loaded_manifest.file_sha256,
                "canonical_sha256": self._action_ball_loaded_manifest.canonical_sha256,
                "manifest_id": self._action_ball_manifest.manifest_id,
            },
            "mobility_mode": self._action_ball_manifest.mobility_mode,
            "action_order": list(self._action_ball_manifest.action_order),
            "action_uids": list(self._action_ball_bundle.action_uids),
            "bindings": [
                binding.to_dict() for binding in self._action_ball_bindings
            ],
            "prototype": {
                "path": self._action_ball_manifest.prototype.path,
                "scope": self._action_ball_manifest.prototype.scope,
                "sha256": self._action_ball_manifest.prototype.sha256,
            },
            "profiles": {
                "adapter_contract_sha256": self._action_ball_bundle.contract_sha256,
                "profile_sha256": list(self._action_ball_bundle.profile_sha256),
                "arm_catalog_sha256": __import__(
                    "whole_body_tracking.tasks.tracking.mdp.action_ball_sampling",
                    fromlist=["ARM_CATALOG_SHA256"],
                ).ARM_CATALOG_SHA256,
                "sampler_contract_sha256": (
                    self._action_ball_sampler.sampler_contract_sha256
                ),
                "frozen_evaluation_proposal_sampler_contract_sha256": (
                    __import__(
                        "whole_body_tracking.tasks.tracking.mdp.action_ball_sampling",
                        fromlist=[
                            "FROZEN_EVALUATION_PROPOSAL_SAMPLER_CONTRACT_SHA256"
                        ],
                    ).FROZEN_EVALUATION_PROPOSAL_SAMPLER_CONTRACT_SHA256
                ),
            },
            "sampling": {
                "action_ball_seed": int(self.cfg.action_ball_seed),
                "initial_center_single_question": (
                    self._action_ball_sampler.initial_center_single_question
                ),
                "pool_refill_rows": (
                    self._action_ball_effective_pool_refill_rows
                ),
                "balanced_clip_sampling": bool(
                    self._motion().cfg.balanced_clip_sampling
                ),
                "balanced_clip_sampling_seed": int(
                    self._motion().cfg.balanced_clip_sampling_seed
                ),
                "external_overdraw_multiplier": (
                    self._action_ball_effective_cq_overdraw
                ),
                "maximum_external_proposal_rounds": int(
                    self._action_ball_effective_cq_max_redraw_rounds
                ),
                "configured_maximum_external_proposal_rounds": int(
                    self.cfg.cq_max_redraw_rounds
                ),
            },
            "timing": {
                "authority": (
                    "immutable_n1_fixed_view_timing"
                    if self._action_ball_fixed_view_enabled
                    else self._action_ball_task_receipt_timing_authority
                ),
                "policy_dt_s": self._action_ball_attempt_close_margin_s,
                "attempt_close_margin_s": (
                    self._action_ball_attempt_close_margin_s
                ),
                "episode_length_s": self._action_ball_episode_length_s,
                "time_to_strike_source": (
                    "MotionCommand.action_ball_time_to_contact_remaining_s"
                ),
                "pre_task_wait": (
                    None
                    if self._action_ball_task_wait_schedule is None
                    else {
                        "schedule": (
                            self._action_ball_task_wait_schedule.to_dict()
                        ),
                        "runtime_owner": (
                            "RacketTargetCommand._action_ball_task_valid"
                        ),
                        "public_task_valid_semantics": (
                            "WAIT=0,TASK_ACTIVE=1"
                        ),
                        "wait_countdown_is_public": False,
                        "wait_masked_public_groups": [
                            "task",
                            "incoming_ball",
                            "desired_base_goal",
                            "time_to_contact",
                            "time_to_teacher_start",
                        ],
                        "reward_and_denominator_intersection_required": True,
                    }
                ),
                "legacy_motion_time_owners": {
                    "hold_steps_range": list(
                        motion.cfg.hold_steps_range
                    ),
                    "stand_start_min_hold": int(
                        motion.cfg.stand_start_min_hold
                    ),
                    "post_swing_min_hold": int(
                        motion.cfg.post_swing_min_hold
                    ),
                    "stagger_initial_clock": bool(
                        motion.cfg.stagger_initial_clock
                    ),
                    "speed_scale_range": list(
                        motion.cfg.speed_scale_range
                    ),
                    "speed_scale_per_clip": (
                        None
                        if motion.cfg.speed_scale_per_clip is None
                        else list(motion.cfg.speed_scale_per_clip)
                    ),
                    "planner_revision_enabled": bool(
                        motion.planner_revision_enabled
                    ),
                },
            },
            "reference_guard": {
                "mode": self._action_ball_reference_guard_mode,
                "contract_payload": json.loads(
                    json.dumps(
                        REFERENCE_GUARD_CONTRACT_PAYLOAD,
                        allow_nan=False,
                        separators=(",", ":"),
                        sort_keys=True,
                    )
                ),
                "contract_sha256": REFERENCE_GUARD_CONTRACT_SHA256,
            },
            "solver": self._action_ball_solver_contract,
            "target_provider": {
                "source": self._action_ball_target_source,
                "recipe": self._action_ball_target_recipe,
                "validity_order": ["position", "velocity", "face"],
                "validity_mask": list(
                    self._action_ball_target_validity_mask
                ),
                "target_observation_noise": (
                    self._action_ball_target_observation_noise
                ),
                "exact_question_answer_reuse": {
                    "enabled": self._action_ball_reuse_exact_question,
                    "ownership": "curriculum_sampler_rng",
                    "capacity": (
                        "all_active_birth_semantic_rows_plus_one_hot_row_per_action"
                    ),
                    "hit_rule": "complete_semantic_question_sha256_equal",
                    "miss_rule": (
                        "epoch_or_levels_or_stratum_or_base_or_ball_or_aim_or_"
                        "motion_or_physics_or_solver_changed"
                    ),
                },
                "actor_width_unchanged": True,
                "critic_width_unchanged": True,
                "immutable_tape": (
                    None
                    if self._action_ball_immutable_tape is None
                    else {
                        "path": str(
                            Path(
                                self.cfg.action_ball_immutable_tape_path
                            ).expanduser().resolve(strict=True)
                        ),
                        "file_sha256": (
                            self.cfg.action_ball_immutable_tape_sha256
                        ),
                        "canonical_sha256": (
                            self._action_ball_immutable_tape.canonical_sha256
                        ),
                        "base_question_sha256": (
                            self._action_ball_immutable_tape.question_sha256
                        ),
                        "target_lineage": (
                            self._action_ball_immutable_tape.target_lineage(
                                self._action_ball_target_recipe
                            )
                        ),
                        "online_lm_calls": 0,
                        "physical_rng_draws": 0,
                        # Both counters above belong only to the immutable
                        # target/question solver. Episode births retain their
                        # separate sampler tape and may consume RNG.
                        "zero_counter_scope": "target_question_solver_only",
                        "birth_sampler_rng": "separate_tracked_mutable_state",
                        "reset_operation": (
                            "FixedQuestionTapeSolver.reset_batch_view"
                        ),
                        "task_receipts_per_reset": 0,
                        "lazy_task_pool_bypassed": True,
                        "fixed_view_identity_sha256": (
                            self._action_ball_fixed_view_identity_sha256
                        ),
                        "diagnostic_unauthorized": True,
                    }
                ),
                "banded_question_bank": (
                    None
                    if self._action_ball_banded_question_bank is None
                    else {
                        "path": str(
                            Path(
                                self.cfg.action_ball_banded_question_bank_path
                            ).expanduser().resolve(strict=True)
                        ),
                        "file_sha256": (
                            self.cfg.action_ball_banded_question_bank_sha256
                        ),
                        "canonical_sha256": (
                            self._action_ball_banded_question_bank.canonical_sha256
                        ),
                        "block_keys": [
                            {
                                "key": dict(block.key),
                                "key_sha256": block.key_sha256,
                                "content_sha256": block.content_sha256,
                                "row_count": len(block.rows),
                            }
                            for block in sorted(
                                self._action_ball_banded_question_bank.blocks,
                                key=lambda item: item.key_sha256,
                            )
                        ],
                        "selection": (
                            self._action_ball_banded_question_bank.canonical_payload[
                                "selection"
                            ]
                        ),
                        "online_solver_calls_per_reset": 0,
                        "missing_block_policy": "fail_closed",
                        "diagnostic_unauthorized_required": True,
                        "curriculum_authority_retained": True,
                        "command_exact_resume_integration": (
                            "pool_owned_bounded_block_state"
                        ),
                    }
                ),
            },
            "physics": self._action_ball_physics_contract,
            "domain_authority": self._action_ball_domain_authority_contract,
            "mutable_state_owner": {
                "schema_version": _ACTION_BALL_SOLVER_STATE_SCHEMA_VERSION,
                "state_owner_sha256": self._action_ball_state_owner_sha256,
                "protocol_views": [
                    "domain_claim_authority",
                    "birth_provider",
                    *(
                        ("task_solver",)
                        if self._action_ball_immutable_tape is None
                        and self._action_ball_banded_question_bank is None
                        else ()
                    ),
                ],
                "checkpoint_state_is_mutable": True,
                "mutable_state_sha256_is_not_a_hard_contract_pin": True,
            },
            "curriculum": {
                "config": self._action_ball_curriculum.config.as_dict(),
                "policy_contract_sha256": (
                    self.cfg.action_ball_policy_contract_sha256
                ),
                "frozen_checkpoint_evidence_required": True,
                "live_rollout_advances_curriculum": False,
            },
            "evaluator_authority": evaluator_authority_contract,
            "runtime": {
                "runtime_contract_sha256": __import__(
                    "whole_body_tracking.tasks.tracking.mdp.action_ball_runtime",
                    fromlist=["RUNTIME_CONTRACT_SHA256"],
                ).RUNTIME_CONTRACT_SHA256,
                "registry_sha256": self._action_ball_broker.registry_sha256,
                "implementation_source_sha256": dict(
                    self._action_ball_runtime_source_sha256
                ),
                "fixed_direction": _ACTION_BALL_SOLVER_FIXED_DIRECTION,
                "wrap_teleport": False,
            },
            "motion_admission": (
                motion.action_ball_motion_admission_hard_contract()
            ),
        }
        if (
            self._action_ball_task_wait_schedule is not None
            and payload["target_provider"]["immutable_tape"] is not None
        ):
            payload["target_provider"]["immutable_tape"].update(
                {
                    "curriculum_scope": (
                        "current_diagnostic_n1_or_early_fixed_band_only"
                    ),
                    "does_not_freeze_final_curriculum_to_one_question": True,
                    "final_curriculum_question_source": (
                        "pregenerated_or_cached_band_question_bank"
                    ),
                    "final_curriculum_reset_operation": (
                        "index_precomputed_question_row"
                    ),
                    "final_curriculum_online_inverse_solves_per_reset": 0,
                }
            )
        if self._counter_rally_enabled:
            payload["counter_rally"] = {
                "mode": self._counter_rally_objective.mode,
                "objective_profile": (
                    self._counter_rally_objective.to_mapping()
                ),
                "objective_profile_sha256": (
                    self._counter_rally_objective.sha256
                ),
                "venue_physics": (
                    self._counter_rally_venue_physics.to_mapping()
                ),
                "venue_physics_sha256": (
                    self._counter_rally_venue_physics.sha256
                ),
                "task_receipt_identity_required": True,
                "actual_policy_fitted_rollout_required": True,
            }
        if self._action_ball_diagnostic_unauthorized:
            # Brand the hard contract.  The evaluator subtree was built
            # diagnostically before payload construction, so no absent formal
            # receipt field is ever read.
            payload["diagnostic_unauthorized"] = True
        payload["canonical_sha256"] = _action_ball_canonical_sha256(payload)
        return payload

    def _action_ball_task_receipt_for_env(self, env_id: int):
        """Return the frozen current task receipt through a fail-closed read-only seam.

        Motion consumes timing from this opaque receipt.  It never receives the
        curriculum, sampler, broker, pool, or their mutable checkpoint bytes.
        """

        if type(env_id) is not int or not 0 <= env_id < self.num_envs:
            raise ValueError("action-ball task receipt env_id is out of range")
        if not self._action_ball_enabled or not hasattr(
            self, "_action_ball_task_by_env"
        ):
            return None
        receipt = self._action_ball_task_by_env[env_id]
        birth = self._action_ball_birth_by_env[env_id]
        active = bool(self._action_ball_attempt_active[env_id].item())
        fixed_view = self._action_ball_fixed_view_enabled
        if fixed_view:
            if (
                receipt is not None
                or self._action_ball_task_ref_by_env[env_id] is not None
            ):
                raise RuntimeError(
                    "immutable fixed-view env acquired a task receipt/ref"
                )
            if active and birth is None:
                raise RuntimeError(
                    "active immutable fixed-view env has no episode birth"
                )
            return None
        if receipt is None:
            if active:
                raise RuntimeError(
                    "active action-ball env has no opaque task receipt"
                )
            return None
        if not active or birth is None:
            raise RuntimeError(
                "action-ball task receipt exists without an active episode birth"
            )
        from whole_body_tracking.tasks.tracking.mdp.action_ball_runtime import (
            ActionBallTaskReceipt,
        )

        if (
            not bool(
                getattr(
                    self,
                    "_action_ball_diagnostic_unauthorized",
                    False,
                )
            )
            and ActionBallTaskReceipt.from_dict(receipt.to_dict()) != receipt
        ):
            raise RuntimeError(
                "action-ball task receipt failed exact read-only round-trip"
            )
        receipt.assert_birth(birth)
        if (
            receipt.env_id != env_id
            or int(self._action_ball_action_uid[env_id].item())
            != receipt.action_uid
            or int(self._action_ball_action_slot[env_id].item())
            != receipt.action_slot
            or int(self._action_ball_reset_generation[env_id].item())
            != receipt.reset_generation
            or int(self._action_ball_swing_generation[env_id].item())
            != receipt.swing_generation
            or int(self._action_ball_attempt_action[env_id].item())
            != receipt.action_slot
        ):
            raise RuntimeError(
                "action-ball opaque task receipt disagrees with current env generation"
            )
        return receipt

    def action_ball_task_ref_for_env(self, env_id: int):
        """Return only the opaque immutable ref for Motion's current env task."""

        receipt = self._action_ball_task_receipt_for_env(env_id)
        if receipt is None:
            return None
        diagnostic_fast_path = bool(
            getattr(
                self,
                "_action_ball_diagnostic_unauthorized",
                False,
            )
        )
        ref = (
            self._action_ball_task_ref_by_env[env_id]
            if diagnostic_fast_path
            else receipt.task_ref()
        )
        from whole_body_tracking.tasks.tracking.mdp.action_ball_runtime import (
            ActionTaskReceiptRef,
        )

        if type(ref) is not ActionTaskReceiptRef:
            raise RuntimeError("action-ball task emitted a forged opaque ref")
        return ref

    def action_ball_resolve_task_ref(self, ref):
        """Resolve one exact current opaque ref; stale/cross-env refs fail closed."""

        if self._action_ball_fixed_view_enabled:
            raise RuntimeError(
                "immutable fixed-view timing has no task receipt refs"
            )

        from whole_body_tracking.tasks.tracking.mdp.action_ball_runtime import (
            ActionTaskReceiptRef,
        )

        if type(ref) is not ActionTaskReceiptRef:
            raise ValueError("action-ball task resolver requires an exact opaque ref")
        env_id = getattr(ref, "env_id", None)
        if type(env_id) is not int:
            raise ValueError("action-ball task ref has no plain env_id")
        receipt = self._action_ball_task_receipt_for_env(env_id)
        diagnostic_fast_path = bool(
            getattr(
                self,
                "_action_ball_diagnostic_unauthorized",
                False,
            )
        )
        expected_ref = (
            self._action_ball_task_ref_by_env[env_id]
            if diagnostic_fast_path
            else None if receipt is None else receipt.task_ref()
        )
        if receipt is None or expected_ref != ref:
            raise RuntimeError(
                "action-ball task ref is stale or belongs to another generation"
            )
        return receipt


    def _initialize_action_ball_full_mdp_racket_protocol_state(self) -> None:
        """Allocate only fresh device leaf state; never legacy host runtime."""

        if getattr(
            self,
            "_action_ball_continuous_racket_owner_nonce",
            None,
        ) is not None:
            raise RuntimeError("fresh full-MDP Racket state is already initialized")
        if bool(getattr(self, "_action_ball_enabled", False)):
            raise RuntimeError(
                "legacy ActionBall cannot enter the full-MDP device binder"
            )
        # The legacy host runtime used to allocate these rows as a side effect
        # of loading a manifest.  The fresh mode must never load that runtime,
        # but selected reset and the future Device-R05 reveal still need the
        # same fixed-shape device destinations.  Allocate only those leaf-owned
        # tombstones here.  Common command tensors were already constructed by
        # ``__init__`` and are deliberately not recreated.
        float_dtype = self.racket_target_pos_w.dtype
        device = torch.device(self.device)
        fresh_tombstones = (
            ("_action_ball_task_valid", (self.num_envs,), torch.bool, 0),
            (
                "_action_ball_task_wait_total_ticks",
                (self.num_envs,),
                torch.int64,
                0,
            ),
            (
                "_action_ball_task_wait_elapsed_ticks",
                (self.num_envs,),
                torch.int64,
                0,
            ),
            ("_action_ball_action_uid", (self.num_envs,), torch.int64, -1),
            ("_action_ball_action_slot", (self.num_envs,), torch.int64, -1),
            (
                "_action_ball_reset_generation",
                (self.num_envs,),
                torch.int64,
                0,
            ),
            (
                "_action_ball_swing_generation",
                (self.num_envs,),
                torch.int64,
                -1,
            ),
            ("_action_ball_attempt_active", (self.num_envs,), torch.bool, 0),
            (
                "_action_ball_attempt_action",
                (self.num_envs,),
                torch.int64,
                -1,
            ),
            ("_action_ball_attempt_legal", (self.num_envs,), torch.bool, 0),
            ("_action_ball_attempt_hit", (self.num_envs,), torch.bool, 0),
            (
                "_action_ball_resume_reset_exclusion",
                (self.num_envs,),
                torch.bool,
                0,
            ),
            (
                "_counter_rally_return_direction_env_xy",
                (self.num_envs, 2),
                float_dtype,
                0,
            ),
            (
                "_counter_rally_target_baseline_speed_mps",
                (self.num_envs,),
                float_dtype,
                0,
            ),
            (
                "_counter_rally_reward_terms",
                (self.num_envs, 5),
                float_dtype,
                0,
            ),
            ("_counter_rally_accepted", (self.num_envs,), torch.bool, 0),
            (
                "_counter_rally_legal_first_landing",
                (self.num_envs,),
                torch.bool,
                0,
            ),
            (
                "_counter_rally_primary_reason_code",
                (self.num_envs,),
                torch.int64,
                -1,
            ),
            (
                "_action_ball_reference_term_center_latch",
                (self.num_envs,),
                torch.bool,
                1,
            ),
        )
        for name, shape, dtype, fill in fresh_tombstones:
            existing = getattr(self, name, None)
            if existing is not None:
                if (
                    not torch.is_tensor(existing)
                    or tuple(existing.shape) != shape
                    or existing.dtype != dtype
                    or existing.device != device
                ):
                    raise RuntimeError(
                        "fresh full-MDP Racket tombstone surface differs: "
                        f"{name}"
                    )
                continue
            value = torch.full(shape, fill, dtype=dtype, device=device)
            setattr(self, name, value)
        self._action_ball_task_wait_last_advance_step = -1
        self._counter_rally_enabled = False
        self._action_ball_continuous_racket_owner_nonce = object()
        self._action_ball_continuous_racket_mutation_version = 0
        version_device = torch.zeros(
            (1,), dtype=torch.int64, device=self.device
        )
        self._action_ball_continuous_racket_mutation_version_device = (
            version_device
        )
        # Compatibility-only attribute for older snapshots/tests.  It is not
        # an authority: this Racket owner both writes the device chronology and
        # would mint any Tensor-version receipt for it.  The independent global
        # drain consumes the actual device value instead.
        self._action_ball_continuous_racket_mutation_version_device_receipt = None
        self._action_ball_continuous_racket_logical_target_root_sha256 = (
            _action_ball_canonical_sha256(
                {
                    "schema_version": 1,
                    "kind": (
                        "action_ball_full_mdp_racket_"
                        "uninitialized_device_target_tombstone_v1"
                    ),
                }
            )
        )

        self._action_ball_continuous_racket_terminal_epoch_committed = False
        self._action_ball_continuous_racket_observation_scheduled_ordinal = (
            torch.full(
                (self.num_envs,), -1, dtype=torch.int64, device=self.device
            )
        )
        self._action_ball_continuous_racket_observation_task_identity = (
            torch.zeros(
                (self.num_envs, 32), dtype=torch.uint8, device=self.device
            )
        )
        self._action_ball_full_mdp_racket_task_identity = torch.full(
            (self.num_envs,), -1, dtype=torch.int64, device=self.device
        )
        self._action_ball_full_mdp_racket_outcome_shot_index = torch.full(
            (self.num_envs,), -1, dtype=torch.int64, device=self.device
        )
        self._action_ball_full_mdp_racket_ball_generation = torch.full(
            (self.num_envs,), -1, dtype=torch.int64, device=self.device
        )
        self._action_ball_full_mdp_racket_outcome_identity = torch.full(
            (self.num_envs,), -1, dtype=torch.int64, device=self.device
        )
        self._action_ball_full_mdp_racket_ball_identity = torch.full(
            (self.num_envs,), -1, dtype=torch.int64, device=self.device
        )
        self._action_ball_continuous_racket_observation_d05_validator = None
        self._action_ball_continuous_racket_observation_publication_sequence = 0
        self._action_ball_continuous_racket_observation_current_token = None
        self._action_ball_continuous_racket_observation_records = {}
        self._action_ball_continuous_racket_poisoned = False
        self._action_ball_continuous_racket_poison_reason = None
        self._action_ball_continuous_racket_terminal_resolution_total = 0
        self._action_ball_continuous_racket_terminal_resolution_total_device = (
            torch.zeros((1,), dtype=torch.int64, device=self.device)
        )
        self._action_ball_continuous_racket_terminal_resolution_total_device_receipt = (
            _action_ball_continuous_tensor_receipt(
                self._action_ball_continuous_racket_terminal_resolution_total_device
            )
        )
        self._action_ball_continuous_racket_drain_fault_count_device = (
            torch.zeros((1,), dtype=torch.int64, device=self.device)
        )
        self._action_ball_continuous_racket_drain_invariant_count_device = (
            torch.zeros((1,), dtype=torch.int64, device=self.device)
        )
        self._action_ball_continuous_racket_active_ppo_drain_pack = None
        self._action_ball_continuous_racket_drain_poisoned = False
        self._action_ball_continuous_racket_drain_poison_reason = None
        self._action_ball_continuous_racket_drain_last_update_index = -1
        self._action_ball_continuous_racket_drain_last_completed_environment_steps = -1
        self._action_ball_continuous_racket_drain_sequence = 0
        self._action_ball_continuous_racket_drain_last_acknowledged_mutation_version = (
            -1
        )
        self._action_ball_continuous_racket_drain_authority = None
        self._action_ball_continuous_racket_drain_last_acknowledged_receipt = None
        self._action_ball_continuous_racket_checkpoint_live_epoch_receipts = None
        self._action_ball_continuous_racket_checkpoint_live_join_required = True
        self._action_ball_continuous_racket_checkpoint_requires_drain_ack = False
        self._action_ball_continuous_racket_selected_reset_authority = None
        self._action_ball_continuous_racket_selected_reset_prepared_validator = None
        self._action_ball_continuous_racket_selected_reset_r05_validator = None
        self._action_ball_continuous_racket_selected_reset_source_sha256 = None
        self._action_ball_continuous_racket_selected_reset_diagnostic = False
        self._action_ball_continuous_racket_selected_reset_next_serial = 0
        for name in (
            "_action_ball_continuous_racket_selected_reset_stage",
            "_action_ball_continuous_racket_selected_reset_record",
            "_action_ball_continuous_racket_selected_reset_prevalidated",
            "_action_ball_continuous_racket_selected_reset_sealed_afterimage",
            "_action_ball_continuous_racket_selected_reset_commit_token",
            "_action_ball_continuous_racket_selected_reset_completion",
            "_action_ball_continuous_racket_selected_reset_completion_prepared",
        ):
            setattr(self, name, None)
        self._action_ball_full_mdp_device_r05_owner = None
        self._action_ball_full_mdp_racket_epoch_owner = None
        self._action_ball_full_mdp_r03_writer_active = False
        self._action_ball_full_mdp_racket_physical_owner = None
        self._action_ball_full_mdp_racket_mount_sign_table = None
        self._action_ball_full_mdp_racket_selected_rubber_sequence = 0
        self._action_ball_full_mdp_racket_selected_rubber_token = None
        self._action_ball_full_mdp_racket_selected_rubber_view = None
        self._action_ball_continuous_fresh_racket_time_left_receipt = None
        self._action_ball_continuous_fresh_racket_lane_bound = True

    def _bind_action_ball_full_mdp_fresh_racket_resample_timer(self) -> None:
        """Seal the inherited timer for the writer-free fresh command lane."""

        time_left = getattr(self, "time_left", None)
        receipt = _tensor_identity_version_receipt(time_left)
        if (
            type(time_left) is not torch.Tensor
            or not time_left.is_floating_point()
            or time_left.device != torch.device(self.device)
            or tuple(time_left.shape) != (self.num_envs,)
            or not time_left.is_contiguous()
            or receipt is None
        ):
            raise ActionBallContinuousRacketHotRevealHold(
                "fresh Racket requires its exact inherited resample timer"
            )
        # The lean lane has no legacy timer/resample writer.  Materialize the
        # impossible-expiry sentinel once at cold graph binding, then retain
        # the exact tensor object/version across policy ticks.  D05 remains the
        # only writer of Racket task, target, and timing business state.
        time_left.copy_(torch.full_like(time_left, float("inf")))
        receipt = _tensor_identity_version_receipt(time_left)
        if receipt is None:
            raise ActionBallContinuousRacketHotRevealHold(
                "fresh Racket inherited resample timer became unsealable"
            )
        self._action_ball_continuous_fresh_racket_time_left_receipt = receipt

    def bind_action_ball_full_mdp_racket_staging(
        self,
        device_r05_owner: object,
    ) -> None:
        """Construction-bind the fresh Device-R05 Racket leaf only.

        Device-R05's exact current-task/current-shot observation ABI is not
        frozen yet.  Consequently this production binder is a construction
        HOLD before it mints genesis authority or writes any Racket state.
        Focused tests may exercise the private Racket publication core, but
        that is deliberately not a production graph closure.
        """

        if not bool(
            getattr(self, "_action_ball_full_mdp_enabled", False)
        ) or bool(getattr(self, "_action_ball_enabled", False)):
            raise RuntimeError(
                "full-MDP Racket staging requires target_mode=action_ball_full_mdp"
            )
        if device_r05_owner is None:
            raise TypeError("fresh Racket requires one Device-R05 owner")
        import action_ball_continuous_runtime_transaction_device as device_r05

        if type(device_r05_owner) is not device_r05.DeviceR05Owner:
            raise TypeError(
                "fresh Racket requires the exact Device-R05 owner type"
            )
        current_projection = getattr(
            device_r05_owner,
            "action_ball_current_observation_projection",
            None,
        )
        current_validator = getattr(
            device_r05_owner,
            "require_owned_action_ball_current_observation_projection",
            None,
        )
        current_abi_frozen = (
            callable(current_projection)
            and callable(current_validator)
            and getattr(current_projection, "__self__", None)
            is device_r05_owner
            and getattr(current_validator, "__self__", None)
            is device_r05_owner
            and getattr(current_projection, "__func__", None)
            is vars(device_r05.DeviceR05Owner).get(
                "action_ball_current_observation_projection"
            )
            and getattr(current_validator, "__func__", None)
            is vars(device_r05.DeviceR05Owner).get(
                "require_owned_action_ball_current_observation_projection"
            )
        )
        if not current_abi_frozen:
            # Device-R05's independent current-task/shot identity ABI is not
            # frozen yet.  This is a production construction HOLD, before the
            # genesis capability is minted or any Racket destination is copied.
            # A focused Racket fixture may exercise the private publication
            # core, but it cannot bypass this binder or claim graph closure.
            raise ActionBallContinuousRacketObservationHold(
                "fresh Racket production binding awaits the exact Device-R05 "
                "current-observation projection/validator ABI"
            )
        current = getattr(
            self, "_action_ball_full_mdp_device_r05_owner", None
        )
        if current is device_r05_owner:
            return
        if current is not None:
            raise RuntimeError("fresh Racket Device-R05 owner may not be rebound")
        project_genesis = getattr(
            device_r05_owner, "project_owned_genesis_for_child", None
        )
        validate_genesis = getattr(
            device_r05_owner, "require_owned_genesis_projection", None
        )
        if (
            not callable(project_genesis)
            or not callable(validate_genesis)
            or getattr(project_genesis, "__self__", None)
            is not device_r05_owner
            or getattr(project_genesis, "__func__", None)
            is not device_r05.DeviceR05Owner.project_owned_genesis_for_child
            or getattr(validate_genesis, "__self__", None)
            is not device_r05_owner
            or getattr(validate_genesis, "__func__", None)
            is not device_r05.DeviceR05Owner.require_owned_genesis_projection
        ):
            raise TypeError("fresh Racket Device-R05 genesis API differs")
        genesis_capability = project_genesis(owner_kind="racket")
        genesis = validate_genesis(
            genesis_capability,
            owner_kind="racket",
        )
        r05_reset_generation = getattr(genesis, "reset_generation", None)
        if (
            type(genesis) is not device_r05.DeviceR05GenesisView
            or getattr(genesis, "device_r05_owner", None)
            is not device_r05_owner
            or getattr(genesis, "owner_kind", None) != "racket"
            or getattr(genesis, "world_reset_identity", None) is None
            or not torch.is_tensor(r05_reset_generation)
            or r05_reset_generation.dtype != torch.int64
            or r05_reset_generation.device != torch.device(self.device)
            or tuple(r05_reset_generation.shape) != (self.num_envs,)
        ):
            raise RuntimeError(
                "fresh Racket Device-R05 genesis generation differs"
            )
        required = (
            "project_owned_genesis_for_child",
            "require_owned_genesis_projection",
            "require_owned_prepared_true_reset",
            "require_owned_true_reset_receipt",
            "require_owned_terminal_claim_for_child",
            "require_owned_terminal_receipt_for_child",
        )
        if any(
            not callable(getattr(device_r05_owner, name, None))
            for name in required
        ):
            raise TypeError("fresh Racket Device-R05 API surface differs")
        if not bool(
            getattr(self, "_action_ball_continuous_fresh_racket_lane_bound", False)
        ):
            self._initialize_action_ball_full_mdp_racket_protocol_state()
        elif getattr(
            self, "_action_ball_continuous_racket_owner_nonce", None
        ) is None:
            self._initialize_action_ball_full_mdp_racket_protocol_state()
        # Construction-time device copy only: the Racket reset-generation
        # destination must begin on the exact Device-R05 genesis frontier.
        # Keeping a clone avoids a shared-writer alias while letting the later
        # prepared-reset projection prove every selected increment.
        self._action_ball_reset_generation.copy_(r05_reset_generation)
        self._action_ball_full_mdp_device_r05_owner = device_r05_owner
        self._action_ball_continuous_racket_observation_d05_validator = (
            current_validator
        )

    def bind_action_ball_full_mdp_racket_epoch_sources(
        self,
        device_r05_owner: object,
        epoch_owner: object,
    ) -> None:
        """Construction-bind the lean D05/epoch pair for the hot writer.

        The binding carries no receipt, hash, or caller-authored verdict.  D05
        remains the sole source of selected task rows and ``ActionEpochOwner``
        remains the sole fixed-order writer coordinator.  This narrow binder
        deliberately bypasses the legacy observation-receipt graph.
        """

        if getattr(self, "_action_ball_full_mdp_enabled", False) is not True:
            raise ActionBallContinuousRacketHotRevealHold(
                "Racket epoch binding requires action_ball_full_mdp"
            )
        if bool(getattr(self, "_action_ball_enabled", False)):
            raise ActionBallContinuousRacketHotRevealHold(
                "Racket epoch binding rejects legacy ActionBall state"
            )
        import action_ball_continuous_runtime_transaction_device as device_r05
        from whole_body_tracking.tasks.tracking.mdp import (
            action_ball_full_mdp_epoch as epoch,
        )

        if type(device_r05_owner) is not device_r05.DeviceR05Owner:
            raise TypeError("Racket epoch binding requires exact Device-R05 owner")
        if type(epoch_owner) is not epoch.ActionEpochOwner:
            raise TypeError("Racket epoch binding requires exact ActionEpoch owner")
        if (
            getattr(device_r05_owner, "_num_envs", None) != self.num_envs
            or torch.device(getattr(device_r05_owner, "_device", "cpu"))
            != torch.device(self.device)
            or epoch_owner.num_envs != self.num_envs
            or epoch_owner.shot_slot_capacity < 1
            or epoch_owner.device != torch.device(self.device)
        ):
            raise ActionBallContinuousRacketHotRevealHold(
                "Racket epoch sources differ in N, slot capacity, or device"
            )
        accepted_rows = getattr(
            device_r05_owner, "require_owned_action_epoch_accepted", None
        )
        if (
            not callable(accepted_rows)
            or getattr(accepted_rows, "__self__", None) is not device_r05_owner
            or getattr(accepted_rows, "__func__", None)
            is not device_r05.DeviceR05Owner.require_owned_action_epoch_accepted
        ):
            raise TypeError("Racket epoch binding requires exact D05 ACCEPT-row API")
        current_d05 = getattr(self, "_action_ball_full_mdp_device_r05_owner", None)
        current_epoch = getattr(
            self, "_action_ball_full_mdp_racket_epoch_owner", None
        )
        if current_d05 is device_r05_owner and current_epoch is epoch_owner:
            return
        if current_d05 is not None or current_epoch is not None:
            raise RuntimeError("Racket epoch sources may not be rebound")
        project_genesis = getattr(
            device_r05_owner, "project_owned_genesis_for_child", None
        )
        require_genesis = getattr(
            device_r05_owner, "require_owned_genesis_projection", None
        )
        if (
            not callable(project_genesis)
            or not callable(require_genesis)
            or getattr(project_genesis, "__self__", None) is not device_r05_owner
            or getattr(project_genesis, "__func__", None)
            is not device_r05.DeviceR05Owner.project_owned_genesis_for_child
            or getattr(require_genesis, "__self__", None) is not device_r05_owner
            or getattr(require_genesis, "__func__", None)
            is not device_r05.DeviceR05Owner.require_owned_genesis_projection
        ):
            raise TypeError("Racket epoch binding requires exact D05 genesis API")
        # The real full-MDP CommandTerm deliberately leaves this fresh leaf
        # cold until the unique top owner has constructed D05 and ActionEpoch.
        # Initialize only after both exact sources and their callable seams
        # passed validation, but before consuming D05's one-shot genesis view.
        if not bool(
            getattr(self, "_action_ball_continuous_fresh_racket_lane_bound", False)
        ):
            self._initialize_action_ball_full_mdp_racket_protocol_state()
        elif getattr(
            self, "_action_ball_continuous_racket_owner_nonce", None
        ) is None:
            self._initialize_action_ball_full_mdp_racket_protocol_state()
        reset_destination = getattr(self, "_action_ball_reset_generation", None)
        if (
            not torch.is_tensor(reset_destination)
            or reset_destination.dtype != torch.int64
            or reset_destination.device != torch.device(self.device)
            or tuple(reset_destination.shape) != (self.num_envs,)
        ):
            raise TypeError(
                "Racket epoch binding requires exact reset-generation destination"
            )
        genesis_capability = project_genesis(owner_kind="racket")
        genesis = require_genesis(genesis_capability, owner_kind="racket")
        reset_generation = getattr(genesis, "reset_generation", None)
        if (
            type(genesis) is not device_r05.DeviceR05GenesisView
            or genesis.device_r05_owner is not device_r05_owner
            or genesis.owner_kind != "racket"
            or genesis.world_reset_identity is None
            or not torch.is_tensor(reset_generation)
            or reset_generation.dtype != torch.int64
            or reset_generation.device != torch.device(self.device)
            or tuple(reset_generation.shape) != (self.num_envs,)
        ):
            raise ActionBallContinuousRacketHotRevealHold(
                "Racket epoch D05 genesis projection differs"
            )
        reset_destination.copy_(reset_generation)
        self._bind_action_ball_full_mdp_fresh_racket_resample_timer()
        self._action_ball_full_mdp_device_r05_owner = device_r05_owner
        self._action_ball_full_mdp_racket_epoch_owner = epoch_owner

    @torch.no_grad()
    def commit_action_ball_full_mdp_racket_epoch_rows(self, token: object) -> None:
        """Install Racket's full-N D05 ACCEPT after-image exactly once.

        The opaque transaction and ACCEPT classification remain owned by D05
        and ActionEpoch.  Racket derives no row index or verdict: it consumes
        the exact full-N candidate view, combines its shared typed shot-key
        validity with ``task_valid``, and preserves every non-accepted row via
        device ``where`` after-images.  The 27-float Racket slice and 5-float
        Motion timing slice are the only numeric inputs; the Physical slice is
        deliberately outside this writer.
        """

        if bool(getattr(self, "_action_ball_continuous_racket_poisoned", False)):
            raise ActionBallContinuousRacketHotRevealHold(
                "Racket epoch writer is poisoned"
            )
        d05_owner = getattr(self, "_action_ball_full_mdp_device_r05_owner", None)
        epoch_owner = getattr(
            self, "_action_ball_full_mdp_racket_epoch_owner", None
        )
        import action_ball_continuous_runtime_transaction_device as device_r05
        from whole_body_tracking.tasks.tracking.mdp import (
            action_ball_full_mdp_epoch as epoch,
        )

        accepted_rows = getattr(
            d05_owner, "require_owned_action_epoch_accepted", None
        )
        if (
            type(d05_owner) is not device_r05.DeviceR05Owner
            or type(epoch_owner) is not epoch.ActionEpochOwner
            or not callable(accepted_rows)
            or getattr(accepted_rows, "__self__", None) is not d05_owner
            or getattr(accepted_rows, "__func__", None)
            is not device_r05.DeviceR05Owner.require_owned_action_epoch_accepted
        ):
            raise ActionBallContinuousRacketHotRevealHold(
                "Racket epoch writer lost its exact construction sources"
            )

        try:
            # D05 is the sole public ACCEPT-row authority.  Its exact method
            # joins this opaque token to Epoch's transient writer window before
            # returning the typed full-N after-image; Racket has no second
            # phase/mask accessor and derives no caller verdict.
            accepted = accepted_rows(token, owner_kind="racket")
            if (
                type(accepted) is not device_r05.DeviceR05AcceptedRowsView
                or accepted.transaction is not token
                or type(accepted.identity) is not epoch.EpochIdentityPayload
                or type(accepted.clocks) is not epoch.EpochClockPayload
                or type(accepted.task) is not epoch.EpochTaskPayload
            ):
                raise ActionBallContinuousRacketHotRevealHold(
                    "Racket D05 ACCEPT view authority differs"
                )

            device = torch.device(self.device)
            n = self.num_envs
            shot_shape = (n, 1)
            task = accepted.task
            required_rows = (
                (accepted.publication_ordinal, torch.int64, shot_shape),
                (accepted.target_xy_m, torch.float32, (n, 1, 2)),
                (accepted.identity.scheduled_ordinal, torch.int64, shot_shape),
                (accepted.identity.target_generation, torch.int64, shot_shape),
                (accepted.identity.selected_cell, torch.int64, shot_shape),
                (accepted.identity.candidate_identity, torch.int64, shot_shape),
                (accepted.clocks.reveal_tick, torch.int64, shot_shape),
                (accepted.clocks.contact_tick, torch.int64, shot_shape),
                (accepted.clocks.launch_tick, torch.int64, shot_shape),
                (accepted.clocks.deadline_tick, torch.int64, shot_shape),
                (accepted.clocks.next_reveal_tick, torch.int64, shot_shape),
                (task.task_f32, torch.float32, (n, 1, epoch.TASK_F32_WIDTH)),
                (task.task_valid, torch.bool, shot_shape),
                (accepted.rng_counter, torch.int64, shot_shape),
            )
            if any(
                type(value) is not torch.Tensor
                or value.dtype != dtype
                or value.device != device
                or tuple(value.shape) != shape
                or not value.is_contiguous()
                for value, dtype, shape in required_rows
            ):
                raise ActionBallContinuousRacketHotRevealHold(
                    "Racket D05 ACCEPT tensor ABI differs"
                )
            try:
                key = epoch.row_identity.require_action_epoch_shot_key(
                    accepted.identity.shot_key,
                    shape=shot_shape,
                    device=device,
                    label="Racket D05 ACCEPT shot key",
                )
            except Exception as exc:
                raise ActionBallContinuousRacketHotRevealHold(
                    "Racket D05 ACCEPT shot-key ABI differs"
                ) from exc
            origins = getattr(
                getattr(self._env, "scene", None), "env_origins", None
            )
            if (
                type(origins) is not torch.Tensor
                or origins.device != device
                or origins.dtype != self.racket_target_pos_w.dtype
                or tuple(origins.shape) != (n, 3)
                or not origins.is_contiguous()
            ):
                raise ActionBallContinuousRacketHotRevealHold(
                    "Racket epoch writer requires exact live environment origins"
                )

            write_mask = (
                epoch.row_identity.action_epoch_shot_key_valid(key)
                & task.task_valid
            )[:, 0]
            motion_image = task.task_f32[:, 0, : epoch.MOTION_TASK_F32_WIDTH]
            racket_image = task.task_f32[
                :,
                0,
                epoch.MOTION_TASK_F32_WIDTH : (
                    epoch.MOTION_TASK_F32_WIDTH + epoch.RACKET_TASK_F32_WIDTH
                ),
            ]
            initial_tts = motion_image[:, 0].to(dtype=self.time_to_strike.dtype)
            tts_abs = initial_tts.abs()
            pos_window_s = self.cfg.strike_window_pos_s
            wide_window_s = self.cfg.strike_window_wide_s

            def install(destination: torch.Tensor, values: torch.Tensor) -> None:
                mask = write_mask
                while mask.ndim < destination.ndim:
                    mask = mask.unsqueeze(-1)
                destination.copy_(torch.where(mask, values, destination))

            install(self.racket_target_pos_w, origins + racket_image[:, 0:3])
            install(self.racket_target_vel_w, racket_image[:, 3:6])
            install(self.racket_target_normal_w, racket_image[:, 6:9])
            install(self.target_normal_cmd, racket_image[:, 6:9])
            install(
                self._action_ball_ball_contact_target_w,
                origins + racket_image[:, 9:12],
            )
            install(
                self._action_ball_face_center_velocity_target_w,
                racket_image[:, 12:15],
            )
            install(
                self._action_ball_racket_command_quat_w,
                racket_image[:, 15:19],
            )
            install(
                self.base_target_pos_w,
                origins[:, :2] + racket_image[:, 19:21],
            )
            install(self.vb_vel_in_w, racket_image[:, 21:24])
            install(self.vb_spin_in_w, racket_image[:, 24:27])

            # Bind every field of the one portable shot key explicitly.  The
            # layout carries env row; no env_id, digest or publication ordinal
            # is promoted into business identity here.
            install(self._action_ball_reset_generation, key.reset_generation[:, 0])
            install(
                self._action_ball_full_mdp_racket_ball_generation,
                key.ball_generation[:, 0],
            )
            install(self._action_ball_swing_generation, key.ball_generation[:, 0])
            install(self._action_ball_action_uid, key.action_uid[:, 0])
            install(self._action_ball_action_slot, key.action_slot[:, 0])
            install(
                self._action_ball_full_mdp_racket_outcome_shot_index,
                key.shot_index[:, 0],
            )
            install(
                self._action_ball_full_mdp_racket_task_identity,
                key.task_identity[:, 0],
            )
            install(
                self._action_ball_full_mdp_racket_outcome_identity,
                key.outcome_identity[:, 0],
            )
            install(
                self._action_ball_full_mdp_racket_ball_identity,
                key.ball_identity[:, 0],
            )
            install(
                self._action_ball_continuous_racket_observation_scheduled_ordinal,
                accepted.identity.scheduled_ordinal[:, 0],
            )
            install(self._action_ball_task_valid, task.task_valid[:, 0])
            install(
                self._action_ball_attempt_active,
                torch.ones_like(write_mask),
            )
            install(self._action_ball_attempt_action, key.action_slot[:, 0])
            install(
                self._action_ball_attempt_legal,
                torch.zeros_like(write_mask),
            )
            install(
                self._action_ball_attempt_hit,
                torch.zeros_like(write_mask),
            )
            install(self.time_to_strike, initial_tts)
            install(self.pre_strike, initial_tts > 0.0)
            install(
                self.strike_window,
                tts_abs <= float(self.cfg.strike_window_s),
            )
            install(
                self.strike_window_pos,
                tts_abs
                <= float(
                    self.cfg.strike_window_s
                    if pos_window_s is None
                    else pos_window_s
                ),
            )
            install(
                self.strike_window_wide,
                tts_abs
                <= float(
                    self.cfg.strike_window_s
                    if wide_window_s is None
                    else wide_window_s
                ),
            )
            install(
                self._counter_rally_reward_terms,
                torch.zeros_like(self._counter_rally_reward_terms),
            )
            install(
                self._counter_rally_accepted,
                torch.zeros_like(write_mask),
            )
            install(
                self._counter_rally_legal_first_landing,
                torch.zeros_like(write_mask),
            )
            install(
                self._counter_rally_primary_reason_code,
                torch.full_like(key.action_slot[:, 0], -1),
            )
            install(
                self._action_ball_prev_contact_valid,
                torch.zeros_like(write_mask),
            )
        except BaseException:
            if getattr(
                self, "_action_ball_continuous_racket_poison_reason", None
            ) is None:
                self._action_ball_continuous_racket_poison_reason = (
                    "action_epoch_racket_writer_failure"
                )
            self._poison_action_ball_continuous_racket_child()
            raise

    @torch.no_grad()
    def _build_action_ball_full_mdp_racket_action_reference_cold_rows(
        self,
        motion_command: MotionCommand,
        loader: MotionLoader,
    ) -> tuple[
        torch.Tensor,
        torch.Tensor,
        torch.Tensor,
        torch.Tensor,
        torch.Tensor,
        torch.Tensor,
        torch.Tensor,
    ]:
        """Pure cold MotionLoader -> Racket FK rows; installs no state.

        This is the production-shaped extraction seam, separated from the
        legacy reference-target builder because that builder also prints and
        runs target/table/return gates after installing mutable caches.  A
        failed construction here cannot leave a half-ready Racket cache.
        """

        if motion_command is not self._motion():
            raise ActionBallContinuousRacketHotRevealHold(
                "cold Racket action reference Motion binding differs"
            )
        action_count = int(loader.num_segments)
        quat_rows = torch.zeros(
            action_count, 4, dtype=torch.float32, device=self.device
        )
        omega_rows = torch.zeros(
            action_count, 3, dtype=torch.float32, device=self.device
        )
        velocity_rows = torch.zeros_like(omega_rows)
        raw_normal_rows = torch.zeros_like(omega_rows)
        reach_offset_xy_rows = torch.zeros(
            action_count, 2, dtype=torch.float32, device=self.device
        )
        site_position_rows = torch.zeros_like(omega_rows)
        base_root_quat_rows = torch.zeros_like(quat_rows)
        window = max(1, int(self.cfg.clean_strike_vel_window))
        if not bool(self.cfg.clean_reference_strike_velocity):
            raise ActionBallContinuousRacketHotRevealHold(
                "cold Racket action reference requires centered-FD site velocity"
            )
        dt = float(self._env.step_dt)
        if not math.isfinite(dt) or dt <= 0.0:
            raise ActionBallContinuousRacketHotRevealHold(
                "cold Racket action reference requires positive finite step_dt"
            )
        for action_slot in range(action_count):
            strike_step, _phase, seg_start, seg_len = self._strike_frame_for_clip(
                loader, action_slot
            )
            seg_end = seg_start + seg_len - 1
            if self._racket_mode == "body":
                _pos, quat, _lin, omega = self._reference_body_state(
                    loader,
                    strike_step,
                    self._racket_body_index,
                    require_ang_vel=True,
                )
            else:
                wrist_pos, wrist_quat, _wrist_lin, wrist_omega = (
                    self._reference_body_state(
                        loader,
                        strike_step,
                        self._wrist_body_index,
                        require_ang_vel=True,
                    )
                )
                del wrist_pos
                quat = quat_mul(
                    wrist_quat.unsqueeze(0), self._mount_quat[0:1]
                ).squeeze(0)
                omega = wrist_omega
            if omega is None:
                raise ActionBallContinuousRacketHotRevealHold(
                    "cold Racket action reference angular velocity is absent"
                )
            velocity = (
                self._ref_racket_pos_at(
                    loader,
                    strike_step + window,
                    clip_start=seg_start,
                    clip_end=seg_end,
                )
                - self._ref_racket_pos_at(
                    loader,
                    strike_step - window,
                    clip_start=seg_start,
                    clip_end=seg_end,
                )
            ) / (2.0 * window * dt)
            raw_normal = matrix_from_quat(quat.unsqueeze(0))[
                0, :, self.cfg.mount_normal_axis
            ]
            raw_normal = raw_normal / (
                torch.linalg.vector_norm(raw_normal) + 1.0e-6
            )
            contact_position = self._ref_racket_pos_at(
                loader,
                strike_step,
                clip_start=seg_start,
                clip_end=seg_end,
            )
            base_position, base_root_quat, _base_lin_vel, _base_ang_vel = (
                self._reference_body_state(loader, strike_step, 0)
            )
            reach_offset_xy = contact_position[:2] - base_position[:2]
            quat_rows[action_slot].copy_(quat)
            omega_rows[action_slot].copy_(omega)
            velocity_rows[action_slot].copy_(velocity)
            raw_normal_rows[action_slot].copy_(raw_normal)
            reach_offset_xy_rows[action_slot].copy_(reach_offset_xy)
            site_position_rows[action_slot].copy_(contact_position)
            base_root_quat_rows[action_slot].copy_(base_root_quat)
        return (
            quat_rows.contiguous(),
            omega_rows.contiguous(),
            velocity_rows.contiguous(),
            raw_normal_rows.contiguous(),
            reach_offset_xy_rows.contiguous(),
            site_position_rows.contiguous(),
            base_root_quat_rows.contiguous(),
        )

    @torch.no_grad()
    def project_action_ball_full_mdp_racket_action_reference_static_table(
        self,
        _cold_public: object,
    ) -> RacketActionReferenceStaticTableProjection:
        """Return clone-only all-action rows from the sealed cold source."""

        if not bool(getattr(self, "_action_ball_full_mdp_enabled", False)):
            raise ActionBallContinuousRacketHotRevealHold(
                "Racket static action table requires action_ball_full_mdp"
            )
        if bool(getattr(self, "_action_ball_enabled", False)):
            raise ActionBallContinuousRacketHotRevealHold(
                "Racket static action table rejects legacy ActionBall state"
            )
        motion_command = getattr(self, "_motion_term", None)
        if type(motion_command) is not MotionCommand:
            raise ActionBallContinuousRacketHotRevealHold(
                "Racket static action table awaits the exact bound MotionCommand"
            )
        loader = getattr(motion_command, "motion", None)
        if (
            type(loader) is not MotionLoader
            or getattr(loader, "kinematics_contract_exact", None) is not True
            or getattr(loader, "num_segments", None) is None
        ):
            raise ActionBallContinuousRacketHotRevealHold(
                "Racket static action table requires exact schema-2 MotionLoader FK"
            )
        if not callable(_cold_public):
            raise ActionBallContinuousRacketHotRevealHold(
                "Racket static action table cold reader is absent"
            )
        (
            quat,
            omega,
            site_velocity,
            raw_normal,
            reach_offset_xy,
            site_position,
            base_root_quat,
        ) = _cold_public()[1](self, motion_command, loader)
        return RacketActionReferenceStaticTableProjection(
            reference_racket_site_position_w_m=site_position,
            reference_racket_quat_wxyz=quat,
            reference_racket_angular_velocity_w_radps=omega,
            reference_racket_site_velocity_w_mps=site_velocity,
            reference_raw_face_normal_w=raw_normal,
            reference_reach_offset_xy_m=reach_offset_xy,
            reference_base_root_quat_wxyz=base_root_quat,
        )

    @torch.no_grad()
    def initialize_action_ball_full_mdp_racket_action_reference_cold(
        self,
        _cold_public: object,
    ) -> None:
        """Materialize the immutable per-action FK table off the hot path.

        The extractor is a pure local MotionLoader/Racket FK computation.  It
        does not reuse the legacy mutable reference-target cache, run target
        return gates, or install any state until every row validates.  It mints
        no receipt and accepts no caller tensor/profile.  Callers must never
        invoke this from physics/reward/observation/optimizer/D05 callbacks.
        """

        if not bool(getattr(self, "_action_ball_full_mdp_enabled", False)):
            raise ActionBallContinuousRacketHotRevealHold(
                "cold Racket action reference requires action_ball_full_mdp"
            )
        if bool(getattr(self, "_action_ball_enabled", False)):
            raise ActionBallContinuousRacketHotRevealHold(
                "cold Racket action reference rejects legacy ActionBall state"
            )
        motion_command = self._motion()
        if type(motion_command) is not MotionCommand:
            raise ActionBallContinuousRacketHotRevealHold(
                "cold Racket action reference awaits exact MotionCommand"
            )
        loader = getattr(motion_command, "motion", None)
        if (
            type(loader) is not MotionLoader
            or getattr(loader, "kinematics_contract_exact", None) is not True
        ):
            raise ActionBallContinuousRacketHotRevealHold(
                "cold Racket action reference requires exact schema-2 MotionLoader FK"
            )
        if not callable(_cold_public):
            raise ActionBallContinuousRacketHotRevealHold(
                "cold Racket action reference reader is absent"
            )
        if _cold_public()[0](
            self, motion_command, loader
        ):
            return
        self._install_action_ball_full_mdp_racket_action_reference_cold_source(
            motion_command, loader
        )

    # Freeze the exact builder identity at class definition.  The second
    # closure becomes the one exact construction callpoint itself: it accepts
    # no rows, proof tensor, digest, or caller builder.  In particular there is
    # no separately published ``seal`` helper that tests/callers can combine
    # with a monkeypatched production builder.
    (
        _action_ball_full_mdp_racket_action_reference_cold_public_methods,
        _install_action_ball_full_mdp_racket_action_reference_cold_source,
    ) = _make_racket_action_reference_cold_registry(
        _build_action_ball_full_mdp_racket_action_reference_cold_rows
    )
    (
        project_action_ball_full_mdp_racket_action_reference_static_table,
        initialize_action_ball_full_mdp_racket_action_reference_cold,
    ) = _bind_racket_action_reference_cold_reader(
        project_action_ball_full_mdp_racket_action_reference_static_table,
        initialize_action_ball_full_mdp_racket_action_reference_cold,
        _action_ball_full_mdp_racket_action_reference_cold_public_methods,
    )

    def bind_action_ball_full_mdp_racket_selected_rubber_physical_owner(
        self,
        physical_owner: object,
    ) -> None:
        """Construction-bind the sole Physical N×K lifecycle source.

        Racket owns which mounted face an admitted action selects.  It does not
        own flight activity, keys, generations, or slots.  Those facts must
        come directly from the exact Physical owner; accepting a caller mask,
        digest, or diagnostic scene projection here would only check caller
        self-consistency and cannot authorize PhysX attribution.
        """

        from whole_body_tracking.tasks.tracking.mdp import (
            action_ball_physical_flight_device as physical,
        )

        if not bool(getattr(self, "_action_ball_full_mdp_enabled", False)):
            raise ActionBallContinuousRacketSelectedRubberHold(
                "selected-rubber Physical binding requires action_ball_full_mdp"
            )
        if type(physical_owner) is not physical.ActionBallPhysicalFlightDeviceOwner:
            raise TypeError(
                "selected-rubber authority requires the exact Physical owner"
            )
        allocation = getattr(
            physical_owner, "action_epoch_physics_fact_allocation", None
        )
        require_allocation = getattr(
            physical_owner,
            "require_owned_action_epoch_physics_fact_allocation",
            None,
        )
        if (
            not callable(allocation)
            or not callable(require_allocation)
            or getattr(allocation, "__self__", None) is not physical_owner
            or getattr(allocation, "__func__", None)
            is not vars(physical.ActionBallPhysicalFlightDeviceOwner).get(
                "action_epoch_physics_fact_allocation"
            )
            or getattr(require_allocation, "__self__", None) is not physical_owner
            or getattr(require_allocation, "__func__", None)
            is not vars(physical.ActionBallPhysicalFlightDeviceOwner).get(
                "require_owned_action_epoch_physics_fact_allocation"
            )
            or getattr(physical_owner, "num_envs", None) != self.num_envs
            or torch.device(getattr(physical_owner, "device", "cpu"))
            != torch.device(self.device)
        ):
            raise ActionBallContinuousRacketSelectedRubberHold(
                "selected-rubber Physical owner API or device differs"
            )
        current = getattr(
            self, "_action_ball_full_mdp_racket_physical_owner", None
        )
        if current is physical_owner:
            return
        if current is not None:
            raise RuntimeError("selected-rubber Physical owner may not be rebound")
        signs_cfg = tuple(
            getattr(self.cfg, "mount_normal_sign_per_clip", ()) or ()
        )
        if signs_cfg:
            sign_values = tuple(int(value) for value in signs_cfg)
        else:
            motion_owner = self._motion()
            action_count = getattr(
                getattr(motion_owner, "motion", None), "num_segments", None
            )
            if type(action_count) is not int or action_count < 1:
                raise ActionBallContinuousRacketSelectedRubberHold(
                    "selected-rubber cold action count is absent"
                )
            sign_values = tuple(
                int(self.cfg.mount_normal_sign) for _ in range(action_count)
            )
        if not sign_values or any(value not in (-1, 1) for value in sign_values):
            raise ActionBallContinuousRacketSelectedRubberHold(
                "selected-rubber cold mount-sign table differs"
            )
        sign_table = torch.tensor(
            sign_values, dtype=torch.int8, device=torch.device(self.device)
        ).contiguous()
        if getattr(
            self, "_action_ball_full_mdp_racket_mount_sign_table", None
        ) is not None:
            raise RuntimeError("selected-rubber mount-sign table may not be rebound")
        self._action_ball_full_mdp_racket_mount_sign_table = sign_table
        self._action_ball_full_mdp_racket_physical_owner = physical_owner

    @torch.no_grad()
    def action_ball_full_mdp_action_epoch_selected_rubber_view(
        self,
    ) -> ActionBallFullMdpActionEpochSelectedRubberView:
        """Derive the exact live Physical K-grid face from bound owners only.

        Physical owns which environment occupies which flight slot and keeps
        its allocation view active only inside ``launch_action_epoch``.
        ActionEpoch owns the immutable current action identity.  Racket owns
        the cold mount-sign table.  Joining those three sources here prevents
        a scene/caller supplied mask, slot, face, digest, or verdict from
        becoming attribution authority.
        """

        if getattr(self, "_action_ball_full_mdp_enabled", False) is not True:
            raise ActionBallContinuousRacketSelectedRubberHold(
                "ActionEpoch selected-rubber view requires action_ball_full_mdp"
            )
        if getattr(self, "_action_ball_enabled", False) is True:
            raise ActionBallContinuousRacketSelectedRubberHold(
                "ActionEpoch selected-rubber view rejects legacy ActionBall"
            )
        if getattr(self, "_action_ball_continuous_racket_poisoned", False) is True:
            raise ActionBallContinuousRacketSelectedRubberHold(
                "ActionEpoch selected-rubber view rejects poisoned Racket"
            )
        physical_owner = getattr(
            self, "_action_ball_full_mdp_racket_physical_owner", None
        )
        epoch_owner = getattr(
            self, "_action_ball_full_mdp_racket_epoch_owner", None
        )
        from whole_body_tracking.tasks.tracking.mdp import (
            action_ball_full_mdp_epoch as epoch,
            action_ball_physical_flight_device as physical,
        )

        allocation_method = getattr(
            physical_owner, "action_epoch_physics_fact_allocation", None
        )
        require_method = getattr(
            physical_owner,
            "require_owned_action_epoch_physics_fact_allocation",
            None,
        )
        if (
            type(physical_owner) is not physical.ActionBallPhysicalFlightDeviceOwner
            or type(epoch_owner) is not epoch.ActionEpochOwner
            or getattr(physical_owner, "_action_epoch_owner", None) is not epoch_owner
            or not callable(allocation_method)
            or not callable(require_method)
            or getattr(allocation_method, "__self__", None) is not physical_owner
            or getattr(allocation_method, "__func__", None)
            is not (
                physical.ActionBallPhysicalFlightDeviceOwner.
                action_epoch_physics_fact_allocation
            )
            or getattr(require_method, "__self__", None) is not physical_owner
            or getattr(require_method, "__func__", None)
            is not (
                physical.ActionBallPhysicalFlightDeviceOwner.
                require_owned_action_epoch_physics_fact_allocation
            )
        ):
            raise ActionBallContinuousRacketSelectedRubberHold(
                "ActionEpoch selected-rubber construction owners differ"
            )
        try:
            allocation = require_method(allocation_method())
        except BaseException as exc:
            raise ActionBallContinuousRacketSelectedRubberHold(
                "ActionEpoch selected-rubber Physical allocation is inactive or stale"
            ) from exc
        if (
            type(allocation) is not physical.ActionEpochPhysicsFactAllocationProjection
            or allocation.physical_owner is not physical_owner
            or allocation.epoch_owner is not epoch_owner
        ):
            raise ActionBallContinuousRacketSelectedRubberHold(
                "ActionEpoch selected-rubber Physical allocation owner differs"
            )

        active = allocation.active_mask
        shape = (self.num_envs, physical_owner.flight_capacity)
        required = (
            (active, torch.bool),
            (allocation.flight_slot, torch.int64),
            (allocation.ball_generation, torch.int64),
            (allocation.action_uid, torch.int64),
            (allocation.reset_generation, torch.int64),
            (allocation.action_slot, torch.int64),
            (allocation.task_identity, torch.int64),
        )
        if any(
            type(value) is not torch.Tensor
            or value.dtype != dtype
            or value.device != torch.device(self.device)
            or tuple(value.shape) != shape
            or not value.is_contiguous()
            for value, dtype in required
        ):
            raise ActionBallContinuousRacketSelectedRubberHold(
                "ActionEpoch selected-rubber Physical allocation ABI differs"
            )
        current_shot = epoch_owner.project_current_shot()
        phase = current_shot.phase
        epoch_active = phase.eq(epoch.PHASE_REVEAL_COMMITTED) | phase.eq(
            epoch.PHASE_LAUNCH_SETTLED
        )
        expected_action_uid = current_shot.shot_key.action_uid[:, None]
        expected_action_slot = current_shot.shot_key.action_slot[:, None]
        expected_task_identity = current_shot.shot_key.task_identity[:, None]
        expected_reset_generation = current_shot.shot_key.reset_generation[:, None]
        epoch_mismatch = active & (
            ~current_shot.slot_valid[:, None]
            | ~epoch_active[:, None]
            | allocation.action_uid.ne(expected_action_uid)
            | allocation.action_slot.ne(expected_action_slot)
            | allocation.task_identity.ne(expected_task_identity)
            | allocation.reset_generation.ne(expected_reset_generation)
            | allocation.ball_generation.lt(0)
        )
        fixed_slot_grid = torch.arange(
            physical_owner.flight_capacity,
            dtype=torch.int64,
            device=torch.device(self.device),
        ).unsqueeze(0).expand(shape)
        allocation_mismatch = active & allocation.flight_slot.ne(fixed_slot_grid)

        sign_table = getattr(
            self, "_action_ball_full_mdp_racket_mount_sign_table", None
        )
        if (
            type(sign_table) is not torch.Tensor
            or sign_table.dtype != torch.int8
            or sign_table.device != torch.device(self.device)
            or sign_table.ndim != 1
            or sign_table.shape[0] < 1
            or not sign_table.is_contiguous()
        ):
            raise ActionBallContinuousRacketSelectedRubberHold(
                "ActionEpoch selected-rubber cold mount-sign table is absent"
            )
        rubber, rubber_bad = _action_ball_full_mdp_expected_rubber_from_action_slot(
            allocation.action_slot, active, sign_table
        )
        invalid = epoch_mismatch | allocation_mismatch | rubber_bad
        # Cross-owner mismatch is row telemetry, not a process assertion.
        # Neutralize only the bad face; the scene keeps Physical's active mask
        # and maps active+inactive to its binding fault, which Physical publishes
        # as the named postphysics-producer fault with zero facts.
        rubber = torch.where(
            invalid,
            torch.full_like(
                rubber, _ACTION_BALL_FULL_MDP_RUBBER_INACTIVE
            ),
            rubber,
        )
        return ActionBallFullMdpActionEpochSelectedRubberView(
            racket_owner=self,
            physical_owner=physical_owner,
            epoch_owner=epoch_owner,
            active_mask=active.detach().clone(),
            expected_rubber=rubber.detach().clone(),
        )

    def publish_action_ball_full_mdp_selected_rubber_authority(
        self,
    ) -> ActionBallFullMdpRacketSelectedRubberToken:
        """Publish exact current selected-rubber truth or HOLD before mutation.

        The only successful publication joins Racket's retained installed
        action/task/generation image with the directly bound Physical N×K
        lifecycle/key/generation/slot image.  The fresh hot Racket writer is
        not reachable yet, so a production call currently stops before token,
        sequence, or registry mutation instead of manufacturing a success from
        tombstones or a caller-authored hash.
        """

        if bool(
            getattr(self, "_action_ball_continuous_racket_poisoned", False)
        ):
            raise ActionBallContinuousRacketSelectedRubberHold(
                "selected-rubber authority cannot publish from poisoned Racket"
            )
        if (
            getattr(self, "_action_ball_full_mdp_device_r05_owner", None) is None
            or not bool(
                getattr(
                    self,
                    "_action_ball_continuous_racket_terminal_epoch_committed",
                    False,
                )
            )
        ):
            raise ActionBallContinuousRacketSelectedRubberHold(
                "selected-rubber authority awaits a real Device-R05 ACCEPT "
                "commit in the fresh Racket hot writer"
            )
        physical_owner = getattr(
            self, "_action_ball_full_mdp_racket_physical_owner", None
        )
        if physical_owner is None:
            raise ActionBallContinuousRacketSelectedRubberHold(
                "selected-rubber authority has no exact bound Physical owner"
            )
        if torch.device(self.device).type != "cpu":
            # CUDA cannot authorize a mutation by launching an async assert and
            # continuing.  The production path must consume the same packed
            # D05/global-boundary row that gates the other four writers; until
            # that causal join exists, stop before snapshot clones or token
            # publication rather than adding a hidden D2H synchronization.
            raise ActionBallContinuousRacketSelectedRubberHold(
                "selected-rubber CUDA publication awaits the packed global "
                "boundary; no async assert may authorize this publication"
            )

        from whole_body_tracking.tasks.tracking.mdp import (
            action_ball_physical_flight_device as physical,
        )

        snapshot = physical_owner.scene_snapshot()
        if (
            type(snapshot) is not physical.PhysicalFlightSceneSnapshotNK
            or type(snapshot.owner_mutation_version) is not int
            or snapshot.owner_mutation_version < 0
        ):
            raise ActionBallContinuousRacketSelectedRubberHold(
                "selected-rubber Physical snapshot is stale or foreign"
            )
        shape = tuple(snapshot.published_to_runtime.shape)
        if (
            len(shape) != 2
            or shape[0] != self.num_envs
            or tuple(snapshot.outcome_key_sha256.shape) != shape + (32,)
            or tuple(snapshot.ball_generation.shape) != shape
            or snapshot.published_to_runtime.dtype != torch.bool
            or snapshot.outcome_key_sha256.dtype != torch.uint8
            or snapshot.ball_generation.dtype != torch.int64
            or snapshot.published_to_runtime.device != torch.device(self.device)
            or snapshot.outcome_key_sha256.device != torch.device(self.device)
            or snapshot.ball_generation.device != torch.device(self.device)
        ):
            raise ActionBallContinuousRacketSelectedRubberHold(
                "selected-rubber Physical N×K snapshot ABI differs"
            )
        active = snapshot.published_to_runtime & ~snapshot.physically_parked
        if bool(
            torch.any(
                active
                & (
                    snapshot.owner_fault
                    | torch.eq(snapshot.outcome_key_sha256, 0).all(dim=-1)
                    | (snapshot.ball_generation < 0)
                )
            )
        ):
            raise ActionBallContinuousRacketSelectedRubberHold(
                "selected-rubber Physical active identity is untrusted"
            )

        action_slot_env = self._action_ball_action_slot
        action_uid_env = self._action_ball_action_uid
        reset_generation_env = self._action_ball_reset_generation
        swing_generation_env = self._action_ball_swing_generation
        task_sha_env = self._action_ball_continuous_racket_observation_task_identity
        task_valid_env = self._action_ball_task_valid
        if any(
            not torch.is_tensor(value)
            for value in (
                action_slot_env,
                action_uid_env,
                reset_generation_env,
                swing_generation_env,
                task_sha_env,
                task_valid_env,
            )
        ):
            raise ActionBallContinuousRacketSelectedRubberHold(
                "selected-rubber retained Racket identity surface is absent"
            )
        k = shape[1]
        action_slot = action_slot_env.unsqueeze(1).expand(shape)
        action_uid = action_uid_env.unsqueeze(1).expand(shape)
        reset_generation = reset_generation_env.unsqueeze(1).expand(shape)
        swing_generation = swing_generation_env.unsqueeze(1).expand(shape)
        task_sha = task_sha_env.unsqueeze(1).expand(shape + (32,))
        retained_bad = active & (
            ~task_valid_env.unsqueeze(1)
            | (action_slot < 0)
            | (action_uid < 0)
            | (reset_generation < 1)
            | (swing_generation < 0)
            | torch.eq(task_sha, 0).all(dim=-1)
            | (snapshot.ball_generation != swing_generation)
        )
        sign_table = torch.tensor(
            tuple(int(value) for value in self._action_ball_mount_signs),
            dtype=torch.int8,
            device=self.device,
        )
        rubber, rubber_bad = _action_ball_full_mdp_expected_rubber_from_action_slot(
            action_slot, active, sign_table
        )
        if bool(torch.any(retained_bad | rubber_bad)):
            raise ActionBallContinuousRacketSelectedRubberHold(
                "selected-rubber Racket/Physical installed identity join differs"
            )

        flight_slot = torch.arange(
            k, dtype=torch.int64, device=self.device
        ).unsqueeze(0).expand(shape)
        sequence = getattr(
            self, "_action_ball_full_mdp_racket_selected_rubber_sequence", None
        )
        if type(sequence) is not int or sequence < 0:
            raise ActionBallContinuousRacketSelectedRubberHold(
                "selected-rubber publication chronology differs"
            )
        token = object.__new__(ActionBallFullMdpRacketSelectedRubberToken)
        view = ActionBallFullMdpRacketSelectedRubberView(
            token=token,
            racket_owner=self,
            publication_identity=object(),
            publication_sequence=sequence + 1,
            physical_owner_mutation_version=snapshot.owner_mutation_version,
            active_mask=active.detach().clone(),
            expected_rubber=rubber.detach().clone(),
            full_key_sha256=snapshot.outcome_key_sha256.detach().clone(),
            ball_generation=snapshot.ball_generation.detach().clone(),
            flight_slot=flight_slot.detach().clone(),
            reset_generation=reset_generation.detach().clone(),
            swing_generation=swing_generation.detach().clone(),
            action_uid=action_uid.detach().clone(),
            action_slot=action_slot.detach().clone(),
            task_receipt_sha256=task_sha.detach().clone(),
        )
        self._action_ball_full_mdp_racket_selected_rubber_sequence = sequence + 1
        self._action_ball_full_mdp_racket_selected_rubber_token = token
        self._action_ball_full_mdp_racket_selected_rubber_view = view
        return token

    def require_owned_action_ball_full_mdp_selected_rubber_authority(
        self,
        token: object,
    ) -> ActionBallFullMdpRacketSelectedRubberView:
        """Validate the exact current token and return fresh clone-only tensors."""

        current = getattr(
            self, "_action_ball_full_mdp_racket_selected_rubber_token", None
        )
        view = getattr(
            self, "_action_ball_full_mdp_racket_selected_rubber_view", None
        )
        if (
            type(token) is not ActionBallFullMdpRacketSelectedRubberToken
            or token is not current
            or type(view) is not ActionBallFullMdpRacketSelectedRubberView
            or view.token is not token
            or view.racket_owner is not self
        ):
            raise ActionBallContinuousRacketSelectedRubberHold(
                "selected-rubber authority is stale, foreign, or replayed"
            )
        physical_owner = getattr(
            self, "_action_ball_full_mdp_racket_physical_owner", None
        )
        if physical_owner is None:
            raise ActionBallContinuousRacketSelectedRubberHold(
                "selected-rubber authority lost its bound Physical owner"
            )
        current_physical = physical_owner.scene_snapshot()
        current_active = (
            current_physical.published_to_runtime
            & ~current_physical.physically_parked
        )
        if (
            current_physical.owner_mutation_version
            != view.physical_owner_mutation_version
            or not torch.equal(
                current_active, view.active_mask
            )
            or not torch.equal(
                current_physical.outcome_key_sha256, view.full_key_sha256
            )
            or not torch.equal(
                current_physical.ball_generation, view.ball_generation
            )
        ):
            raise ActionBallContinuousRacketSelectedRubberHold(
                "selected-rubber Physical lifecycle changed after publication"
            )
        return ActionBallFullMdpRacketSelectedRubberView(
            token=token,
            racket_owner=self,
            publication_identity=view.publication_identity,
            publication_sequence=view.publication_sequence,
            physical_owner_mutation_version=view.physical_owner_mutation_version,
            active_mask=view.active_mask.detach().clone(),
            expected_rubber=view.expected_rubber.detach().clone(),
            full_key_sha256=view.full_key_sha256.detach().clone(),
            ball_generation=view.ball_generation.detach().clone(),
            flight_slot=view.flight_slot.detach().clone(),
            reset_generation=view.reset_generation.detach().clone(),
            swing_generation=view.swing_generation.detach().clone(),
            action_uid=view.action_uid.detach().clone(),
            action_slot=view.action_slot.detach().clone(),
            task_receipt_sha256=view.task_receipt_sha256.detach().clone(),
        )

    def _action_ball_continuous_racket_observation_source(
        self,
    ) -> dict[str, torch.Tensor]:
        """Validate and return the retained installed-task Racket surface.

        The per-environment task digest and scheduled ordinal are deliberately
        separate owner-private retained fields.  They are not reconstructed
        from numeric destinations, and this leaf never manufactures Device-
        R05's independent shot index.  The fresh reveal writer must install
        these fields before the production observation binder can be opened.
        """

        device = torch.device(self.device)
        n = self.num_envs
        specifications = {
            "reset_generation": (
                "_action_ball_reset_generation",
                (n,),
                torch.int64,
            ),
            "swing_generation": (
                "_action_ball_swing_generation",
                (n,),
                torch.int64,
            ),
            "scheduled_ordinal": (
                "_action_ball_continuous_racket_observation_scheduled_ordinal",
                (n,),
                torch.int64,
            ),
            "action_uid": ("_action_ball_action_uid", (n,), torch.int64),
            "action_slot": ("_action_ball_action_slot", (n,), torch.int64),
            "task_identity": (
                "_action_ball_continuous_racket_observation_task_identity",
                (n, 32),
                torch.uint8,
            ),
            "task_valid": ("_action_ball_task_valid", (n,), torch.bool),
            "landing_target_xy_table": (
                "_vb_target_xy_per_env", (n, 2), self.racket_target_pos_w.dtype,
            ),
            "desired_position_w": (
                "racket_target_pos_w", (n, 3), self.racket_target_pos_w.dtype,
            ),
            "desired_velocity_w": (
                "racket_target_vel_w", (n, 3), self.racket_target_pos_w.dtype,
            ),
            "desired_face_normal_w": (
                "target_normal_cmd", (n, 3), self.racket_target_pos_w.dtype,
            ),
            "desired_base_xy_w": (
                "base_target_pos_w", (n, 2), self.racket_target_pos_w.dtype,
            ),
            "ball_contact_target_w": (
                "_action_ball_ball_contact_target_w",
                (n, 3),
                self.racket_target_pos_w.dtype,
            ),
            "face_center_velocity_target_w": (
                "_action_ball_face_center_velocity_target_w",
                (n, 3),
                self.racket_target_pos_w.dtype,
            ),
            "command_quaternion_wxyz": (
                "_action_ball_racket_command_quat_w",
                (n, 4),
                self.racket_target_pos_w.dtype,
            ),
            "incoming_velocity_w": (
                "vb_vel_in_w", (n, 3), self.racket_target_pos_w.dtype,
            ),
            "incoming_spin_w": (
                "vb_spin_in_w", (n, 3), self.racket_target_pos_w.dtype,
            ),
            "time_to_contact_s": (
                "time_to_strike", (n,), self.racket_target_pos_w.dtype,
            ),
        }
        values: dict[str, torch.Tensor] = {}
        for public_name, (private_name, shape, dtype) in specifications.items():
            value = getattr(self, private_name, None)
            if (
                not torch.is_tensor(value)
                or tuple(value.shape) != shape
                or value.dtype != dtype
                or value.device != device
            ):
                raise ActionBallContinuousRacketObservationHold(
                    "continuous Racket retained observation field differs: "
                    f"{private_name}"
                )
            values[public_name] = value

        # An invalid/hidden row may still be at its construction tombstone.
        # Only rows that this owner calls installed must carry a complete
        # retained identity.  The future R08 join still has to compare those
        # rows with Device-R05/Motion; Racket does not self-certify that join.
        identity_invalid = values["task_valid"] & (
            (values["reset_generation"] < 1)
            | (values["swing_generation"] < 0)
            | (values["scheduled_ordinal"] < 0)
            | (values["action_uid"] < 0)
            | (values["action_slot"] < 0)
            | ~torch.any(values["task_identity"] != 0, dim=1)
        )
        if bool(torch.any(identity_invalid)):
            raise RuntimeError(
                "continuous Racket retained installed-task identity is incomplete"
            )
        numeric_names = (
            "landing_target_xy_table",
            "desired_position_w",
            "desired_velocity_w",
            "desired_face_normal_w",
            "desired_base_xy_w",
            "ball_contact_target_w",
            "face_center_velocity_target_w",
            "command_quaternion_wxyz",
            "incoming_velocity_w",
            "incoming_spin_w",
            "time_to_contact_s",
        )
        if any(
            not bool(torch.isfinite(values[name]).all())
            for name in numeric_names
        ):
            raise RuntimeError(
                "continuous Racket retained observation numerics are nonfinite"
            )
        return values

    def _publish_action_ball_continuous_racket_observation_for_test(
        self,
    ) -> ActionBallContinuousRacketObservationToken:
        """Mint a focused-test publication without claiming Device-R05 closure.

        This seam is intentionally private and refuses any owner that completed
        the production Device-R05 binder.  It proves this leaf's clone/stale/
        replay behavior only; it is not a production writer callpoint.
        """

        if (
            getattr(self, "_action_ball_full_mdp_device_r05_owner", None)
            is not None
            or getattr(
                self,
                "_action_ball_continuous_racket_observation_d05_validator",
                None,
            )
            is not None
        ):
            raise RuntimeError(
                "continuous Racket test observation seam cannot replace the "
                "production Device-R05 join"
            )
        common_step = getattr(self._env, "common_step_counter", None)
        mutation_version = getattr(
            self, "_action_ball_continuous_racket_mutation_version", None
        )
        sequence = getattr(
            self,
            "_action_ball_continuous_racket_observation_publication_sequence",
            None,
        )
        records = getattr(
            self, "_action_ball_continuous_racket_observation_records", None
        )
        if (
            type(common_step) is not int
            or common_step < 0
            or type(mutation_version) is not int
            or mutation_version < 0
            or type(sequence) is not int
            or sequence < 0
            or type(records) is not dict
        ):
            raise RuntimeError(
                "continuous Racket observation publication chronology differs"
            )
        values = self._action_ball_continuous_racket_observation_source()
        next_sequence = sequence + 1
        publication_identity = object()
        token = object.__new__(ActionBallContinuousRacketObservationToken)
        record = _ActionBallContinuousRacketObservationRecord(
            token=token,
            publication_identity=publication_identity,
            publication_sequence=next_sequence,
            common_step=common_step,
            mutation_version=mutation_version,
            values={
                name: value.detach().clone() for name, value in values.items()
            },
        )
        old = getattr(
            self, "_action_ball_continuous_racket_observation_current_token", None
        )
        if old is not None:
            old_record = records.get(old)
            if type(old_record) is _ActionBallContinuousRacketObservationRecord:
                old_record.stage = "stale"
        records.clear()
        records[token] = record
        self._action_ball_continuous_racket_observation_publication_sequence = (
            next_sequence
        )
        self._action_ball_continuous_racket_observation_current_token = token
        return token

    def action_ball_continuous_racket_observation_projection(
        self,
    ) -> ActionBallContinuousRacketObservationToken:
        """Return the retained empty R08 token or fail on the unfrozen D05 ABI."""

        d05_owner = getattr(
            self, "_action_ball_full_mdp_device_r05_owner", None
        )
        d05_validator = getattr(
            self,
            "_action_ball_continuous_racket_observation_d05_validator",
            None,
        )
        if d05_owner is None or not callable(d05_validator):
            raise ActionBallContinuousRacketObservationHold(
                "continuous Racket production observation awaits the exact "
                "Device-R05 current identity ABI"
            )
        # The callback signature and exact current view are intentionally not
        # guessed here.  Once Device-R05 freezes them, this method must invoke
        # that exact owner-issued projection before returning the Racket token.
        raise ActionBallContinuousRacketObservationHold(
            "continuous Racket production Device-R05 current identity callback "
            "is not frozen"
        )

    def require_owned_action_ball_continuous_racket_observation_projection(
        self,
        token: ActionBallContinuousRacketObservationToken,
    ) -> ActionBallContinuousRacketObservationView:
        """Authenticate the current token and return fresh clone-only tensors."""

        records = getattr(
            self, "_action_ball_continuous_racket_observation_records", None
        )
        record = (
            records.get(token)
            if type(records) is dict
            and type(token) is ActionBallContinuousRacketObservationToken
            else None
        )
        current = getattr(
            self, "_action_ball_continuous_racket_observation_current_token", None
        )
        if (
            type(token) is not ActionBallContinuousRacketObservationToken
            or type(record) is not _ActionBallContinuousRacketObservationRecord
            or record.token is not token
            or token is not current
            or record.stage != "issued"
            or record.publication_sequence
            != getattr(
                self,
                "_action_ball_continuous_racket_observation_publication_sequence",
                None,
            )
        ):
            raise RuntimeError(
                "continuous Racket observation token is forged, replayed, or stale"
            )
        if (
            getattr(self, "_action_ball_full_mdp_device_r05_owner", None)
            is not None
            or getattr(
                self,
                "_action_ball_continuous_racket_observation_d05_validator",
                None,
            )
            is not None
        ):
            raise ActionBallContinuousRacketObservationHold(
                "continuous Racket production observation cannot validate "
                "current identity before the exact Device-R05 ABI is frozen"
            )
        common_step = getattr(self._env, "common_step_counter", None)
        mutation_version = getattr(
            self, "_action_ball_continuous_racket_mutation_version", None
        )
        current_values = self._action_ball_continuous_racket_observation_source()
        if (
            common_step != record.common_step
            or mutation_version != record.mutation_version
            or any(
                not torch.equal(current_values[name], retained)
                for name, retained in record.values.items()
            )
        ):
            raise RuntimeError(
                "continuous Racket observation token has stale current task or numerics"
            )
        view = ActionBallContinuousRacketObservationView(
            racket_owner=self,
            publication_identity=record.publication_identity,
            publication_sequence=record.publication_sequence,
            common_step=record.common_step,
            **{
                name: value.detach().clone()
                for name, value in record.values.items()
            },
        )
        record.stage = "consumed"
        self._action_ball_continuous_racket_observation_current_token = None
        return view

    def require_owned_action_ball_continuous_racket_observation(
        self,
        token: ActionBallContinuousRacketObservationToken,
    ) -> ActionBallContinuousRacketObservationView:
        """R08 exact-provider-table spelling for the projection validator."""

        return self.require_owned_action_ball_continuous_racket_observation_projection(
            token
        )

    def bind_action_ball_continuous_racket_selected_reset(
        self,
        r05_owner: object,
        *,
        prepared_reset_validator,
        r05_receipt_validator,
        authority_source_sha256: str | None = None,
        diagnostic: bool = False,
    ) -> None:
        """Construction-bind the exact Device-R05 selected-reset authority.

        The only admitted validators are Device-R05's frozen
        ``require_owned_prepared_true_reset`` and
        ``require_owned_true_reset_receipt`` capabilities.  The deprecated
        source-hash argument grants no authority.  Production uses exact owner
        and bound-method identity; explicit diagnostic fixtures remain
        non-authoritative test doubles.
        """

        if not bool(
            getattr(
                self,
                "_action_ball_continuous_fresh_racket_lane_bound",
                False,
            )
        ):
            raise RuntimeError(
                "continuous Racket selected reset requires the fresh lane"
            )
        import action_ball_continuous_runtime_transaction_device as device_r05

        if r05_owner is None:
            raise TypeError(
                "continuous Racket selected reset authority is required"
            )
        if (
            not callable(prepared_reset_validator)
            or not callable(r05_receipt_validator)
            or getattr(prepared_reset_validator, "__self__", None)
            is not r05_owner
            or getattr(r05_receipt_validator, "__self__", None)
            is not r05_owner
        ):
            raise TypeError(
                "continuous Racket selected reset requires exact Device-R05 validators"
            )
        if type(diagnostic) is not bool:
            raise TypeError(
                "continuous Racket selected reset diagnostic flag must be exact"
            )
        if diagnostic is False and (
            type(r05_owner) is not device_r05.DeviceR05Owner
            or getattr(prepared_reset_validator, "__func__", None)
            is not device_r05.DeviceR05Owner.require_owned_prepared_true_reset
            or getattr(r05_receipt_validator, "__func__", None)
            is not device_r05.DeviceR05Owner.require_owned_true_reset_receipt
            or not bool(getattr(self, "_action_ball_full_mdp_enabled", False))
            or getattr(self, "_action_ball_full_mdp_device_r05_owner", None)
            is not r05_owner
        ):
            raise RuntimeError(
                "Racket selected reset lacks exact Device-R05 methods and binder"
            )
        del authority_source_sha256
        current = self._action_ball_continuous_racket_selected_reset_authority
        if current is not None:
            if (
                current is r05_owner
                and getattr(
                    self._action_ball_continuous_racket_selected_reset_prepared_validator,
                    "__self__",
                    None,
                )
                is r05_owner
                and getattr(
                    self._action_ball_continuous_racket_selected_reset_prepared_validator,
                    "__func__",
                    None,
                )
                is getattr(prepared_reset_validator, "__func__", None)
                and getattr(
                    self._action_ball_continuous_racket_selected_reset_r05_validator,
                    "__self__",
                    None,
                )
                is r05_owner
                and getattr(
                    self._action_ball_continuous_racket_selected_reset_r05_validator,
                    "__func__",
                    None,
                )
                is getattr(r05_receipt_validator, "__func__", None)
                and self._action_ball_continuous_racket_selected_reset_diagnostic
                is diagnostic
            ):
                return
            raise RuntimeError(
                "continuous Racket selected reset authority may not be rebound"
            )
        self._action_ball_continuous_racket_selected_reset_authority = r05_owner
        self._action_ball_continuous_racket_selected_reset_prepared_validator = (
            prepared_reset_validator
        )
        self._action_ball_continuous_racket_selected_reset_r05_validator = (
            r05_receipt_validator
        )
        self._action_ball_continuous_racket_selected_reset_source_sha256 = (
            None
        )
        self._action_ball_continuous_racket_selected_reset_diagnostic = (
            diagnostic
        )

    def _action_ball_continuous_racket_selected_reset_destinations(
        self,
    ) -> tuple[tuple[str, str, torch.Tensor], ...]:
        """Return the complete fixed-shape device tombstone surface."""

        rows = []
        for name, disposition in (
            _ACTION_BALL_CONTINUOUS_RACKET_SELECTED_RESET_TOMBSTONES
        ):
            value = getattr(self, name, None)
            if (
                not torch.is_tensor(value)
                or value.ndim < 1
                or value.shape[0] != self.num_envs
                or value.device != torch.device(self.device)
            ):
                raise RuntimeError(
                    "continuous Racket selected-reset destination differs: "
                    f"{name}"
                )
            if disposition == "identity_quaternion" and (
                value.ndim != 2 or value.shape[1] != 4
            ):
                raise RuntimeError(
                    "continuous Racket selected-reset quaternion destination differs"
                )
            rows.append((name, disposition, value))
        return tuple(rows)

    def _action_ball_continuous_racket_require_strike_fact_reset_idle(
        self,
    ) -> object | None:
        """Return the exact construction-bound fresh R03 reset child.

        Fresh full-MDP always constructs R03 under this Racket writer and the
        factory cold-binds both owners to one ActionEpoch.  Selected reset must
        therefore join that independent writer, not reject merely because the
        feature is enabled and not silently clear only Racket-local mirrors.
        Legacy/diagnostic R03 has no such transaction and remains outside this
        production reset path.
        """

        if not bool(
            getattr(
                self,
                "_action_ball_strike_fact_device_enabled",
                False,
            )
        ):
            return None
        if getattr(self, "_action_ball_full_mdp_enabled", False) is not True:
            raise RuntimeError(
                "continuous Racket selected reset requires the fresh R03 owner"
            )
        from .action_ball_strike_fact_device import (
            ActionBallStrikeFactDeviceCoordinator,
            OBSERVATION_PROJECTION_MODE_FRESH_FULL_MDP,
        )

        owner = getattr(
            self, "_action_ball_strike_fact_device_coordinator", None
        )
        epoch_owner = getattr(
            self, "_action_ball_full_mdp_racket_epoch_owner", None
        )
        if (
            type(owner) is not ActionBallStrikeFactDeviceCoordinator
            or getattr(owner, "_observation_projection_mode", None)
            != OBSERVATION_PROJECTION_MODE_FRESH_FULL_MDP
            or owner.action_epoch_owner is not epoch_owner
            or getattr(owner, "_epoch_racket_owner", None) is not self
            or any(
                getattr(owner, name, None) is not None
                for name in (
                    "_epoch_arm_identity",
                    "_epoch_arm_source_step",
                    "_epoch_arm_mask",
                    "_epoch_arm_vectors",
                    "_epoch_arm_shot_key",
                    "_epoch_arm_slot",
                    "_epoch_arm_d05_identity",
                    "_active_full_mdp_reward_publication",
                    "_active_pre_optimizer_pack",
                )
            )
            or owner.pre_optimizer_poisoned
            or getattr(
                self,
                "_action_ball_strike_fact_expected_publish_step",
                None,
            )
            is not None
        ):
            raise RuntimeError(
                "continuous Racket selected reset requires one settled exact fresh R03 owner"
            )
        return owner

    @staticmethod
    def _action_ball_continuous_racket_reset_fill(
        destination: torch.Tensor,
        disposition: str,
    ) -> torch.Tensor:
        """Create one full-shape tombstone without inspecting device values."""

        if disposition == "zero":
            return torch.zeros_like(destination)
        if disposition == "one":
            return torch.ones_like(destination)
        if disposition == "negative_one":
            return torch.full_like(destination, -1)
        if disposition == "increment_one":
            if destination.dtype == torch.bool or destination.is_floating_point():
                raise RuntimeError(
                    "continuous Racket selected-reset generation destination differs"
                )
            return torch.clamp(
                destination,
                max=torch.iinfo(destination.dtype).max - 1,
            ) + torch.ones_like(destination)
        if disposition == "identity_quaternion":
            result = torch.zeros_like(destination)
            result[:, 0] = 1
            return result
        raise RuntimeError(
            "continuous Racket selected-reset disposition is unknown"
        )

    def stage_action_ball_continuous_racket_selected_reset(
        self,
        prepared_true_reset: object,
    ) -> ActionBallContinuousRacketSelectedResetStage:
        """Validate one Device-R05 prepare and retain device-only reset facts."""

        if self._action_ball_continuous_racket_poisoned:
            raise RuntimeError("continuous Racket child owner is poisoned")
        if (
            self._action_ball_continuous_racket_selected_reset_authority
            is None
            or not callable(
                self._action_ball_continuous_racket_selected_reset_prepared_validator
            )
        ):
            raise RuntimeError(
                "continuous Racket selected reset has no bound authority"
            )
        retained_completion = (
            self._action_ball_continuous_racket_selected_reset_completion
        )
        retained_completion_prepared = (
            self._action_ball_continuous_racket_selected_reset_completion_prepared
        )
        if (
            retained_completion is not None
            or retained_completion_prepared is not None
        ):
            # The top owner alone consumes this ACK after joining all four
            # leaves.  A new reset may never erase it as a side effect of
            # staging; retain both identities verbatim for that consumer.
            raise RuntimeError(
                "continuous Racket selected reset has an unconsumed completion"
            )
        if (
            self._action_ball_continuous_racket_selected_reset_stage
            is not None
            or self._action_ball_continuous_racket_selected_reset_prevalidated
            is not None
            or self._action_ball_continuous_racket_selected_reset_commit_token
            is not None
            or self._action_ball_continuous_racket_active_ppo_drain_pack
            is not None
        ):
            raise RuntimeError(
                "continuous Racket has an open reveal or selected-reset epoch"
            )
        strike_fact_owner = (
            self._action_ball_continuous_racket_require_strike_fact_reset_idle()
        )
        try:
            projection = (
                self._action_ball_continuous_racket_selected_reset_prepared_validator(
                    prepared_true_reset,
                    owner_kind="racket",
                )
            )
        except Exception as exc:
            raise RuntimeError(
                "continuous Racket selected-reset Device-R05 prepare is not owner-issued"
            ) from exc
        if not self._action_ball_continuous_racket_selected_reset_diagnostic:
            import action_ball_continuous_runtime_transaction_device as device_r05

            if type(projection) is not (
                device_r05.DeviceR05PreparedTrueResetProjection
            ):
                raise RuntimeError(
                    "continuous Racket selected-reset projection type differs"
                )
        selected_mask = getattr(projection, "selected_mask", None)
        generation_before = getattr(projection, "generation_before", None)
        generation_after = getattr(projection, "generation_after", None)
        if (
            getattr(projection, "prepared_true_reset", None)
            is not prepared_true_reset
            or getattr(projection, "owner_kind", None) != "racket"
            or getattr(projection, "prepared_identity", None) is None
            or getattr(projection, "reset_event_identity", None) is None
            or not torch.is_tensor(generation_before)
            or not torch.is_tensor(generation_after)
            or generation_before.dtype != torch.int64
            or generation_after.dtype != torch.int64
            or generation_before.device != torch.device(self.device)
            or generation_after.device != torch.device(self.device)
            or tuple(generation_before.shape) != (self.num_envs,)
            or tuple(generation_after.shape) != (self.num_envs,)
        ):
            raise RuntimeError(
                "continuous Racket selected-reset projection differs"
            )
        if (
            not torch.is_tensor(selected_mask)
            or selected_mask.shape != (self.num_envs,)
            or selected_mask.dtype != torch.bool
            or selected_mask.device != torch.device(self.device)
        ):
            raise RuntimeError(
                "continuous Racket selected-reset device selection differs"
            )
        destinations = (
            self._action_ball_continuous_racket_selected_reset_destinations()
        )
        logical_root = _action_ball_continuous_sha256_hex(
            self._action_ball_continuous_racket_logical_target_root_sha256,
            label="Racket logical committed-target root",
        )
        serial = (
            self._action_ball_continuous_racket_selected_reset_next_serial
        )
        mutation_version = self._action_ball_continuous_racket_mutation_version
        if (
            type(serial) is not int
            or serial < 0
            or type(mutation_version) is not int
            or not 0 <= mutation_version < (1 << 63) - 1
        ):
            raise RuntimeError(
                "continuous Racket selected-reset chronology differs"
            )
        stage_sha256 = _action_ball_canonical_sha256(
            {
                "schema_version": 1,
                "kind": "action_ball_continuous_racket_selected_reset_stage_v1",
                "serial": serial,
                "owner_mutation_version": mutation_version,
                "logical_committed_target_root_sha256_before": logical_root,
                "ordered_tombstones": [
                    {"name": name, "disposition": disposition}
                    for name, disposition, _value in destinations
                ],
            }
        )
        # Clone every Device-R05 tensor immediately.  The projection is
        # caller-visible, but the retained reset facts and their storage are
        # owner-private; the opaque stage returned below contains no Tensor.
        # Do not mint Tensor-version receipts for the clones or Racket-owned
        # destinations: that same-writer seal rejects inference tensors and
        # proves no independent reset fact.
        selected_mask = selected_mask.detach().clone()
        generation_before = generation_before.detach().clone()
        generation_after = generation_after.detach().clone()
        stage = ActionBallContinuousRacketSelectedResetStage(
            _owner_nonce=self._action_ball_continuous_racket_owner_nonce,
            serial=serial,
            owner_mutation_version=mutation_version,
            logical_committed_target_root_sha256_before=logical_root,
            stage_sha256=stage_sha256,
        )
        record = _ActionBallContinuousRacketSelectedResetRecord(
            stage=stage,
            prepared_true_reset=prepared_true_reset,
            prepared_identity=projection.prepared_identity,
            selected_mask=selected_mask,
            reset_generation_before=generation_before,
            reset_generation_after=generation_after,
            strike_fact_owner=strike_fact_owner,
        )
        self._action_ball_continuous_racket_selected_reset_next_serial = (
            serial + 1
        )
        self._action_ball_continuous_racket_selected_reset_stage = stage
        self._action_ball_continuous_racket_selected_reset_record = record
        return stage

    prepare_action_ball_continuous_racket_selected_reset = (
        stage_action_ball_continuous_racket_selected_reset
    )

    # The constructed top owner uses the same short verb as the physical/R06
    # leaves.  Keep the long class-qualified verb for diagnostics and focused
    # ownership tests while exposing one symmetric integration seam.
    prepare_selected_reset = (
        stage_action_ball_continuous_racket_selected_reset
    )

    def _validate_action_ball_continuous_racket_selected_reset_stage(
        self,
        stage: ActionBallContinuousRacketSelectedResetStage,
    ) -> None:
        """Authenticate one current reset stage without a host synchronization."""

        record = self._action_ball_continuous_racket_selected_reset_record
        if (
            self._action_ball_continuous_racket_poisoned
            or type(stage)
            is not ActionBallContinuousRacketSelectedResetStage
            or self._action_ball_continuous_racket_selected_reset_stage
            is not stage
            or type(record)
            is not _ActionBallContinuousRacketSelectedResetRecord
            or record.stage is not stage
            or stage._owner_nonce
            is not self._action_ball_continuous_racket_owner_nonce
            or self._action_ball_continuous_racket_mutation_version
            != stage.owner_mutation_version
            or self._action_ball_continuous_racket_logical_target_root_sha256
            != stage.logical_committed_target_root_sha256_before
            or not torch.is_tensor(record.selected_mask)
            or record.selected_mask.dtype != torch.bool
            or record.selected_mask.device != torch.device(self.device)
            or tuple(record.selected_mask.shape) != (self.num_envs,)
            or not torch.is_tensor(record.reset_generation_before)
            or not torch.is_tensor(record.reset_generation_after)
            or record.reset_generation_before.dtype != torch.int64
            or record.reset_generation_after.dtype != torch.int64
            or record.reset_generation_before.device != torch.device(self.device)
            or record.reset_generation_after.device != torch.device(self.device)
            or tuple(record.reset_generation_before.shape) != (self.num_envs,)
            or tuple(record.reset_generation_after.shape) != (self.num_envs,)
        ):
            raise RuntimeError(
                "continuous Racket selected-reset stage is forged or stale"
            )
        if (
            self._action_ball_continuous_racket_require_strike_fact_reset_idle()
            is not record.strike_fact_owner
        ):
            raise RuntimeError(
                "continuous Racket selected-reset R03 owner drifted"
            )
        destinations = (
            self._action_ball_continuous_racket_selected_reset_destinations()
        )
        expected_stage_sha256 = _action_ball_canonical_sha256(
            {
                "schema_version": 1,
                "kind": "action_ball_continuous_racket_selected_reset_stage_v1",
                "serial": stage.serial,
                "owner_mutation_version": stage.owner_mutation_version,
                "logical_committed_target_root_sha256_before": (
                    stage.logical_committed_target_root_sha256_before
                ),
                "ordered_tombstones": [
                    {"name": name, "disposition": disposition}
                    for name, disposition, _value in destinations
                ],
            }
        )
        if expected_stage_sha256 != stage.stage_sha256:
            raise RuntimeError(
                "continuous Racket selected-reset stage root mutated"
            )

    def finalize_action_ball_continuous_racket_selected_reset(
        self,
        stage: ActionBallContinuousRacketSelectedResetStage,
    ) -> ActionBallContinuousRacketPrevalidatedSelectedReset:
        """Prebuild every masked after-image before the pure commit."""

        record = self._action_ball_continuous_racket_selected_reset_record
        if (
            type(stage)
            is not ActionBallContinuousRacketSelectedResetStage
            or self._action_ball_continuous_racket_selected_reset_stage
            is not stage
            or type(record)
            is not _ActionBallContinuousRacketSelectedResetRecord
            or record.stage is not stage
        ):
            raise RuntimeError(
                "continuous Racket selected-reset stage is forged or stale"
            )
        try:
            self._validate_action_ball_continuous_racket_selected_reset_stage(
                stage
            )
        except BaseException:
            # An exact current handle plus failed validation is owner-state
            # drift, not a caller typo.  Retain the first durable fault and do
            # not permit this reset epoch to retry.
            self._poison_action_ball_continuous_racket_child()
            raise
        if (
            self._action_ball_continuous_racket_selected_reset_prevalidated
            is not None
            or self._action_ball_continuous_racket_selected_reset_sealed_afterimage
            is not None
        ):
            raise RuntimeError(
                "continuous Racket selected reset is already prevalidated"
            )
        mask = record.selected_mask
        reset_generation = self._action_ball_reset_generation
        if reset_generation.dtype != torch.int64:
            raise RuntimeError(
                "continuous Racket selected-reset generation destination differs"
            )
        # Device-resident validation is a settlement fault, not a rollback
        # gate.  Once Device-R05 has issued the selected mask, leaving an old
        # task/target reachable is less safe than completing the tombstone
        # cleanup.  Record the durable fault in the same stream, then prebuild
        # the owner-issued selected reset regardless.  The opaque child/global
        # reset capabilities deliberately make no health claim; the sole
        # global drain rejects this bit before the next optimizer boundary.
        # The device result cannot be observed here without an extra D2H.  Mark
        # the checkpoint frontier conservatively before evaluating it.  Even a
        # later precommit abort must cross the sole global drain once: only its
        # exact ACK proves that this device validation produced no fault row.
        self._action_ball_continuous_racket_checkpoint_requires_drain_ack = True
        int64_max = torch.iinfo(torch.int64).max
        generation_increment_allowed = (
            (~mask) | (record.reset_generation_before < int64_max)
        )
        incremented_generation = torch.clamp(
            record.reset_generation_before,
            max=int64_max - 1,
        ) + torch.ones_like(record.reset_generation_before)
        safe_generation_after = torch.where(
            mask & (record.reset_generation_before < int64_max),
            incremented_generation,
            record.reset_generation_before,
        )
        validation_ok = (
            torch.any(mask)
            & torch.all(
                reset_generation == record.reset_generation_before
            )
            & torch.all(generation_increment_allowed)
            & torch.all(
                record.reset_generation_after
                == safe_generation_after
            )
        )
        validation_fault = (~validation_ok).to(dtype=torch.int64).reshape(1)
        self._action_ball_continuous_racket_drain_fault_count_device.bitwise_or_(
            validation_fault
        )
        swaps = []
        for name, disposition, destination in (
            self._action_ball_continuous_racket_selected_reset_destinations()
        ):
            if name == "_action_ball_reset_generation":
                # Never publish an authority-provided wrapped generation on
                # the settlement path.  A mismatch is already in the same
                # device fault row above; the safe after-image saturates at
                # MAX so a selected task cannot alias an old generation.
                fill = safe_generation_after
            else:
                fill = self._action_ball_continuous_racket_reset_fill(
                    destination, disposition
                )
            expanded_mask = mask.reshape(
                (self.num_envs,) + (1,) * (destination.ndim - 1)
            )
            after = torch.where(expanded_mask, fill, destination)
            swaps.append((name, destination, after))
        mutation_version_after = stage.owner_mutation_version + 1
        prevalidated = ActionBallContinuousRacketPrevalidatedSelectedReset(
            _owner_nonce=self._action_ball_continuous_racket_owner_nonce,
            serial=stage.serial,
            stage_sha256=stage.stage_sha256,
        )
        logical_root_after = _action_ball_canonical_sha256(
            {
                "schema_version": 1,
                "kind": (
                    "action_ball_continuous_racket_"
                    "selected_reset_tombstone_v1"
                ),
                "parent_root_sha256": (
                    stage.logical_committed_target_root_sha256_before
                ),
                "selected_reset_stage_sha256": stage.stage_sha256,
                "owner_mutation_version": stage.owner_mutation_version + 1,
            }
        )
        self._action_ball_continuous_racket_selected_reset_sealed_afterimage = (
            _ActionBallContinuousRacketSealedSelectedResetAfterImage(
                prevalidated=prevalidated,
                stage=stage,
                swaps=tuple(swaps),
                mutation_version_after=mutation_version_after,
                logical_root_after=logical_root_after,
            )
        )
        self._action_ball_continuous_racket_selected_reset_prevalidated = (
            prevalidated
        )
        return prevalidated

    arm_prevalidated_action_ball_continuous_racket_selected_reset = (
        finalize_action_ball_continuous_racket_selected_reset
    )

    arm_prevalidated_selected_reset = (
        finalize_action_ball_continuous_racket_selected_reset
    )

    def abort_prevalidated_action_ball_continuous_racket_selected_reset(
        self,
        value: (
            ActionBallContinuousRacketSelectedResetStage
            | ActionBallContinuousRacketPrevalidatedSelectedReset
        ),
    ) -> None:
        """Release an exact precommit lease without changing live tensors."""

        stage = self._action_ball_continuous_racket_selected_reset_stage
        prevalidated = (
            self._action_ball_continuous_racket_selected_reset_prevalidated
        )
        if (
            self._action_ball_continuous_racket_poisoned
            or stage is None
            or not (value is stage or value is prevalidated)
            or self._action_ball_continuous_racket_selected_reset_commit_token
            is not None
        ):
            raise RuntimeError(
                "continuous Racket selected-reset abort requires its exact precommit handle"
            )
        self._action_ball_continuous_racket_selected_reset_stage = None
        self._action_ball_continuous_racket_selected_reset_record = None
        self._action_ball_continuous_racket_selected_reset_prevalidated = None
        self._action_ball_continuous_racket_selected_reset_sealed_afterimage = (
            None
        )

    abort_prevalidated_selected_reset = (
        abort_prevalidated_action_ball_continuous_racket_selected_reset
    )

    def commit_prevalidated_action_ball_continuous_racket_selected_reset(
        self,
        prevalidated: ActionBallContinuousRacketPrevalidatedSelectedReset,
    ) -> ActionBallContinuousRacketSelectedResetCommitToken:
        """Publish only prebuilt device after-images; failure is poison-only."""

        stage = self._action_ball_continuous_racket_selected_reset_stage
        active = (
            self._action_ball_continuous_racket_selected_reset_prevalidated
        )
        sealed = (
            self._action_ball_continuous_racket_selected_reset_sealed_afterimage
        )
        if (
            self._action_ball_continuous_racket_poisoned
            or type(prevalidated)
            is not ActionBallContinuousRacketPrevalidatedSelectedReset
            or prevalidated is not active
            or prevalidated._owner_nonce
            is not self._action_ball_continuous_racket_owner_nonce
            or stage is None
            or prevalidated.serial != stage.serial
            or prevalidated.stage_sha256 != stage.stage_sha256
            or type(sealed)
            is not _ActionBallContinuousRacketSealedSelectedResetAfterImage
            or sealed.prevalidated is not prevalidated
            or sealed.stage is not stage
            or self._action_ball_continuous_racket_selected_reset_commit_token
            is not None
        ):
            self._poison_action_ball_continuous_racket_child()
            raise RuntimeError(
                "continuous Racket selected-reset prevalidated token differs"
            )
        try:
            # No tensor/receipt validator belongs below the top-level
            # irreversible arm.  All such work happened before ``sealed`` was
            # published; this loop merely consumes the owner-private copies.
            for _name, destination, after in sealed.swaps:
                destination.copy_(after)
            self._action_ball_continuous_racket_mutation_version_device.add_(1)
            self._action_ball_continuous_racket_mutation_version = (
                sealed.mutation_version_after
            )
            self._action_ball_continuous_racket_logical_target_root_sha256 = (
                sealed.logical_root_after
            )
            token = ActionBallContinuousRacketSelectedResetCommitToken(
                _owner_nonce=self._action_ball_continuous_racket_owner_nonce,
                serial=stage.serial,
                stage_sha256=stage.stage_sha256,
            )
            self._action_ball_continuous_racket_selected_reset_commit_token = (
                token
            )
            return token
        except BaseException:
            self._poison_action_ball_continuous_racket_child()
            raise

    commit_prevalidated_selected_reset = (
        commit_prevalidated_action_ball_continuous_racket_selected_reset
    )

    def require_owned_selected_reset_commit(
        self,
        commit_token: object,
        *,
        expected_prepared_true_reset: object,
    ) -> ActionBallContinuousRacketSelectedResetCommitToken:
        """Repeatably validate Racket's exact pre-R05 child commit identity."""

        stage = self._action_ball_continuous_racket_selected_reset_stage
        record = self._action_ball_continuous_racket_selected_reset_record
        retained = (
            self._action_ball_continuous_racket_selected_reset_commit_token
        )
        if (
            self._action_ball_continuous_racket_poisoned
            or type(commit_token)
            is not ActionBallContinuousRacketSelectedResetCommitToken
            or commit_token is not retained
            or commit_token._owner_nonce
            is not self._action_ball_continuous_racket_owner_nonce
            or stage is None
            or type(record)
            is not _ActionBallContinuousRacketSelectedResetRecord
            or record.stage is not stage
            or record.prepared_true_reset is not expected_prepared_true_reset
            or commit_token.serial != stage.serial
            or commit_token.stage_sha256 != stage.stage_sha256
        ):
            raise RuntimeError(
                "continuous Racket selected-reset commit token is stale or foreign"
            )
        return commit_token

    def complete_action_ball_continuous_racket_selected_reset_after_r05(
        self,
        commit_token: ActionBallContinuousRacketSelectedResetCommitToken,
        r05_receipt: object,
    ) -> ActionBallContinuousRacketSelectedResetCompletionToken:
        """Validate exact Device-R05-last and mint one opaque local ACK."""

        stage = self._action_ball_continuous_racket_selected_reset_stage
        record = self._action_ball_continuous_racket_selected_reset_record
        active = (
            self._action_ball_continuous_racket_selected_reset_commit_token
        )
        if (
            self._action_ball_continuous_racket_poisoned
            or type(commit_token)
            is not ActionBallContinuousRacketSelectedResetCommitToken
            or commit_token is not active
            or commit_token._owner_nonce
            is not self._action_ball_continuous_racket_owner_nonce
            or stage is None
            or type(record)
            is not _ActionBallContinuousRacketSelectedResetRecord
            or record.stage is not stage
            or commit_token.serial != stage.serial
            or commit_token.stage_sha256 != stage.stage_sha256
            or not callable(
                self._action_ball_continuous_racket_selected_reset_r05_validator
            )
            or self._action_ball_continuous_racket_selected_reset_completion
            is not None
        ):
            self._poison_action_ball_continuous_racket_child()
            raise RuntimeError(
                "continuous Racket selected-reset completion token is stale or foreign"
            )
        try:
            owned = (
                self._action_ball_continuous_racket_selected_reset_r05_validator(
                    r05_receipt,
                    expected_prepared_true_reset=(
                        record.prepared_true_reset
                    ),
                )
            )
        except Exception as exc:
            self._poison_action_ball_continuous_racket_child()
            raise RuntimeError(
                "continuous Racket R05 selected-reset receipt is stale or foreign"
            ) from exc
        if owned is not r05_receipt:
            self._poison_action_ball_continuous_racket_child()
            raise RuntimeError(
                "continuous Racket R05 selected-reset acknowledgement differs"
            )
        completion = ActionBallContinuousRacketSelectedResetCompletionToken(
            _owner_nonce=self._action_ball_continuous_racket_owner_nonce,
            _completion_identity=object(),
        )
        self._action_ball_continuous_racket_selected_reset_stage = None
        self._action_ball_continuous_racket_selected_reset_record = None
        self._action_ball_continuous_racket_selected_reset_prevalidated = None
        self._action_ball_continuous_racket_selected_reset_sealed_afterimage = (
            None
        )
        self._action_ball_continuous_racket_selected_reset_commit_token = None
        self._action_ball_continuous_racket_selected_reset_completion = completion
        self._action_ball_continuous_racket_selected_reset_completion_prepared = (
            record.prepared_true_reset
        )
        return completion

    def require_owned_selected_reset_completion(
        self,
        completion: object,
        *,
        expected_prepared_true_reset: object,
    ) -> ActionBallContinuousRacketSelectedResetCompletionToken:
        """Repeatably validate the latest exact opaque Racket reset ACK."""

        retained = self._action_ball_continuous_racket_selected_reset_completion
        if (
            self._action_ball_continuous_racket_poisoned
            or type(completion)
            is not ActionBallContinuousRacketSelectedResetCompletionToken
            or completion is not retained
            or completion._owner_nonce
            is not self._action_ball_continuous_racket_owner_nonce
            or expected_prepared_true_reset
            is not self._action_ball_continuous_racket_selected_reset_completion_prepared
        ):
            raise RuntimeError(
                "continuous Racket selected-reset completion token is stale or foreign"
            )
        return completion

    def consume_owned_selected_reset_completion(
        self,
        completion: object,
        *,
        expected_prepared_true_reset: object,
    ) -> ActionBallContinuousRacketSelectedResetCompletionToken:
        """Let the top owner consume the exact validated Racket ACK once."""

        owned = self.require_owned_selected_reset_completion(
            completion,
            expected_prepared_true_reset=expected_prepared_true_reset,
        )
        self._action_ball_continuous_racket_selected_reset_completion = None
        self._action_ball_continuous_racket_selected_reset_completion_prepared = (
            None
        )
        return owned

    complete_selected_reset_after_r05 = (
        complete_action_ball_continuous_racket_selected_reset_after_r05
    )


    def _action_ball_reject_legacy_fresh_lane(self, operation: str) -> None:
        """Fail before a legacy producer mutates fresh continuous owner state."""

        if type(operation) is not str or not operation:
            raise TypeError("fresh continuous Racket operation must be named")
        if bool(
            getattr(
                self,
                "_action_ball_continuous_fresh_racket_lane_bound",
                False,
            )
        ):
            raise RuntimeError(
                "fresh continuous Racket lane rejects legacy "
                f"{operation}; use the Device-R05/ActionEpoch row transaction"
            )


    def _poison_action_ball_continuous_racket_child(self) -> None:
        """Sticky-poison one Racket owner protocol violation."""

        self._action_ball_continuous_racket_poisoned = True
        fault_count = getattr(
            self,
            "_action_ball_continuous_racket_drain_fault_count_device",
            None,
        )
        if (
            torch.is_tensor(fault_count)
            and fault_count.dtype == torch.int64
            and tuple(fault_count.shape) == (1,)
        ):
            # This is the durable device witness exported by the next global
            # drain (if the process is still auditable).  It is deliberately a
            # sticky bit: once fail-stop is entered, no later path may clear it.
            fault_count.fill_(1)
        active_drain = getattr(
            self,
            "_action_ball_continuous_racket_active_ppo_drain_pack",
            None,
        )
        if type(active_drain) is _ActionBallContinuousRacketPreparedPpoDrainPack:
            active_drain.stage = "poisoned"
        if getattr(
            self,
            "_action_ball_continuous_racket_poison_reason",
            None,
        ) is None:
            self._action_ball_continuous_racket_poison_reason = (
                "internal_racket_owner_protocol_violation"
            )
        self._action_ball_continuous_racket_terminal_epoch_committed = False
        self._action_ball_continuous_racket_selected_reset_stage = None
        self._action_ball_continuous_racket_selected_reset_record = None
        self._action_ball_continuous_racket_selected_reset_prevalidated = None
        self._action_ball_continuous_racket_selected_reset_sealed_afterimage = (
            None
        )
        self._action_ball_continuous_racket_selected_reset_commit_token = None
        self._action_ball_continuous_racket_selected_reset_completion = None
        self._action_ball_continuous_racket_selected_reset_completion_prepared = (
            None
        )


    def poison_global_reveal_epoch(self, reason: str) -> None:
        """Idempotently fail-stop this leaf without obstructing peer poison."""

        if bool(
            getattr(
                self,
                "_action_ball_continuous_racket_poisoned",
                False,
            )
        ):
            return
        self._action_ball_continuous_racket_poison_reason = (
            reason
            if type(reason) is str and bool(reason.strip())
            else "invalid_global_reveal_poison_reason"
        )
        self._poison_action_ball_continuous_racket_child()

    @staticmethod
    def _action_ball_continuous_racket_exact_drain_index(
        value: object,
        *,
        label: str,
    ) -> int:
        if type(value) is not int or value < 0:
            raise RuntimeError(f"continuous Racket {label} must be nonnegative int")
        return value

    def _action_ball_continuous_racket_drain_leaf_idle(self) -> bool:
        return not any(
            value is not None
            for value in (
                getattr(
                    self,
                    "_action_ball_continuous_racket_observation_current_token",
                    None,
                ),
                self._action_ball_continuous_racket_selected_reset_stage,
                self._action_ball_continuous_racket_selected_reset_prevalidated,
                self._action_ball_continuous_racket_selected_reset_commit_token,
                self._action_ball_continuous_racket_selected_reset_completion,
            )
        )

    def _action_ball_continuous_racket_checkpoint_live_tensor_receipts(
        self,
    ) -> tuple[tuple[str, tuple[object, ...]], ...]:
        """Seal the actual Racket destination epoch without a host read.

        Mutation-version equality alone cannot detect an in-place write that
        stores the same numeric value.  R10 therefore retains the exact
        object/storage/layout/Torch-version epoch for the complete selected-
        reset surface plus the four drain-owned device counters.  These are
        observations of the real live tensors, not a parallel counter or a
        caller-supplied snapshot.
        """

        destinations = tuple(
            (name, value)
            for name, _disposition, value in (
                self._action_ball_continuous_racket_selected_reset_destinations()
            )
        ) + (
            (
                "_action_ball_continuous_racket_mutation_version_device",
                self._action_ball_continuous_racket_mutation_version_device,
            ),
            (
                "_action_ball_continuous_racket_terminal_resolution_total_device",
                self._action_ball_continuous_racket_terminal_resolution_total_device,
            ),
            (
                "_action_ball_continuous_racket_drain_fault_count_device",
                self._action_ball_continuous_racket_drain_fault_count_device,
            ),
            (
                "_action_ball_continuous_racket_drain_invariant_count_device",
                self._action_ball_continuous_racket_drain_invariant_count_device,
            ),
        )
        names = tuple(name for name, _value in destinations)
        if len(set(names)) != len(names):
            raise RuntimeError(
                "continuous Racket checkpoint live tensor inventory aliases a name"
            )
        return tuple(
            (name, _action_ball_continuous_tensor_receipt(value))
            for name, value in destinations
        )

    def current_checkpoint_mutation_projection(
        self,
        boundary: object,
        owner_kind: str,
    ) -> object:
        """Project Racket's live version only from its latest exact global ACK.

        This is the construction-bound R10 leaf callback.  It deliberately
        accepts neither a caller mutation number nor a drain receipt.  The
        exact global-drain authority/receipt pair was retained only after that
        authority's leaf ACK callback succeeded.  A cold restore retains the
        portable last-ACK/debt chronology but clears these process identities,
        so it must complete a new global drain join before this callback can
        authorize publication.
        """

        try:
            import action_ball_full_mdp_checkpoint as checkpoint
            from whole_body_tracking.tasks.tracking.mdp import (
                action_ball_full_mdp_ppo_drain as drain,
            )
        except (ImportError, ModuleNotFoundError):
            import action_ball_full_mdp_checkpoint as checkpoint
            import action_ball_full_mdp_ppo_drain as drain

        if owner_kind != _ACTION_BALL_CONTINUOUS_RACKET_DRAIN_OWNER_KIND:
            raise RuntimeError("continuous Racket R10 leaf role differs")
        if type(boundary) is not checkpoint.CheckpointBoundary:
            raise RuntimeError(
                "continuous Racket R10 projection requires the exact checkpoint boundary"
            )
        checkpoint.validate_checkpoint_boundary(boundary)

        authority = self._action_ball_continuous_racket_drain_authority
        receipt = (
            self._action_ball_continuous_racket_drain_last_acknowledged_receipt
        )
        retained_epoch = (
            self._action_ball_continuous_racket_checkpoint_live_epoch_receipts
        )
        mutation_version = self._action_ball_continuous_racket_mutation_version
        acknowledged_mutation = (
            self._action_ball_continuous_racket_drain_last_acknowledged_mutation_version
        )
        if (
            self._action_ball_continuous_racket_poisoned
            or self._action_ball_continuous_racket_drain_poisoned
            or self._action_ball_continuous_racket_active_ppo_drain_pack is not None
            or not self._action_ball_continuous_racket_drain_leaf_idle()
            or self._action_ball_continuous_racket_checkpoint_requires_drain_ack
            or self._action_ball_continuous_racket_checkpoint_live_join_required
            or type(authority) is not drain.LeafDevicePackAuthority
            or type(receipt) is not drain.PreOptimizerPpoBoundaryReceipt
            or receipt.acknowledged is not True
            or receipt.update_index
            != self._action_ball_continuous_racket_drain_last_update_index
            or receipt.completed_environment_steps
            != self._action_ball_continuous_racket_drain_last_completed_environment_steps
            or receipt.drain_sequence
            != self._action_ball_continuous_racket_drain_sequence
            or receipt.num_envs != self.num_envs
            or boundary.update_index != receipt.update_index
            or type(mutation_version) is not int
            or type(acknowledged_mutation) is not int
            or mutation_version != acknowledged_mutation
            or type(retained_epoch) is not tuple
            or not retained_epoch
            or any(
                type(named) is not tuple
                or len(named) != 2
                or type(named[0]) is not str
                or not _action_ball_continuous_tensor_matches_receipt(
                    getattr(self, named[0], None), named[1]
                )
                for named in retained_epoch
            )
        ):
            raise RuntimeError(
                "continuous Racket R10 projection lacks its exact latest global ACK, idle epoch, or live join"
            )
        racket_rows = tuple(
            row
            for row in receipt.owner_rows
            if row.owner_kind
            == _ACTION_BALL_CONTINUOUS_RACKET_DRAIN_OWNER_KIND
        )
        if (
            len(racket_rows) != 1
            or self._action_ball_continuous_racket_drain_owner_row_values(
                racket_rows[0]
            )[0]
            != mutation_version
        ):
            raise RuntimeError(
                "continuous Racket R10 projection differs from its ACKed owner row"
            )
        return checkpoint.PpoDrainLeafLiveMutationProjection(
            schema_version=1,
            kind="action_ball_r10_leaf_live_mutation_projection_v1",
            owner_kind=_ACTION_BALL_CONTINUOUS_RACKET_DRAIN_OWNER_KIND,
            mutation_version=mutation_version,
        )

    def _action_ball_continuous_racket_exact_resume_protocol_state(self) -> dict:
        """Return only chronology covered by an exact healthy global drain ACK.

        This helper remains legacy/future protocol plumbing.  Fresh full-MDP
        intentionally installs no public exact-resume hooks
        (``exact_resume_supported=False``, integration ``HOLD``) until R10
        also owns every Racket destination/registry.  Keeping this inner schema
        fail-closed prevents a future hookup from checkpointing a settlement
        fault or any post-ACK mutation and restoring its device fault bit as
        zero.
        """

        if (
            self._action_ball_continuous_racket_active_ppo_drain_pack is not None
            or not self._action_ball_continuous_racket_drain_leaf_idle()
            or self._action_ball_continuous_racket_poisoned
            or self._action_ball_continuous_racket_drain_poisoned
        ):
            raise RuntimeError(
                "continuous Racket checkpoint crossed an in-flight reset/drain epoch"
            )
        acknowledged_mutation = (
            self._action_ball_continuous_racket_drain_last_acknowledged_mutation_version
        )
        if (
            type(acknowledged_mutation) is not int
            or acknowledged_mutation
            != self._action_ball_continuous_racket_mutation_version
            or self._action_ball_continuous_racket_checkpoint_requires_drain_ack
        ):
            raise RuntimeError(
                "continuous Racket checkpoint lacks the exact globally ACKed "
                "mutation frontier"
            )
        values = (
            self._action_ball_continuous_racket_mutation_version,
            self._action_ball_continuous_racket_terminal_resolution_total,
            self._action_ball_continuous_racket_drain_last_update_index,
            self._action_ball_continuous_racket_drain_last_completed_environment_steps,
            self._action_ball_continuous_racket_drain_sequence,
        )
        if any(type(value) is not int for value in values):
            raise RuntimeError(
                "continuous Racket exact-resume protocol chronology differs"
            )
        return {
            "schema_version": 2,
            "kind": (
                "whole_body_tracking.RacketTargetCommand."
                "continuous_protocol_exact_resume_v2"
            ),
            "mutation_version": values[0],
            "drain_last_acknowledged_mutation_version": (
                acknowledged_mutation
            ),
            "terminal_resolution_total": values[1],
            "drain_last_update_index": values[2],
            "drain_last_completed_environment_steps": values[3],
            "drain_sequence": values[4],
            "selected_reset_next_serial": (
                self._action_ball_continuous_racket_selected_reset_next_serial
            ),
            "drain_poisoned": (
                self._action_ball_continuous_racket_drain_poisoned
            ),
            "drain_poison_reason": (
                self._action_ball_continuous_racket_drain_poison_reason
            ),
        }

    @staticmethod
    def _action_ball_continuous_racket_stage_exact_resume_protocol_state(
        state: object,
    ) -> dict:
        expected = {
            "schema_version",
            "kind",
            "mutation_version",
            "drain_last_acknowledged_mutation_version",
            "terminal_resolution_total",
            "drain_last_update_index",
            "drain_last_completed_environment_steps",
            "drain_sequence",
            "selected_reset_next_serial",
            "drain_poisoned",
            "drain_poison_reason",
        }
        if (
            type(state) is not dict
            or set(state) != expected
            or state["schema_version"] != 2
            or state["kind"]
            != (
                "whole_body_tracking.RacketTargetCommand."
                "continuous_protocol_exact_resume_v2"
            )
        ):
            raise ValueError(
                "continuous Racket exact-resume protocol schema differs"
            )
        for name in (
            "mutation_version",
            "drain_last_acknowledged_mutation_version",
            "terminal_resolution_total",
            "drain_sequence",
            "selected_reset_next_serial",
        ):
            if type(state[name]) is not int or state[name] < 0:
                raise ValueError(
                    f"continuous Racket exact-resume {name} differs"
                )
        if (
            state["drain_last_acknowledged_mutation_version"]
            != state["mutation_version"]
        ):
            raise ValueError(
                "continuous Racket exact-resume mutation lacks its global "
                "drain ACK frontier"
            )
        for name in (
            "drain_last_update_index",
            "drain_last_completed_environment_steps",
        ):
            if type(state[name]) is not int or state[name] < -1:
                raise ValueError(
                    f"continuous Racket exact-resume {name} differs"
                )
        if (
            type(state["drain_poisoned"]) is not bool
            or not (
                state["drain_poison_reason"] is None
                or type(state["drain_poison_reason"]) is str
            )
            or (
                state["drain_poisoned"]
                and not bool(state["drain_poison_reason"])
            )
            or (
                not state["drain_poisoned"]
                and state["drain_poison_reason"] is not None
            )
        ):
            raise ValueError(
                "continuous Racket exact-resume drain poison state differs"
            )
        return dict(state)

    def prepare_pre_optimizer_ppo_boundary_device_pack(
        self,
        *,
        authority: object,
        update_index: int,
        completed_environment_steps: int,
    ) -> object:
        """Mint Racket's int64 row inside the sole global drain prepare."""

        if (
            self._action_ball_continuous_racket_poisoned
            or self._action_ball_continuous_racket_drain_poisoned
        ):
            raise RuntimeError("continuous Racket PPO drain owner is poisoned")
        update = self._action_ball_continuous_racket_exact_drain_index(
            update_index,
            label="PPO drain update_index",
        )
        completed = self._action_ball_continuous_racket_exact_drain_index(
            completed_environment_steps,
            label="PPO drain completed_environment_steps",
        )
        if (
            update <= self._action_ball_continuous_racket_drain_last_update_index
            or completed
            <= self._action_ball_continuous_racket_drain_last_completed_environment_steps
            or self._action_ball_continuous_racket_active_ppo_drain_pack
            is not None
            or not self._action_ball_continuous_racket_drain_leaf_idle()
            or getattr(authority, "owner_kind", None)
            != _ACTION_BALL_CONTINUOUS_RACKET_DRAIN_OWNER_KIND
            or tuple(getattr(authority, "field_names", ()))
            != _ACTION_BALL_CONTINUOUS_RACKET_DRAIN_FIELD_NAMES
            or getattr(authority, "expected_width", None)
            != len(_ACTION_BALL_CONTINUOUS_RACKET_DRAIN_FIELD_NAMES)
            or (
                getattr(
                    self,
                    "_action_ball_continuous_racket_drain_authority",
                    None,
                )
                is not None
                and getattr(
                    self,
                    "_action_ball_continuous_racket_drain_authority",
                    None,
                )
                is not authority
            )
        ):
            raise RuntimeError(
                "continuous Racket global PPO drain prepare differs"
            )
        mint = getattr(authority, "mint_device_pack", None)
        require_owned_ack = getattr(authority, "require_owned_ack", None)
        try:
            from whole_body_tracking.tasks.tracking.mdp import (
                action_ball_full_mdp_ppo_drain as drain,
            )
        except (ImportError, ModuleNotFoundError):
            import action_ball_full_mdp_ppo_drain as drain
        if (
            type(authority) is not drain.LeafDevicePackAuthority
            or not callable(mint)
            or getattr(mint, "__self__", None) is not authority
            or getattr(mint, "__func__", None)
            is not drain.LeafDevicePackAuthority.mint_device_pack
            or not callable(require_owned_ack)
            or getattr(require_owned_ack, "__self__", None) is not authority
            or getattr(require_owned_ack, "__func__", None)
            is not drain.LeafDevicePackAuthority.require_owned_ack
        ):
            raise RuntimeError(
                "continuous Racket global PPO drain authority API differs"
            )
        device_version = (
            self._action_ball_continuous_racket_mutation_version_device
        )
        fault_count = (
            self._action_ball_continuous_racket_drain_fault_count_device
        )
        terminal_total = (
            self._action_ball_continuous_racket_terminal_resolution_total_device
        )
        if (
            any(
                not torch.is_tensor(value)
                for value in (device_version, fault_count, terminal_total)
            )
            or any(
                value.dtype != torch.int64
                for value in (device_version, fault_count, terminal_total)
            )
            or any(
                value.device != torch.device(self.device)
                for value in (device_version, fault_count, terminal_total)
            )
            or any(
                tuple(value.shape) != (1,)
                for value in (device_version, fault_count, terminal_total)
            )
            or not _action_ball_continuous_tensor_matches_receipt(
                terminal_total,
                self._action_ball_continuous_racket_terminal_resolution_total_device_receipt,
            )
        ):
            raise RuntimeError(
                "continuous Racket device chronology drifted before PPO drain"
            )
        mutation_version = (
            self._action_ball_continuous_racket_mutation_version
        )
        terminal_resolution_total = (
            self._action_ball_continuous_racket_terminal_resolution_total
        )
        if (
            type(mutation_version) is not int
            or type(terminal_resolution_total) is not int
            or mutation_version < 0
            or terminal_resolution_total < 0
        ):
            raise RuntimeError(
                "continuous Racket PPO drain host chronology differs"
            )
        # A real device chronology relation, not a decorative constant.
        # ``terminal_total`` counts selected environments while
        # ``device_version`` counts committed batches; cross-owner equality
        # is checked at the sole seven-leaf global drain.
        invariant_failure = (
            (device_version < 0)
            | (terminal_total < 0)
        )
        invariant_count = torch.where(
            invariant_failure,
            torch.ones_like(device_version),
            torch.zeros_like(device_version),
        )
        values = torch.cat(
            (
                device_version,
                fault_count,
                invariant_count,
                terminal_total,
            )
        ).contiguous()
        source_receipts = tuple(
            _action_ball_continuous_tensor_receipt(value)
            for value in (device_version, fault_count, terminal_total)
        )
        pack = mint(leaf=self, values=values)
        self._action_ball_continuous_racket_active_ppo_drain_pack = (
            _ActionBallContinuousRacketPreparedPpoDrainPack(
                pack=pack,
                authority=authority,
                update_index=update,
                completed_environment_steps=completed,
                mutation_version=mutation_version,
                terminal_resolution_total=terminal_resolution_total,
                source_tensor_receipts=source_receipts,
                expected_values=(
                    mutation_version,
                    0,
                    0,
                    terminal_resolution_total,
                ),
            )
        )
        return pack

    def abort_pre_optimizer_ppo_boundary_device_pack(
        self,
        *,
        pack: object,
    ) -> None:
        """Release one exact pre-transfer pack without business mutation."""

        active = self._action_ball_continuous_racket_active_ppo_drain_pack
        if (
            self._action_ball_continuous_racket_poisoned
            or self._action_ball_continuous_racket_drain_poisoned
            or type(active)
            is not _ActionBallContinuousRacketPreparedPpoDrainPack
            or active.stage != "prepared"
            or pack is not active.pack
        ):
            raise RuntimeError(
                "continuous Racket PPO drain abort pack is stale or foreign"
            )
        if (
            self._action_ball_continuous_racket_mutation_version
            != active.mutation_version
            or self._action_ball_continuous_racket_terminal_resolution_total
            != active.terminal_resolution_total
            or any(
                not _action_ball_continuous_tensor_matches_receipt(
                    receipt[0], receipt
                )
                for receipt in active.source_tensor_receipts
            )
        ):
            self.poison_pre_optimizer_ppo_boundary(
                reason=(
                    "continuous Racket mutated during global PPO drain prepare"
                )
            )
            raise RuntimeError(
                "continuous Racket PPO drain pre-transfer image drifted"
            )
        active.stage = "aborted"
        self._action_ball_continuous_racket_active_ppo_drain_pack = None

    @staticmethod
    def _action_ball_continuous_racket_drain_owner_row_values(
        owner_row: object,
    ) -> tuple[int, int, int, int]:
        if (
            getattr(owner_row, "owner_kind", None)
            != _ACTION_BALL_CONTINUOUS_RACKET_DRAIN_OWNER_KIND
        ):
            raise RuntimeError("continuous Racket drain owner row kind differs")
        values = getattr(owner_row, "values", None)
        if type(values) is not tuple:
            raise RuntimeError("continuous Racket drain owner row differs")
        names = []
        scalars = []
        for item in values:
            if (
                type(item) is not tuple
                or len(item) != 2
                or type(item[0]) is not str
                or type(item[1]) is not int
            ):
                raise RuntimeError(
                    "continuous Racket drain owner row contains non-scalars"
                )
            names.append(item[0])
            scalars.append(item[1])
        if tuple(names) != _ACTION_BALL_CONTINUOUS_RACKET_DRAIN_FIELD_NAMES:
            raise RuntimeError("continuous Racket drain owner row schema differs")
        return tuple(scalars)

    def acknowledge_pre_optimizer_ppo_boundary(
        self,
        *,
        pack: object,
        receipt: object,
        owner_row: object,
    ) -> None:
        """Acknowledge the exact pack/row after the one global D2H."""

        active = self._action_ball_continuous_racket_active_ppo_drain_pack
        try:
            if (
                type(active)
                is not _ActionBallContinuousRacketPreparedPpoDrainPack
            ):
                raise RuntimeError(
                    "continuous Racket PPO drain acknowledgement has no active pack"
                )
            # This construction-bound callback is the first receipt/row
            # consumer.  It proves the exact current coordinator, leaf, pack,
            # receipt, decoded row and optimizer-return window; equal facts
            # from a foreign real coordinator are not authority.
            active.authority.require_owned_ack(
                leaf=self,
                pack=pack,
                receipt=receipt,
                owner_row=owner_row,
            )
            try:
                from whole_body_tracking.tasks.tracking.mdp import (
                    action_ball_full_mdp_ppo_drain as drain,
                )
            except (ImportError, ModuleNotFoundError):
                # Focused Isaac tests load ``mdp`` through a minimal module
                # shim rather than the package.  The source directory is on
                # sys.path there, so this resolves the same file/class once.
                import action_ball_full_mdp_ppo_drain as drain

            if (
                self._action_ball_continuous_racket_poisoned
                or self._action_ball_continuous_racket_drain_poisoned
                or active.stage != "prepared"
                or pack is not active.pack
                or type(receipt) is not drain.PreOptimizerPpoBoundaryReceipt
                or type(owner_row) is not drain.OwnerDrainRow
                or not any(
                    row is owner_row for row in receipt.owner_rows
                )
                or receipt.acknowledged
                or receipt.num_envs != self.num_envs
                or type(getattr(receipt, "update_index", None)) is not int
                or receipt.update_index != active.update_index
                or type(
                    getattr(receipt, "completed_environment_steps", None)
                )
                is not int
                or receipt.completed_environment_steps
                != active.completed_environment_steps
                or getattr(receipt, "device_to_host_transfers", None) != 1
                or type(getattr(receipt, "drain_sequence", None)) is not int
                or receipt.drain_sequence
                != self._action_ball_continuous_racket_drain_sequence + 1
            ):
                raise RuntimeError(
                    "continuous Racket PPO drain acknowledgement differs"
                )
            row = self._action_ball_continuous_racket_drain_owner_row_values(
                owner_row
            )
            if row != active.expected_values:
                raise RuntimeError(
                    "continuous Racket PPO drain row differs from prepared pack"
                )
            if (
                self._action_ball_continuous_racket_mutation_version
                != active.mutation_version
                or self._action_ball_continuous_racket_terminal_resolution_total
                != active.terminal_resolution_total
                or any(
                    not _action_ball_continuous_tensor_matches_receipt(
                        source_receipt[0], source_receipt
                    )
                    for source_receipt in active.source_tensor_receipts
                )
            ):
                raise RuntimeError(
                    "continuous Racket mutated after PPO drain prepare"
                )
        except BaseException as exc:
            self.poison_pre_optimizer_ppo_boundary(
                reason=(
                    "continuous Racket PPO drain acknowledgement failed: "
                    f"{type(exc).__name__}: {exc}"
                )
            )
            raise
        self._action_ball_continuous_racket_drain_last_update_index = (
            active.update_index
        )
        self._action_ball_continuous_racket_drain_last_completed_environment_steps = (
            active.completed_environment_steps
        )
        self._action_ball_continuous_racket_drain_sequence = receipt.drain_sequence
        self._action_ball_continuous_racket_drain_last_acknowledged_mutation_version = (
            active.mutation_version
        )
        # Retain the causal writer and the actual live tensor epoch.  The
        # public receipt is not yet marked ACKed inside this leaf callback;
        # the global owner flips that same object only after all seven leaves
        # return successfully.  A foreign real coordinator can therefore not
        # replace the process-local authority merely by reproducing equal row
        # values.
        self._action_ball_continuous_racket_drain_authority = active.authority
        self._action_ball_continuous_racket_drain_last_acknowledged_receipt = (
            receipt
        )
        self._action_ball_continuous_racket_checkpoint_live_epoch_receipts = (
            self._action_ball_continuous_racket_checkpoint_live_tensor_receipts()
        )
        self._action_ball_continuous_racket_checkpoint_live_join_required = False
        self._action_ball_continuous_racket_checkpoint_requires_drain_ack = False
        active.stage = "acknowledged"
        self._action_ball_continuous_racket_active_ppo_drain_pack = None

    def poison_pre_optimizer_ppo_boundary(self, *, reason: str) -> None:
        """Idempotently fail-stop Racket after an irreversible drain failure."""

        if self._action_ball_continuous_racket_drain_poisoned:
            return
        self._action_ball_continuous_racket_drain_poisoned = True
        self._action_ball_continuous_racket_drain_poison_reason = (
            reason
            if type(reason) is str and bool(reason.strip())
            else "invalid_continuous_racket_ppo_drain_poison_reason"
        )
        self._poison_action_ball_continuous_racket_child()


    def action_ball_shared_state_sha256(self) -> str | None:
        """Return the canonical digest covering Racket's complete shared checkpoint."""

        if not self._action_ball_enabled or not hasattr(
            self, "_action_ball_broker"
        ):
            return None
        state = self._action_ball_exact_resume_state_dict()
        digest = state.get("integrity_sha256")
        if (
            type(digest) is not str
            or len(digest) != 64
            or any(character not in "0123456789abcdef" for character in digest)
        ):
            raise RuntimeError(
                "action-ball shared exact-resume state has no canonical digest"
            )
        return digest

    def _action_ball_note(self, action_slot: int, name: str, amount: int = 1) -> None:
        if name not in _ACTION_BALL_LEDGER_NAMES:
            raise RuntimeError(f"unknown action-ball ledger field {name!r}")
        if type(action_slot) is not int or not 0 <= action_slot < len(
            self._action_ball_bindings
        ):
            raise RuntimeError(f"invalid action-ball ledger slot {action_slot!r}")
        if type(amount) is not int or amount < 0:
            raise RuntimeError("action-ball ledger increments must be non-negative plain ints")
        self._action_ball_live_ledger()[
            _ACTION_BALL_LEDGER_NAMES.index(name), action_slot
        ].add_(amount)

    def _action_ball_live_ledger(self) -> torch.Tensor:
        """Return the mutually exclusive evidence ledger for this task source."""

        if self._action_ball_fixed_view_enabled:
            return self._action_ball_fixed_view_ledger
        return self._action_ball_ledger

    def _action_ball_decode_provider_births(
        self, raw_provider: object, *, staged_sampler, curriculum=None
    ) -> dict:
        """Validate the exact active runtime↔sampler birth cross-bindings."""

        from whole_body_tracking.tasks.tracking.mdp.action_ball_runtime import (
            ActionBirthReceipt,
        )
        from whole_body_tracking.tasks.tracking.mdp.action_ball_sampling import (
            ARM_KEYS,
            DomainLevels,
        )

        curriculum = (
            self._action_ball_curriculum
            if curriculum is None
            else curriculum
        )
        if not isinstance(raw_provider, list):
            raise ValueError("action-ball provider_births must be a list")
        provider_births = {}
        previous_digest = ""
        axes = ARM_KEYS
        for index, raw in enumerate(raw_provider):
            keys = {
                "birth_sha256",
                "runtime_birth",
                "sampler_birth",
                "stratum",
                "levels",
                "rho",
            }
            if not isinstance(raw, dict) or set(raw) != keys:
                raise ValueError(
                    f"action-ball provider_births[{index}] has invalid keys"
                )
            runtime_birth = ActionBirthReceipt.from_dict(raw["runtime_birth"])
            digest = runtime_birth.canonical_sha256
            if raw["birth_sha256"] != digest or digest <= previous_digest:
                raise ValueError(
                    "action-ball provider births must be unique and sorted by SHA"
                )
            previous_digest = digest
            sampler_birth = self._action_ball_parse_sampler_birth(
                raw["sampler_birth"]
            )
            levels = DomainLevels.from_mapping(raw["levels"])
            if (
                levels != sampler_birth.domain_levels
                or runtime_birth.domain_levels.to_dict() != levels.as_dict()
            ):
                raise ValueError(
                    "action-ball runtime/sampler provider levels disagree"
                )
            key = self._action_ball_key_by_uid.get(runtime_birth.action_uid)
            if key is None:
                raise ValueError(
                    "action-ball provider birth has unknown action UID"
                )
            if not 0 <= runtime_birth.action_slot < len(
                self._action_ball_bindings
            ):
                raise ValueError(
                    "action-ball provider birth has invalid action slot"
                )
            binding = self._action_ball_bindings[runtime_birth.action_slot]
            runtime_birth.assert_contract(
                binding=binding,
                pins=self._action_ball_pins,
                mobility_mode=self._action_ball_manifest.mobility_mode,
                registry_sha256=self._action_ball_broker.registry_sha256,
            )
            staged_sampler._validate_birth(
                sampler_birth,
                action_uid=runtime_birth.action_uid,
                domain_epoch=runtime_birth.domain_epoch,
                levels=levels,
                base_yaw_rad=runtime_birth.base_yaw_rad,
            )
            staged_sampler.assert_issued_birth(sampler_birth)
            if (
                sampler_birth.birth_id
                != runtime_birth.sampler_birth_sha256
                or sampler_birth.birth_index
                != runtime_birth.sampler_birth_index
                or sampler_birth.draw_start
                != runtime_birth.sampler_draw_start
                or sampler_birth.draw_end != runtime_birth.sampler_draw_end
                or sampler_birth.profile_sha256
                != runtime_birth.profile_sha256
                or tuple(sampler_birth.base_start_w_m)
                != tuple(runtime_birth.base_spawn_w_m)
            ):
                raise ValueError(
                    "action-ball provider runtime/sampler birth identity mismatch"
                )
            if type(raw["stratum"]) is not str or not raw["stratum"]:
                raise ValueError("action-ball provider stratum is invalid")
            if (
                type(raw["rho"]) not in (int, float)
                or not math.isfinite(float(raw["rho"]))
                or not 0.0 <= float(raw["rho"]) <= 1.0
            ):
                raise ValueError("action-ball provider rho is invalid")
            matching_domains = [
                domain
                for domain in curriculum.expected_domains(key)
                if (
                    domain.stratum == raw["stratum"]
                    and domain.domain_epoch == runtime_birth.domain_epoch
                    and tuple(domain.arm_levels)
                    == tuple(levels.as_dict()[axis] for axis in axes)
                    and domain.rho == float(raw["rho"])
                )
            ]
            if len(matching_domains) != 1:
                raise ValueError(
                    "action-ball provider birth is outside the frozen curriculum domain"
                )
            provider_births[digest] = {
                "runtime_birth": runtime_birth,
                "sampler_birth": sampler_birth,
                "stratum": raw["stratum"],
                "levels": levels,
                "rho": float(raw["rho"]),
            }
        return provider_births

    def _action_ball_decode_provider_history(
        self, raw_history: object, *, staged_sampler
    ) -> dict:
        """Validate the append-only runtime assignment transcript.

        Historical births are deliberately validated against their content-addressed
        sampler identities, not against the curriculum's *current* domain.  An old
        episode may outlive several curriculum advances, while its exact assignment
        must remain available for broker-history and exact-resume verification.
        """

        from whole_body_tracking.tasks.tracking.mdp.action_ball_runtime import (
            ActionBirthReceipt,
        )
        from whole_body_tracking.tasks.tracking.mdp.action_ball_sampling import (
            BaseBirthReceipt,
        )

        if not isinstance(raw_history, list):
            raise ValueError("action-ball provider_history must be a list")
        provider_history = {}
        previous_digest = ""
        seen_generations = set()
        for index, raw in enumerate(raw_history):
            receipt = ActionBirthReceipt.from_dict(raw)
            digest = receipt.canonical_sha256
            if digest <= previous_digest:
                raise ValueError(
                    "action-ball provider history must be unique and sorted by SHA"
                )
            previous_digest = digest
            generation = (int(receipt.env_id), int(receipt.reset_generation))
            if generation in seen_generations:
                raise ValueError(
                    "action-ball provider history repeats an env/reset generation"
                )
            seen_generations.add(generation)
            if not 0 <= receipt.action_slot < len(self._action_ball_bindings):
                raise ValueError(
                    f"action-ball provider_history[{index}] has invalid action slot"
                )
            binding = self._action_ball_bindings[receipt.action_slot]
            if binding.action_uid != receipt.action_uid:
                raise ValueError(
                    f"action-ball provider_history[{index}] action slot/UID drifted"
                )
            receipt.assert_contract(
                binding=binding,
                pins=self._action_ball_pins,
                mobility_mode=self._action_ball_manifest.mobility_mode,
                registry_sha256=self._action_ball_broker.registry_sha256,
            )
            sampler_birth = BaseBirthReceipt.from_identity_receipt(
                receipt.sampler_identity_receipt()
            )
            staged_sampler.assert_issued_birth(sampler_birth)
            provider_history[digest] = receipt
        return provider_history

    def _action_ball_decode_task_transcripts(
        self, raw_transcripts: object, *, provider_history: dict
    ) -> tuple[dict, dict]:
        """Validate compact per-birth admitted-task count/hash-chain roots."""

        from whole_body_tracking.tasks.tracking.mdp.action_ball_runtime import (
            task_transcript_sha256,
        )

        if not isinstance(raw_transcripts, list):
            raise ValueError("action-ball task_transcripts must be a list")
        transcripts = {}
        counts_by_uid = {
            int(uid): 0 for uid in self._action_ball_bundle.action_uids
        }
        previous_birth = ""
        expected_keys = {
            "birth_sha256",
            "admitted_count",
            "transcript_sha256",
        }
        for index, raw in enumerate(raw_transcripts):
            if not isinstance(raw, dict) or set(raw) != expected_keys:
                raise ValueError(
                    f"action-ball task_transcripts[{index}] has invalid keys"
                )
            birth_sha = raw["birth_sha256"]
            count = raw["admitted_count"]
            root = raw["transcript_sha256"]
            if (
                type(birth_sha) is not str
                or birth_sha <= previous_birth
                or birth_sha not in provider_history
                or type(count) is not int
                or count < 0
                or type(root) is not str
                or len(root) != 64
                or any(character not in "0123456789abcdef" for character in root)
            ):
                raise ValueError(
                    f"action-ball task_transcripts[{index}] is invalid"
                )
            previous_birth = birth_sha
            if count == 0 and root != task_transcript_sha256(birth_sha, ()):
                raise ValueError(
                    "empty action-ball task transcript has the wrong root"
                )
            receipt = provider_history[birth_sha]
            counts_by_uid[int(receipt.action_uid)] += count
            transcripts[birth_sha] = (count, root)
        if set(transcripts) != set(provider_history):
            raise ValueError(
                "action-ball task transcript catalog differs from birth history"
            )
        return transcripts, counts_by_uid

    def _action_ball_birth_catalogs_are_live_only(self) -> bool:
        """Whether this run deliberately keeps both per-birth catalogs empty.

        人话:诊断跑(且不是 fixed-view)每次出生只写"还活着的出生表"
        ``_action_ball_provider_births``,**故意**不写 ``_action_ball_provider_history``
        和逐出生的任务 transcript —— 4096 个环境每次 reset 都要多两次哈希表写入加一次
        sha256,而这两本存档在诊断跑里没有任何消费者。这条设计在
        ``_action_ball_retire_previous_births`` 里有自陈注释。

        凡是"拿这两本存档去对账"的地方都必须先问这个函数:在这个模式下它们空是对的,
        拿空账去证伪一个正在正常增长的计数器,证伪的是对账范围,不是那个计数器。
        """

        return bool(self._action_ball_diagnostic_unauthorized) and not bool(
            self._action_ball_fixed_view_enabled
        )

    def _action_ball_task_transcript_scope(self) -> str:
        """Name the per-birth bookkeeping this run actually writes."""

        return (
            _ACTION_BALL_TASK_TRANSCRIPT_SCOPE_DIAGNOSTIC
            if self._action_ball_birth_catalogs_are_live_only()
            else _ACTION_BALL_TASK_TRANSCRIPT_SCOPE_EXACT
        )

    def _action_ball_online_solver_owns_admitted_task_counts(self) -> bool:
        """Whether ``_action_ball_emitted_task_count_by_uid`` has a live producer.

        Only the online proposal solver increments it.  A banded question bank
        owns its own block counters and never calls the online refill callback,
        so in that configuration this map must stay at zero forever.
        """

        return (
            self._action_ball_banded_question_bank is None
            and self._action_ball_immutable_tape is None
        )

    def _action_ball_host_proposal_rows(self) -> dict:
        """Read the ``P``/``A`` ledger rows to the host exactly once.

        This whole state blob is rebuilt inside the pool's purity envelope on
        every reset batch, not only at checkpoint time, so each extra
        device-to-host read here is a per-reset synchronization.  One read
        serves both the admitted-task reconciliation and the payload.
        """

        ledger = self._action_ball_live_ledger()
        return {
            name: [
                int(value)
                for value in ledger[_ACTION_BALL_LEDGER_NAMES.index(name)]
                .detach()
                .cpu()
                .tolist()
            ]
            for name in ("P", "A")
        }

    def _action_ball_expected_admitted_task_counts_live_only(
        self, admitted_row: list
    ) -> dict:
        """Admitted-task counts a live-births-only run must be showing.

        The per-birth transcript is intentionally absent here, so the check
        moves to the ledger this mode does maintain: every admitted proposal
        increments ``A`` in the same producer transaction that increments the
        per-action admitted-task count.  Same drift, different witness.
        """

        if not self._action_ball_online_solver_owns_admitted_task_counts():
            return {int(uid): 0 for uid in self._action_ball_bundle.action_uids}
        return {
            int(uid): admitted_row[slot]
            for slot, uid in enumerate(self._action_ball_bundle.action_uids)
        }

    def _action_ball_solver_mutable_state_dict(self) -> dict:
        """One exact state blob shared by domain, provider and solver protocol views."""

        provider_births = []
        for digest, provider in sorted(self._action_ball_provider_births.items()):
            if digest != provider["runtime_birth"].canonical_sha256:
                raise RuntimeError("action-ball provider birth map key drifted")
            provider_births.append(
                {
                    "birth_sha256": digest,
                    "runtime_birth": provider["runtime_birth"].to_dict(),
                    "sampler_birth": provider["sampler_birth"].to_receipt(),
                    "stratum": provider["stratum"],
                    "levels": provider["levels"].as_dict(),
                    "rho": provider["rho"],
                }
            )
        provider_history = []
        for digest, receipt in sorted(self._action_ball_provider_history.items()):
            if digest != receipt.canonical_sha256:
                raise RuntimeError("action-ball provider history map key drifted")
            provider_history.append(receipt.to_dict())
        transcript_counts = {
            int(uid): 0 for uid in self._action_ball_bundle.action_uids
        }
        task_transcripts = []
        if set(self._action_ball_task_transcript_by_birth) != set(
            self._action_ball_provider_history
        ):
            raise RuntimeError(
                "action-ball task transcript catalog differs from birth history"
            )
        for birth_sha, transcript in sorted(
            self._action_ball_task_transcript_by_birth.items()
        ):
            count, root = transcript
            receipt = self._action_ball_provider_history[birth_sha]
            task_transcripts.append(
                {
                    "birth_sha256": birth_sha,
                    "admitted_count": int(count),
                    "transcript_sha256": root,
                }
            )
            transcript_counts[int(receipt.action_uid)] += int(count)
        proposal_rows = self._action_ball_host_proposal_rows()
        if self._action_ball_birth_catalogs_are_live_only():
            # Both per-birth catalogs are deliberately empty in this mode, so
            # reconciling the admitted-task counts against them would compare a
            # live counter with a ledger that has no producer.  Fail closed on
            # the two facts that are actually claimed here instead: the catalogs
            # really are empty, and every admitted task has a matching admitted
            # proposal.
            if (
                self._action_ball_provider_history
                or self._action_ball_task_transcript_by_birth
            ):
                raise RuntimeError(
                    "action-ball run declares live-births-only bookkeeping but "
                    "wrote a per-birth provider-history/task-transcript row"
                )
            if (
                self._action_ball_expected_admitted_task_counts_live_only(
                    proposal_rows["A"]
                )
                != self._action_ball_emitted_task_count_by_uid
            ):
                raise RuntimeError(
                    "action-ball admitted-task count disagrees with the "
                    "admitted-proposal ledger"
                )
        elif transcript_counts != self._action_ball_emitted_task_count_by_uid:
            raise RuntimeError(
                "action-ball admitted-task count disagrees with the per-birth "
                "task transcript"
            )
        curriculum_state = self._action_ball_curriculum.state_dict()
        payload = {
            "schema_version": _ACTION_BALL_SOLVER_STATE_SCHEMA_VERSION,
            "kind": "whole_body_tracking.RacketTargetCommand.action_ball_mutable_state",
            "state_owner_sha256": self._action_ball_state_owner_sha256,
            "domain_authority_contract_sha256": (
                self._action_ball_domain_authority_contract["sha256"]
            ),
            "sampler_contract_sha256": (
                self._action_ball_sampler.sampler_contract_sha256
            ),
            "solver_contract_sha256": self._action_ball_solver_contract["sha256"],
            "action_uids": list(self._action_ball_bundle.action_uids),
            "curriculum_state_sha256": curriculum_state["state_sha256"],
            # Signed self-declaration of which per-birth bookkeeping the rows
            # below actually contain.  A reader must never have to guess this
            # from "provider_history happens to be empty".
            "task_transcript_scope": self._action_ball_task_transcript_scope(),
            "sampler": self._action_ball_sampler.state_dict(),
            "exact_question_cache": (
                None
                if self._action_ball_exact_question_cache is None
                else self._action_ball_exact_question_cache.state_dict()
            ),
            "provider_births": provider_births,
            "provider_history": provider_history,
            "task_transcripts": task_transcripts,
            "domain_cursors": [
                [int(uid), int(self._action_ball_domain_cursor_by_uid[int(uid)])]
                for uid in self._action_ball_bundle.action_uids
            ],
            # Same host rows the admitted-task reconciliation above already
            # read; re-reading the device here would double the per-reset
            # synchronization for no extra evidence.
            "proposal_ledger": {
                name: list(proposal_rows[name]) for name in ("P", "A")
            },
            "solver_rejections": [
                {
                    "action_uid": int(uid),
                    "counts": {
                        name: int(count)
                        for name, count in sorted(
                            self._action_ball_reject_counts[int(uid)].items()
                        )
                    },
                }
                for uid in self._action_ball_bundle.action_uids
            ],
        }
        payload["integrity_sha256"] = _action_ball_canonical_sha256(payload)
        return payload

    def _action_ball_decode_solver_mutable_state(
        self,
        state: object,
        *,
        curriculum=None,
        expected_curriculum_state_sha256: str | None = None,
    ):
        """Validate the shared domain/provider/solver state on disposable components."""

        expected = {
            "schema_version",
            "kind",
            "state_owner_sha256",
            "domain_authority_contract_sha256",
            "sampler_contract_sha256",
            "solver_contract_sha256",
            "action_uids",
            "curriculum_state_sha256",
            "task_transcript_scope",
            "sampler",
            "exact_question_cache",
            "provider_births",
            "provider_history",
            "task_transcripts",
            "domain_cursors",
            "proposal_ledger",
            "solver_rejections",
            "integrity_sha256",
        }
        if (
            isinstance(state, dict)
            and "task_transcript_scope" not in state
            and set(state) | {"task_transcript_scope"} == expected
        ):
            # 人话:老状态包没有这块牌子,读的人无法判断它那两本逐出生存档是"故意空"
            # 还是"丢了"。分不清就不许续跑。
            raise ValueError(
                "action-ball solver state predates the task-transcript scope "
                "brand and cannot prove whether its per-birth catalogs are "
                "intentionally empty; launch fresh"
            )
        if not isinstance(state, dict) or set(state) != expected:
            raise ValueError("action-ball solver state has invalid keys")
        unsigned = {
            key: state[key] for key in expected if key != "integrity_sha256"
        }
        curriculum = (
            self._action_ball_curriculum
            if curriculum is None
            else curriculum
        )
        expected_curriculum_sha = (
            curriculum.state_dict()["state_sha256"]
            if expected_curriculum_state_sha256 is None
            else expected_curriculum_state_sha256
        )
        if (
            type(state["integrity_sha256"]) is not str
            or _action_ball_canonical_sha256(unsigned) != state["integrity_sha256"]
        ):
            raise ValueError("action-ball solver state integrity mismatch")
        if (
            type(state["schema_version"]) is not int
            or state["schema_version"] != _ACTION_BALL_SOLVER_STATE_SCHEMA_VERSION
            or state["kind"]
            != "whole_body_tracking.RacketTargetCommand.action_ball_mutable_state"
            or state["state_owner_sha256"]
            != self._action_ball_state_owner_sha256
            or state["domain_authority_contract_sha256"]
            != self._action_ball_domain_authority_contract["sha256"]
            or state["sampler_contract_sha256"]
            != self._action_ball_sampler.sampler_contract_sha256
            or state["solver_contract_sha256"]
            != self._action_ball_solver_contract["sha256"]
            or state["action_uids"] != list(self._action_ball_bundle.action_uids)
            or state["curriculum_state_sha256"]
            != expected_curriculum_sha
        ):
            raise ValueError("action-ball mutable state immutable identity mismatch")
        live_only = self._action_ball_birth_catalogs_are_live_only()
        expected_scope = self._action_ball_task_transcript_scope()
        if state["task_transcript_scope"] not in _ACTION_BALL_TASK_TRANSCRIPT_SCOPES:
            raise ValueError(
                "action-ball solver state has an unknown task-transcript scope"
            )
        if state["task_transcript_scope"] != expected_scope:
            # 人话:诊断跑的存档里根本没有逐出生 transcript,精确跑必须有;两边互相
            # 不能续。宁可在这里明说,也不要让缺的那一半悄悄变成零。
            raise ValueError(
                "action-ball solver state task-transcript scope mismatch: "
                f"checkpoint={state['task_transcript_scope']!r}, this run "
                f"requires {expected_scope!r}"
            )
        from whole_body_tracking.tasks.tracking.mdp.action_ball_sampling import (
            ActionBallSampler,
            BaseBirthReceipt,
            DomainLevels,
            SamplingMixture,
        )

        staged_sampler = ActionBallSampler(
            self._action_ball_bundle.profiles,
            seed=int(self.cfg.action_ball_seed),
            sampling_mixture=SamplingMixture(),
            contact_time_step_s=float(self._env.step_dt),
            initial_center_single_question=(
                self.cfg.action_ball_initial_center_single_question
            ),
            # 人话:这块牌子决定这个采样器**记不记**逐出生的账,活采样器是按
            # ``action_ball_diagnostic_unauthorized`` 建的,存档里也签着那块牌子。
            # 这里以前传的是 ``_action_ball_fixed_view_enabled`` —— 另一个布尔,
            # 两者在"诊断跑但不是 fixed view"时正好相反,于是回滚/续跑一走到这里
            # 就被 sampler 的 scope 牌子当场拒(checkpoint=diagnostic,本采样器
            # =exact)。同文件另外五处建采样器/broker/pool 用的都是这一个。
            diagnostic_unauthorized=(
                self._action_ball_diagnostic_unauthorized
            ),
        )
        staged_sampler.load_state_dict(state["sampler"])
        if self._action_ball_exact_question_cache is None:
            if state["exact_question_cache"] is not None:
                raise ValueError(
                    "action-ball mutable state unexpectedly contains an "
                    "exact-question cache"
                )
            staged_question_cache = None
        else:
            staged_question_cache = self._action_ball_exact_question_cache.clone()
            staged_question_cache.load_state_dict(
                state["exact_question_cache"]
            )
        self._action_ball_restore_fixed_sampler_highwaters(
            staged_sampler
        )
        provider_history = self._action_ball_decode_provider_history(
            state["provider_history"],
            staged_sampler=staged_sampler,
        )
        provider_births = self._action_ball_decode_provider_births(
            state["provider_births"],
            staged_sampler=staged_sampler,
            curriculum=curriculum,
        )
        if live_only:
            # This scope claims both per-birth catalogs are empty.  Anything in
            # them is drift, and an "active birth must appear in history" cross
            # check has no history to consult.  The active births themselves are
            # still fully re-proved against the staged sampler above.
            if provider_history:
                raise ValueError(
                    "live-births-only action-ball solver state carries a "
                    "per-birth provider-history row"
                )
        else:
            for digest, provider in provider_births.items():
                if (
                    provider_history.get(digest) != provider["runtime_birth"]
                    or BaseBirthReceipt.from_identity_receipt(
                        provider_history[digest].sampler_identity_receipt()
                    )
                    != provider["sampler_birth"]
                ):
                    raise ValueError(
                        "active action-ball provider birth is absent from exact history"
                    )
        if staged_question_cache is not None and not set(
            staged_question_cache.active_birth_sha256s
        ).issubset(provider_births):
            raise ValueError(
                "exact-question cache references a non-active provider birth"
            )
        task_transcripts, emitted_task_counts = (
            self._action_ball_decode_task_transcripts(
                state["task_transcripts"],
                provider_history=provider_history,
            )
        )
        raw_cursors = state["domain_cursors"]
        if not isinstance(raw_cursors, list) or len(raw_cursors) != len(
            self._action_ball_bundle.action_uids
        ):
            raise ValueError("action-ball domain_cursors has invalid shape")
        domain_cursors = {}
        for row, expected_uid in zip(
            raw_cursors, self._action_ball_bundle.action_uids
        ):
            if (
                not isinstance(row, list)
                or len(row) != 2
                or type(row[0]) is not int
                or row[0] != expected_uid
                or type(row[1]) is not int
                or row[1] < 0
            ):
                raise ValueError("action-ball domain cursor row is invalid")
            domain_cursors[int(row[0])] = int(row[1])
        if not live_only:
            history_counts = {
                int(uid): sum(
                    receipt.action_uid == int(uid)
                    for receipt in provider_history.values()
                )
                for uid in self._action_ball_bundle.action_uids
            }
            if any(
                domain_cursors[int(uid)] != history_counts[int(uid)]
                for uid in self._action_ball_bundle.action_uids
            ):
                raise ValueError(
                    "action-ball domain cursor/provider assignment transcript diverged"
                )
        # 人话:live-only 这一档没有 provider_history 可以给这些 cursor 当锚点。
        # 这里以前写着"独立见证在 ``ActionBirthBroker.load_state_dict``",那句话
        # 是错的 —— broker 的 ``load_state_dict`` 只在
        # ``_action_ball_load_exact_resume_state_dict`` 里被调用,而那个函数第一句
        # 就把 live-only 顶回去了(见下面 15550 附近);broker 自己的存档现在也
        # 自陈 ``birth_transcript_scope=live_envs_only`` 并拒绝载入。那条锚点在
        # 这一档**永远走不到**。
        #
        # 实际依据是:live-only 解码器唯一的活消费者是**进程内回滚**
        # (``_restore_solver_state`` -> ``_action_ball_load_solver_mutable_state``),
        # 载荷是本进程几行之前自己刚生成的,``integrity_sha256`` 覆盖了含范围牌子
        # 在内的全部字段。也就是自产自销 + 完整性哈希,不是第二个独立证人。
        # 这一档本来就不支持跨进程续跑,所以这样是够的 —— 但别再声称一个
        # 跑不到的锚点。
        raw_proposals = state["proposal_ledger"]
        if not isinstance(raw_proposals, dict) or set(raw_proposals) != {"P", "A"}:
            raise ValueError("action-ball solver proposal_ledger has invalid keys")
        count = len(self._action_ball_bundle.action_uids)
        proposal_rows = {}
        for name in ("P", "A"):
            row = raw_proposals[name]
            if (
                not isinstance(row, list)
                or len(row) != count
                or any(type(value) is not int or value < 0 for value in row)
            ):
                raise ValueError(
                    f"action-ball solver proposal_ledger.{name} is invalid"
                )
            proposal_rows[name] = [int(value) for value in row]
        if any(
            proposal_rows["A"][slot] > proposal_rows["P"][slot]
            for slot in range(count)
        ):
            raise ValueError("action-ball solver proposal ledger requires P >= A")
        if self._action_ball_fixed_view_enabled:
            if (
                any(emitted_task_counts.values())
                or proposal_rows["P"] != proposal_rows["A"]
            ):
                raise ValueError(
                    "immutable fixed-view mutable state contains task "
                    "receipts or rejected logical rows"
                )
        elif live_only:
            # 没有逐出生 transcript 可以重建这些计数,所以这里的 admitted 提案
            # 台账是**被复原的值本身**,不是对它的第二种意见。
            #
            # 这里以前写着"独立见证在外面一层:
            # ``_action_ball_load_exact_resume_state_dict`` 要求顶层 ``A`` 等于
            # 复原后池子的 ``admitted``"。那句话是错的 —— 那条检查就在那个函数
            # 里面,而该函数对 live-only 直接抛错(15550 附近),这一档根本走不到。
            #
            # 真正的依据是:live-only 唯一能到这里的入口是进程内回滚,而生产者
            # (``_action_ball_solver_mutable_state_dict``)在几行之前刚断言过
            # ``A[slot] == emitted[uid]``,``integrity_sha256`` 又覆盖了全部字段。
            if state["task_transcripts"] != []:
                raise ValueError(
                    "live-births-only action-ball solver state carries a "
                    "per-birth task transcript row"
                )
            emitted_task_counts = (
                {
                    int(uid): proposal_rows["A"][slot]
                    for slot, uid in enumerate(
                        self._action_ball_bundle.action_uids
                    )
                }
                if self._action_ball_online_solver_owns_admitted_task_counts()
                else {
                    int(uid): 0
                    for uid in self._action_ball_bundle.action_uids
                }
            )
        elif any(
            emitted_task_counts[int(uid)] != proposal_rows["A"][slot]
            for slot, uid in enumerate(self._action_ball_bundle.action_uids)
        ):
            raise ValueError(
                "action-ball admitted ledger differs from emitted task transcript"
            )

        known_reasons = set(
            self._action_ball_solver_contract["payload"]["acceptance"][
                "ordered_rejection_reason_schema"
            ]
        )
        raw_rejections = state["solver_rejections"]
        if not isinstance(raw_rejections, list) or len(raw_rejections) != count:
            raise ValueError("action-ball solver rejection rows have invalid shape")
        rejection_rows = {}
        for raw, uid in zip(raw_rejections, self._action_ball_bundle.action_uids):
            if (
                not isinstance(raw, dict)
                or set(raw) != {"action_uid", "counts"}
                or raw["action_uid"] != uid
                or not isinstance(raw["counts"], dict)
                or not set(raw["counts"]).issubset(known_reasons)
                or any(
                    type(value) is not int or value < 0
                    for value in raw["counts"].values()
                )
            ):
                raise ValueError("action-ball solver rejection row is invalid")
            rejection_rows[int(uid)] = {
                str(name): int(value)
                for name, value in sorted(raw["counts"].items())
            }
        for slot, uid in enumerate(self._action_ball_bundle.action_uids):
            if (
                sum(rejection_rows[int(uid)].values())
                != proposal_rows["P"][slot] - proposal_rows["A"][slot]
            ):
                raise ValueError(
                    "action-ball solver rejection histogram does not conserve P-A"
                )
        return (
            state["sampler"],
            staged_question_cache,
            provider_births,
            provider_history,
            task_transcripts,
            emitted_task_counts,
            domain_cursors,
            proposal_rows,
            rejection_rows,
        )

    def _action_ball_load_solver_mutable_state(self, state: object) -> None:
        (
            sampler_state,
            staged_question_cache,
            provider_births,
            provider_history,
            task_transcripts,
            emitted_task_counts,
            domain_cursors,
            proposal_rows,
            rejection_rows,
        ) = (
            self._action_ball_decode_solver_mutable_state(state)
        )
        # The disposable sampler above makes the following commit non-branching and exact.
        self._action_ball_sampler.load_state_dict(sampler_state)
        if self._action_ball_exact_question_cache is not None:
            if staged_question_cache is None:
                raise RuntimeError("validated question cache disappeared")
            self._action_ball_exact_question_cache.load_state_dict(
                staged_question_cache.state_dict()
            )
        self._action_ball_restore_fixed_sampler_highwaters(
            self._action_ball_sampler
        )
        self._action_ball_provider_births = provider_births
        self._action_ball_provider_history = provider_history
        self._action_ball_task_transcript_by_birth = task_transcripts
        self._action_ball_emitted_task_count_by_uid = emitted_task_counts
        self._action_ball_domain_cursor_by_uid = domain_cursors
        for name in ("P", "A"):
            self._action_ball_live_ledger()[
                _ACTION_BALL_LEDGER_NAMES.index(name)
            ].copy_(
                torch.tensor(
                    proposal_rows[name], dtype=torch.long, device=self.device
                )
            )
        self._action_ball_reject_counts = rejection_rows

    def _action_ball_restore_fixed_sampler_highwaters(self, sampler) -> None:
        """Rebuild diagnostic-only highwaters omitted by sampler state bytes."""

        if not self._action_ball_fixed_view_enabled:
            return
        if not bool(getattr(sampler, "_diagnostic_fast_path", False)):
            raise RuntimeError(
                "immutable fixed-view sampler restore lost diagnostic mode"
            )
        birth_highwaters = {}
        sample_highwaters = {}
        for uid in self._action_ball_bundle.action_uids:
            action_uid = int(uid)
            birth_count = sampler.birth_count_for(action_uid)
            sample_count = sampler.sample_count_for(action_uid)
            retired_births, retired_samples = sampler.retired_prefix_for(
                action_uid
            )
            if (
                sample_count != 0
                or retired_births != 0
                or retired_samples != 0
            ):
                raise RuntimeError(
                    "immutable fixed-view sampler state contains solved "
                    "samples or compacted birth authority"
                )
            if birth_count == 0:
                birth_draw_end = 0
            else:
                try:
                    last_birth = sampler._issued_births_by_action[
                        action_uid
                    ][birth_count - 1]
                except (AttributeError, KeyError) as error:
                    raise RuntimeError(
                        "immutable fixed-view sampler lost its retained "
                        "birth highwater"
                    ) from error
                birth_draw_end = int(last_birth.draw_end)
            if birth_draw_end != sampler.draw_count_for(action_uid):
                raise RuntimeError(
                    "immutable fixed-view birth highwater differs from RNG"
                )
            birth_highwaters[action_uid] = birth_draw_end
            sample_highwaters[action_uid] = 0
        sampler._diagnostic_last_birth_draw_end_by_action = (
            birth_highwaters
        )
        sampler._diagnostic_last_sample_draw_end_by_action = (
            sample_highwaters
        )

    def _action_ball_fixed_view_broker_state_dict(self) -> dict:
        """Snapshot a complete fixed-view birth transcript read-only.

        The ordinary diagnostic broker intentionally retains only the latest
        consumed receipt per env.  Fixed exact resume instead owns append-only
        provider/sampler history.  The broker's strict diagnostic-only seam
        validates that full transcript without mutating its compact live
        state or changing legacy ``state_dict()`` bytes.
        """

        if not self._action_ball_fixed_view_enabled:
            return self._action_ball_broker.state_dict()
        receipts = tuple(
            sorted(
                self._action_ball_provider_history.values(),
                key=lambda receipt: (
                    receipt.env_id,
                    receipt.reset_generation,
                ),
            )
        )
        return (
            self._action_ball_broker
            .diagnostic_state_dict_with_consumed_history(receipts)
        )

    def _action_ball_fixed_view_pool_state_dict(self) -> dict:
        """Return the cached, unbound legacy-pool identity for fixed resume."""

        if not self._action_ball_fixed_view_enabled:
            return self._action_ball_pool.state_dict()
        state = self._action_ball_fixed_view_pristine_pool_state
        if (
            not self._action_ball_fixed_view_pool_is_pristine(state)
            or state.get("birth_authority_state_sha256") is not None
            or state.get("solver_state")
            != self._action_ball_pool_solver.state_dict()
        ):
            raise RuntimeError(
                "immutable fixed-view cached pool identity is not pristine"
            )
        return json.loads(
            json.dumps(
                state,
                sort_keys=True,
                separators=(",", ":"),
                ensure_ascii=True,
                allow_nan=False,
            )
        )

    def _action_ball_phase_center_mask_tensor(self) -> torch.Tensor:
        """(n_actions,) bool — True while the action's curriculum phase is center.

        Franco 2026-07-28 third ruling (sole default behavior): envs whose
        action has expanded past center (phase >= marginal) stop being
        terminated by the reference-consistency envelopes anchor_pos /
        anchor_ori / ee_body_pos; the absolute fall/table/joint guards are
        separate terms and always stay on.  Curriculum phase only moves
        through exact-resume evidence, so this mask refreshes at
        construction and at load_state_dict — never mid-rollout.
        """

        return torch.tensor(
            [
                self._action_ball_curriculum.phase(key) == "center"
                for key in self._action_ball_profile_keys
            ],
            dtype=torch.bool,
            device=self.device,
        )

    def action_ball_reference_terminations_enabled(
        self,
    ) -> torch.Tensor | None:
        """Per-env gate consumed by the hold-aware reference terminations.

        Returns ``None`` outside action-ball mode (old verdicts everywhere
        else); otherwise the per-env bit frozen by that env's last committed
        true-reset birth.  It is deliberately not selected from a live
        per-action phase table: publication and an episode wrap must not
        change termination semantics underneath an installed attempt.
        """

        if not self._action_ball_enabled:
            return None
        mode = _reference_guard_mode(self.cfg.reference_guard_mode)
        if mode == _REFERENCE_GUARD_METRICS_ONLY:
            # The raw predicates are still evaluated and recorded by
            # ``action_ball_record_reference_guard_raw``.  Only their
            # termination verdict is disabled.  The mask is allocated once
            # with the treatment runtime; do not allocate 3 x N booleans on
            # every control step.
            disabled = getattr(
                self, "_action_ball_reference_term_disabled_mask", None
            )
            if disabled is None:
                self._ensure_action_ball_runtime_initialized()
                disabled = getattr(
                    self,
                    "_action_ball_reference_term_disabled_mask",
                    None,
                )
            if disabled is None:
                raise RuntimeError(
                    "metrics-only ActionBall has no disabled reference mask"
                )
            return disabled
        if getattr(self, "_action_ball_curriculum", None) is None:
            return None
        return self._action_ball_reference_term_center_latch

    def action_ball_record_reference_guard_raw(
        self,
        reason: str,
        raw_mask: torch.Tensor,
    ) -> None:
        """Book one raw reference predicate only for explicit metrics-only ActionBall."""

        if (
            not self._action_ball_enabled
            or _reference_guard_mode(self.cfg.reference_guard_mode)
            != _REFERENCE_GUARD_METRICS_ONLY
        ):
            return
        self._ensure_action_ball_runtime_initialized()
        tracker = self._action_ball_reference_guard_metrics
        if tracker is None:
            raise RuntimeError(
                "metrics-only ActionBall has no reference-guard tracker"
            )
        token = getattr(self._env, "common_step_counter", None)
        ledger = getattr(
            self, "_exact_behavior_decision_counters", None
        )
        if (
            ledger is None
            or "reference_guard_sample_count" not in ledger
        ):
            ledger = self._ensure_exact_behavior_decision_counters()
        tracker.record(
            reason=reason,
            raw_mask=raw_mask,
            step_token=token,
            pre_strike=self.pre_strike,
            strike_window=self.strike_window,
            center_phase=self._action_ball_reference_term_center_latch,
            ledger=ledger,
        )

    def _action_ball_claim_domain(self, action_uid: int):
        """Mint the next frozen curriculum domain only at the broker reset barrier."""

        from whole_body_tracking.tasks.tracking.mdp.action_ball_runtime import (
            ActionDomainClaim,
            ActionDomainLevels,
        )
        from whole_body_tracking.tasks.tracking.mdp.action_ball_sampling import (
            ARM_CATALOG_SHA256,
            ARM_KEYS,
        )

        uid = int(action_uid)
        key = self._action_ball_key_by_uid.get(uid)
        if key is None:
            raise RuntimeError(f"domain requested unknown action_uid {uid}")
        domains = self._action_ball_curriculum.expected_domains(key)
        if not domains:
            raise RuntimeError(
                f"action-ball action_uid {uid} has no trainable curriculum domain"
            )
        cursor = self._action_ball_domain_cursor_by_uid[uid]
        domain = domains[cursor % len(domains)]
        if domain.arm_catalog_sha256 != ARM_CATALOG_SHA256:
            raise RuntimeError(
                "curriculum domain arm catalog differs from sampler"
            )
        levels = ActionDomainLevels(
            **{
                axis: float(value)
                for axis, value in zip(ARM_KEYS, domain.arm_levels)
            }
        )
        claim = ActionDomainClaim(
            authority_contract_sha256=(
                self._action_ball_domain_authority_contract["sha256"]
            ),
            action_uid=uid,
            domain_epoch=int(domain.domain_epoch),
            domain_levels=levels,
            arm_catalog_sha256=ARM_CATALOG_SHA256,
            levels_sha256=levels.canonical_sha256,
            profile_sha256=key.profile_sha256,
            mobility_mode=self._action_ball_manifest.mobility_mode,
        )
        self._action_ball_domain_cursor_by_uid[uid] = cursor + 1
        return claim

    def _action_ball_claim_domains(self, action_uids):
        """Mint one diagnostic reset batch with one domain scan per action.

        The input order is the random-tape order.  All UIDs/domains/claims are
        validated against projected cursors before the live cursor map moves,
        so a bad late row cannot publish a valid prefix.
        """

        from whole_body_tracking.tasks.tracking.mdp.action_ball_runtime import (
            ActionDomainClaim,
            ActionDomainLevels,
        )
        from whole_body_tracking.tasks.tracking.mdp.action_ball_sampling import (
            ARM_CATALOG_SHA256,
            ARM_KEYS,
        )

        rows = tuple(action_uids)
        if not rows:
            raise RuntimeError(
                "action-ball domain claim batch must be non-empty"
            )
        projected_cursors = dict(
            self._action_ball_domain_cursor_by_uid
        )
        domains_by_uid = {}
        claims = []
        for raw_uid in rows:
            uid = int(raw_uid)
            key = self._action_ball_key_by_uid.get(uid)
            if key is None:
                raise RuntimeError(
                    f"domain requested unknown action_uid {uid}"
                )
            domains = domains_by_uid.get(uid)
            if domains is None:
                domains = tuple(
                    self._action_ball_curriculum.expected_domains(key)
                )
                if not domains:
                    raise RuntimeError(
                        f"action-ball action_uid {uid} has no trainable "
                        "curriculum domain"
                    )
                domains_by_uid[uid] = domains
            cursor = projected_cursors[uid]
            domain = domains[cursor % len(domains)]
            if domain.arm_catalog_sha256 != ARM_CATALOG_SHA256:
                raise RuntimeError(
                    "curriculum domain arm catalog differs from sampler"
                )
            levels = ActionDomainLevels(
                **{
                    axis: float(value)
                    for axis, value in zip(ARM_KEYS, domain.arm_levels)
                }
            )
            claims.append(
                ActionDomainClaim(
                    authority_contract_sha256=(
                        self._action_ball_domain_authority_contract[
                            "sha256"
                        ]
                    ),
                    action_uid=uid,
                    domain_epoch=int(domain.domain_epoch),
                    domain_levels=levels,
                    arm_catalog_sha256=ARM_CATALOG_SHA256,
                    levels_sha256=levels.canonical_sha256,
                    profile_sha256=key.profile_sha256,
                    mobility_mode=(
                        self._action_ball_manifest.mobility_mode
                    ),
                )
            )
            projected_cursors[uid] = cursor + 1

        self._action_ball_domain_cursor_by_uid = projected_cursors
        return tuple(claims)

    def _action_ball_provide_birth(self, request):
        """Reserve the exact sampler birth for an authority-minted domain claim."""

        if bool(
            getattr(self, "_action_ball_drain_fence_active", False)
        ):
            raise RuntimeError(
                "action-ball birth work is fenced for global domain release"
            )
        from whole_body_tracking.tasks.tracking.mdp.action_ball_runtime import (
            ActionBirthReceipt,
            ActionDomainLevels,
            ActionSamplingMixture,
            task_transcript_sha256,
        )
        from whole_body_tracking.tasks.tracking.mdp.action_ball_sampling import (
            ARM_CATALOG_SHA256,
            ARM_KEYS,
        )

        claim = request.domain_claim
        uid = int(request.action_uid)
        key = self._action_ball_key_by_uid.get(uid)
        if key is None:
            raise RuntimeError(f"birth requested unknown action_uid {uid}")
        levels = self._action_ball_domain_levels_type.from_mapping(
            claim.domain_levels.to_dict()
        )
        matching_domains = [
            domain
            for domain in self._action_ball_curriculum.expected_domains(key)
            if (
                domain.domain_epoch == claim.domain_epoch
                and tuple(domain.arm_levels)
                == tuple(
                    levels.as_dict()[axis]
                    for axis in ARM_KEYS
                )
            )
        ]
        if len(matching_domains) != 1:
            raise RuntimeError(
                "birth domain claim is not one exact frozen curriculum domain"
            )
        domain = matching_domains[0]
        slot = int(request.action_slot)
        sampler_birth = self._action_ball_sampler.reserve_birth(
            action_uid=uid,
            domain_epoch=int(claim.domain_epoch),
            levels=levels,
            base_yaw_rad=self._action_ball_ready_yaw[slot],
        )
        base_spawn = tuple(float(value) for value in sampler_birth.base_start_w_m)
        if not math.isclose(
            base_spawn[2],
            self._action_ball_ready_z[slot],
            rel_tol=0.0,
            abs_tol=1.0e-7,
        ):
            raise RuntimeError(
                "sampler birth base Z differs from canonical ready"
            )
        receipt = ActionBirthReceipt(
            env_id=int(request.env_id),
            reset_generation=int(request.reset_generation),
            action_uid=uid,
            action_slot=slot,
            domain_epoch=int(claim.domain_epoch),
            domain_claim_sha256=claim.canonical_sha256,
            domain_authority_sha256=(
                self._action_ball_pins.domain_authority_sha256
            ),
            domain_levels=claim.domain_levels,
            arm_catalog_sha256=ARM_CATALOG_SHA256,
            levels_sha256=claim.levels_sha256,
            sampler_birth_sha256=sampler_birth.birth_id,
            sampler_birth_index=int(sampler_birth.birth_index),
            sampler_draw_start=int(sampler_birth.draw_start),
            sampler_draw_end=int(sampler_birth.draw_end),
            mobility_mode=self._action_ball_manifest.mobility_mode,
            base_yaw_rad=float(self._action_ball_ready_yaw[slot]),
            base_quat_wxyz=self._action_ball_ready_quat[slot],
            base_spawn_w_m=base_spawn,
            registry_sha256=self._action_ball_broker.registry_sha256,
            manifest_sha256=self._action_ball_pins.manifest_sha256,
            sampler_sha256=self._action_ball_pins.sampler_sha256,
            profile_sha256=request.binding.profile_sha256,
            motion_sha256=request.binding.motion_sha256,
            physics_sha256=self._action_ball_pins.physics_sha256,
            solver_sha256=self._action_ball_pins.solver_sha256,
            sampling_mixture=(
                None
                if sampler_birth.sampling_mixture is None
                else ActionSamplingMixture.from_dict(
                    sampler_birth.sampling_mixture.as_dict()
                )
            ),
            sampling_stratum=sampler_birth.sampling_stratum,
            sampling_levels=(
                None
                if sampler_birth.sampling_mixture is None
                else ActionDomainLevels(
                    **sampler_birth.sampling_levels.as_dict()
                )
            ),
            frontier_arm=sampler_birth.frontier_arm,
            # Record the sampler law this birth was drawn under.  With every
            # curriculum arm at level zero the sampler collapses the plan to the
            # literal centre point, so the receipt gate must judge the row
            # against that law rather than against the quota slot.
            initial_center_single_question=(
                sampler_birth.sampling_mixture is not None
                and self._action_ball_sampler.initial_center_single_question
            ),
        )
        receipt_sha256 = receipt.canonical_sha256
        if (
            receipt_sha256 in self._action_ball_provider_births
            or receipt_sha256 in self._action_ball_provider_history
        ):
            raise RuntimeError("action-ball birth provider produced a duplicate runtime receipt")
        self._action_ball_provider_births[receipt_sha256] = {
            "runtime_birth": receipt,
            "sampler_birth": sampler_birth,
            "stratum": str(domain.stratum),
            "levels": levels,
            "rho": float(domain.rho),
        }
        if not self._action_ball_birth_catalogs_are_live_only():
            # The batched diagnostic provider deliberately skips both per-birth
            # catalogs.  Which catalogs a run keeps is a property of the run, not
            # of which provider entry point a batch happened to take, so this
            # scalar seam has to make the same choice.
            self._action_ball_provider_history[receipt_sha256] = receipt
            self._action_ball_task_transcript_by_birth[
                receipt_sha256
            ] = (
                0,
                task_transcript_sha256(receipt_sha256, ()),
            )
        return receipt

    def _action_ball_provide_births(self, requests):
        """Provide one diagnostic birth batch without per-env domain scans.

        Request/domain checks are side-effect free and complete before the
        sampler advances.  Sampler births are then reserved in the original
        request order (including mixed-action batches), preserving every
        action-local RNG cursor exactly.  Provider maps commit only after the
        complete receipt batch validates.
        """

        if bool(
            getattr(self, "_action_ball_drain_fence_active", False)
        ):
            raise RuntimeError(
                "action-ball birth work is fenced for global domain release"
            )
        from whole_body_tracking.tasks.tracking.mdp.action_ball_runtime import (
            ActionBirthReceipt,
            ActionDomainLevels,
            ActionSamplingMixture,
            task_transcript_sha256,
        )
        from whole_body_tracking.tasks.tracking.mdp.action_ball_sampling import (
            ARM_CATALOG_SHA256,
            ARM_KEYS,
        )

        rows = tuple(requests)
        if not rows:
            raise RuntimeError(
                "action-ball birth provider batch must be non-empty"
            )

        # ``expected_domains`` constructs the complete domain support.  Do it
        # once per action and index exact identities once, rather than once
        # for every reset env.  Duplicate identities remain a hard error, as
        # in the scalar provider's ``len(matching_domains) == 1`` check.
        domains_by_uid = {}
        levels_by_identity = {}
        prepared = []
        for request in rows:
            claim = request.domain_claim
            uid = int(request.action_uid)
            key = self._action_ball_key_by_uid.get(uid)
            if key is None:
                raise RuntimeError(
                    f"birth requested unknown action_uid {uid}"
                )
            domain_index = domains_by_uid.get(uid)
            if domain_index is None:
                domain_index = {}
                for domain in (
                    self._action_ball_curriculum.expected_domains(key)
                ):
                    identity = (
                        int(domain.domain_epoch),
                        tuple(float(value) for value in domain.arm_levels),
                    )
                    domain_index.setdefault(identity, []).append(domain)
                if not domain_index:
                    raise RuntimeError(
                        f"action-ball action_uid {uid} has no trainable "
                        "curriculum domain"
                    )
                domains_by_uid[uid] = domain_index

            levels_identity = (
                uid,
                claim.levels_sha256,
            )
            levels_row = levels_by_identity.get(levels_identity)
            if levels_row is None:
                levels = (
                    self._action_ball_domain_levels_type.from_mapping(
                        claim.domain_levels.to_dict()
                    )
                )
                levels_mapping = levels.as_dict()
                arm_levels = tuple(
                    float(levels_mapping[axis]) for axis in ARM_KEYS
                )
                levels_by_identity[levels_identity] = (
                    levels,
                    arm_levels,
                )
            else:
                levels, arm_levels = levels_row
            matching_domains = domain_index.get(
                (int(claim.domain_epoch), arm_levels), ()
            )
            if len(matching_domains) != 1:
                raise RuntimeError(
                    "birth domain claim is not one exact frozen curriculum "
                    "domain"
                )
            domain = matching_domains[0]
            slot = int(request.action_slot)
            if (
                slot < 0
                or slot >= len(self._action_ball_bindings)
                or self._action_ball_bindings[slot] != request.binding
                or request.binding.action_uid != uid
                or claim.action_uid != uid
                or claim.profile_sha256 != key.profile_sha256
                or claim.arm_catalog_sha256 != ARM_CATALOG_SHA256
            ):
                raise RuntimeError(
                    "birth request action/domain binding drifted before "
                    "sampler reservation"
                )
            prepared.append(
                (
                    request,
                    claim,
                    uid,
                    slot,
                    domain,
                    levels,
                )
            )

        staged = []
        staged_digests = set()
        for request, claim, uid, slot, domain, levels in prepared:
            # This is deliberately sequential in the caller's row order.
            # Per-action counter RNGs therefore see the exact scalar sequence.
            sampler_birth = self._action_ball_sampler.reserve_birth(
                action_uid=uid,
                domain_epoch=int(claim.domain_epoch),
                levels=levels,
                base_yaw_rad=self._action_ball_ready_yaw[slot],
            )
            base_spawn = tuple(
                float(value)
                for value in sampler_birth.base_start_w_m
            )
            if not math.isclose(
                base_spawn[2],
                self._action_ball_ready_z[slot],
                rel_tol=0.0,
                abs_tol=1.0e-7,
            ):
                raise RuntimeError(
                    "sampler birth base Z differs from canonical ready"
                )
            receipt = ActionBirthReceipt(
                env_id=int(request.env_id),
                reset_generation=int(request.reset_generation),
                action_uid=uid,
                action_slot=slot,
                domain_epoch=int(claim.domain_epoch),
                domain_claim_sha256=claim.canonical_sha256,
                domain_authority_sha256=(
                    self._action_ball_pins.domain_authority_sha256
                ),
                domain_levels=claim.domain_levels,
                arm_catalog_sha256=ARM_CATALOG_SHA256,
                levels_sha256=claim.levels_sha256,
                sampler_birth_sha256=sampler_birth.birth_id,
                sampler_birth_index=int(sampler_birth.birth_index),
                sampler_draw_start=int(sampler_birth.draw_start),
                sampler_draw_end=int(sampler_birth.draw_end),
                mobility_mode=(
                    self._action_ball_manifest.mobility_mode
                ),
                base_yaw_rad=float(
                    self._action_ball_ready_yaw[slot]
                ),
                base_quat_wxyz=self._action_ball_ready_quat[slot],
                base_spawn_w_m=base_spawn,
                registry_sha256=(
                    self._action_ball_broker.registry_sha256
                ),
                manifest_sha256=(
                    self._action_ball_pins.manifest_sha256
                ),
                sampler_sha256=self._action_ball_pins.sampler_sha256,
                profile_sha256=request.binding.profile_sha256,
                motion_sha256=request.binding.motion_sha256,
                physics_sha256=self._action_ball_pins.physics_sha256,
                solver_sha256=self._action_ball_pins.solver_sha256,
                sampling_mixture=(
                    None
                    if sampler_birth.sampling_mixture is None
                    else ActionSamplingMixture.from_dict(
                        sampler_birth.sampling_mixture.as_dict()
                    )
                ),
                sampling_stratum=sampler_birth.sampling_stratum,
                sampling_levels=(
                    None
                    if sampler_birth.sampling_mixture is None
                    else ActionDomainLevels(
                        **sampler_birth.sampling_levels.as_dict()
                    )
                ),
                frontier_arm=sampler_birth.frontier_arm,
                # Same sampler-law record as the single-birth path above.
                initial_center_single_question=(
                    sampler_birth.sampling_mixture is not None
                    and self._action_ball_sampler.initial_center_single_question
                ),
            )
            receipt_sha256 = receipt.canonical_sha256
            if (
                receipt_sha256 in staged_digests
                or receipt_sha256
                in self._action_ball_provider_births
                or (
                    self._action_ball_fixed_view_enabled
                    and receipt_sha256
                    in self._action_ball_provider_history
                )
            ):
                raise RuntimeError(
                    "action-ball birth provider produced a duplicate "
                    "runtime receipt"
                )
            staged_digests.add(receipt_sha256)
            staged.append(
                (
                    receipt_sha256,
                    receipt,
                    sampler_birth,
                    str(domain.stratum),
                    levels,
                    float(domain.rho),
                )
            )

        for (
            receipt_sha256,
            receipt,
            sampler_birth,
            stratum,
            levels,
            rho,
        ) in staged:
            self._action_ball_provider_births[receipt_sha256] = {
                "runtime_birth": receipt,
                "sampler_birth": sampler_birth,
                "stratum": stratum,
                "levels": levels,
                "rho": rho,
            }
            if self._action_ball_fixed_view_enabled:
                # Exact fixed-view resume retains the legitimate birth tape,
                # but its per-birth task transcript is provably empty because
                # no ActionBallTaskReceipt exists in this data plane.
                self._action_ball_provider_history[
                    receipt_sha256
                ] = receipt
                self._action_ball_task_transcript_by_birth[
                    receipt_sha256
                ] = (
                    0,
                    task_transcript_sha256(receipt_sha256, ()),
                )
        return tuple(row[1] for row in staged)

    def _action_ball_assert_issued_birth(self, receipt) -> None:
        """Prove any broker-history receipt against the append-only sampler tape."""

        from whole_body_tracking.tasks.tracking.mdp.action_ball_runtime import (
            ActionBirthReceipt,
        )
        from whole_body_tracking.tasks.tracking.mdp.action_ball_sampling import (
            BaseBirthReceipt,
        )

        if not isinstance(receipt, ActionBirthReceipt):
            raise RuntimeError(
                "action-ball issued-birth check requires a birth receipt"
            )
        if ActionBirthReceipt.from_dict(receipt.to_dict()) != receipt:
            raise RuntimeError(
                "action-ball birth receipt failed exact identity round-trip"
            )
        if not 0 <= receipt.action_slot < len(self._action_ball_bindings):
            raise RuntimeError(
                "action-ball sampler birth has an invalid action slot"
            )
        binding = self._action_ball_bindings[receipt.action_slot]
        if binding.action_uid != receipt.action_uid:
            raise RuntimeError(
                "action-ball sampler birth action slot/UID binding drifted"
            )
        receipt.assert_contract(
            binding=binding,
            pins=self._action_ball_pins,
            mobility_mode=self._action_ball_manifest.mobility_mode,
            registry_sha256=self._action_ball_broker.registry_sha256,
        )
        sampler_birth = BaseBirthReceipt.from_identity_receipt(
            receipt.sampler_identity_receipt()
        )
        # ``ActionBallSampler.assert_issued_birth`` above is the issuance proof:
        # it re-derives the birth identity and requires an exact match against
        # the sampler's live issued-birth transcript.  That transcript is
        # maintained in every mode, including live-births-only.
        self._action_ball_sampler.assert_issued_birth(sampler_birth)
        if self._action_ball_birth_catalogs_are_live_only():
            if self._action_ball_provider_history:
                raise RuntimeError(
                    "action-ball run declares live-births-only bookkeeping but "
                    "kept a provider assignment transcript"
                )
        else:
            historical_receipt = self._action_ball_provider_history.get(
                receipt.canonical_sha256
            )
            if historical_receipt != receipt:
                raise RuntimeError(
                    "runtime birth is absent from the exact provider assignment transcript"
                )
        provider = self._action_ball_provider_births.get(
            receipt.canonical_sha256
        )
        if provider is not None and (
            provider["runtime_birth"] != receipt
            or provider["sampler_birth"] != sampler_birth
        ):
            raise RuntimeError(
                "active runtime birth disagrees with provider assignment history"
            )

    def _action_ball_refill_pool(self, request):
        """Scalar pool seam implemented by the same vectorized transaction as env batches."""

        return self._action_ball_refill_pool_many((request,))[0]

    def _action_ball_cache_reference_host_rows(self) -> None:
        """Materialize immutable per-action reference rows once after identity binding.

        Racket reference quaternion/angular-velocity tensors are populated once
        by ``_ensure_reference_strike_state`` and never mutated afterwards.
        Refill used to copy both complete tensors from device to host on every
        solver round.  Bind their exact action identity plus shape/device here,
        then retain a deep immutable host snapshot for receipt construction.
        """

        actions = tuple(self._action_ball_manifest.actions)
        bindings = tuple(self._action_ball_bindings)
        profile_sha256 = tuple(self._action_ball_bundle.profile_sha256)
        if (
            len(bindings) != len(actions)
            or len(profile_sha256) != len(actions)
        ):
            raise RuntimeError(
                "action-ball reference host cache identity cardinality differs "
                "from the ordered motion/profile bindings"
            )
        expected_identity = tuple(
            (
                str(action.action_id),
                int(action.action_uid),
                slot,
                str(action.motion_path),
                str(action.motion_sha256),
                str(profile_sha256[slot]),
            )
            for slot, action in enumerate(actions)
        )
        bound_identity = tuple(
            (
                str(action.action_id),
                int(binding.action_uid),
                int(binding.action_slot),
                str(binding.motion_path),
                str(binding.motion_sha256),
                str(binding.profile_sha256),
            )
            for action, binding in zip(actions, bindings)
        )
        if bound_identity != expected_identity:
            raise RuntimeError(
                "action-ball reference host cache identity differs from the "
                "ordered motion/profile bindings"
            )

        quat = self._ref_racket_quat_w_per_clip
        omega = self._ref_racket_ang_vel_w_per_clip
        velocity = self._ref_racket_vel_w_per_clip
        raw_normal = self._ref_racket_normal_raw_w_per_clip
        expected_device = str(self.device)
        metadata = (
            tuple(quat.shape),
            str(quat.device),
            str(quat.dtype),
            tuple(omega.shape),
            str(omega.device),
            str(omega.dtype),
            tuple(velocity.shape),
            str(velocity.device),
            str(velocity.dtype),
            tuple(raw_normal.shape),
            str(raw_normal.device),
            str(raw_normal.dtype),
        )
        if (
            metadata[0] != (len(actions), 4)
            or metadata[3] != (len(actions), 3)
            or metadata[6] != (len(actions), 3)
            or metadata[9] != (len(actions), 3)
            or metadata[1] != expected_device
            or metadata[4] != expected_device
            or metadata[7] != expected_device
            or metadata[10] != expected_device
            or not (
                metadata[2]
                == metadata[5]
                == metadata[8]
                == metadata[11]
            )
        ):
            raise RuntimeError(
                "action-ball reference host cache tensor shape/device/dtype "
                f"mismatch: expected_device={expected_device!r}, "
                f"metadata={metadata!r}"
            )

        # ``tolist`` owns fresh Python storage even when the source tensor is
        # already on CPU.  Nesting tuples makes the cache independent of every
        # mutable tensor/list view for the lifetime of this run.
        quat_rows = tuple(
            tuple(float(value) for value in row)
            for row in quat.detach().cpu().tolist()
        )
        omega_rows = tuple(
            tuple(float(value) for value in row)
            for row in omega.detach().cpu().tolist()
        )
        velocity_rows = tuple(
            tuple(float(value) for value in row)
            for row in velocity.detach().cpu().tolist()
        )
        raw_normal_rows = tuple(
            tuple(float(value) for value in row)
            for row in raw_normal.detach().cpu().tolist()
        )
        if (
            len(quat_rows) != len(actions)
            or any(len(row) != 4 for row in quat_rows)
            or len(omega_rows) != len(actions)
            or any(len(row) != 3 for row in omega_rows)
            or len(velocity_rows) != len(actions)
            or any(len(row) != 3 for row in velocity_rows)
            or len(raw_normal_rows) != len(actions)
            or any(len(row) != 3 for row in raw_normal_rows)
        ):
            raise RuntimeError(
                "action-ball reference host cache conversion changed tensor shape"
            )
        self._action_ball_reference_host_identity = expected_identity
        self._action_ball_reference_host_tensor_metadata = metadata
        self._action_ball_reference_quat_host_rows = quat_rows
        self._action_ball_reference_omega_host_rows = omega_rows
        self._action_ball_reference_velocity_host_rows = velocity_rows
        self._action_ball_reference_raw_normal_host_rows = raw_normal_rows

    def _action_ball_assert_emitted_sample(self, receipt) -> None:
        """Cross-check a task sample against live sampler/provider issuance state."""

        from whole_body_tracking.tasks.tracking.mdp.action_ball_runtime import (
            ActionBallTaskReceipt,
        )

        if not isinstance(receipt, ActionBallTaskReceipt):
            raise RuntimeError(
                "action-ball emitted-sample check requires a task receipt"
            )
        # Reparse the full JSON identity so this seam never trusts a mutated
        # dataclass-shaped object supplied by a solver callback.
        if ActionBallTaskReceipt.from_dict(receipt.to_dict()) != receipt:
            raise RuntimeError(
                "action-ball task receipt failed exact identity round-trip"
            )
        provider = self._action_ball_provider_births.get(
            receipt.birth_sha256
        )
        if (
            provider is None
            or provider["runtime_birth"].canonical_sha256
            != receipt.birth_sha256
            or provider["sampler_birth"].birth_id
            != receipt.sampler_birth_sha256
        ):
            raise RuntimeError(
                "action-ball task sample has no exact active provider birth"
            )
        # This is the provenance authority, not a high-water heuristic: it
        # excludes birth draw blocks, replays the exact counter-RNG sample and
        # compares every position/speed/spin/aim identity field.
        self._action_ball_sampler.assert_issued_sample(
            receipt.sampler_identity_receipt()
        )

    def _action_ball_assert_emitted_task_reference_and_timing(
        self,
        receipts,
    ) -> None:
        """Prove solver-independent measured-reference and timing fields."""

        from whole_body_tracking.tasks.tracking.mdp.action_ball_runtime import (
            derive_action_teacher_site_timing,
        )
        from whole_body_tracking.tasks.tracking.mdp import (
            racket_contact_geometry as contact_geometry,
        )

        reference_quat_rows = self._action_ball_reference_quat_host_rows
        reference_omega_rows = self._action_ball_reference_omega_host_rows
        for receipt in receipts:
            slot = receipt.action_slot
            profile = self._action_ball_bundle.profiles[slot]
            expected_reference_quat = contact_geometry.canonical_quat_wxyz(
                reference_quat_rows[slot]
            )
            expected_reference_omega = tuple(
                float(value) for value in reference_omega_rows[slot]
            )
            if (
                receipt.mount_normal_sign
                != self._action_ball_mount_signs[slot]
                or receipt.reference_racket_quat_wxyz
                != expected_reference_quat
                or receipt.reference_racket_angular_velocity_w_radps
                != expected_reference_omega
                or receipt.geometry_source_sha256
                != contact_geometry.GEOMETRY_SOURCE_SHA256
            ):
                raise RuntimeError(
                    "action-ball exact-face receipt differs from the selected "
                    "motion's sign/reference quaternion/angular velocity"
                )
            expected_timing = derive_action_teacher_site_timing(
                racket_site_velocity_w_mps=(
                    receipt.racket_site_velocity_w_mps
                ),
                time_to_contact_s=receipt.time_to_contact_s,
                reference_t_hit_s=profile.reference_t_hit_s,
                reference_t_cycle_s=profile.reference_t_cycle_s,
                reference_racket_site_speed_mps=(
                    profile.reference_racket_site_speed_mps
                ),
                reaction_margin_s=profile.reaction_margin_s,
                teacher_rate_min=profile.teacher_rate_min,
                teacher_rate_max=profile.teacher_rate_max,
            )
            if (
                receipt.reference_t_hit_s != profile.reference_t_hit_s
                or receipt.reference_t_cycle_s != profile.reference_t_cycle_s
                or receipt.reference_racket_site_speed_mps
                != profile.reference_racket_site_speed_mps
                or receipt.reaction_margin_s != profile.reaction_margin_s
                or receipt.teacher_rate_min != profile.teacher_rate_min
                or receipt.teacher_rate_max != profile.teacher_rate_max
                or receipt.required_racket_site_speed_mps
                != expected_timing.required_racket_site_speed_mps
                or receipt.teacher_rate != expected_timing.teacher_rate
                or receipt.scaled_t_hit_s != expected_timing.scaled_t_hit_s
                or receipt.scaled_t_cycle_s != expected_timing.scaled_t_cycle_s
                or receipt.pre_swing_wait_s != expected_timing.pre_swing_wait_s
            ):
                raise RuntimeError(
                    "action-ball task timing differs from the exact pinned "
                    "profile/formula"
                )
            if (
                receipt.pre_swing_wait_s
                + receipt.scaled_t_cycle_s
                + self._action_ball_attempt_close_margin_s
                > self._action_ball_episode_length_s + 1.0e-12
            ):
                raise RuntimeError(
                    "action-ball task timing exceeds the pinned episode horizon"
                )

    def _action_ball_replay_emitted_tasks(
        self,
        receipts,
        *,
        sampler,
        provider_history: dict,
        question_cache,
    ) -> None:
        """Purely replay one task batch through the pinned sampler and solver."""

        from whole_body_tracking.tasks.tracking.mdp.action_ball_runtime import (
            ActionBallTaskReceipt,
        )
        from whole_body_tracking.tasks.tracking.mdp.continuous_questions import (
            solve_proposals,
        )
        receipts = tuple(receipts)
        if not receipts:
            return
        canonical = []
        births = []
        for index, receipt in enumerate(receipts):
            if not isinstance(receipt, ActionBallTaskReceipt):
                raise RuntimeError(
                    f"action-ball emitted task {index} is not a task receipt"
                )
            if ActionBallTaskReceipt.from_dict(receipt.to_dict()) != receipt:
                raise RuntimeError(
                    "action-ball emitted task failed exact identity round-trip"
                )
            birth = provider_history.get(receipt.birth_sha256)
            if birth is None:
                raise RuntimeError(
                    "action-ball emitted task has no exact provider birth history"
                )
            if not 0 <= receipt.action_slot < len(self._action_ball_bindings):
                raise RuntimeError(
                    "action-ball emitted task has an invalid action slot"
                )
            binding = self._action_ball_bindings[receipt.action_slot]
            receipt.assert_contract(
                binding=binding,
                pins=self._action_ball_pins,
                mobility_mode=self._action_ball_manifest.mobility_mode,
                registry_sha256=self._action_ball_broker.registry_sha256,
            )
            receipt.assert_birth(birth)
            canonical.append(receipt)
            births.append(birth)
        if len({receipt.canonical_sha256 for receipt in canonical}) != len(
            canonical
        ):
            raise RuntimeError(
                "action-ball emitted task assertion repeated one receipt"
            )

        # One sampler batch proves every ball/base/TTC field.  The separate
        # solver call below proves fields owned by the deterministic adapter.
        sampler.assert_issued_samples(
            tuple(receipt.sampler_identity_receipt() for receipt in canonical)
        )
        if bool(getattr(self, "_counter_rally_enabled", False)):
            from whole_body_tracking.tasks.tracking.mdp.counter_rally import (
                precheck_counter_rally_fixed_solver_proposal,
            )

            expected_objective_sha256 = (
                self._counter_rally_objective.sha256
            )
            for receipt, birth in zip(canonical, births):
                identity = receipt.require_counter_rally_task(
                    expected_objective_profile_sha256=(
                        expected_objective_sha256
                    )
                )
                precheck = (
                    precheck_counter_rally_fixed_solver_proposal(
                        frozen_action_uid=int(receipt.action_uid),
                        solver_action_uid=int(
                            self._action_ball_bindings[
                                receipt.action_slot
                            ].action_uid
                        ),
                        expected_objective_profile_sha256=(
                            expected_objective_sha256
                        ),
                        base_goal_env_xy_m=(
                            receipt.base_goal_w_m[:2]
                        ),
                        base_yaw_env_rad=float(
                            birth.base_yaw_rad
                        ),
                        contact_offset_b_yaw_m=(
                            receipt.contact_offset_from_base_goal_b_yaw_m
                        ),
                        incoming_direction_b_yaw=(
                            receipt.incoming_direction_b_yaw[:2]
                        ),
                        incoming_ball_speed_at_contact_mps=float(
                            receipt.incoming_speed_mps
                        ),
                        landing_depth_env_x_m=float(
                            receipt.landing_aim_w_xy_m[0]
                        ),
                        profile=self._counter_rally_objective,
                    )
                )
                if not precheck.eligible_for_solver:
                    raise RuntimeError(
                        "admitted counter-rally task is rejected by "
                        "the pinned precheck during replay: "
                        f"{precheck.rejection_reason}"
                    )
                task = precheck.task
                if task is None or (
                    identity.objective_profile_sha256
                    != task.objective_profile_sha256
                ):
                    raise RuntimeError(
                        "counter-rally replay lost objective identity"
                    )
                if any(
                    not math.isclose(
                        float(actual),
                        float(expected),
                        rel_tol=0.0,
                        abs_tol=1.0e-12,
                    )
                    for actual, expected in (
                        *zip(
                            identity.return_direction_env_xy,
                            task.return_direction_env_xy,
                        ),
                        (
                            identity.target_baseline_speed_mps,
                            task.target_baseline_speed_mps,
                        ),
                        *zip(
                            receipt.landing_aim_w_xy_m,
                            task.landing_aim_env_xy_m,
                        ),
                    )
                ):
                    raise RuntimeError(
                        "counter-rally task receipt differs from pinned "
                        "precheck replay"
                    )
        if self._action_ball_target_source == "direct_ball":
            for receipt in canonical:
                slot = int(receipt.action_slot)
                expected_velocity = (
                    self._action_ball_reference_velocity_host_rows[slot]
                )
                expected_normal = (
                    self._action_ball_reference_raw_normal_host_rows[slot]
                )
                if (
                    receipt.racket_face_center_velocity_w_mps
                    != expected_velocity
                    or receipt.racket_normal_w != expected_normal
                    or receipt.solver_residual_m != 0.0
                ):
                    raise RuntimeError(
                        "direct-ball receipt carrier differs from the pinned "
                        "teacher reference rows"
                    )
            # Full receipt round-trip above already re-proves exact-face
            # geometry and teacher timing.  C211 deliberately has no inverse
            # ball-to-paddle target to replay.
            self._action_ball_assert_emitted_task_reference_and_timing(
                canonical
            )
            return
        if question_cache is not None:
            if self._action_ball_target_source != "online_solver":
                raise RuntimeError(
                    "exact-question answer cache is bound to a non-online target source"
                )
            from whole_body_tracking.tasks.tracking.mdp.action_ball_question_cache import (
                exact_question_sha256,
            )

            for receipt, birth in zip(canonical, births):
                slot = int(receipt.action_slot)
                question_sha256 = exact_question_sha256(
                    _action_ball_exact_question_payload(
                        action_uid=int(receipt.action_uid),
                        action_slot=slot,
                        birth=birth,
                        sample=receipt,
                        mount_normal_sign=int(
                            self._action_ball_mount_signs[slot]
                        ),
                    )
                )
                answer = question_cache.peek(
                    action_uid=int(receipt.action_uid),
                    question_sha256=question_sha256,
                )
                if answer is None:
                    raise RuntimeError(
                        "cache-enabled emitted task has no exact semantic answer"
                    )
                velocity, normal, residual = answer.values()
                if (
                    not answer.admitted
                    or answer.reason_code != -1
                    or velocity
                    != receipt.racket_face_center_velocity_w_mps
                    or normal != receipt.racket_normal_w
                    or residual != receipt.solver_residual_m
                ):
                    raise RuntimeError(
                        "cache-enabled emitted task differs from its exact IEEE answer"
                    )
            # The sampler assertion above still replays every question/RNG row.
            # Only the deterministic inverse answer is reused, so neither pool
            # purity checks nor cold-resume validation call the inverse again.
            self._action_ball_assert_emitted_task_reference_and_timing(
                canonical
            )
            return
        dtype = self._ref_racket_normal_raw_w_per_clip.dtype
        clip_ids = torch.tensor(
            [receipt.action_slot for receipt in canonical],
            dtype=torch.long,
            device=self.device,
        )
        contact = torch.tensor(
            [receipt.ball_contact_w_m for receipt in canonical],
            dtype=dtype,
            device=self.device,
        )
        incoming = torch.tensor(
            [receipt.incoming_velocity_w_mps for receipt in canonical],
            dtype=dtype,
            device=self.device,
        )
        spin = torch.tensor(
            [receipt.incoming_spin_w_radps for receipt in canonical],
            dtype=dtype,
            device=self.device,
        )
        aim = torch.tensor(
            [receipt.landing_aim_w_xy_m for receipt in canonical],
            dtype=dtype,
            device=self.device,
        )
        ref_normal = self._ref_racket_normal_raw_w_per_clip.index_select(
            0, clip_ids
        )
        base_quat = torch.tensor(
            [birth.base_quat_wxyz for birth in births],
            dtype=dtype,
            device=self.device,
        )
        surface_z, net_x, net_top_z = self._action_ball_planes
        rollout_h = float(self.cfg.vb_rollout_h)
        rollout_steps = int(self.cfg.vb_rollout_steps)
        # Replay must be solved by the same numbers the pin declares, or a
        # "pinned solver replay" that passes proves nothing.  overdraw/rounds are
        # not consulted on this path (one solve, no redraw), so they are declared
        # absent rather than compared against a value nobody uses.
        action_ball_assert_solver_adapter_binds_these_entry_points(
            adapter=self._action_ball_pool_solver,
            expected={
                "solve": self._action_ball_refill_pool,
                "solve_many": self._action_ball_refill_pool_many,
                "assert_emitted_sample": (
                    self._action_ball_assert_emitted_sample
                ),
                "assert_emitted_tasks": self._action_ball_assert_emitted_tasks,
                "emitted_task_count_for": (
                    self._action_ball_emitted_task_count_for
                ),
                "task_transcript_for_birth": (
                    self._action_ball_task_transcript_for_birth
                ),
                "assert_proposal_assignments": (
                    self._action_ball_assert_proposal_assignments
                ),
            },
            call_site="_action_ball_replay_emitted_tasks",
            required=False,
        )
        action_ball_assert_solver_runtime_matches_declaration(
            solver_declaration=self._action_ball_solver_contract["payload"],
            physics_declaration=self._action_ball_physics_contract["payload"],
            answer_input_declaration=(
                self._action_ball_answer_input_contract["payload"]
            ),
            expected_solver_profile_sha256=(
                self._action_ball_manifest.solver_profile_sha256
            ),
            expected_prototype_file_sha256=(
                self._action_ball_manifest.prototype.sha256
            ),
            prototypes=self._action_ball_prototypes,
            reference_normal_rows=self._ref_racket_normal_raw_w_per_clip,
            solver_cfg=self._action_ball_solver_cfg,
            prm=self._action_ball_prm,
            planes=(surface_z, net_x, net_top_z),
            rollout_h=rollout_h,
            rollout_steps=rollout_steps,
            overdraw=None,
            maximum_rounds=None,
            diagnostic_unauthorized=bool(
                getattr(self, "_action_ball_diagnostic_unauthorized", False)
            ),
            call_site="_action_ball_replay_emitted_tasks",
        )
        result = solve_proposals(
            clip_ids,
            contact,
            incoming,
            spin,
            aim,
            ref_normal,
            protos=self._action_ball_prototypes,
            base_quat=base_quat,
            prm=self._action_ball_prm,
            surface_z=surface_z,
            net_x=net_x,
            net_top_z=net_top_z,
            cfg=self._action_ball_solver_cfg,
            h=rollout_h,
            n_steps=rollout_steps,
        )
        if (
            tuple(result.ok.shape) != (len(canonical),)
            or not bool(result.ok.all())
            or result.reason_counts
        ):
            raise RuntimeError(
                "action-ball admitted task is not admitted by pinned solver replay"
            )
        expected_velocity = torch.tensor(
            [
                receipt.racket_face_center_velocity_w_mps
                for receipt in canonical
            ],
            dtype=dtype,
            device=self.device,
        )
        expected_normal = torch.tensor(
            [receipt.racket_normal_w for receipt in canonical],
            dtype=dtype,
            device=self.device,
        )
        expected_residual = torch.tensor(
            [receipt.solver_residual_m for receipt in canonical],
            dtype=dtype,
            device=self.device,
        )
        if (
            not torch.equal(result.v_racket, expected_velocity)
            or not torch.equal(result.n_racket, expected_normal)
            or not torch.equal(result.resid_m, expected_residual)
        ):
            raise RuntimeError(
                "action-ball task solver outputs differ from deterministic replay"
            )
        self._action_ball_assert_emitted_task_reference_and_timing(canonical)

    def _action_ball_assert_emitted_tasks(self, receipts) -> None:
        """Batch proof for all sampler, solver, timing, and birth-owned fields."""

        self._action_ball_replay_emitted_tasks(
            tuple(receipts),
            sampler=self._action_ball_sampler,
            provider_history=self._action_ball_provider_history,
            question_cache=self._action_ball_exact_question_cache,
        )

    def _action_ball_emitted_task_count_for(self, action_uid: int) -> int:
        """Pure O(1) count of admitted tasks this solver has emitted for one action.

        This is a live running counter, not a view over the per-birth task
        transcript.  It is maintained in every mode, including the
        live-births-only one where that transcript is deliberately never
        written; do not describe it as a cache over the transcript.
        """

        if type(action_uid) is not int or action_uid not in (
            self._action_ball_emitted_task_count_by_uid
        ):
            raise RuntimeError(
                f"action-ball task count requested unknown action_uid {action_uid!r}"
            )
        return int(self._action_ball_emitted_task_count_by_uid[action_uid])

    def _action_ball_task_transcript_for_birth(
        self, birth_sha256: str
    ) -> tuple[int, str]:
        """Return the compact ordered admitted-task count/hash-chain root."""

        if self._action_ball_birth_catalogs_are_live_only():
            raise RuntimeError(
                "live-births-only action-ball runs keep no solver-side per-birth "
                "task transcript; the pool owns those roots"
            )
        if (
            type(birth_sha256) is not str
            or birth_sha256 not in self._action_ball_provider_history
            or birth_sha256 not in self._action_ball_task_transcript_by_birth
        ):
            raise RuntimeError(
                "action-ball task transcript requested unknown birth"
            )
        count, root = self._action_ball_task_transcript_by_birth[birth_sha256]
        return int(count), str(root)

    def _action_ball_assert_proposal_assignments_against(
        self,
        assignments,
        *,
        sampler,
        provider_history: dict,
    ) -> None:
        """Pure cross-view check for every proposed sample's episode birth.

        The sampler owns the action-local ``sample_index -> birth_index``
        assignment ledger.  The provider history independently supplies the
        exact runtime birth receipt used by the pool segment.  Replaying the
        pair proves those two in-checkpoint views agree without advancing the
        random tape.  This is deliberately not described as external checkpoint
        authentication: formal resume still needs the runner's pre-existing raw
        checkpoint and shared-state-root pins.
        """

        from whole_body_tracking.tasks.tracking.mdp.action_ball_runtime import (
            ActionSampleAssignment,
        )

        assignments = tuple(assignments)
        replay_requests = []
        seen_samples = set()
        for index, assignment in enumerate(assignments):
            if type(assignment) is not ActionSampleAssignment:
                raise RuntimeError(
                    "action-ball proposal assignment "
                    f"{index} has a forged runtime type"
                )
            birth = assignment.birth
            birth_sha = birth.canonical_sha256
            if provider_history.get(birth_sha) != birth:
                raise RuntimeError(
                    "action-ball proposal assignment has no exact provider "
                    "birth history"
                )
            sampler_birth = birth.sampler_identity_receipt()
            for sample_index in assignment.proposal_sample_indices:
                sample_key = (int(birth.action_uid), int(sample_index))
                if sample_key in seen_samples:
                    raise RuntimeError(
                        "action-ball proposal assignments repeat one "
                        "action-local sample index"
                    )
                seen_samples.add(sample_key)
                replay_requests.append(
                    (sampler_birth, int(sample_index))
                )
        # ``replay_issued_samples`` consults the sampler-owned compact
        # assignment ledger before reconstructing each exact 18-draw sample.
        # No caller-provided sample payload is accepted here.
        replayed = sampler.replay_issued_samples(tuple(replay_requests))
        if len(replayed) != len(replay_requests):
            raise RuntimeError(
                "action-ball sampler returned the wrong proposal replay count"
            )

    def _action_ball_assert_proposal_assignments(
        self, assignments
    ) -> None:
        """Check live pool segments against sampler and provider history."""

        self._action_ball_assert_proposal_assignments_against(
            tuple(assignments),
            sampler=self._action_ball_sampler,
            provider_history=self._action_ball_provider_history,
        )

    def _action_ball_refill_pool_many(self, requests):
        """Flatten all active refill rows and solve each proposal round in one Torch batch.

        Sampling remains on the action-specific deterministic tapes, but solver work scales with
        the number of proposal rows rather than the number of environments.  The pool snapshots
        this adapter's full mutable state before the callback, so a malformed row rolls back the
        complete flattened transaction.
        """

        from whole_body_tracking.tasks.tracking.mdp.action_ball_runtime import (
            ActionBallContractError,
            ActionBallTaskReceipt,
            ActionPoolRefillBatch,
            _diagnostic_prevalidated_task_receipt_from_birth,
            derive_action_teacher_site_timing,
        )
        from whole_body_tracking.tasks.tracking.mdp.continuous_questions import (
            BALL_BIRTH_NET_MARGIN_M,
            _CONTINUOUS_REASONS,
            _DIAGNOSTIC_PREVALIDATED_SOLVE_AUTHORITY,
            _solve_proposals_diagnostic_host_only,
            ball_birth_x_lower_bound_m,
            solve_proposals,
        )
        from whole_body_tracking.tasks.tracking.mdp import (
            racket_contact_geometry as contact_geometry,
        )

        requests = tuple(requests)
        if not requests:
            raise RuntimeError("action-ball refill batch must be non-empty")
        # Source-level tensor tests construct a narrow command view with
        # ``__new__``/SimpleNamespace.  Absence is the safe, historical
        # cache-disabled behavior; real runtimes always bind the attribute in
        # ``_load_action_ball_runtime``.
        live_question_cache = getattr(
            self, "_action_ball_exact_question_cache", None
        )
        target_source = getattr(
            self, "_action_ball_target_source", "online_solver"
        )
        staged_question_cache = (
            None
            if live_question_cache is None
            else live_question_cache.clone()
        )
        diagnostic_unauthorized = getattr(
            self,
            "_action_ball_diagnostic_unauthorized",
            False,
        )
        if type(diagnostic_unauthorized) is not bool:
            raise RuntimeError(
                "action-ball diagnostic_unauthorized must be an exact boolean"
            )
        if diagnostic_unauthorized:
            def task_receipt_from_birth(birth, **kwargs):
                return (
                    _diagnostic_prevalidated_task_receipt_from_birth(
                        birth,
                        **kwargs,
                    )
                )
        else:
            task_receipt_from_birth = ActionBallTaskReceipt.from_birth
        if hasattr(
            self,
            "_action_ball_effective_cq_max_redraw_rounds",
        ):
            maximum_rounds = int(
                self._action_ball_effective_cq_max_redraw_rounds
            )
        else:
            maximum_rounds = int(self.cfg.cq_max_redraw_rounds)
        if hasattr(self, "_action_ball_effective_cq_overdraw"):
            effective_cq_overdraw = float(
                self._action_ball_effective_cq_overdraw
            )
        else:
            effective_cq_overdraw = float(self.cfg.cq_overdraw)
        surface_z, net_x, net_top_z = self._action_ball_planes
        rollout_h = float(self.cfg.vb_rollout_h)
        rollout_steps = int(self.cfg.vb_rollout_steps)
        # Every number below comes out of the boot wiring function, which the
        # semantic surface excludes.  Compare it to the sealed profile before a
        # single question is drawn: this call site is covered, so removing it
        # moves the pin.
        action_ball_assert_solver_adapter_binds_these_entry_points(
            adapter=self._action_ball_pool_solver,
            expected={
                "solve": self._action_ball_refill_pool,
                "solve_many": self._action_ball_refill_pool_many,
                "assert_emitted_sample": (
                    self._action_ball_assert_emitted_sample
                ),
                "assert_emitted_tasks": self._action_ball_assert_emitted_tasks,
                "emitted_task_count_for": (
                    self._action_ball_emitted_task_count_for
                ),
                "task_transcript_for_birth": (
                    self._action_ball_task_transcript_for_birth
                ),
                "assert_proposal_assignments": (
                    self._action_ball_assert_proposal_assignments
                ),
            },
            call_site="_action_ball_refill_pool_many",
            required=True,
        )
        action_ball_assert_solver_runtime_matches_declaration(
            solver_declaration=self._action_ball_solver_contract["payload"],
            physics_declaration=self._action_ball_physics_contract["payload"],
            answer_input_declaration=(
                self._action_ball_answer_input_contract["payload"]
            ),
            expected_solver_profile_sha256=(
                self._action_ball_manifest.solver_profile_sha256
            ),
            expected_prototype_file_sha256=(
                self._action_ball_manifest.prototype.sha256
            ),
            prototypes=self._action_ball_prototypes,
            reference_normal_rows=self._ref_racket_normal_raw_w_per_clip,
            solver_cfg=self._action_ball_solver_cfg,
            prm=self._action_ball_prm,
            planes=(surface_z, net_x, net_top_z),
            rollout_h=rollout_h,
            rollout_steps=rollout_steps,
            overdraw=effective_cq_overdraw,
            maximum_rounds=maximum_rounds,
            diagnostic_unauthorized=diagnostic_unauthorized,
            call_site="_action_ball_refill_pool_many",
        )
        dtype = self._ref_racket_normal_raw_w_per_clip.dtype
        states = []
        seen_births = set()
        for request in requests:
            birth_sha = request.birth.canonical_sha256
            if birth_sha in seen_births:
                raise RuntimeError("action-ball refill batch repeated one episode birth")
            seen_births.add(birth_sha)
            provider = self._action_ball_provider_births.get(birth_sha)
            if provider is None or provider["runtime_birth"] != request.birth:
                raise RuntimeError(
                    "task pool requested a birth absent from exact provider state"
                )
            slot = int(request.action_slot)
            if (
                slot < 0
                or slot >= len(self._action_ball_bindings)
                or self._action_ball_bindings[slot].action_uid
                != int(request.action_uid)
            ):
                raise RuntimeError("action-ball refill action slot/UID binding drifted")
            states.append(
                {
                    "request": request,
                    "sampler_birth": provider["sampler_birth"],
                    "levels": provider["levels"],
                    "slot": slot,
                    "minimum": int(request.minimum_receipts),
                    "proposed": 0,
                    "proposal_sample_indices": [],
                    "receipts": [],
                }
            )

        reason_schema = tuple(
            self._action_ball_solver_contract["payload"]["acceptance"][
                "ordered_rejection_reason_schema"
            ]
        )
        solver_reason_schema = tuple(_CONTINUOUS_REASONS)
        if reason_schema[: len(solver_reason_schema)] != solver_reason_schema:
            raise RuntimeError(
                "action-ball solver profile rejection ABI does not match "
                "the live continuous-question producer"
            )
        known_reasons = set(reason_schema)
        counter_rally_enabled = bool(
            getattr(self, "_counter_rally_enabled", False)
        )
        counter_rally_task_identity_type = None
        counter_rally_precheck = None
        if counter_rally_enabled:
            from whole_body_tracking.tasks.tracking.mdp.action_ball_runtime import (
                CounterRallyTaskIdentity,
            )
            from whole_body_tracking.tasks.tracking.mdp.counter_rally import (
                precheck_counter_rally_fixed_solver_proposal,
            )

            counter_rally_task_identity_type = CounterRallyTaskIdentity
            counter_rally_precheck = (
                precheck_counter_rally_fixed_solver_proposal
            )
        for _round in range(maximum_rounds):
            flat_samples = []
            flat_state_indices = []
            for state_index, state in enumerate(states):
                remaining = state["minimum"] - len(state["receipts"])
                if remaining <= 0:
                    continue
                proposal_rows = max(
                    remaining,
                    int(
                        math.ceil(
                            remaining * effective_cq_overdraw
                        )
                    ),
                )
                request = state["request"]
                if diagnostic_unauthorized:
                    samples = (
                        self._action_ball_sampler.sample_many_prevalidated(
                            birth=state["sampler_birth"],
                            action_uid=int(request.action_uid),
                            domain_epoch=int(
                                request.birth.domain_epoch
                            ),
                            levels=state["levels"],
                            base_yaw_rad=float(
                                request.birth.base_yaw_rad
                            ),
                            count=proposal_rows,
                        )
                    )
                else:
                    samples = [
                        self._action_ball_sampler.sample(
                            birth=state["sampler_birth"],
                            action_uid=int(request.action_uid),
                            domain_epoch=int(
                                request.birth.domain_epoch
                            ),
                            levels=state["levels"],
                            base_yaw_rad=float(
                                request.birth.base_yaw_rad
                            ),
                        )
                        for _ in range(proposal_rows)
                    ]
                state["proposed"] += len(samples)
                state["proposal_sample_indices"].extend(
                    int(sample.sample_index) for sample in samples
                )
                self._action_ball_note(state["slot"], "P", len(samples))
                flat_samples.extend(samples)
                flat_state_indices.extend([state_index] * len(samples))
            if not flat_samples:
                break

            counter_rally_tasks = [None] * len(flat_samples)
            if counter_rally_enabled:
                eligible_samples = []
                eligible_state_indices = []
                eligible_tasks = []
                expected_objective_sha256 = (
                    self._counter_rally_objective.sha256
                )
                for index, (sample, state_index) in enumerate(
                    zip(flat_samples, flat_state_indices)
                ):
                    state = states[state_index]
                    request = state["request"]
                    precheck = (
                        counter_rally_precheck(
                            frozen_action_uid=int(
                                request.action_uid
                            ),
                            solver_action_uid=int(
                                self._action_ball_bindings[
                                    state["slot"]
                                ].action_uid
                            ),
                            expected_objective_profile_sha256=(
                                expected_objective_sha256
                            ),
                            base_goal_env_xy_m=(
                                sample.base_goal_w_m[:2]
                            ),
                            base_yaw_env_rad=float(
                                request.birth.base_yaw_rad
                            ),
                            contact_offset_b_yaw_m=(
                                sample.contact_offset_from_base_goal_b_yaw_m
                            ),
                            incoming_direction_b_yaw=(
                                sample.incoming_direction_b_yaw[:2]
                            ),
                            incoming_ball_speed_at_contact_mps=float(
                                sample.incoming_speed_mps
                            ),
                            landing_depth_env_x_m=float(
                                sample.landing_aim_w_xy_m[0]
                            ),
                            profile=self._counter_rally_objective,
                        )
                    )
                    if not precheck.eligible_for_solver:
                        reason = precheck.rejection_reason
                        if reason not in known_reasons:
                            raise RuntimeError(
                                "counter-rally precheck returned an "
                                f"unpinned rejection reason {reason!r}"
                            )
                        reject_counts = (
                            self._action_ball_reject_counts[
                                int(request.action_uid)
                            ]
                        )
                        reject_counts[reason] = (
                            reject_counts.get(reason, 0) + 1
                        )
                        continue
                    task = precheck.task
                    if task is None:
                        raise RuntimeError(
                            "eligible counter-rally precheck has no task"
                        )
                    if any(
                        not math.isclose(
                            float(actual),
                            float(expected),
                            rel_tol=0.0,
                            abs_tol=1.0e-12,
                        )
                        for actual, expected in zip(
                            task.landing_aim_env_xy_m,
                            sample.landing_aim_w_xy_m,
                        )
                    ):
                        raise RuntimeError(
                            "counter-rally sampler and fixed-solver "
                            "reverse-ray aims disagree"
                        )
                    eligible_samples.append(sample)
                    eligible_state_indices.append(state_index)
                    eligible_tasks.append(task)
                flat_samples = eligible_samples
                flat_state_indices = eligible_state_indices
                counter_rally_tasks = eligible_tasks
                if not flat_samples:
                    continue

            clip_ids = torch.tensor(
                [states[index]["slot"] for index in flat_state_indices],
                dtype=torch.long,
                device=self.device,
            )
            if diagnostic_unauthorized:
                # The five producer-owned host rectangles share one dtype/device and are consumed
                # in this exact field/row order.  Flatten them field-major into one H2D transfer;
                # each reshaped slice stays contiguous and has the same float32 values as the
                # former five torch.tensor constructions.
                solver_row_count = len(flat_samples)
                solver_host_rectangles = (
                    [],
                    [],
                    [],
                    [],
                    [],
                )
                solver_field_contract = (
                    ("contact_w_m", 3),
                    ("incoming_velocity_w_mps", 3),
                    ("spin_w_radps", 3),
                    ("landing_aim_w_xy_m", 2),
                    ("base_quat_wxyz", 4),
                )
                for proposal_index, (sample, state_index) in enumerate(
                    zip(flat_samples, flat_state_indices)
                ):
                    solver_host_rows = (
                        sample.contact_w_m,
                        sample.incoming_velocity_w_mps,
                        sample.spin_w_radps,
                        sample.landing_aim_w_xy_m,
                        states[state_index][
                            "request"
                        ].birth.base_quat_wxyz,
                    )
                    for rectangle, (field_name, expected_width), row in zip(
                        solver_host_rectangles,
                        solver_field_contract,
                        solver_host_rows,
                    ):
                        try:
                            frozen_row = tuple(row)
                        except TypeError as error:
                            raise RuntimeError(
                                "diagnostic action-ball solver host field "
                                f"{field_name} row {proposal_index} must be a sequence"
                            ) from error
                        if len(frozen_row) != expected_width:
                            raise RuntimeError(
                                "diagnostic action-ball solver host field "
                                f"{field_name} row {proposal_index} must have exactly "
                                f"{expected_width} values, got {len(frozen_row)}"
                            )
                        rectangle.append(frozen_row)
                solver_float_values = torch.tensor(
                    [
                        value
                        for rectangle in solver_host_rectangles
                        for row in rectangle
                        for value in row
                    ],
                    dtype=dtype,
                    device=self.device,
                )
                contact = solver_float_values[
                    0 : 3 * solver_row_count
                ].view(solver_row_count, 3)
                incoming = solver_float_values[
                    3 * solver_row_count : 6 * solver_row_count
                ].view(solver_row_count, 3)
                spin = solver_float_values[
                    6 * solver_row_count : 9 * solver_row_count
                ].view(solver_row_count, 3)
                aim = solver_float_values[
                    9 * solver_row_count : 11 * solver_row_count
                ].view(solver_row_count, 2)
                base_quat = solver_float_values[
                    11 * solver_row_count : 15 * solver_row_count
                ].view(solver_row_count, 4)
            else:
                contact = torch.tensor(
                    [sample.contact_w_m for sample in flat_samples],
                    dtype=dtype,
                    device=self.device,
                )
                incoming = torch.tensor(
                    [sample.incoming_velocity_w_mps for sample in flat_samples],
                    dtype=dtype,
                    device=self.device,
                )
                spin = torch.tensor(
                    [sample.spin_w_radps for sample in flat_samples],
                    dtype=dtype,
                    device=self.device,
                )
                aim = torch.tensor(
                    [sample.landing_aim_w_xy_m for sample in flat_samples],
                    dtype=dtype,
                    device=self.device,
                )
                base_quat = torch.tensor(
                    [
                        states[index]["request"].birth.base_quat_wxyz
                        for index in flat_state_indices
                    ],
                    dtype=dtype,
                    device=self.device,
                )
            ref_normal = self._ref_racket_normal_raw_w_per_clip.index_select(
                0, clip_ids
            )
            solver_kwargs = {
                "protos": self._action_ball_prototypes,
                "base_quat": base_quat,
                "prm": self._action_ball_prm,
                "surface_z": surface_z,
                "net_x": net_x,
                "net_top_z": net_top_z,
                "cfg": self._action_ball_solver_cfg,
                "h": rollout_h,
                "n_steps": rollout_steps,
            }
            if target_source == "direct_ball":
                from whole_body_tracking.tasks.tracking.mdp.continuous_questions import (
                    ProposalHostPacket,
                )

                # C211 has no desired-contact inverse target.  Its task is the
                # sampler-owned incoming ball plus landing aim; these reference
                # rows are receipt carriers only and all desired p/v/face
                # validity bits/rewards remain zero.  No LM/analytic inverse is
                # called on reset.
                direct_slots = [
                    int(states[index]["slot"])
                    for index in flat_state_indices
                ]
                host_packet = ProposalHostPacket(
                    reason_codes=tuple(-1 for _ in direct_slots),
                    admitted=tuple(True for _ in direct_slots),
                    racket_velocity_rows=tuple(
                        self._action_ball_reference_velocity_host_rows[slot]
                        for slot in direct_slots
                    ),
                    racket_normal_rows=tuple(
                        self._action_ball_reference_raw_normal_host_rows[slot]
                        for slot in direct_slots
                    ),
                    residual_rows=tuple(0.0 for _ in direct_slots),
                )
                solver_reason_counts = {}
            elif staged_question_cache is None:
                if diagnostic_unauthorized:
                    (
                        host_packet,
                        solver_reason_counts,
                    ) = _solve_proposals_diagnostic_host_only(
                        clip_ids,
                        contact,
                        incoming,
                        spin,
                        aim,
                        ref_normal,
                        _diagnostic_prevalidated_authority=(
                            _DIAGNOSTIC_PREVALIDATED_SOLVE_AUTHORITY
                        ),
                        **solver_kwargs,
                    )
                else:
                    result = solve_proposals(
                        clip_ids,
                        contact,
                        incoming,
                        spin,
                        aim,
                        ref_normal,
                        **solver_kwargs,
                    )
                    host_packet = result.proposal_host_packet
                    if host_packet is None:
                        raise RuntimeError(
                            "fixed-action solver omitted its immutable host result packet"
                        )
                    solver_reason_counts = result.reason_counts
            else:
                from whole_body_tracking.tasks.tracking.mdp.action_ball_question_cache import (
                    CachedQuestionAnswer,
                    exact_question_sha256,
                )
                from whole_body_tracking.tasks.tracking.mdp.continuous_questions import (
                    ProposalHostPacket,
                )

                question_keys = []
                action_uids = []
                birth_sha256s = []
                for sample, state_index in zip(
                    flat_samples, flat_state_indices
                ):
                    state = states[state_index]
                    request = state["request"]
                    slot = int(state["slot"])
                    question_keys.append(
                        exact_question_sha256(
                            _action_ball_exact_question_payload(
                                action_uid=int(request.action_uid),
                                action_slot=slot,
                                birth=request.birth,
                                sample=sample,
                                mount_normal_sign=int(
                                    self._action_ball_mount_signs[slot]
                                ),
                            )
                        )
                    )
                    action_uids.append(int(request.action_uid))
                    birth_sha256s.append(request.birth.canonical_sha256)

                answers = [None] * len(question_keys)
                unique_miss_indices = []
                first_miss_by_key = {}
                duplicate_of = {}
                for index, (uid, key) in enumerate(
                    zip(action_uids, question_keys)
                ):
                    cached = staged_question_cache.peek(
                        action_uid=uid, question_sha256=key
                    )
                    if cached is not None:
                        answers[index] = staged_question_cache.note_hit(
                            action_uid=uid,
                            question_sha256=key,
                            birth_sha256=birth_sha256s[index],
                        )
                        continue
                    identity = (uid, key)
                    if identity in first_miss_by_key:
                        duplicate_of[index] = first_miss_by_key[identity]
                    else:
                        first_miss_by_key[identity] = index
                        unique_miss_indices.append(index)

                if unique_miss_indices:
                    selector = torch.tensor(
                        unique_miss_indices,
                        dtype=torch.long,
                        device=self.device,
                    )
                    miss_clip_ids = clip_ids.index_select(0, selector)
                    miss_contact = contact.index_select(0, selector)
                    miss_incoming = incoming.index_select(0, selector)
                    miss_spin = spin.index_select(0, selector)
                    miss_aim = aim.index_select(0, selector)
                    miss_ref_normal = ref_normal.index_select(0, selector)
                    miss_kwargs = dict(solver_kwargs)
                    miss_kwargs["base_quat"] = base_quat.index_select(
                        0, selector
                    )
                    if diagnostic_unauthorized:
                        miss_packet, _ = (
                            _solve_proposals_diagnostic_host_only(
                                miss_clip_ids,
                                miss_contact,
                                miss_incoming,
                                miss_spin,
                                miss_aim,
                                miss_ref_normal,
                                _diagnostic_prevalidated_authority=(
                                    _DIAGNOSTIC_PREVALIDATED_SOLVE_AUTHORITY
                                ),
                                **miss_kwargs,
                            )
                        )
                    else:
                        miss_result = solve_proposals(
                            miss_clip_ids,
                            miss_contact,
                            miss_incoming,
                            miss_spin,
                            miss_aim,
                            miss_ref_normal,
                            **miss_kwargs,
                        )
                        miss_packet = miss_result.proposal_host_packet
                        if miss_packet is None:
                            raise RuntimeError(
                                "fixed-action solver omitted its immutable "
                                "host result packet"
                            )
                    for miss_row, original_index in enumerate(
                        unique_miss_indices
                    ):
                        answer = CachedQuestionAnswer.from_values(
                            reason_code=miss_packet.reason_codes[miss_row],
                            admitted=miss_packet.admitted[miss_row],
                            racket_velocity=(
                                miss_packet.racket_velocity_rows[miss_row]
                            ),
                            racket_normal=(
                                miss_packet.racket_normal_rows[miss_row]
                            ),
                            residual=miss_packet.residual_rows[miss_row],
                        )
                        staged_question_cache.install_novel(
                            action_uid=action_uids[original_index],
                            question_sha256=question_keys[original_index],
                            answer=answer,
                            birth_sha256=(
                                birth_sha256s[original_index]
                            ),
                        )
                        answers[original_index] = answer
                for index, original_index in duplicate_of.items():
                    answer = answers[original_index]
                    if answer is None:
                        raise RuntimeError(
                            "in-batch exact-question producer answer missing"
                        )
                    staged_question_cache.note_in_batch_reuse(
                        action_uid=action_uids[index],
                        question_sha256=question_keys[index],
                        answer=answer,
                        birth_sha256=birth_sha256s[index],
                    )
                    answers[index] = answer
                if any(answer is None for answer in answers):
                    raise RuntimeError(
                        "exact-question cache did not resolve every proposal"
                    )
                unpacked = [answer.values() for answer in answers]
                host_packet = ProposalHostPacket(
                    reason_codes=tuple(
                        answer.reason_code for answer in answers
                    ),
                    admitted=tuple(answer.admitted for answer in answers),
                    racket_velocity_rows=tuple(
                        values[0] for values in unpacked
                    ),
                    racket_normal_rows=tuple(
                        values[1] for values in unpacked
                    ),
                    residual_rows=tuple(values[2] for values in unpacked),
                )
                solver_reason_counts = {}
                for admitted, code in zip(
                    host_packet.admitted, host_packet.reason_codes
                ):
                    if admitted:
                        continue
                    name = reason_schema[code]
                    solver_reason_counts[name] = (
                        solver_reason_counts.get(name, 0) + 1
                    )
            unknown_reasons = sorted(
                set(solver_reason_counts) - known_reasons
            )
            if unknown_reasons:
                raise RuntimeError(
                    "fixed-action solver returned reasons outside its pinned schema: "
                    f"{unknown_reasons}"
                )
            # Admission and reason are locally amended by the exact-face/timing prefilter below;
            # keep those two columns mutable without ever retaining a mutable GPU view as receipt
            # evidence.  Geometric values remain the packet's immutable host tuples.
            reason_codes = list(host_packet.reason_codes)
            admitted_rows = list(host_packet.admitted)
            racket_velocity_rows = host_packet.racket_velocity_rows
            racket_normal_rows = host_packet.racket_normal_rows
            residual_rows = host_packet.residual_rows
            reference_quat_rows = (
                self._action_ball_reference_quat_host_rows
            )
            reference_omega_rows = (
                self._action_ball_reference_omega_host_rows
            )
            if (
                len(reason_codes) != len(flat_samples)
                or len(admitted_rows) != len(flat_samples)
            ):
                raise RuntimeError("fixed-action solver returned a wrong-size proposal ledger")
            rejected_count = sum(
                int(count) for count in solver_reason_counts.values()
            )
            if (
                rejected_count
                + sum(bool(value) for value in admitted_rows)
                != len(flat_samples)
            ):
                raise RuntimeError(
                    "fixed-action solver admission/rejection counts do not conserve proposals"
                )
            timing_by_flat_index = {}
            geometry_by_flat_index = {}
            timing_rejections = {}
            for index, is_admitted in enumerate(admitted_rows):
                if not is_admitted:
                    continue
                state = states[flat_state_indices[index]]
                profile = self._action_ball_bundle.profiles[
                    state["slot"]
                ]
                face_velocity = tuple(
                    float(value) for value in racket_velocity_rows[index]
                )
                raw_normal = tuple(
                    float(value) for value in racket_normal_rows[index]
                )
                slot = int(state["slot"])
                reference_quat = tuple(
                    float(value) for value in reference_quat_rows[slot]
                )
                reference_omega = tuple(
                    float(value) for value in reference_omega_rows[slot]
                )
                birth_x_lower_bound_m = ball_birth_x_lower_bound_m(
                    float(flat_samples[index].contact_w_m[0]),
                    float(
                        flat_samples[index].incoming_velocity_w_mps[0]
                    ),
                    float(flat_samples[index].time_to_contact_s),
                )
                if birth_x_lower_bound_m < (
                    net_x + BALL_BIRTH_NET_MARGIN_M
                ):
                    # 球出生在半路:反推出生点连网平面都过不了,不是对面来球。
                    timing_reason = "ball_birth_not_beyond_net"
                else:
                    try:
                        geometry = contact_geometry.solve_exact_face_contact(
                            ball_contact_w_m=(
                                flat_samples[index].contact_w_m
                            ),
                            racket_face_center_velocity_w_mps=(
                                face_velocity
                            ),
                            solved_raw_a_normal_w=raw_normal,
                            mount_normal_sign=(
                                self._action_ball_mount_signs[slot]
                            ),
                            reference_racket_quat_wxyz=reference_quat,
                            reference_racket_angular_velocity_w_radps=(
                                reference_omega
                            ),
                            reference_racket_site_speed_mps=float(
                                profile.reference_racket_site_speed_mps
                            ),
                            teacher_rate_min=float(
                                profile.teacher_rate_min
                            ),
                            teacher_rate_max=float(
                                profile.teacher_rate_max
                            ),
                        )
                        geometry_by_flat_index[index] = geometry
                    except (
                        contact_geometry.ExactFaceContactGeometryError
                    ) as error:
                        if error.reason == "teacher_rate_out_of_bounds":
                            timing_reason = "teacher_rate_out_of_bounds"
                        else:
                            timing_reason = error.reason
                        if timing_reason not in known_reasons:
                            raise RuntimeError(
                                "exact-face geometry returned an unpinned "
                                f"rejection reason {timing_reason!r}"
                            ) from error
                        geometry = None
                    else:
                        timing_reason = None
                if timing_reason is None:
                    teacher_rate = geometry.teacher_rate
                    scaled_t_hit_s = (
                        float(profile.reference_t_hit_s)
                        / teacher_rate
                    )
                    scaled_t_cycle_s = (
                        float(profile.reference_t_cycle_s)
                        / teacher_rate
                    )
                    pre_swing_wait_s = (
                        float(flat_samples[index].time_to_contact_s)
                        - scaled_t_hit_s
                    )
                    if not (
                        float(profile.reaction_margin_s)
                        <= pre_swing_wait_s
                        <= 1.0
                    ):
                        timing_reason = (
                            "pre_swing_wait_out_of_bounds"
                        )
                    elif (
                        pre_swing_wait_s
                        + scaled_t_cycle_s
                        + self._action_ball_attempt_close_margin_s
                        > self._action_ball_episode_length_s + 1.0e-12
                    ):
                        timing_reason = (
                            "cycle_exceeds_episode_horizon"
                        )
                    else:
                        timing_reason = None
                if timing_reason is not None:
                    admitted_rows[index] = False
                    reason_codes[index] = reason_schema.index(
                        timing_reason
                    )
                    timing_rejections[timing_reason] = (
                        timing_rejections.get(timing_reason, 0) + 1
                    )
                    continue
                try:
                    timing_by_flat_index[index] = (
                        derive_action_teacher_site_timing(
                            racket_site_velocity_w_mps=(
                                geometry.racket_site_velocity_w_mps
                            ),
                            time_to_contact_s=float(
                                flat_samples[index].time_to_contact_s
                            ),
                            reference_t_hit_s=float(
                                profile.reference_t_hit_s
                            ),
                            reference_t_cycle_s=float(
                                profile.reference_t_cycle_s
                            ),
                            reference_racket_site_speed_mps=float(
                                profile.reference_racket_site_speed_mps
                            ),
                            reaction_margin_s=float(
                                profile.reaction_margin_s
                            ),
                            teacher_rate_min=float(
                                profile.teacher_rate_min
                            ),
                            teacher_rate_max=float(
                                profile.teacher_rate_max
                            ),
                        )
                    )
                except ActionBallContractError as error:
                    raise RuntimeError(
                        "producer timing prefilter disagrees with the "
                        "runtime's exact derive_action_teacher_site_timing"
                    ) from error
            split_rejections = [dict() for _ in states]
            aggregate_rejections = {}
            for index, (is_admitted, code) in enumerate(
                zip(admitted_rows, reason_codes)
            ):
                if is_admitted:
                    continue
                if type(code) is not int or not 0 <= code < len(reason_schema):
                    raise RuntimeError(
                        "fixed-action solver returned an invalid rejection reason code"
                    )
                name = reason_schema[code]
                state_counts = split_rejections[flat_state_indices[index]]
                state_counts[name] = state_counts.get(name, 0) + 1
                aggregate_rejections[name] = aggregate_rejections.get(name, 0) + 1
            expected_rejections = {
                str(name): int(count)
                for name, count in solver_reason_counts.items()
                if int(count) != 0
            }
            for name, count in timing_rejections.items():
                expected_rejections[name] = (
                    expected_rejections.get(name, 0) + count
                )
            if aggregate_rejections != expected_rejections:
                raise RuntimeError(
                    "fixed-action solver aggregate and per-row rejection ledgers disagree"
                )
            for state_index, counts in enumerate(split_rejections):
                request = states[state_index]["request"]
                reject_counts = self._action_ball_reject_counts[
                    int(request.action_uid)
                ]
                for name, count in counts.items():
                    reject_counts[name] = reject_counts.get(name, 0) + count

            admitted_indices_by_state = [[] for _ in states]
            for index, is_admitted in enumerate(admitted_rows):
                if is_admitted:
                    admitted_indices_by_state[flat_state_indices[index]].append(index)
            for state_index, indices in enumerate(admitted_indices_by_state):
                state = states[state_index]
                request = state["request"]
                slot = state["slot"]
                self._action_ball_note(slot, "A", len(indices))
                for index in indices:
                    sample = flat_samples[index]
                    timing = timing_by_flat_index.get(index)
                    geometry = geometry_by_flat_index.get(index)
                    if timing is None or geometry is None:
                        raise RuntimeError(
                            "admitted action-ball row has no exact face/site "
                            "geometry and teacher timing proof"
                        )
                    profile = self._action_ball_bundle.profiles[slot]
                    if not bool(
                        getattr(
                            self,
                            "_action_ball_diagnostic_unauthorized",
                            False,
                        )
                    ):
                        sample.verify_sample_id()
                    goal = (
                        float(sample.base_goal_w_m[0]),
                        float(sample.base_goal_w_m[1]),
                        float(request.birth.base_spawn_w_m[2]),
                    )
                    receipts = state["receipts"]
                    receipts.append(
                        task_receipt_from_birth(
                            request.birth,
                            sample_sha256=sample.sample_id,
                            sample_index=int(sample.sample_index),
                            sample_draw_start=int(sample.draw_start),
                            sample_draw_end=int(sample.draw_end),
                            swing_generation=(
                                int(request.swing_generation_start)
                                + len(receipts)
                            ),
                            base_goal_w_m=goal,
                            base_spawn_latent_w_m=(
                                sample.base_spawn_latent_w_m
                            ),
                            base_travel_latent_b_yaw_m=(
                                sample.base_travel_latent_b_yaw_m
                            ),
                            contact_offset_from_base_goal_b_yaw_m=(
                                sample.contact_offset_from_base_goal_b_yaw_m
                            ),
                            ball_contact_w_m=sample.contact_w_m,
                            racket_site_target_w_m=(
                                geometry.racket_site_target_w_m
                            ),
                            time_to_contact_s=float(
                                sample.time_to_contact_s
                            ),
                            incoming_speed_mps=float(
                                sample.incoming_speed_mps
                            ),
                            incoming_direction_b_yaw=(
                                sample.incoming_direction_b_yaw
                            ),
                            incoming_velocity_w_mps=sample.incoming_velocity_w_mps,
                            spin_magnitude_radps=float(
                                sample.spin_magnitude_radps
                            ),
                            spin_direction_b_yaw=(
                                sample.spin_direction_b_yaw
                            ),
                            incoming_spin_w_radps=sample.spin_w_radps,
                            landing_aim_w_xy_m=sample.landing_aim_w_xy_m,
                            mount_normal_sign=(
                                geometry.mount_normal_sign
                            ),
                            racket_normal_w=racket_normal_rows[index],
                            reference_racket_quat_wxyz=reference_quat_rows[
                                slot
                            ],
                            reference_racket_angular_velocity_w_radps=(
                                reference_omega_rows[slot]
                            ),
                            racket_command_quat_wxyz=(
                                geometry.racket_command_quat_wxyz
                            ),
                            racket_face_center_velocity_w_mps=(
                                geometry.racket_face_center_velocity_w_mps
                            ),
                            racket_site_velocity_w_mps=(
                                geometry.racket_site_velocity_w_mps
                            ),
                            racket_command_angular_velocity_w_radps=(
                                geometry.racket_command_angular_velocity_w_radps
                            ),
                            geometry_source_sha256=(
                                geometry.geometry_source_sha256
                            ),
                            reference_t_hit_s=float(
                                profile.reference_t_hit_s
                            ),
                            reference_t_cycle_s=float(
                                profile.reference_t_cycle_s
                            ),
                            reference_racket_site_speed_mps=float(
                                profile.reference_racket_site_speed_mps
                            ),
                            required_racket_site_speed_mps=(
                                timing.required_racket_site_speed_mps
                            ),
                            reaction_margin_s=float(
                                profile.reaction_margin_s
                            ),
                            teacher_rate_min=float(
                                profile.teacher_rate_min
                            ),
                            teacher_rate_max=float(
                                profile.teacher_rate_max
                            ),
                            teacher_rate=timing.teacher_rate,
                            scaled_t_hit_s=timing.scaled_t_hit_s,
                            scaled_t_cycle_s=timing.scaled_t_cycle_s,
                            pre_swing_wait_s=(
                                timing.pre_swing_wait_s
                            ),
                            solver_residual_m=float(residual_rows[index]),
                            contact_time_step_s=(
                                getattr(
                                    sample,
                                    "contact_time_step_s",
                                    None,
                                )
                            ),
                            time_to_contact_tick=(
                                getattr(
                                    sample,
                                    "time_to_contact_tick",
                                    None,
                                )
                            ),
                            birth_index=int(
                                getattr(sample, "birth_index", -1)
                            ),
                            birth_sampling_stratum=(
                                getattr(
                                    sample,
                                    "birth_sampling_stratum",
                                    "domain",
                                )
                            ),
                            birth_sampling_levels=(
                                None
                                if getattr(
                                    sample,
                                    "sampling_mixture",
                                    None,
                                )
                                is None
                                else type(request.birth.domain_levels)(
                                    **sample.birth_sampling_levels.as_dict()
                                )
                            ),
                            birth_frontier_arm=(
                                getattr(
                                    sample,
                                    "birth_frontier_arm",
                                    None,
                                )
                            ),
                            sampling_mixture=(
                                None
                                if getattr(
                                    sample,
                                    "sampling_mixture",
                                    None,
                                )
                                is None
                                else type(
                                    request.birth.sampling_mixture
                                ).from_dict(
                                    sample.sampling_mixture.as_dict()
                                )
                            ),
                            sampling_stratum=getattr(
                                sample,
                                "sampling_stratum",
                                "domain",
                            ),
                            sampling_levels=(
                                None
                                if getattr(
                                    sample,
                                    "sampling_mixture",
                                    None,
                                )
                                is None
                                else type(request.birth.domain_levels)(
                                    **sample.sampling_levels.as_dict()
                                )
                            ),
                            frontier_arm=getattr(
                                sample,
                                "frontier_arm",
                                None,
                            ),
                            counter_rally_task=(
                                None
                                if not counter_rally_enabled
                                else counter_rally_task_identity_type(
                                    objective_profile_sha256=(
                                        counter_rally_tasks[
                                            index
                                        ].objective_profile_sha256
                                    ),
                                    return_direction_env_xy=(
                                        counter_rally_tasks[
                                            index
                                        ].return_direction_env_xy
                                    ),
                                    target_baseline_speed_mps=(
                                        counter_rally_tasks[
                                            index
                                        ].target_baseline_speed_mps
                                    ),
                                )
                            ),
                        )
                    )

        batches = tuple(
            ActionPoolRefillBatch(
                action_uid=int(state["request"].action_uid),
                proposed_count=int(state["proposed"]),
                proposal_sample_indices=tuple(
                    state["proposal_sample_indices"]
                ),
                receipts=tuple(state["receipts"]),
            )
            for state in states
        )
        admitted_receipts = tuple(
            receipt
            for batch in batches
            for receipt in batch.receipts
        )
        from whole_body_tracking.tasks.tracking.mdp.action_ball_runtime import (
            extend_task_transcript_sha256,
        )

        staged_uid_counts = {}
        if diagnostic_unauthorized:
            # Diagnostic checkpoints intentionally contain no exact ActionBall
            # resume transcript.  The active provider row, pool birth cursor,
            # and aggregate P/A/issued ledgers already retain the identities
            # consumed by training, so do not construct a second per-birth
            # human-readable history/hash chain on every short episode.
            for receipt in admitted_receipts:
                provider = self._action_ball_provider_births.get(
                    receipt.birth_sha256
                )
                birth = (
                    None
                    if provider is None
                    else provider["runtime_birth"]
                )
                if (
                    birth is None
                    or birth.canonical_sha256
                    != receipt.birth_sha256
                    or birth.action_uid != receipt.action_uid
                ):
                    raise RuntimeError(
                        "action-ball admitted task lost its active provider "
                        "birth"
                    )
                uid = int(receipt.action_uid)
                staged_uid_counts[uid] = (
                    staged_uid_counts.get(uid, 0) + 1
                )
        else:
            staged_transcripts = {}
            for receipt in admitted_receipts:
                birth_sha = receipt.birth_sha256
                birth = self._action_ball_provider_history.get(
                    birth_sha
                )
                if birth is None or birth.action_uid != receipt.action_uid:
                    raise RuntimeError(
                        "action-ball admitted task lost its provider birth "
                        "history"
                    )
                count, root = staged_transcripts.get(
                    birth_sha,
                    self._action_ball_task_transcript_by_birth[
                        birth_sha
                    ],
                )
                if receipt.swing_generation != count:
                    raise RuntimeError(
                        "action-ball admitted task swing generation is not "
                        "the next transcript row"
                    )
                staged_transcripts[birth_sha] = (
                    count + 1,
                    extend_task_transcript_sha256(
                        root, receipt.canonical_sha256
                    ),
                )
                uid = int(receipt.action_uid)
                staged_uid_counts[uid] = (
                    staged_uid_counts.get(uid, 0) + 1
                )
        # The pool snapshots the entire shared solver state before entering this
        # callback.  Register the whole admitted batch before return; any later
        # structural or authority failure restores this transcript atomically.
        if not diagnostic_unauthorized:
            self._action_ball_task_transcript_by_birth.update(
                staged_transcripts
            )
        for uid, amount in staged_uid_counts.items():
            self._action_ball_emitted_task_count_by_uid[
                uid
            ] += amount
        if live_question_cache is not None:
            if staged_question_cache is None:
                raise RuntimeError("staged exact-question cache disappeared")
            # Last operation in the producer transaction: exceptions above
            # leave the live cache byte-identical; pool-level rollback still
            # restores this same checkpoint state if a later protocol gate
            # rejects the returned batch.
            live_question_cache.load_state_dict(
                staged_question_cache.state_dict()
            )
        return batches

    def _action_ball_reset_outcome_masks(
        self,
        ids: torch.Tensor,
        *,
        _defer_unattributed_validation: bool = False,
    ) -> tuple[torch.Tensor, ...]:
        """Return independent raw unsafe masks plus reset/timeout truth.

        A single physics tick may trip several instruments (for example a
        hard joint limit while the arm also strikes the table).  The evidence
        ledger must preserve both raw facts; precedence is applied only by a
        downstream outcome classifier and must never erase a sensor.  The
        Reference-consistency resets are safe policy failures.  There is no
        generic collision sensor in this task, so an otherwise unexplained
        termination is an attribution-contract error rather than permission to
        fabricate ``U_collision`` evidence.
        """

        manager = getattr(self._env, "termination_manager", None)
        if manager is None:
            raise RuntimeError("action-ball true reset has no termination manager")
        active_terms = set(str(name) for name in getattr(manager, "active_terms", ()))
        required = {
            "robot_hit_table",
            "joint_qdes_forbidden",
            "joint_actual_forbidden",
            *_PHYSICAL_FALL_TERMINATION_TERMS,
            *_REFERENCE_TERMINATION_TERMS,
        }
        missing = sorted(required - active_terms)
        if missing:
            raise RuntimeError(
                "action-ball outcome attribution requires table/fall/joint-hard "
                "termination terms; "
                f"missing={missing}"
            )
        get_term = getattr(manager, "get_term", None)
        if not callable(get_term):
            raise RuntimeError(
                "action-ball termination manager cannot expose per-term outcomes"
            )
        terminated = self._selected_bool(
            getattr(
                manager,
                "terminated",
                torch.zeros((), dtype=torch.bool, device=self.device),
            ),
            ids,
        )
        timed_out = self._selected_bool(
            getattr(
                manager,
                "time_outs",
                torch.zeros((), dtype=torch.bool, device=self.device),
            ),
            ids,
        )
        joint_actual = (
            self._selected_bool(get_term("joint_actual_forbidden"), ids)
            & terminated
        )
        joint_qdes = (
            self._selected_bool(get_term("joint_qdes_forbidden"), ids)
            & terminated
        )
        fall = torch.zeros(len(ids), dtype=torch.bool, device=self.device)
        for name in _PHYSICAL_FALL_TERMINATION_TERMS:
            fall |= self._selected_bool(get_term(name), ids)
        fall &= terminated
        table = (
            self._selected_bool(get_term("robot_hit_table"), ids)
            & terminated
        )
        named_unsafe = joint_actual | joint_qdes | fall | table
        reference_failure = torch.zeros(
            len(ids), dtype=torch.bool, device=self.device
        )
        for name in _REFERENCE_TERMINATION_TERMS:
            reference_failure |= self._selected_bool(get_term(name), ids)
        reference_failure &= terminated
        unattributed = (
            terminated
            & ~timed_out
            & ~named_unsafe
            & ~reference_failure
        )
        if not _defer_unattributed_validation:
            if bool(unattributed.any()):
                raise RuntimeError(
                    "action-ball termination attribution encountered an "
                    "unregistered non-timeout term; extend the named physical "
                    "safety or reference-failure contract before training"
                )
        # Reserved for a future explicit collision sensor.  A residual union
        # is not evidence and therefore cannot populate this ledger channel.
        collision = torch.zeros(
            len(ids), dtype=torch.bool, device=self.device
        )
        result = (
            table,
            fall,
            collision,
            joint_qdes,
            joint_actual,
            terminated | timed_out,
        )
        if _defer_unattributed_validation:
            return (*result, unattributed)
        return result

    def _action_ball_strike_fact_pack_task_refs(
        self, refs: tuple
    ) -> object | None:
        """Pack exact receipt refs before the live task-install transaction.

        This is a reset/wrap host boundary, not a policy-step hot path.  The
        source objects must be the exact runtime ``ActionTaskReceiptRef`` type;
        a fixed-view identity, UID tuple, or shortened digest is never accepted
        as a substitute.
        """

        if not self._action_ball_strike_fact_device_enabled:
            return None
        if self._action_ball_fixed_view_enabled:
            raise RuntimeError(
                "same-transition strike facts require full "
                "ActionTaskReceiptRef rows; immutable fixed-view tasks have "
                "no receipt refs"
            )
        from whole_body_tracking.tasks.tracking.mdp.action_ball_runtime import (
            ActionTaskReceiptRef,
        )
        from .action_ball_strike_fact import PackedActionTaskReceiptRef
        from .action_ball_strike_fact_device import DeviceActionTaskKey

        if not refs or any(type(ref) is not ActionTaskReceiptRef for ref in refs):
            raise RuntimeError(
                "same-transition strike fact install requires exact full "
                "ActionTaskReceiptRef rows"
            )
        packed = PackedActionTaskReceiptRef.from_receipt_refs(
            refs, device=self.device
        )
        return DeviceActionTaskKey.from_mapping(packed.to_mapping())

    def _action_ball_strike_fact_commit_task_key(
        self, ids: torch.Tensor, packed_key: object | None
    ) -> None:
        """Commit one validated selected-row key into the all-env device key."""

        if not self._action_ball_strike_fact_device_enabled:
            if packed_key is not None:
                raise RuntimeError(
                    "disabled strike-fact owner received a packed task key"
                )
            return
        from .action_ball_strike_fact_device import DeviceActionTaskKey

        if not isinstance(packed_key, DeviceActionTaskKey):
            raise RuntimeError(
                "strike-fact task install lost its full device task key"
            )
        rows = ids.shape[0]
        if any(
            getattr(packed_key, name).shape != (rows,)
            for name in (
                "env_id",
                "reset_generation",
                "swing_generation",
                "action_uid",
                "action_slot",
            )
        ) or any(
            getattr(packed_key, name).shape != (rows, 32)
            for name in (
                "birth_sha256",
                "sample_sha256",
                "task_sha256",
            )
        ):
            raise RuntimeError(
                "selected strike-fact task key has an invalid fixed shape"
            )
        for name, destination in self._action_ball_strike_fact_key_ints.items():
            destination.index_copy_(0, ids, getattr(packed_key, name))
        for name, destination in (
            self._action_ball_strike_fact_key_digests.items()
        ):
            destination.index_copy_(0, ids, getattr(packed_key, name))

    def _action_ball_strike_fact_close_before_task_mutation(
        self, ids: torch.Tensor, *, mutation: str
    ) -> None:
        """Fail-close device rows before reset/wrap/task identity mutation."""

        if not self._action_ball_strike_fact_device_enabled:
            return
        if type(mutation) is not str or not mutation:
            raise TypeError("strike-fact task mutation must be named")
        outstanding_step = self._action_ball_strike_fact_expected_publish_step
        reset_mask = self._action_ball_strike_fact_mutation_mask
        reset_mask.zero_()
        reset_mask.index_fill_(0, ids, True)
        # Reset first while the old key is still intact.  ARMED/PENDING rows
        # become sticky device faults; fully paid rows close cleanly.
        self._action_ball_strike_fact_device_coordinator.reset(reset_mask)
        self._action_ball_strike_fact_exact_eligibility.masked_fill_(
            reset_mask, False
        )
        self._action_ball_strike_fact_source_step.masked_fill_(reset_mask, -1)
        for name, tensor in self._action_ball_strike_fact_key_ints.items():
            if name != "env_id":
                tensor.masked_fill_(reset_mask, -1 if name in (
                    "swing_generation", "action_slot"
                ) else 0)
        for tensor in self._action_ball_strike_fact_key_digests.values():
            tensor.masked_fill_(reset_mask.unsqueeze(-1), 0)
        self._action_ball_strike_fact_expected_publish_step = None
        if outstanding_step is not None:
            raise RuntimeError(
                f"{mutation} attempted before strike-fact DoneTerm sealed "
                f"source_step={outstanding_step}"
            )

    def _capture_action_ball_single_exact_eligibility(
        self, exact_strike: torch.Tensor
    ) -> None:
        """Latch the existing one-shot exact mask for the next transition."""

        if self._action_ball_strike_fact_device_enabled:
            self._action_ball_strike_fact_exact_eligibility.copy_(
                exact_strike
            )

    def _arm_action_ball_strike_fact_for_next_transition(self) -> None:
        """Arm the current immutable task for the next physics transition.

        ManagerBasedRLEnv calls CommandManager only after the current Reward
        and reset seams.  Therefore ``common_step_counter + 1`` is the unique
        next post-physics DoneTerm source step.  This method runs after both
        the normal and disabled-resampling CommandTerm compute paths.
        """

        if not self._action_ball_strike_fact_device_enabled:
            return
        if getattr(self, "_action_ball_full_mdp_enabled", False) is True:
            from .action_ball_strike_fact_device import EpochR03RacketIdentity

            source_step = getattr(self._env, "common_step_counter", None)
            if type(source_step) is not int or source_step < 0:
                raise RuntimeError(
                    "fresh R03 arm requires a non-negative integer common step"
                )
            next_source_step = source_step + 1
            source = self._action_ball_strike_fact_source_step
            source.fill_(next_source_step)
            if self._action_ball_full_mdp_r03_writer_active:
                raise RuntimeError("fresh R03 Racket writer is reentrant")
            self._action_ball_full_mdp_r03_writer_active = True
            try:
                self._action_ball_strike_fact_device_coordinator.arm_action_epoch_strike_fact_v1(
                    source_step=source,
                    racket_identity=EpochR03RacketIdentity(
                        reset_generation=self._action_ball_reset_generation,
                        action_uid=self._action_ball_action_uid,
                        action_slot=self._action_ball_action_slot,
                        task_identity=(
                            self._action_ball_full_mdp_racket_task_identity
                        ),
                    ),
                    racket_owner=self,
                )
            finally:
                self._action_ball_full_mdp_r03_writer_active = False
            self._action_ball_strike_fact_expected_publish_step = next_source_step
            return
        if self._action_ball_fixed_view_enabled:
            raise RuntimeError(
                "cannot arm same-transition strike facts from a receipt-free "
                "immutable fixed view"
            )
        if self._action_ball_strike_fact_expected_publish_step is not None:
            raise RuntimeError(
                "previous strike-fact transition did not reach its DoneTerm publisher"
            )
        common_step = getattr(self._env, "common_step_counter", None)
        if type(common_step) is not int or common_step < 0:
            raise RuntimeError(
                "strike-fact arm requires a non-negative integer common step"
            )
        source_step = common_step + 1
        self._action_ball_strike_fact_source_step.fill_(source_step)
        self._action_ball_strike_fact_device_coordinator.arm(
            self._action_ball_strike_fact_exact_eligibility,
            source_step=self._action_ball_strike_fact_source_step,
            task_key=self._action_ball_strike_fact_task_key,
            target_position=self.racket_target_pos_w,
            target_velocity=self.racket_target_vel_w,
            target_face_normal=self.target_normal_cmd,
            ball_position=self._action_ball_ball_contact_target_w,
            ball_velocity=self.vb_vel_in_w,
            validity=self._action_ball_strike_fact_target_validity,
        )
        self._action_ball_strike_fact_expected_publish_step = source_step

    def _arm_action_ball_strike_fact_after_initial_reset(self) -> None:
        """Cover the one pre-physics transition with no preceding Reward seam.

        IsaacLab's public ``reset()`` performs CommandManager.reset and then
        observations; it does not call CommandManager.compute.  The initial
        full reset therefore arms source step one after its complete task
        install.  Every later transition remains owned by the normal
        post-Reward compute tail above.
        """

        if not self._action_ball_strike_fact_device_enabled:
            return
        if getattr(self, "_action_ball_full_mdp_enabled", False) is True:
            # Full-MDP genesis has not revealed an ActionEpoch task during
            # CommandTerm's initial reset.  The lean top owner performs the
            # unique arm only after D05 settlement returns; arming here would
            # bind tombstones or reenter a non-existent epoch.
            return
        common_step = getattr(self._env, "common_step_counter", None)
        if (
            common_step == 0
            and self._action_ball_strike_fact_expected_publish_step is None
        ):
            self._arm_action_ball_strike_fact_for_next_transition()

    def arm_action_ball_full_mdp_epoch_strike_fact(self) -> None:
        """Arm the bound R03 after D05 reveal and before the next physics.

        This helper accepts no mask, identity, step, or verdict from the top
        owner.  The Racket leaf owns its live task integers and the manager's
        next-transition clock; R03 freezes targets only from its independently
        bound current ActionEpoch after the D05 coordinator operation returns.
        """

        if getattr(self, "_action_ball_full_mdp_enabled", False) is not True:
            raise ActionBallContinuousRacketStrikeFactHold(
                "epoch R03 arm is full-MDP-only"
            )
        self._arm_action_ball_strike_fact_for_next_transition()

    def require_active_action_epoch_r03_writer(self) -> None:
        """Require the exact scalar Racket call stack around an R03 mutation."""

        if (
            getattr(self, "_action_ball_full_mdp_r03_writer_active", False)
            is not True
        ):
            raise ActionBallContinuousRacketStrikeFactHold(
                "R03 mutation is outside the active Racket writer callback"
            )

    def action_ball_full_mdp_r03_owner(self) -> object:
        """Return the one R03 child constructed by this exact Racket owner.

        The full-MDP factory may retrieve this object; it must not construct a
        parallel coordinator or accept one supplied by a launcher.  This
        getter grants no publication authority and cannot bypass the missing
        Device-R05 current full-key/shot projection.
        """

        if getattr(self, "_action_ball_full_mdp_enabled", False) is not True:
            raise ActionBallContinuousRacketStrikeFactHold(
                "fresh R03 owner is available only in action_ball_full_mdp"
            )
        from .action_ball_strike_fact_device import (
            ActionBallStrikeFactDeviceCoordinator,
            OBSERVATION_PROJECTION_MODE_FRESH_FULL_MDP,
        )

        owner = getattr(
            self, "_action_ball_strike_fact_device_coordinator", None
        )
        if (
            type(owner) is not ActionBallStrikeFactDeviceCoordinator
            or getattr(owner, "_observation_projection_mode", None)
            != OBSERVATION_PROJECTION_MODE_FRESH_FULL_MDP
        ):
            raise ActionBallContinuousRacketStrikeFactHold(
                "Racket lost its exact fresh R03 child"
            )
        return owner

    def publish_action_ball_full_mdp_epoch_strike_fact(
        self, *, source_step: int
    ) -> None:
        """Top-owner final-substep seam for the once-per-control R03 write."""

        if getattr(self, "_action_ball_full_mdp_enabled", False) is not True:
            raise ActionBallContinuousRacketStrikeFactHold(
                "epoch R03 post-physics publication is full-MDP-only"
            )
        self.publish_action_ball_strike_fact_for_reward(
            source_step=source_step
        )

    def publish_action_ball_strike_fact_for_reward(
        self, *, source_step: int
    ) -> None:
        """Publish exact post-physics FK to R03 and its bound ActionEpoch."""

        if not self._action_ball_strike_fact_device_enabled:
            raise RuntimeError(
                "strike-fact DoneTerm is installed while its Racket owner is disabled"
            )
        if (
            type(source_step) is not int
            or source_step
            != self._action_ball_strike_fact_expected_publish_step
        ):
            raise RuntimeError(
                "strike-fact DoneTerm source step differs from the armed transition"
            )
        if getattr(self, "_action_ball_full_mdp_enabled", False) is True:
            from .action_ball_strike_fact_device import EpochR03RacketIdentity

            coordinator = self.action_ball_full_mdp_r03_owner()
            epoch_owner = getattr(
                self, "_action_ball_full_mdp_racket_epoch_owner", None
            )
            if coordinator.action_epoch_owner is not epoch_owner:
                raise ActionBallContinuousRacketStrikeFactHold(
                    "fresh R03 and Racket lost their common ActionEpoch owner"
                )
            (
                achieved_position,
                _achieved_quaternion,
                achieved_velocity,
                achieved_raw_face_normal,
                _achieved_signed_face_normal,
            ) = self._racket_fk()
            origins = getattr(
                getattr(self._env, "scene", None), "env_origins", None
            )
            if (
                type(origins) is not torch.Tensor
                or origins.device != torch.device(self.device)
                or origins.dtype != achieved_position.dtype
                or tuple(origins.shape) != (self.num_envs, 3)
                or not origins.is_contiguous()
            ):
                raise ActionBallContinuousRacketStrikeFactHold(
                    "fresh R03 publication requires exact live environment origins"
                )
            achieved_position_scene = achieved_position - origins
            source = self._action_ball_strike_fact_source_step
            if self._action_ball_full_mdp_r03_writer_active:
                raise RuntimeError("fresh R03 Racket writer is reentrant")
            self._action_ball_full_mdp_r03_writer_active = True
            try:
                coordinator.publish_action_epoch_strike_fact_v1(
                    racket_owner=self,
                    source_step=source,
                    racket_identity=EpochR03RacketIdentity(
                        reset_generation=self._action_ball_reset_generation,
                        action_uid=self._action_ball_action_uid,
                        action_slot=self._action_ball_action_slot,
                        task_identity=(
                            self._action_ball_full_mdp_racket_task_identity
                        ),
                    ),
                    achieved_position=achieved_position_scene,
                    achieved_velocity=achieved_velocity,
                    achieved_face_normal=achieved_raw_face_normal,
                )
            finally:
                self._action_ball_full_mdp_r03_writer_active = False
            self._action_ball_strike_fact_expected_publish_step = None
            return
        (
            achieved_position,
            _achieved_quaternion,
            achieved_velocity,
            achieved_raw_face_normal,
            _achieved_signed_face_normal,
        ) = self._racket_fk()
        self._action_ball_strike_fact_device_coordinator.publish(
            self._action_ball_strike_fact_exact_eligibility,
            source_step=self._action_ball_strike_fact_source_step,
            task_key=self._action_ball_strike_fact_task_key,
            achieved_position=achieved_position,
            achieved_velocity=achieved_velocity,
            achieved_face_normal=achieved_raw_face_normal,
        )
        self._action_ball_strike_fact_expected_publish_step = None

    def _action_ball_close_attempts(
        self,
        ids: torch.Tensor,
        *,
        true_reset: bool,
        active_host_env_ids=None,
    ) -> None:
        """Close prior installed attempts before any replacement task is requested."""

        self._action_ball_strike_fact_close_before_task_mutation(
            ids,
            mutation=(
                "ActionBall true reset" if true_reset else "ActionBall wrap"
            ),
        )

        installed_active = self._action_ball_attempt_active[ids]
        resume_exclusion_state = getattr(
            self, "_action_ball_resume_reset_exclusion", None
        )
        if resume_exclusion_state is None:
            resume_exclusion_state = torch.zeros(
                self.num_envs, dtype=torch.bool, device=self.device
            )
            self._action_ball_resume_reset_exclusion = (
                resume_exclusion_state
            )
        if (
            resume_exclusion_state.dtype != torch.bool
            or tuple(resume_exclusion_state.shape) != (self.num_envs,)
        ):
            raise RuntimeError(
                "ActionBall resume reset-exclusion latch is invalid"
            )
        resume_exclusion = resume_exclusion_state[ids] & installed_active
        active = installed_active & ~resume_exclusion
        if self._action_ball_task_wait_schedule is not None:
            # A reset during RESET_WAIT is a safety/reset fact, not a closed
            # task opportunity.  Only revealed tasks enter C/L/F denominators.
            active = active & self._action_ball_task_valid[ids]
        slots = self._action_ball_attempt_action[ids]
        n_actions = len(self._action_ball_bindings)
        slot_authority = (
            installed_active
            if self._action_ball_fixed_view_enabled
            else (active | resume_exclusion)
        )
        invalid = slot_authority & (
            (slots < 0) | (slots >= n_actions)
        )
        inactive_dirty = ~installed_active & (
            (slots != -1)
            | self._action_ball_attempt_legal[ids]
            | self._action_ball_attempt_hit[ids]
        )
        diagnostic_fast_path = self._action_ball_diagnostic_unauthorized
        if diagnostic_fast_path:
            # Keep this first packet ahead of termination-manager reads so a
            # corrupt latch retains the original first-error boundary.
            latch_checks = _action_ball_host_bool_packet(
                (
                    ~invalid.any(),
                    ~inactive_dirty.any(),
                )
            )
            if not latch_checks[0] or not latch_checks[1]:
                raise RuntimeError(
                    "action-ball attempt latches are internally inconsistent"
                )
        elif bool(invalid.any()) or bool(inactive_dirty.any()):
            raise RuntimeError(
                "action-ball attempt latches are internally inconsistent"
            )
        if true_reset:
            if diagnostic_fast_path:
                (
                    table,
                    fall,
                    collision,
                    joint_qdes,
                    joint_actual,
                    terminal_or_timeout,
                    unattributed,
                ) = self._action_ball_reset_outcome_masks(
                    ids,
                    _defer_unattributed_validation=True,
                )
            else:
                (
                    table,
                    fall,
                    collision,
                    joint_qdes,
                    joint_actual,
                    terminal_or_timeout,
                ) = self._action_ball_reset_outcome_masks(ids)
        else:
            table = torch.zeros(len(ids), dtype=torch.bool, device=self.device)
            fall = torch.zeros_like(table)
            collision = torch.zeros_like(table)
            joint_qdes = torch.zeros_like(table)
            joint_actual = torch.zeros_like(table)
            terminal_or_timeout = torch.zeros_like(table)
            if diagnostic_fast_path:
                unattributed = torch.zeros_like(table)
        table &= active
        fall &= active
        collision &= active
        joint_qdes &= active
        joint_actual &= active
        if diagnostic_fast_path:
            # A resumed row has no checkpointed PhysX state and is deliberately
            # retired as X on the mandatory first fresh reset.  Termination
            # manager residues observed while performing that reset therefore
            # cannot be attributed to the old policy attempt.  Keep the normal
            # diagnostic fail-close check for every genuinely gradeable row.
            unattributed &= active
        unsafe_union = (
            table | fall | collision | joint_qdes | joint_actual
        )
        safe = active & ~unsafe_union
        hit = active & self._action_ball_attempt_hit[ids]
        legal = safe & self._action_ball_attempt_legal[ids]
        failed = safe & ~self._action_ball_attempt_legal[ids]
        # A timeout is a completed safe policy outcome: legal-at-strike remains L, otherwise F.
        # ``terminal_or_timeout`` is retained in the invariant check so a future unsafe term cannot
        # accidentally fall through to safe without extending the classification above.
        unclassified_terminated = active & terminal_or_timeout & ~(
            table
            | fall
            | collision
            | joint_qdes
            | joint_actual
            | legal
            | failed
        )
        if not diagnostic_fast_path and bool(unclassified_terminated.any()):
            raise RuntimeError("action-ball reset outcome classification is incomplete")

        clamped = slots.clamp(min=0)
        additions = {
            "C": torch.bincount(clamped[active], minlength=n_actions),
            "H": torch.bincount(clamped[hit], minlength=n_actions),
            "L": torch.bincount(clamped[legal], minlength=n_actions),
            "F": torch.bincount(clamped[failed], minlength=n_actions),
            "U_table": torch.bincount(clamped[table], minlength=n_actions),
            "U_fall": torch.bincount(clamped[fall], minlength=n_actions),
            "U_collision": torch.bincount(
                clamped[collision], minlength=n_actions
            ),
            "U_joint_qdes": torch.bincount(
                clamped[joint_qdes], minlength=n_actions
            ),
            "U_joint_actual": torch.bincount(
                clamped[joint_actual], minlength=n_actions
            ),
        }
        if self._action_ball_fixed_view_enabled:
            # A fixed row installed but reset before private RESET_WAIT reveal
            # is not a policy opportunity (so it must not enter C/L/F), yet it
            # still consumes one logical S row.  Record that withdrawal as X
            # so every fixed install remains exactly C-or-X conserved.
            hidden_withdrawal = installed_active & ~active
            additions["X"] = torch.bincount(
                clamped[hidden_withdrawal], minlength=n_actions
            )
        resume_x = torch.bincount(
            clamped[resume_exclusion], minlength=n_actions
        )
        additions["X"] = additions.get(
            "X", torch.zeros_like(resume_x)
        ) + resume_x
        unsafe_unique = torch.bincount(
            clamped[active & unsafe_union], minlength=n_actions
        )
        unsafe_rows = torch.stack(
            (
                additions["U_table"],
                additions["U_fall"],
                additions["U_collision"],
                additions["U_joint_qdes"],
                additions["U_joint_actual"],
            ),
            dim=0,
        )
        unsafe_sum = unsafe_rows.sum(dim=0)
        unsafe_max = unsafe_rows.max(dim=0).values
        if diagnostic_fast_path:
            # Attribution, classification, and conservation are now one
            # ordered read; host-side checks below retain their old priority.
            outcome_checks = _action_ball_host_bool_packet(
                (
                    ~unattributed.any(),
                    ~unclassified_terminated.any(),
                    torch.all(
                        additions["C"]
                        == additions["L"] + additions["F"] + unsafe_unique
                    ),
                    torch.all(additions["H"] <= additions["C"]),
                    torch.all(unsafe_max <= unsafe_unique),
                    torch.all(unsafe_unique <= unsafe_sum),
                )
            )
            if not outcome_checks[0]:
                raise RuntimeError(
                    "action-ball termination attribution encountered an "
                    "unregistered non-timeout term; extend the named physical "
                    "safety or reference-failure contract before training"
                )
            if not outcome_checks[1]:
                raise RuntimeError(
                    "action-ball reset outcome classification is incomplete"
                )
            if not all(outcome_checks[2:]):
                raise RuntimeError(
                    "action-ball closed outcome union/raw ledgers do not conserve"
                )
        elif (
            not torch.equal(
                additions["C"],
                additions["L"] + additions["F"] + unsafe_unique,
            )
            or bool((additions["H"] > additions["C"]).any())
            or bool((unsafe_max > unsafe_unique).any())
            or bool((unsafe_unique > unsafe_sum).any())
        ):
            raise RuntimeError(
                "action-ball closed outcome union/raw ledgers do not conserve"
            )
        for name, values in additions.items():
            row = _ACTION_BALL_LEDGER_NAMES.index(name)
            self._action_ball_live_ledger()[row].add_(values)
        if active_host_env_ids is None:
            active_host_env_ids = tuple(
                int(env)
                for env in ids[installed_active].detach().cpu().tolist()
            )
        for env_id in active_host_env_ids:
            self._action_ball_task_by_env[env_id] = None
            self._action_ball_task_ref_by_env[env_id] = None
            self._counter_rally_task_identity_by_env[env_id] = None
        self._action_ball_attempt_active[ids] = False
        self._action_ball_attempt_action[ids] = -1
        self._action_ball_attempt_legal[ids] = False
        self._action_ball_attempt_hit[ids] = False
        self._action_ball_resume_reset_exclusion[ids] = False
        self._counter_rally_reward_terms[ids] = 0.0
        self._counter_rally_accepted[ids] = False
        self._counter_rally_legal_first_landing[ids] = False
        self._counter_rally_primary_reason_code[ids] = -1
        self._action_ball_invalidate_virtual_contact_history(ids)

    def _action_ball_retire_previous_births(
        self, ids: torch.Tensor, *, host_env_ids=None
    ) -> None:
        """Retire old per-env FIFO queues only at a true episode reset."""

        # Normal reset batches already materialize and validate these ids as
        # part of their one identity D2H.  The fallback remains for the global
        # drain, which intentionally calls this seam outside that hot path.
        if host_env_ids is None:
            host_env_ids = tuple(
                int(env) for env in ids.detach().cpu().tolist()
            )
        elif len(host_env_ids) != len(ids):
            raise RuntimeError(
                "action-ball retirement host id batch length mismatch"
            )
        rows = []
        for env_id in host_env_ids:
            birth = self._action_ball_birth_by_env[env_id]
            if birth is None:
                continue
            provider = self._action_ball_provider_births.get(
                birth.canonical_sha256
            )
            if provider is None or provider["runtime_birth"] != birth:
                raise RuntimeError(
                    "retired action-ball birth was absent from provider state"
                )
            if birth.env_id != env_id:
                raise RuntimeError(
                    "retired action-ball birth belongs to another environment"
                )
            rows.append((env_id, birth, provider["sampler_birth"]))
        births = tuple(birth for _env_id, birth, _sampler_birth in rows)
        if not births:
            return
        fixed_view = self._action_ball_fixed_view_enabled
        if fixed_view:
            from whole_body_tracking.tasks.tracking.mdp.action_ball_runtime import (
                task_transcript_sha256,
            )

            for _env_id, birth, _sampler_birth in rows:
                birth_sha = birth.canonical_sha256
                if (
                    self._action_ball_provider_history.get(birth_sha)
                    != birth
                    or self._action_ball_task_transcript_by_birth.get(
                        birth_sha
                    )
                    != (0, task_transcript_sha256(birth_sha, ()))
                ):
                    raise RuntimeError(
                        "immutable fixed-view birth history/transcript drifted"
                    )
            # Fixed rows were never registered with LazyActionTaskPool.  The
            # validate-all boundary above is therefore the complete logical
            # retirement receipt; legitimate sampler/provider history remains
            # append-only for exact replay.
            discarded = (0,) * len(rows)
        else:
            # The pool performs one validate-all/commit-all retirement.
            # Provider maps and env latches mutate only after this atomic call.
            discarded = self._action_ball_pool.retire_many(births)
        if (
            not isinstance(discarded, tuple)
            or len(discarded) != len(rows)
            or any(type(value) is not int or value < 0 for value in discarded)
        ):
            raise AssertionError(
                "action-ball pool returned an invalid batch discard receipt"
            )
        if self._action_ball_diagnostic_unauthorized and not fixed_view:
            self._action_ball_sampler.forget_diagnostic_births(
                tuple(
                    sampler_birth
                    for _env_id, _birth, sampler_birth in rows
                )
            )
        question_cache = self._action_ball_exact_question_cache
        if question_cache is not None:
            # The pool has now atomically retired every queue that could replay
            # these births.  Release their exact-answer ownership while
            # retaining the latest static question per action as the intended
            # cross-reset hot row.
            question_cache.retire_births(
                tuple(birth.canonical_sha256 for birth in births)
            )
        for env_id, birth, _sampler_birth in rows:
            del self._action_ball_provider_births[birth.canonical_sha256]
            if (
                self._action_ball_diagnostic_unauthorized
                and not fixed_view
            ):
                # Batched diagnostic births never enter either formal proof
                # catalog.  Retain compatibility with a scalar diagnostic
                # adapter without paying two empty-map hash probes per reset.
                if self._action_ball_provider_history:
                    self._action_ball_provider_history.pop(
                        birth.canonical_sha256, None
                    )
                if self._action_ball_task_transcript_by_birth:
                    self._action_ball_task_transcript_by_birth.pop(
                        birth.canonical_sha256, None
                    )
            self._action_ball_birth_by_env[env_id] = None
            self._action_ball_task_by_env[env_id] = None
            self._action_ball_task_ref_by_env[env_id] = None
            self._counter_rally_task_identity_by_env[env_id] = None

    def _action_ball_commit_install(
        self,
        *,
        ids: torch.Tensor,
        origins: torch.Tensor,
        births: tuple,
        receipts: tuple,
        action_uids: torch.Tensor,
        action_slots: torch.Tensor,
        reset_generations: torch.Tensor,
        swing_generations: torch.Tensor,
        host_env_ids: tuple,
    ) -> tuple | None:
        """Single mutation seam for one fully validated task+ball env batch."""

        self._action_ball_reject_legacy_fresh_lane("direct task install")

        if len(host_env_ids) != len(ids):
            raise RuntimeError(
                "action-ball install host id batch length mismatch"
            )
        counter_rally_identities = None
        if self._counter_rally_enabled:
            expected_objective_sha256 = (
                self._counter_rally_objective.sha256
            )
            counter_rally_identities = tuple(
                receipt.require_counter_rally_task(
                    expected_objective_profile_sha256=(
                        expected_objective_sha256
                    )
                )
                for receipt in receipts
            )
        diagnostic_task_refs = (
            tuple(receipt.task_ref() for receipt in receipts)
            if self._action_ball_diagnostic_unauthorized
            else None
        )
        strike_fact_task_refs = None
        if self._action_ball_strike_fact_device_enabled:
            strike_fact_task_refs = (
                diagnostic_task_refs
                if diagnostic_task_refs is not None
                else tuple(receipt.task_ref() for receipt in receipts)
            )
        packed_strike_fact_key = (
            self._action_ball_strike_fact_pack_task_refs(
                strike_fact_task_refs
            )
            if strike_fact_task_refs is not None
            else None
        )
        dtype = self.racket_target_pos_w.dtype
        # Both reset and same-cycle WRAP install at receipt age zero.
        pending_elapsed_s = 0.0
        if self._action_ball_diagnostic_unauthorized:
            packed_install = _action_ball_pack_diagnostic_install_rows(
                receipts=receipts,
                counter_rally_identities=counter_rally_identities,
                dtype=dtype,
                device=self.device,
            )
            expected_width = (
                31 if counter_rally_identities is None else 34
            )
            if tuple(packed_install.shape) != (len(ids), expected_width):
                raise RuntimeError(
                    "diagnostic ActionBall install packet has the wrong shape"
                )
            ball_contact_local = packed_install[:, 0:3]
            site_target_local = packed_install[:, 3:6]
            base_goal_local = packed_install[:, 6:9]
            face_center_velocity = packed_install[:, 9:12]
            site_velocity = packed_install[:, 12:15]
            command_quat = packed_install[:, 15:19]
            racket_normal = packed_install[:, 19:22]
            incoming_velocity = packed_install[:, 22:25]
            incoming_spin = packed_install[:, 25:28]
            landing_aim = packed_install[:, 28:30]
            initial_tts = packed_install[:, 30].to(
                dtype=self.time_to_strike.dtype
            )
            counter_rally_return_direction = (
                None
                if counter_rally_identities is None
                else packed_install[:, 31:33]
            )
            counter_rally_target_speed = (
                None
                if counter_rally_identities is None
                else packed_install[:, 33]
            )
        else:
            ball_contact_local = torch.tensor(
                [receipt.ball_contact_w_m for receipt in receipts],
                dtype=dtype,
                device=self.device,
            )
            site_target_local = torch.tensor(
                [receipt.racket_site_target_w_m for receipt in receipts],
                dtype=dtype,
                device=self.device,
            )
            base_goal_local = torch.tensor(
                [receipt.base_goal_w_m for receipt in receipts],
                dtype=dtype,
                device=self.device,
            )
            face_center_velocity = torch.tensor(
                [
                    receipt.racket_face_center_velocity_w_mps
                    for receipt in receipts
                ],
                dtype=dtype,
                device=self.device,
            )
            site_velocity = torch.tensor(
                [receipt.racket_site_velocity_w_mps for receipt in receipts],
                dtype=dtype,
                device=self.device,
            )
            command_quat = torch.tensor(
                [receipt.racket_command_quat_wxyz for receipt in receipts],
                dtype=dtype,
                device=self.device,
            )
            racket_normal = torch.tensor(
                [receipt.racket_normal_w for receipt in receipts],
                dtype=dtype,
                device=self.device,
            )
            incoming_velocity = torch.tensor(
                [receipt.incoming_velocity_w_mps for receipt in receipts],
                dtype=dtype,
                device=self.device,
            )
            incoming_spin = torch.tensor(
                [receipt.incoming_spin_w_radps for receipt in receipts],
                dtype=dtype,
                device=self.device,
            )
            landing_aim = torch.tensor(
                [receipt.landing_aim_w_xy_m for receipt in receipts],
                dtype=dtype,
                device=self.device,
            )
            counter_rally_return_direction = None
            counter_rally_target_speed = None
            if counter_rally_identities is not None:
                counter_rally_return_direction = torch.tensor(
                    [
                        identity.return_direction_env_xy
                        for identity in counter_rally_identities
                    ],
                    dtype=dtype,
                    device=self.device,
                )
                counter_rally_target_speed = torch.tensor(
                    [
                        identity.target_baseline_speed_mps
                        for identity in counter_rally_identities
                    ],
                    dtype=dtype,
                    device=self.device,
                )
        tensors = (
            ball_contact_local,
            site_target_local,
            base_goal_local,
            face_center_velocity,
            site_velocity,
            command_quat,
            racket_normal,
            incoming_velocity,
            incoming_spin,
            landing_aim,
            *(
                ()
                if counter_rally_return_direction is None
                else (
                    counter_rally_return_direction,
                    counter_rally_target_speed,
                )
            ),
        )
        if self._action_ball_diagnostic_unauthorized:
            install_checks = _action_ball_host_bool_packet(
                (
                    torch.stack(
                        tuple(torch.isfinite(value).all() for value in tensors)
                    ).all(),
                    torch.all(
                        torch.abs(
                            torch.linalg.norm(racket_normal, dim=-1) - 1.0
                        )
                        <= 1.0e-6
                    ),
                    torch.all(
                        torch.abs(
                            torch.linalg.norm(command_quat, dim=-1) - 1.0
                        )
                        <= 1.0e-6
                    ),
                    torch.isfinite(initial_tts).all(),
                    torch.all(initial_tts > 0.0),
                )
            )
            if not install_checks[0]:
                raise RuntimeError(
                    "validated action-ball receipt produced a non-finite tensor"
                )
            if not install_checks[1]:
                raise RuntimeError(
                    "action-ball task normals are not unit length at install"
                )
            if not install_checks[2]:
                raise RuntimeError(
                    "action-ball task command quaternions are not unit length at install"
                )
            if not install_checks[3] or not install_checks[4]:
                raise RuntimeError(
                    "fresh action-ball receipt has no positive remaining "
                    "time-to-contact"
                )
        else:
            if any(not bool(torch.isfinite(value).all()) for value in tensors):
                raise RuntimeError(
                    "validated action-ball receipt produced a non-finite tensor"
                )
            if not bool(
                torch.allclose(
                    torch.linalg.norm(racket_normal, dim=-1),
                    torch.ones(len(ids), dtype=dtype, device=self.device),
                    rtol=0.0,
                    atol=1.0e-6,
                )
            ):
                raise RuntimeError(
                    "action-ball task normals are not unit length at install"
                )
            if not bool(
                torch.allclose(
                    torch.linalg.norm(command_quat, dim=-1),
                    torch.ones(len(ids), dtype=dtype, device=self.device),
                    rtol=0.0,
                    atol=1.0e-6,
                )
            ):
                raise RuntimeError(
                    "action-ball task command quaternions are not unit length at install"
                )
            initial_tts = torch.tensor(
                [
                    float(receipt.time_to_contact_s) - pending_elapsed_s
                    for receipt in receipts
                ],
                dtype=self.time_to_strike.dtype,
                device=self.device,
            )
            if not bool(torch.isfinite(initial_tts).all()) or bool(
                (initial_tts <= 0.0).any()
            ):
                raise RuntimeError(
                    "fresh action-ball receipt has no positive remaining "
                    "time-to-contact"
                )

        # Motion deliberately publishes a large positive sentinel between its
        # same-step WRAP and this atomic Racket install.  Validate the
        # receipt-owned replacement before touching any command buffer.  A
        # same-compute WRAP has not yet run one physical policy tick under the
        # newly installed task, so both WRAP and true reset enter at age zero.
        # No command or ball buffer is touched until every receipt and every materialized tensor in
        # the batch has validated.  These adjacent copies are the only live install transaction.
        self.racket_target_pos_w[ids] = origins + site_target_local
        self.racket_target_vel_w[ids] = site_velocity
        self.racket_target_normal_w[ids] = racket_normal
        self.target_normal_cmd[ids] = racket_normal
        self._action_ball_ball_contact_target_w[ids] = (
            origins + ball_contact_local
        )
        self._action_ball_face_center_velocity_target_w[ids] = (
            face_center_velocity
        )
        self._action_ball_racket_command_quat_w[ids] = command_quat
        self.base_target_pos_w[ids] = origins[:, :2] + base_goal_local[:, :2]
        self.vb_vel_in_w[ids] = incoming_velocity
        self.vb_spin_in_w[ids] = incoming_spin
        self._vb_target_xy_per_env[ids] = landing_aim
        if counter_rally_return_direction is not None:
            self._counter_rally_return_direction_env_xy[ids] = (
                counter_rally_return_direction
            )
            self._counter_rally_target_baseline_speed_mps[ids] = (
                counter_rally_target_speed
            )
        self._counter_rally_reward_terms[ids] = 0.0
        self._counter_rally_accepted[ids] = False
        self._counter_rally_legal_first_landing[ids] = False
        self._counter_rally_primary_reason_code[ids] = -1

        install_counts = torch.bincount(
            action_slots, minlength=len(self._action_ball_bindings)
        )
        self._action_ball_live_ledger()[_ACTION_BALL_LEDGER_NAMES.index("I")].add_(
            install_counts
        )
        self._action_ball_live_ledger()[_ACTION_BALL_LEDGER_NAMES.index("S")].add_(
            install_counts
        )
        self._action_ball_action_uid[ids] = action_uids
        self._action_ball_action_slot[ids] = action_slots
        self._action_ball_reset_generation[ids] = reset_generations
        self._action_ball_swing_generation[ids] = swing_generations
        self._action_ball_attempt_active[ids] = True
        self._action_ball_attempt_action[ids] = action_slots
        self._action_ball_attempt_legal[ids] = False
        self._action_ball_attempt_hit[ids] = False
        self._action_ball_invalidate_virtual_contact_history(ids)
        for row_index, (env_id, birth, receipt) in enumerate(
            zip(host_env_ids, births, receipts)
        ):
            self._action_ball_birth_by_env[env_id] = birth
            self._action_ball_task_by_env[env_id] = receipt
            self._action_ball_task_ref_by_env[env_id] = (
                diagnostic_task_refs[row_index]
                if diagnostic_task_refs is not None
                else None
            )
            self._counter_rally_task_identity_by_env[env_id] = (
                None
                if counter_rally_identities is None
                else counter_rally_identities[row_index]
            )
        self._action_ball_strike_fact_commit_task_key(
            ids, packed_strike_fact_key
        )
        # Replace only freshly installed rows so actor and reward views do not
        # observe a fake one-frame strike or Motion's pending sentinel.
        self.time_to_strike[ids] = initial_tts
        self.pre_strike[ids] = True
        tts_abs = initial_tts.abs()
        self.strike_window[ids] = (
            tts_abs <= float(self.cfg.strike_window_s)
        )
        pos_window_s = self.cfg.strike_window_pos_s
        wide_window_s = self.cfg.strike_window_wide_s
        self.strike_window_pos[ids] = (
            self.strike_window[ids]
            if pos_window_s is None
            else tts_abs <= float(pos_window_s)
        )
        self.strike_window_wide[ids] = (
            self.strike_window[ids]
            if wide_window_s is None
            else tts_abs <= float(wide_window_s)
        )
        return diagnostic_task_refs

    def _action_ball_commit_fixed_view_install(
        self,
        *,
        ids: torch.Tensor,
        origins: torch.Tensor,
        births: tuple,
        view,
        action_uids: torch.Tensor,
        action_slots: torch.Tensor,
        reset_generations: torch.Tensor,
        swing_generations: torch.Tensor,
        host_env_ids: tuple,
    ) -> None:
        """Install one immutable row-zero view without task materialization."""

        self._action_ball_reject_legacy_fresh_lane(
            "fixed-view direct task install"
        )

        if self._action_ball_strike_fact_device_enabled:
            raise RuntimeError(
                "same-transition strike facts require a full "
                "ActionTaskReceiptRef; immutable fixed-view install is "
                "receipt-free"
            )
        if not self._action_ball_fixed_view_enabled:
            raise RuntimeError(
                "immutable fixed-view install used outside its authority"
            )
        template = self._action_ball_fixed_view_template
        if (
            template is None
            or len(ids) != len(host_env_ids)
            or view.batch_size != len(ids)
            or view.row_index != 0
            or view.install_row != template.install_row
            or view.observation_row != template.observation_row
            or view.timing_row != template.timing_row
            or dict(view.lineage) != dict(template.lineage)
        ):
            raise RuntimeError(
                "immutable fixed-view reset template drifted before install"
            )
        install_rows = view.expand_install_rows(
            self._action_ball_fixed_view_install_row_device
        )
        observation_rows = view.expand_observation_rows(
            self._action_ball_fixed_view_observation_row_device
        )
        timing_rows = view.expand_timing_rows(
            self._action_ball_fixed_view_timing_row_device
        )
        if (
            tuple(install_rows.shape) != (len(ids), 31)
            or tuple(observation_rows.shape)[0] != len(ids)
            or tuple(timing_rows.shape) != (len(ids), 15)
        ):
            raise RuntimeError(
                "immutable fixed-view cached tensor broadcast drifted"
            )
        if len(births) != len(ids):
            raise RuntimeError(
                "immutable fixed-view birth batch has the wrong size"
            )
        for env_id, birth in zip(host_env_ids, births):
            if (
                self._action_ball_task_by_env[env_id] is not None
                or self._action_ball_task_ref_by_env[env_id] is not None
            ):
                raise RuntimeError(
                    "immutable fixed-view install found a task receipt/ref"
                )
            # This pure assertion preserves the legacy fixed-tape physical
            # guard (action/base/fixed-domain identity) without invoking its
            # pool-compatible materializer.
            self._action_ball_pool_solver._assert_birth_matches_question(
                birth
            )

        ball_contact_local = install_rows[:, 0:3]
        site_target_local = install_rows[:, 3:6]
        base_goal_local = install_rows[:, 6:9]
        face_center_velocity = install_rows[:, 9:12]
        site_velocity = install_rows[:, 12:15]
        command_quat = install_rows[:, 15:19]
        racket_normal = install_rows[:, 19:22]
        incoming_velocity = install_rows[:, 22:25]
        incoming_spin = install_rows[:, 25:28]
        landing_aim = install_rows[:, 28:30]
        initial_tts = install_rows[:, 30].to(
            dtype=self.time_to_strike.dtype
        )
        counter_rally_identity = (
            self._action_ball_fixed_view_counter_rally_identity
        )
        counter_rally_rows = (
            None
            if counter_rally_identity is None
            else self._action_ball_fixed_view_counter_rally_row_device.expand(
                len(ids), 3
            )
        )
        if (
            (counter_rally_rows is None) != (not self._counter_rally_enabled)
            or (
                counter_rally_rows is not None
                and tuple(counter_rally_rows.shape) != (len(ids), 3)
            )
        ):
            raise RuntimeError(
                "immutable fixed-view counter-rally cache drifted"
            )
        self.racket_target_pos_w[ids] = origins + site_target_local
        self.racket_target_vel_w[ids] = site_velocity
        self.racket_target_normal_w[ids] = racket_normal
        self.target_normal_cmd[ids] = racket_normal
        self._action_ball_ball_contact_target_w[ids] = (
            origins + ball_contact_local
        )
        self._action_ball_face_center_velocity_target_w[ids] = (
            face_center_velocity
        )
        self._action_ball_racket_command_quat_w[ids] = command_quat
        self.base_target_pos_w[ids] = (
            origins[:, :2] + base_goal_local[:, :2]
        )
        self.vb_vel_in_w[ids] = incoming_velocity
        self.vb_spin_in_w[ids] = incoming_spin
        self._vb_target_xy_per_env[ids] = landing_aim
        if counter_rally_rows is not None:
            self._counter_rally_return_direction_env_xy[ids] = (
                counter_rally_rows[:, :2]
            )
            self._counter_rally_target_baseline_speed_mps[ids] = (
                counter_rally_rows[:, 2]
            )
        self._counter_rally_reward_terms[ids] = 0.0
        self._counter_rally_accepted[ids] = False
        self._counter_rally_legal_first_landing[ids] = False
        self._counter_rally_primary_reason_code[ids] = -1

        install_counts = torch.bincount(
            action_slots, minlength=len(self._action_ball_bindings)
        )
        fixed_ledger = self._action_ball_fixed_view_ledger
        for name in ("P", "A", "I", "S"):
            fixed_ledger[
                _ACTION_BALL_LEDGER_NAMES.index(name)
            ].add_(install_counts)
        self._action_ball_action_uid[ids] = action_uids
        self._action_ball_action_slot[ids] = action_slots
        self._action_ball_reset_generation[ids] = reset_generations
        self._action_ball_swing_generation[ids] = swing_generations
        self._action_ball_attempt_active[ids] = True
        self._action_ball_attempt_action[ids] = action_slots
        self._action_ball_attempt_legal[ids] = False
        self._action_ball_attempt_hit[ids] = False
        self._action_ball_invalidate_virtual_contact_history(ids)
        for env_id, birth in zip(host_env_ids, births):
            self._action_ball_birth_by_env[env_id] = birth
            self._action_ball_task_by_env[env_id] = None
            self._action_ball_task_ref_by_env[env_id] = None
            self._counter_rally_task_identity_by_env[env_id] = (
                counter_rally_identity
            )

        self.time_to_strike[ids] = initial_tts
        self.pre_strike[ids] = True
        tts_abs = initial_tts.abs()
        self.strike_window[ids] = (
            tts_abs <= float(self.cfg.strike_window_s)
        )
        pos_window_s = self.cfg.strike_window_pos_s
        wide_window_s = self.cfg.strike_window_wide_s
        self.strike_window_pos[ids] = (
            self.strike_window[ids]
            if pos_window_s is None
            else tts_abs <= float(pos_window_s)
        )
        self.strike_window_wide[ids] = (
            self.strike_window[ids]
            if wide_window_s is None
            else tts_abs <= float(wide_window_s)
        )

    def _action_ball_finish_fixed_view_reset(
        self,
        *,
        ids: torch.Tensor,
        action_slots: torch.Tensor,
        host_identity_rows: tuple,
        true_reset: bool,
    ) -> None:
        """Publish fixed Motion timing, then the episode latch/wait state."""

        self._motion().install_action_ball_fixed_view_timing_now(
            env_ids=ids,
            host_identity_rows=host_identity_rows,
            fixed_view_identity_sha256=(
                self._action_ball_fixed_view_identity_sha256
            ),
        )
        if true_reset:
            phase_by_slot = self._action_ball_phase_center_mask_tensor()
            self._action_ball_reference_term_center_latch[ids] = (
                phase_by_slot[action_slots]
            )
        self._action_ball_arm_task_wait(
            ids,
            host_identity_rows=host_identity_rows,
            true_reset=true_reset,
        )

    def _sample_targets_action_ball(
        self,
        env_ids: Sequence[int],
        origins: torch.Tensor,
        n: int,
    ) -> None:
        """Consume the selected action birth, issue its solved ball, then install atomically."""

        self._action_ball_reject_legacy_fresh_lane("task sampler")

        if not self._action_ball_enabled:
            raise RuntimeError("action-ball sampler called while target_mode is not action_ball")
        from whole_body_tracking.tasks.tracking.mdp.action_ball_runtime import (
            ActionTaskIssueRequest,
            BirthConsumeRequest,
        )

        ids = torch.as_tensor(
            env_ids, dtype=torch.long, device=self.device
        ).reshape(-1)
        if len(ids) != n or tuple(origins.shape) != (n, 3):
            raise RuntimeError("action-ball resample batch shape mismatch")
        true_reset = not bool(self._resample_is_wrap)
        motion = self._motion()
        action_slots = motion.clip_id[ids].to(dtype=torch.long)
        action_uids = motion.action_ball_action_uid_for_envs(ids).to(
            dtype=torch.long
        )
        reset_generations = motion.action_ball_reset_generation[ids].to(
            dtype=torch.long
        )
        swing_generations = motion.action_ball_swing_generation[ids].to(
            dtype=torch.long
        )
        previous_swing_generations = self._action_ball_swing_generation[ids]
        attempt_active = self._action_ball_attempt_active[ids]

        # This is the only device-to-host identity transfer in the reset/task
        # transaction.  Every Python-side broker/pool/receipt check below
        # reuses these immutable rows instead of synchronizing each scalar.
        host_identity_rows = tuple(
            (
                int(env_id),
                int(action_slot),
                int(action_uid),
                int(reset_generation),
                int(swing_generation),
                int(previous_swing_generation),
                bool(active),
            )
            for (
                env_id,
                action_slot,
                action_uid,
                reset_generation,
                swing_generation,
                previous_swing_generation,
                active,
            ) in torch.stack(
                (
                    ids,
                    action_slots,
                    action_uids,
                    reset_generations,
                    swing_generations,
                    previous_swing_generations,
                    attempt_active.to(dtype=torch.long),
                ),
                dim=1,
            )
            .detach()
            .cpu()
            .tolist()
        )
        host_env_ids = tuple(row[0] for row in host_identity_rows)
        if (
            len(host_env_ids) != n
            or len(set(host_env_ids)) != n
            or any(
                env_id < 0 or env_id >= self.num_envs
                for env_id in host_env_ids
            )
        ):
            raise RuntimeError(
                "action-ball resample batch has invalid or repeated environments"
            )
        active_host_env_ids = tuple(
            row[0] for row in host_identity_rows if row[6]
        )
        self._action_ball_close_attempts(
            ids,
            true_reset=true_reset,
            active_host_env_ids=active_host_env_ids,
        )

        n_actions = len(self._action_ball_bindings)
        for row in host_identity_rows:
            action_slot = row[1]
            action_uid = row[2]
            if action_slot < 0 or action_slot >= n_actions:
                raise RuntimeError(
                    "action-ball selected motion slot is outside the manifest"
                )
            if (
                action_uid
                != int(self._action_ball_bundle.action_uids[action_slot])
            ):
                raise RuntimeError(
                    "Motion action UID and manifest slot disagree"
                )

        if true_reset:
            if any(row[4] != 0 for row in host_identity_rows):
                raise RuntimeError(
                    "action-ball true reset must start at swing generation zero"
                )
            self._action_ball_retire_previous_births(
                ids, host_env_ids=host_env_ids
            )
            consume_requests = tuple(
                BirthConsumeRequest(
                    env_id=env_id,
                    reset_generation=reset_generation,
                    action_uid=action_uid,
                    action_slot=action_slot,
                    receipt_sha256=motion.action_ball_birth_receipt_sha256(
                        env_id
                    ),
                )
                for (
                    env_id,
                    action_slot,
                    action_uid,
                    reset_generation,
                    _swing_generation,
                    _previous_swing_generation,
                    _active,
                ) in host_identity_rows
            )
            births = self._action_ball_broker.consume_many_true_reset(
                consume_requests, reset_kind="true_reset"
            )
        else:
            birth_rows = []
            for (
                env_id,
                action_slot,
                action_uid,
                reset_generation,
                swing_generation,
                previous_swing_generation,
                _active,
            ) in host_identity_rows:
                birth = self._action_ball_birth_by_env[env_id]
                if birth is None:
                    raise RuntimeError(
                        "action-ball wrap has no consumed episode birth"
                    )
                if (
                    birth.env_id != env_id
                    or birth.action_uid != action_uid
                    or birth.action_slot != action_slot
                    or birth.reset_generation
                    != reset_generation
                    or motion.action_ball_birth_receipt_sha256(env_id)
                    != birth.canonical_sha256
                ):
                    raise RuntimeError(
                        "action-ball wrap changed its frozen action/birth identity"
                    )
                if swing_generation != previous_swing_generation + 1:
                    raise RuntimeError(
                        "action-ball wrap swing generation did not advance exactly once"
                    )
                self._action_ball_broker.assert_consumed_birth(birth)
                birth_rows.append(birth)
            births = tuple(birth_rows)

        if len(births) != n:
            raise RuntimeError("action-ball broker returned the wrong birth batch size")
        for birth, row in zip(births, host_identity_rows):
            env_id, action_slot, _uid, reset_generation = row[:4]
            binding = self._action_ball_bindings[action_slot]
            birth.assert_contract(
                binding=binding,
                pins=self._action_ball_pins,
                mobility_mode=self._action_ball_manifest.mobility_mode,
                registry_sha256=self._action_ball_broker.registry_sha256,
            )
            if (
                birth.env_id != env_id
                or birth.reset_generation != reset_generation
            ):
                raise RuntimeError(
                    "action-ball consumed birth does not match its env generation"
                )

        if self._action_ball_fixed_view_enabled:
            # This is the complete immutable reset data plane.  It never
            # enters LazyActionTaskPool and therefore cannot materialize or
            # forge a per-environment ActionBallTaskReceipt.
            fixed_view = self._action_ball_pool_solver.reset_batch_view(
                batch_size=n
            )
            self._action_ball_commit_fixed_view_install(
                ids=ids,
                origins=origins,
                births=births,
                view=fixed_view,
                action_uids=action_uids,
                action_slots=action_slots,
                reset_generations=reset_generations,
                swing_generations=swing_generations,
                host_env_ids=host_env_ids,
            )
            self._action_ball_finish_fixed_view_reset(
                ids=ids,
                action_slots=action_slots,
                host_identity_rows=host_identity_rows,
                true_reset=true_reset,
            )
            return

        # The pool can refill each birth lazily.  Simulator/command buffers remain untouched until
        # all rows issue and validate; solver rejects only increase P/reason counters upstream.
        receipts = self._action_ball_pool.request_many(
            tuple(
                ActionTaskIssueRequest(
                    birth=birth,
                    swing_generation=row[4],
                )
                for birth, row in zip(births, host_identity_rows)
            )
        )
        if self._action_ball_banded_question_bank is not None:
            # The precomputed solver bypasses the online proposal callback, so
            # the pool is the task P/A authority.  Mirror only those aggregate
            # counters after the pool transaction commits; broker/domain
            # sampler state and the bank's bounded block state remain separate.
            for action_slot in sorted({int(row[1]) for row in host_identity_rows}):
                action_uid = int(self._action_ball_bindings[action_slot].action_uid)
                pool_ledger = self._action_ball_pool.ledger(action_uid)
                self._action_ball_live_ledger()[
                    _ACTION_BALL_LEDGER_NAMES.index("P"), action_slot
                ] = int(pool_ledger.proposed)
                self._action_ball_live_ledger()[
                    _ACTION_BALL_LEDGER_NAMES.index("A"), action_slot
                ] = int(pool_ledger.admitted)
        if len(receipts) != n:
            raise RuntimeError("action-ball pool issued the wrong task batch size")
        for birth, receipt, row in zip(
            births, receipts, host_identity_rows
        ):
            env_id, action_slot = row[:2]
            swing_generation = row[4]
            binding = self._action_ball_bindings[action_slot]
            receipt.assert_contract(
                binding=binding,
                pins=self._action_ball_pins,
                mobility_mode=self._action_ball_manifest.mobility_mode,
                registry_sha256=self._action_ball_broker.registry_sha256,
            )
            receipt.assert_birth(birth)
            if (
                receipt.env_id != env_id
                or receipt.swing_generation != swing_generation
            ):
                raise RuntimeError(
                    "action-ball task receipt env/swing generation mismatch"
                )
        diagnostic_task_refs = self._action_ball_commit_install(
            ids=ids,
            origins=origins,
            births=births,
            receipts=receipts,
            action_uids=action_uids,
            action_slots=action_slots,
            reset_generations=reset_generations,
            swing_generations=swing_generations,
            host_env_ids=host_env_ids,
        )
        # Motion resets before Racket.  Resolve the just-published task receipt
        # now so the first post-reset actor observation sees the full teacher
        # wait instead of a one-frame false zero.  The diagnostic fast path
        # reuses the already validated host rows and receipts; formal retains
        # the opaque ref/resolver authority seam unchanged.
        if self._action_ball_diagnostic_unauthorized:
            if type(diagnostic_task_refs) is not tuple:
                raise RuntimeError(
                    "diagnostic action-ball install lost its task ref batch"
                )
            # The diagnostic pool and Racket install have already advanced.
            # Any Motion validation failure poisons the whole run and must
            # propagate; catching it and retrying would reuse advanced state.
            motion.resolve_action_ball_task_timing_now(
                diagnostic_host_identity_rows=host_identity_rows,
                diagnostic_receipts=receipts,
                diagnostic_task_refs=diagnostic_task_refs,
            )
        else:
            motion.resolve_action_ball_task_timing_now(ids)
        if true_reset:
            # The installed birth is the authority boundary for the whole
            # episode.  Compute against the published phase only after all
            # birth/task receipts validate, then latch by env.  A wrap never
            # enters this branch.
            phase_by_slot = self._action_ball_phase_center_mask_tensor()
            self._action_ball_reference_term_center_latch[ids] = (
                phase_by_slot[action_slots]
            )

        self._action_ball_arm_task_wait(
            ids,
            host_identity_rows=host_identity_rows,
            true_reset=true_reset,
        )

    def _action_ball_arm_task_wait(
        self,
        ids: torch.Tensor,
        *,
        host_identity_rows: tuple,
        true_reset: bool,
    ) -> None:
        """Install one deterministic RESET_WAIT without exposing its countdown.

        The immutable task is already installed, but both Motion clocks are
        extended by exactly ``wait_ticks * policy_dt``.  The public teacher
        remains the frozen physical safe-ready reference (and the physical
        ball remains parked) until the atomic frame-zero reveal.  Actor,
        critic, and reward consumers see only ``_action_ball_task_valid``;
        the wait countdown remains private.
        """

        schedule = self._action_ball_task_wait_schedule
        motion = self._motion()
        motion.bind_action_ball_public_task_valid(
            self._action_ball_task_valid
        )
        if schedule is None or not true_reset:
            self._action_ball_task_wait_total_ticks[ids] = 0
            self._action_ball_task_wait_elapsed_ticks[ids] = 0
            self._action_ball_task_valid[ids] = True
            return
        if type(true_reset) is not bool:
            raise TypeError("ActionBall task-wait true_reset must be boolean")
        if len(host_identity_rows) != len(ids):
            raise RuntimeError("ActionBall task-wait identity batch differs")
        assignments = tuple(
            self._action_ball_task_wait_highwater.record(
                env_id=int(row[0]), reset_generation=int(row[3])
            )
            for row in host_identity_rows
        )
        wait_ticks = torch.tensor(
            [assignment.wait_ticks for assignment in assignments],
            dtype=torch.long,
            device=self.device,
        )
        if tuple(wait_ticks.shape) != (len(ids),) or bool(
            (wait_ticks <= 0).any()
        ):
            raise RuntimeError("ActionBall task-wait assignment is malformed")
        wait_s = wait_ticks.to(dtype=torch.float64) * float(self._env.step_dt)
        motion._action_ball_time_to_contact_s[ids] += wait_s
        motion._action_ball_pre_swing_wait_s[ids] += wait_s
        self.time_to_strike[ids] = (
            motion.action_ball_time_to_contact_remaining_s[ids].to(
                dtype=self.time_to_strike.dtype
            )
        )
        self._action_ball_task_wait_total_ticks[ids] = wait_ticks
        self._action_ball_task_wait_elapsed_ticks[ids] = 0
        self._action_ball_task_valid[ids] = False
        self._ensure_exact_behavior_decision_counters()[
            _TASK_WAIT_STARTED_COUNTER
        ].add_(len(ids))

    def _advance_action_ball_task_wait(self) -> None:
        """Reveal tasks exactly after their private integer wait expires."""

        if self._action_ball_task_wait_schedule is None:
            return
        policy_step = getattr(self._env, "common_step_counter", None)
        if type(policy_step) is not int or policy_step < 0:
            raise RuntimeError(
                "ActionBall task-wait requires a non-negative integer policy-step token"
            )
        if policy_step == self._action_ball_task_wait_last_advance_step:
            return
        if policy_step < self._action_ball_task_wait_last_advance_step:
            raise RuntimeError("ActionBall task-wait policy-step token moved backwards")
        self._action_ball_task_wait_last_advance_step = policy_step
        waiting = ~self._action_ball_task_valid
        elapsed = self._action_ball_task_wait_elapsed_ticks
        total = self._action_ball_task_wait_total_ticks
        elapsed.add_(waiting.to(dtype=elapsed.dtype))
        invalid = waiting & ((total <= 0) | (elapsed > total))
        _action_ball_validate_tensor_predicate(
            ~invalid,
            "ActionBall task-wait counter is invalid",
            async_validate=bool(self._action_ball_diagnostic_unauthorized),
        )
        reveal = waiting & (elapsed == total)
        # This counter is consumed transactionally by the once-per-PPO-update
        # exact-behavior marker.  Count the false->true edge, never the number
        # of task-valid samples: it is the honest survival denominator for
        # reaching the public task reveal after RESET_WAIT.
        self._ensure_exact_behavior_decision_counters()[
            _TASK_REVEAL_REACHED_COUNTER
        ].add_(reveal.sum(dtype=torch.long))
        self._action_ball_task_valid |= reveal
        # Motion ran earlier in CommandManager order and cached the hidden
        # safe-ready aligned body tuple.  Update newly revealed rows now so
        # joint/body/paddle consumers all observe measured frame 0 this tick.
        self._motion().refresh_action_ball_revealed_body_reference(reveal)

    def _action_ball_ledger_payload(self) -> dict:
        fixed_view = self._action_ball_fixed_view_enabled
        values = self._action_ball_live_ledger().detach().cpu().tolist()
        fixed_active_counts = None
        if fixed_view:
            fixed_solver_state = self._action_ball_pool_solver.state_dict()
            if (
                any(
                    task is not None
                    for task in self._action_ball_task_by_env
                )
                or any(
                    ref is not None
                    for ref in self._action_ball_task_ref_by_env
                )
                or any(self._action_ball_emitted_task_count_by_uid.values())
                or any(
                    any(int(count) != 0 for count in counts.values())
                    for counts in self._action_ball_reject_counts.values()
                )
                or fixed_solver_state.get("highwaters") != []
                or fixed_solver_state.get("assignments") != []
                or fixed_solver_state.get("emitted_tasks") != []
                or fixed_solver_state.get("physical_rng_draws") != 0
                or fixed_solver_state.get("online_lm_calls") != 0
            ):
                raise RuntimeError(
                    "immutable fixed-view report acquired task receipt or "
                    "solver-rejection state"
                )
            active = self._action_ball_attempt_active
            slots = self._action_ball_attempt_action
            invalid_active = active & (
                (slots < 0) | (slots >= len(self._action_ball_bindings))
            )
            if bool(invalid_active.any().item()):
                raise RuntimeError(
                    "immutable fixed-view report has an invalid active slot"
                )
            fixed_active_counts = (
                torch.bincount(
                    slots[active],
                    minlength=len(self._action_ball_bindings),
                )
                .detach()
                .cpu()
                .tolist()
            )
        payload = {
            action: {
                name: int(values[row][slot])
                for row, name in enumerate(_ACTION_BALL_LEDGER_NAMES)
            }
            for slot, action in enumerate(self._action_ball_manifest.action_order)
        }
        for slot, uid in enumerate(self._action_ball_bundle.action_uids):
            values = payload[self._action_ball_manifest.action_order[slot]]
            if values["H"] > values["C"]:
                raise RuntimeError(
                    "action-ball selected-rubber hits exceed closed attempts"
                )
            ledger = self._action_ball_outcome_type(
                **{
                    name: values[name]
                    for name in _ACTION_BALL_OUTCOME_LEDGER_NAMES
                }
            )
            if fixed_view:
                if not (
                    ledger.P == ledger.A == ledger.I == ledger.S
                    and ledger.S
                    == ledger.C
                    + ledger.X
                    + int(fixed_active_counts[slot])
                ):
                    raise RuntimeError(
                        "immutable fixed-view logical ledger does not "
                        "conserve P=A=I=S=C+X+active: "
                        f"action_uid={uid}, ledger={ledger.as_dict()}"
                    )
            else:
                pool = self._action_ball_pool.ledger(int(uid))
                if (
                    ledger.P != pool.proposed
                    or ledger.A != pool.admitted
                    or ledger.I != pool.issued
                    or ledger.S != pool.issued
                ):
                    raise RuntimeError(
                        "action-ball outcome ledger diverged from the solved-task pool: "
                        f"action_uid={uid}, ledger={ledger.as_dict()}, pool={pool.to_dict()}"
                    )
        if fixed_view and bool(self._action_ball_ledger.any().item()):
            raise RuntimeError(
                "immutable fixed-view evidence leaked into the legacy pool ledger"
            )
        return payload

    def _action_ball_on_rollout_end(self, step: int) -> None:
        """Emit cumulative collection truth; live PPO rollouts never advance the curriculum."""

        if type(step) is not int or step < 0:
            raise ValueError("action-ball rollout step must be a non-negative plain integer")
        if (
            self._action_ball_last_rollout_step is not None
            and step <= self._action_ball_last_rollout_step
        ):
            raise RuntimeError(
                "action-ball rollout callback must run exactly once in increasing step order"
            )
        ledger_payload = self._action_ball_ledger_payload()
        receipt = {
            "event": "action_ball_training_ledger",
            "schema_version": 1,
            "step": step,
            "manifest_sha256": self._action_ball_loaded_manifest.file_sha256,
            "status": "report_only_requires_frozen_checkpoint_evidence",
            "action_order": list(self._action_ball_manifest.action_order),
            "ledger": ledger_payload,
            "solver_rejections": {
                str(uid): {
                    name: int(count)
                    for name, count in sorted(
                        self._action_ball_reject_counts[int(uid)].items()
                    )
                }
                for uid in self._action_ball_bundle.action_uids
            },
            "exact_question_answer_cache": (
                None
                if self._action_ball_exact_question_cache is None
                else {
                    "policy": (
                        "reuse_exact_question_until_semantics_change"
                    ),
                    "consumer_hit_count": (
                        self._action_ball_exact_question_cache.consumer_hit_count
                    ),
                    "novel_producer_count": (
                        self._action_ball_exact_question_cache.novel_producer_count
                    ),
                    "row_count": (
                        self._action_ball_exact_question_cache.row_count
                    ),
                    "active_birth_count": (
                        self._action_ball_exact_question_cache.active_birth_count
                    ),
                    "capacity_policy": (
                        "active_birth_rows_plus_one_hot_row_per_action"
                    ),
                }
            ),
            "curriculum": {
                str(key.action_uid): {
                    "phase": self._action_ball_curriculum.phase(key),
                    "frontiers": self._action_ball_curriculum.frontiers(key),
                    "expected_domains": [
                        {
                            "stratum": domain.stratum,
                            "domain_epoch": domain.domain_epoch,
                            "levels": list(domain.levels),
                            "rho": domain.rho,
                        }
                        for domain in self._action_ball_curriculum.expected_domains(
                            key
                        )
                    ],
                }
                for key in self._action_ball_profile_keys
            },
        }
        if self._action_ball_fixed_view_enabled:
            receipt["fixed_view"] = {
                "identity_sha256": (
                    self._action_ball_fixed_view_identity_sha256
                ),
                "reset_operation": (
                    "FixedQuestionTapeSolver.reset_batch_view"
                ),
                "task_pool_bypassed": True,
                "task_receipts_created": 0,
                "logical_ledger": ledger_payload,
            }
        else:
            receipt["pool"] = {
                str(uid): {
                    **self._action_ball_pool.ledger(int(uid)).to_dict(),
                    "pending": self._action_ball_pool.pending_count(int(uid)),
                }
                for uid in self._action_ball_bundle.action_uids
            }
        if self._action_ball_diagnostic_unauthorized:
            # Brand every receipt this run emits; default-off runs stay
            # byte-identical.
            receipt["diagnostic_unauthorized"] = True
        if (
            self._action_ball_reference_guard_mode
            == _REFERENCE_GUARD_METRICS_ONLY
        ):
            receipt["reference_guard_mode"] = (
                _REFERENCE_GUARD_METRICS_ONLY
            )
        print(
            json.dumps(
                receipt,
                sort_keys=True,
                separators=(",", ":"),
                ensure_ascii=False,
                allow_nan=False,
            ),
            flush=True,
        )
        self._action_ball_last_rollout_step = step

    def _action_ball_force_drain_for_release(self) -> None:
        """Burn live rollout work and retire all births before one global reset."""

        if self._action_ball_diagnostic_unauthorized:
            raise RuntimeError(
                "diagnostic action-ball cannot publish a curriculum release"
            )
        if bool(
            getattr(self, "_action_ball_drain_fence_active", False)
        ) or bool(
            getattr(self, "_action_ball_drain_prepared", False)
        ):
            raise RuntimeError("action-ball global drain is already active")
        if not any(
            self._action_ball_curriculum.pending_domain_release(key)
            is not None
            for key in self._action_ball_profile_keys
        ):
            raise RuntimeError(
                "action-ball global drain has no pending domain release"
            )
        ids = torch.arange(
            self.num_envs, dtype=torch.long, device=self.device
        )
        self._action_ball_strike_fact_close_before_task_mutation(
            ids, mutation="ActionBall global drain"
        )
        active = self._action_ball_attempt_active.clone()
        slots = self._action_ball_attempt_action.clone()
        if bool(
            (
                active
                & (
                    (slots < 0)
                    | (slots >= len(self._action_ball_bindings))
                )
            ).any()
        ):
            raise RuntimeError(
                "action-ball drain found an invalid active attempt slot"
            )
        if bool(active.any()):
            additions = torch.bincount(
                slots[active],
                minlength=len(self._action_ball_bindings),
            )
            self._action_ball_live_ledger()[
                _ACTION_BALL_LEDGER_NAMES.index("X")
            ].add_(additions)
        for env_id in range(self.num_envs):
            self._action_ball_task_by_env[env_id] = None
            self._action_ball_task_ref_by_env[env_id] = None
            self._counter_rally_task_identity_by_env[env_id] = None
        self._action_ball_attempt_active.zero_()
        self._action_ball_attempt_action.fill_(-1)
        self._action_ball_attempt_legal.zero_()
        self._action_ball_attempt_hit.zero_()
        self._counter_rally_reward_terms.zero_()
        self._counter_rally_accepted.zero_()
        self._counter_rally_legal_first_landing.zero_()
        self._counter_rally_primary_reason_code.fill_(-1)
        self._action_ball_invalidate_virtual_contact_history(ids)
        self._action_ball_retire_previous_births(ids)

        broker_state = self._action_ball_broker.state_dict()
        if broker_state["pending"]:
            raise RuntimeError(
                "action-ball global drain left pending birth reservations"
            )
        if self._action_ball_provider_births:
            raise RuntimeError(
                "action-ball global drain left active provider births"
            )
        if any(
            self._action_ball_pool.pending_count(int(uid))
            for uid in self._action_ball_bundle.action_uids
        ):
            raise RuntimeError(
                "action-ball global drain left pending task receipts"
            )
        self._action_ball_drain_prepared = True
        self._action_ball_drain_reset_participants = tuple(
            range(self.num_envs)
        )

    def _action_ball_drain_runtime_snapshot(
        self, *, reset_generation: int
    ) -> dict:
        """Return code-owned drain truth; callers cannot supply counters."""

        if (
            type(reset_generation) is not int
            or reset_generation < 1
            or not bool(
                getattr(self, "_action_ball_drain_prepared", False)
            )
        ):
            raise RuntimeError(
                "action-ball drain snapshot requires a prepared full reset"
            )
        participants = tuple(
            getattr(
                self,
                "_action_ball_drain_reset_participants",
                (),
            )
        )
        if participants != tuple(range(self.num_envs)):
            raise RuntimeError(
                "action-ball drain snapshot is not exact N-of-N"
            )
        fixed_view = self._action_ball_fixed_view_enabled
        broker_state = (
            self._action_ball_fixed_view_broker_state_dict()
            if fixed_view
            else self._action_ball_broker.state_dict()
        )
        pool_state = (
            self._action_ball_fixed_view_pool_state_dict()
            if fixed_view
            else self._action_ball_pool.state_dict()
        )
        active_attempts = int(
            self._action_ball_attempt_active.sum().item()
        )
        active_births = sum(
            birth is not None for birth in self._action_ball_birth_by_env
        )
        pending_tasks = (
            0
            if fixed_view
            else sum(
                self._action_ball_pool.pending_count(int(uid))
                for uid in self._action_ball_bundle.action_uids
            )
        )
        env_state = {
            "action_uid": [
                int(value)
                for value in self._action_ball_action_uid.detach()
                .cpu()
                .tolist()
            ],
            "action_slot": [
                int(value)
                for value in self._action_ball_action_slot.detach()
                .cpu()
                .tolist()
            ],
            "reset_generation": [
                int(value)
                for value in self._action_ball_reset_generation.detach()
                .cpu()
                .tolist()
            ],
            "swing_generation": [
                int(value)
                for value in self._action_ball_swing_generation.detach()
                .cpu()
                .tolist()
            ],
            "participants": list(participants),
            "global_reset_generation": reset_generation,
        }
        bitmap = _action_ball_canonical_sha256(
            {
                "schema_version": 1,
                "reset_generation": reset_generation,
                "env_count": self.num_envs,
                "reset_participant_ids": list(participants),
            }
        )
        generation_fields = {
            "broker_reset_generation": reset_generation,
            "attempt_pool_reset_generation": reset_generation,
            "task_receipt_pool_reset_generation": reset_generation,
            "env_reset_generation": reset_generation,
        }
        return {
            **generation_fields,
            "active_attempts": active_attempts,
            "reserved_attempts": len(broker_state["pending"]),
            "active_births": active_births,
            "pending_task_receipts": pending_tasks,
            "reset_count": len(participants),
            "env_count": self.num_envs,
            "reset_participant_ids": list(participants),
            "reset_bitmap_sha256": bitmap,
            "broker_state_root_sha256": (
                _action_ball_canonical_sha256(broker_state)
            ),
            "attempt_pool_state_root_sha256": (
                _action_ball_canonical_sha256(
                    {
                        "active": active_attempts,
                        "attempt_action": [
                            int(value)
                            for value in (
                                self._action_ball_attempt_action.detach()
                                .cpu()
                                .tolist()
                            )
                        ],
                        "ledger": self._action_ball_ledger_payload(),
                    }
                )
            ),
            "task_receipt_pool_state_root_sha256": (
                _action_ball_canonical_sha256(pool_state)
            ),
            "env_reset_state_root_sha256": (
                _action_ball_canonical_sha256(env_state)
            ),
        }

    def _action_ball_complete_global_reset(self) -> None:
        if not bool(
            getattr(self, "_action_ball_drain_prepared", False)
        ):
            raise RuntimeError(
                "action-ball global reset completed without a drain"
            )
        if bool(
            getattr(self, "_action_ball_drain_fence_active", False)
        ):
            raise RuntimeError(
                "action-ball global reset returned with a live fence"
            )
        if (
            any(
                birth is None
                for birth in self._action_ball_birth_by_env
            )
            or not bool(self._action_ball_attempt_active.all())
        ):
            raise RuntimeError(
                "action-ball global reset did not install every new birth/task"
            )
        self._action_ball_drain_prepared = False
        self._action_ball_drain_reset_participants = ()

    def _action_ball_eval_runtime_state_dict(self) -> dict:
        if self._action_ball_diagnostic_unauthorized:
            return {
                "schema_version": 1,
                "diagnostic_unauthorized": True,
                "last_request_step": -1,
                "profile_cursor": 0,
                "next_kind_by_uid": {},
                "coordinator": None,
                "drain_source": None,
            }
        result = {
            "schema_version": 1,
            "diagnostic_unauthorized": False,
            "last_request_step": self._action_ball_eval_last_request_step,
            "profile_cursor": self._action_ball_eval_profile_cursor,
            "next_kind_by_uid": {
                str(uid): self._action_ball_eval_next_kind_by_uid[int(uid)]
                for uid in self._action_ball_bundle.action_uids
            },
            "coordinator": (
                self._action_ball_evaluation_coordinator.state_dict()
            ),
            "drain_source": (
                self._action_ball_drain_reset_source.state_dict()
            ),
        }
        result["state_sha256"] = _action_ball_canonical_sha256(result)
        return result

    def _action_ball_eval_request_binding(
        self,
        *,
        checkpoint_path: str,
        runner_bindings: Mapping[str, object],
    ) -> dict:
        from whole_body_tracking.tasks.tracking.mdp import (
            action_ball_evaluation_inbox as inbox_protocol,
        )

        expected_runner = {
            "schema_version",
            "training_contract_sha256",
            "training_contract",
            "environment_config_pickle",
            "agent_config_pickle",
            "runtime_identity",
            "training_launch_claim_sha256",
            "runtime_bootstrap_receipt_sha256",
            "runtime_bootstrap_lineage_payload_sha256",
            "runtime_bootstrap_receipt",
            "policy_generation",
            "policy_state",
            "ppo_recipe_sha256",
            "reward_sha256",
            "actor_obs_normalizer",
            "critic_obs_normalizer",
        }
        if (
            not isinstance(runner_bindings, Mapping)
            or set(runner_bindings) != expected_runner
            or runner_bindings["schema_version"] != 1
            or runner_bindings["ppo_recipe_sha256"]
            != self.cfg.action_ball_policy_contract_sha256
            or not isinstance(
                runner_bindings["training_contract"], Mapping
            )
            or runner_bindings["training_contract"].get("sha256")
            != runner_bindings["training_contract_sha256"]
        ):
            raise RuntimeError(
                "runner frozen-eval binding differs from policy contract"
            )
        actions = []
        for binding in self._action_ball_bindings:
            motion = (
                self._action_ball_repo_root / binding.motion_path
            ).resolve(strict=True)
            actions.append(
                {
                    "action_uid": int(binding.action_uid),
                    "motion": inbox_protocol.artifact_receipt(motion),
                }
            )
        return {
            "checkpoint": inbox_protocol.artifact_receipt(
                checkpoint_path
            ),
            "training_contract": dict(
                runner_bindings["training_contract"]
            ),
            "environment_config_pickle": dict(
                runner_bindings["environment_config_pickle"]
            ),
            "agent_config_pickle": dict(
                runner_bindings["agent_config_pickle"]
            ),
            "runtime_identity": dict(
                runner_bindings["runtime_identity"]
            ),
            "training_launch_claim_sha256": runner_bindings[
                "training_launch_claim_sha256"
            ],
            "runtime_bootstrap_receipt_sha256": runner_bindings[
                "runtime_bootstrap_receipt_sha256"
            ],
            "runtime_bootstrap_lineage_payload_sha256": runner_bindings[
                "runtime_bootstrap_lineage_payload_sha256"
            ],
            "runtime_bootstrap_receipt": dict(
                runner_bindings["runtime_bootstrap_receipt"]
            ),
            "policy_generation": runner_bindings["policy_generation"],
            "policy_state": dict(runner_bindings["policy_state"]),
            "actor_obs_normalizer": dict(
                runner_bindings["actor_obs_normalizer"]
            ),
            "critic_obs_normalizer": dict(
                runner_bindings["critic_obs_normalizer"]
            ),
            "ppo_recipe_sha256": runner_bindings[
                "ppo_recipe_sha256"
            ],
            "policy_contract_sha256": (
                self.cfg.action_ball_policy_contract_sha256
            ),
            "action_order": [
                int(uid) for uid in self._action_ball_bundle.action_uids
            ],
            "actions": actions,
            "manifest_sha256": (
                self._action_ball_loaded_manifest.file_sha256
            ),
            "sampler_sha256": (
                self._action_ball_sampler.sampler_contract_sha256
            ),
            "proposal_sampler_contract_sha256": (
                __import__(
                    "whole_body_tracking.tasks.tracking.mdp.action_ball_sampling",
                    fromlist=[
                        "FROZEN_EVALUATION_PROPOSAL_SAMPLER_CONTRACT_SHA256"
                    ],
                ).FROZEN_EVALUATION_PROPOSAL_SAMPLER_CONTRACT_SHA256
            ),
            "solver_sha256": self._action_ball_solver_contract["sha256"],
            "physics_sha256": self._action_ball_physics_contract[
                "sha256"
            ],
            "reward_sha256": runner_bindings["reward_sha256"],
            "curriculum_sha256": (
                self._action_ball_bundle.contract_sha256
            ),
        }

    def _action_ball_eval_latest_record(self) -> tuple[int, dict] | None:
        state = self._action_ball_evaluation_coordinator.state_dict()
        records = state["records"]
        if not records:
            return None
        return len(records) - 1, records[-1]

    def _action_ball_eval_key_for_request(self, request_seq: int):
        coordinator = self._action_ball_evaluation_coordinator
        request = coordinator._inbox.load_request(
            self._action_ball_evaluator_launch["inbox_owner_id"],
            self._action_ball_evaluator_launch["inbox_run_id"],
            request_seq,
        )
        uid = int(request["content"]["target"]["action_uid"])
        try:
            return self._action_ball_key_by_uid[uid]
        except KeyError as exc:
            raise RuntimeError(
                "frozen-eval request names an unknown action UID"
            ) from exc

    def _action_ball_eval_assert_frozen_runner_binding(
        self,
        request_seq: int,
        runner_bindings: object,
    ) -> None:
        """Prove the live policy/normalizers still equal the frozen request."""

        expected_runner = {
            "schema_version",
            "training_contract_sha256",
            "training_contract",
            "environment_config_pickle",
            "agent_config_pickle",
            "runtime_identity",
            "training_launch_claim_sha256",
            "runtime_bootstrap_receipt_sha256",
            "runtime_bootstrap_lineage_payload_sha256",
            "runtime_bootstrap_receipt",
            "policy_generation",
            "policy_state",
            "ppo_recipe_sha256",
            "reward_sha256",
            "actor_obs_normalizer",
            "critic_obs_normalizer",
        }
        if (
            not isinstance(runner_bindings, Mapping)
            or set(runner_bindings) != expected_runner
            or runner_bindings["schema_version"] != 1
        ):
            raise RuntimeError(
                "frozen-eval fence received an invalid runner binding"
            )
        request = self._action_ball_evaluation_coordinator._inbox.load_request(
            self._action_ball_evaluator_launch["inbox_owner_id"],
            self._action_ball_evaluator_launch["inbox_run_id"],
            request_seq,
        )
        frozen = request["content"]["bindings"]
        comparable = {
            "training_contract": runner_bindings["training_contract"],
            "environment_config_pickle": runner_bindings[
                "environment_config_pickle"
            ],
            "agent_config_pickle": runner_bindings[
                "agent_config_pickle"
            ],
            "runtime_identity": runner_bindings["runtime_identity"],
            "training_launch_claim_sha256": runner_bindings[
                "training_launch_claim_sha256"
            ],
            "runtime_bootstrap_receipt_sha256": runner_bindings[
                "runtime_bootstrap_receipt_sha256"
            ],
            "runtime_bootstrap_lineage_payload_sha256": runner_bindings[
                "runtime_bootstrap_lineage_payload_sha256"
            ],
            "runtime_bootstrap_receipt": runner_bindings[
                "runtime_bootstrap_receipt"
            ],
            "policy_generation": runner_bindings["policy_generation"],
            "policy_state": runner_bindings["policy_state"],
            "actor_obs_normalizer": runner_bindings[
                "actor_obs_normalizer"
            ],
            "critic_obs_normalizer": runner_bindings[
                "critic_obs_normalizer"
            ],
            "ppo_recipe_sha256": runner_bindings["ppo_recipe_sha256"],
            "reward_sha256": runner_bindings["reward_sha256"],
        }
        observed = {name: frozen[name] for name in comparable}
        if observed != comparable:
            raise RuntimeError(
                "live policy/normalizer identity drifted while frozen "
                "evaluation was in flight"
            )

    def _action_ball_eval_consume_ready(self) -> None:
        latest = self._action_ball_eval_latest_record()
        if latest is None:
            return
        seq, record = latest
        coordinator = self._action_ball_evaluation_coordinator
        if record["stage"] == "ack_prepared":
            ack_path = coordinator._inbox.ack_path(
                self._action_ball_evaluator_launch["inbox_owner_id"],
                self._action_ball_evaluator_launch["inbox_run_id"],
                seq,
            )
            if ack_path.exists():
                coordinator.reconcile_ack(seq)
            return
        if record["stage"] == "published":
            evidence_path = coordinator._inbox.evidence_path(
                self._action_ball_evaluator_launch["inbox_owner_id"],
                self._action_ball_evaluator_launch["inbox_run_id"],
                seq,
            )
            if not evidence_path.exists():
                return
            result = coordinator.consume_evidence(seq)
        elif record["stage"] == "result_ready":
            result = coordinator.pending_result(seq)
        elif record["stage"] == "curriculum_consumed":
            coordinator.prepare_ack(seq)
            return
        else:
            return
        key = self._action_ball_eval_key_for_request(seq)
        if record["request_kind"] == "scheduler":
            self._action_ball_curriculum.observe_scheduler({key: result})
            self._action_ball_eval_next_kind_by_uid[
                int(key.action_uid)
            ] = "formal"
        else:
            self._action_ball_curriculum.stage_selected({key: result})
            self._action_ball_eval_next_kind_by_uid[
                int(key.action_uid)
            ] = (
                "scheduler"
                if self._action_ball_curriculum.pending_domain_release(
                    key
                )
                is not None
                else "formal"
            )
        coordinator.mark_curriculum_consumed(seq)
        coordinator.prepare_ack(seq)

    def action_ball_frozen_evaluation_boundary(
        self,
        *,
        step: int,
        phase: str,
        checkpoint_path: str = "",
        runner_bindings: object = None,
        consumer_state_sha256: str = "",
    ) -> dict:
        """Runner-only lifecycle for frozen sidecar evidence and publication."""

        if type(step) is not int or step < 0:
            raise ValueError("frozen-eval step must be non-negative int")
        if self._action_ball_diagnostic_unauthorized:
            if phase != "poll":
                raise RuntimeError(
                    "diagnostic action-ball has no frozen-eval authority"
                )
            return {
                "request_seq": 0,
                "request_due": False,
                "needs_global_reset": False,
                "needs_ack_checkpoint": False,
                "diagnostic_unauthorized": True,
            }
        coordinator = self._action_ball_evaluation_coordinator
        if phase == "poll":
            latest = self._action_ball_eval_latest_record()
            if (
                latest is not None
                and latest[1]["stage"] != "acked"
                and runner_bindings is None
            ):
                return {
                    "request_seq": latest[0],
                    "request_due": False,
                    "needs_global_reset": False,
                    "needs_ack_checkpoint": False,
                    "stage": latest[1]["stage"],
                    "requires_runner_binding": True,
                }
            if latest is not None and latest[1]["stage"] != "acked":
                self._action_ball_eval_assert_frozen_runner_binding(
                    latest[0],
                    runner_bindings,
                )
            self._action_ball_eval_consume_ready()
            latest = self._action_ball_eval_latest_record()
            request_seq = 0 if latest is None else latest[0]
            stage = None if latest is None else latest[1]["stage"]
            needs_ack = stage == "ack_prepared"
            needs_reset = any(
                self._action_ball_curriculum.pending_domain_release(key)
                is not None
                for key in self._action_ball_profile_keys
            )
            interval = int(
                self.cfg.action_ball_frozen_eval_interval_updates
            )
            no_inflight = latest is None or stage == "acked"
            due = (
                no_inflight
                and not needs_reset
                and step - self._action_ball_eval_last_request_step
                >= interval
            )
            return {
                "request_seq": (
                    len(coordinator.state_dict()["records"])
                    if due
                    else request_seq
                ),
                "request_due": due,
                "needs_global_reset": needs_reset,
                "needs_ack_checkpoint": needs_ack,
                "stage": stage,
                "requires_runner_binding": False,
            }
        if phase == "commit_global_reset":
            # A band-backed curriculum release is usable only if the exact next
            # domain block already exists.  Validate that while the old domain
            # and every live attempt are still untouched: draining first would
            # irreversibly burn rollout work even though commit must then fail.
            pending_releases = tuple(
                self._action_ball_curriculum.pending_domain_release(key)
                for key in self._action_ball_profile_keys
            )
            bank = self._action_ball_banded_question_bank
            if bank is not None:
                bank.preflight_pending_releases(pending_releases)
            self._action_ball_force_drain_for_release()
            receipt = (
                self._action_ball_curriculum.issue_global_pre_reset_barrier()
            )
            releases = self._action_ball_curriculum.commit_release(
                receipt
            )
            return {
                "request_seq": (
                    0
                    if self._action_ball_eval_latest_record() is None
                    else self._action_ball_eval_latest_record()[0]
                ),
                "global_release_committed": True,
                "release_count": len(releases),
            }
        if phase == "after_global_reset":
            self._action_ball_complete_global_reset()
            latest = self._action_ball_eval_latest_record()
            return {
                "request_seq": 0 if latest is None else latest[0],
                "request_due": False,
                "needs_global_reset": False,
                "needs_ack_checkpoint": (
                    latest is not None
                    and latest[1]["stage"] == "ack_prepared"
                ),
            }
        if phase == "publish_request":
            bindings = self._action_ball_eval_request_binding(
                checkpoint_path=checkpoint_path,
                runner_bindings=runner_bindings,
            )
            raw = Path(checkpoint_path).read_bytes()
            snapshot = self._action_ball_evaluator_authority.freeze_checkpoint(
                raw,
                policy_generation=runner_bindings["policy_generation"],
            )
            keys = self._action_ball_profile_keys
            start = self._action_ball_eval_profile_cursor % len(keys)
            key = keys[start]
            for offset in range(len(keys)):
                candidate = keys[(start + offset) % len(keys)]
                if (
                    self._action_ball_curriculum.pending_domain_release(
                        candidate
                    )
                    is None
                ):
                    key = candidate
                    self._action_ball_eval_profile_cursor = (
                        start + offset + 1
                    ) % len(keys)
                    break
            kind = self._action_ball_eval_next_kind_by_uid[
                int(key.action_uid)
            ]
            domains = ()
            if kind == "scheduler":
                selected = self._action_ball_curriculum.selected_arm(key)
                domains = tuple(
                    domain
                    for domain in self._action_ball_curriculum.scheduler_domains(
                        key
                    )
                    if domain.selected_arm_key == selected
                )
            if len(domains) != 1:
                kind = "formal"
                domain = self._action_ball_curriculum.selected_formal_domain(
                    key
                )
                if domain is None:
                    raise RuntimeError(
                        "action-ball curriculum has no evaluable domain"
                    )
                domains = (domain,)
            domain = domains[0]
            roles = (
                ("scheduler",)
                if kind == "scheduler"
                else ("frozen_canary", "frozen_heldout")
            )
            sessions = tuple(
                self._action_ball_evaluator_authority.open_window(
                    snapshot=snapshot,
                    key=key,
                    evidence_role=role,
                    domain_epoch=domain.domain_epoch,
                    stratum=domain.stratum,
                    selected_arm_key=domain.selected_arm_key,
                    selection_round=domain.selection_round,
                    arm_levels=tuple(domain.arm_levels),
                    rho=domain.rho,
                )
                for role in roles
            )
            seq = coordinator.publish_sessions(
                sessions=sessions,
                bindings=bindings,
            )
            self._action_ball_eval_last_request_step = step
            return {
                "request_seq": seq,
                "request_due": False,
                "published": True,
                "request_kind": kind,
                "action_uid": int(key.action_uid),
            }
        latest = self._action_ball_eval_latest_record()
        if latest is None:
            raise RuntimeError("frozen-eval phase has no request")
        seq, record = latest
        if phase == "consumer_state_sha256":
            if record["stage"] != "ack_prepared":
                raise RuntimeError(
                    "consumer state requested before ACK preparation"
                )
            state = {
                "curriculum": self._action_ball_curriculum.state_dict(),
                "coordinator": coordinator.state_dict(),
                "drain_source": (
                    self._action_ball_drain_reset_source.state_dict()
                ),
                "schedule": {
                    "last_request_step": (
                        self._action_ball_eval_last_request_step
                    ),
                    "profile_cursor": (
                        self._action_ball_eval_profile_cursor
                    ),
                    "next_kind_by_uid": {
                        str(uid): self._action_ball_eval_next_kind_by_uid[
                            int(uid)
                        ]
                        for uid in self._action_ball_bundle.action_uids
                    },
                },
            }
            return {
                "request_seq": seq,
                "consumer_state_sha256": (
                    _action_ball_canonical_sha256(state)
                ),
                "checkpoint_path": checkpoint_path,
            }
        if phase == "publish_ack":
            coordinator.publish_ack(
                seq,
                consumer_state_sha256=consumer_state_sha256,
                consumer_checkpoint=__import__(
                    "whole_body_tracking.tasks.tracking.mdp."
                    "action_ball_evaluation_inbox",
                    fromlist=["artifact_receipt"],
                ).artifact_receipt(checkpoint_path),
            )
            return {
                "request_seq": seq,
                "ack_published": True,
            }
        raise ValueError(f"unknown frozen-eval boundary phase {phase!r}")

    @staticmethod
    def _action_ball_frozen_eval_empty_signals() -> dict:
        return {
            "infrastructure_invalid": False,
            "joint_actual_limit": False,
            "joint_qdes_limit": False,
            "fall": False,
            "table_hit": False,
            "collision": False,
            "legal_return": False,
        }

    def _action_ball_frozen_eval_solve(
        self,
        rows: list[dict],
        *,
        action_slot: int,
    ) -> None:
        """Solve every frozen proposal exactly once and never redraw.

        Results are written back to ``rows`` as either a named physical
        invalid, a named solver/timing rejection, or one immutable
        evaluator-specific task receipt.  Nothing in the training sampler,
        pool, proposal ledger or curriculum is consulted or mutated.
        """

        from whole_body_tracking.tasks.tracking.mdp.action_ball_runtime import (
            ActionBallContractError,
            derive_action_teacher_site_timing,
        )
        from whole_body_tracking.tasks.tracking.mdp.continuous_questions import (
            BALL_BIRTH_NET_MARGIN_M,
            ball_birth_x_lower_bound_m,
            solve_proposals,
        )
        from whole_body_tracking.tasks.tracking.mdp import (
            racket_contact_geometry as contact_geometry,
        )

        if not rows:
            return
        if (
            type(action_slot) is not int
            or not 0 <= action_slot < len(self._action_ball_bindings)
        ):
            raise RuntimeError("frozen evaluator action slot is invalid")
        proposals = [row["proposal"] for row in rows]
        for proposal in proposals:
            proposal.verify()
            if proposal.action_uid != int(
                self._action_ball_bindings[action_slot].action_uid
            ):
                raise RuntimeError(
                    "frozen evaluator proposal changed action identity"
                )
        reason_schema = tuple(
            self._action_ball_solver_contract["payload"]["acceptance"][
                "ordered_rejection_reason_schema"
            ]
        )
        known_reasons = set(reason_schema)
        counter_rally_tasks = [None] * len(rows)
        if self._counter_rally_enabled:
            from whole_body_tracking.tasks.tracking.mdp.counter_rally import (
                precheck_counter_rally_fixed_solver_proposal,
            )

            eligible_rows = []
            eligible_tasks = []
            for row, proposal in zip(rows, proposals):
                sample = proposal.sample
                precheck = (
                    precheck_counter_rally_fixed_solver_proposal(
                        frozen_action_uid=int(proposal.action_uid),
                        solver_action_uid=int(
                            self._action_ball_bindings[
                                action_slot
                            ].action_uid
                        ),
                        expected_objective_profile_sha256=(
                            self._counter_rally_objective.sha256
                        ),
                        base_goal_env_xy_m=(
                            sample.base_goal_w_m[:2]
                        ),
                        base_yaw_env_rad=float(
                            proposal.birth.base_yaw_rad
                        ),
                        contact_offset_b_yaw_m=(
                            sample.contact_offset_from_base_goal_b_yaw_m
                        ),
                        incoming_direction_b_yaw=(
                            sample.incoming_direction_b_yaw[:2]
                        ),
                        incoming_ball_speed_at_contact_mps=float(
                            sample.incoming_speed_mps
                        ),
                        landing_depth_env_x_m=float(
                            sample.landing_aim_w_xy_m[0]
                        ),
                        profile=self._counter_rally_objective,
                    )
                )
                if not precheck.eligible_for_solver:
                    if precheck.rejection_reason not in known_reasons:
                        raise RuntimeError(
                            "frozen counter-rally precheck returned an "
                            "unpinned rejection reason"
                        )
                    row["solver_disposition"] = "rejected"
                    row["reject_reason"] = precheck.rejection_reason
                    row["task_receipt"] = None
                    continue
                task = precheck.task
                if task is None or any(
                    not math.isclose(
                        float(actual),
                        float(expected),
                        rel_tol=0.0,
                        abs_tol=1.0e-12,
                    )
                    for actual, expected in zip(
                        task.landing_aim_env_xy_m,
                        sample.landing_aim_w_xy_m,
                    )
                ):
                    raise RuntimeError(
                        "frozen counter-rally sampler/precheck task drift"
                    )
                eligible_rows.append(row)
                eligible_tasks.append(task)
            rows = eligible_rows
            counter_rally_tasks = eligible_tasks
            proposals = [row["proposal"] for row in rows]
            if not rows:
                return
        surface_z, net_x, net_top_z = self._action_ball_planes
        dtype = self._ref_racket_normal_raw_w_per_clip.dtype
        clip_ids = torch.full(
            (len(rows),),
            action_slot,
            dtype=torch.long,
            device=self.device,
        )
        contact = torch.tensor(
            [proposal.sample.contact_w_m for proposal in proposals],
            dtype=dtype,
            device=self.device,
        )
        incoming = torch.tensor(
            [
                proposal.sample.incoming_velocity_w_mps
                for proposal in proposals
            ],
            dtype=dtype,
            device=self.device,
        )
        spin = torch.tensor(
            [proposal.sample.spin_w_radps for proposal in proposals],
            dtype=dtype,
            device=self.device,
        )
        aim = torch.tensor(
            [
                proposal.sample.landing_aim_w_xy_m
                for proposal in proposals
            ],
            dtype=dtype,
            device=self.device,
        )
        ref_normal = (
            self._ref_racket_normal_raw_w_per_clip.index_select(
                0, clip_ids
            )
        )
        base_quat = torch.tensor(
            [self._action_ball_ready_quat[action_slot]] * len(rows),
            dtype=dtype,
            device=self.device,
        )
        rollout_h = float(self.cfg.vb_rollout_h)
        rollout_steps = int(self.cfg.vb_rollout_steps)
        # The frozen evaluator solves once and never redraws, so overdraw and the
        # redraw-round budget are declared absent here rather than compared.
        action_ball_assert_solver_adapter_binds_these_entry_points(
            adapter=self._action_ball_pool_solver,
            expected={
                "solve": self._action_ball_refill_pool,
                "solve_many": self._action_ball_refill_pool_many,
                "assert_emitted_sample": (
                    self._action_ball_assert_emitted_sample
                ),
                "assert_emitted_tasks": self._action_ball_assert_emitted_tasks,
                "emitted_task_count_for": (
                    self._action_ball_emitted_task_count_for
                ),
                "task_transcript_for_birth": (
                    self._action_ball_task_transcript_for_birth
                ),
                "assert_proposal_assignments": (
                    self._action_ball_assert_proposal_assignments
                ),
            },
            call_site="_action_ball_frozen_eval_solve",
            required=False,
        )
        action_ball_assert_solver_runtime_matches_declaration(
            solver_declaration=self._action_ball_solver_contract["payload"],
            physics_declaration=self._action_ball_physics_contract["payload"],
            answer_input_declaration=(
                self._action_ball_answer_input_contract["payload"]
            ),
            expected_solver_profile_sha256=(
                self._action_ball_manifest.solver_profile_sha256
            ),
            expected_prototype_file_sha256=(
                self._action_ball_manifest.prototype.sha256
            ),
            prototypes=self._action_ball_prototypes,
            reference_normal_rows=self._ref_racket_normal_raw_w_per_clip,
            solver_cfg=self._action_ball_solver_cfg,
            prm=self._action_ball_prm,
            planes=(surface_z, net_x, net_top_z),
            rollout_h=rollout_h,
            rollout_steps=rollout_steps,
            overdraw=None,
            maximum_rounds=None,
            diagnostic_unauthorized=bool(
                getattr(self, "_action_ball_diagnostic_unauthorized", False)
            ),
            call_site="_action_ball_frozen_eval_solve",
        )
        result = solve_proposals(
            clip_ids,
            contact,
            incoming,
            spin,
            aim,
            ref_normal,
            protos=self._action_ball_prototypes,
            base_quat=base_quat,
            prm=self._action_ball_prm,
            surface_z=surface_z,
            net_x=net_x,
            net_top_z=net_top_z,
            cfg=self._action_ball_solver_cfg,
            h=rollout_h,
            n_steps=rollout_steps,
        )
        unknown_reasons = sorted(
            set(result.reason_counts) - known_reasons
        )
        if unknown_reasons:
            raise RuntimeError(
                "frozen evaluator solver returned unpinned reasons "
                f"{unknown_reasons}"
            )
        host_packet = result.proposal_host_packet
        if host_packet is None:
            raise RuntimeError(
                "frozen evaluator solver omitted its immutable host result packet"
            )
        admitted = host_packet.admitted
        reason_codes = host_packet.reason_codes
        racket_velocity_rows = host_packet.racket_velocity_rows
        racket_normal_rows = host_packet.racket_normal_rows
        residual_rows = host_packet.residual_rows
        if (
            len(admitted) != len(rows)
            or len(reason_codes) != len(rows)
            or sum(int(value) for value in result.reason_counts.values())
            + sum(bool(value) for value in admitted)
            != len(rows)
        ):
            raise RuntimeError(
                "frozen evaluator solver result does not conserve proposals"
            )
        profile = self._action_ball_bundle.profiles[action_slot]
        reference_quat = (
            self._action_ball_reference_quat_host_rows[action_slot]
        )
        reference_omega = (
            self._action_ball_reference_omega_host_rows[action_slot]
        )
        for index, row in enumerate(rows):
            proposal = row["proposal"]
            sample = proposal.sample
            counter_rally_task = counter_rally_tasks[index]
            physical_invalid = ball_birth_x_lower_bound_m(
                float(sample.contact_w_m[0]),
                float(sample.incoming_velocity_w_mps[0]),
                float(sample.time_to_contact_s),
            ) < (net_x + BALL_BIRTH_NET_MARGIN_M)
            if physical_invalid:
                row["solver_disposition"] = "physics_invalid"
                row["reject_reason"] = "ball_birth_not_beyond_net"
                row["task_receipt"] = None
                continue
            if not bool(admitted[index]):
                code = reason_codes[index]
                if (
                    type(code) is not int
                    or not 0 <= code < len(reason_schema)
                ):
                    raise RuntimeError(
                        "frozen evaluator solver emitted an invalid "
                        "rejection reason code"
                    )
                row["solver_disposition"] = "rejected"
                row["reject_reason"] = reason_schema[code]
                row["task_receipt"] = None
                continue
            face_velocity = tuple(
                float(value)
                for value in racket_velocity_rows[index]
            )
            raw_normal = tuple(
                float(value)
                for value in racket_normal_rows[index]
            )
            try:
                geometry = contact_geometry.solve_exact_face_contact(
                    ball_contact_w_m=sample.contact_w_m,
                    racket_face_center_velocity_w_mps=face_velocity,
                    solved_raw_a_normal_w=raw_normal,
                    mount_normal_sign=(
                        self._action_ball_mount_signs[action_slot]
                    ),
                    reference_racket_quat_wxyz=reference_quat,
                    reference_racket_angular_velocity_w_radps=(
                        reference_omega
                    ),
                    reference_racket_site_speed_mps=float(
                        profile.reference_racket_site_speed_mps
                    ),
                    teacher_rate_min=float(profile.teacher_rate_min),
                    teacher_rate_max=float(profile.teacher_rate_max),
                )
            except contact_geometry.ExactFaceContactGeometryError as error:
                reason = (
                    "teacher_rate_out_of_bounds"
                    if error.reason == "teacher_rate_out_of_bounds"
                    else error.reason
                )
                if reason not in known_reasons:
                    raise RuntimeError(
                        "frozen exact-face solver returned an unpinned "
                        f"reason {reason!r}"
                    ) from error
                row["solver_disposition"] = "rejected"
                row["reject_reason"] = reason
                row["task_receipt"] = None
                continue
            try:
                timing = derive_action_teacher_site_timing(
                    racket_site_velocity_w_mps=(
                        geometry.racket_site_velocity_w_mps
                    ),
                    time_to_contact_s=float(sample.time_to_contact_s),
                    reference_t_hit_s=float(profile.reference_t_hit_s),
                    reference_t_cycle_s=float(
                        profile.reference_t_cycle_s
                    ),
                    reference_racket_site_speed_mps=float(
                        profile.reference_racket_site_speed_mps
                    ),
                    reaction_margin_s=float(profile.reaction_margin_s),
                    teacher_rate_min=float(profile.teacher_rate_min),
                    teacher_rate_max=float(profile.teacher_rate_max),
                )
            except ActionBallContractError as error:
                raise RuntimeError(
                    "frozen evaluator timing derivation disagrees with "
                    "the admitted exact-face geometry"
                ) from error
            timing_reason = None
            if not (
                float(profile.reaction_margin_s)
                <= timing.pre_swing_wait_s
                <= 1.0
            ):
                timing_reason = "pre_swing_wait_out_of_bounds"
            elif (
                timing.pre_swing_wait_s
                + timing.scaled_t_cycle_s
                + self._action_ball_attempt_close_margin_s
                > self._action_ball_episode_length_s + 1.0e-12
            ):
                timing_reason = "cycle_exceeds_episode_horizon"
            if timing_reason is not None:
                row["solver_disposition"] = "rejected"
                row["reject_reason"] = timing_reason
                row["task_receipt"] = None
                continue

            issued = row["issued_proposal_receipt"]
            task_content = {
                "issued_proposal_receipt_sha256": issued[
                    "receipt_sha256"
                ],
                "sampler_proposal_receipt_sha256": (
                    proposal.proposal_receipt_sha256
                ),
                "proposal_sampler_contract_sha256": (
                    proposal.proposal_sampler_contract_sha256
                ),
                "request_content_sha256": issued["content"][
                    "request_content_sha256"
                ],
                "policy_generation": issued["content"][
                    "policy_generation"
                ],
                "action_uid": int(proposal.action_uid),
                "action_slot": action_slot,
                "profile_sha256": proposal.profile_sha256,
                "motion_sha256": self._action_ball_bindings[
                    action_slot
                ].motion_sha256,
                "domain_epoch": int(proposal.domain_epoch),
                "domain_levels": proposal.domain_levels.as_dict(),
                "evaluation_stratum": proposal.sampling_stratum,
                "selected_arm": proposal.selected_arm,
                "component_strata": {
                    "birth": proposal.birth_component_stratum,
                    "ball_task": (
                        proposal.ball_task_component_stratum
                    ),
                },
                "sampler_birth_receipt": proposal.birth.to_receipt(),
                "sampler_sample_receipt": sample.to_receipt(),
                "solver": {
                    "solver_contract_sha256": (
                        self._action_ball_solver_contract["sha256"]
                    ),
                    "physics_contract_sha256": (
                        self._action_ball_physics_contract["sha256"]
                    ),
                    "solver_residual_m": float(residual_rows[index]),
                    "raw_a_normal_w": list(raw_normal),
                    "face_center_velocity_w_mps": list(face_velocity),
                },
                "task": {
                    "ball_contact_w_m": list(sample.contact_w_m),
                    "racket_site_target_w_m": list(
                        geometry.racket_site_target_w_m
                    ),
                    "racket_site_velocity_w_mps": list(
                        geometry.racket_site_velocity_w_mps
                    ),
                    "racket_face_center_velocity_w_mps": list(
                        geometry.racket_face_center_velocity_w_mps
                    ),
                    "racket_normal_w": list(raw_normal),
                    "racket_command_quat_wxyz": list(
                        geometry.racket_command_quat_wxyz
                    ),
                    "racket_command_angular_velocity_w_radps": list(
                        geometry.racket_command_angular_velocity_w_radps
                    ),
                    "mount_normal_sign": int(
                        geometry.mount_normal_sign
                    ),
                    "base_spawn_w_m": list(
                        proposal.birth.base_start_w_m
                    ),
                    "base_goal_w_m": list(sample.base_goal_w_m),
                    "incoming_velocity_w_mps": list(
                        sample.incoming_velocity_w_mps
                    ),
                    "incoming_spin_w_radps": list(sample.spin_w_radps),
                    "landing_aim_w_xy_m": list(
                        sample.landing_aim_w_xy_m
                    ),
                },
                "teacher": {
                    "contact_time_step_s": float(
                        sample.contact_time_step_s
                    ),
                    "time_to_contact_tick": int(
                        sample.time_to_contact_tick
                    ),
                    "time_to_contact_s": float(
                        sample.time_to_contact_s
                    ),
                    "reference_t_hit_s": float(
                        profile.reference_t_hit_s
                    ),
                    "reference_t_cycle_s": float(
                        profile.reference_t_cycle_s
                    ),
                    "reference_racket_site_speed_mps": float(
                        profile.reference_racket_site_speed_mps
                    ),
                    "required_racket_site_speed_mps": float(
                        timing.required_racket_site_speed_mps
                    ),
                    "reaction_margin_s": float(
                        profile.reaction_margin_s
                    ),
                    "teacher_rate_min": float(
                        profile.teacher_rate_min
                    ),
                    "teacher_rate_max": float(
                        profile.teacher_rate_max
                    ),
                    "teacher_rate": float(timing.teacher_rate),
                    "scaled_t_hit_s": float(timing.scaled_t_hit_s),
                    "scaled_t_cycle_s": float(
                        timing.scaled_t_cycle_s
                    ),
                    "pre_swing_wait_s": float(
                        timing.pre_swing_wait_s
                    ),
                },
            }
            if counter_rally_task is not None:
                task_content["counter_rally"] = {
                    "objective_profile_sha256": (
                        counter_rally_task.objective_profile_sha256
                    ),
                    "venue_physics_sha256": (
                        self._counter_rally_venue_physics.sha256
                    ),
                    "return_direction_env_xy": list(
                        counter_rally_task.return_direction_env_xy
                    ),
                    "target_baseline_speed_mps": float(
                        counter_rally_task.target_baseline_speed_mps
                    ),
                }
            task_receipt = _action_ball_frozen_eval_receipt(
                kind="action_ball_frozen_evaluation_task",
                content=task_content,
            )
            _action_ball_assert_frozen_eval_receipt(
                task_receipt,
                kind="action_ball_frozen_evaluation_task",
                expected_content=task_content,
            )
            row["solver_disposition"] = "admitted"
            row["reject_reason"] = ""
            row["task_receipt"] = task_receipt
            row["task_content"] = task_content

    def _action_ball_frozen_eval_install(
        self,
        rows: list[dict],
        *,
        env_ids: torch.Tensor,
        attempt_tokens: torch.Tensor,
    ) -> None:
        """Atomically replace reset-time training questions by eval receipts."""

        if not rows or len(rows) != len(env_ids):
            raise RuntimeError(
                "frozen evaluator install requires equal non-empty rows/envs"
            )
        if self._action_ball_strike_fact_device_enabled:
            self._action_ball_strike_fact_close_before_task_mutation(
                env_ids, mutation="ActionBall frozen-evaluator replacement"
            )
            raise RuntimeError(
                "frozen evaluator replacement has no full "
                "ActionTaskReceiptRef binding for the same-transition "
                "strike-fact owner"
            )
        if self._physical is None or (
            self._physical.cross_engine_truth_capability
            != "physical_paddle_contact_and_post_contact_flight_v1"
        ):
            raise RuntimeError(
                "formal ActionBall evaluation requires physical "
                "substep paddle/contact/landing truth"
            )
        motion = self._motion()
        action_slot = int(rows[0]["task_content"]["action_slot"])
        action_uid = int(rows[0]["task_content"]["action_uid"])
        if any(
            row["solver_disposition"] != "admitted"
            or int(row["task_content"]["action_slot"]) != action_slot
            or int(row["task_content"]["action_uid"]) != action_uid
            for row in rows
        ):
            raise RuntimeError(
                "frozen evaluator install batch changed action identity"
            )
        counter_rally_identities = None
        if self._counter_rally_enabled:
            from whole_body_tracking.tasks.tracking.mdp.action_ball_runtime import (
                CounterRallyTaskIdentity,
            )

            counter_rally_identities = []
        for index, row in enumerate(rows):
            _action_ball_assert_frozen_eval_receipt(
                row["task_receipt"],
                kind="action_ball_frozen_evaluation_task",
                expected_content=row["task_content"],
            )
            if self._counter_rally_enabled:
                env_id = int(env_ids[index].item())
                identity = (
                    self._counter_rally_task_identity_by_env[
                        env_id
                    ]
                )
                content = row["task_content"].get("counter_rally")
                if (
                    identity is None
                    or not isinstance(content, dict)
                    or identity.objective_profile_sha256
                    != content.get("objective_profile_sha256")
                    or list(identity.return_direction_env_xy)
                    != content.get("return_direction_env_xy")
                    or identity.target_baseline_speed_mps
                    != content.get("target_baseline_speed_mps")
                ):
                    raise RuntimeError(
                        "frozen evaluator counter-rally task identity "
                        "changed after install"
                    )
            proposal = row["proposal"]
            proposal.verify()
            if (
                row["task_content"]["issued_proposal_receipt_sha256"]
                != row["issued_proposal_receipt"][
                    "receipt_sha256"
                ]
                or row["task_content"][
                    "sampler_proposal_receipt_sha256"
                ]
                != proposal.proposal_receipt_sha256
            ):
                raise RuntimeError(
                    "frozen evaluator task detached from proposal receipt"
                )
            if not math.isclose(
                float(proposal.birth.base_start_w_m[2]),
                float(self._action_ball_ready_z[action_slot]),
                rel_tol=0.0,
                abs_tol=1.0e-7,
            ):
                raise RuntimeError(
                    "frozen evaluator base spawn Z differs from ready state"
                )
            counter_content = row["task_content"].get(
                "counter_rally"
            )
            if self._counter_rally_enabled:
                if (
                    not isinstance(counter_content, dict)
                    or set(counter_content)
                    != {
                        "objective_profile_sha256",
                        "venue_physics_sha256",
                        "return_direction_env_xy",
                        "target_baseline_speed_mps",
                    }
                    or counter_content["venue_physics_sha256"]
                    != self._counter_rally_venue_physics.sha256
                ):
                    raise RuntimeError(
                        "frozen evaluator counter-rally identity is "
                        "missing or drifted"
                    )
                identity = CounterRallyTaskIdentity(
                    objective_profile_sha256=counter_content[
                        "objective_profile_sha256"
                    ],
                    return_direction_env_xy=counter_content[
                        "return_direction_env_xy"
                    ],
                    target_baseline_speed_mps=counter_content[
                        "target_baseline_speed_mps"
                    ],
                )
                if (
                    identity.objective_profile_sha256
                    != self._counter_rally_objective.sha256
                ):
                    raise RuntimeError(
                        "frozen evaluator counter-rally objective "
                        "profile drifted"
                    )
                counter_rally_identities.append(identity)
            elif counter_content is not None:
                raise RuntimeError(
                    "ordinary frozen evaluator task cannot carry "
                    "counter-rally identity"
                )

        dtype = self.racket_target_pos_w.dtype
        origins = self._env.scene.env_origins[env_ids]
        task_rows = [row["task_content"]["task"] for row in rows]
        teacher_rows = [
            row["task_content"]["teacher"] for row in rows
        ]
        site_target = torch.tensor(
            [task["racket_site_target_w_m"] for task in task_rows],
            dtype=dtype,
            device=self.device,
        )
        site_velocity = torch.tensor(
            [
                task["racket_site_velocity_w_mps"]
                for task in task_rows
            ],
            dtype=dtype,
            device=self.device,
        )
        face_velocity = torch.tensor(
            [
                task["racket_face_center_velocity_w_mps"]
                for task in task_rows
            ],
            dtype=dtype,
            device=self.device,
        )
        normal = torch.tensor(
            [task["racket_normal_w"] for task in task_rows],
            dtype=dtype,
            device=self.device,
        )
        command_quat = torch.tensor(
            [
                task["racket_command_quat_wxyz"]
                for task in task_rows
            ],
            dtype=dtype,
            device=self.device,
        )
        ball_contact = torch.tensor(
            [task["ball_contact_w_m"] for task in task_rows],
            dtype=dtype,
            device=self.device,
        )
        base_spawn = torch.tensor(
            [task["base_spawn_w_m"] for task in task_rows],
            dtype=dtype,
            device=self.device,
        )
        base_goal = torch.tensor(
            [task["base_goal_w_m"] for task in task_rows],
            dtype=dtype,
            device=self.device,
        )
        incoming = torch.tensor(
            [task["incoming_velocity_w_mps"] for task in task_rows],
            dtype=dtype,
            device=self.device,
        )
        spin = torch.tensor(
            [task["incoming_spin_w_radps"] for task in task_rows],
            dtype=dtype,
            device=self.device,
        )
        aim = torch.tensor(
            [task["landing_aim_w_xy_m"] for task in task_rows],
            dtype=dtype,
            device=self.device,
        )
        counter_rally_direction = None
        counter_rally_target_speed = None
        if counter_rally_identities is not None:
            counter_rally_direction = torch.tensor(
                [
                    identity.return_direction_env_xy
                    for identity in counter_rally_identities
                ],
                dtype=dtype,
                device=self.device,
            )
            counter_rally_target_speed = torch.tensor(
                [
                    identity.target_baseline_speed_mps
                    for identity in counter_rally_identities
                ],
                dtype=dtype,
                device=self.device,
            )
        finite_tensors = (
            site_target,
            site_velocity,
            face_velocity,
            normal,
            command_quat,
            ball_contact,
            base_spawn,
            base_goal,
            incoming,
            spin,
            aim,
            *(
                ()
                if counter_rally_direction is None
                else (
                    counter_rally_direction,
                    counter_rally_target_speed,
                )
            ),
        )
        if any(
            not bool(torch.isfinite(value).all())
            for value in finite_tensors
        ):
            raise RuntimeError(
                "frozen evaluator task materialized a non-finite tensor"
            )
        if (
            not bool(
                torch.allclose(
                    torch.linalg.vector_norm(normal, dim=-1),
                    torch.ones(
                        len(rows), dtype=dtype, device=self.device
                    ),
                    rtol=0.0,
                    atol=1.0e-6,
                )
            )
            or not bool(
                torch.allclose(
                    torch.linalg.vector_norm(command_quat, dim=-1),
                    torch.ones(
                        len(rows), dtype=dtype, device=self.device
                    ),
                    rtol=0.0,
                    atol=1.0e-6,
                )
            )
        ):
            raise RuntimeError(
                "frozen evaluator task normal/quaternion is not unit"
            )
        ready_quat = torch.tensor(
            [self._action_ball_ready_quat[action_slot]] * len(rows),
            dtype=dtype,
            device=self.device,
        )
        slots = torch.full(
            (len(rows),),
            action_slot,
            dtype=torch.long,
            device=self.device,
        )
        uids = torch.full(
            (len(rows),),
            action_uid,
            dtype=torch.long,
            device=self.device,
        )
        ttc = torch.tensor(
            [teacher["time_to_contact_s"] for teacher in teacher_rows],
            dtype=torch.float64,
            device=self.device,
        )
        teacher_rate = torch.tensor(
            [teacher["teacher_rate"] for teacher in teacher_rows],
            dtype=torch.float64,
            device=self.device,
        )
        scaled_hit = torch.tensor(
            [teacher["scaled_t_hit_s"] for teacher in teacher_rows],
            dtype=torch.float64,
            device=self.device,
        )
        scaled_cycle = torch.tensor(
            [teacher["scaled_t_cycle_s"] for teacher in teacher_rows],
            dtype=torch.float64,
            device=self.device,
        )
        prewait = torch.tensor(
            [teacher["pre_swing_wait_s"] for teacher in teacher_rows],
            dtype=torch.float64,
            device=self.device,
        )

        # All receipt and tensor checks above precede the first live write.
        motion.clip_id[env_ids] = slots
        motion._write_canonical_ready_state(
            env_ids,
            action_ball_base_spawn_w_m=base_spawn,
            action_ball_base_quat_wxyz=ready_quat,
        )
        starts = motion.motion.seg_start[slots]
        motion.time_steps[env_ids] = starts
        motion.time_steps_f[env_ids] = starts.to(
            motion.time_steps_f.dtype
        )
        motion.speed_scale[env_ids] = 0.0
        motion.hold_counter[env_ids] = 1
        motion._action_ball_task_timing_active[env_ids] = True
        motion._action_ball_task_pending_elapsed_s[env_ids] = 0.0
        motion._action_ball_task_age_s[env_ids] = 0.0
        motion._action_ball_time_to_contact_s[env_ids] = ttc
        motion._action_ball_teacher_rate[env_ids] = teacher_rate
        motion._action_ball_scaled_t_hit_s[env_ids] = scaled_hit
        motion._action_ball_scaled_t_cycle_s[env_ids] = scaled_cycle
        motion._action_ball_pre_swing_wait_s[env_ids] = prewait
        if hasattr(motion, "_planner_active"):
            motion._planner_active[env_ids] = False

        self.racket_target_pos_w[env_ids] = origins + site_target
        self.racket_target_vel_w[env_ids] = site_velocity
        self.racket_target_normal_w[env_ids] = normal
        self.target_normal_cmd[env_ids] = normal
        self._action_ball_ball_contact_target_w[env_ids] = (
            origins + ball_contact
        )
        self._action_ball_face_center_velocity_target_w[
            env_ids
        ] = face_velocity
        self._action_ball_racket_command_quat_w[
            env_ids
        ] = command_quat
        self.base_target_pos_w[env_ids] = (
            origins[:, :2] + base_goal[:, :2]
        )
        self.station_anchor_pos_w[env_ids] = (
            origins[:, :2] + base_spawn[:, :2]
        )
        self.vb_vel_in_w[env_ids] = incoming
        self.vb_spin_in_w[env_ids] = spin
        self._vb_target_xy_per_env[env_ids] = aim
        if counter_rally_direction is not None:
            self._counter_rally_return_direction_env_xy[
                env_ids
            ] = counter_rally_direction
            self._counter_rally_target_baseline_speed_mps[
                env_ids
            ] = counter_rally_target_speed
        self._counter_rally_reward_terms[env_ids] = 0.0
        self._counter_rally_accepted[env_ids] = False
        self._counter_rally_legal_first_landing[env_ids] = False
        self._counter_rally_primary_reason_code[env_ids] = -1
        self._action_ball_action_slot[env_ids] = slots
        self._action_ball_action_uid[env_ids] = uids
        self._action_ball_attempt_action[env_ids] = slots
        self._action_ball_attempt_active[env_ids] = True
        self._action_ball_attempt_legal[env_ids] = False
        self._action_ball_attempt_hit[env_ids] = False
        for index, env_id in enumerate(
            env_ids.detach().cpu().tolist()
        ):
            self._counter_rally_task_identity_by_env[int(env_id)] = (
                None
                if counter_rally_identities is None
                else counter_rally_identities[index]
            )
        self._action_ball_invalidate_virtual_contact_history(env_ids)
        self._action_ball_reference_term_center_latch[
            env_ids
        ] = False
        self.time_to_strike[env_ids] = ttc.to(
            self.time_to_strike.dtype
        )
        self.pre_strike[env_ids] = True
        tts_abs = self.time_to_strike[env_ids].abs()
        self.strike_window[env_ids] = (
            tts_abs <= float(self.cfg.strike_window_s)
        )
        self.strike_window_pos[env_ids] = (
            self.strike_window[env_ids]
            if self.cfg.strike_window_pos_s is None
            else tts_abs <= float(self.cfg.strike_window_pos_s)
        )
        self.strike_window_wide[env_ids] = (
            self.strike_window[env_ids]
            if self.cfg.strike_window_wide_s is None
            else tts_abs <= float(self.cfg.strike_window_wide_s)
        )
        if motion._multiseg:
            family_forehand = self._clip_family_is_forehand()[slots]
            self.swing_sign[env_ids] = torch.where(
                family_forehand,
                torch.ones(
                    len(rows), dtype=dtype, device=self.device
                ),
                -torch.ones(
                    len(rows), dtype=dtype, device=self.device
                ),
            )
        self._prev_motion_steps[env_ids] = motion.time_steps[env_ids]
        if hasattr(self, "time_left"):
            # This task is evaluator-owned for the complete attempt.  Disable
            # the generic command-manager resample clock so it cannot replace
            # the frozen ball/task receipt before physical closure.
            self.time_left[env_ids] = float("inf")
        self._exact_fired[env_ids] = False
        self.racket_progress[env_ids] = 0.0
        self._progress_reset_mask[env_ids] = True
        if self.planner_revision_enabled:
            self._planner_visible_pos[env_ids] = (
                self.racket_target_pos_w[env_ids]
            )
            self._planner_visible_vel[env_ids] = (
                self.racket_target_vel_w[env_ids]
            )
            self._planner_visible_normal[env_ids] = normal
            self._planner_visible_tts[env_ids] = self.time_to_strike[
                env_ids
            ]
            self._planner_visible_last_precontact[env_ids] = False
        if self._shadow is not None:
            self._shadow.on_resample(env_ids)
        self._physical.on_resample(env_ids)
        self._physical.begin_external_exam_attempt(
            env_ids, attempt_tokens
        )

    def _action_ball_frozen_eval_refresh_motion_reference(
        self, env_ids: torch.Tensor
    ) -> None:
        """Refresh installed clip FK caches without advancing its clock."""

        motion = self._motion()
        body_count = len(motion.cfg.body_names)
        anchor_pos = motion.anchor_pos_w[env_ids, None, :].repeat(
            1, body_count, 1
        )
        anchor_quat = motion.anchor_quat_w[env_ids, None, :].repeat(
            1, body_count, 1
        )
        robot_anchor_pos = motion.robot_anchor_pos_w[
            env_ids, None, :
        ].repeat(1, body_count, 1)
        robot_anchor_quat = motion.robot_anchor_quat_w[
            env_ids, None, :
        ].repeat(1, body_count, 1)
        delta_pos = robot_anchor_pos
        delta_pos[..., 2] = anchor_pos[..., 2]
        delta_quat = yaw_quat(
            quat_mul(robot_anchor_quat, quat_inv(anchor_quat))
        )
        body_quat = quat_mul(
            delta_quat, motion.body_quat_w[env_ids]
        )
        body_pos = delta_pos + quat_apply(
            delta_quat,
            motion.body_pos_w[env_ids] - anchor_pos,
        )
        if not bool(
            torch.isfinite(body_quat).all()
            and torch.isfinite(body_pos).all()
        ):
            raise RuntimeError(
                "frozen evaluator installed non-finite motion reference"
            )
        motion.body_quat_relative_w[env_ids] = body_quat
        motion.body_pos_relative_w[env_ids] = body_pos

    def _action_ball_frozen_eval_assert_live_identity(
        self,
        rows: list[dict],
        *,
        env_ids: torch.Tensor,
    ) -> None:
        motion = self._motion()
        expected_slot = torch.tensor(
            [
                int(row["task_content"]["action_slot"])
                for row in rows
            ],
            dtype=torch.long,
            device=self.device,
        )
        expected_uid = torch.tensor(
            [
                int(row["task_content"]["action_uid"])
                for row in rows
            ],
            dtype=torch.long,
            device=self.device,
        )
        if (
            not torch.equal(motion.clip_id[env_ids], expected_slot)
            or not torch.equal(
                self._action_ball_action_slot[env_ids], expected_slot
            )
            or not torch.equal(
                self._action_ball_action_uid[env_ids], expected_uid
            )
        ):
            raise RuntimeError(
                "frozen evaluator action identity changed after install"
            )
        for row in rows:
            _action_ball_assert_frozen_eval_receipt(
                row["task_receipt"],
                kind="action_ball_frozen_evaluation_task",
                expected_content=row["task_content"],
            )

    def _action_ball_frozen_eval_raw_signals(
        self, env_ids: torch.Tensor
    ) -> tuple[list[dict], torch.Tensor]:
        (
            table,
            fall,
            collision,
            joint_qdes,
            joint_actual,
            terminal_or_timeout,
        ) = self._action_ball_reset_outcome_masks(env_ids)
        result = []
        for index in range(len(env_ids)):
            result.append(
                {
                    "infrastructure_invalid": False,
                    "joint_actual_limit": bool(
                        joint_actual[index].item()
                    ),
                    "joint_qdes_limit": bool(
                        joint_qdes[index].item()
                    ),
                    "fall": bool(fall[index].item()),
                    "table_hit": bool(table[index].item()),
                    "collision": bool(collision[index].item()),
                    "legal_return": False,
                }
            )
        return result, terminal_or_timeout

    # The independent sidecar discovers this exact public seam before it emits
    # READY.  The implementation above uses a stateless proposal sampler and a
    # dedicated eval receipt root; training's redraw pool is never evidence.
    ACTION_BALL_FROZEN_EVALUATOR_RUNTIME_V1_READY = True

    def action_ball_frozen_evaluator_execute_v1(
        self,
        *,
        request_document: object,
        vector_env: object,
        runner: object,
        deterministic_policy,
        expected_task_id: str,
        expected_policy_generation: int,
        expected_proposal_sampler_contract_sha256: str,
        progress_callback=None,
        request_deadline_monotonic_ns: int = 0,
    ) -> dict:
        """Evaluate one request with fixed action, no redraw and raw physics."""

        import time

        from whole_body_tracking.tasks.tracking.mdp import (
            action_ball_evaluation_inbox as inbox_protocol,
        )
        from whole_body_tracking.tasks.tracking.mdp.action_ball_sampling import (
            ARM_KEYS,
            FROZEN_EVALUATION_PROPOSAL_SAMPLER_CONTRACT_SHA256,
            DomainLevels,
            SamplingMixture,
            sample_frozen_evaluation_proposal,
        )

        if expected_task_id != "HOPE-PingPong-ActionBall-AgibotA3-v0":
            raise RuntimeError(
                "formal evaluator requested another Gym task"
            )
        if (
            type(expected_policy_generation) is not int
            or expected_policy_generation < 0
        ):
            raise RuntimeError(
                "formal evaluator policy generation is invalid"
            )
        if (
            type(request_deadline_monotonic_ns) is not int
            or request_deadline_monotonic_ns < 0
        ):
            raise RuntimeError(
                "formal evaluator monotonic deadline is invalid"
            )

        def _deadline() -> None:
            if (
                request_deadline_monotonic_ns
                and time.monotonic_ns()
                > request_deadline_monotonic_ns
            ):
                raise TimeoutError(
                    "formal ActionBall request exceeded its monotonic "
                    "deadline"
                )

        _deadline()
        request = inbox_protocol.validate_request_document(
            request_document
        )
        bindings = request["bindings"]
        target = request["target"]
        if (
            bindings["policy_generation"]
            != expected_policy_generation
        ):
            raise RuntimeError(
                "formal evaluator request policy generation drifted"
            )
        live_proposal_contract = (
            FROZEN_EVALUATION_PROPOSAL_SAMPLER_CONTRACT_SHA256
        )
        if (
            bindings["proposal_sampler_contract_sha256"]
            != live_proposal_contract
            or expected_proposal_sampler_contract_sha256
            != live_proposal_contract
        ):
            raise RuntimeError(
                "formal evaluator proposal sampler contract is not the "
                "live code-pinned contract"
            )
        expected_order = [
            int(uid) for uid in self._action_ball_bundle.action_uids
        ]
        if (
            bindings["action_order"] != expected_order
            or bindings["manifest_sha256"]
            != self._action_ball_loaded_manifest.file_sha256
            or bindings["sampler_sha256"]
            != self._action_ball_sampler.sampler_contract_sha256
            or bindings["solver_sha256"]
            != self._action_ball_solver_contract["sha256"]
            or bindings["physics_sha256"]
            != self._action_ball_physics_contract["sha256"]
            or bindings["curriculum_sha256"]
            != self._action_ball_bundle.contract_sha256
            or target["mobility_mode"]
            != self._action_ball_manifest.mobility_mode
        ):
            raise RuntimeError(
                "formal evaluator request differs from constructed "
                "ActionBall runtime"
            )
        action_uid = int(target["action_uid"])
        slots = [
            index
            for index, uid in enumerate(expected_order)
            if uid == action_uid
        ]
        if len(slots) != 1:
            raise RuntimeError(
                "formal evaluator target action is not uniquely bound"
            )
        action_slot = slots[0]
        profile = self._action_ball_bundle.profiles[action_slot]
        binding = self._action_ball_bindings[action_slot]
        if (
            target["profile_sha256"] != profile.sha256
            or binding.profile_sha256 != profile.sha256
            or bindings["actions"][action_slot]["motion"]["sha256"]
            != binding.motion_sha256
        ):
            raise RuntimeError(
                "formal evaluator target profile/motion binding drifted"
            )
        if (
            type(target["arm_levels"]) is not list
            or len(target["arm_levels"]) != len(ARM_KEYS)
        ):
            raise RuntimeError(
                "formal evaluator target does not contain 32 arm levels"
            )
        levels = DomainLevels(
            **{
                arm: float(value)
                for arm, value in zip(ARM_KEYS, target["arm_levels"])
            }
        )
        selected_arm = str(target["selected_arm_key"])
        if selected_arm and selected_arm not in ARM_KEYS:
            raise RuntimeError(
                "formal evaluator selected arm is outside the catalog"
            )
        policy_dt_s = float(self._env.step_dt)
        if not math.isclose(
            policy_dt_s,
            float(self._action_ball_attempt_close_margin_s),
            rel_tol=0.0,
            abs_tol=1.0e-12,
        ):
            raise RuntimeError(
                "formal evaluator policy tick differs from task receipts"
            )
        if (
            getattr(vector_env, "unwrapped", self._env) is not self._env
            or not callable(deterministic_policy)
        ):
            raise RuntimeError(
                "formal evaluator received another vector environment or "
                "no deterministic policy"
            )
        vector_count = int(
            getattr(vector_env, "num_envs", self.num_envs)
        )
        if vector_count != self.num_envs or vector_count <= 0:
            raise RuntimeError(
                "formal evaluator changed saved environment cardinality"
            )
        if not isinstance(request_document, dict):
            raise RuntimeError(
                "formal evaluator request envelope is not a mapping"
            )
        request_content_sha256 = request_document.get("content_sha256")
        if (
            type(request_content_sha256) is not str
            or len(request_content_sha256) != 64
            or any(
                character not in "0123456789abcdef"
                for character in request_content_sha256
            )
        ):
            raise RuntimeError(
                "formal evaluator request has no canonical content SHA"
            )

        mixture = SamplingMixture()
        all_rows: list[dict] = []
        role_rows: dict[str, list[dict]] = {}
        global_index = 0
        for window in request["windows"]:
            role = str(window["role"])
            role_rows[role] = []
            for offset in range(int(window["proposal_count"])):
                seed = int(window["seed_start"]) + offset
                sample_index = int(window["sample_start"]) + offset
                birth_index = int(window["birth_start"]) + offset
                stratum = mixture.stratum_for(sample_index)
                if mixture.stratum_for(birth_index) != stratum:
                    raise RuntimeError(
                        "formal evaluator birth/sample allocations have "
                        "different quota strata"
                    )
                if stratum == "frontier" and not selected_arm:
                    raise RuntimeError(
                        "formal frontier allocation has no selected arm"
                    )
                proposal = sample_frozen_evaluation_proposal(
                    profile,
                    evaluation_seed=seed,
                    external_sample_index=sample_index,
                    external_birth_index=birth_index,
                    domain_epoch=int(target["domain_epoch"]),
                    domain_levels=levels,
                    rho=float(target["rho"]),
                    sampling_stratum=stratum,
                    selected_arm=(
                        selected_arm
                        if stratum == "frontier"
                        else None
                    ),
                    base_yaw_rad=float(
                        self._action_ball_ready_yaw[action_slot]
                    ),
                    policy_dt_s=policy_dt_s,
                    initial_center_single_question=(
                        self.cfg.action_ball_initial_center_single_question
                    ),
                )
                issued_content = {
                    "request_content_sha256": request_content_sha256,
                    "policy_generation": expected_policy_generation,
                    "role": role,
                    "proposal_offset": offset,
                    "global_proposal_index": global_index,
                    "evaluation_seed": seed,
                    "external_sample_index": sample_index,
                    "external_birth_index": birth_index,
                    "action_uid": action_uid,
                    "evaluation_stratum": stratum,
                    "selected_arm": proposal.selected_arm,
                    "sampler_proposal_receipt_sha256": (
                        proposal.proposal_receipt_sha256
                    ),
                    "proposal_sampler_contract_sha256": (
                        proposal.proposal_sampler_contract_sha256
                    ),
                }
                issued = _action_ball_frozen_eval_receipt(
                    kind=(
                        "action_ball_frozen_evaluation_issued_proposal"
                    ),
                    content=issued_content,
                )
                _action_ball_assert_frozen_eval_receipt(
                    issued,
                    kind=(
                        "action_ball_frozen_evaluation_issued_proposal"
                    ),
                    expected_content=issued_content,
                )
                row = {
                    "role": role,
                    "proposal_offset": offset,
                    "global_proposal_index": global_index,
                    "proposal": proposal,
                    "issued_proposal_receipt": issued,
                }
                all_rows.append(row)
                role_rows[role].append(row)
                global_index += 1
        total = len(all_rows)
        expected_total = sum(
            int(window["proposal_count"])
            for window in request["windows"]
        )
        if total != expected_total:
            raise RuntimeError(
                "formal evaluator proposal allocation did not conserve"
            )
        self._action_ball_frozen_eval_solve(
            all_rows, action_slot=action_slot
        )

        for row in all_rows:
            proposal = row["proposal"]
            row["attempt"] = {
                "proposal_offset": int(row["proposal_offset"]),
                "seed": int(proposal.evaluation_seed),
                "sample_id": int(proposal.external_sample_index),
                "birth_id": int(proposal.external_birth_index),
                "proposal_sampler_contract_sha256": (
                    proposal.proposal_sampler_contract_sha256
                ),
                "proposal_receipt_sha256": row[
                    "issued_proposal_receipt"
                ]["receipt_sha256"],
                "sample_receipt_sha256": proposal.sample.sample_id,
                "birth_receipt_sha256": proposal.birth.birth_id,
                "sampling_stratum": proposal.sampling_stratum,
                "frontier_arm": (
                    "" if proposal.selected_arm is None
                    else proposal.selected_arm
                ),
                "solver_disposition": row["solver_disposition"],
                "reject_reason": row["reject_reason"],
                "task_receipt_sha256": (
                    ""
                    if row["task_receipt"] is None
                    else row["task_receipt"]["receipt_sha256"]
                ),
                "installed": False,
                "started": False,
                "closed": False,
                "terminal_signals": (
                    self._action_ball_frozen_eval_empty_signals()
                ),
            }
        admitted_rows = [
            row
            for row in all_rows
            if row["solver_disposition"] == "admitted"
        ]
        completed = total - len(admitted_rows)
        if progress_callback is not None:
            progress_callback(completed, total)
        _deadline()

        for start in range(0, len(admitted_rows), self.num_envs):
            _deadline()
            batch = admitted_rows[start : start + self.num_envs]
            reset_result = vector_env.reset()
            del reset_result
            env_ids = torch.arange(
                len(batch), dtype=torch.long, device=self.device
            )
            tokens = torch.tensor(
                [
                    int(row["global_proposal_index"])
                    for row in batch
                ],
                dtype=torch.long,
                device=self.device,
            )
            self._action_ball_frozen_eval_install(
                batch, env_ids=env_ids, attempt_tokens=tokens
            )
            for row in batch:
                row["attempt"]["installed"] = True
            self._action_ball_frozen_eval_assert_live_identity(
                batch, env_ids=env_ids
            )
            # Refresh the simulator-backed state and then ask the wrapper for
            # the actor view; no zero-action policy step is inserted.
            sim = getattr(self._env, "sim", None)
            if sim is not None and callable(getattr(sim, "forward", None)):
                sim.forward()
            scene = getattr(self._env, "scene", None)
            if scene is not None and callable(
                getattr(scene, "update", None)
            ):
                scene.update(0.0)
            self._action_ball_frozen_eval_refresh_motion_reference(
                env_ids
            )
            self._compute_racket_state()
            self._compute_strike_timing()
            self._prev_racket_dist[env_ids] = torch.norm(
                self.racket_pos_w[env_ids]
                - self.racket_target_pos_w[env_ids],
                dim=-1,
            ).detach()
            self._reset_actor_target_state(env_ids)
            get_observations = getattr(
                vector_env, "get_observations", None
            )
            if not callable(get_observations):
                raise RuntimeError(
                    "formal evaluator vector environment has no "
                    "observation seam"
                )
            observations = get_observations()
            if isinstance(observations, tuple):
                observations = observations[0]

            actor_critic = getattr(
                getattr(runner, "alg", None), "actor_critic", None
            )
            if bool(getattr(actor_critic, "is_recurrent", False)):
                reset_memory = getattr(actor_critic, "reset", None)
                if not callable(reset_memory):
                    raise RuntimeError(
                        "recurrent formal policy has no per-birth reset"
                    )
                reset_memory(
                    torch.ones(
                        self.num_envs,
                        dtype=torch.bool,
                        device=self.device,
                    )
                )

            sticky = [
                self._action_ball_frozen_eval_empty_signals()
                for _ in batch
            ]
            active = [True] * len(batch)
            dt = float(self._env.step_dt)
            budgets = [
                max(
                    1,
                    int(
                        math.ceil(
                            (
                                row["task_content"]["teacher"][
                                    "pre_swing_wait_s"
                                ]
                                + row["task_content"]["teacher"][
                                    "scaled_t_cycle_s"
                                ]
                                + self._action_ball_attempt_close_margin_s
                            )
                            / dt
                            - 1.0e-9
                        )
                    ),
                )
                for row in batch
            ]
            for step_index in range(max(budgets)):
                live_indices = [
                    index
                    for index, value in enumerate(active)
                    if value
                ]
                if not live_indices:
                    break
                live_ids = env_ids[
                    torch.tensor(
                        live_indices,
                        dtype=torch.long,
                        device=self.device,
                    )
                ]
                self._action_ball_frozen_eval_assert_live_identity(
                    [batch[index] for index in live_indices],
                    env_ids=live_ids,
                )
                actions = deterministic_policy(observations)
                step_result = vector_env.step(actions)
                if (
                    not isinstance(step_result, tuple)
                    or len(step_result) not in (4, 5)
                ):
                    raise RuntimeError(
                        "formal evaluator vector step has an unknown API"
                    )
                observations = step_result[0]
                raw_signals, terminal_or_timeout = (
                    self._action_ball_frozen_eval_raw_signals(env_ids)
                )
                for index, row in enumerate(batch):
                    if not active[index]:
                        continue
                    row["attempt"]["started"] = True
                    for name in (
                        "joint_actual_limit",
                        "joint_qdes_limit",
                        "fall",
                        "table_hit",
                        "collision",
                    ):
                        sticky[index][name] = (
                            sticky[index][name]
                            or raw_signals[index][name]
                        )
                    unsafe = any(
                        sticky[index][name]
                        for name in (
                            "joint_actual_limit",
                            "joint_qdes_limit",
                            "fall",
                            "table_hit",
                            "collision",
                        )
                    )
                    truth = self._physical.cross_engine_physical_truth(
                        int(env_ids[index].item()),
                        expected_attempt_token=int(tokens[index].item()),
                        final=True,
                    )
                    available = bool(truth.get("available", False))
                    if available:
                        physical_returned = bool(
                            truth.get("returned", False)
                        )
                        if self._counter_rally_enabled:
                            objective_accepted = bool(
                                self._action_ball_attempt_legal[
                                    env_ids[index]
                                ].item()
                            )
                            sticky[index]["legal_return"] = (
                                physical_returned
                                and objective_accepted
                            )
                        else:
                            sticky[index]["legal_return"] = (
                                physical_returned
                            )
                    if unsafe:
                        row["attempt"]["closed"] = True
                        row["attempt"]["terminal_signals"] = dict(
                            sticky[index]
                        )
                        active[index] = False
                    elif available:
                        self._action_ball_frozen_eval_assert_live_identity(
                            [row],
                            env_ids=env_ids[index : index + 1],
                        )
                        row["attempt"]["closed"] = True
                        row["attempt"]["terminal_signals"] = dict(
                            sticky[index]
                        )
                        active[index] = False
                    elif bool(terminal_or_timeout[index].item()):
                        sticky[index] = (
                            self._action_ball_frozen_eval_empty_signals()
                        )
                        sticky[index]["infrastructure_invalid"] = True
                        row["attempt"]["terminal_signals"] = dict(
                            sticky[index]
                        )
                        active[index] = False
                    elif step_index + 1 >= budgets[index]:
                        sticky[index] = (
                            self._action_ball_frozen_eval_empty_signals()
                        )
                        sticky[index]["infrastructure_invalid"] = True
                        row["attempt"]["terminal_signals"] = dict(
                            sticky[index]
                        )
                        active[index] = False
                _deadline()
            for index, row in enumerate(batch):
                if active[index]:
                    signals = (
                        self._action_ball_frozen_eval_empty_signals()
                    )
                    signals["infrastructure_invalid"] = True
                    row["attempt"]["terminal_signals"] = signals
                    active[index] = False
                # Closure-time receipt/action recheck is independent of an
                # Isaac auto-reset that may already have replaced live state.
                _action_ball_assert_frozen_eval_receipt(
                    row["task_receipt"],
                    kind="action_ball_frozen_evaluation_task",
                    expected_content=row["task_content"],
                )
                if (
                    row["task_content"]["action_uid"] != action_uid
                    or row["task_content"]["policy_generation"]
                    != expected_policy_generation
                ):
                    raise RuntimeError(
                        "frozen evaluator action/generation drifted at "
                        "attempt close"
                    )
            # Reuse is allowed only after the held truth has been consumed.
            self._physical._truth_exam_active[env_ids] = False
            completed += len(batch)
            if progress_callback is not None:
                progress_callback(completed, total)
            _deadline()
        if completed != total:
            raise RuntimeError(
                "formal evaluator did not account for every proposal"
            )
        return {
            role: [row["attempt"] for row in rows]
            for role, rows in role_rows.items()
        }

    @staticmethod
    def _action_ball_parse_sampler_birth(value):
        """Reconstruct and structurally validate one dependency-light sampler birth."""

        from whole_body_tracking.tasks.tracking.mdp.action_ball_sampling import (
            BaseBirthReceipt,
            SCHEMA_VERSION,
        )

        expected = {
            "schema_version",
            "birth_id",
            "sampler_contract_sha256",
            "arm_catalog_sha256",
            "action_uid",
            "domain_epoch",
            "domain_levels",
            "profile_sha256",
            "levels_sha256",
            "birth_index",
            "draw_range",
            "mobility_mode",
            "base_yaw_rad",
            "base_start_w_m",
        }
        has_sampling = isinstance(value, dict) and "sampling" in value
        if has_sampling:
            expected.add("sampling")
        if not isinstance(value, dict) or set(value) != expected:
            raise ValueError("action-ball sampler birth receipt has invalid keys")
        if type(value["schema_version"]) is not int or value["schema_version"] != SCHEMA_VERSION:
            raise ValueError("action-ball sampler birth schema_version mismatch")
        draw = value["draw_range"]
        if not isinstance(draw, dict) or set(draw) != {
            "action_tape",
            "start_inclusive",
            "end_exclusive",
        }:
            raise ValueError("action-ball sampler birth draw_range has invalid keys")
        for name in (
            "action_uid",
            "domain_epoch",
            "birth_index",
        ):
            if type(value[name]) is not int or value[name] < 0:
                raise ValueError(f"action-ball sampler birth {name} is invalid")
        for name in ("action_tape", "start_inclusive", "end_exclusive"):
            if type(draw[name]) is not int or draw[name] < 0:
                raise ValueError(
                    f"action-ball sampler birth draw_range.{name} is invalid"
                )
        if draw["action_tape"] != value["action_uid"]:
            raise ValueError("action-ball sampler birth draw tape/action UID mismatch")
        identity = {
            "birth_id": value["birth_id"],
            "sampler_contract_sha256": value[
                "sampler_contract_sha256"
            ],
            "arm_catalog_sha256": value["arm_catalog_sha256"],
            "action_uid": value["action_uid"],
            "domain_epoch": value["domain_epoch"],
            "domain_levels": value["domain_levels"],
            "profile_sha256": value["profile_sha256"],
            "levels_sha256": value["levels_sha256"],
            "birth_index": value["birth_index"],
            "draw_start": draw["start_inclusive"],
            "draw_end": draw["end_exclusive"],
            "mobility_mode": value["mobility_mode"],
            "base_yaw_rad": value["base_yaw_rad"],
            "base_start_w_m": value["base_start_w_m"],
        }
        if has_sampling:
            sampling = value["sampling"]
            sampling_keys = {
                "mixture",
                "stratum",
                "effective_levels",
                "frontier_arm",
            }
            if (
                not isinstance(sampling, dict)
                or set(sampling) != sampling_keys
            ):
                raise ValueError(
                    "action-ball sampler birth sampling has invalid keys"
                )
            identity.update(
                {
                    "sampling_mixture": sampling["mixture"],
                    "sampling_stratum": sampling["stratum"],
                    "sampling_levels": sampling["effective_levels"],
                    "frontier_arm": sampling["frontier_arm"],
                }
            )
        receipt = BaseBirthReceipt.from_identity_receipt(identity)
        if receipt.to_receipt() != value:
            raise ValueError(
                "action-ball sampler birth receipt failed exact round-trip"
            )
        return receipt

    def _action_ball_adaptive_sigma_active(self) -> bool:
        """Whether this ActionBall lineage owns the three-channel exact-strike controller."""

        return bool(
            self.cfg.adaptive_sigma
            and self.cfg.adaptive_sigma_monotonic
            and self.cfg.adaptive_sigma_normal
            and _adaptive_sigma_source(self.cfg)
            == _ADAPTIVE_SIGMA_SOURCE_BALL_EXACT
        )

    def _action_ball_adaptive_sigma_identity(self) -> dict:
        """Immutable reward-controller identity stored inside the ActionBall checkpoint."""

        if not self._action_ball_adaptive_sigma_active():
            raise RuntimeError("ActionBall adaptive-sigma identity requested while disabled")
        return {
            "source": _ADAPTIVE_SIGMA_SOURCE_BALL_EXACT,
            "error_statistic": "exact_strike_decayed_mean",
            "monotonic": True,
            "normal_channel": True,
            "sigma_pos_min": float(self.cfg.sigma_pos_min),
            "sigma_pos_max": float(self.cfg.sigma_pos_max),
            "sigma_vel_min": float(self.cfg.sigma_vel_min),
            "sigma_vel_max": float(self.cfg.sigma_vel_max),
            "sigma_normal_min": float(self.cfg.sigma_normal_min),
            "sigma_normal_max": float(self.cfg.sigma_normal_max),
            "sigma_update_every": int(self.cfg.sigma_update_every),
            "sigma_ema_scale": float(self.cfg.sigma_ema_scale),
            "exact_success_decay": float(self.cfg.exact_success_decay),
            "exact_success_min_count": float(self.cfg.exact_success_min_count),
            "strike_window_pos_s": float(self.cfg.strike_window_pos_s),
            "strike_window_wide_s": float(self.cfg.strike_window_wide_s),
        }

    def _action_ball_adaptive_sigma_state_dict(self) -> dict:
        """Serialize live widths and the exact-strike EMA that determines their next update."""

        return {
            "schema_version": 1,
            "identity": self._action_ball_adaptive_sigma_identity(),
            "sigma": {
                "position": float(self._adaptive_sigma_pos),
                "velocity": float(self._adaptive_sigma_vel),
                "normal": float(self._adaptive_sigma_normal),
            },
            "ema": {
                "exact_count": float(self._exact_n_acc),
                "position_error_sum": float(self._exact_pos_err_sum),
                "velocity_error_sum": float(self._exact_vel_err_sum),
                "normal_error_sum_rad": float(self._exact_nrm_err_sum),
            },
        }

    def _action_ball_stage_adaptive_sigma_state(self, state: object) -> dict:
        """Validate adaptive state without mutating RewardManager or live accumulators."""

        expected_keys = {"schema_version", "identity", "sigma", "ema"}
        if (
            not isinstance(state, dict)
            or set(state) != expected_keys
            or state.get("schema_version") != 1
            or state.get("identity") != self._action_ball_adaptive_sigma_identity()
        ):
            raise ValueError("ActionBall adaptive-sigma exact-resume identity/schema changed")
        sigma = state.get("sigma")
        ema = state.get("ema")
        if not isinstance(sigma, dict) or set(sigma) != {
            "position",
            "velocity",
            "normal",
        }:
            raise ValueError("ActionBall adaptive-sigma widths are invalid")
        if not isinstance(ema, dict) or set(ema) != {
            "exact_count",
            "position_error_sum",
            "velocity_error_sum",
            "normal_error_sum_rad",
        }:
            raise ValueError("ActionBall adaptive-sigma EMA is invalid")
        numeric = [*sigma.values(), *ema.values()]
        if any(
            isinstance(value, bool)
            or not isinstance(value, (int, float))
            or not math.isfinite(float(value))
            or float(value) < 0.0
            for value in numeric
        ):
            raise ValueError(
                "ActionBall adaptive-sigma state must be finite and nonnegative"
            )
        staged = {
            "position": float(sigma["position"]),
            "velocity": float(sigma["velocity"]),
            "normal": float(sigma["normal"]),
            "exact_count": float(ema["exact_count"]),
            "position_error_sum": float(ema["position_error_sum"]),
            "velocity_error_sum": float(ema["velocity_error_sum"]),
            "normal_error_sum_rad": float(ema["normal_error_sum_rad"]),
        }
        for channel, lower, upper in (
            ("position", self.cfg.sigma_pos_min, self.cfg.sigma_pos_max),
            ("velocity", self.cfg.sigma_vel_min, self.cfg.sigma_vel_max),
            ("normal", self.cfg.sigma_normal_min, self.cfg.sigma_normal_max),
        ):
            if not float(lower) <= staged[channel] <= float(upper):
                raise ValueError(
                    f"ActionBall restored {channel} sigma is outside configured bounds"
                )
        resolved = self._resolve_adaptive_sigma_terms(
            _ADAPTIVE_SIGMA_SOURCE_BALL_EXACT, True
        )
        self._adaptive_sigma_live_widths(
            resolved, _ADAPTIVE_SIGMA_SOURCE_BALL_EXACT, True
        )
        staged["resolved_reward_terms"] = resolved
        return staged

    def _action_ball_commit_adaptive_sigma_state(self, staged: dict) -> None:
        """Atomically restore controller scalars and all RewardManager-owned live widths."""

        resolved = staged["resolved_reward_terms"]
        self._commit_adaptive_sigma_widths(
            resolved,
            _ADAPTIVE_SIGMA_SOURCE_BALL_EXACT,
            staged["position"],
            staged["velocity"],
            staged["normal"],
        )
        self._adaptive_sigma_pos = staged["position"]
        self._adaptive_sigma_vel = staged["velocity"]
        self._adaptive_sigma_normal = staged["normal"]
        self._exact_n_acc = staged["exact_count"]
        self._exact_pos_err_sum = staged["position_error_sum"]
        self._exact_vel_err_sum = staged["velocity_error_sum"]
        self._exact_nrm_err_sum = staged["normal_error_sum_rad"]

    def _action_ball_fixed_view_pool_is_pristine(
        self, pool_state: object
    ) -> bool:
        """Whether the legacy receipt pool has remained completely unused."""

        if not isinstance(pool_state, dict):
            return False
        solver_state = pool_state.get("solver_state")
        if (
            not isinstance(solver_state, dict)
            or solver_state.get("highwaters") != []
            or solver_state.get("assignments") != []
            or solver_state.get("emitted_tasks") != []
            or solver_state.get("physical_rng_draws") != 0
            or solver_state.get("online_lm_calls") != 0
            or pool_state.get("retired_generations") != []
        ):
            return False
        actions = pool_state.get("actions")
        if not isinstance(actions, list) or len(actions) != len(
            self._action_ball_bindings
        ):
            return False
        zero_ledger = {
            "requests": 0,
            "refill_calls": 0,
            "proposed": 0,
            "admitted": 0,
            "issued": 0,
            "discarded": 0,
        }
        for action in actions:
            if (
                not isinstance(action, dict)
                or action.get("ledger") != zero_ledger
                or action.get("last_sample_index") is not None
                or action.get("last_sample_draw_end") is not None
                or action.get("lifecycle_sample_count") != 0
                or action.get("births") != []
                or action.get("retired_births") != []
            ):
                return False
        return True

    def _action_ball_task_wait_exact_state_dict(self) -> dict:
        """Serialize the hidden WAIT/reveal clock for every ActionBall source.

        This used to live only inside the deprecated immutable-tape fixture.  A211 cached-target
        and C211 direct-ball both use the same hidden WAIT ABI, so omitting it made a checkpoint
        silently reveal a different task cohort after cold load.
        """

        return {
            "schema_version": 1,
            "schedule_enabled": self._action_ball_task_wait_schedule is not None,
            "highwater": (
                None
                if self._action_ball_task_wait_highwater is None
                else self._action_ball_task_wait_highwater.state_dict()
            ),
            "task_valid": [
                bool(value)
                for value in self._action_ball_task_valid.detach().cpu().tolist()
            ],
            "total_ticks": [
                int(value)
                for value in (
                    self._action_ball_task_wait_total_ticks.detach().cpu().tolist()
                )
            ],
            "elapsed_ticks": [
                int(value)
                for value in (
                    self._action_ball_task_wait_elapsed_ticks.detach().cpu().tolist()
                )
            ],
            "last_advance_step": int(
                self._action_ball_task_wait_last_advance_step
            ),
        }

    def _action_ball_stage_task_wait_exact_state(
        self, state: object
    ) -> dict:
        """Read-only validation of hidden WAIT state."""

        expected = {
            "schema_version",
            "schedule_enabled",
            "highwater",
            "task_valid",
            "total_ticks",
            "elapsed_ticks",
            "last_advance_step",
        }
        if (
            not isinstance(state, dict)
            or set(state) != expected
            or state.get("schema_version") != 1
            or type(state.get("schedule_enabled")) is not bool
            or state["schedule_enabled"]
            != (self._action_ball_task_wait_schedule is not None)
        ):
            raise ValueError("ActionBall task-wait exact-resume schema/identity mismatch")
        vectors = (
            state["task_valid"],
            state["total_ticks"],
            state["elapsed_ticks"],
        )
        if any(
            not isinstance(vector, list) or len(vector) != self.num_envs
            for vector in vectors
        ):
            raise ValueError("ActionBall task-wait vectors must match num_envs")
        if any(type(value) is not bool for value in vectors[0]) or any(
            type(value) is not int or value < 0
            for vector in vectors[1:]
            for value in vector
        ):
            raise ValueError("ActionBall task-wait vector values are invalid")
        if any(
            elapsed > total
            for total, elapsed in zip(vectors[1], vectors[2])
        ):
            raise ValueError("ActionBall task-wait elapsed ticks exceed total ticks")
        last_step = state["last_advance_step"]
        if type(last_step) is not int or last_step < -1:
            raise ValueError("ActionBall task-wait last advance step is invalid")
        if self._action_ball_task_wait_schedule is None:
            if (
                state["highwater"] is not None
                or not all(vectors[0])
                or any(vectors[1])
                or any(vectors[2])
                or last_step != -1
            ):
                raise ValueError("disabled ActionBall task wait has non-empty state")
            highwater = None
        else:
            from whole_body_tracking.tasks.tracking.action_ball_task_wait import (
                ActionBallTaskWaitHighwater,
            )

            highwater = ActionBallTaskWaitHighwater.from_state_dict(
                self._action_ball_task_wait_schedule,
                state["highwater"],
            )
        return {
            "task_valid": list(vectors[0]),
            "total_ticks": list(vectors[1]),
            "elapsed_ticks": list(vectors[2]),
            "last_advance_step": last_step,
            "highwater": highwater,
        }

    @staticmethod
    def _action_ball_runtime_latch_field_names() -> tuple[str, ...]:
        """Observation/reward/event tensors that survive between command ticks."""

        return (
            "_prev_motion_steps",
            "racket_target_pos_w",
            "racket_target_vel_w",
            "racket_target_normal_w",
            "target_normal_cmd",
            "base_target_pos_w",
            "swing_sign",
            "time_to_strike",
            "pre_strike",
            "strike_window",
            "strike_window_pos",
            "strike_window_wide",
            "_post_strike_elapsed_s",
            "_post_strike_elapsed_valid",
            "_exact_fired",
            "_action_ball_ball_contact_target_w",
            "_action_ball_face_center_velocity_target_w",
            "_action_ball_racket_command_quat_w",
            "_action_ball_prev_racket_site_w",
            "_action_ball_prev_racket_quat_w",
            "_action_ball_prev_racket_site_velocity_w",
            "_action_ball_prev_racket_angular_velocity_w",
            "_action_ball_prev_attempt_action",
            "_action_ball_prev_reset_generation",
            "_action_ball_prev_swing_generation",
            "_action_ball_prev_contact_valid",
            "vb_vel_in_w",
            "vb_spin_in_w",
            "vb_fired",
            "vb_landing_xy",
            "vb_landing_valid",
            "vb_on_opponent",
            "vb_depth_ok",
            "vb_net_z",
            "vb_net_clear",
            "vb_net_crossed",
            "vb_topspin",
            "vb_spin_out_norm",
            "_vb_target_xy_per_env",
            "_counter_rally_return_direction_env_xy",
            "_counter_rally_target_baseline_speed_mps",
            "_counter_rally_reward_terms",
            "_counter_rally_accepted",
            "_counter_rally_legal_first_landing",
            "_counter_rally_primary_reason_code",
        )

    def _action_ball_runtime_latches_exact_state_dict(self) -> dict:
        if bool(self._strike_timing_metrics_handoff_pending) or (
            self._strike_timing_metrics_step_token is not None
        ):
            raise RuntimeError(
                "ActionBall checkpoint captured an in-flight metrics/update timing handoff"
            )
        tensors = {}
        for name in self._action_ball_runtime_latch_field_names():
            value = getattr(self, name, None)
            if not torch.is_tensor(value):
                raise RuntimeError(
                    f"ActionBall exact-resume runtime latch {name} is unavailable"
                )
            if torch.is_floating_point(value) and not bool(
                torch.isfinite(value).all()
            ):
                raise RuntimeError(
                    f"ActionBall exact-resume runtime latch {name} is non-finite"
                )
            tensors[name] = value.detach().cpu().tolist()
        return {
            "schema_version": 1,
            "tensors": tensors,
            "post_strike_elapsed_last_step": int(
                self._post_strike_elapsed_last_step
            ),
            "metrics_update_handoff_clear": True,
        }

    def _action_ball_stage_runtime_latches_exact_state(
        self, state: object
    ) -> dict[str, torch.Tensor | int]:
        expected = {
            "schema_version",
            "tensors",
            "post_strike_elapsed_last_step",
            "metrics_update_handoff_clear",
        }
        names = self._action_ball_runtime_latch_field_names()
        if (
            not isinstance(state, dict)
            or set(state) != expected
            or state.get("schema_version") != 1
            or state.get("metrics_update_handoff_clear") is not True
            or not isinstance(state.get("tensors"), dict)
            or tuple(state["tensors"]) != names
        ):
            raise ValueError(
                "ActionBall runtime-latch exact-resume schema/order mismatch"
            )
        last_step = state["post_strike_elapsed_last_step"]
        if type(last_step) is not int or last_step < -1:
            raise ValueError(
                "ActionBall post-strike elapsed last step is invalid"
            )
        staged: dict[str, torch.Tensor | int] = {
            "post_strike_elapsed_last_step": last_step
        }

        def _raw_leaves(value):
            if isinstance(value, list):
                for item in value:
                    yield from _raw_leaves(item)
                return
            yield value

        for name in names:
            live = getattr(self, name, None)
            if not torch.is_tensor(live):
                raise ValueError(
                    f"ActionBall runtime latch {name} is absent from the live command"
                )
            raw = state["tensors"][name]
            leaves = tuple(_raw_leaves(raw))
            if live.dtype == torch.bool:
                scalar_types_valid = all(type(value) is bool for value in leaves)
            elif torch.is_floating_point(live):
                scalar_types_valid = all(
                    type(value) in (int, float) for value in leaves
                )
            else:
                scalar_types_valid = all(type(value) is int for value in leaves)
            if not scalar_types_valid:
                raise ValueError(
                    f"ActionBall runtime latch {name} has invalid scalar types"
                )
            try:
                value = torch.as_tensor(
                    raw, dtype=live.dtype, device="cpu"
                )
            except (TypeError, ValueError, RuntimeError) as exc:
                raise ValueError(
                    f"ActionBall runtime latch {name} cannot be decoded"
                ) from exc
            if tuple(value.shape) != tuple(live.shape):
                raise ValueError(
                    f"ActionBall runtime latch {name} shape changed: "
                    f"checkpoint={tuple(value.shape)} runtime={tuple(live.shape)}"
                )
            if torch.is_floating_point(value) and not bool(
                torch.isfinite(value).all()
            ):
                raise ValueError(
                    f"ActionBall runtime latch {name} contains NaN or Inf"
                )
            staged[name] = value.clone()

        if bool(
            (
                staged["_counter_rally_accepted"]
                & ~staged["_counter_rally_legal_first_landing"]
            ).any()
        ):
            raise ValueError(
                "ActionBall counter-rally acceptance lacks a legal first landing"
            )
        return staged

    def _action_ball_exact_resume_state_dict(self) -> dict:
        """Serialize every random tape, receipt queue, generation and attribution latch."""

        fixed_view = self._action_ball_fixed_view_enabled
        # ``diagnostic_unauthorized`` removes evaluator/promotion authority; it does not make the
        # sampler, curriculum, exact-question cache, WAIT clock or outcome latches disappear.
        # A211/C211 therefore use the same complete data-continuation envelope as formal runs while
        # retaining their diagnostic brand in ``hard_contract`` and frozen-evaluation state.
        hard_contract = self.action_ball_hard_contract()
        if hard_contract is None:
            raise RuntimeError("action-ball exact state requested before runtime admission")
        ledger = self._action_ball_ledger_payload()
        ledger_rows = {
            name: [
                ledger[action][name]
                for action in self._action_ball_manifest.action_order
            ]
            for name in _ACTION_BALL_LEDGER_NAMES
        }
        mutable_state = self._action_ball_solver_mutable_state_dict()
        broker_state = (
            self._action_ball_fixed_view_broker_state_dict()
            if fixed_view
            else self._action_ball_broker.state_dict()
        )
        pool_state = self._action_ball_pool.state_dict()
        banded_question_bank = self._action_ball_banded_question_bank
        if (
            broker_state["provider_state"] != mutable_state
            or broker_state["domain_authority_state"] != mutable_state
            or (
                not fixed_view
                and
                banded_question_bank is None
                and pool_state["solver_state"] != mutable_state
            )
        ):
            raise RuntimeError(
                "action-ball shared mutable state views diverged at checkpoint"
            )
        if (
            (fixed_view or banded_question_bank is not None)
            and pool_state["solver_state"]
            != self._action_ball_pool_solver.state_dict()
        ):
            raise RuntimeError(
                "action-ball precomputed solver state diverged from the pool"
            )
        if fixed_view and not self._action_ball_fixed_view_pool_is_pristine(
            pool_state
        ):
            raise RuntimeError(
                "immutable fixed-view exact state found legacy pool activity"
            )
        env_state = {
            "births": [
                None if birth is None else birth.to_dict()
                for birth in self._action_ball_birth_by_env
            ],
            "tasks": [
                None if task is None else task.to_dict()
                for task in self._action_ball_task_by_env
            ],
            "task_refs": [
                (
                    None
                    if task is None
                    else (
                        self._action_ball_task_ref_by_env[env_id]
                        if self._action_ball_diagnostic_unauthorized
                        else task.task_ref()
                    ).to_dict()
                )
                for env_id, task in enumerate(self._action_ball_task_by_env)
            ],
            "counter_rally_tasks": [
                None if task is None else task.to_dict()
                for task in self._counter_rally_task_identity_by_env
            ],
            "action_uid": [
                int(value)
                for value in self._action_ball_action_uid.detach().cpu().tolist()
            ],
            "action_slot": [
                int(value)
                for value in self._action_ball_action_slot.detach().cpu().tolist()
            ],
            "reset_generation": [
                int(value)
                for value in self._action_ball_reset_generation.detach().cpu().tolist()
            ],
            "swing_generation": [
                int(value)
                for value in self._action_ball_swing_generation.detach().cpu().tolist()
            ],
            "attempt_active": [
                bool(value)
                for value in self._action_ball_attempt_active.detach().cpu().tolist()
            ],
            "attempt_action_slot": [
                int(value)
                for value in self._action_ball_attempt_action.detach().cpu().tolist()
            ],
            "attempt_legal": [
                bool(value)
                for value in self._action_ball_attempt_legal.detach().cpu().tolist()
            ],
            "attempt_hit": [
                bool(value)
                for value in self._action_ball_attempt_hit.detach().cpu().tolist()
            ],
            "reference_term_center_latch": [
                bool(value)
                for value in (
                    self._action_ball_reference_term_center_latch.detach()
                    .cpu()
                    .tolist()
                )
            ],
            "strike_window_entry_armed": (
                self._strike_window_entry_distance_probe_exact_state()
            ),
        }
        task_wait_state = self._action_ball_task_wait_exact_state_dict()
        runtime_latches_state = (
            self._action_ball_runtime_latches_exact_state_dict()
        )
        fixed_view_state = None
        if fixed_view:
            if any(task is not None for task in self._action_ball_task_by_env) or any(
                ref is not None for ref in self._action_ball_task_ref_by_env
            ):
                raise RuntimeError(
                    "immutable fixed-view exact state acquired a task receipt/ref"
                )
            # The simulator is intentionally not checkpointed.  Canonicalize
            # each in-flight installed attempt into exactly one X now, inside
            # the serialized continuation, so cold load and a no-step re-save
            # are byte-stable and the deferred first reset cannot grade stale
            # physics as L/F evidence.
            for env_id, active in enumerate(env_state["attempt_active"]):
                if not active:
                    continue
                slot = env_state["attempt_action_slot"][env_id]
                if type(slot) is not int or not 0 <= slot < len(
                    self._action_ball_bindings
                ):
                    raise RuntimeError(
                        "immutable fixed-view active attempt has an invalid slot"
                    )
                ledger_rows["X"][slot] += 1
                env_state["attempt_active"][env_id] = False
                env_state["attempt_action_slot"][env_id] = -1
                env_state["attempt_legal"][env_id] = False
                env_state["attempt_hit"][env_id] = False
                env_state["counter_rally_tasks"][env_id] = None
                # Match the data-only reset disposition above.  These are
                # command-side event/reward memories, not simulator bytes;
                # leaving them armed after the serialized attempt became X
                # would make the strict loader correctly reject its own
                # fixed-view snapshot as an outcome latch without an active
                # attempt.
                runtime_latches_state["tensors"][
                    "_action_ball_prev_contact_valid"
                ][env_id] = False
                runtime_latches_state["tensors"]["vb_fired"][env_id] = False
                runtime_latches_state["tensors"][
                    "_post_strike_elapsed_valid"
                ][env_id] = False
                runtime_latches_state["tensors"]["_exact_fired"][env_id] = False
                reward_row = runtime_latches_state["tensors"][
                    "_counter_rally_reward_terms"
                ][env_id]
                runtime_latches_state["tensors"][
                    "_counter_rally_reward_terms"
                ][env_id] = [0.0 for _ in reward_row]
                runtime_latches_state["tensors"][
                    "_counter_rally_accepted"
                ][env_id] = False
                runtime_latches_state["tensors"][
                    "_counter_rally_legal_first_landing"
                ][env_id] = False
                runtime_latches_state["tensors"][
                    "_counter_rally_primary_reason_code"
                ][env_id] = -1
            fixed_view_state = {
                "schema_version": 1,
                "kind": (
                    "whole_body_tracking.RacketTargetCommand."
                    "immutable_n1_fixed_view_exact_resume"
                ),
                "diagnostic_unauthorized": True,
                "exact_resume_supported": True,
                "identity_sha256": (
                    self._action_ball_fixed_view_identity_sha256
                ),
                "task_receipts_created": 0,
                "legacy_pool_pristine": True,
                "task_wait_highwater": (
                    task_wait_state["highwater"]
                ),
                "task_valid": task_wait_state["task_valid"],
                "task_wait_total_ticks": task_wait_state["total_ticks"],
                "task_wait_elapsed_ticks": task_wait_state["elapsed_ticks"],
                "task_wait_last_advance_step": int(
                    task_wait_state["last_advance_step"]
                ),
            }
        payload = {
            "schema_version": _ACTION_BALL_STATE_SCHEMA_VERSION,
            "kind": _ACTION_BALL_STATE_KIND,
            "manifest_sha256": self._action_ball_loaded_manifest.file_sha256,
            "hard_contract": hard_contract,
            "action_order": list(self._action_ball_manifest.action_order),
            "action_uids": list(self._action_ball_bundle.action_uids),
            "num_envs": int(self.num_envs),
            "solver": self._action_ball_solver_contract,
            "physics": self._action_ball_physics_contract,
            "curriculum": self._action_ball_curriculum.state_dict(),
            "frozen_evaluation": (
                self._action_ball_eval_runtime_state_dict()
            ),
            "mutable_state": mutable_state,
            "broker": broker_state,
            "pool": pool_state,
            "ledger": ledger_rows,
            "env_state": env_state,
            "task_wait": task_wait_state,
            "runtime_latches": runtime_latches_state,
            "last_rollout_step": self._action_ball_last_rollout_step,
        }
        if bool(
            getattr(
                self,
                "_action_ball_continuous_fresh_racket_lane_bound",
                False,
            )
        ):
            payload["continuous_protocol"] = (
                self._action_ball_continuous_racket_exact_resume_protocol_state()
            )
        if fixed_view_state is not None:
            payload["fixed_view"] = fixed_view_state
        if self._action_ball_adaptive_sigma_active():
            payload["adaptive_sigma"] = (
                self._action_ball_adaptive_sigma_state_dict()
            )
        payload["integrity_sha256"] = _action_ball_canonical_sha256(payload)
        return payload

    def _action_ball_stage_resume_curriculum(
        self,
        curriculum_state: object,
        frozen_evaluation_state: object,
    ) -> dict:
        """Rebuild the whole formal authority graph before live commit."""

        from whole_body_tracking.tasks.tracking.mdp.action_ball_curriculum import (
            ActionBallCurriculum,
        )
        from whole_body_tracking.tasks.tracking.mdp.action_ball_sampling import (
            ARM_CATALOG_SHA256,
        )

        diagnostic_unauthorized = self._action_ball_diagnostic_unauthorized
        if type(diagnostic_unauthorized) is not bool:
            raise ValueError(
                "action-ball diagnostic resume brand must be an exact boolean"
            )
        if diagnostic_unauthorized:
            # A diagnostic checkpoint deliberately has no evaluator authority
            # nested in its curriculum state.  Its branded hard contract was
            # already matched above, so reopening a formal launch receipt here
            # would both cross the trust boundary and make diagnostic resume
            # depend on intentionally absent formal material.
            if (
                not isinstance(self._action_ball_evaluator_launch, dict)
                or self._action_ball_evaluator_launch.get(
                    "diagnostic_unauthorized"
                )
                is not True
            ):
                raise ValueError(
                    "diagnostic action-ball resume lost its evaluator brand"
                )
            staged_evaluator = None
            staged_source = None
            staged_coordinator = None
            staged_drain_authority = None
            staged_drain_source = None
            staged_drain_launch = None
            staged_launch = self._action_ball_evaluator_launch
            expected_eval = {
                "schema_version": 1,
                "diagnostic_unauthorized": True,
                "last_request_step": -1,
                "profile_cursor": 0,
                "next_kind_by_uid": {},
                "coordinator": None,
                "drain_source": None,
            }
            if frozen_evaluation_state != expected_eval:
                raise ValueError(
                    "diagnostic frozen-evaluation resume state mismatch"
                )
            schedule = {
                "last_request_step": -1,
                "profile_cursor": 0,
                "next_kind_by_uid": {},
            }
        else:
            (
                staged_evaluator,
                staged_source,
                staged_coordinator,
                staged_launch,
            ) = _action_ball_load_frozen_evaluation_runtime(
                    cfg=self.cfg,
                    repo_root=self._action_ball_repo_root,
                    curriculum_contract_sha256=(
                        self._action_ball_bundle.contract_sha256
                    ),
                    profile_order=self._action_ball_profile_keys,
                    arm_catalog_sha256=ARM_CATALOG_SHA256,
                    scheduler_contract_sha256=(
                        self._action_ball_curriculum.scheduler_contract_sha256
                    ),
                    sampler_sha256=(
                        self._action_ball_sampler.sampler_contract_sha256
                    ),
                    solver_sha256=self._action_ball_solver_contract["sha256"],
                )
            (
                staged_drain_authority,
                staged_drain_source,
                staged_drain_launch,
            ) = _action_ball_load_drain_reset_authority(
                cfg=self.cfg,
                repo_root=self._action_ball_repo_root,
                curriculum_contract_sha256=(
                    self._action_ball_bundle.contract_sha256
                ),
                profile_order=self._action_ball_profile_keys,
                arm_catalog_sha256=ARM_CATALOG_SHA256,
                scheduler_contract_sha256=(
                    self._action_ball_curriculum.scheduler_contract_sha256
                ),
                sampler_sha256=(
                    self._action_ball_sampler.sampler_contract_sha256
                ),
                solver_sha256=self._action_ball_solver_contract["sha256"],
                runtime_owner=self,
            )
            expected_eval_keys = {
                "schema_version",
                "diagnostic_unauthorized",
                "last_request_step",
                "profile_cursor",
                "next_kind_by_uid",
                "coordinator",
                "drain_source",
                "state_sha256",
            }
            if (
                not isinstance(frozen_evaluation_state, dict)
                or set(frozen_evaluation_state) != expected_eval_keys
            ):
                raise ValueError(
                    "formal frozen-evaluation resume keys mismatch"
                )
            unsigned_eval = dict(frozen_evaluation_state)
            eval_digest = unsigned_eval.pop("state_sha256")
            if (
                type(eval_digest) is not str
                or _action_ball_canonical_sha256(unsigned_eval)
                != eval_digest
                or frozen_evaluation_state["schema_version"] != 1
                or frozen_evaluation_state["diagnostic_unauthorized"]
                is not False
            ):
                raise ValueError(
                    "formal frozen-evaluation resume integrity mismatch"
                )
            last_request_step = frozen_evaluation_state[
                "last_request_step"
            ]
            profile_cursor = frozen_evaluation_state["profile_cursor"]
            next_kind = frozen_evaluation_state["next_kind_by_uid"]
            expected_uids = {
                str(uid) for uid in self._action_ball_bundle.action_uids
            }
            if (
                type(last_request_step) is not int
                or last_request_step < -1
                or type(profile_cursor) is not int
                or not 0
                <= profile_cursor
                < len(self._action_ball_profile_keys)
                or not isinstance(next_kind, dict)
                or set(next_kind) != expected_uids
                or any(
                    value not in ("scheduler", "formal")
                    for value in next_kind.values()
                )
            ):
                raise ValueError(
                    "formal frozen-evaluation schedule state mismatch"
                )
            staged_drain_source.load_state_dict(
                frozen_evaluation_state["drain_source"]
            )
            schedule = {
                "last_request_step": last_request_step,
                "profile_cursor": profile_cursor,
                "next_kind_by_uid": {
                    int(uid): next_kind[str(uid)]
                    for uid in self._action_ball_bundle.action_uids
                },
            }
        if staged_launch != self._action_ball_evaluator_launch:
            raise ValueError(
                "action-ball evaluator launch changed during exact resume"
            )
        if not diagnostic_unauthorized and (
            staged_drain_launch != self._action_ball_drain_reset_launch
        ):
            raise ValueError(
                "action-ball drain/reset launch changed during exact resume"
            )
        staged_curriculum = ActionBallCurriculum(
            contract_sha256=self._action_ball_bundle.contract_sha256,
            profile_order=self._action_ball_profile_keys,
            sampler_sha256=self._action_ball_sampler.sampler_contract_sha256,
            solver_sha256=self._action_ball_solver_contract["sha256"],
            policy_contract_sha256=(
                self.cfg.action_ball_policy_contract_sha256
            ),
            config=self._action_ball_curriculum.config,
            scheduler_config=self._action_ball_curriculum.scheduler_config,
            evaluator_authority=staged_evaluator,
            drain_reset_authority=staged_drain_authority,
        )
        staged_curriculum.load_state_dict(curriculum_state)
        recovered_request = None
        if not diagnostic_unauthorized:
            staged_coordinator.load_state_dict(
                frozen_evaluation_state["coordinator"]
            )
            recovered_request = (
                staged_coordinator.reconcile_published_request()
            )
        return {
            "curriculum": staged_curriculum,
            "evaluator_authority": staged_evaluator,
            "evaluator_source": staged_source,
            "coordinator": staged_coordinator,
            "drain_authority": staged_drain_authority,
            "drain_source": staged_drain_source,
            "schedule": schedule,
            "recovered_request": recovered_request,
        }

    def _action_ball_validate_exact_resume_state_dict(
        self, state: dict, *, strict: bool = True
    ) -> None:
        """Validate the full ActionBall graph without changing live command state."""

        self._action_ball_load_exact_resume_state_dict(
            state, strict=strict, _validate_only=True
        )

    def _action_ball_load_exact_resume_state_dict(
        self,
        state: dict,
        strict: bool = True,
        *,
        _validate_only: bool = False,
    ) -> None:
        """Strictly validate into temporary components, then commit without sampling or sim I/O."""

        if strict is not True:
            raise ValueError("action-ball exact resume only supports strict=True")
        if self._action_ball_birth_catalogs_are_live_only():
            # 人话:这种跑法故意不写逐出生存档,所以它存下来的 checkpoint 本来就不含
            # "精确续跑"需要的那半份材料。A211/C211 的发射合同自己也写着
            # resume_prohibited / fresh_only。与其让缺的那半份悄悄变成零,不如在这里
            # 直说:这类 checkpoint 只用于数据延续与取证,续跑请重开。
            raise ValueError(
                "action-ball live-births-only runs keep no per-birth provider "
                "history or task transcript, so their checkpoints cannot serve "
                "an exact resume; launch fresh"
            )
        fixed_view = self._action_ball_fixed_view_enabled
        expected = {
            "schema_version",
            "kind",
            "manifest_sha256",
            "hard_contract",
            "action_order",
            "action_uids",
            "num_envs",
            "solver",
            "physics",
            "curriculum",
            "frozen_evaluation",
            "mutable_state",
            "broker",
            "pool",
            "ledger",
            "env_state",
            "task_wait",
            "runtime_latches",
            "last_rollout_step",
            "integrity_sha256",
        }
        adaptive_sigma_active = self._action_ball_adaptive_sigma_active()
        if adaptive_sigma_active:
            expected.add("adaptive_sigma")
        if fixed_view:
            expected.add("fixed_view")
        continuous_protocol_bound = bool(
            getattr(
                self,
                "_action_ball_continuous_fresh_racket_lane_bound",
                False,
            )
        )
        if continuous_protocol_bound:
            expected.add("continuous_protocol")
        if not isinstance(state, dict) or set(state) != expected:
            raise ValueError(
                f"action-ball exact-resume keys must be exactly {sorted(expected)}"
            )
        unsigned = {key: state[key] for key in expected if key != "integrity_sha256"}
        if (
            type(state["integrity_sha256"]) is not str
            or _action_ball_canonical_sha256(unsigned) != state["integrity_sha256"]
        ):
            raise ValueError("action-ball exact-resume integrity mismatch")
        if (
            type(state["schema_version"]) is not int
            or state["schema_version"] != _ACTION_BALL_STATE_SCHEMA_VERSION
            or state["kind"] != _ACTION_BALL_STATE_KIND
        ):
            raise ValueError("action-ball exact-resume schema/kind mismatch")
        hard_contract = self.action_ball_hard_contract()
        if hard_contract is None or state["hard_contract"] != hard_contract:
            raise ValueError("action-ball exact-resume hard contract mismatch")
        if (
            state["manifest_sha256"]
            != self._action_ball_loaded_manifest.file_sha256
            or state["action_order"]
            != list(self._action_ball_manifest.action_order)
            or state["action_uids"] != list(self._action_ball_bundle.action_uids)
            or type(state["num_envs"]) is not int
            or state["num_envs"] != self.num_envs
            or state["solver"] != self._action_ball_solver_contract
            or state["physics"] != self._action_ball_physics_contract
        ):
            raise ValueError("action-ball exact-resume immutable identity mismatch")
        staged_task_wait_state = (
            self._action_ball_stage_task_wait_exact_state(
                state["task_wait"]
            )
        )
        staged_runtime_latches = (
            self._action_ball_stage_runtime_latches_exact_state(
                state["runtime_latches"]
            )
        )
        staged_continuous_protocol = (
            self._action_ball_continuous_racket_stage_exact_resume_protocol_state(
                state["continuous_protocol"]
            )
            if continuous_protocol_bound
            else None
        )
        staged_fixed_view_state = None
        if fixed_view:
            fixed = state["fixed_view"]
            fixed_keys = {
                "schema_version",
                "kind",
                "diagnostic_unauthorized",
                "exact_resume_supported",
                "identity_sha256",
                "task_receipts_created",
                "legacy_pool_pristine",
                "task_wait_highwater",
                "task_valid",
                "task_wait_total_ticks",
                "task_wait_elapsed_ticks",
                "task_wait_last_advance_step",
            }
            if (
                not isinstance(fixed, dict)
                or set(fixed) != fixed_keys
                or fixed["schema_version"] != 1
                or fixed["kind"]
                != (
                    "whole_body_tracking.RacketTargetCommand."
                    "immutable_n1_fixed_view_exact_resume"
                )
                or fixed["diagnostic_unauthorized"] is not True
                or fixed["exact_resume_supported"] is not True
                or fixed["identity_sha256"]
                != self._action_ball_fixed_view_identity_sha256
                or fixed["task_receipts_created"] != 0
                or fixed["legacy_pool_pristine"] is not True
            ):
                raise ValueError(
                    "immutable fixed-view exact-resume identity/schema mismatch"
                )
            task_vectors = (
                fixed["task_valid"],
                fixed["task_wait_total_ticks"],
                fixed["task_wait_elapsed_ticks"],
            )
            if any(
                not isinstance(vector, list)
                or len(vector) != self.num_envs
                for vector in task_vectors
            ):
                raise ValueError(
                    "immutable fixed-view task-wait vectors must match num_envs"
                )
            if any(type(value) is not bool for value in task_vectors[0]) or any(
                type(value) is not int or value < 0
                for vector in task_vectors[1:]
                for value in vector
            ):
                raise ValueError(
                    "immutable fixed-view task-wait vector values are invalid"
                )
            last_wait_step = fixed["task_wait_last_advance_step"]
            if type(last_wait_step) is not int or last_wait_step < -1:
                raise ValueError(
                    "immutable fixed-view task-wait step is invalid"
                )
            if self._action_ball_task_wait_schedule is None:
                if (
                    fixed["task_wait_highwater"] is not None
                    or any(task_vectors[1])
                    or any(task_vectors[2])
                    or not all(task_vectors[0])
                ):
                    raise ValueError(
                        "disabled fixed-view task wait has non-empty state"
                    )
                staged_wait_highwater = None
            else:
                from whole_body_tracking.tasks.tracking.action_ball_task_wait import (
                    ActionBallTaskWaitHighwater,
                )

                staged_wait_highwater = (
                    ActionBallTaskWaitHighwater.from_state_dict(
                        self._action_ball_task_wait_schedule,
                        fixed["task_wait_highwater"],
                    )
                )
            staged_fixed_view_state = {
                "task_valid": list(task_vectors[0]),
                "total_ticks": list(task_vectors[1]),
                "elapsed_ticks": list(task_vectors[2]),
                "last_advance_step": last_wait_step,
                "highwater": staged_wait_highwater,
            }
            fixed_wait_comparable = {
                "task_valid": staged_fixed_view_state["task_valid"],
                "total_ticks": staged_fixed_view_state["total_ticks"],
                "elapsed_ticks": staged_fixed_view_state["elapsed_ticks"],
                "last_advance_step": staged_fixed_view_state[
                    "last_advance_step"
                ],
                "highwater": (
                    None
                    if staged_fixed_view_state["highwater"] is None
                    else staged_fixed_view_state["highwater"].state_dict()
                ),
            }
            shared_wait_comparable = {
                "task_valid": staged_task_wait_state["task_valid"],
                "total_ticks": staged_task_wait_state["total_ticks"],
                "elapsed_ticks": staged_task_wait_state["elapsed_ticks"],
                "last_advance_step": staged_task_wait_state[
                    "last_advance_step"
                ],
                "highwater": (
                    None
                    if staged_task_wait_state["highwater"] is None
                    else staged_task_wait_state["highwater"].state_dict()
                ),
            }
            if fixed_wait_comparable != shared_wait_comparable:
                raise ValueError(
                    "immutable fixed-view and shared task-wait states differ"
                )
        last_step = state["last_rollout_step"]
        if last_step is not None and (type(last_step) is not int or last_step < 0):
            raise ValueError(
                "action-ball last_rollout_step must be null or a non-negative int"
            )
        staged_adaptive_sigma = (
            self._action_ball_stage_adaptive_sigma_state(
                state["adaptive_sigma"]
            )
            if adaptive_sigma_active
            else None
        )

        from whole_body_tracking.tasks.tracking.mdp.action_ball_runtime import (
            ActionBallTaskReceipt,
            ActionBirthBroker,
            ActionBirthReceipt,
            ActionTaskReceiptRef,
            CounterRallyTaskIdentity,
            LazyActionTaskPool,
        )
        from whole_body_tracking.tasks.tracking.mdp.action_ball_sampling import (
            ActionBallSampler,
            BaseBirthReceipt,
            SamplingMixture,
        )

        # Validate all component states on disposable objects.  Formal runs
        # reopen their code-rooted evaluator receipt with every immutable
        # identity pin; diagnostic runs restore the intentionally authority-
        # free curriculum without reading formal receipt material.
        staged_runtime = self._action_ball_stage_resume_curriculum(
            state["curriculum"],
            state["frozen_evaluation"],
        )
        staged_curriculum = staged_runtime["curriculum"]
        if staged_runtime["recovered_request"] is not None:
            if last_step is None:
                raise ValueError(
                    "published frozen-eval request cannot follow a "
                    "pre-rollout checkpoint"
                )
            schedule = staged_runtime["schedule"]
            cursor = schedule["profile_cursor"]
            keys = self._action_ball_profile_keys
            expected_key = None
            expected_cursor = None
            for offset in range(len(keys)):
                candidate = keys[(cursor + offset) % len(keys)]
                if (
                    staged_curriculum.pending_domain_release(candidate)
                    is None
                ):
                    expected_key = candidate
                    expected_cursor = (
                        cursor + offset + 1
                    ) % len(keys)
                    break
            if expected_key is None:
                raise ValueError(
                    "published frozen-eval request has no schedulable profile"
                )
            request = staged_runtime["coordinator"]._inbox.load_request(
                self._action_ball_evaluator_launch["inbox_owner_id"],
                self._action_ball_evaluator_launch["inbox_run_id"],
                staged_runtime["recovered_request"],
            )
            target = request["content"]["target"]
            if (
                target["action_uid"] != expected_key.action_uid
                or target["profile_sha256"]
                != expected_key.profile_sha256
                or target["mobility_mode"] != expected_key.mobility
            ):
                raise ValueError(
                    "reconciled frozen-eval request differs from the "
                    "pre-checkpoint schedule cursor"
                )
            schedule["profile_cursor"] = expected_cursor
            schedule["last_request_step"] = last_step
        curriculum_state_sha = state["curriculum"].get("state_sha256")
        (
            _sampler_state,
            staged_question_cache,
            provider_births,
            provider_history,
            task_transcripts,
            emitted_task_counts,
            domain_cursors,
            proposal_rows,
            reject_counts,
        ) = self._action_ball_decode_solver_mutable_state(
            state["mutable_state"],
            curriculum=staged_curriculum,
            expected_curriculum_state_sha256=curriculum_state_sha,
        )
        if self._action_ball_target_source == "direct_ball" and (
            staged_question_cache is not None
            or state["mutable_state"].get("exact_question_cache") is not None
        ):
            raise ValueError(
                "C211 direct_ball exact resume must remain solver/cache free"
            )
        if self._action_ball_reuse_exact_question and (
            staged_question_cache is None
        ):
            raise ValueError(
                "A211 exact-question reuse lost its checkpoint cache"
            )
        mutable_state = state["mutable_state"]
        banded_question_bank = self._action_ball_banded_question_bank
        if (
            state["broker"].get("provider_state") != mutable_state
            or state["broker"].get("domain_authority_state")
            != mutable_state
            or (
                not fixed_view
                and
                banded_question_bank is None
                and state["pool"].get("solver_state") != mutable_state
            )
        ):
            raise ValueError(
                "action-ball shared mutable state copies differ in exact checkpoint"
            )
        if fixed_view and (
            state["pool"].get("solver_state")
            != self._action_ball_pool_solver.state_dict()
            or not self._action_ball_fixed_view_pool_is_pristine(
                state["pool"]
            )
        ):
            raise ValueError(
                "immutable fixed-view exact checkpoint has non-pristine pool state"
            )

        def _json_clone(value):
            return json.loads(
                json.dumps(
                    value,
                    sort_keys=True,
                    separators=(",", ":"),
                    ensure_ascii=True,
                    allow_nan=False,
                )
            )

        staged_sampler = ActionBallSampler(
            self._action_ball_bundle.profiles,
            seed=int(self.cfg.action_ball_seed),
            sampling_mixture=SamplingMixture(),
            contact_time_step_s=float(self._env.step_dt),
            initial_center_single_question=(
                self.cfg.action_ball_initial_center_single_question
            ),
            diagnostic_unauthorized=(
                self._action_ball_diagnostic_unauthorized
            ),
        )
        staged_sampler.load_state_dict(_sampler_state)
        self._action_ball_restore_fixed_sampler_highwaters(
            staged_sampler
        )
        staged_shared = {
            "state": _json_clone(mutable_state),
            "decoded": (
                _sampler_state,
                staged_question_cache,
                provider_births,
                provider_history,
                task_transcripts,
                emitted_task_counts,
                domain_cursors,
                proposal_rows,
                reject_counts,
            ),
            "sampler": staged_sampler,
        }

        def _staged_state():
            return _json_clone(staged_shared["state"])

        def _staged_load(value):
            detached = _json_clone(value)
            if detached == staged_shared["state"]:
                return
            decoded = self._action_ball_decode_solver_mutable_state(
                detached,
                curriculum=staged_curriculum,
                expected_curriculum_state_sha256=curriculum_state_sha,
            )
            replacement_sampler = ActionBallSampler(
                self._action_ball_bundle.profiles,
                seed=int(self.cfg.action_ball_seed),
                sampling_mixture=SamplingMixture(),
                contact_time_step_s=float(self._env.step_dt),
                initial_center_single_question=(
                    self.cfg.action_ball_initial_center_single_question
                ),
                diagnostic_unauthorized=(
                    self._action_ball_diagnostic_unauthorized
                ),
            )
            replacement_sampler.load_state_dict(decoded[0])
            self._action_ball_restore_fixed_sampler_highwaters(
                replacement_sampler
            )
            staged_shared["state"] = detached
            staged_shared["decoded"] = decoded
            staged_shared["sampler"] = replacement_sampler

        def _staged_forbidden(_request):
            raise RuntimeError(
                "exact-resume validation must not invoke runtime producers"
            )

        def _staged_assert_birth(receipt):
            sampler_birth = BaseBirthReceipt.from_identity_receipt(
                receipt.sampler_identity_receipt()
            )
            staged_shared["sampler"].assert_issued_birth(sampler_birth)
            provider = staged_shared["decoded"][2].get(
                receipt.canonical_sha256
            )
            historical_receipt = staged_shared["decoded"][3].get(
                receipt.canonical_sha256
            )
            if historical_receipt != receipt:
                raise RuntimeError(
                    "exact-resume birth is absent from provider assignment history"
                )
            if provider is not None and (
                provider["runtime_birth"] != receipt
                or provider["sampler_birth"] != sampler_birth
            ):
                raise RuntimeError(
                    "exact-resume active birth disagrees with provider history"
                )

        def _staged_assert_sample(receipt):
            provider = staged_shared["decoded"][2].get(
                receipt.birth_sha256
            )
            if (
                provider is None
                or provider["runtime_birth"].canonical_sha256
                != receipt.birth_sha256
                or provider["sampler_birth"].birth_id
                != receipt.sampler_birth_sha256
            ):
                raise RuntimeError(
                    "exact-resume task has no exact shared provider birth"
                )
            staged_shared["sampler"].assert_issued_sample(
                receipt.sampler_identity_receipt()
            )

        def _staged_assert_tasks(receipts):
            self._action_ball_replay_emitted_tasks(
                tuple(receipts),
                sampler=staged_shared["sampler"],
                provider_history=staged_shared["decoded"][3],
                question_cache=staged_shared["decoded"][1],
            )

        def _staged_assert_proposal_assignments(assignments):
            self._action_ball_assert_proposal_assignments_against(
                tuple(assignments),
                sampler=staged_shared["sampler"],
                provider_history=staged_shared["decoded"][3],
            )

        staged_domain = _ActionBallDomainAuthorityAdapter(
            domain_authority_contract_sha256=(
                self._action_ball_domain_authority_contract["sha256"]
            ),
            state_owner_sha256=self._action_ball_state_owner_sha256,
            claim=_staged_forbidden,
            claim_many=None,
            domain_cursor_for=lambda uid: int(
                staged_shared["decoded"][6][int(uid)]
            ),
            state_getter=_staged_state,
            state_loader=_staged_load,
        )
        staged_provider = _ActionBallBirthProviderAdapter(
            sampler_contract_sha256=(
                self._action_ball_sampler.sampler_contract_sha256
            ),
            state_owner_sha256=self._action_ball_state_owner_sha256,
            provide=_staged_forbidden,
            provide_many=None,
            assert_issued_birth=_staged_assert_birth,
            birth_highwater_for=lambda uid: (
                staged_shared["sampler"].birth_highwater_for(uid)
            ),
            state_getter=_staged_state,
            state_loader=_staged_load,
        )
        staged_broker = ActionBirthBroker(
            self._action_ball_bindings,
            self._action_ball_pins,
            self._action_ball_manifest.mobility_mode,
            diagnostic_unauthorized=(
                self._action_ball_diagnostic_unauthorized
            ),
        )
        staged_broker.bind_domain_claim_authority(staged_domain)
        staged_broker.bind_provider(staged_provider)
        staged_broker.load_state_dict(state["broker"])
        if state["broker"]["pending"]:
            raise ValueError(
                "action-ball exact checkpoint captured an in-flight birth transaction"
            )

        if fixed_view:
            from whole_body_tracking.tasks.tracking.mdp.action_ball_fixed_question_tape import (
                FixedQuestionTapeSolver,
            )

            staged_solver = FixedQuestionTapeSolver(
                tape=self._action_ball_immutable_tape,
                target_recipe=self._action_ball_target_recipe,
                solver_contract_sha256=(
                    self._action_ball_solver_contract["sha256"]
                ),
            )
        elif banded_question_bank is None:
            staged_solver = _ActionBallPoolSolverAdapter(
                solver_contract_sha256=self._action_ball_solver_contract["sha256"],
                state_owner_sha256=self._action_ball_state_owner_sha256,
                solve=_staged_forbidden,
                solve_many=lambda _requests: (_staged_forbidden(None),),
                assert_emitted_sample=_staged_assert_sample,
                assert_emitted_tasks=_staged_assert_tasks,
                emitted_task_count_for=lambda uid: int(
                    staged_shared["decoded"][5][int(uid)]
                ),
                task_transcript_for_birth=lambda birth_sha: (
                    staged_shared["decoded"][4][birth_sha]
                ),
                assert_proposal_assignments=(
                    _staged_assert_proposal_assignments
                ),
                sample_highwater_for=lambda uid: (
                    staged_shared["sampler"].sample_highwater_for(uid)
                ),
                state_getter=_staged_state,
                state_loader=_staged_load,
                # Exact resume is refused outright for live-births-only runs at
                # the head of this method, so a staged solver reached here is
                # always the solver-owned-transcript kind.
                pool_owns_birth_task_transcripts=False,
            )
        else:
            from whole_body_tracking.tasks.tracking.mdp.action_ball_banded_question_bank import (
                BandedQuestionBankSolver,
            )

            staged_solver = BandedQuestionBankSolver(
                bank=banded_question_bank,
                solver_contract_sha256=self._action_ball_solver_contract["sha256"],
            )
        staged_pool = LazyActionTaskPool(
            self._action_ball_bindings,
            self._action_ball_pins,
            self._action_ball_manifest.mobility_mode,
            refill_size=self._action_ball_effective_pool_refill_rows,
            diagnostic_unauthorized=(
                self._action_ball_diagnostic_unauthorized
            ),
        )
        staged_pool.bind_solver(staged_solver)
        staged_pool.bind_birth_authority(staged_broker)
        staged_pool.load_state_dict(state["pool"])
        if (
            staged_broker.provider_state_snapshot() != mutable_state
            or (
                not fixed_view
                and
                banded_question_bank is None
                and staged_pool.state_dict()["solver_state"] != mutable_state
            )
            or (
                not fixed_view
                and banded_question_bank is not None
                and staged_pool.state_dict()["solver_state"]
                != state["pool"]["solver_state"]
            )
        ):
            raise ValueError(
                "action-ball staged protocol views did not restore their exact states"
            )
        if fixed_view:
            zero_pool_ledger = {
                "requests": 0,
                "refill_calls": 0,
                "proposed": 0,
                "admitted": 0,
                "issued": 0,
                "discarded": 0,
            }
            if staged_solver.state_dict() != state["pool"]["solver_state"] or any(
                staged_pool.ledger(int(uid)).to_dict()
                != zero_pool_ledger
                or staged_pool.pending_count(int(uid)) != 0
                for uid in self._action_ball_bundle.action_uids
            ):
                raise ValueError(
                    "immutable fixed-view staged legacy pool is not pristine"
                )
        (
            _sampler_state,
            staged_question_cache,
            provider_births,
            provider_history,
            task_transcripts,
            emitted_task_counts,
            domain_cursors,
            proposal_rows,
            reject_counts,
        ) = staged_shared["decoded"]

        raw_ledger = state["ledger"]
        if not isinstance(raw_ledger, dict) or set(raw_ledger) != set(
            _ACTION_BALL_LEDGER_NAMES
        ):
            raise ValueError("action-ball exact ledger has invalid keys")
        n_actions = len(self._action_ball_bindings)
        ledger_rows = []
        for name in _ACTION_BALL_LEDGER_NAMES:
            row = raw_ledger[name]
            if (
                not isinstance(row, list)
                or len(row) != n_actions
                or any(type(value) is not int or value < 0 for value in row)
            ):
                raise ValueError(f"action-ball ledger.{name} has invalid values")
            ledger_rows.append([int(value) for value in row])
        if not fixed_view and banded_question_bank is None and (
            proposal_rows["P"] != raw_ledger["P"]
            or proposal_rows["A"] != raw_ledger["A"]
        ):
            raise ValueError(
                "action-ball top-level ledger/rejections differ from pool-owned solver state"
            )
        for slot, uid in enumerate(self._action_ball_bundle.action_uids):
            values = {
                name: ledger_rows[row][slot]
                for row, name in enumerate(_ACTION_BALL_LEDGER_NAMES)
            }
            if values["H"] > values["C"]:
                raise ValueError(
                    "action-ball exact selected-rubber hits exceed closed attempts"
                )
            outcome = self._action_ball_outcome_type(
                **{
                    name: values[name]
                    for name in _ACTION_BALL_OUTCOME_LEDGER_NAMES
                }
            )
            if fixed_view:
                if not (
                    outcome.P == outcome.A == outcome.I == outcome.S
                    and outcome.S == outcome.C + outcome.X
                ):
                    raise ValueError(
                        "immutable fixed-view exact ledger does not conserve "
                        "P=A=I=S=C+X"
                    )
            else:
                pool_ledger = staged_pool.ledger(int(uid))
                if (
                    outcome.P != pool_ledger.proposed
                    or outcome.A != pool_ledger.admitted
                    or outcome.I != pool_ledger.issued
                    or outcome.S != pool_ledger.issued
                ):
                    raise ValueError(
                        "action-ball exact ledger disagrees with restored pool accounting"
                    )

        env = state["env_state"]
        env_keys = {
            "births",
            "tasks",
            "task_refs",
            "counter_rally_tasks",
            "action_uid",
            "action_slot",
            "reset_generation",
            "swing_generation",
            "attempt_active",
            "attempt_action_slot",
            "attempt_legal",
            "attempt_hit",
            "reference_term_center_latch",
            "strike_window_entry_armed",
        }
        if not isinstance(env, dict) or set(env) != env_keys:
            raise ValueError("action-ball env_state has invalid keys")
        if any(
            not isinstance(env[name], list)
            or len(env[name]) != self.num_envs
            for name in env_keys
        ):
            raise ValueError("action-ball env_state vectors must match num_envs")
        for name in (
            "attempt_active",
            "attempt_legal",
            "attempt_hit",
            "reference_term_center_latch",
            "strike_window_entry_armed",
        ):
            if any(type(value) is not bool for value in env[name]):
                raise ValueError(f"action-ball env_state.{name} must contain bools")
        for name in (
            "action_uid",
            "action_slot",
            "reset_generation",
            "swing_generation",
            "attempt_action_slot",
        ):
            if any(type(value) is not int for value in env[name]):
                raise ValueError(f"action-ball env_state.{name} must contain ints")
        births = []
        tasks = []
        task_refs = []
        counter_rally_tasks = []
        env_birth_digests = set()
        staged_strike_window_entry_armed = (
            self._stage_strike_window_entry_distance_probe_exact_state(
                env["strike_window_entry_armed"]
            )
        )
        for index in range(self.num_envs):
            birth = (
                None
                if env["births"][index] is None
                else ActionBirthReceipt.from_dict(env["births"][index])
            )
            task = (
                None
                if env["tasks"][index] is None
                else ActionBallTaskReceipt.from_dict(env["tasks"][index])
            )
            task_ref = (
                None
                if env["task_refs"][index] is None
                else ActionTaskReceiptRef.from_dict(
                    env["task_refs"][index]
                )
            )
            counter_rally_task = (
                None
                if env["counter_rally_tasks"][index] is None
                else CounterRallyTaskIdentity.from_dict(
                    env["counter_rally_tasks"][index]
                )
            )
            active = env["attempt_active"][index]
            attempt_slot = env["attempt_action_slot"][index]
            legal = env["attempt_legal"][index]
            hit = env["attempt_hit"][index]
            if birth is None:
                if (
                    task is not None
                    or task_ref is not None
                    or counter_rally_task is not None
                    or active
                    or attempt_slot != -1
                    or legal
                    or hit
                    or env["action_uid"][index] != -1
                    or env["action_slot"][index] != -1
                    or env["reset_generation"][index] != 0
                    or env["swing_generation"][index] != -1
                ):
                    raise ValueError(
                        f"action-ball empty env {index} has non-empty generation state"
                    )
            else:
                digest = birth.canonical_sha256
                if digest in env_birth_digests or digest not in provider_births:
                    raise ValueError(
                        "action-ball env birth is duplicate or absent from provider state"
                    )
                env_birth_digests.add(digest)
                if (
                    birth.env_id != index
                    or env["action_uid"][index] != birth.action_uid
                    or env["action_slot"][index] != birth.action_slot
                    or env["reset_generation"][index] != birth.reset_generation
                    or env["swing_generation"][index] < 0
                ):
                    raise ValueError(
                        f"action-ball env {index} birth/generation identity mismatch"
                    )
                binding = self._action_ball_bindings[birth.action_slot]
                birth.assert_contract(
                    binding=binding,
                    pins=self._action_ball_pins,
                    mobility_mode=self._action_ball_manifest.mobility_mode,
                    registry_sha256=self._action_ball_broker.registry_sha256,
                )
                if active:
                    if fixed_view:
                        raise ValueError(
                            "immutable fixed-view checkpoint was not "
                            "canonicalized to a reset-ready X state"
                        )
                    if task is None or attempt_slot != birth.action_slot:
                        raise ValueError(
                            f"action-ball active env {index} has no matching task"
                        )
                    task.assert_contract(
                        binding=binding,
                        pins=self._action_ball_pins,
                        mobility_mode=self._action_ball_manifest.mobility_mode,
                        registry_sha256=self._action_ball_broker.registry_sha256,
                    )
                    task.assert_birth(birth)
                    expected_ref = task.task_ref()
                    if task_ref != expected_ref:
                        raise ValueError(
                            f"action-ball active env {index} task ref mismatch"
                        )
                    if task.counter_rally_task != counter_rally_task:
                        raise ValueError(
                            f"action-ball active env {index} counter-rally task mismatch"
                        )
                    if task.swing_generation != env["swing_generation"][index]:
                        raise ValueError(
                            f"action-ball env {index} task swing generation mismatch"
                        )
                elif (
                    task is not None
                    or task_ref is not None
                    or counter_rally_task is not None
                    or attempt_slot != -1
                    or legal
                    or hit
                ):
                    raise ValueError(
                        f"action-ball inactive env {index} has dirty attempt state"
                    )
            births.append(birth)
            tasks.append(task)
            task_refs.append(task_ref)
            counter_rally_tasks.append(counter_rally_task)
        active_mask = torch.tensor(
            env["attempt_active"], dtype=torch.bool
        )
        task_valid_mask = torch.tensor(
            staged_task_wait_state["task_valid"], dtype=torch.bool
        )
        prev_valid = staged_runtime_latches[
            "_action_ball_prev_contact_valid"
        ]
        if bool((prev_valid & ~active_mask).any()):
            raise ValueError(
                "ActionBall previous-contact latch outlives its active attempt"
            )
        for latch_name, env_name in (
            ("_action_ball_prev_attempt_action", "attempt_action_slot"),
            ("_action_ball_prev_reset_generation", "reset_generation"),
            ("_action_ball_prev_swing_generation", "swing_generation"),
        ):
            staged_values = staged_runtime_latches[latch_name]
            expected_values = torch.tensor(
                env[env_name], dtype=staged_values.dtype
            )
            if bool(
                (prev_valid & (staged_values != expected_values)).any()
            ):
                raise ValueError(
                    f"ActionBall previous-contact identity {latch_name} drifted"
                )
        if bool(
            (
                staged_runtime_latches["vb_fired"]
                & (~active_mask | ~task_valid_mask)
            ).any()
        ):
            raise ValueError(
                "ActionBall fired outcome latch is outside a revealed active task"
            )
        if self._action_ball_task_wait_schedule is not None:
            wait_state = state["task_wait"]
            highwater_rows = wait_state["highwater"][
                "highwater_by_env"
            ]
            highwater_by_env = {
                int(row[0]): int(row[1]) for row in highwater_rows
            }
            expected_highwater = {
                env_id: int(env["reset_generation"][env_id])
                for env_id, birth in enumerate(births)
                if birth is not None
            }
            if highwater_by_env != expected_highwater:
                raise ValueError(
                    "ActionBall wait highwater differs from reset generations"
                )
            for env_id, birth in enumerate(births):
                valid = staged_task_wait_state["task_valid"][env_id]
                total = staged_task_wait_state["total_ticks"][env_id]
                elapsed = staged_task_wait_state["elapsed_ticks"][env_id]
                if birth is None:
                    if not valid or total != 0 or elapsed != 0:
                        raise ValueError(
                            "empty ActionBall env has task-wait state"
                        )
                    continue
                assignment = self._action_ball_task_wait_schedule.assignment(
                    env_id=env_id,
                    reset_generation=birth.reset_generation,
                )
                staged_task_wait_state["highwater"].assert_recorded(
                    assignment
                )
                if env["swing_generation"][env_id] == 0:
                    if (
                        total != assignment.wait_ticks
                        or elapsed > total
                        or valid != (elapsed == total)
                    ):
                        raise ValueError(
                            "ActionBall reset wait state is inconsistent"
                        )
                elif not valid or total != 0 or elapsed != 0:
                    raise ValueError(
                        "ActionBall wrap retained reset-wait state"
                    )
        provider_birth_digests = set(provider_births)
        if env_birth_digests != provider_birth_digests:
            raise ValueError(
                "action-ball active provider births do not equal current env births"
            )
        provider_history_digests = set(provider_history)
        broker_birth_digests = {
            str(row["canonical_sha256"])
            for row in state["broker"]["consumed_receipts"]
        }
        if fixed_view:
            latest_by_env = {}
            for row in state["broker"]["consumed_receipts"]:
                env_id = int(row["env_id"])
                generation = int(row["reset_generation"])
                previous = latest_by_env.get(env_id)
                if previous is None or generation > previous[0]:
                    latest_by_env[env_id] = (
                        generation,
                        str(row["canonical_sha256"]),
                    )
            if broker_birth_digests != provider_history_digests or {
                digest for _generation, digest in latest_by_env.values()
            } != env_birth_digests:
                raise ValueError(
                    "immutable fixed-view broker/current/history births differ"
                )
            for _generation, digest in latest_by_env.values():
                staged_broker.assert_consumed_birth(
                    provider_history[digest]
                )
        else:
            if broker_birth_digests != provider_history_digests:
                raise ValueError(
                    "action-ball broker/provider birth assignment histories differ"
                )
            for receipt in provider_history.values():
                staged_broker.assert_consumed_birth(receipt)

        pool_birth_digests = {
            birth_row["birth"]["canonical_sha256"]
            for action_row in state["pool"]["actions"]
            for birth_row in action_row["births"]
        }
        if (
            (fixed_view and pool_birth_digests)
            or (not fixed_view and pool_birth_digests != env_birth_digests)
        ):
            raise ValueError(
                "action-ball restored pool births do not equal current env births"
            )
        # Preserve the command graph byte-for-byte for the verifier's no-step round trip.  The
        # simulator is intentionally not serialized; a private post-load exclusion latch below
        # makes the runner's mandatory first true reset retire these active rows as X rather than
        # grading them against newly reset physics.
        restored_ledger = [list(row) for row in ledger_rows]
        for slot in range(n_actions):
            values = {
                name: restored_ledger[row][slot]
                for row, name in enumerate(_ACTION_BALL_LEDGER_NAMES)
            }
            if values["H"] > values["C"]:
                raise ValueError(
                    "action-ball restored selected-rubber hits exceed closed attempts"
                )
            self._action_ball_outcome_type(
                **{
                    name: values[name]
                    for name in _ACTION_BALL_OUTCOME_LEDGER_NAMES
                }
            )

        # All nested receipts, RNG tapes, cache rows, curriculum/domain state, broker/pool
        # transcripts, WAIT fields and outcome ledgers are now staged on disposable objects.
        # Runner calls this branch for both Racket and Motion before any checkpoint component is
        # committed, which makes a late command-schema failure process-wide atomic.
        if _validate_only:
            return

        # Atomic live commit after all nested structures, cross-links and X
        # accounting validate.  The evaluator/coordinator/drain graph must move
        # as one unit: mixing a restored curriculum with the pre-load authority
        # lifetime would invalidate every opaque capability.
        self._action_ball_curriculum = staged_runtime["curriculum"]
        self._action_ball_evaluator_authority = staged_runtime[
            "evaluator_authority"
        ]
        self._action_ball_evaluator_source = staged_runtime[
            "evaluator_source"
        ]
        self._action_ball_evaluation_coordinator = staged_runtime[
            "coordinator"
        ]
        self._action_ball_drain_reset_authority = staged_runtime[
            "drain_authority"
        ]
        self._action_ball_drain_reset_source = staged_runtime[
            "drain_source"
        ]
        schedule = staged_runtime["schedule"]
        self._action_ball_eval_last_request_step = schedule[
            "last_request_step"
        ]
        self._action_ball_eval_profile_cursor = schedule["profile_cursor"]
        self._action_ball_eval_next_kind_by_uid = dict(
            schedule["next_kind_by_uid"]
        )
        self._action_ball_drain_fence_active = False
        self._action_ball_drain_prepared = False
        self._action_ball_drain_reset_participants = ()
        self._action_ball_broker.load_state_dict(state["broker"])
        self._action_ball_pool.load_state_dict(state["pool"])
        self._action_ball_provider_births = provider_births
        self._action_ball_provider_history = provider_history
        self._action_ball_task_transcript_by_birth = task_transcripts
        self._action_ball_emitted_task_count_by_uid = emitted_task_counts
        self._action_ball_domain_cursor_by_uid = domain_cursors
        self._action_ball_reject_counts = reject_counts
        restored_ledger_tensor = torch.tensor(
            restored_ledger, dtype=torch.long, device=self.device
        )
        if fixed_view:
            self._action_ball_ledger.zero_()
            self._action_ball_fixed_view_ledger.copy_(
                restored_ledger_tensor
            )
        else:
            self._action_ball_ledger.copy_(restored_ledger_tensor)
        self._action_ball_birth_by_env = births
        self._action_ball_task_by_env = tasks
        self._action_ball_task_ref_by_env = (
            task_refs
            if self._action_ball_diagnostic_unauthorized
            else [None] * self.num_envs
        )
        self._counter_rally_task_identity_by_env = counter_rally_tasks
        self._action_ball_action_uid.copy_(
            torch.tensor(env["action_uid"], dtype=torch.long, device=self.device)
        )
        self._action_ball_action_slot.copy_(
            torch.tensor(env["action_slot"], dtype=torch.long, device=self.device)
        )
        self._action_ball_reset_generation.copy_(
            torch.tensor(
                env["reset_generation"], dtype=torch.long, device=self.device
            )
        )
        self._action_ball_swing_generation.copy_(
            torch.tensor(
                env["swing_generation"], dtype=torch.long, device=self.device
            )
        )
        self._action_ball_attempt_active.copy_(
            torch.tensor(
                env["attempt_active"], dtype=torch.bool, device=self.device
            )
        )
        self._action_ball_attempt_action.copy_(
            torch.tensor(
                env["attempt_action_slot"],
                dtype=torch.long,
                device=self.device,
            )
        )
        self._action_ball_attempt_legal.copy_(
            torch.tensor(
                env["attempt_legal"], dtype=torch.bool, device=self.device
            )
        )
        self._action_ball_attempt_hit.copy_(
            torch.tensor(
                env["attempt_hit"], dtype=torch.bool, device=self.device
            )
        )
        self._action_ball_task_wait_highwater = staged_task_wait_state[
            "highwater"
        ]
        self._action_ball_task_valid.copy_(
            torch.tensor(
                staged_task_wait_state["task_valid"],
                dtype=torch.bool,
                device=self.device,
            )
        )
        self._action_ball_task_wait_total_ticks.copy_(
            torch.tensor(
                staged_task_wait_state["total_ticks"],
                dtype=torch.long,
                device=self.device,
            )
        )
        self._action_ball_task_wait_elapsed_ticks.copy_(
            torch.tensor(
                staged_task_wait_state["elapsed_ticks"],
                dtype=torch.long,
                device=self.device,
            )
        )
        self._action_ball_task_wait_last_advance_step = (
            staged_task_wait_state["last_advance_step"]
        )
        for name in self._action_ball_runtime_latch_field_names():
            getattr(self, name).copy_(
                staged_runtime_latches[name].to(device=self.device)
            )
        self._post_strike_elapsed_last_step = staged_runtime_latches[
            "post_strike_elapsed_last_step"
        ]
        self._strike_timing_metrics_step_token = None
        self._strike_timing_metrics_handoff_pending = False
        resume_reset_exclusion = getattr(
            self, "_action_ball_resume_reset_exclusion", None
        )
        if resume_reset_exclusion is None:
            resume_reset_exclusion = torch.zeros(
                self.num_envs, dtype=torch.bool, device=self.device
            )
            self._action_ball_resume_reset_exclusion = (
                resume_reset_exclusion
            )
        elif (
            not torch.is_tensor(resume_reset_exclusion)
            or resume_reset_exclusion.dtype != torch.bool
            or tuple(resume_reset_exclusion.shape) != (self.num_envs,)
        ):
            raise RuntimeError(
                "ActionBall resume reset-exclusion latch is invalid"
            )
        resume_reset_exclusion.copy_(
            self._action_ball_attempt_active
        )
        self._action_ball_reference_term_center_latch.copy_(
            torch.tensor(
                env["reference_term_center_latch"],
                dtype=torch.bool,
                device=self.device,
            )
        )
        self._ensure_strike_window_entry_distance_probe_state()
        self._strike_window_entry_armed.copy_(
            staged_strike_window_entry_armed
        )
        if staged_continuous_protocol is not None:
            self._action_ball_continuous_racket_mutation_version = (
                staged_continuous_protocol["mutation_version"]
            )
            self._action_ball_continuous_racket_mutation_version_device.fill_(
                staged_continuous_protocol["mutation_version"]
            )
            self._action_ball_continuous_racket_mutation_version_device_receipt = None
            self._action_ball_continuous_racket_terminal_resolution_total = (
                staged_continuous_protocol["terminal_resolution_total"]
            )
            self._action_ball_continuous_racket_terminal_resolution_total_device.fill_(
                staged_continuous_protocol["terminal_resolution_total"]
            )
            self._action_ball_continuous_racket_terminal_resolution_total_device_receipt = (
                _action_ball_continuous_tensor_receipt(
                    self._action_ball_continuous_racket_terminal_resolution_total_device
                )
            )
            self._action_ball_continuous_racket_drain_last_update_index = (
                staged_continuous_protocol["drain_last_update_index"]
            )
            self._action_ball_continuous_racket_drain_last_completed_environment_steps = (
                staged_continuous_protocol[
                    "drain_last_completed_environment_steps"
                ]
            )
            self._action_ball_continuous_racket_drain_sequence = (
                staged_continuous_protocol["drain_sequence"]
            )
            self._action_ball_continuous_racket_drain_last_acknowledged_mutation_version = (
                staged_continuous_protocol[
                    "drain_last_acknowledged_mutation_version"
                ]
            )
            # Portable chronology survives cold restore; process-local global
            # drain authority/receipt and tensor epochs do not.  A fresh
            # seven-leaf ACK must rejoin them before R10 may read this leaf.
            self._action_ball_continuous_racket_drain_authority = None
            self._action_ball_continuous_racket_drain_last_acknowledged_receipt = None
            self._action_ball_continuous_racket_checkpoint_live_epoch_receipts = None
            self._action_ball_continuous_racket_checkpoint_live_join_required = True
            self._action_ball_continuous_racket_checkpoint_requires_drain_ack = False
            self._action_ball_continuous_racket_selected_reset_next_serial = (
                staged_continuous_protocol["selected_reset_next_serial"]
            )
            self._action_ball_continuous_racket_drain_poisoned = (
                staged_continuous_protocol["drain_poisoned"]
            )
            self._action_ball_continuous_racket_drain_poison_reason = (
                staged_continuous_protocol["drain_poison_reason"]
            )
            self._action_ball_continuous_racket_active_ppo_drain_pack = None
        self._action_ball_last_rollout_step = last_step
        if staged_adaptive_sigma is not None:
            self._action_ball_commit_adaptive_sigma_state(
                staged_adaptive_sigma
            )

    def _bind_event_timing_contract(self) -> None:
        """Bind every immutable schedule row to this exact train bank and native clip timing."""

        motion = self._motion_term
        if motion is None or not motion.event_timing_enabled:
            self._event_timing_bound = True
            return
        bank = self._question_bank
        if bank is None:
            # Hard block for continuous too: the immutable event schedule is content-addressed by
            # question_id(incoming_vel) against bank ROWS, and a continuously drawn ball has none.
            raise ValueError(
                "post_strike_t1 requires a schema-v3 train question bank; it is mutually "
                "exclusive with target_mode='solved' (continuous draws have no bank row for the "
                "immutable schedule to reconcile against)"
            )
        metadata = getattr(bank, "metadata", None)
        if (
            not isinstance(metadata, dict)
            or int(metadata.get("schema_version", 0)) != 3
            or metadata.get("split") != "train"
        ):
            raise ValueError("post_strike_t1 requires a validated schema-v3 train-split bank")
        if float(self.cfg.midswing_resample_prob) != 0.0:
            raise ValueError("post_strike_t1 requires midswing_resample_prob=0")

        schedule = motion.event_schedule
        if schedule is None:
            raise RuntimeError("post_strike_t1 has no loaded immutable schedule")
        counts = bank.counts.to(device=self.device, dtype=torch.long)
        # 族寻址(clip_family_per_clip 配了才有;None = 现役行为逐字节不变):日程行的 clip_id
        # 是加载 clip 序号,题库下标要过族表折算。内容寻址的 question_id 对账保持不变——族表
        # 配错时哪怕越界检查侥幸通过,问题指纹也对不上,照样当场炸。
        family_table = self._qb_bank_family_table(motion, bank)
        for flat_index, row in enumerate(schedule.rows):
            if family_table is None:
                bank_clip = row.clip_id
            elif 0 <= row.clip_id < int(family_table.shape[0]):
                bank_clip = int(family_table[row.clip_id])
            else:
                raise ValueError(
                    f"event schedule row {flat_index} references clip {row.clip_id} outside "
                    f"the loaded motion's {int(family_table.shape[0])} clip(s)"
                )
            if bank_clip >= len(counts) or row.bank_row >= int(counts[bank_clip]):
                raise ValueError(
                    f"event schedule row {flat_index} references unavailable train-bank row "
                    f"clip={row.clip_id} bank_row={row.bank_row}"
                )
            incoming = bank.incoming_vel[bank_clip, row.bank_row].detach().cpu().numpy()
            actual_id = question_id(incoming)
            if actual_id != row.question_id:
                raise ValueError(
                    f"event schedule row {flat_index} question_id={row.question_id} does not "
                    f"match train bank clip={row.clip_id} row={row.bank_row} id={actual_id}"
                )

        ml = motion.motion
        nseg = int(ml.num_segments)
        phases_cfg = self._strike_phases_cfg(nseg)
        phases = (
            [float(value) for value in phases_cfg]
            if phases_cfg
            else [float(self.cfg.strike_phase)] * nseg
        )
        files = (
            [motion.cfg.motion_file]
            if isinstance(motion.cfg.motion_file, str)
            else list(motion.cfg.motion_file)
        )
        validate_runtime_motion_contract(
            metadata,
            files,
            [int(value) for value in ml.seg_len.tolist()],
            phases,
            clip_families=(family_table.tolist() if family_table is not None else None),
        )
        native_ticks = []
        for clip_id in range(nseg):
            strike_step, _, seg_start, _ = self._strike_frame_for_clip(ml, clip_id)
            native_ticks.append(strike_step - seg_start)
        motion.bind_event_native_strike_ticks(native_ticks)
        self._event_timing_bound = True

    def _clip_label(self, clip_id: int) -> str:
        """Human clip name for error text. Safe before ``_clip_names`` is assigned in ``__init__``."""
        return getattr(self, "_clip_names", {}).get(int(clip_id), f"clip{clip_id}")

    def _commanded_target_x_hi(self, box_x_hi: float) -> float:
        """Farthest env-frame x a commanded racket target built from ``box_x_hi`` can reach.

        ``hitter_pure`` position boxes are STATION-relative (see :meth:`_sample_targets_hitter_pure`),
        so the commanded station's own forward span rides on top of the box; every other mode adds the
        box straight to the env origin.
        """
        x_hi = float(box_x_hi)
        if self.cfg.target_mode == "hitter_pure":
            x_hi += float(max(self.cfg.base_target_x_range))
        return x_hi

    def _assert_contact_clears_table(
        self, clip_id: int, x_hi: float, z_lo: float, source: str
    ) -> None:
        """Fail closed when a commanded contact point out over the table sits below the ball line.

        Physical rule, from the SAME constants the virtual ball is integrated against
        (``cfg.vb_table_surface_z`` + ``geometry.BALL_RADIUS``): a ball centre can never be lower than
        the table surface plus one ball radius. A commanded strike point past the near table edge
        (``cfg.vb_table_near_x``) with z under that line is unreachable BY CONSTRUCTION — its
        signature is a per-side return rate pinned at exactly 0 with nothing else complaining, which
        is why this is a construction-time error and not a warning.
        人话:桌面以下没有球。目标框/参考击球点掉到桌面以下就当场报错,别再让某一侧的回球率
        无声地钉在 0.0000。
        """
        if float(x_hi) <= float(self.cfg.vb_table_near_x):
            return
        z_min = float(self.cfg.vb_table_surface_z) + self._vb_ball_r
        if float(z_lo) < z_min - 1e-9:
            raise ValueError(
                f"{source}: clip {self._clip_label(clip_id)} commands racket contact down to "
                f"z={float(z_lo):.4f} m, below the minimum legal contact height {z_min:.4f} m "
                f"(vb_table_surface_z={float(self.cfg.vb_table_surface_z):.4f} + ball radius "
                f"{self._vb_ball_r:.4f}). The commanded point reaches x={float(x_hi):.4f} m, past the "
                f"near table edge vb_table_near_x={float(self.cfg.vb_table_near_x):.4f} m, so it lies "
                f"inside/below the table top where no ball can ever be — raise the z floor to "
                f"{z_min:.2f} m"
            )

    def _assert_target_velocity_points_forward(self) -> None:
        """Fail closed when a per-clip target-velocity box can demand a non-forward return.

        +x is toward the opponent (geometry.py world frame), so ``x_lo <= 0`` lets the sampler command
        a return that stalls or travels back at the robot — a shot that can never land on the far half
        however well the policy tracks it.
        """
        if self.cfg.allow_non_forward_target_velocity:
            return
        for clip_id, clip_rng in enumerate(self.cfg.racket_vel_range_per_clip):
            x_lo = float(clip_rng[0][0])
            if x_lo <= 0.0:
                raise ValueError(
                    f"racket_vel_range_per_clip: clip {self._clip_label(clip_id)} has "
                    f"x_lo={x_lo:.4f} <= 0, so the commanded return velocity can point away from the "
                    f"opponent (+x is toward the opponent). Set "
                    f"allow_non_forward_target_velocity=True to command this deliberately"
                )

    def _assert_incoming_ball_boxes_are_sane(self) -> None:
        """Fail closed when a per-clip INCOMING-ball box cannot describe a ball coming at us.

        人话:来球得朝机器人飞。``vb_vel_x_range`` 的 -x 是"冲着机器人来";per-clip 表里哪个 clip
        写成了 x_hi >= 0,那个 clip 的球就可能永远不到拍子跟前,回球率会无声钉在 0——和目标框掉到
        桌面以下同一类的构造期错误,所以当场报错,不 warning。
        """
        for clip_id, clip_rng in enumerate(self.cfg.vb_vel_range_per_clip):
            (x_lo, x_hi), (y_lo, y_hi), (z_lo, z_hi) = clip_rng
            if float(x_hi) >= 0.0:
                raise ValueError(
                    f"vb_vel_range_per_clip: clip {self._clip_label(clip_id)} has "
                    f"x_hi={float(x_hi):.4f} >= 0, but the incoming ball travels toward the robot "
                    f"(-x). A non-negative ceiling lets the sampler launch a ball that flies AWAY, "
                    f"which no stroke can ever answer"
                )
            for name, (lo, hi) in (("x", (x_lo, x_hi)), ("y", (y_lo, y_hi)), ("z", (z_lo, z_hi))):
                if float(lo) > float(hi):
                    raise ValueError(
                        f"vb_vel_range_per_clip: clip {self._clip_label(clip_id)} axis {name} has "
                        f"lo={float(lo):.4f} > hi={float(hi):.4f} — an empty box"
                    )

    def _assert_reference_strike_can_return_its_own_regime(
        self, clip_id: int, p_contact_w, v_racket_w, n_racket_w, face_sign: float = 1.0
    ) -> None:
        """Fail closed when a bound strike frame cannot return ANY ball from THAT clip's regime.

        人话(最重要的一道闸):把这个 clip 自己的来球箱采一批球,用仓库自己的 NumPy 记分器
        (virtual_return_scorer,和训练里评分用的是同一套接触+落点模型)算一下:这个 clip 绑定的
        参考击球状态到底能不能把自己的球打回台上。一个都打不回就当场报错、点名是哪个 clip、
        打回率多少——不要再让某一侧的回球率无声地钉在 0.0000。

        Scored with the repo's OWN NumPy return scorer so the gate and the in-training metric cannot
        disagree; the acceptance threshold is ``reference_return_gate_min_rate`` (0.0 = gate off).
        """
        min_rate = float(getattr(self.cfg, "reference_return_gate_min_rate", 0.0))
        if min_rate <= 0.0:
            return
        try:
            from reference_return_gate import score_reference_returns
        except Exception as exc:                            # pragma: no cover - import path varies
            raise ValueError(
                "reference_return_gate_min_rate > 0 but the repo's NumPy return scorer wrapper "
                "(scripts/reference_return_gate.py: score_reference_returns, built on "
                f"scripts/virtual_return_scorer.py) could not be imported ({exc}). The gate must "
                "not be silently skipped — put scripts/ on sys.path or set "
                "reference_return_gate_min_rate=0.0 deliberately"
            )
        # 采哪个箱子必须跟着"谁在出球"走。连续路径下 vb_vel_range_per_clip 是死的(通用采样器被
        # _solved_targets_active 关掉了),真正出球的是 cq_vel_range_per_clip;不改这里,闸门会拿一
        # 个一颗球都不来自的分布判绿 —— 它不拒绝也不报警,它换了个问题回答,比失效更糟。
        if self._cq_enabled:
            box = self.cfg.cq_vel_range_per_clip[clip_id]
            spin_max = float(self.cfg.cq_spin_abs_max)
        else:
            box = self.cfg.vb_vel_range_per_clip[clip_id] if (
                getattr(self.cfg, "vb_vel_range_per_clip", None) is not None
            ) else (self.cfg.vb_vel_x_range, self.cfg.vb_vel_y_range, self.cfg.vb_vel_z_range)
            spin_max = (
                float(self.cfg.vb_spin_abs_max_per_clip[clip_id])
                if getattr(self.cfg, "vb_spin_abs_max_per_clip", None) is not None
                else float(self.cfg.vb_spin_abs_max)
            )
        rate = float(score_reference_returns(
            p_contact_w=p_contact_w, v_racket_w=v_racket_w, n_racket_w=n_racket_w,
            vel_box=box, spin_abs_max=spin_max,
            surface_z=float(self.cfg.vb_table_surface_z),
            near_x=float(self.cfg.vb_table_near_x),
            n_samples=int(getattr(self.cfg, "reference_return_gate_samples", 256)),
            seed=int(getattr(self.cfg, "reference_return_gate_seed", 0)),
            face_sign=float(face_sign),
        ))
        if rate < min_rate:
            raise ValueError(
                f"reference strike gate: clip {self._clip_label(clip_id)} returns only "
                f"{rate:.4f} of the balls in its OWN incoming regime "
                f"(vel box {tuple(tuple(float(v) for v in ax) for ax in box)}, |spin| <= "
                f"{spin_max:.1f} rad/s), below reference_return_gate_min_rate={min_rate:.4f}. "
                f"The bound strike frame cannot answer the balls this clip will be posed — fix the "
                f"strike phase, the clip, or that clip's ball box; a 0.0000 per-clip return rate "
                f"must never be discovered from a training curve"
            )

    def _strike_phases_cfg(self, nseg: int) -> tuple:
        """cfg.strike_phase_per_clip validated against the loaded motion's segment count (fail-loud).

        Empty tuple = use the scalar strike_phase for every clip (the documented default). Any OTHER
        length means the per-clip table and the loaded clips no longer line up — every env would
        strike at a wrong frame — so raise instead of silently falling back to the global phase.
        人话:每个 clip 的击球点表和实际加载的 clip 数对不上就当场报错,不再悄悄用全局值凑合。
        """
        spc = tuple(self.cfg.strike_phase_per_clip)
        if spc and len(spc) != nseg:
            raise ValueError(
                f"strike_phase_per_clip has {len(spc)} entries but the loaded motion has {nseg} "
                f"segment(s) — align it with the motion_file clip order, or set () to use "
                f"strike_phase={self.cfg.strike_phase} for every clip"
            )
        # _strike_frame_for_clip adds round(p * (seg_len - 1)) to the segment start with NO clamp, so a
        # phase outside [0, 1] silently reads a NEIGHBOURING clip's pose as this clip's strike frame.
        # TODO: the stronger check — the phase must land inside the clip's compiled contact window —
        # needs the binding manifest, which the plain motion_file path does not carry.
        out_of_range = [(i, float(p)) for i, p in enumerate(spc) if not 0.0 <= float(p) <= 1.0]
        if out_of_range:
            raise ValueError(
                f"strike_phase_per_clip entries must lie in [0, 1] (fraction along the clip); "
                f"got {out_of_range} as (clip index, value)"
            )
        return spc

    def _mount_signs_cfg(self, nseg: int) -> tuple:
        """Resolve striking-face signs from the measured teacher or cfg (fail-loud).

        人话:每个 clip 的击球面符号表和实际加载的 clip 数对不上就当场报错(照 _strike_phases_cfg
        先例),不悄悄退回标量符号凑合——那样反手又会被按错误的一面判分还不吭声。空表 = 全部 clip 用
        标量 mount_normal_sign(文档化的默认,现役行为逐位不变)。符号只认 ±1:0 会把法向悄悄清零,
        其他值会把"单位法向"变成带模长的向量,奖励核和角度误差全被污染,所以也当场报错。

        measured_channel 模式下,重定向求解器选出的逐动作拍面是权威。cfg/
        manifest 可以重复声明但必须逐项相同；不同就拒绝启动，避免实测 teacher 和机器人
        FK 实际面相差 180°。
        """
        mns = tuple(self.cfg.mount_normal_sign_per_clip)
        if mns and len(mns) != nseg:
            raise ValueError(
                f"mount_normal_sign_per_clip has {len(mns)} entries but the loaded motion has {nseg} "
                f"segment(s) — align it with the motion_file clip order, or set () to use "
                f"mount_normal_sign={self.cfg.mount_normal_sign} for every clip"
            )
        if any(float(s) not in (1.0, -1.0) for s in mns):
            raise ValueError(
                f"mount_normal_sign_per_clip entries must be +1 or -1 (which paddle FACE strikes), "
                f"got {mns}"
            )
        if str(getattr(self.cfg, "motion_teacher_racket_source", "robot_fk")) == "measured_channel":
            loader = self._motion().motion
            measured = tuple(
                int(value)
                for value in getattr(
                    loader, "measured_racket_mount_normal_sign_per_clip", ()
                )
            )
            if len(measured) != nseg or any(value not in (-1, 1) for value in measured):
                raise RuntimeError(
                    "measured_channel requires one admitted robot mount-normal sign per motion clip"
                )
            if mns and tuple(int(float(value)) for value in mns) != measured:
                raise ValueError(
                    "mount_normal_sign_per_clip disagrees with the measured-racket retarget "
                    f"authority: configured={mns}, measured={measured}"
                )
            return measured
        return mns

    def _clip_family_is_forehand(self) -> torch.Tensor:
        """[num_segments] bool 表:True = 该 clip 属正手家族(懒构建 + fail-loud)。

        人话:替换四处写死的"clips==0 才是正手"判断(spdmix v2 硬绑定一)。没配
        task.motion.clip_family_per_clip 时按老规矩推——单 clip 当正手、恰好 2 clip = (正手, 反手),
        和写死判断逐字节同值(现役所有在跑臂);≥3 clip 缺表当场报错,不猜。配了表按表取:同一家族的
        变速 clip(如正手 0.8/1.0/1.2)swing_sign、swing_type 观测、目标侧全一致。解析/校验规则的
        单一来源是 commands.resolve_clip_family_is_forehand(和 MotionCommand 开机校验同一份)。
        """
        if self._family_is_forehand_t is None:
            motion = self._motion()
            self._family_is_forehand_t = torch.tensor(
                resolve_clip_family_is_forehand(
                    getattr(getattr(motion, "cfg", None), "clip_family_per_clip", None),
                    int(motion.motion.num_segments),
                ),
                dtype=torch.bool,
                device=self.device,
            )
        return self._family_is_forehand_t

    def _clip_family_rows(self) -> torch.Tensor:
        """[num_segments] long 表:每个加载 clip 的家族行号(0=正手族, 1=反手族;懒构建缓存)。

        人话(spdmix v2 硬绑定四配套):HER 缓存、per-族指标累计器、"每族一行"的框表全都按
        家族分桶。legacy 2-clip 下行号恒等于 clip_id(正手=0、反手=1),所有消费点逐字节不变;
        6-clip 变速列表里正手 0.8/1.0/1.2 三档同落 0 行、反手三档同落 1 行。单一来源 =
        _clip_family_is_forehand()(boot 已整表校验;≥3 clip 缺族表在那里当场报人话错误)。
        """
        rows = getattr(self, "_clip_family_rows_t", None)
        if rows is None:
            rows = (~self._clip_family_is_forehand()).to(dtype=torch.long)
            self._clip_family_rows_t = rows
        return rows

    def _metric_bucket_rows(self) -> torch.Tensor:
        """[num_segments] long:每个 clip 的**指标桶**行号(缓存)。

        人话(硬绑定四的下一步):`cfg.clip_names_per_clip` 没配时,桶就是家族行号——现役所有在跑
        臂逐字节不变。配了名字表,桶就是 clip_id 本身,每个动作一个桶。家族语义仍归
        `_clip_family_rows()`:回放/框表按族展开/题库按族寻址都不动。
        """
        # getattr defaults, like _clip_family_rows: the older unit-test fakes build the command with
        # __new__ and set only a handful of fields, and a metric bucket must never be the thing that
        # explodes on them.
        rows = getattr(self, "_metric_bucket_rows_t", None)
        if rows is not None:
            return rows
        if not getattr(self, "_metric_buckets_per_clip", False):
            rows = self._clip_family_rows()
        else:
            nseg = int(self._motion().motion.num_segments)
            if nseg != len(self._clip_names):
                raise ValueError(
                    f"racket_target.clip_names_per_clip has {len(self._clip_names)} name(s) "
                    f"{sorted(self._clip_names.values())} but the loaded motion has {nseg} "
                    f"clip(s) — give one name per loaded clip, in motion_file order; a short "
                    f"name table would put two clips in one metric bucket"
                )
            rows = torch.arange(nseg, dtype=torch.long, device=self.device)
        self._metric_bucket_rows_t = rows
        return rows

    def _metric_bucket_accounting_enabled(self, motion=None) -> bool:
        """Whether named/family metric buckets must receive events.

        ``MotionCommand._multiseg`` answers a motion-layout question, not a telemetry question.
        A deliberately single-segment N=1 run still declares ``clip_names_per_clip=(action_id,)``
        so its public counters are named after that action.  Treating ``_multiseg`` as the writer
        gate registered those counters but left every one at zero.  Explicit names therefore turn
        bucket accounting on even when the one loaded clip is not concatenated; an unnamed legacy
        single-clip run remains on the old aggregate-only path.

        This predicate is telemetry-only.  Sampling, HER replay, motion timing, Reward, PPO and
        curriculum continue to use their own motion/task predicates.
        """

        if motion is None:
            motion = self._motion()
        return bool(
            getattr(motion, "_multiseg", False)
            or getattr(self, "_metric_buckets_per_clip", False)
        )

    def _per_clip_range_rows(self, table: torch.Tensor, cfg_key: str) -> torch.Tensor:
        """把 cfg 的 per-clip 框表对齐成"每个加载 clip 一行"((num_segments, 3, 2),缓存)。

        人话(spdmix v2 硬绑定四 = 六 clip boot 炸的真凶):racket_pos/vel_range_per_clip 只有
        正/反手两行,六 clip 列表拿 clip_id(0..5)直接进 GPU gather,越界不当场报错,而是异步
        CUDA device-side assert,尸体倒在下一个同步点(_strike_frame_for_clip 的 .item()),
        traceback 指向无辜的 seg_start。这里在任何 gather 之前按行数核对:

        * 行数 == 加载段数:按 clip 逐行用(legacy 2-clip 原张量原样返回,逐字节不变);
        * 行数 == 2 且段数 != 2:按 clip_family_per_clip 族表把"每族一行"展开成"每 clip 一行"
          (同族变速档共享该族的框;族表缺席时 _clip_family_is_forehand 自己报人话错误);
        * 其他组合:当场 ValueError 报人话,绝不让越界下标进 GPU。
        """
        cache = getattr(self, "_per_clip_range_rows_cache", None)
        if cache is None:
            cache = {}
            self._per_clip_range_rows_cache = cache
        cached = cache.get(cfg_key)
        if cached is not None:
            return cached
        nseg = int(self._motion().motion.num_segments)
        rows = int(table.shape[0])
        if rows == nseg:
            expanded = table
        elif rows == 2:
            # 每族一行:按族表展开(0=正手行, 1=反手行)。族表缺席时下一行当场报人话错误。
            expanded = table[self._clip_family_rows()]
        else:
            raise ValueError(
                f"task.racket.{cfg_key} has {rows} row(s) but the loaded motion has {nseg} "
                f"clip(s) — give one row per loaded clip (motion_file then motion_file_2 order), "
                f"or exactly 2 rows (forehand, backhand) plus task.motion.clip_family_per_clip "
                f"so each speed variant reuses its family's box"
            )
        cache[cfg_key] = expanded
        return expanded

    # ------------------------------------------------------------------ continuous questions ---
    @property
    def _solved_targets_active(self) -> bool:
        """目标是不是"逆解出来的答案"(题库行 或 连续缓冲行)。

        人话:仓库里有一批门,写的是"有没有题库",想问的其实是"目标是不是解出来的"。那批门必须
        改问这个属性,否则连续路径下它们会**静默失效** —— 而一个静默失效的门,正是"解出来的目标
        最后被什么都不打分"的走法。判据用 cfg 级的 ``_cq_enabled`` 而不是缓冲对象,因为缓冲是
        懒建的:第一次 resample 之前它还是 None,而那些门在更早就要给出正确答案。
        """
        return (
            self._question_bank is not None
            or self._cq_enabled
            or self._action_ball_enabled
        )

    def _cq_prm(self):
        """Venue ball params, shared with the scorer's own lazy load (one model, one object)."""
        if self._vb_params is None:
            from whole_body_tracking.tasks.tracking.mdp import virtual_ball as _vb
            self._vb_params = _vb.load_venue_params()
            print(
                f"[RacketTargetCommand] virtual ball ON (continuous solve): venue constants from "
                f"{self._vb_params.source_path}",
                flush=True,
            )
        return self._vb_params

    def _cq_planes(self) -> tuple[float, float, float]:
        """(surface_z, net_x, net_top_z) — THE SAME NUMBERS THE SCORER USES, read from the same
        fields, never re-derived.

        人话:"你解的那个面,就是你被打分的那个面"是靠共用同一个属性保证的,不是靠两处各写一遍
        同一个数字。表面用 surface + 球半径(球心过平面),和 _vb_evaluate 的 :4493 / 题库生成器
        逐字一致;裸 0.76 会让求解落在离评分面 20 mm 的另一张桌子上。
        """
        prm = self._cq_prm()
        return (
            float(self.cfg.vb_table_surface_z) + float(prm.ball_radius),
            float(self._vb_net_x),
            float(self._vb_net_top_z) + float(self._vb_ball_r),
        )

    def _cq_ref_normals(self) -> torch.Tensor:
        """(nseg, 3) RUNTIME raw +Y clip face — what the continuous answers are sign-aligned to.

        题库是离线对齐到 npz 里烤死的 clip_normal、再由 _check_question_bank_face_frame 在运行时
        核 dot>0;连续路径直接对齐到**运行时**这张 FK 面,所以那条 dot>0 卫兵在这里恒真,漂移
        无从发生(没有可以对不上的第二份数)。
        """
        self._ensure_reference_strike_state()
        ref = self._ref_racket_normal_raw_w_per_clip
        if ref is None:
            raise RuntimeError("reference strike-state initialization produced no raw face normals")
        return ref

    def _cq_build_cfg(self, nseg: int):
        """Freeze the ContinuousQuestionCfg for this run (once). Every field comes from cfg."""
        if self._cq_cfg is not None:
            return self._cq_cfg
        from .continuous_questions import ContinuousQuestionCfg

        if self._pos_range_per_clip_t is None:
            raise ValueError(
                "target_mode='solved' needs racket.racket_pos_range_per_clip as the contact-point "
                "draw box"
            )
        pos_rows = self._per_clip_range_rows(
            self._pos_range_per_clip_t, "racket_pos_range_per_clip")
        if self.cfg.cq_vel_range_per_clip is None:
            raise ValueError("target_mode='solved' needs racket.cq_vel_range_per_clip")
        vel_t = torch.tensor(
            [[[float(lo), float(hi)] for (lo, hi) in clip_rng]
             for clip_rng in self.cfg.cq_vel_range_per_clip],
            dtype=torch.float32, device=self.device,
        )
        vel_rows = self._per_clip_range_rows(vel_t, "cq_vel_range_per_clip")
        aim = self.cfg.cq_aim_xy
        aim_x, aim_y = (
            (float(self.cfg.vb_target_x), float(self.cfg.vb_target_y)) if aim is None
            else (float(aim[0]), float(aim[1]))
        )
        self._cq_cfg = ContinuousQuestionCfg(
            vel_range_per_clip=vel_rows,
            pos_range_per_clip=pos_rows,
            spin_abs_max=float(self.cfg.cq_spin_abs_max),
            # DEGENERATE aim on purpose — the single point the landing reward / virtual_land_err_m /
            # the physical ball's return flight all grade against (see cq_aim_xy's cfg comment).
            aim_x_range=(aim_x, aim_x),
            aim_y_range=(aim_y, aim_y),
            tol_m=float(self.cfg.cq_tol_m),
            n_iters=int(self.cfg.cq_n_iters),
            speed_budget=float(self.cfg.cq_speed_budget),
            max_redraw_rounds=int(self.cfg.cq_max_redraw_rounds),
            fixed_direction=False,
        )
        del nseg
        return self._cq_cfg

    def _cq_bucket_of(self, v_in_x: torch.Tensor, clip_rows: torch.Tensor) -> torch.Tensor:
        """Per-regime bucket index = |v_in_x| bin crossed with the clip. (Both axes are a CHOICE.)

        人话:这是唯一能看见"重画循环把难的那条尾巴悄悄削掉"的仪表 —— 有 overdraw 之后
        ``exhausted`` 会整轮读 0,而全局 reject 直方图看不出是哪一档球消失了。
        """
        nb = max(1, int(self.cfg.cq_accept_buckets))
        lo = self._cq["vx_lo"][clip_rows]
        hi = self._cq["vx_hi"][clip_rows]
        u = ((v_in_x.abs() - lo) / (hi - lo).clamp(min=1e-6)).clamp(0.0, 1.0 - 1e-6)
        return clip_rows * nb + (u * nb).long()

    def _cq_note(self, name: str, amount) -> None:
        ledger = self._ensure_exact_behavior_decision_counters()
        if name in ledger:
            ledger[name] += int(amount)

    @torch.no_grad()
    def _cq_refill(self) -> None:
        """Solve ONE big batch and refill the buffer. Only ``ok=True`` rows are ever admitted.

        人话:失败策略在代码里的落点只有这一条线 —— 缓冲只收解出来的行。生产者把无解行整行填
        NaN,所以就算这条掩码哪天被删,装进去的也是 NaN 而不是一个看起来很像答案的东西;两层都
        在,才叫结构性。
        """
        from .continuous_questions import generate

        if self._cq is not None and "count" in self._cq:
            # A refill throws away whatever the old buffer had left (a drought refill can happen
            # before the cursor reaches the end). Book it, so "the reservoir is provably not a
            # small bank" stays auditable from the hourly log rather than being assumed.
            self._cq_note(
                "continuous_question_rows_discarded_count",
                int((self._cq["count"] - self._cq["cursor"]).clamp(min=0).sum()),
            )
        motion = self._motion()
        nseg = int(motion.motion.num_segments)
        cqcfg = self._cq_build_cfg(nseg)
        prm = self._cq_prm()
        surface_z, net_x, net_top_z = self._cq_planes()
        ref_all = self._cq_ref_normals()[:nseg]                      # (nseg,3)
        P = int(self.cfg.cq_buffer_rows)
        per = int(math.ceil(P * float(self.cfg.cq_overdraw)))
        clip_ids = torch.arange(nseg, device=self.device).repeat_interleave(per)
        if self._cq_gen is None:
            # Dedicated stream so the question draw is reproducible independently of every other
            # sampler's consumption pattern (the resume path stores its state; see _cq_state_dict).
            self._cq_gen = torch.Generator(device=self.device)
            self._cq_gen.manual_seed(int(self.cfg.cq_seed))
        res = generate(
            clip_ids, prm, surface_z=surface_z, net_x=net_x, cfg=cqcfg,
            ref_normal=ref_all[clip_ids], net_top_z=net_top_z, generator=self._cq_gen,
            # ONE source for the rollout parameters: the scorer's. They happen to equal the
            # solver's defaults today, which is exactly the kind of coincidence that rots.
            h=float(self.cfg.vb_rollout_h), n_steps=int(self.cfg.vb_rollout_steps),
        )
        n_draw = int(clip_ids.shape[0])
        self._cq_note("continuous_question_draw_count", n_draw)
        self._cq_note("continuous_question_exhausted_count", int(res.exhausted))
        self._cq_note("continuous_question_refill_count", 1)
        self._cq_note("continuous_question_redraw_round_sum", int(res.rounds_used))
        for name, cnt in (res.reason_counts or {}).items():
            self._cq_note(f"continuous_question_reject_{name}_count", int(cnt))

        keep = res.ok.clone()
        # FACE CAP. After sign alignment dot>0 is tautological, so the residual risk is "same side
        # but wildly off"; this is the knob that watches it. Shipped banks: p50 7.8-9.1, max 20.3.
        ang = torch.rad2deg(torch.arccos(
            torch.sum(torch.nan_to_num(res.n_racket) * ref_all[clip_ids], dim=-1).clamp(-1.0, 1.0)))
        face_bad = keep & (ang > float(self.cfg.cq_max_face_deg))
        self._cq_note("continuous_question_reject_face_deg_over_cap_count", int(face_bad.sum()))
        keep = keep & ~face_bad
        # EXAM HOLDOUT. Keep the repo invariant that no TRAINED question is an exam question, so a
        # paired exam comparison is not grading the policy on balls it trained on.
        if bool(self.cfg.cq_exam_holdout):
            from .stage1_question_bank import question_split

            v_np = torch.nan_to_num(res.v_ball_in).detach().cpu().numpy()
            is_exam = torch.tensor(
                [question_split(row) == "exam" for row in v_np],
                dtype=torch.bool, device=self.device,
            ) & keep
            self._cq_note("continuous_question_reject_exam_holdout_count", int(is_exam.sum()))
            keep = keep & ~is_exam

        exh_frac = float(res.exhausted) / max(1, n_draw)
        self._cq_last_exhausted_frac = exh_frac
        if exh_frac > float(self.cfg.cq_abort_exhausted_frac):
            raise RuntimeError(
                f"continuous question refill: {res.exhausted}/{n_draw} drawn balls have NO legal "
                f"answer after {res.rounds_used} redraw round(s) ({exh_frac * 100:.1f}% > "
                f"{float(self.cfg.cq_abort_exhausted_frac) * 100:.0f}%). reasons={res.reason_counts}. "
                f"This is a task-construction error (an incoming box that cannot be returned to the "
                f"aim point within the speed budget), not a hyperparameter — fix "
                f"racket.cq_vel_range_per_clip / racket_pos_range_per_clip / cq_speed_budget."
            )
        if exh_frac > float(self.cfg.cq_max_exhausted_frac):
            print(
                f"[RacketTargetCommand] WARN continuous refill: exhausted {res.exhausted}/{n_draw} "
                f"({exh_frac * 100:.1f}%) reasons={res.reason_counts}",
                flush=True,
            )

        # --- per-clip buffers, cursor at 0 ------------------------------------------------------
        vel_rows = cqcfg.vel_range_per_clip
        vx_lo = torch.minimum(vel_rows[:, 0, 0].abs(), vel_rows[:, 0, 1].abs())
        vx_hi = torch.maximum(vel_rows[:, 0, 0].abs(), vel_rows[:, 0, 1].abs())
        if self._cq is None:
            self._cq = {"vx_lo": vx_lo, "vx_hi": vx_hi}
        self._cq["vx_lo"], self._cq["vx_hi"] = vx_lo, vx_hi

        nb = max(1, int(self.cfg.cq_accept_buckets))
        asked_b = self._cq_bucket_of(torch.nan_to_num(res.attempted_v_ball_in)[:, 0], clip_ids)
        asked = torch.bincount(asked_b, minlength=nseg * nb)
        kept_b = self._cq_bucket_of(torch.nan_to_num(res.v_ball_in)[keep][:, 0], clip_ids[keep])
        kept = torch.bincount(kept_b, minlength=nseg * nb)
        for c in range(nseg):
            for b in range(nb):
                idx = c * nb + b
                self._cq_note(f"continuous_question_bucket{c}_{b}_asked_count", int(asked[idx]))
                self._cq_note(f"continuous_question_bucket{c}_{b}_kept_count", int(kept[idx]))
                a_i, k_i = int(asked[idx]), int(kept[idx])
                if a_i >= 2000 and k_i == 0:
                    raise RuntimeError(
                        f"continuous question refill: clip {self._clip_label(c)} |v_in_x| bucket "
                        f"{b}/{nb} asked {a_i} balls and kept ZERO. The declared incoming box has "
                        f"a regime with no legal answer at all, so the run's real distribution is "
                        f"not the one its yaml declares. Narrow cq_vel_range_per_clip or raise "
                        f"cq_speed_budget."
                    )
                if a_i >= 500 and k_i > 0 and (k_i / a_i) < float(self.cfg.cq_min_accept_rate):
                    print(
                        f"[RacketTargetCommand] WARN continuous accept: clip "
                        f"{self._clip_label(c)} |v_in_x| bucket {b}/{nb} accept "
                        f"{k_i}/{a_i} = {k_i / a_i:.3f} < {float(self.cfg.cq_min_accept_rate)} — "
                        f"the hard tail of the declared box is being thinned out by the redraw "
                        f"loop, and `exhausted` cannot show it",
                        flush=True,
                    )

        buf_pos, buf_vin, buf_win, buf_vr, buf_nr, buf_diff, buf_cnt = [], [], [], [], [], [], []
        discarded = 0
        for c in range(nseg):
            m = keep & (clip_ids == c)
            idx = torch.nonzero(m, as_tuple=False).flatten()
            if idx.numel() > P:
                discarded += int(idx.numel() - P)
                idx = idx[:P]
            if idx.numel() == 0:
                raise RuntimeError(
                    f"continuous question refill produced ZERO usable rows for clip "
                    f"{self._clip_label(c)} out of {per} draws — refusing to hand out a target "
                    f"that was never solved. reasons={res.reason_counts}"
                )
            buf_pos.append(res.p_contact[idx])
            buf_vin.append(res.v_ball_in[idx])
            buf_win.append(res.w_ball_in[idx])
            buf_vr.append(res.v_racket[idx])
            buf_nr.append(res.n_racket[idx])
            buf_diff.append(ang[idx])
            buf_cnt.append(int(idx.numel()))
        width = max(buf_cnt)

        def _pad(rows_list, dim):
            out = torch.zeros(nseg, width, dim, device=self.device) if dim > 1 else \
                torch.zeros(nseg, width, device=self.device)
            for c, rows in enumerate(rows_list):
                out[c, : rows.shape[0]] = rows
            return out

        self._cq.update({
            "pos": _pad(buf_pos, 3), "v_in": _pad(buf_vin, 3), "w_in": _pad(buf_win, 3),
            "v_r": _pad(buf_vr, 3), "n_r": _pad(buf_nr, 3), "diff": _pad(buf_diff, 1),
            "count": torch.tensor(buf_cnt, dtype=torch.long, device=self.device),
            "cursor": torch.zeros(nseg, dtype=torch.long, device=self.device),
        })
        n_admit = int(sum(buf_cnt))
        self._cq_note("continuous_question_admitted_count", n_admit)
        self._cq_note("continuous_question_rows_discarded_count", discarded)
        self._cq_note(
            "continuous_question_resid_um_sum",
            int((torch.nan_to_num(res.resid_m[keep], posinf=0.0) * 1e6).sum()),
        )
        self._cq_closed_loop_check()

    @torch.no_grad()
    def _cq_closed_loop_check(self) -> None:
        """Re-roll a subsample of the ADMITTED rows through the SCORER's own call and hard-fail.

        人话:题库是离线验一次(``validation.max_landing_error_m <= 0.10``,
        stage1_question_bank.py:402-413);连续路径每换一批都验一次。诚实说明范围:求解器和评分器
        今天用同一套 h/n_steps(下面 boot 时断言),所以这条检查抓的是**平面/帧/参数漂移**,不是
        积分器分歧 —— 它是唯一能抓到"求解的那张桌子和打分的那张桌子不是同一张"的东西,而 resid_m
        结构上抓不到(它是自评的)。
        """
        rows = int(self.cfg.cq_closed_loop_rows)
        if rows <= 0 or self._cq is None:
            return
        from whole_body_tracking.tasks.tracking.mdp import virtual_ball as _vb

        prm = self._cq_prm()
        surface_z, net_x, _net_top = self._cq_planes()
        pos = self._cq["pos"].reshape(-1, 3)
        cnt_mask = torch.zeros(pos.shape[0], dtype=torch.bool, device=self.device)
        width = int(self._cq["pos"].shape[1])
        for c, k in enumerate(self._cq["count"].tolist()):
            cnt_mask[c * width: c * width + int(k)] = True
        idx = torch.nonzero(cnt_mask, as_tuple=False).flatten()
        if idx.numel() == 0:
            return
        take = idx[torch.randperm(idx.numel(), device=self.device)[:rows]]
        v_plus, w_plus = _vb.predict_paddle_contact(
            self._cq["v_in"].reshape(-1, 3)[take], self._cq["v_r"].reshape(-1, 3)[take],
            self._cq["n_r"].reshape(-1, 3)[take], self._cq["w_in"].reshape(-1, 3)[take], prm,
        )
        land = _vb.coarse_landing(
            pos[take], v_plus, w_plus, prm, surface_z=surface_z, net_x=net_x,
            h=float(self.cfg.vb_rollout_h), n_steps=int(self.cfg.vb_rollout_steps),
        )
        err = torch.linalg.norm(land["land_xy"] - self._vb_target_xy.unsqueeze(0), dim=-1)
        err = torch.where(land["land_valid"], err, torch.full_like(err, float("inf")))
        worst = float(err.max())
        self._cq_note("continuous_question_closed_loop_um_sum",
                      int((torch.nan_to_num(err, posinf=0.0) * 1e6).sum()))
        self._cq_note("continuous_question_closed_loop_row_count", int(take.numel()))
        bad = int((err > float(self.cfg.cq_closed_loop_max_err_m)).sum())
        self._cq_note("continuous_question_closed_loop_fail_count", bad)
        if bad:
            raise RuntimeError(
                f"continuous question refill failed its own closed-loop check: {bad}/"
                f"{int(take.numel())} admitted answers land more than "
                f"{float(self.cfg.cq_closed_loop_max_err_m)} m from the aim when re-rolled through "
                f"the SCORER's call (worst {worst:.4f} m). The solver and the scorer are not "
                f"looking at the same table/net/frame."
            )

    @torch.no_grad()
    def _cq_take(self, clip_rows: torch.Tensor, n: int):
        """Hand out ``n`` rows WITHOUT REPLACEMENT, same 6-tuple shape as ``select_questions``.

        人话:每道题只发一次,发完就丢。这不是题库,是缓冲。改成有放回抽取 = 它立刻退化成一张
        8192 行的滚动题库,也就是 owner 明确否掉的那个东西,而且没有任何断言会响。
        """
        if self._cq is None or "count" not in self._cq:
            self._cq_refill()
        nseg = int(self._cq["count"].shape[0])
        need = torch.bincount(clip_rows, minlength=nseg)
        left = self._cq["count"] - self._cq["cursor"]
        if bool((need > left).any()):
            # DROUGHT: refill synchronously for the shortfall. No branch reuses a row, reorders by
            # resid, or substitutes — if the fresh batch is still short, that is a raise.
            self._cq_note("continuous_question_pool_dry_count", 1)
            self._cq_refill()
            left = self._cq["count"] - self._cq["cursor"]
            if bool((need > left).any()):
                self._cq_note("continuous_question_pool_underflow_count", 1)
                raise RuntimeError(
                    f"continuous question buffer underflow after a fresh refill: need "
                    f"{need.tolist()} rows per clip, have {left.tolist()}. Raise "
                    f"racket.cq_buffer_rows / cq_overdraw. Nothing was reused or substituted."
                )
        out_pos = torch.zeros(n, 3, device=self.device)
        out_vin = torch.zeros(n, 3, device=self.device)
        out_win = torch.zeros(n, 3, device=self.device)
        out_vr = torch.zeros(n, 3, device=self.device)
        out_nr = torch.zeros(n, 3, device=self.device)
        out_diff = torch.zeros(n, device=self.device)
        for c in range(nseg):
            sel = torch.nonzero(clip_rows == c, as_tuple=False).flatten()
            k = int(sel.numel())
            if k == 0:
                continue
            start = int(self._cq["cursor"][c])
            rows = torch.arange(start, start + k, device=self.device)
            out_pos[sel] = self._cq["pos"][c, rows]
            out_vin[sel] = self._cq["v_in"][c, rows]
            out_win[sel] = self._cq["w_in"][c, rows]
            out_vr[sel] = self._cq["v_r"][c, rows]
            out_nr[sel] = self._cq["n_r"][c, rows]
            out_diff[sel] = self._cq["diff"][c, rows]
            self._cq["cursor"][c] = start + k          # 游标只前进,行发过就永远不再出现
        self._cq_note("continuous_question_install_count", n)
        return out_pos, out_vin, out_win, out_vr, out_nr, out_diff

    @torch.no_grad()
    def _cq_boot_gate(self) -> None:
        """Boot-time contract anchor + parity gate for the continuous path. Runs ONCE, lazily.

        人话:连续训练把题库的四条溯源丢了两条,这里把它们拿回来 —— 用一份**同族的、完整校验过
        的**题库当**契约锚**:加载它就跑物理契约(ball physics 改了 = 和 bank 臂一模一样的开机
        报错,而不是训练分布悄悄变了)和运行时动作契约(motion SHA / 段长 / strike_phase)。它
        **一行都不参与训练**,只做两件事:锁契约,和给下面这个 parity 断言当数据。

        parity 用的是 pytest 里那**同一个函数**(continuous_questions.parity_report),所以"两条
        路同物理"从一句离线 pytest 声明,变成这台机器、这个 commit 上的既成事实。
        """
        self._cq_boot_gate_done = True          # 先置位:失败要炸,不要变成每步重试
        path = str(getattr(self.cfg, "cq_anchor_bank", "") or "").strip()
        if not path:
            # 到不了这里:_assert_solved_target_recipe_is_coherent 已经把空锚拦在构造期了。留着是
            # 因为"必须开的东西"只该有一条政策 —— 不能上面报错、这里降级成一行 WARN。
            raise ValueError(
                "continuous questions cannot run WITHOUT a contract anchor "
                "(racket.cq_anchor_bank is empty): no physics-contract SHA, no runtime motion "
                "contract, and no boot parity gate. Point it at a same-family schema-v3 train "
                "bank — it is never trained on."
            )
        from .continuous_questions import parity_report

        motion = self._motion()
        nseg = int(motion.motion.num_segments)
        _order = _peek_question_bank_clip_order(path)
        _names = tuple(_order) if _order else tuple(
            str(x) for x in (getattr(self.cfg, "clip_names_per_clip", ()) or ())
        ) or ("forehand", "backhand")
        # The loader itself runs validate_runtime_physics_contract + the split check.
        anchor = load_question_bank(path, device=self.device, clip_names=_names,
                                    allow_legacy=False, expected_split="train")
        family_table = self._qb_bank_family_table(motion, anchor)
        if anchor.metadata:
            files = ([motion.cfg.motion_file] if isinstance(motion.cfg.motion_file, str)
                     else list(motion.cfg.motion_file))
            phases_cfg = self._strike_phases_cfg(nseg)
            phases = ([float(v) for v in phases_cfg] if phases_cfg
                      else [float(self.cfg.strike_phase)] * nseg)
            validate_runtime_motion_contract(
                anchor.metadata, files,
                [int(v) for v in motion.motion.seg_len.tolist()], phases,
                clip_families=(family_table.tolist() if family_table is not None else None),
            )
        self._cq_anchor = anchor

        prm = self._cq_prm()
        surface_z, net_x, net_top_z = self._cq_planes()
        ref_all = self._cq_ref_normals()[:nseg]
        meta = anchor.metadata or {}
        land = meta.get("landing_env") or [float(self.cfg.vb_target_x), float(self.cfg.vb_target_y)]
        aim_pt = torch.tensor([float(land[0]), float(land[1])], device=self.device)
        budget = float(meta.get("speed_budget") or 4.0)
        K = 128
        for c in range(nseg):
            fam = c if family_table is None else int(family_table[c])
            q = int(anchor.counts[fam])
            if q <= 0:
                continue
            k = min(K, q)
            rows = torch.arange(k, device=self.device)
            p_c = anchor.contact_pos[fam].unsqueeze(0).expand(k, 3)
            rep = parity_report(
                p_c, anchor.incoming_vel[fam, rows], anchor.incoming_spin[fam, rows],
                aim_pt.unsqueeze(0).expand(k, 2), ref_all[c].unsqueeze(0).expand(k, 3),
                anchor.demanded_vel[fam, rows], anchor.demanded_normal[fam, rows],
                prm, surface_z=surface_z, net_x=net_x, net_top_z=net_top_z,
                speed_budget=budget, tol_m=0.005, n_iters=int(self.cfg.cq_n_iters),
                h=float(self.cfg.vb_rollout_h), n_steps=int(self.cfg.vb_rollout_steps),
            )
            if rep["failures"]:
                raise RuntimeError(
                    f"continuous-vs-bank boot parity gate FAILED on anchor {path!r} clip "
                    f"{self._clip_label(c)}:\n  - " + "\n  - ".join(rep["failures"])
                    + f"\nstats={rep['stats']}"
                )
            print(
                f"[RacketTargetCommand] continuous boot parity OK: clip {self._clip_label(c)} "
                f"{k} anchor rows, {rep['stats']}",
                flush=True,
            )

    def _cq_hard_contract(self) -> dict | None:
        """What produced this run's targets, for the checkpoint hard contract. None when off.

        人话:没有这一块,checkpoint 对"目标是怎么产生的"一个字都不记 —— 因为 bank_path_cfg 是
        空的,现在的 question_bank 直接是 None,可复现性会掉到前题库时代以下。
        """
        if not self._cq_enabled:
            return None
        from .stage1_question_bank import (
            canonical_sha256, runtime_physics_contract, sha256_file,
        )

        motion = self._motion()
        nseg = int(motion.motion.num_segments)
        cqcfg = self._cq_build_cfg(nseg)
        surface_z, net_x, net_top_z = self._cq_planes()
        declared = {
            "pos_range_per_clip": cqcfg.pos_range_per_clip.tolist(),
            "vel_range_per_clip": cqcfg.vel_range_per_clip.tolist(),
            "spin_abs_max": float(cqcfg.spin_abs_max),
            "aim_xy": [float(cqcfg.aim_x_range[0]), float(cqcfg.aim_y_range[0])],
            "exam_holdout": bool(self.cfg.cq_exam_holdout),
            "max_face_deg": float(self.cfg.cq_max_face_deg),
            "seed": int(self.cfg.cq_seed),
        }
        anchor = self._cq_anchor
        return {
            "producer": "continuous_inline_solve_v1",
            "cfg_sha256": canonical_sha256(declared),
            "declared": declared,
            "physics_contract_sha256": canonical_sha256(runtime_physics_contract()),
            "solver": {
                "n_iters": int(cqcfg.n_iters), "tol_m": float(cqcfg.tol_m),
                "speed_budget": float(cqcfg.speed_budget),
                "max_redraw_rounds": int(cqcfg.max_redraw_rounds),
                "rollout_h": float(self.cfg.vb_rollout_h),
                "rollout_steps": int(self.cfg.vb_rollout_steps),
            },
            # The three planes ACTUALLY handed to the solver, not the cfg values they came from.
            "planes": {"surface_z": surface_z, "net_x": net_x, "net_top_z": net_top_z},
            "ref_normal_source": "runtime_ref_racket_normal_raw_w_per_clip",
            "anchor_bank": (None if anchor is None else {
                "sha256": sha256_file(anchor.source_path),
                "schema_version": int((anchor.metadata or {}).get("schema_version", 0)),
                "split": (anchor.metadata or {}).get("split"),
                "source_family_sha256": (anchor.metadata or {}).get("source_family_sha256"),
                "trained_on": False,
            }),
        }

    def _cq_state_dict(self) -> dict:
        """Cursor/fill state for the exact-resume path (the buffer is run state, not derived)."""
        if self._cq is None or "count" not in self._cq:
            return {"filled": False}
        return {
            "filled": True,
            "cursor": self._cq["cursor"].tolist(),
            "count": self._cq["count"].tolist(),
            "generator": (None if self._cq_gen is None else self._cq_gen.get_state()),
        }

    def _qb_bank_family_table(self, motion, bank) -> torch.Tensor | None:
        """clip→题库族查表 ((nseg,) long;forehand 族=0 行, backhand 族=1 行),或 None。

        人话(spdmix v2 硬绑定二):题库永远只有正/反手两族题;6-clip 变速列表里每个 clip 先查
        自己属于哪族,再拿族号当题库下标。cfg.motion.clip_family_per_clip 没配(现役所有在跑臂)
        返回 None,调用方直接拿 clip_id 当题库下标——行为逐字节不变。配了表就复用
        _clip_family_is_forehand()(和 swing_sign 同一份 boot 已整表校验的表)折成题库行号;
        族寻址的允许 motion SHA 列表住在 schema-v3 元数据里,legacy 题库配族表当场报错,不猜。
        """
        if getattr(getattr(motion, "cfg", None), "clip_family_per_clip", None) is None:
            return None
        if self._qb_family_table is None:
            metadata = getattr(bank, "metadata", None)
            if not metadata:
                raise ValueError(
                    "clip_family_per_clip requires a schema-v3 question bank: a legacy bank "
                    "carries no per-family motion-SHA contract to reconcile the extra speed "
                    "clips against (allow_legacy 题库不配变速族表)"
                )
            order = list(metadata.get("clip_order") or [])
            declared = [str(n) for n in (getattr(self.cfg, "clip_names_per_clip", ()) or ())]
            _m = getattr(motion, "motion", motion)
            _nseg = int(getattr(_m, "num_segments", 0) or 0)
            if declared and order == declared and (_nseg == 0 or _nseg == len(order)):
                # PER-CLIP bank (chingmu101 whole-library arm, 2026-07-28): the bank carries
                # ONE row per loaded clip (clip_order == racket clip_names, 1:1), so clip_id
                # IS the bank row. Return None = the identity addressing every
                # family_table-None caller implements, and the exact contract
                # validate_runtime_motion_contract(clip_families=None) verifies (per-clip
                # SHA/n_frames/anchor). The (forehand, backhand) 2-row convention below only
                # binds when a many-clip motion list shares a 2-family bank (spdmix 变速表).
                return None
            if order != ["forehand", "backhand"]:
                raise ValueError(
                    f"question bank clip_order {order!r} does not match the (forehand, "
                    f"backhand) family convention required by clip_family_per_clip"
                )
            is_forehand = self._clip_family_is_forehand()
            self._qb_family_table = (~is_forehand).to(dtype=torch.long)
        return self._qb_family_table

    def _strike_frame_for_clip(self, motion, clip_id: int) -> tuple[int, float, int, int]:
        """Return (global strike frame, phase, segment start, segment len) for one reference clip."""
        nseg = int(motion.num_segments)
        if clip_id < 0 or clip_id >= nseg:
            raise IndexError(f"clip_id {clip_id} out of range for {nseg} segments")
        seg_start = int(motion.seg_start[clip_id].item())
        seg_len = int(motion.seg_len[clip_id].item())
        spc = self._strike_phases_cfg(nseg)
        phase = float(spc[clip_id]) if spc else float(self.cfg.strike_phase)
        strike_step = seg_start + round(phase * (seg_len - 1))
        return int(strike_step), phase, seg_start, seg_len

    def _ref_racket_pos_at(
        self,
        motion,
        f: int,
        *,
        clip_start: int = 0,
        clip_end: int | None = None,
    ) -> torch.Tensor:
        """Racket-center FK position (env-origin rel) at reference frame ``f``.

        Uses the SAME FK as :meth:`_compute_racket_state` /
        :meth:`_ensure_reference_strike_state` (racket body, or wrist + constant mount offset) but reads
        the reference MOTION's body poses. ``f`` is clamped to the requested clip segment so clean
        centered-difference velocities never leak across a concatenated forehand/backhand boundary.
        """
        total = max(int(motion.time_step_total), 1)
        hi = total - 1 if clip_end is None else int(clip_end)
        lo = int(clip_start)
        f = int(max(lo, min(hi, f)))
        if self._racket_mode == "body":
            return motion._body_pos_w[f, self._racket_body_index]
        widx = self._wrist_body_index
        wpos = motion._body_pos_w[f, widx]
        wquat = motion._body_quat_w[f, widx]
        offset_w = quat_apply(wquat.unsqueeze(0), self._mount_offset[0:1]).squeeze(0)
        return wpos + offset_w

    def _ensure_reference_strike_state(self):
        """Cache per-clip reference racket/base states at each clip's strike frame.

        Target sampling in ``reference_perturbed`` mode must be centered on the exact teacher clip the
        env is imitating. The old single cached state was fine for one clip, but a unified forehand+
        backhand policy needs separate strike position, velocity, face normal, and base->racket reach
        offsets for each concatenated MotionLoader segment.
        """
        if self._ref_strike_cached:
            return
        motion = self._motion().motion  # MotionLoader
        nseg = int(motion.num_segments)
        pos_all = torch.zeros(nseg, 3, device=self.device)
        vel_all = torch.zeros(nseg, 3, device=self.device)
        quat_all = torch.zeros(nseg, 4, device=self.device)
        ang_all = torch.zeros(nseg, 3, device=self.device)
        nrm_all = torch.zeros(nseg, 3, device=self.device)
        nrm_raw_all = torch.zeros(nseg, 3, device=self.device)
        base_all = torch.zeros(nseg, 3, device=self.device)
        reach_all = torch.zeros(nseg, 2, device=self.device)
        W = max(1, int(self.cfg.clean_strike_vel_window))
        dt = float(self._env.step_dt)
        report_lines = []
        # 每 clip 的击球面符号(空表 = 标量,现役行为不变)。参考拍面法向也要按 clip 翻面:诊断报表
        # 和参考锁定的拍面目标(_ref_normal_per_clip)都从这里出,必须和判分的那一面(实际击球面)一致。
        _mount_signs = self._mount_signs_cfg(nseg)

        for clip_id in range(nseg):
            strike_step, phase, seg_start, seg_len = self._strike_frame_for_clip(motion, clip_id)
            seg_end = seg_start + seg_len - 1
            if self._racket_mode == "body":
                idx = self._racket_body_index
                pos, quat, lin, ang = self._reference_body_state(
                    motion, strike_step, idx, require_ang_vel=True
                )
            else:
                widx = self._wrist_body_index
                wpos, wquat, wlin, wang = self._reference_body_state(motion, strike_step, widx, require_ang_vel=True)
                offset_w = quat_apply(wquat.unsqueeze(0), self._mount_offset[0:1]).squeeze(0)
                pos = wpos + offset_w
                lin = wlin + torch.cross(wang, offset_w, dim=-1)
                quat = quat_mul(wquat.unsqueeze(0), self._mount_quat[0:1]).squeeze(0)
                ang = wang
            if ang is None or not bool(torch.isfinite(ang).all()):
                raise RuntimeError(
                    "reference racket angular velocity is unavailable/non-finite "
                    f"at action {clip_id} strike"
                )
            # 击球面符号按 clip 取(正手一面、反手另一面);表为空用标量符号(现役行为逐位不变)。
            _sgn = float(_mount_signs[clip_id]) if _mount_signs else float(self.cfg.mount_normal_sign)
            normal_raw = matrix_from_quat(quat.unsqueeze(0))[0, :, self.cfg.mount_normal_axis]
            normal = normal_raw * _sgn

            # --- clean reference strike velocity --------------------------------------------------
            # Recompute the strike target velocity from the FINAL racket FK position by a centered
            # finite difference (clamped to this clip's segment), so it is consistent with the
            # position the policy actually tracks (the stored body_lin_vel_w is FD'd/interpolated and
            # ~1 m/s inconsistent at the racket tip — see cfg docs). raw_lin is retained only as
            # a diagnostic: the NPZ channel is a COM-point velocity and is not the controlled site.
            raw_lin = lin.detach().clone()
            fd1 = (
                self._ref_racket_pos_at(motion, strike_step + 1, clip_start=seg_start, clip_end=seg_end)
                - self._ref_racket_pos_at(motion, strike_step - 1, clip_start=seg_start, clip_end=seg_end)
            ) / (2.0 * dt)
            clean_lin = (
                self._ref_racket_pos_at(motion, strike_step + W, clip_start=seg_start, clip_end=seg_end)
                - self._ref_racket_pos_at(motion, strike_step - W, clip_start=seg_start, clip_end=seg_end)
            ) / (2.0 * W * dt)
            if not self.cfg.clean_reference_strike_velocity:
                raise RuntimeError(
                    "clean_reference_strike_velocity=false is no longer a valid racket contract: "
                    "motion body_lin_vel_w is a COM-point channel, not the URDF racket site. "
                    "Use the point-consistent centered difference."
                )
            lin = clean_lin

            pos_all[clip_id] = pos.detach().clone()
            vel_all[clip_id] = lin.detach().clone()
            quat_all[clip_id] = quat.detach().clone()
            ang_all[clip_id] = ang.detach().clone()
            nrm_all[clip_id] = (normal / (torch.norm(normal) + 1e-6)).detach().clone()
            # Raw (+Y/A-frame) twin — the question-bank A-frame guard compares against this one.
            nrm_raw_all[clip_id] = (normal_raw / (torch.norm(normal_raw) + 1e-6)).detach().clone()
            # Reference base (root) at the strike — root is articulation body index 0 (same order the
            # motion arrays use). The base->racket horizontal offset couples base_target to racket_target.
            base_all[clip_id] = self._reference_body_state(motion, strike_step, 0)[0].detach().clone()
            reach_all[clip_id] = (pos_all[clip_id, :2] - base_all[clip_id, :2]).detach().clone()

            cname = self._clip_names.get(clip_id, f"clip{clip_id}")
            p = pos_all[clip_id]
            v = vel_all[clip_id]
            nrm = nrm_all[clip_id]
            b = base_all[clip_id]
            off = reach_all[clip_id]
            report_lines.append(
                f"  {cname}: strike frame {strike_step}/{seg_end} (phase {phase:.3f}) "
                f"pos=({float(p[0]):.3f},{float(p[1]):.3f},{float(p[2]):.3f}) "
                f"vel=({float(v[0]):.3f},{float(v[1]):.3f},{float(v[2]):.3f}) "
                f"|v|={float(torch.norm(v)):.2f} "
                f"normal=({float(nrm[0]):.3f},{float(nrm[1]):.3f},{float(nrm[2]):.3f}) "
                f"baseXY=({float(b[0]):.3f},{float(b[1]):.3f}) "
                f"reachXY=({float(off[0]):.3f},{float(off[1]):.3f}) "
                f"raw_speed={float(torch.norm(raw_lin)):.3f} "
                f"clean_speed={float(torch.norm(clean_lin)):.3f} "
                f"raw_clean_diff={float(torch.norm(raw_lin - clean_lin)):.3f} "
                f"raw_fd_diff={float(torch.norm(raw_lin - fd1)):.3f}"
                f" |omega|={float(torch.norm(ang)):.3f}"
            )

        self._ref_racket_pos_rel_per_clip = pos_all
        self._ref_racket_vel_w_per_clip = vel_all
        self._ref_racket_quat_w_per_clip = quat_all
        self._ref_racket_ang_vel_w_per_clip = ang_all
        self._ref_racket_normal_w_per_clip = nrm_all
        self._ref_racket_normal_raw_w_per_clip = nrm_raw_all
        self._ref_base_pos_rel_per_clip = base_all
        self._ref_reach_offset_xy_per_clip = reach_all
        # Legacy single-clip fields (no in-file consumers besides diagnostics): mirror clip 0.
        self._ref_racket_pos_rel = pos_all[0].detach().clone()
        self._ref_racket_vel_w = vel_all[0].detach().clone()
        self._ref_racket_normal_w = nrm_all[0].detach().clone()
        self._ref_base_pos_rel = base_all[0].detach().clone()
        self._ref_reach_offset_xy = reach_all[0].detach().clone()
        self._ref_strike_cached = True
        print(
            "[RacketTargetCommand] reference strike centers per clip "
            f"(clean_reference_strike_velocity={self.cfg.clean_reference_strike_velocity}, window=+-{W}):\n"
            + "\n".join(report_lines),
            flush=True,
        )
        # Table-clearance gate, reference half. It has to live HERE and not in __init__: the motion term
        # is unresolved at construction (see the _ref_strike_cached comment above), so this is the first
        # moment the reference strike point — the target CENTRE in reference_perturbed mode — exists.
        # Placed after the report so the operator sees every clip's numbers before the raise. The x is
        # the reference point's own — no station term: reference_perturbed derives base_target FROM the
        # racket target, so base_target_x_range moves the BASE, never the commanded contact point.
        for clip_id in range(nseg):
            self._assert_contact_clears_table(
                clip_id,
                float(pos_all[clip_id, 0]),
                float(pos_all[clip_id, 2]),
                "reference strike point",
            )
        # RETURN gate, same placement rationale: this is the first moment the bound strike state
        # exists, so it is the first moment we can ask whether it returns THIS CLIP'S OWN balls.
        # pos_all/vel_all are env-origin-relative / world; the scorer needs one consistent
        # env-local frame with z above the FLOOR, which is exactly what pos_all already is.
        # TIME LAW under a solved/banked target: the retiming scale is DEAD for the target (the
        # answer is solved at the ball, not read off a retimed clip) but it still divides the
        # time-to-strike the actor sees. Leaving it non-unity is therefore a silent inconsistency,
        # not a variation. Checked here because the motion term is unresolved at __init__.
        _solved = bool(str(getattr(self.cfg, "question_bank", "") or "").strip()) or \
            str(getattr(self.cfg, "target_mode", "")) == "solved"
        if _solved:
            # KNOWN-DEAD FOR BANK ARMS, DELIBERATELY NOT REPAIRED HERE. ``motion`` was bound above
            # as ``self._motion().motion`` — a MotionLoader, which stores no cfg — so this getattr
            # always yields None and the guard has never once fired. Repairing it would refuse
            # EVERY currently running arm at boot (all five run question_bank=... together with
            # motion.speed_scale_range=[0.6,1.0], and the same code is in the pin they execute
            # from). That is its own decision — "is the rule wrong or are the arms wrong?" — and it
            # does not belong in a wiring change mid-wave.
            # The NEW path does not get to ship with a guard that can never fire, so the continuous
            # source reads the real MotionCommand cfg. No continuous arm exists yet, so nothing
            # running can be refused by this scoping.
            _mcfg = getattr(motion, "cfg", None)
            if self._cq_enabled:
                _mcfg = getattr(self._motion(), "cfg", None)
            _rng = tuple(float(x) for x in (getattr(_mcfg, "speed_scale_range", (1.0, 1.0))
                                            or (1.0, 1.0)))
            if _rng != (1.0, 1.0):
                raise ValueError(
                    f"task.motion.speed_scale_range={_rng} with a solved/banked racket target: the "
                    f"retiming scale no longer shapes the TARGET (it is solved at the ball) but it "
                    f"still divides the actor's time-to-strike, so a non-unity range is a silent "
                    f"inconsistency between the command and the clock. Set "
                    f"motion.speed_scale_range: [1.0, 1.0]"
                )
            _spc = getattr(_mcfg, "speed_scale_per_clip", None)
            if _spc is not None and any(float(s) != 1.0 for s in _spc):
                raise ValueError(
                    f"task.motion.speed_scale_per_clip={tuple(float(s) for s in _spc)} with a "
                    f"solved/banked racket target — same inconsistency as speed_scale_range; set "
                    f"every entry to 1.0"
                )
        _signs = self._mount_signs_cfg(nseg)
        for clip_id in range(nseg):
            self._assert_reference_strike_can_return_its_own_regime(
                clip_id,
                pos_all[clip_id].detach().cpu().numpy(),
                vel_all[clip_id].detach().cpu().numpy(),
                nrm_all[clip_id].detach().cpu().numpy(),
                float(_signs[clip_id]) if _signs else float(self.cfg.mount_normal_sign),
            )

    def _reference_body_state(self, motion, step: int, body_index: int, require_ang_vel: bool = False):
        """Return reference body state from MotionLoader's full-articulation private arrays.

        This is the current, intentional coupling point to upstream ``MotionLoader`` internals. Public
        ``MotionCommand`` buffers expose only the tracking subset, while the racket FK needs the full
        articulation body order so it can read the racket body or wrist mount. Keep direct private-field
        access centralized here until MotionLoader grows a public full-body state API.
        """
        required = ["_body_pos_w", "_body_quat_w", "_body_lin_vel_w"]
        if require_ang_vel:
            required.append("_body_ang_vel_w")
        missing = [name for name in required if not hasattr(motion, name)]
        if missing:
            raise AttributeError(
                "RacketTargetCommand requires MotionLoader full-body reference arrays "
                f"{required}, but missing {missing}. This is the HOPE coupling point for "
                "reference_perturbed racket FK; update _reference_body_state if upstream MotionLoader changes."
            )

        pos = motion._body_pos_w[step, body_index]
        quat = motion._body_quat_w[step, body_index]
        lin = motion._body_lin_vel_w[step, body_index]
        ang = motion._body_ang_vel_w[step, body_index] if require_ang_vel else None
        return pos, quat, lin, ang

    def _perturb_scale(self) -> float:
        """Curriculum factor in [start, 1.0] that widens the reference perturbation over training.

        Success-gated mode (default): return the running ``_curr_perturb_scale``, which advances only
        when the policy demonstrates exact-strike success (see :meth:`_update_metrics`). Otherwise fall
        back to the legacy open-loop ramp keyed to ``env.common_step_counter``. The returned scale is
        clamped to ``[ref_perturb_curriculum_start, 1.0]``.
        """
        start = float(self.cfg.ref_perturb_curriculum_start)
        if self.cfg.target_mode == "reference_perturbed" and self.cfg.ref_perturb_success_gated:
            scale = self._curr_perturb_scale
        else:
            steps = float(getattr(self._env, "common_step_counter", 0))
            c = float(self.cfg.ref_perturb_curriculum_steps)
            frac = 1.0 if c <= 0.0 else min(1.0, steps / c)
            scale = start + (1.0 - start) * frac
        return min(1.0, max(start, scale))

    def _ensure_ref_normal_per_clip(self):
        """Cache the reference paddle face normal at each clip's strike frame ([num_segments, 3]).

        行数守卫(人话):这张表马上要被 motion.clip_id gather;行数和加载段数对不上就当场报
        人话错误,而不是让 GPU 越界变成一句没人看得懂的 CUDA device-side assert。
        """
        if self._ref_normal_per_clip is None:
            self._ensure_reference_strike_state()
            if self._ref_racket_normal_w_per_clip is None:
                raise RuntimeError("reference strike-state initialization produced no face normals")
            self._ref_normal_per_clip = self._ref_racket_normal_w_per_clip
        nseg = int(self._motion().motion.num_segments)
        rows = int(self._ref_normal_per_clip.shape[0])
        if rows != nseg:
            raise RuntimeError(
                f"per-clip reference face-normal cache has {rows} row(s) but the loaded motion "
                f"has {nseg} clip(s) — the cache is stale for this motion list; it must be "
                f"rebuilt with one row per loaded clip before any clip_id lookup"
            )

    def _sample_targets_uniform(self, env_ids: Sequence[int], origins: torch.Tensor, n: int):
        """Independent box sampling (legacy mode). Ranges are PLACEHOLDERS not tied to the swing."""
        pos = origins.clone()
        motion = self._motion()
        if self._pos_range_per_clip_t is not None and motion._multiseg:
            # PER-CLIP position box (unified policy): each env samples x/y/z from ITS clip's box (added to
            # the env origin). The y range is SIGNED per clip (the configured box is used directly, so a
            # near-center backhand box is valid and does not go through the shared +/-|y| fallback). This
            # replaces the shared x-range + |y|-sign + z-range logic below and lets each clip track its own
            # reference strike point.
            clip = motion.clip_id[env_ids]                      # (n,) long clip ids on the loaded list
            # 行数先对齐再 gather(spdmix v2 硬绑定四):两行家族框 + 六 clip 直接下标会越界成
            # 异步 CUDA assert;_per_clip_range_rows 先按族展开/当场报人话错误。
            rng_e = self._per_clip_range_rows(
                self._pos_range_per_clip_t, "racket_pos_range_per_clip"
            )[clip]                                             # (n, 3, 2): [env][x/y/z][lo/hi]
            lo = rng_e[..., 0]                                  # (n, 3)
            hi = rng_e[..., 1]                                  # (n, 3)
            pos[:, :3] += lo + (hi - lo) * torch.rand(n, 3, device=self.device)
        else:
            # Shared box (legacy / single-clip): identical sampling to before — backward compatible.
            pos[:, 0] += sample_uniform(*self.cfg.racket_pos_x_range, (n,), self.device)
            if motion._multiseg:
                # Unified policy: the target Y region is conditioned on the swing FAMILY so forehand and
                # backhand regions are non-overlapping (HITTER §IV). Sample |y| and set the sign per clip
                # via the family table (clip_family_per_clip; absent = the legacy (forehand, backhand)
                # 2-clip derivation, byte-identical to the old clips==0 hardcode): forehand-family clips
                # on -y if forehand_on_negative_y, backhand-family clips on the opposite side.
                clip = motion.clip_id[env_ids]
                ymag = sample_uniform(*self.cfg.racket_pos_y_abs_range, (n,), self.device)
                fh_sign = -1.0 if self.cfg.forehand_on_negative_y else 1.0
                sign = torch.where(self._clip_family_is_forehand()[clip], fh_sign, -fh_sign)
                pos[:, 1] = origins[:, 1] + sign * ymag
            else:
                pos[:, 1] += sample_uniform(*self.cfg.racket_pos_y_range, (n,), self.device)
            pos[:, 2] += sample_uniform(*self.cfg.racket_pos_z_range, (n,), self.device)
        self.racket_target_pos_w[env_ids] = pos

        if self._vel_range_per_clip_t is not None and motion._multiseg:
            # PER-CLIP velocity (unified policy): each env samples from ITS clip's box, so the slower
            # backhand gets a lower target speed than the forehand instead of one shared box that
            # overshoots the backhand. Vectorized: gather each env's clip range, then uniform-sample.
            clip = motion.clip_id[env_ids]                      # (n,) long clip ids on the loaded list
            rng_e = self._per_clip_range_rows(
                self._vel_range_per_clip_t, "racket_vel_range_per_clip"
            )[clip]                                             # (n, 3, 2): [env][x/y/z][lo/hi]
            lo = rng_e[..., 0]                                  # (n, 3)
            hi = rng_e[..., 1]                                  # (n, 3)
            vel = lo + (hi - lo) * torch.rand(n, 3, device=self.device)
        else:
            # Shared box (legacy / single-clip): identical sampling to before — backward compatible.
            vel = torch.empty(n, 3, device=self.device)
            vel[:, 0] = sample_uniform(*self.cfg.racket_vel_x_range, (n,), self.device)
            vel[:, 1] = sample_uniform(*self.cfg.racket_vel_y_range, (n,), self.device)
            vel[:, 2] = sample_uniform(*self.cfg.racket_vel_z_range, (n,), self.device)
        if motion.retiming_active:
            # R14: the vel boxes are centered on the clips' NATIVE strike velocities; a swing replayed
            # at speed s can only deliver ~s× that, so scale the demand (reference-target consistency).
            vel = vel * motion.speed_scale[env_ids].unsqueeze(-1)
        self.racket_target_vel_w[env_ids] = vel

        # --- HER-style achieved-target replay (mixture) --------------------------------------------
        # With prob achieved_target_mix_prob, overwrite the freshly box-sampled pos+vel with a jittered
        # PREVIOUSLY-ACHIEVED strike state from this clip's ring buffer (written at exact-strike frames
        # in _update_metrics). Replayed targets are reachable-by-demonstration, so the target
        # distribution stops asking for points the taught swing never passes through (Ace/HER, adapted
        # forward-looking for on-policy PPO — retroactive relabel would be obs-inconsistent). Clamped
        # into the per-clip box inflated by achieved_clamp_inflate so replay can neither collapse the
        # target support nor drift outside the deploy runner's hand-synced target clips. Non-replayed
        # envs keep the pure box sample; the per-clip reference normal below is shared by both paths.
        # Hard-gated on the question bank (belt to the init-time force-off braces): the bank
        # override below would clobber every replayed target, so the replay draw AND the
        # _resample_n_acc/_replay_n_acc accounting must never run — achieved_replay_frac would
        # otherwise report replays that no env ever trained on.
        # 判据是"目标是不是解出来的"。锁在 bank 对象上时,连续路径下这个块会真的跑、烧 RNG 和
        # 算力、推高 _resample_n_acc/_replay_n_acc,然后被后面的连续覆盖清掉 —— 正好复现报错
        # 文案里描述的"撒谎的 achieved_replay_frac"。
        if (self.cfg.achieved_target_mix_prob > 0.0 and not self._solved_targets_active
                and motion._multiseg):
            env_ids_t = torch.as_tensor(env_ids, dtype=torch.long, device=self.device)
            clip_all = motion.clip_id[env_ids_t]
            # 按族分桶(spdmix v2 硬绑定四):缓存桶是正/反手两族;legacy 2-clip 下族行号==clip_id,
            # 逐字节不变;6-clip 变速档按族共享缓存,不再有 clip 2..5 永远选不中桶的哑弹。
            fam_all = self._metric_bucket_rows()[clip_all]
            replay = torch.rand(n, device=self.device) < float(self.cfg.achieved_target_mix_prob)
            self._resample_n_acc += float(n)
            infl = 1.0 + float(self.cfg.achieved_clamp_inflate)
            for c in self._clip_names:
                fill = self._ach_fill.get(c, 0)
                if fill < int(self.cfg.achieved_min_fill):
                    continue
                sel = replay & (fam_all == c)
                m = int(sel.sum())
                if m == 0:
                    continue
                rows = torch.randint(0, fill, (m,), device=self.device)
                rpos = self._ach_pos[c][rows] + (torch.rand(m, 3, device=self.device) * 2.0 - 1.0) * float(
                    self.cfg.achieved_jitter_pos
                )
                rvel_c = self._ach_vel[c][rows]
                if motion.retiming_active:
                    # R14: achieved velocities carry their SOURCE swing's playback speed; rescale to
                    # the replaying swing's own s so a slowed swing is not asked for a fast strike.
                    s_now = motion.speed_scale[env_ids_t[sel]]
                    rvel_c = rvel_c * (s_now / self._ach_spd[c][rows].clamp(min=1e-6)).unsqueeze(-1)
                rvel = rvel_c + (torch.rand(m, 3, device=self.device) * 2.0 - 1.0) * float(
                    self.cfg.achieved_jitter_vel
                )
                # 夹回各 env 自己 clip 的框(经 _per_clip_range_rows 对齐,行数保证够;
                # legacy 2-clip 下行 == 族桶行,数值逐字节不变)。
                clips_sel = clip_all[sel]
                if self._pos_range_per_clip_t is not None:
                    box = self._per_clip_range_rows(
                        self._pos_range_per_clip_t, "racket_pos_range_per_clip"
                    )[clips_sel]                                 # (m, 3, 2)
                    lo, hi = box[..., 0], box[..., 1]
                    ctr, half = (lo + hi) * 0.5, (hi - lo) * 0.5 * infl
                    rpos = torch.min(torch.max(rpos, ctr - half), ctr + half)
                if self._vel_range_per_clip_t is not None:
                    box = self._per_clip_range_rows(
                        self._vel_range_per_clip_t, "racket_vel_range_per_clip"
                    )[clips_sel]                                 # (m, 3, 2)
                    lo, hi = box[..., 0], box[..., 1]
                    ctr, half = (lo + hi) * 0.5, (hi - lo) * 0.5 * infl
                    if motion.retiming_active:
                        # R14: clamp replayed velocities into the box scaled by THIS swing's playback
                        # speed, so replay does not demand native-speed strikes from a slowed swing.
                        s_sel = motion.speed_scale[env_ids_t[sel]].unsqueeze(-1)
                        rvel = torch.min(torch.max(rvel, (ctr - half) * s_sel), (ctr + half) * s_sel)
                    else:
                        rvel = torch.min(torch.max(rvel, ctr - half), ctr + half)
                ids_sel = env_ids_t[sel]
                self.racket_target_pos_w[ids_sel] = self._env.scene.env_origins[ids_sel] + rpos
                self.racket_target_vel_w[ids_sel] = rvel
                self._replay_n_acc += float(m)

        if motion._multiseg:
            # Unified policy: the target paddle normal is the imitated swing's actual face normal at
            # strike (reachable by the imitation). The sampled racket velocity is the SWING-PATH direction,
            # which is ~18-110 deg off the +Y blade face, so normal_mode=velocity makes the normal goal
            # unsatisfiable (normal_pass=0 -> composite success stuck at 0).
            self._ensure_ref_normal_per_clip()
            clip = motion.clip_id[env_ids]
            normal = self._ref_normal_per_clip[clip]
        elif self.cfg.normal_mode == "velocity":
            normal = vel / (torch.norm(vel, dim=-1, keepdim=True) + 1e-6)
        else:  # "sampled"
            normal = torch.empty(n, 3, device=self.device)
            normal[:, 0] = sample_uniform(*self.cfg.racket_normal_x_range, (n,), self.device)
            normal[:, 1] = sample_uniform(*self.cfg.racket_normal_y_range, (n,), self.device)
            normal[:, 2] = sample_uniform(*self.cfg.racket_normal_z_range, (n,), self.device)
            normal = normal / (torch.norm(normal, dim=-1, keepdim=True) + 1e-6)
        self.racket_target_normal_w[env_ids] = normal

        # Stage-1 question bank: overrides pos/vel + target_normal_cmd for these envs (no-op when off).
        self._apply_question_bank_targets(env_ids, origins, n)

    def _sample_targets_hitter_pure(
        self, env_ids: Sequence[int], origins: torch.Tensor, n: int, resample_base: bool = True
    ):
        """HITTER-faithful sampling (arXiv:2508.21043 §V-B-1 + §IV-C), 2026-07-07.

        Order and frames follow the paper exactly:

        1. BASE STATION first, sampled INDEPENDENTLY around the env origin (world frame) from
           ``base_target_x_range`` / ``base_target_y_range`` (which are the STATION BOX here, not a
           jitter — paper Fig. 4 evaluates initial station distances up to ±0.8 m).
        2. RACKET TARGET on a striking plane FIXED RELATIVE TO THE COMMANDED STATION ("0.4 m in
           front of the robot" on their G1; our A3 analog is the clips' blade reach x ≈ 0.70 m):
           the per-clip ``racket_pos_range_per_clip`` boxes are interpreted as STATION-RELATIVE
           x/y offsets (x degenerate = the fixed plane, y = the swing-side band) with z absolute
           above the ground. Forehand/backhand y-bands must be non-overlapping (paper §V-B-1).
        3. RACKET VELOCITY from the per-clip velocity boxes (world frame), then the target FACE
           NORMAL from ``normal_mode``: "velocity" = the paper's §IV-C impact model ("the racket
           plane is perpendicular to its velocity vector") — the policy must LEARN to orient the
           blade; do NOT fall back to the reference-clip normal here (that made the normal term
           trivially satisfied and is why deployed models could touch balls but not return them).

        No HER replay, no reference_reach coupling, no curriculum in this mode.

        ``resample_base=False`` (mid-swing refinement path): keep the CURRENT station and only
        re-draw the racket target/velocity around it — the paper's Fig. 3 refinement converges on
        WHERE the ball arrives; it never teleports the commanded stance mid-swing.
        """
        motion = self._motion()
        if self._pos_range_per_clip_t is None or self._vel_range_per_clip_t is None:
            raise RuntimeError(
                "target_mode='hitter_pure' requires racket_pos_range_per_clip AND "
                "racket_vel_range_per_clip (station-relative position boxes; see "
                "HOPEPingPongHitterPure.yaml)."
            )

        # 1) independent base station (world xy, around the env origin).
        if resample_base:
            base_xy = origins[:, :2].clone()
            base_xy[:, 0] += sample_uniform(*self.cfg.base_target_x_range, (n,), self.device)
            base_xy[:, 1] += sample_uniform(*self.cfg.base_target_y_range, (n,), self.device)
            self.base_target_pos_w[env_ids] = base_xy
        else:
            base_xy = self.base_target_pos_w[env_ids].clone()

        # 2) racket target: per-clip STATION-RELATIVE box (x = fixed plane, y = swing band), z above ground.
        if motion._multiseg:
            clip = motion.clip_id[env_ids]
            # 行数先对齐再 gather(spdmix v2 硬绑定四;单 clip 分支 clip 恒 0,历史上就允许
            # 两行表取第 0 行,不动)。
            pos_tab = self._per_clip_range_rows(
                self._pos_range_per_clip_t, "racket_pos_range_per_clip"
            )
            vel_tab = self._per_clip_range_rows(
                self._vel_range_per_clip_t, "racket_vel_range_per_clip"
            )
        else:
            clip = torch.zeros(n, dtype=torch.long, device=self.device)
            pos_tab = self._pos_range_per_clip_t
            vel_tab = self._vel_range_per_clip_t
        rng_e = pos_tab[clip]                                   # (n, 3, 2): [env][x/y/z][lo/hi]
        lo, hi = rng_e[..., 0], rng_e[..., 1]
        off = lo + (hi - lo) * torch.rand(n, 3, device=self.device)
        pos = origins.clone()
        pos[:, 0] = base_xy[:, 0] + off[:, 0]
        pos[:, 1] = base_xy[:, 1] + off[:, 1]
        pos[:, 2] = origins[:, 2] + off[:, 2]
        self.racket_target_pos_w[env_ids] = pos

        # 3) racket velocity (world) + face normal from normal_mode (paper: velocity direction).
        rng_v = vel_tab[clip]
        lo_v, hi_v = rng_v[..., 0], rng_v[..., 1]
        vel = lo_v + (hi_v - lo_v) * torch.rand(n, 3, device=self.device)
        self.racket_target_vel_w[env_ids] = vel

        if self.cfg.normal_mode == "sampled":
            normal = torch.empty(n, 3, device=self.device)
            normal[:, 0] = sample_uniform(*self.cfg.racket_normal_x_range, (n,), self.device)
            normal[:, 1] = sample_uniform(*self.cfg.racket_normal_y_range, (n,), self.device)
            normal[:, 2] = sample_uniform(*self.cfg.racket_normal_z_range, (n,), self.device)
        else:  # "velocity" (paper §IV-C impact model)
            normal = vel.clone()
        self.racket_target_normal_w[env_ids] = normal / (torch.norm(normal, dim=-1, keepdim=True) + 1e-6)

    def _sample_targets_reference_perturbed(self, env_ids: Sequence[int], origins: torch.Tensor, n: int):
        """Target = this env's reference racket state @ strike + curriculum-scaled perturbation.

        The target center is selected by ``motion.clip_id`` for unified forehand+backhand training, so
        the policy no longer has to imitate one teacher strike while chasing a different sampled target.
        """
        self._ensure_reference_strike_state()
        if (self._ref_racket_pos_rel_per_clip is None
                or self._ref_racket_vel_w_per_clip is None
                or self._ref_racket_normal_w_per_clip is None):
            raise RuntimeError("reference strike-state initialization is incomplete")
        motion = self._motion()
        if motion._multiseg:
            clip = motion.clip_id[env_ids]
        else:
            clip = torch.zeros(n, dtype=torch.long, device=self.device)
        ref_pos = self._ref_racket_pos_rel_per_clip[clip]
        ref_vel = self._ref_racket_vel_w_per_clip[clip]
        ref_nrm = self._ref_racket_normal_w_per_clip[clip]

        scale = self._perturb_scale()
        dev = self.device
        pos_h = torch.tensor(self.cfg.ref_perturb_pos, device=dev) * scale
        vel_h = torch.tensor(self.cfg.ref_perturb_vel, device=dev) * scale
        nrm_h = float(self.cfg.ref_perturb_normal) * scale

        dpos = (torch.rand(n, 3, device=dev) * 2.0 - 1.0) * pos_h
        self.racket_target_pos_w[env_ids] = origins + ref_pos + dpos

        dvel = (torch.rand(n, 3, device=dev) * 2.0 - 1.0) * vel_h
        ref_vel_scaled = ref_vel * self.cfg.ref_vel_scale
        if motion.retiming_active:
            # R14: the cached reference strike velocity is native-speed; scale by this swing's playback speed.
            ref_vel_scaled = ref_vel_scaled * motion.speed_scale[env_ids].unsqueeze(-1)
        self.racket_target_vel_w[env_ids] = ref_vel_scaled + dvel

        dnrm = (torch.rand(n, 3, device=dev) * 2.0 - 1.0) * nrm_h
        normal = ref_nrm + dnrm
        self.racket_target_normal_w[env_ids] = normal / (torch.norm(normal, dim=-1, keepdim=True) + 1e-6)

        self.metrics["ref_perturb_scale"][env_ids] = scale

        # Stage-1 question bank: overrides pos/vel + target_normal_cmd for these envs (no-op when off).
        self._apply_question_bank_targets(env_ids, origins, n)

    def _sample_targets_task_first(
        self,
        env_ids: Sequence[int],
        origins: torch.Tensor,
        n: int,
    ) -> None:
        """Sample each action's task around its own reference strike, with no ball or solver.

        Station semantics are intentionally coupled:

        ``racket = ref_racket + [station_shift, 0] + delta_position``
        ``base = ref_base + station_shift + delta_position_xy + delta_base``

        Thus a negative-X station center moves the complete comfortable action away from the
        table. Position curriculum translates racket and base together; only the later base axis
        varies body placement relative to that demanded contact.
        """

        if not self._task_first_enabled:
            raise RuntimeError("task-first sampler called while target_mode is not task_first")
        self._ensure_reference_strike_state()
        if (
            self._ref_racket_pos_rel_per_clip is None
            or self._ref_racket_vel_w_per_clip is None
            or self._ref_racket_normal_raw_w_per_clip is None
            or self._ref_base_pos_rel_per_clip is None
        ):
            raise RuntimeError("task-first reference strike-state initialization is incomplete")
        ids = torch.as_tensor(env_ids, dtype=torch.long, device=self.device)
        motion = self._motion()
        clip = (
            motion.clip_id[ids]
            if motion._multiseg
            else torch.zeros(n, dtype=torch.long, device=self.device)
        )
        actions = self._task_first_manifest.actions
        level_rows = torch.tensor(
            [
                [self._task_first_curriculum.axis_level(action.action_id, axis)
                 for axis in _TASK_FIRST_AXES]
                for action in actions
            ],
            dtype=torch.float32,
            device=self.device,
        )
        levels = level_rows[clip]
        position_level = levels[:, 0:1]
        speed_level = levels[:, 1]
        face_level = levels[:, 2]
        base_level = levels[:, 3:4]

        position_half = torch.tensor(
            [action.position_half_extent_m for action in actions],
            dtype=torch.float32,
            device=self.device,
        )[clip]
        station_shift = torch.tensor(
            [action.station_center_shift_xy_m for action in actions],
            dtype=torch.float32,
            device=self.device,
        )[clip]
        base_half = torch.tensor(
            [action.base_half_extent_xy_m for action in actions],
            dtype=torch.float32,
            device=self.device,
        )[clip]
        speed_delta = torch.tensor(
            [action.speed_delta_mps for action in actions],
            dtype=torch.float32,
            device=self.device,
        )[clip]
        face_cone_rad = torch.tensor(
            [math.radians(action.face_cone_deg) for action in actions],
            dtype=torch.float32,
            device=self.device,
        )[clip]

        delta_position = (
            (torch.rand(n, 3, device=self.device) * 2.0 - 1.0)
            * position_half
            * position_level
        )
        delta_base = (
            (torch.rand(n, 2, device=self.device) * 2.0 - 1.0)
            * base_half
            * base_level
        )
        ref_pos = self._ref_racket_pos_rel_per_clip[clip]
        ref_base = self._ref_base_pos_rel_per_clip[clip, :2]
        position, base_target = _task_first_station_targets(
            origins,
            ref_pos,
            ref_base,
            station_shift,
            delta_position,
            delta_base,
        )
        self.racket_target_pos_w[ids] = position
        self.base_target_pos_w[ids] = base_target

        ref_velocity = self._ref_racket_vel_w_per_clip[clip]
        ref_speed = torch.norm(ref_velocity, dim=-1)
        direction = ref_velocity / ref_speed.unsqueeze(-1)
        demanded_speed = ref_speed + (
            torch.rand(n, device=self.device) * 2.0 - 1.0
        ) * speed_delta * speed_level
        if bool(torch.any(demanded_speed <= 1.0e-6)):
            # Construction validates the full lower bound, so reaching this branch means state or
            # manifest corruption rather than an admissible draw. Never clamp/flip silently.
            raise RuntimeError("task-first sampled a non-positive demanded strike speed")
        self.racket_target_vel_w[ids] = direction * demanded_speed.unsqueeze(-1)

        face = _task_first_face_cone_sample(
            self._ref_racket_normal_raw_w_per_clip[clip],
            face_cone_rad * face_level,
            torch.rand(n, 2, device=self.device),
        )
        self.racket_target_normal_w[ids] = face
        self.target_normal_cmd[ids] = face

    def _apply_question_bank_targets(self, env_ids: Sequence[int], origins: torch.Tensor, n: int):
        """Install a SOLVED question: bank row (discrete) or continuous buffer row. One seam.

        A question is the inverse-solved ANSWER to an incoming ball: target pos := the ball's
        arrival point (env-local -> world by adding the env origin), target vel := demanded racket
        velocity, target_normal_cmd := demanded face normal, plus the incoming ball itself. Two
        producers write it:

        * DISCRETE — a pre-solved bank row (scripts/gen_stage1_questions.py) at the clip's FIXED
          contact point. Exams and reproducibility.
        * CONTINUOUS — ``target_mode='solved'``: the ball is drawn from a continuous per-clip box
          and solved batched, handed out without replacement from a buffer (_cq_take). Training.

        Runs at the END of BOTH sampling paths so every resample route (reset / clip wrap) sees a
        solved target, and the downstream A1 delay/noise injectors act on it exactly like a
        box-sampled one. ``racket_target_normal_w`` storage remains the clip-reference lane for
        provenance, while the critic accessor, rewards and exact/composite metrics all use the
        shared face pair and see the demanded A-frame normal when cfg.face_command is on.
        """
        if self._question_bank is None and not self._cq_enabled:
            return
        motion = self._motion()
        if motion._multiseg:
            clip = motion.clip_id[env_ids]
        else:
            clip = torch.zeros(n, dtype=torch.long, device=self.device)
        if self._cq_enabled:
            # CONTINUOUS producer: same six values, drawn+solved instead of read off a row. The
            # buffer is addressed by LOADED clip (its boxes and its ref face are per loaded clip),
            # not by bank family. The +Y face guard has nothing to sweep here because the sign is
            # closed at SOLVE time (ref_normal = the runtime raw +Y face), so there is no second
            # copy of the face convention that could drift out of agreement.
            if not self._cq_boot_gate_done:
                self._cq_boot_gate()
            pos, incoming_vel, incoming_spin, vel, nrm, diff = self._cq_take(clip, n)
            self.metrics["question_exhausted_frac"][env_ids] = self._cq_last_exhausted_frac
        else:
            if not self._qb_face_frame_checked:
                self._check_question_bank_face_frame()
            # 族寻址:clip → 题库族行(clip_family_per_clip 缺席 = None = clip_id 直接当下标,
            # 现役行为逐字节不变;同族变速 clip 共享同一份题目/答案——烤入片段触球行逐位相同,
            # 复用合法,见 validate_runtime_motion_contract 的族级 SHA 对账)。
            family_table = self._qb_bank_family_table(motion, self._question_bank)
            bank_clip = clip if family_table is None else family_table[clip]
            pos, incoming_vel, incoming_spin, vel, nrm, diff = select_questions(
                self._question_bank, bank_clip, torch.rand(n, device=self.device)
            )
        # ---- BELOW THIS LINE THE TWO PRODUCERS SHARE ONE INSTALL, BYTE FOR BYTE ----------------
        # 人话:两条路必须走同一段安装代码。哪天这六行难写成一段共享代码了,就是两条路已经分叉了
        # ——tests/test_continuous_vs_bank_parity.py 的 seam 断言就是钉这件事的。
        self.racket_target_pos_w[env_ids] = origins + pos
        self.racket_target_vel_w[env_ids] = vel
        self.target_normal_cmd[env_ids] = nrm
        # The inverse-solved answer and its incoming ball are one atomic question. These writes
        # happen from the same row; the generic virtual-ball sampler below is disabled whenever a
        # SOLVED target is active (bank OR continuous — see _solved_targets_active) so it cannot
        # replace question A's ball with question B.
        self.vb_vel_in_w[env_ids] = incoming_vel
        self.vb_spin_in_w[env_ids] = incoming_spin
        # Held per env until its next resample; reset-mean reports the question difficulty mix.
        self.metrics["question_difficulty_deg"][env_ids] = diff

    def _install_event_training_questions(
        self,
        env_ids: Sequence[int] | torch.Tensor,
        clip_ids: torch.Tensor,
        bank_rows: torch.Tensor,
    ) -> None:
        """Install T1 train-bank rows without resetting physical, action, history, or noise state."""

        if self._question_bank is None or not self._event_timing_bound:
            raise RuntimeError("post_strike_t1 question-bank contract is not bound")
        ids = torch.as_tensor(env_ids, dtype=torch.long, device=self.device).reshape(-1)
        clips = torch.as_tensor(clip_ids, dtype=torch.long, device=self.device).reshape(-1)
        rows = torch.as_tensor(bank_rows, dtype=torch.long, device=self.device).reshape(-1)
        if len(ids) == 0 or len(ids) != len(clips) or len(ids) != len(rows):
            raise ValueError("event question install requires equal, non-empty id/clip/row vectors")
        motion = self._motion()
        live_clips = motion.clip_id[ids] if motion._multiseg else torch.zeros_like(clips)
        if not torch.equal(live_clips, clips):
            raise RuntimeError("event motion and atomic train-bank question clips disagree")
        counts = self._question_bank.counts.to(device=self.device, dtype=torch.long)
        # 族寻址:题库行号 = 族表[clip](族表缺席 = clip 直接当行号,现役行为逐字节不变)。
        family_table = self._qb_bank_family_table(motion, self._question_bank)
        if family_table is None:
            bank_clips = clips
        else:
            if torch.any(clips < 0) or torch.any(clips >= int(family_table.shape[0])):
                raise ValueError("event question install references an invalid motion clip")
            bank_clips = family_table[clips]
        if (
            torch.any(bank_clips < 0)
            or torch.any(bank_clips >= len(counts))
            or torch.any(rows < 0)
            or torch.any(rows >= counts[bank_clips])
        ):
            raise ValueError("event question install references an invalid train-bank row")
        if not self._qb_face_frame_checked:
            self._check_question_bank_face_frame()

        origins = self._env.scene.env_origins[ids]
        bank = self._question_bank
        contact = bank.contact_pos[bank_clips]
        self.racket_target_pos_w[ids] = origins + contact
        self.racket_target_vel_w[ids] = bank.demanded_vel[bank_clips, rows]
        demanded_normal = bank.demanded_normal[bank_clips, rows]
        self.racket_target_normal_w[ids] = demanded_normal
        self.target_normal_cmd[ids] = demanded_normal
        self.vb_vel_in_w[ids] = bank.incoming_vel[bank_clips, rows]
        self.vb_spin_in_w[ids] = bank.incoming_spin[bank_clips, rows]
        self.metrics["question_difficulty_deg"][ids] = bank.difficulty_deg[bank_clips, rows]

        # Bank training uses a pinned ready anchor.  Do not draw a fresh base jitter here: the
        # immutable question row and its clip/deadline are installed as one deterministic message.
        self.base_target_pos_w[ids] = origins[:, :2] + self._qb_base_anchor_off_xy()[clips]
        self.station_anchor_pos_w[ids] = origins[:, :2] + torch.tensor(
            self.cfg.station_anchor_offset_xy, dtype=torch.float32, device=self.device
        )
        # Swing type by clip FAMILY (clip_family_per_clip; absent = the legacy 2-clip derivation,
        # byte-identical to the old clips==0 hardcode).
        self.swing_sign[ids] = torch.where(self._clip_family_is_forehand()[clips], 1.0, -1.0)

        # This is an intra-episode post-strike transition: close the previous swing's ledger and
        # start the new one, but do not classify it as a pre-strike fall and do not reset session
        # state.  _prev_clip_id still names the just-finished clip because MotionCommand publishes
        # the new clip earlier in the same manager step.
        if motion._multiseg:
            self._recover_from_clip[ids] = self._prev_clip_id[ids]
        self._resample_is_wrap = True
        try:
            self._count_swing_starts(ids, count_prestrike_falls=False)
        finally:
            self._resample_is_wrap = False
        self._hold_edge_pending[ids] = True
        self._previous_in_hold[ids] = False
        self._hold_start_yaw[ids] = 0.0
        self._exact_fired[ids] = False
        self._prev_motion_steps[ids] = motion.time_steps[ids]
        self._prev_racket_dist[ids] = torch.norm(
            self.racket_pos_w[ids] - self.racket_target_pos_w[ids], dim=-1
        ).detach()
        self.racket_progress[ids] = 0.0
        self._progress_reset_mask[ids] = True
        if hasattr(self, "time_left"):
            self.time_left[ids] = float("inf")
        if self._shadow is not None:
            self._shadow.on_resample(ids)
        if self._physical is not None:
            self._physical.on_resample(ids)
        # Deliberately no _reset_actor_target_state(): _push_actor_target() advances the existing
        # latency ring, AR(1) noise, dropout countdown and hold-last state below.

    def install_external_exam_questions(
        self,
        env_ids: Sequence[int],
        exam_bank,
        clip_ids: torch.Tensor,
        bank_rows: torch.Tensor,
    ) -> None:
        """Atomically install evaluator-owned exam rows without changing the training bank.

        ``cfg.question_bank`` and ``self._question_bank`` remain the saved *train* split.  A formal
        evaluator independently loads/validates the exam split, materializes an immutable
        content-addressed schedule, resets the environment to nominal stand, then calls this seam
        once before the first actor observation.  There is intentionally no automatic cursor or
        wrap behavior here: one environment answers one scheduled row, and any later resample is a
        protocol violation handled by the evaluator ledger.
        """

        raw_ids = torch.as_tensor(env_ids, device=self.device)
        raw_clips = torch.as_tensor(clip_ids, device=self.device)
        raw_rows = torch.as_tensor(bank_rows, device=self.device)
        for name, value in (("env_ids", raw_ids), ("clip_ids", raw_clips),
                            ("bank_rows", raw_rows)):
            if value.dtype == torch.bool or value.is_floating_point() or value.is_complex():
                raise ValueError(f"external exam {name} must use an integer dtype")
        ids = raw_ids.to(dtype=torch.long).reshape(-1)
        clips = raw_clips.to(dtype=torch.long).reshape(-1)
        rows = raw_rows.to(dtype=torch.long).reshape(-1)
        if len(ids) == 0 or len(ids) != len(clips) or len(ids) != len(rows):
            raise ValueError(
                "external exam questions require equal, non-empty env/clip/row vectors"
            )
        if len(torch.unique(ids)) != len(ids) or torch.any(ids < 0) or torch.any(ids >= self.num_envs):
            raise ValueError("external exam env ids must be unique and in range")
        if float(self.cfg.midswing_resample_prob) != 0.0:
            raise ValueError("external BankExam requires midswing_resample_prob=0")
        metadata = getattr(exam_bank, "metadata", None)
        if not isinstance(metadata, dict) or metadata.get("split") != "exam":
            raise ValueError("external BankExam requires a validated schema-v3 exam split")
        counts = exam_bank.counts.to(device=self.device, dtype=torch.long)
        motion = self._motion()
        # 族寻址(clip_family_per_clip 配了才有;None = 现役行为逐字节不变):考卷传进来的
        # clip_ids 是加载 clip 序号,题库行号要过族表折算,同族变速 clip 共享同一族考题。
        family_table = self._qb_bank_family_table(motion, exam_bank)
        if family_table is None:
            if torch.any(clips < 0) or torch.any(clips >= len(counts)):
                raise ValueError("external exam clip ids are outside the exam bank")
            bank_clips = clips
        else:
            if torch.any(clips < 0) or torch.any(clips >= int(family_table.shape[0])):
                raise ValueError("external exam clip ids are outside the loaded motion clips")
            bank_clips = family_table[clips]
            if torch.any(bank_clips >= len(counts)):
                raise ValueError("external exam clip family is outside the exam bank")
        if torch.any(rows < 0) or torch.any(rows >= counts[bank_clips]):
            raise ValueError("external exam row is outside its clip's validated question count")

        live_clips = motion.clip_id[ids] if motion._multiseg else torch.zeros_like(clips)
        if not torch.equal(live_clips, clips):
            raise ValueError(
                "external exam motion clip must be installed before its atomic racket question"
            )

        # The same +Y/A-frame guard used by training, now against the independently loaded exam
        # bank.  Checking all rows makes a bad regenerated bank fail before any score is emitted.
        # 族寻址下逐"加载 clip"核:每个 clip 用自己的参考面对照其族的全部考题法向。
        self._ensure_reference_strike_state()
        ref_raw = self._ref_racket_normal_raw_w_per_clip
        n_guard = len(counts) if family_table is None else int(family_table.shape[0])
        if ref_raw is None or ref_raw.shape[0] < n_guard:
            raise RuntimeError("external exam could not resolve per-clip raw face normals")
        demanded_all = exam_bank.demanded_normal.to(self.device)
        for clip in range(n_guard):
            fam = clip if family_table is None else int(family_table[clip])
            count = int(counts[fam])
            dots = torch.mv(demanded_all[fam, :count], ref_raw[clip])
            if float(dots.min()) <= 0.0:
                raise ValueError(
                    f"external exam clip {clip} contains a demanded normal opposite the +Y/A frame"
                )

        origins = self._env.scene.env_origins[ids]
        contact = exam_bank.contact_pos.to(self.device)[bank_clips]
        incoming_vel = exam_bank.incoming_vel.to(self.device)[bank_clips, rows]
        incoming_spin = exam_bank.incoming_spin.to(self.device)[bank_clips, rows]
        demanded_vel = exam_bank.demanded_vel.to(self.device)[bank_clips, rows]
        demanded_normal = demanded_all[bank_clips, rows]
        difficulty = exam_bank.difficulty_deg.to(self.device)[bank_clips, rows]

        self.racket_target_pos_w[ids] = origins + contact
        self.racket_target_vel_w[ids] = demanded_vel
        # Formal diagnostics grade the demanded exam face even for legacy actors that had no
        # face-command observation.  Face-command actors still read ``target_normal_cmd`` through
        # the audited +Y/A-frame lane below.
        self.racket_target_normal_w[ids] = demanded_normal
        self.target_normal_cmd[ids] = demanded_normal
        self.vb_vel_in_w[ids] = incoming_vel
        self.vb_spin_in_w[ids] = incoming_spin
        if "question_difficulty_deg" not in self.metrics:
            self.metrics["question_difficulty_deg"] = torch.zeros(
                self.num_envs, device=self.device
            )
        self.metrics["question_difficulty_deg"][ids] = difficulty

        # Preserve the saved training task's station semantics while removing reset-time jitter.
        if self.cfg.target_mode == "reference_perturbed":
            if self._ref_reach_offset_xy_per_clip is None:
                raise RuntimeError("external exam could not resolve reference reach offsets")
            base_off = contact[:, :2] - self._ref_reach_offset_xy_per_clip[clips]
        else:
            base_off = torch.zeros_like(contact[:, :2])
            blend = float(self.cfg.base_couple_blend)
            if blend > 0.0:
                base_off[:, 1] = (blend * contact[:, 1]).clamp(
                    -self.cfg.base_couple_max_offset, self.cfg.base_couple_max_offset
                )
        self.base_target_pos_w[ids] = origins[:, :2] + base_off
        self.station_anchor_pos_w[ids] = origins[:, :2] + torch.tensor(
            self.cfg.station_anchor_offset_xy, dtype=torch.float32, device=self.device
        )
        # Swing type by clip FAMILY (clip_family_per_clip; absent = the legacy 2-clip derivation,
        # byte-identical to the old clips==0 hardcode).
        self.swing_sign[ids] = torch.where(self._clip_family_is_forehand()[clips], 1.0, -1.0)

        self._exact_fired[ids] = False
        self._prev_motion_steps[ids] = motion.time_steps[ids]
        self.racket_progress[ids] = 0.0
        self._progress_reset_mask[ids] = True
        if hasattr(self, "time_left"):
            self.time_left[ids] = float("inf")
        self._prev_clip_id[ids] = clips
        self._recover_from_clip[ids] = -1
        self._rally_returned[ids] = False
        self._rally_pending_return[ids] = False
        # The reset sampled a training clip/question before the evaluator installed the exam item.
        # Refresh actual racket FK and the actor-visible clock without advancing physics or either
        # command clock; otherwise action 0 pairs the new question with zero/stale FK and TTS.
        self._compute_racket_state()
        self._compute_strike_timing()
        self._prev_racket_dist[ids] = torch.norm(
            self.racket_pos_w[ids] - self.racket_target_pos_w[ids], dim=-1
        ).detach()
        self._reset_actor_target_state(ids)

    def _check_question_bank_face_frame(self):
        """A-frame (+Y calibration) guard: every bank demanded normal must be same-side with the
        RAW clip reference face (2026-07-09 单翻病防复发卫兵).

        The face_command channel is +Y/A-frame end to end (bank rows, actor obs, reward measured
        side — see hope_rewards._face_pair). gen_stage1_questions.py sign-aligns each demanded
        normal to the raw +Y clip face, so ``dot(demanded, ref_raw) > 0`` holds for every valid
        row (shipped banks: min 0.86). A bank regenerated in the striking-face ("B") convention —
        the retired TIMELINE debt "题库按翻面重出", which must NEVER be completed — would flip the
        backhand rows and silently re-create the M3c disease; this guard turns that into a loud
        startup error instead. Runs once, lazily (the reference strike state resolves after
        __init__); comparing against the runtime FK reference also couples the check to the
        configured strike_phase_per_clip — a large phase drift shows up here as a shrinking
        margin, which is a feature, not a bug.
        """
        self._ensure_reference_strike_state()
        if self._ref_racket_normal_raw_w_per_clip is None:
            raise RuntimeError("reference strike-state initialization produced no raw face normals")
        bank = self._question_bank
        family_table = None
        if bank.metadata:
            motion = self._motion()
            # 族寻址(clip_family_per_clip 配了才有;None = 现役行为逐字节不变):运行时 motion
            # 对账按"每 clip 的 SHA ∈ 其族允许列表"核,下面的 +Y 卫兵也按族取题、逐 clip 对面。
            family_table = self._qb_bank_family_table(motion, bank)
            files = (
                [motion.cfg.motion_file]
                if isinstance(motion.cfg.motion_file, str)
                else list(motion.cfg.motion_file)
            )
            nseg = int(motion.motion.num_segments)
            phases_cfg = self._strike_phases_cfg(nseg)
            phases = (
                [float(value) for value in phases_cfg]
                if phases_cfg
                else [float(self.cfg.strike_phase)] * nseg
            )
            validate_runtime_motion_contract(
                bank.metadata,
                files,
                [int(value) for value in motion.motion.seg_len.tolist()],
                phases,
                clip_families=(family_table.tolist() if family_table is not None else None),
            )
        nseg = int(self._ref_racket_normal_raw_w_per_clip.shape[0])
        n_guard = (
            min(int(bank.counts.shape[0]), nseg)
            if family_table is None
            else min(int(family_table.shape[0]), nseg)
        )
        for c in range(n_guard):
            fam = c if family_table is None else int(family_table[c])
            q = int(bank.counts[fam])
            if q <= 0:
                continue
            rows = bank.demanded_normal[fam, :q]
            ref_raw = self._ref_racket_normal_raw_w_per_clip[c]
            d = torch.mv(rows, ref_raw)
            min_d = float(d.min())
            cname = getattr(self, "_family_names", {0: "forehand", 1: "backhand"}).get(
                fam, f"family{fam}")
            if family_table is not None:
                cname = f"{cname}[clip{c}]"
            if min_d <= 0.0:
                raise ValueError(
                    f"question bank {self.cfg.question_bank!r} clip {cname!r}: "
                    f"{int((d <= 0).sum())}/{q} demanded normals are OPPOSITE the raw +Y clip "
                    f"face (min dot = {min_d:.4f}). The face_command channel is +Y/A-frame by "
                    f"design (hope_rewards._face_pair) — this bank looks regenerated in the "
                    f"striking-face convention, which would silently re-create the M3c 单翻病. "
                    f"Use an A-frame bank (gen_stage1_questions.py output); NEVER re-emit banks "
                    f"in the flipped convention."
                )
            if min_d < 0.5:
                print(
                    f"[RacketTargetCommand] WARN question bank clip {cname}: min dot(demanded, "
                    f"ref_raw_normal) = {min_d:.4f} < 0.5 — unusually far from the calibration "
                    f"face; check strike_phase_per_clip vs the bank's anchor phase.",
                    flush=True,
                )
        self._qb_face_frame_checked = True

    def _qb_base_anchor_off_xy(self) -> torch.Tensor:
        """Per-clip PINNED ready-anchor XY offset from the env origin ((C, 2); cached after the
        first call — the reference reach offset is unresolved at __init__).

        S2a anti-cheat (stage_curriculum_v1): the base demand must NOT track the question. The
        per-question coupling below re-derives base_xy from racket_target_pos_w every resample, so
        once the question point starts varying (point_mode box+) it would leak each question's
        contact point into the base demand and reward stepping toward it — exactly what the
        stand-your-ground gate (root-XY excursion < 0.15 m, 0 steps) must rule out. Instead the
        SAME coupling is evaluated ONCE with the bank's FIXED contact point and reused verbatim.

        族寻址(clip_family_per_clip 配了才有)下表按"加载 clip"展开成 (nseg, 2):同族变速
        clip 共享该族的固定触球点,但 reference_perturbed 的 reach offset 是逐 clip 的,所以锚
        点也逐 clip 各算各的。两处调用端都拿运行时 clip_id 直接下标,两种模式行号语义一致。
        """
        if self._qb_base_anchor is not None:
            return self._qb_base_anchor
        if self._question_bank is not None:
            contact = self._question_bank.contact_pos  # (C, 3), tracking-env frame
            family_table = self._qb_bank_family_table(self._motion(), self._question_bank)
            if family_table is not None:
                contact = contact[family_table]  # (nseg, 3): one row per LOADED clip
        else:
            # CONTINUOUS: there is no fixed contact point by construction, so the per-clip CONSTANT
            # that plays its role is the CENTRE of the contact draw box — exactly the use the
            # dead-knob note above already records for racket_pos_range_per_clip under a solved
            # target. One constant per clip, evaluated once: the S2a argument is unchanged word for
            # word, and _assert_contact_clears_table already runs over this same table at __init__.
            box = self._per_clip_range_rows(
                self._pos_range_per_clip_t, "racket_pos_range_per_clip")     # (nseg, 3, 2)
            contact = (box[..., 0] + box[..., 1]) * 0.5                      # (nseg, 3)
        if self.cfg.target_mode == "reference_perturbed":
            self._ensure_reference_strike_state()
            if self._ref_reach_offset_xy_per_clip is None:
                raise RuntimeError("reference strike-state initialization produced no reach offsets")
            # Single-clip runs cache one reach offset row; clamp the gather like the samplers do.
            idx = torch.arange(contact.shape[0], device=self.device).clamp_(
                max=self._ref_reach_offset_xy_per_clip.shape[0] - 1
            )
            anchor = contact[:, :2] - self._ref_reach_offset_xy_per_clip[idx]
        else:
            # uniform coupling: origin + clamped Y blend toward the (fixed) contact point; X stays 0.
            anchor = torch.zeros_like(contact[:, :2])
            blend = float(self.cfg.base_couple_blend)
            if blend > 0.0:
                anchor[:, 1] = (blend * contact[:, 1]).clamp(
                    -self.cfg.base_couple_max_offset, self.cfg.base_couple_max_offset
                )
        # 行数守卫(人话):两处调用端拿运行时 clip_id 直接下标这张表;题库锚点行数少于加载
        # clip 数就当场报错(6-clip 变速列表必须配 clip_family_per_clip 族表把 2 族锚点展开),
        # 而不是让 GPU gather 越界变成异步 CUDA device-side assert。单 clip 臂(段数 1、
        # 表 2 行)历史上就取第 0 行,行数只要 >= 段数即合法,不动。
        nseg = int(self._motion().motion.num_segments)
        if int(anchor.shape[0]) < nseg:
            raise ValueError(
                f"question-bank ready-anchor table has {int(anchor.shape[0])} row(s) but the "
                f"loaded motion has {nseg} clip(s) — a >2-clip speed-variant list needs "
                f"task.motion.clip_family_per_clip so the two family anchors expand to one row "
                f"per loaded clip"
            )
        self._qb_base_anchor = anchor
        return anchor

    def _resample_command(self, env_ids: Sequence[int]):
        if len(env_ids) == 0:
            return
        if self._action_ball_full_mdp_enabled:
            # Fresh targets are written only by the atomic D05 Racket child.
            # Falling through would silently sample an unrelated legacy
            # uniform target before that writer exists.
            raise ActionBallContinuousRacketHotRevealHold(
                "fresh full-MDP resample awaits the Device-R05 Racket writer"
            )
        if self._action_ball_enabled:
            self._action_ball_reject_legacy_fresh_lane("resample/wrap producer")
        # A true reset or wrap can install new action-ball timing under the same manager step
        # token.  Never let the following update consume a pre-resample metrics handoff.
        self._invalidate_strike_timing_metrics_handoff()
        # The Stage-1 teacher-site cache is keyed by the policy step.  A reset or natural wrap may
        # replace its clip/anchor inside that same step token, so invalidate before any first-frame
        # observation can reuse the previous swing's target.
        self._stage1_clip_site_target_cache = None
        self._stage1_clip_site_reference_hit_cache = None
        self._stage1_clip_long_axis_target_cache = None
        self._ensure_action_ball_runtime_initialized()
        n = len(env_ids)
        env_ids_t = torch.as_tensor(env_ids, dtype=torch.long, device=self.device)
        if (
            _adaptive_sigma_source(self.cfg)
            == _ADAPTIVE_SIGMA_SOURCE_STAGE1_CLIP_SITE
            and not self._resample_is_wrap
        ):
            # Reference-state initialization can place the robot exactly on the
            # teacher.  Exclude the first subsequent metrics sample so reset
            # quality cannot masquerade as policy-earned sigma progress.
            self._stage1_sigma_reset_exclusion[env_ids_t] = True
        if self._action_ball_enabled:
            self._rearm_strike_window_entry_distance_probe(env_ids_t)
        self._post_strike_elapsed_s[env_ids_t] = 0.0
        self._post_strike_elapsed_valid[env_ids_t] = False
        # A reset/wrap may replace one held state with another without a boolean edge. Force
        # the next fresh metrics tick to stamp the new hold's yaw instead of reusing old state.
        self._hold_edge_pending[env_ids_t] = True
        self._previous_in_hold[env_ids_t] = False
        self._hold_start_yaw[env_ids_t] = 0.0
        origins = self._env.scene.env_origins[env_ids]
        motion = self._motion()
        # R14: re-arm the one-shot exact-strike latch for the new swing.
        self._exact_fired[env_ids] = False

        # UNCONDITIONAL swing accounting: every resample STARTS a new swing attempt. On the
        # true-reset path (not a wrap) it also ENDS the previous attempt — count a pre-strike
        # fall if the env terminated before reaching the strike frame.
        self._count_swing_starts(env_ids, count_prestrike_falls=not self._resample_is_wrap)

        # Desired racket pos/vel/normal — independent box sampling (legacy uniform), coupled to the
        # reference swing's strike state (reference_perturbed), or HITTER-faithful station-first
        # sampling (hitter_pure: base station independent, racket plane fixed relative to the station).
        if self.cfg.target_mode == "action_ball":
            self._sample_targets_action_ball(env_ids, origins, n)
        elif self.cfg.target_mode == "task_first":
            self._sample_targets_task_first(env_ids, origins, n)
        elif self.cfg.target_mode == "reference_perturbed":
            self._sample_targets_reference_perturbed(env_ids, origins, n)
        elif self.cfg.target_mode == "hitter_pure":
            self._sample_targets_hitter_pure(env_ids, origins, n)
        else:
            self._sample_targets_uniform(env_ids, origins, n)

        # Desired base XY (world): COUPLE it to the racket target so standing there keeps the racket
        # reachable by the imitated swing — base_target = racket_target_xy - (reference base->racket
        # offset). Independent sampling used to fight the arm's reach (the base_position reward pulled
        # the base away from where the racket needed it). base_target_*_range is now a SMALL JITTER
        # around the coupled point. Legacy "uniform" mode keeps the old origin-relative sampling.
        # hitter_pure sampled the station inside the sampler; question-bank tasks retain their
        # fixed per-clip ready anchor. The two modes are deliberately mutually exclusive here.
        if self.cfg.target_mode in ("hitter_pure", "task_first"):
            pass
        elif self.cfg.target_mode == "action_ball":
            pass
        elif self._solved_targets_active:
            # Stage-1/S2a BASE PIN: fixed per-clip ready anchor (the coupling evaluated ONCE with
            # the bank's fixed contact point / the continuous draw box's CENTRE — see
            # _qb_base_anchor_off_xy), never the per-question coupling below. Keying this on the
            # bank OBJECT would drop a continuous arm straight into the per-question coupling,
            # which re-derives base_xy from racket_target_pos_w every resample and therefore leaks
            # each question's contact point into the base demand — the exact S2a stand-your-ground
            # leak spelled out in _qb_base_anchor_off_xy. Continuous sampling makes the question
            # point vary BY CONSTRUCTION, so that is not hypothetical. Numerically identical while the question point is fixed (S1); becomes
            # load-bearing the moment the point varies (S2a box). base_target_*_range jitter still
            # applies after, unchanged.
            if motion._multiseg:
                clip = motion.clip_id[env_ids]
            else:
                clip = torch.zeros(n, dtype=torch.long, device=self.device)
            base_xy = origins[:, :2] + self._qb_base_anchor_off_xy()[clip]
        elif self.cfg.target_mode == "reference_perturbed":
            self._ensure_reference_strike_state()
            if self._ref_reach_offset_xy_per_clip is None:
                raise RuntimeError("reference strike-state initialization produced no reach offsets")
            if motion._multiseg:
                clip = motion.clip_id[env_ids]
            else:
                clip = torch.zeros(n, dtype=torch.long, device=self.device)
            base_xy = self.racket_target_pos_w[env_ids][:, :2] - self._ref_reach_offset_xy_per_clip[clip]
        elif self.cfg.base_couple_mode == "reference_reach":
            # uniform + HITTER separate-commands coupling (§V-B-1): base_target = racket_target_xy −
            # (reference base→racket strike offset). Same derivation as the reference_perturbed branch
            # above, but the racket target keeps the proven uniform box distribution (warm-start
            # friendly). Standing at the commanded station = racket target at the clip's reference
            # reach, so the striking plane is fixed RELATIVE TO THE COMMANDED BASE and the x-span of
            # the box moves the STATION, not the reach depth. The jitter below (base_target_*_range)
            # trains the policy to strike with the station deliberately offset — y-reach diversity.
            self._ensure_reference_strike_state()
            if self._ref_reach_offset_xy_per_clip is None:
                raise RuntimeError("reference strike-state initialization produced no reach offsets")
            if motion._multiseg:
                clip = motion.clip_id[env_ids]
            else:
                clip = torch.zeros(n, dtype=torch.long, device=self.device)
            base_xy = self.racket_target_pos_w[env_ids][:, :2] - self._ref_reach_offset_xy_per_clip[clip]
        else:
            # uniform: start at spawn, then WEAKLY couple the base toward the racket target's SIDEWAYS
            # offset (Y only; X is the fixed strike plane, so no forward repositioning). The base shifts a
            # fraction (base_couple_blend) of the target's Y offset, clamped to ±base_couple_max_offset, so
            # the robot leans/steps slightly toward far targets instead of stretching in place. blend=0 ->
            # the old spawn-only behaviour. This only moves a REWARD target — the racket target distribution
            # is unchanged. (No walking reference exists, so keep the blend small: it fights leg imitation.)
            base_xy = origins[:, :2].clone()
            blend = float(self.cfg.base_couple_blend)
            if blend > 0.0:
                racket_y_off = self.racket_target_pos_w[env_ids][:, 1] - origins[:, 1]
                base_xy[:, 1] += (blend * racket_y_off).clamp(
                    -self.cfg.base_couple_max_offset, self.cfg.base_couple_max_offset
                )
        if self.cfg.target_mode not in ("hitter_pure", "task_first", "action_ball"):
            # hitter_pure sampled the station inside the sampler; base_target_*_range was the
            # station box there, NOT a jitter — adding it again would double-sample.
            base_xy[:, 0] += sample_uniform(*self.cfg.base_target_x_range, (n,), self.device)
            base_xy[:, 1] += sample_uniform(*self.cfg.base_target_y_range, (n,), self.device)
            self.base_target_pos_w[env_ids] = base_xy

        # R10c 站位锚:常数 = env origin + 可配置偏移。每次 resample 重写同一常数(幂等,
        # 放这里只因 origins 在手);故意不带抖动、不跟 racket/base_target 耦合——它是"你该站在
        # 哪"的世界系锚,不是奖励目标。
        self.station_anchor_pos_w[env_ids] = origins[:, :2] + torch.tensor(
            self.cfg.station_anchor_offset_xy, dtype=torch.float32, device=self.device
        )

        # Swing type. Unified multi-clip: it IS the imitated clip's FAMILY (forehand family -> +1,
        # backhand family -> -1; clip_family_per_clip, absent = the legacy (forehand, backhand) 2-clip
        # derivation, byte-identical to the old clips==0 hardcode), matching the swing_type
        # observation. Single-clip legacy: infer from the target Y side.
        if motion._multiseg:
            clip = motion.clip_id[env_ids]
            self.swing_sign[env_ids] = torch.where(
                self._clip_family_is_forehand()[clip], 1.0, -1.0
            )
        else:
            base_y_nom = origins[:, 1] + self.cfg.base_nominal_offset[1]
            dy = self.racket_target_pos_w[env_ids][:, 1] - base_y_nom
            if self.cfg.forehand_on_negative_y:
                self.swing_sign[env_ids] = torch.where(dy <= 0.0, 1.0, -1.0)
            else:
                self.swing_sign[env_ids] = torch.where(dy >= 0.0, 1.0, -1.0)

        # Tier-1 virtual incoming ball: one (v_in, omega_in) per swing. The ball's position at the
        # strike time is the racket target BY CONSTRUCTION (the sampler defines the ball to arrive
        # there), so only velocity + spin are sampled. Boxes stay inside the venue-fit envelope.
        # ATOMICITY, enforcement half. The samplers (where the solve seam lives) run FIRST and this
        # runs AFTER; with the predicate keyed on the bank OBJECT a continuous arm would land here
        # and overwrite vb_vel_in_w / vb_spin_in_w with a fresh uniform draw — the policy would be
        # asked to answer a ball that is NOT the one its racket command was solved for. This single
        # line is the most dangerous silent disengagement in the whole change.
        if ((self.cfg.virtual_ball or self.cfg.vb_metrics_only)
                and not self._solved_targets_active):
            if self._vb_vel_range_per_clip_t is None:
                self.vb_vel_in_w[env_ids, 0] = sample_uniform(*self.cfg.vb_vel_x_range, (n,), self.device)
                self.vb_vel_in_w[env_ids, 1] = sample_uniform(*self.cfg.vb_vel_y_range, (n,), self.device)
                self.vb_vel_in_w[env_ids, 2] = sample_uniform(*self.cfg.vb_vel_z_range, (n,), self.device)
            else:
                # PER-CLIP incoming-ball regime: a block is posed fast balls and a loop slow ones in
                # the SAME run. Same gather discipline as the racket boxes (_per_clip_range_rows
                # validates the row count BEFORE any GPU index, so a mis-sized table is a human-
                # readable ValueError, not an async CUDA device-side assert).
                _clip_e = self._motion().clip_id[
                    torch.as_tensor(env_ids, dtype=torch.long, device=self.device)
                ]
                _vb_rng = self._per_clip_range_rows(
                    self._vb_vel_range_per_clip_t, "vb_vel_range_per_clip"
                )[_clip_e]                                        # (n, 3, 2)
                _u = torch.rand(n, 3, device=self.device)
                self.vb_vel_in_w[env_ids] = (
                    _vb_rng[:, :, 0] + (_vb_rng[:, :, 1] - _vb_rng[:, :, 0]) * _u
                )
            if self._vb_spin_abs_max_per_clip_t is None:
                _s = float(self.cfg.vb_spin_abs_max)
                self.vb_spin_in_w[env_ids] = sample_uniform(-_s, _s, (n, 3), self.device)
            else:
                _clip_e = self._motion().clip_id[
                    torch.as_tensor(env_ids, dtype=torch.long, device=self.device)
                ]
                _s_e = self._vb_spin_abs_max_per_clip_t[_clip_e].unsqueeze(-1)      # (n, 1)
                self.vb_spin_in_w[env_ids] = (
                    (torch.rand(n, 3, device=self.device) * 2.0 - 1.0) * _s_e
                )

        # Rally drift accounting: base->NEW-station error at swing start (the recovery debt the
        # previous swing left). Wrap path only — at true resets base_pos_w still caches the
        # pre-teleport pose (the lazy-stamp rationale in __init__), which would book the reset
        # teleport as recovery debt. Denominator: _drift_n_acc (same wrap-only event count).
        if self._resample_is_wrap and n > 0:
            _ids_so = torch.as_tensor(env_ids, dtype=torch.long, device=self.device)
            _off = torch.norm(self.base_pos_w[_ids_so, :2] - self.base_target_pos_w[_ids_so], dim=-1)
            _off_sum = _off.sum()
            if self._action_ball_diagnostic_device_telemetry_enabled():
                self._action_ball_diagnostic_device_telemetry_add(
                    "swing",
                    ("_station_offset_start_sum_acc", None),
                    _off_sum,
                )
            else:
                self._station_offset_start_sum_acc += float(_off_sum)

        # Stamp the motion phase baseline for these envs so the per-swing wrap detector in
        # _update_command does not immediately re-trigger after this (e.g. reset-time) resample.
        self._prev_motion_steps[env_ids] = self._motion().time_steps[env_ids]
        self._prev_racket_dist[env_ids] = torch.norm(
            self.racket_pos_w[env_ids] - self.racket_target_pos_w[env_ids], dim=-1
        ).detach()
        self.racket_progress[env_ids] = 0.0
        self._progress_reset_mask[env_ids] = True

        # Install the task only after every truth field (bank row, contact, demanded velocity/
        # signed normal and incoming ball) has been sampled.  Revisions below update a separate
        # actor tuple and can never mutate these buffers.
        self._begin_same_ball_planner_task(env_ids)

        # A1 target latency: a TRUE reset (not an intra-episode wrap) starts a fresh "deploy
        # session".  Backfill the complete atomic planner message and clear every stateful sensor
        # defect; otherwise a new episode can inherit the previous episode's held frame, dropout
        # countdown, AR(1) error or per-swing bias.  Intra-episode wraps deliberately keep those
        # dynamics: the next command reaching the actor late is the deployment effect being modeled.
        if not self._resample_is_wrap:
            self._reset_actor_target_state(env_ids)

        # SHADOW ball lifecycle: a resample (reset or wrap) starts these envs' next question —
        # back to the kinematic incoming path (metrics-only; no reward/obs effect).
        if self._shadow is not None:
            self._shadow.on_resample(env_ids)

        # PHYSICAL ball lifecycle: the new question's serve is scheduled from here — the ball
        # parks until time_to_strike enters the serve horizon (metrics-only; no reward/obs effect).
        if self._physical is not None:
            self._physical.on_resample(env_ids)
        if not self._resample_is_wrap:
            self._arm_action_ball_strike_fact_after_initial_reset()

    def _racket_fk(
        self,
    ) -> tuple[torch.Tensor, torch.Tensor, torch.Tensor, torch.Tensor, torch.Tensor]:
        """Pure current articulation FK.

        Returns ``(position, quaternion, link-point linear velocity, raw +Y normal, signed
        striking-face normal)`` without rebinding any reward/observation-visible command buffer.
        The Phase-B physics callback consumes these locals so enabling a metrics-only ball cannot
        leak substep-fresh racket state into the policy or reward stream.
        """
        data = self.robot.data
        # Isaac Lab 2.1's legacy ``body_*`` state deliberately mixes frames:
        # ``body_pos_w`` / ``body_quat_w`` are LINK/actor-frame quantities, but
        # ``body_lin_vel_w`` is the COM-point velocity.  Racket position and
        # velocity must describe the SAME rigid point.  Use the explicit link
        # velocity buffers before applying the fixed wrist->site offset;
        # otherwise the old formula adds omega x (link-origin->site) to a COM
        # velocity and over-counts omega x (link-origin->COM), a measured
        # 0.40/0.60 m/s error at the hopex forehand/backhand strike frames.
        # The fallback keeps dependency-light unit stubs and pre-2.1 shims
        # importable; the pinned Isaac Lab 2.1 runtime always exposes the link
        # properties (formal runtime verification covers that contract).
        if self._racket_mode == "body":
            idx = self._racket_body_index
            pos = data.body_pos_w[:, idx]
            quat = data.body_quat_w[:, idx]
            if not hasattr(data, "body_link_lin_vel_w"):
                raise RuntimeError(
                    "RacketTargetCommand requires Isaac Lab body_link_lin_vel_w: body_pos_w is a "
                    "link-origin position but body_lin_vel_w is a COM-point velocity. Falling back "
                    "would silently corrupt racket speed. Use the pinned Isaac Lab 2.1 runtime."
                )
            lin_vel = data.body_link_lin_vel_w[:, idx]
        else:
            widx = self._wrist_body_index
            wpos = data.body_pos_w[:, widx]
            wquat = data.body_quat_w[:, widx]
            if not hasattr(data, "body_link_lin_vel_w") or not hasattr(data, "body_link_ang_vel_w"):
                raise RuntimeError(
                    "RacketTargetCommand wrist FK requires body_link_{lin,ang}_vel_w; legacy "
                    "body_lin_vel_w is a different rigid point and is not a safe fallback."
                )
            wlin = data.body_link_lin_vel_w[:, widx]
            wang = data.body_link_ang_vel_w[:, widx]
            offset_w = quat_apply(wquat, self._mount_offset)
            pos = wpos + offset_w
            lin_vel = wlin + torch.cross(wang, offset_w, dim=-1)
            quat = quat_mul(wquat, self._mount_quat)
        # Face normal = chosen local axis of the racket frame, mapped to world, times the striking-FACE
        # sign. 人话(franco 2026-07-09 拍板"哪面拍子超前就是哪面"):统一正反手策略里两个挥拍用的是
        # 拍子相反的两面(正手=红面/+Y,反手=黑面/−Y),所以开了 mount_normal_sign_per_clip 时符号按
        # 每个 env 的 clip_id 取;表为空(默认)走标量 mount_normal_sign,现役行为逐位不变(此时连
        # _motion() 都不碰)。racket_normal 奖励(hope_rewards._normal_kernel_raw)和训练内拍面误差
        # 指标(racket_normal_error_deg,_update_metrics)都读 self.racket_normal_w,一处修两处好。
        # Asset audit 2026-07-10 confirms local +Y is the red outer-face normal;
        # see docs/interfaces/racket_contact_geometry.md.
        axis_w = matrix_from_quat(quat)[:, :, self.cfg.mount_normal_axis]
        use_per_clip_sign = bool(self.cfg.mount_normal_sign_per_clip) or (
            str(getattr(self.cfg, "motion_teacher_racket_source", "robot_fk"))
            == "measured_channel"
        )
        if use_per_clip_sign:
            motion = self._motion()
            if self._mount_sign_per_clip_t is None:
                # 懒构建 + fail-loud：实测 channel 的 solver 符号优先；cfg 若声明了
                # 逐 clip 表则必须与它一致。
                mns = self._mount_signs_cfg(int(motion.motion.num_segments))
                self._mount_sign_per_clip_t = torch.tensor(
                    [float(s) for s in mns], dtype=torch.float32, device=self.device
                )
            if motion._multiseg:
                sign = self._mount_sign_per_clip_t[motion.clip_id].unsqueeze(-1)  # (num_envs, 1)
            else:
                sign = self._mount_sign_per_clip_t[0]  # 单 clip:表长已校验 = 1
        else:
            sign = self.cfg.mount_normal_sign
        # RAW (+Y calibration frame, "A" convention) normal, kept alongside the striking-face-signed
        # one: the face_command reward channel pairs against +Y-frame question-bank targets and must
        # read THIS buffer (hope_rewards._face_pair; 2026-07-09 单翻病定案). Sign table empty =>
        # racket_normal_w == raw * 1.0, bitwise identical.
        return pos, quat, lin_vel, axis_w, axis_w * sign

    def _racket_angular_velocity_w(self) -> torch.Tensor:
        """Return angular velocity of the rigid racket frame in world axes.

        The mounted racket is fixed to either the configured racket body or
        wrist body, so both frames share angular velocity.  ActionBall v2
        needs this quantity to convert the official control-site velocity to
        the selected rubber face-centre velocity.  There is deliberately no
        legacy/COM fallback: silently omitting ``omega x r`` would reinstate
        the site/face colocation bug.
        """

        data = self.robot.data
        if not hasattr(data, "body_link_ang_vel_w"):
            raise RuntimeError(
                "ActionBall exact-face geometry requires "
                "Isaac Lab body_link_ang_vel_w"
            )
        index = (
            self._racket_body_index
            if self._racket_mode == "body"
            else self._wrist_body_index
        )
        return data.body_link_ang_vel_w[:, index]

    def _action_ball_exact_achieved_contact_state(
        self,
        *,
        racket_site_pos_w: torch.Tensor,
        racket_quat_wxyz: torch.Tensor,
        racket_site_velocity_w: torch.Tensor,
        racket_angular_velocity_w: torch.Tensor | None = None,
        valid_mask: torch.Tensor | None = None,
    ) -> dict[str, torch.Tensor]:
        """Materialize achieved selected-face geometry for ActionBall v2."""

        if not self._action_ball_enabled:
            raise RuntimeError(
                "exact ActionBall contact geometry requested outside ActionBall"
            )
        from . import racket_contact_geometry as contact_geometry

        slots = self._action_ball_action_slot
        invalid_slots = (
            (slots < 0) | (slots >= len(self._action_ball_mount_signs))
        )
        if valid_mask is None:
            required = torch.ones_like(invalid_slots)
        else:
            required = torch.as_tensor(
                valid_mask, dtype=torch.bool, device=self.device
            )
            if required.shape != invalid_slots.shape:
                raise ValueError(
                    "ActionBall exact-face valid_mask shape mismatch"
                )
        _action_ball_validate_tensor_predicate(
            ~(invalid_slots & required),
            "ActionBall exact-face geometry saw an uninstalled action slot",
            async_validate=bool(
                getattr(
                    self,
                    "_action_ball_diagnostic_unauthorized",
                    False,
                )
            ),
        )
        sign_table = torch.as_tensor(
            self._action_ball_mount_signs,
            dtype=racket_site_pos_w.dtype,
            device=self.device,
        )
        # Inactive rows are never admitted or snapshotted.  Clamp them only so
        # the vectorized geometry helper can preserve full-batch execution;
        # an invalid required row failed loudly above.
        signs = sign_table[slots.clamp(
            min=0, max=len(self._action_ball_mount_signs) - 1
        )]
        angular_velocity = (
            self._racket_angular_velocity_w()
            if racket_angular_velocity_w is None
            else racket_angular_velocity_w
        )
        return contact_geometry.torch_exact_contact_state(
            racket_site_pos_w=racket_site_pos_w,
            racket_quat_wxyz=racket_quat_wxyz,
            racket_site_velocity_w=racket_site_velocity_w,
            racket_angular_velocity_w=angular_velocity,
            face_sign=signs,
        )

    def _action_ball_invalidate_virtual_contact_history(
        self, env_ids: torch.Tensor | None = None
    ) -> None:
        """Invalidate the previous face sample at every task-identity seam."""

        valid = self._action_ball_prev_contact_valid
        if env_ids is None:
            valid.zero_()
            return
        ids = torch.as_tensor(
            env_ids, dtype=torch.long, device=self.device
        ).reshape(-1)
        valid[ids] = False

    def _action_ball_store_virtual_contact_history(
        self,
        angular_velocity_w: torch.Tensor,
    ) -> None:
        """Snapshot one raw site pose/twist with its exact attempt identity."""

        active = self._action_ball_attempt_active
        quaternion_norm = torch.linalg.norm(
            self.racket_quat_w, dim=-1
        )
        raw_state_finite = (
            torch.isfinite(self.racket_pos_w).all(dim=-1)
            & torch.isfinite(self.racket_quat_w).all(dim=-1)
            & torch.isfinite(self.racket_lin_vel_w).all(dim=-1)
            & torch.isfinite(angular_velocity_w).all(dim=-1)
            & torch.isfinite(quaternion_norm)
            & (quaternion_norm > 1.0e-12)
        )
        _action_ball_validate_tensor_predicate(
            ~(active & ~raw_state_finite),
            "ActionBall active contact history contains a non-finite "
            "site/twist or zero quaternion",
            async_validate=bool(
                getattr(
                    self,
                    "_action_ball_diagnostic_unauthorized",
                    False,
                )
            ),
        )
        self._action_ball_prev_racket_site_w.copy_(
            self.racket_pos_w
        )
        self._action_ball_prev_racket_quat_w.copy_(
            self.racket_quat_w
        )
        self._action_ball_prev_racket_site_velocity_w.copy_(
            self.racket_lin_vel_w
        )
        self._action_ball_prev_racket_angular_velocity_w.copy_(
            angular_velocity_w
        )
        self._action_ball_prev_attempt_action.copy_(
            self._action_ball_attempt_action
        )
        self._action_ball_prev_reset_generation.copy_(
            self._action_ball_reset_generation
        )
        self._action_ball_prev_swing_generation.copy_(
            self._action_ball_swing_generation
        )
        self._action_ball_prev_contact_valid.copy_(active)

    def _compute_racket_state(self):
        # This remains the only writer of the command's racket-state buffers. Phase-B substep
        # contact scans call _racket_fk() and keep its results local.
        (
            self.racket_pos_w,
            self.racket_quat_w,
            self.racket_lin_vel_w,
            self.racket_normal_raw_w,
            self.racket_normal_w,
        ) = self._racket_fk()
        from . import racket_contact_geometry as contact_geometry

        local_butt_to_blade = torch.tensor(
            contact_geometry.RACKET_BUTT_TO_BLADE_AXIS_LOCAL,
            device=self.device,
            dtype=self.racket_quat_w.dtype,
        ).expand(self.num_envs, 3)
        self.racket_long_axis_w = quat_apply(
            self.racket_quat_w, local_butt_to_blade
        )

    def _strike_steps_for_envs(self, env_ids: torch.Tensor) -> torch.Tensor:
        """Return absolute float clip indices for the configured contact phase."""

        motion = self._motion()
        ml = motion.motion
        ids = env_ids.to(device=self.device, dtype=torch.long)
        if motion._multiseg:
            if self._strike_phase_per_clip_t is None:
                phases = self._strike_phases_cfg(int(ml.num_segments))
                self._strike_phase_per_clip_t = (
                    torch.tensor([float(value) for value in phases], device=self.device)
                    if phases
                    else torch.full(
                        (int(ml.num_segments),),
                        float(self.cfg.strike_phase),
                        device=self.device,
                    )
                )
            clips = motion.clip_id[ids]
            starts = ml.seg_start[clips].float()
            lengths = ml.seg_len[clips].float()
            return starts + torch.round(
                self._strike_phase_per_clip_t[clips] * (lengths - 1.0)
            )
        total = max(int(ml.time_step_total), 1)
        return torch.full(
            (len(ids),),
            float(round(self.cfg.strike_phase * (total - 1))),
            device=self.device,
        )

    def _advance_post_strike_elapsed(self, exact_strike: torch.Tensor) -> None:
        """Advance an exact, reset-aware control-time clock for the current attempt.

        The planner phase governor can change ``motion.speed_scale`` every tick.  Consequently,
        dividing a cumulative reference-frame gap by the *current* speed is not elapsed wall time.
        This latch starts from the phase-aligned exact-strike opportunity (independent of hit
        success), advances once per unique 50-Hz control tick, and closes at reset/wrap/T1 reveal.
        """

        token = getattr(self._env, "common_step_counter", None)
        if type(token) is not int:
            raise RuntimeError(
                "post-strike elapsed clock requires integer env.common_step_counter"
            )
        if self._post_strike_elapsed_last_step == token:
            return
        self._post_strike_elapsed_last_step = token

        dt = float(self._env.step_dt)
        if not math.isfinite(dt) or dt <= 0.0:
            raise RuntimeError("post-strike elapsed clock requires finite positive env.step_dt")
        exact = exact_strike.detach().bool()
        if tuple(exact.shape) != (self.num_envs,):
            raise RuntimeError("exact_strike must be a per-environment boolean mask")

        motion = self._motion()
        wrapped = getattr(motion, "just_resampled", None)
        if wrapped is None:
            wrapped = torch.zeros_like(exact)
        revealed = getattr(motion, "event_just_installed", None)
        if revealed is None:
            revealed = torch.zeros_like(exact)
        wrapped = wrapped.detach().bool()
        revealed = revealed.detach().bool()
        if tuple(wrapped.shape) != (self.num_envs,) or tuple(revealed.shape) != (
            self.num_envs,
        ):
            raise RuntimeError("wrap/reveal masks must be per-environment")

        # The exact opportunity can lie on the small positive-TTS side of the +/-dt/2 detector.
        # In that case ``pre_strike`` is still true, but this is nevertheless the unique origin
        # for the attempt.  Let exact win over pre-strike; wrap/reveal always win over exact.
        close = (self.pre_strike.detach().bool() & ~exact) | wrapped | revealed
        continuing = self._post_strike_elapsed_valid & ~close
        self._post_strike_elapsed_s[continuing] += dt
        origin = exact & ~wrapped & ~revealed
        self._post_strike_elapsed_s[origin] = 0.0
        self._post_strike_elapsed_valid[origin] = True
        self._post_strike_elapsed_s[close] = 0.0
        self._post_strike_elapsed_valid[close] = False

    def post_strike_age_and_same_attempt(self) -> tuple[torch.Tensor, torch.Tensor]:
        """Return the control-time recovery age and current-attempt validity mask."""

        return self._post_strike_elapsed_s, self._post_strike_elapsed_valid

    @staticmethod
    def _planner_initial_tts_bucket_ids(initial_tts: torch.Tensor) -> torch.Tensor:
        """Classify task-entry preparation time into four disjoint deployment buckets."""

        if initial_tts.ndim != 1:
            raise ValueError("planner initial TTS bucket input must be one-dimensional")
        if not bool(torch.isfinite(initial_tts).all()):
            raise ValueError("planner initial TTS bucket input must be finite")
        buckets = torch.full_like(initial_tts, -1, dtype=torch.long)
        buckets[initial_tts < 0.5] = 0
        buckets[initial_tts == 0.5] = 1
        buckets[(initial_tts > 0.5) & (initial_tts <= 0.9)] = 2
        buckets[initial_tts > 0.9] = 3
        if bool((buckets < 0).any()):
            raise RuntimeError("planner initial TTS bucket partition is incomplete")
        return buckets

    def _ensure_exact_timing_bucket_state(self) -> None:
        """Lazy allocation for unit-test construction and older restored command objects."""

        if not hasattr(self, "_exact_attempt_initial_tts_bucket"):
            self._exact_attempt_initial_tts_bucket = torch.full(
                (self.num_envs,), -1, dtype=torch.long, device=self.device
            )
        if not hasattr(self, "_exact_pending_timing_bucket_events"):
            self._exact_pending_timing_bucket_events = {
                name: torch.zeros(self.num_envs, dtype=torch.bool, device=self.device)
                for name in _TIMING_BUCKET_SPARSE_EVENTS
            }

    def _assign_exact_attempt_initial_tts(
        self, env_ids: torch.Tensor, initial_tts: torch.Tensor
    ) -> None:
        """Latch a new attempt's bucket and flush any same-wrap sparse outcomes into it."""

        ids = torch.as_tensor(env_ids, dtype=torch.long, device=self.device).reshape(-1)
        tts = torch.as_tensor(initial_tts, dtype=torch.float32, device=self.device).reshape(-1)
        if len(ids) != len(tts):
            raise ValueError("planner initial TTS bucket assignment length mismatch")
        self._ensure_exact_timing_bucket_state()
        bucket_ids = self._planner_initial_tts_bucket_ids(tts)
        self._exact_attempt_initial_tts_bucket[ids] = bucket_ids

        ledger = self._ensure_exact_behavior_decision_counters()
        with torch.inference_mode():
            for event_name, pending in self._exact_pending_timing_bucket_events.items():
                selected_pending = pending[ids]
                for bucket_id, bucket_name in enumerate(_PLANNER_INITIAL_TTS_BUCKETS):
                    ledger[f"planner_initial_tts_{bucket_name}_{event_name}"].add_(
                        (selected_pending & (bucket_ids == bucket_id)).sum(dtype=torch.long)
                    )
                pending[ids] = False

    def _book_exact_timing_bucket_sparse_events(
        self, masks: dict[str, torch.Tensor]
    ) -> None:
        """Book strike/capture/return masks against the attempt's latched initial TTS."""

        if not getattr(self, "planner_revision_enabled", False):
            return
        self._ensure_exact_timing_bucket_state()
        ledger = self._ensure_exact_behavior_decision_counters()
        motion = self._motion()
        wrapped = getattr(motion, "just_resampled", None)
        if wrapped is None:
            wrapped = torch.zeros(self.num_envs, dtype=torch.bool, device=self.device)
        else:
            wrapped = wrapped.detach().to(device=self.device)
            if wrapped.dtype != torch.bool or wrapped.shape != (self.num_envs,):
                raise ValueError("motion.just_resampled must be a per-env boolean mask")

        bucket_ids = self._exact_attempt_initial_tts_bucket
        for event_name in _TIMING_BUCKET_SPARSE_EVENTS:
            mask = masks.get(event_name)
            if mask is None:
                continue
            mask = mask.detach().to(device=self.device)
            if mask.dtype != torch.bool or mask.shape != (self.num_envs,):
                raise ValueError(f"{event_name} must be a per-env boolean mask")
            pending = mask & wrapped
            self._exact_pending_timing_bucket_events[event_name] |= pending
            current = mask & ~wrapped
            for bucket_id, bucket_name in enumerate(_PLANNER_INITIAL_TTS_BUCKETS):
                ledger[f"planner_initial_tts_{bucket_name}_{event_name}"].add_(
                    (current & (bucket_ids == bucket_id)).sum(dtype=torch.long)
                )

    def _sample_planner_initial_tts(self, count: int) -> torch.Tensor:
        """Draw the checkpoint-bound preparation-time mixture exactly once per new task."""

        if count <= 0:
            return torch.empty(0, device=self.device)
        mixture = self._planner_initial_tts_mixture
        if mixture is None:
            raise RuntimeError("planner initial-TTS mixture is unavailable")
        component_ids = torch.multinomial(
            self._planner_initial_tts_component_weight,
            count,
            replacement=True,
        )
        lo = self._planner_initial_tts_component_lo[component_ids]
        hi = self._planner_initial_tts_component_hi[component_ids]
        # Point-mass rows (notably the explicit 0.5 s deployment baseline) remain exact because
        # (hi - lo) is bitwise zero; sub-0.5 s rows are a stress stratum, not a support floor.
        samples = lo + (hi - lo) * torch.rand(count, device=self.device)
        ledger = self._ensure_exact_behavior_decision_counters()
        counts = torch.bincount(
            component_ids,
            minlength=len(mixture.components),
        )
        ledger["planner_initial_tts_sample_count"].add_(count)
        for index, component_count in enumerate(counts):
            ledger[f"planner_initial_tts_component_{index}_count"].add_(
                component_count
            )
        ledger["planner_initial_tts_sub_0p5_count"].add_(
            (samples < 0.5).sum(dtype=torch.long)
        )
        ledger["planner_initial_tts_exact_0p5_count"].add_(
            (samples == 0.5).sum(dtype=torch.long)
        )
        ledger["planner_initial_tts_above_0p5_count"].add_(
            (samples > 0.5).sum(dtype=torch.long)
        )
        return samples

    def _begin_same_ball_planner_task(self, env_ids: Sequence[int]) -> None:
        """Create one new task identity without changing the already-sampled physical truth."""

        if not self.planner_revision_enabled or len(env_ids) == 0:
            return
        motion = self._motion()
        if not motion.planner_revision_enabled:
            raise RuntimeError(
                "half-configured planner revisions: racket command enabled but motion governor off"
            )
        profile = self._planner_revision_profile
        motion_profile = motion._planner_revision_profile
        if profile is None or motion_profile is None or (
            profile.profile_sha256 != motion_profile.profile_sha256
        ):
            raise RuntimeError(
                "half-configured planner revisions: racket/motion profile SHA mismatch"
            )
        motion_mixture = motion._planner_initial_tts_mixture
        if (
            motion_mixture is None
            or self._planner_initial_tts_mixture is None
            or motion_mixture.document()
            != self._planner_initial_tts_mixture.document()
        ):
            raise RuntimeError(
                "half-configured planner revisions: racket/motion initial-TTS mixture mismatch"
            )
        ids = torch.as_tensor(env_ids, dtype=torch.long, device=self.device)
        if getattr(self, "_coupled_transport", False):
            # 任务安装即时生效(任务安装不是 mocap 流,BEGIN 元组不过在途环)。上一颗球还
            # 在途的修订全部作废:中继丢弃已结束任务的消息,绝不能把旧球的元组提交进新任务。
            self._pend_valid[:, ids] = False
        if self._resample_is_wrap:
            self._planner_task_id[ids] += 1
        else:
            self._planner_control_epoch[ids] += 1
            self._planner_task_id[ids] = 1
        self._planner_task_revision[ids] = 1
        initial_tts = self._sample_planner_initial_tts(len(ids))
        self._assign_exact_attempt_initial_tts(ids, initial_tts)
        strike_step = self._strike_steps_for_envs(ids)
        normal = self.target_normal_cmd[ids]
        normal = normal / torch.linalg.vector_norm(normal, dim=-1, keepdim=True).clamp(min=1.0e-12)
        motion.begin_planner_task(
            ids,
            control_epoch=self._planner_control_epoch[ids],
            task_id=self._planner_task_id[ids],
            strike_step=strike_step,
            initial_tts=initial_tts,
            target_position=self.racket_target_pos_w[ids],
            target_velocity=self.racket_target_vel_w[ids],
            target_normal=normal,
        )
        self.time_to_strike[ids] = initial_tts
        self._planner_visible_pos[ids] = self.racket_target_pos_w[ids]
        self._planner_visible_vel[ids] = self.racket_target_vel_w[ids]
        self._planner_visible_normal[ids] = normal
        self._planner_visible_tts[ids] = initial_tts
        self._planner_visible_last_precontact[ids] = False
        self.metrics["planner_task_revision"][ids] = 1.0

    def _revise_same_ball_actor_tuple(self) -> None:
        """Generate and atomically submit one bounded estimate revision for each pre-strike task."""

        if not self.planner_revision_enabled:
            return
        motion = self._motion()
        profile = self._planner_revision_profile
        if profile is None:
            raise RuntimeError("planner revision profile is unavailable")
        coupled = bool(getattr(self, "_coupled_transport", False))
        if coupled and getattr(motion, "event_timing_enabled", False):
            # 未定义交互,fail-loud:event timing 的 deadline 属于不可变考卷排程(不在 planner
            # 元组里),把提交压 d 步无法对它保持一致语义(排程该不该也晚 d 步?)。想同时用,
            # 先给事件时钟定义耦合传输合同再解锁。
            raise RuntimeError(
                "coupled transport delay + event timing is undefined: the event scheduler owns "
                "deadlines outside the planner tuple, so delaying revision submission by d steps "
                "has no coherent meaning for scheduled rows. Disable target_delay_steps or "
                "event timing."
            )
        # The runner can advance an accepted source timestamp locally between messages.  Mirror
        # that here so the actor clock never freezes inside the profile's no-new-revision cutoff.
        active = motion._planner_active
        self._planner_visible_tts[active] = (
            self._planner_visible_tts[active] - profile.policy_dt_s
        ).clamp(min=0.0)
        self._planner_visible_tts[active] = motion._planner_canonicalize_tts(
            self._planner_visible_tts[active], profile
        )
        eligible = motion._planner_active & (
            motion._planner_truth_tts + profile.early_deadline_tolerance_s
            >= profile.min_tts_s
        )
        ids = torch.where(eligible)[0]
        if len(ids) == 0 and not coupled:
            # 耦合模式不许在这早退:本步就算没新生成,也必须弹环提交 d 步前的在途修订。
            return
        # Estimate noise converges toward contact.  Every proposal is clamped against the
        # immutable task-begin tuple.  This is essential for latest-value transport: the runner may
        # observe revision N+2 without ever seeing N+1, yet both remain valid members of one task.
        convergence = motion._planner_truth_tts[ids].clamp(0.0, 1.0).unsqueeze(-1)
        begin_pos = self.racket_target_pos_w[ids]
        pos = begin_pos
        pos_std = float(self.cfg.planner_revision_position_std_m)
        if pos_std > 0.0:
            proposal = pos + torch.randn_like(pos) * (pos_std * convergence)
        else:
            proposal = pos
        delta = proposal - begin_pos
        delta_norm = torch.linalg.vector_norm(delta, dim=-1, keepdim=True).clamp(min=1.0e-12)
        pos = begin_pos + delta * torch.minimum(
            torch.ones_like(delta_norm), profile.max_position_revision_delta_m / delta_norm
        )

        begin_vel = self.racket_target_vel_w[ids]
        vel = begin_vel
        vel_std = float(self.cfg.planner_revision_velocity_std_mps)
        if vel_std > 0.0:
            proposal = vel + torch.randn_like(vel) * (vel_std * convergence)
        else:
            proposal = vel
        delta = proposal - begin_vel
        delta_norm = torch.linalg.vector_norm(delta, dim=-1, keepdim=True).clamp(min=1.0e-12)
        vel = begin_vel + delta * torch.minimum(
            torch.ones_like(delta_norm), profile.max_velocity_revision_delta_mps / delta_norm
        )

        truth_normal = self.target_normal_cmd[ids]
        normal_std = float(self.cfg.planner_revision_normal_std_rad)
        normal = truth_normal
        if normal_std > 0.0:
            tangent = torch.randn_like(normal)
            tangent -= (tangent * truth_normal).sum(dim=-1, keepdim=True) * truth_normal
            tangent /= torch.linalg.vector_norm(tangent, dim=-1, keepdim=True).clamp(min=1.0e-12)
            angle = torch.randn(len(ids), 1, device=self.device) * (
                normal_std * convergence
            )
            normal = truth_normal * torch.cos(angle) + tangent * torch.sin(angle)
        dot = (truth_normal * normal).sum(dim=-1, keepdim=True).clamp(-1.0, 1.0)
        angle = torch.acos(dot)
        ratio = torch.minimum(
            torch.ones_like(angle),
            profile.max_normal_revision_delta_rad / angle.clamp(min=1.0e-12),
        )
        normal = truth_normal + ratio * (normal - truth_normal)
        normal /= torch.linalg.vector_norm(normal, dim=-1, keepdim=True).clamp(min=1.0e-12)

        raw_truth_tts = motion._planner_truth_tts[ids]
        truth_tts = motion._planner_canonicalize_tts(raw_truth_tts, profile)
        tts = truth_tts
        tts_std = float(self.cfg.planner_revision_tts_std_s)
        if tts_std > 0.0:
            deadline_jitter = torch.randn_like(tts) * (
                tts_std * convergence.squeeze(-1)
            )
            deadline_jitter = deadline_jitter.clamp(
                min=-profile.max_deadline_revision_delta_s,
                max=profile.max_deadline_revision_delta_s,
            )
            tts = tts + deadline_jitter
        tts = tts.clamp(profile.min_tts_s, profile.max_tts_s)
        if coupled:
            # 耦合传输:本步生成的元组只入在途环;真正提交的是 d 步前生成的那一份(原子出队,
            # tts 已按源时间戳补偿/或按 uncompensated 原样)。记账与 last_precontact 改用
            # "提交时刻"的 truth 时钟——与消息到达中继的真实时刻一致。
            ids, pos, vel, normal, tts = self._exchange_pending_planner_revision(
                ids, pos, vel, normal, tts
            )
            if len(ids) == 0:
                self.metrics["planner_task_revision"] = (
                    self._planner_task_revision.clamp(min=0).float()
                )
                self.metrics["planner_same_task_revision_active"] = eligible.float()
                return
            truth_tts = motion._planner_canonicalize_tts(
                motion._planner_truth_tts[ids], profile
            )
        revision = self._planner_task_revision[ids] + 1
        accepted = motion.submit_planner_revision(
            ids,
            control_epoch=self._planner_control_epoch[ids],
            task_id=self._planner_task_id[ids],
            task_revision=revision,
            desired_tts=tts,
            target_position=pos,
            target_velocity=vel,
            target_normal=normal,
        )
        self._book_planner_revision_decisions(
            attempted_tts=truth_tts,
            accepted=accepted,
        )
        last_precontact = torch.isclose(
            truth_tts,
            torch.full_like(truth_tts, profile.min_tts_s),
            rtol=0.0,
            atol=profile.early_deadline_tolerance_s,
        )
        accepted_ids = ids[accepted]
        if len(accepted_ids) > 0:
            self._planner_task_revision[accepted_ids] = revision[accepted]
            self._planner_visible_pos[accepted_ids] = pos[accepted]
            self._planner_visible_vel[accepted_ids] = vel[accepted]
            self._planner_visible_normal[accepted_ids] = normal[accepted]
            self._planner_visible_tts[accepted_ids] = tts[accepted]
            self._planner_visible_last_precontact[accepted_ids] = last_precontact[accepted]
        self.metrics["planner_task_revision"] = self._planner_task_revision.clamp(min=0).float()
        self.metrics["planner_same_task_revision_active"] = eligible.float()

    def _exchange_pending_planner_revision(
        self,
        ids: torch.Tensor,
        pos: torch.Tensor,
        vel: torch.Tensor,
        normal: torch.Tensor,
        tts: torch.Tensor,
    ) -> tuple[torch.Tensor, torch.Tensor, torch.Tensor, torch.Tensor, torch.Tensor]:
        """耦合传输在途环的一次"压入本步 / 弹出 d 步前"交换(每控制步恰好调用一次)。

        单指针环(长度 d):先读槽 p(恰好是 d 步前写入的元组),再把本步生成的元组写进
        同一个槽,指针前进——生成于 t 的修订恰在 t+d 提交,d=2 时效果整整晚 2 步。
        出队的 tts 处理遵循 target_delay_tts_mode:
        * source_timestamp_compensated——减去在途时长 d*dt(runner 的源时间戳补偿),
          提交进调度器的 deadline ≈ 提交时刻的真实剩余时间,actor 时钟连续;
        * uncompensated——原样提交(显式陈旧 tts 阴性对照;调度器可能因 deadline 超过
          begin 包络而拒收,这正是该对照要暴露的行为)。
        无效槽位不提交:当步没生成(env 不在 eligible 集),或新任务安装时被
        _begin_same_ball_planner_task 作废(旧球消息不得进新任务)。补偿后过期的元组
        交给 submit_planner_revision 的接受判据拒收(fail-safe 拒绝并记账,而非静默丢弃)。
        """
        if tts.dim() != 1 or pos.shape != (len(ids), 3) or vel.shape != (len(ids), 3) \
                or normal.shape != (len(ids), 3) or len(tts) != len(ids):
            raise ValueError(
                "coupled transport exchange expects one atomic (pos, vel, normal, tts) tuple "
                "per generating env"
            )
        p = self._pend_ptr
        out_valid = self._pend_valid[p].clone()
        out_pos = self._pend_pos[p].clone()
        out_vel = self._pend_vel[p].clone()
        out_normal = self._pend_normal[p].clone()
        out_tts = self._pend_tts[p].clone()
        self._pend_valid[p] = False
        self._pend_valid[p, ids] = True
        self._pend_pos[p, ids] = pos
        self._pend_vel[p, ids] = vel
        self._pend_normal[p, ids] = normal
        self._pend_tts[p, ids] = tts
        self._pend_ptr = (p + 1) % int(self._pend_valid.shape[0])
        sub_ids = torch.where(out_valid)[0]
        sub_tts = out_tts[sub_ids]
        if self._delay_tts_mode == "source_timestamp_compensated":
            sub_tts = sub_tts - self._delay_steps * float(self._env.step_dt)
        return sub_ids, out_pos[sub_ids], out_vel[sub_ids], out_normal[sub_ids], sub_tts

    def _book_planner_revision_decisions(
        self,
        *,
        attempted_tts: torch.Tensor,
        accepted: torch.Tensor,
    ) -> None:
        """Book exact actor-revision activation, including the final pre-contact tick."""

        if not self.planner_revision_enabled or self._planner_revision_profile is None:
            raise RuntimeError("planner revision decisions require an enabled validated profile")
        tts = attempted_tts.detach().reshape(-1)
        decisions = accepted.detach().reshape(-1)
        if decisions.dtype != torch.bool:
            raise TypeError("planner revision accepted mask must have boolean dtype")
        if tts.shape != decisions.shape:
            raise ValueError("planner revision TTS and decision masks must have identical shape")
        if not bool(torch.isfinite(tts).all()):
            raise ValueError("planner revision attempted TTS must be finite")
        ledger = self._ensure_exact_behavior_decision_counters()
        last_tick = torch.isclose(
            tts,
            torch.full_like(tts, self._planner_revision_profile.min_tts_s),
            rtol=0.0,
            atol=self._planner_revision_profile.early_deadline_tolerance_s,
        )
        ledger["planner_revision_attempt_count"].add_(tts.numel())
        ledger["planner_revision_accepted_count"].add_(
            decisions.sum(dtype=torch.long)
        )
        ledger["planner_revision_rejected_count"].add_(
            (~decisions).sum(dtype=torch.long)
        )
        ledger["planner_revision_last_precontact_attempt_count"].add_(
            last_tick.sum(dtype=torch.long)
        )
        ledger["planner_revision_last_precontact_accepted_count"].add_(
            (last_tick & decisions).sum(dtype=torch.long)
        )

    def _invalidate_strike_timing_metrics_handoff(self) -> None:
        """Invalidate the one-shot metrics -> update timing handoff.

        This only mutates two Python scalars.  In particular, it never inspects a CUDA tensor.
        ``getattr``-tolerant consumers constructed through ``__new__`` therefore keep the historic
        direct-call behavior even if they did not run the full initializer.
        """

        self._strike_timing_metrics_step_token = None
        self._strike_timing_metrics_handoff_pending = False

    def _refresh_strike_timing_for_policy_step(self, *, metrics_pass: bool) -> None:
        """Refresh timing, skipping only CommandTerm's same-step duplicate update call.

        Isaac Lab calls this term's ``_update_metrics`` and then ``_update_command`` with the same
        host ``common_step_counter``.  The metrics pass owns the phase-aligned refresh; the ordered
        update pass may consume that result exactly once.  Any direct update, missing/non-integer
        token, token change, reset/resample, or intervening direct timing refresh recomputes.
        """

        if type(metrics_pass) is not bool:
            raise TypeError("strike timing cache metrics_pass must be boolean")
        token = getattr(self._env, "common_step_counter", None)
        if (
            not metrics_pass
            and type(token) is int
            and getattr(
                self, "_strike_timing_metrics_handoff_pending", False
            )
            and getattr(self, "_strike_timing_metrics_step_token", None)
            == token
        ):
            # One-shot consumption is what preserves direct _update_command semantics when a caller
            # invokes it again without an intervening metrics pass.
            self._invalidate_strike_timing_metrics_handoff()
            return

        self._compute_strike_timing()
        if metrics_pass and type(token) is int:
            self._strike_timing_metrics_step_token = token
            self._strike_timing_metrics_handoff_pending = True
        else:
            self._invalidate_strike_timing_metrics_handoff()

    def _compute_strike_timing(self):
        """Refresh time_to_strike / pre_strike / strike_window from the CURRENT motion phase.

        The ``motion`` command term computes before this one (it is a parent-class field, registered
        first), so by now ``motion.time_steps`` is already advanced for this control step. Computing the
        timing here — at the top of _update_metrics, alongside the fresh racket FK — keeps the strike
        masks ALIGNED with the racket pose they gate. Previously the masks were only set in
        _update_command (which runs AFTER _update_metrics), so _update_metrics read a 1-step-stale
        time_to_strike: ``exact_strike`` fired one control frame LATE, after the paddle had flown ~one
        step past the strike (~12 cm at a 6 m/s swing) — which collapsed the measured position accuracy
        (exact-strike pos<7.5cm read ~11% instead of the true ~68%) while barely moving velocity (flat
        near the peak). That made strike_composite_success_exact ~6x pessimistic vs the honest probe.
        """
        # This public/internal seam is also used directly by reset-time evaluators and source tests.
        # A direct refresh must make any earlier metrics handoff unconsumable.
        self._invalidate_strike_timing_metrics_handoff()
        motion = self._motion()
        ml = motion.motion
        # Legacy/unit consumers construct a minimal command around this timing
        # helper without running the full action-ball initializer.  Missing the
        # opt-in flag therefore means the legacy clock, never an implicit
        # action-ball task.
        if (
            getattr(self, "_action_ball_enabled", False)
            or getattr(self, "_action_ball_full_mdp_enabled", False)
        ):
            timing_active = motion.action_ball_task_timing_active
            async_validate = bool(
                getattr(
                    self,
                    "_action_ball_diagnostic_unauthorized",
                    False,
                )
            )
            if getattr(self, "_action_ball_full_mdp_enabled", False):
                receipt_active = (
                    motion.action_ball_current_task_receipt_active
                )
                if (
                    not torch.is_tensor(receipt_active)
                    or receipt_active.dtype != torch.bool
                    or tuple(receipt_active.shape) != (self.num_envs,)
                    or receipt_active.device != timing_active.device
                ):
                    raise RuntimeError(
                        "FullMDP Motion current-receipt mask is malformed"
                    )
                _action_ball_validate_tensor_predicate(
                    receipt_active.eq(timing_active),
                    "FullMDP Motion current receipt and timing activity differ",
                    async_validate=async_validate,
                )
            elif hasattr(self, "_action_ball_attempt_active"):
                wrapped = getattr(motion, "just_resampled", None)
                if wrapped is None:
                    wrapped = torch.zeros_like(timing_active)
                elif (
                    wrapped.dtype != torch.bool
                    or tuple(wrapped.shape) != (self.num_envs,)
                ):
                    raise RuntimeError(
                        "action-ball Motion just_resampled mask is malformed"
                    )
                invalid_active_timing = (
                    self._action_ball_attempt_active
                    & ~timing_active
                    & ~wrapped
                )
                _action_ball_validate_tensor_predicate(
                    ~invalid_active_timing,
                    "active action-ball task has no receipt-owned Motion timing",
                    async_validate=async_validate,
                )
            # TTC is the task deadline.  It includes the canonical-ready wait,
            # the scaled approach to contact, and remains signed after contact;
            # legacy clip phase / speed division is not an independent clock.
            self.time_to_strike = (
                motion.action_ball_time_to_contact_remaining_s.to(
                    dtype=self.time_to_strike.dtype
                )
            )
            self.pre_strike = self.time_to_strike > 0.0
            tts_abs = self.time_to_strike.abs()
            self.strike_window = tts_abs <= self.cfg.strike_window_s
            pos_window_s = self.cfg.strike_window_pos_s
            wide_window_s = self.cfg.strike_window_wide_s
            self.strike_window_pos = (
                self.strike_window
                if pos_window_s is None
                else tts_abs <= float(pos_window_s)
            )
            self.strike_window_wide = (
                self.strike_window
                if wide_window_s is None
                else tts_abs <= float(wide_window_s)
            )
            return
        if motion._multiseg:
            # Per-clip strike frame on the concatenated time axis: the contact phase differs per swing
            # (v2 blade re-plane: forehand 0.47, backhand 0.333), so resolve strike_step per env from its clip.
            if self._strike_phase_per_clip_t is None:
                sp = self._strike_phases_cfg(int(ml.num_segments))
                if sp:
                    self._strike_phase_per_clip_t = torch.tensor([float(x) for x in sp], device=self.device)
                else:
                    self._strike_phase_per_clip_t = torch.full(
                        (int(ml.num_segments),), float(self.cfg.strike_phase), device=self.device
                    )
            clip = motion.clip_id
            seg_start = ml.seg_start[clip]
            seg_len = ml.seg_len[clip]
            phase = self._strike_phase_per_clip_t[clip]
            strike_step = seg_start + (phase * (seg_len - 1).float()).round().long()
            if motion.retiming_active:
                # R14: at playback speed s the clock covers (strike_step - t) frames in
                # (strike_step - t)/s control steps. Use the FLOAT clock so tts still decreases by
                # exactly step_dt per unheld step and the exact-strike detector fires once per swing.
                self.time_to_strike = (
                    (strike_step.float() - motion.time_steps_f) * self._env.step_dt / motion.speed_scale
                )
            else:
                self.time_to_strike = (strike_step - motion.time_steps).float() * self._env.step_dt
        else:
            total = max(int(ml.time_step_total), 1)
            strike_step = round(self.cfg.strike_phase * (total - 1))
            if motion.retiming_active:
                self.time_to_strike = (
                    (float(strike_step) - motion.time_steps_f) * self._env.step_dt / motion.speed_scale
                )
            else:
                self.time_to_strike = (strike_step - motion.time_steps).float() * self._env.step_dt
        # 窗掩码时钟:默认 = 上面算好的 legacy 有符号 clip 时钟(planner 关时天然 ±窗)。
        tts_for_window = self.time_to_strike
        if self.planner_revision_enabled:
            if not motion.planner_revision_enabled:
                raise RuntimeError(
                    "half-configured planner revisions: motion governor disabled at runtime"
                )
            # Physical-ball/reward/critic truth is the immutable task deadline, independent of
            # the actor's noisy revised estimate and independent of the reference phase chosen to
            # meet it.  This breaks the old circular definition (TTS derived from clip phase).
            # Schema-4 owns a task deadline: it reaches zero at contact and
            # remains zero through follow-through.  Legacy clip-derived clocks
            # keep their historical signed post-strike values above.
            self.time_to_strike = motion._planner_truth_tts.clamp(min=0.0)
            # 击球窗掩码改读带符号孪生时钟(2026-07-25):deadline 的钉 0 曾让
            # |tts|<=0.12 的窗覆盖整个随挥段(~50-100 步)——position/normal 触球后
            # 停拍可薅钱、站稳包/face 税全程计费、模仿在恢复段被 0.25x 捂嘴。
            # 窗回到设计的 ±0.12 s;time_to_strike/pre_strike/exact_strike(自带
            # 一拍锁存)语义不变,obs/critic 仍读钉 0 的任务期限。
            tts_for_window = motion._planner_truth_tts_signed
        if getattr(motion, "event_timing_enabled", False):
            # For a successfully revealed T1 row, WHEN is owned by the immutable schedule rather
            # than by the clip phase.  The native clip/hold pair is only the feasible trajectory
            # used to arrive there; it may never move the deadline.  Pending, unavailable and
            # infeasible rows keep their old clip timing but are masked out of exact grading below.
            event_mask = motion.event_installed
            scheduled_tts = (
                motion.event_deadline_ticks_remaining.float() * self._env.step_dt
            )
            self.time_to_strike = torch.where(event_mask, scheduled_tts, self.time_to_strike)
            # event timing 现役全 disabled;若启用,T1 行的 deadline ticks 亦是截断时钟,
            # 其窗关闭语义待事件时钟带符号化时再接(掩码暂沿用 tts_for_window)。
        self.pre_strike = self.time_to_strike > 0.0
        _tts_abs = tts_for_window.abs()
        self.strike_window = _tts_abs <= self.cfg.strike_window_s
        # 1c split windows: POSITION gets the tight window, NORMAL/VELOCITY the wide one; None
        # (default) falls back to strike_window_s for that channel — numerically identical to the
        # legacy single window. The stability penalties / hit-rate metric keep strike_window.
        _pos_s = self.cfg.strike_window_pos_s
        _wide_s = self.cfg.strike_window_wide_s
        self.strike_window_pos = self.strike_window if _pos_s is None else (_tts_abs <= float(_pos_s))
        self.strike_window_wide = self.strike_window if _wide_s is None else (_tts_abs <= float(_wide_s))

    def compute(self, dt: float):
        fresh_lane = getattr(
            self,
            "_action_ball_continuous_fresh_racket_lane_bound",
            False,
        ) is True
        if fresh_lane:
            if not _tensor_matches_identity_version_receipt(
                getattr(self, "time_left", None),
                getattr(
                    self,
                    "_action_ball_continuous_fresh_racket_time_left_receipt",
                    None,
                ),
            ):
                self.poison_global_reveal_epoch(
                    "fresh Racket inherited resample timer drifted"
                )
                raise ActionBallContinuousRacketHotRevealHold(
                    "fresh Racket inherited resample timer drifted"
                )
            # Preserve IsaacLab's metric/timer/update order.  Expiry is
            # impossible because the construction-bound timer is literal
            # infinity, while the legacy resampler is intentionally a fresh
            # lane tombstone and D05 owns every live command/timing write.
            self._update_metrics()
            self.time_left -= dt
            receipt = _tensor_identity_version_receipt(self.time_left)
            if receipt is None:
                self.poison_global_reveal_epoch(
                    "fresh Racket inherited resample timer became unsealable"
                )
                raise ActionBallContinuousRacketHotRevealHold(
                    "fresh Racket inherited resample timer became unsealable"
                )
            self._action_ball_continuous_fresh_racket_time_left_receipt = (
                receipt
            )
            self._update_command()
            return
        fast_path_complete = _compute_without_disabled_time_resampling_scan(
            self, dt
        )
        if not fast_path_complete:
            super().compute(dt)
        # Both branches have now completed _update_metrics followed by
        # _update_command.  ManagerBasedRLEnv is after Reward here, so this
        # single tail owns the arm for the next physics transition.
        # The fresh lane instead settles D05 after CommandManager returns and
        # only then arms R03 from the newly current ActionEpoch.  Arming here
        # would bind the previous epoch on both command zero and reveal ticks.
        self._arm_action_ball_strike_fact_for_next_transition()

    def _resample(self, env_ids: Sequence[int]):
        _poison_disabled_time_resampling_fast_path_on_drift(self)
        _revoke_disabled_time_resampling_fast_path_on_timer_drift(self)
        super()._resample(env_ids)
        _arm_disabled_time_resampling_fast_path_after_resample(
            self, env_ids
        )

    def _motion_wrap_ids_for_target_resample(self, motion):
        """Return true motion-wrap rows, skipping only the proven-empty lane."""

        if _split_ready_nonloop_wrap_scan_is_impossible(motion):
            return torch.empty(0, dtype=torch.long, device=self.device)
        if hasattr(motion, "just_resampled"):
            return torch.where(motion.just_resampled)[0]
        return torch.where(motion.time_steps < self._prev_motion_steps)[0]

    def _update_command(self):
        if getattr(
            self,
            "_action_ball_continuous_fresh_racket_lane_bound",
            False,
        ) is True:
            # D05/ActionEpoch callbacks are the sole writers of every fresh
            # Racket command/timing buffer.  CommandManager still invokes this
            # hook at genesis and on every policy step; its fresh behavior is
            # deliberately a write-free no-op before legacy initialization,
            # wrap detection, target sampling, or task mutation can run.
            return
        self._ensure_action_ball_runtime_initialized()
        motion = self._motion()
        # Normal CommandTerm order consumes the phase-aligned metrics refresh exactly once.  A direct
        # _update_command call, reset/resample, or token mismatch recomputes through the same helper.
        self._refresh_strike_timing_for_policy_step(metrics_pass=False)
        if self._action_ball_enabled:
            # Motion owns the first update in CommandManager order.  Its clocks
            # have therefore consumed this policy tick before the reveal bit is
            # advanced; on the exact reveal tick the visible remaining clocks
            # equal the original immutable receipt values.
            self._advance_action_ball_task_wait()

        # Re-sample the target at each new swing. Use the motion command's robust just_resampled signal
        # (set this same step when it wrapped a swing) instead of a time_steps<prev heuristic — the latter
        # fails for the unified policy when a wrap jumps the index to a HIGHER concatenated segment start
        # (forehand->backhand). Targets for fresh episodes are sampled by the manager's reset.
        event_ids = (
            torch.where(motion.event_just_installed)[0]
            if getattr(motion, "event_timing_enabled", False)
            else torch.empty(0, dtype=torch.long, device=self.device)
        )
        if len(event_ids) > 0:
            self._install_event_training_questions(
                event_ids,
                motion.event_current_clip_id[event_ids],
                motion.event_current_bank_row[event_ids],
            )
        wrapped = self._motion_wrap_ids_for_target_resample(motion)
        if len(wrapped) > 0:
            # Wrap path: a wrapped env passed its strike frame alive (strike < seg end), so no
            # pre-strike fall is counted — the flag only gates fall accounting inside
            # _resample_command's _count_swing_starts hook.
            if motion._multiseg:
                # Latch the clip that JUST finished (before _prev_clip_id is re-snapshotted below):
                # while the post-wrap hold lasts, a fall belongs to THIS swing's recovery.
                self._recover_from_clip[wrapped] = self._prev_clip_id[wrapped]
            self._resample_is_wrap = True
            try:
                self._resample_command(wrapped)
            finally:
                self._resample_is_wrap = False
        # The recovery window ends when the post-wrap hold expires (the new swing's clock starts
        # advancing) — from then on falls are genuinely pre-strike of the new clip. in_hold is this
        # step's post-decrement hold state, so a zero-length hold clears the latch immediately.
        if hasattr(motion, "in_hold") and self._task_first_enabled:
            self._task_first_finish_recovery_holds(motion.in_hold)
        if motion._multiseg and hasattr(motion, "in_hold"):
            self._recover_from_clip[~motion.in_hold] = -1
        self._prev_motion_steps = motion.time_steps.clone()
        # Snapshot the clip each env is swinging THIS step: at the next true reset the motion command
        # will already have resampled clip_id, so fall attribution reads this snapshot instead.
        if motion._multiseg:
            self._prev_clip_id = motion.clip_id.clone()

        # --- A1 mid-swing target refinement (the planner refines WHERE, not WHEN) -------------------
        # Each step, envs still approaching the strike (pre_strike AND time_to_strike > tts floor)
        # re-draw their target with per-step prob p, exactly as the deploy planner refines its ball
        # prediction mid-swing. ONLY the target sampling runs (position/velocity/normal through the
        # existing uniform / per-clip-box / reference-perturbed path, including the HER achieved-target
        # mixture inside it):
        #   * strike timing untouched — same strike step, the swing clock keeps running;
        #   * NO _count_swing_starts — a refinement is not a new swing attempt (metrics denominators
        #     would otherwise be inflated);
        #   * base target / swing type / _prev_motion_steps untouched;
        #   * the racket-progress baseline is reset via _progress_reset_mask (same mechanism as the
        #     resample path) so the target jump creates no fake progress reward;
        #   * the achieved-target replay WRITE is unaffected (it stores the LIVE target state at
        #     exact-strike frames, and tts floor > 0 keeps refinement away from the strike frame).
        # prob==0 (default) short-circuits before any RNG draw — byte-identical baseline.
        _ms_prob = float(self.cfg.midswing_resample_prob)
        if _ms_prob > 0.0:
            eligible = self.pre_strike & (self.time_to_strike > float(self.cfg.midswing_resample_tts_floor))
            redraw = eligible & (torch.rand(self.num_envs, device=self.device) < _ms_prob)
            ids = torch.where(redraw)[0]
            if len(ids) > 0:
                origins = self._env.scene.env_origins[ids]
                if self.cfg.target_mode == "reference_perturbed":
                    self._sample_targets_reference_perturbed(ids, origins, len(ids))
                elif self.cfg.target_mode == "hitter_pure":
                    # Refinement re-draws WHERE around the UNCHANGED station (paper Fig. 3
                    # convergence; the commanded stance never teleports mid-swing).
                    self._sample_targets_hitter_pure(ids, origins, len(ids), resample_base=False)
                else:
                    self._sample_targets_uniform(ids, origins, len(ids))
                self._prev_racket_dist[ids] = torch.norm(
                    self.racket_pos_w[ids] - self.racket_target_pos_w[ids], dim=-1
                ).detach()
                self.racket_progress[ids] = 0.0
                self._progress_reset_mask[ids] = True
            # Per-env 0/1 indicator; the wandb reset-mean = per-step refinement fraction (~ prob *
            # eligible fraction). Written every step while the feature is on so zero-redraw steps count.
            self.metrics["midswing_resample_count"] = redraw.float()

        # Same-ball planner: refine the complete estimate (including WHEN) without changing truth.
        self._revise_same_ball_actor_tuple()

        # A1 target latency/jitter: refresh the ACTOR-visible target view once per step (no-op alias
        # when the knobs are off). Runs LAST so it sees this step's wrap/refinement target updates.
        self._push_actor_target()
        # CommandTerm.compute() ran exact-strike metrics before this update.  Consume every due
        # opportunity now regardless of whether the policy hit it, so a miss cannot pause or shift
        # the immutable sequence.  MotionCommand will fail closed next step if this handoff is ever
        # skipped, preventing a stale due row from being silently extended.
        if getattr(motion, "event_timing_enabled", False):
            motion.finalize_event_deadlines()

    def _push_actor_target(self):
        """A1: refresh the ACTOR-visible target view once per control step (latency + jitter).

        Applied on PUSH (not on read) so the jitter is drawn ONCE per step and every actor obs term
        reads the same tensor within the step (determinism). The jitter std decays with the time to
        strike (SMASH Eq. 14 — the mocap ball prediction converges as the strike approaches):
        per-step std = knob * clamp(time_to_strike, 0, 1). The ring buffer stores the jittered
        values, so a delayed read reproduces the prediction noise AS OF push time (what the mocap
        link actually emitted then). The TRUE live target is untouched — rewards, metrics, the
        privileged critic, and the achieved-target-replay write keep reading racket_target_pos_w /
        racket_target_vel_w / target_normal_cmd / swing_sign / time_to_strike.  In the explicit
        non-live TTS modes, all five actor-visible fields are emitted atomically: delay and dropout
        can never mix two question rows. ``source_timestamp_compensated`` advances the delayed
        source TTS by the configured transport age; ``uncompensated`` deliberately exposes the
        stale source value as a negative control.
        """
        if not self._actor_view_active:
            self.metrics["actor_time_to_strike_s"][:] = self.time_to_strike
            return  # default path: delayed_* alias the live tensors — nothing to compute, no RNG
        pos = (
            self._planner_visible_pos
            if self.planner_revision_enabled
            else self.racket_target_pos_w
        )
        vel = (
            self._planner_visible_vel
            if self.planner_revision_enabled
            else self.racket_target_vel_w
        )
        normal = (
            self._planner_visible_normal
            if self.planner_revision_enabled
            else self.target_normal_cmd
        )
        sign = self.swing_sign
        tts = (
            self._planner_visible_tts
            if self.planner_revision_enabled
            else self.time_to_strike
        )
        if self.planner_revision_enabled:
            tts = tts.clamp(min=0.0)
            planner_epoch = self._planner_control_epoch
            planner_task = self._planner_task_id
            planner_revision = self._planner_task_revision
            planner_last_precontact = self._planner_visible_last_precontact
        if self._jitter_pos > 0.0 or self._jitter_vel > 0.0:
            scale = self.time_to_strike.clamp(0.0, 1.0).unsqueeze(-1)
            if self._jitter_pos > 0.0:
                pos = pos + torch.randn_like(pos) * (self._jitter_pos * scale)
            if self._jitter_vel > 0.0:
                vel = vel + torch.randn_like(vel) * (self._jitter_vel * scale)
        if self._mnoise_ar1_sigma > 0.0:
            rho = self._mnoise_ar1_rho
            self._mnoise_ar1_state.mul_(rho).add_(
                torch.randn_like(self._mnoise_ar1_state), alpha=self._mnoise_ar1_sigma * (1.0 - rho * rho) ** 0.5
            )
            pos = pos + self._mnoise_ar1_state
        if self._mnoise_white > 0.0:
            pos = pos + torch.randn_like(pos) * self._mnoise_white
        if self._a1v2_active:
            # (c) per-swing systematic bias: resample at each strike moment (pre_strike falling edge
            # = sensor re-lock after the contact), constant until the next strike.
            struck = self._prev_pre_strike & ~self.pre_strike
            if self._bias_per_swing > 0.0 and struck.any():
                self._swing_bias[struck] = torch.randn(int(struck.sum()), 3, device=self.device) * self._bias_per_swing
            # (b) forced hold-last window right after the strike (sensor loses the target at contact)
            if self._post_strike_drop_steps > 0 and struck.any():
                self._drop_cd[struck] = self._post_strike_drop_steps
            self._prev_pre_strike.copy_(self.pre_strike)
            pos = pos + self._swing_bias
            # (a) random frame loss + (b) countdown: actor view HOLDS the last emitted value
            drop = self._drop_cd > 0
            if self._drop_prob > 0.0:
                drop = drop | (torch.rand(self.num_envs, device=self.device) < self._drop_prob)
            self._drop_cd = (self._drop_cd - 1).clamp_(min=0)
            d3 = drop.unsqueeze(-1)
            pos = torch.where(d3, self._held_pos, pos)
            vel = torch.where(d3, self._held_vel, vel)
            normal = torch.where(d3, self._held_normal, normal)
            sign = torch.where(drop, self._held_sign, sign)
            if self._atomic_tts_active:
                tts = torch.where(drop, self._held_tts, tts)
            if self.planner_revision_enabled:
                planner_epoch = torch.where(drop, self._held_planner_epoch, planner_epoch)
                planner_task = torch.where(drop, self._held_planner_task, planner_task)
                planner_revision = torch.where(
                    drop, self._held_planner_revision, planner_revision
                )
                planner_last_precontact = torch.where(
                    drop,
                    self._held_planner_last_precontact,
                    planner_last_precontact,
                )
            self._held_pos.copy_(pos)
            self._held_vel.copy_(vel)
            self._held_normal.copy_(normal)
            self._held_sign.copy_(sign)
            if self._atomic_tts_active:
                self._held_tts.copy_(tts)
            if self.planner_revision_enabled:
                self._held_planner_epoch.copy_(planner_epoch)
                self._held_planner_task.copy_(planner_task)
                self._held_planner_revision.copy_(planner_revision)
                self._held_planner_last_precontact.copy_(planner_last_precontact)
        if self._actor_ring_steps > 0:
            # Write this step's (jittered) target into slot `w`; the next slot in the length-
            # (delay+1) ring was written exactly `delay` pushes ago — that is the actor's view.
            w = self._delay_ptr
            self._delay_buf_pos[w].copy_(pos)
            self._delay_buf_vel[w].copy_(vel)
            self._delay_buf_normal[w].copy_(normal)
            self._delay_buf_sign[w].copy_(sign)
            if self._atomic_tts_active:
                self._delay_buf_tts[w].copy_(tts)
            if self.planner_revision_enabled:
                self._delay_buf_planner_epoch[w].copy_(planner_epoch)
                self._delay_buf_planner_task[w].copy_(planner_task)
                self._delay_buf_planner_revision[w].copy_(planner_revision)
                self._delay_buf_planner_last_precontact[w].copy_(
                    planner_last_precontact
                )
            r = (w + 1) % (self._actor_ring_steps + 1)
            self._delay_ptr = r
            self.delayed_racket_target_pos_w.copy_(self._delay_buf_pos[r])
            self.delayed_racket_target_vel_w.copy_(self._delay_buf_vel[r])
            self.delayed_target_normal_cmd.copy_(self._delay_buf_normal[r])
            self.delayed_swing_sign.copy_(self._delay_buf_sign[r])
            if self._atomic_tts_active:
                delayed_tts = self._delay_buf_tts[r]
                if self._delay_tts_mode == "source_timestamp_compensated":
                    delayed_tts = delayed_tts - self._actor_ring_steps * float(self._env.step_dt)
                if self.planner_revision_enabled:
                    delayed_tts = delayed_tts.clamp(min=0.0)
                self.delayed_time_to_strike.copy_(delayed_tts)
            if self.planner_revision_enabled:
                self._book_planner_revision_actor_delivery(
                    self._delay_buf_planner_epoch[r],
                    self._delay_buf_planner_task[r],
                    self._delay_buf_planner_revision[r],
                    self._delay_buf_planner_last_precontact[r],
                )
        else:
            # Jitter-only (delay==0): the actor view is live + this step's noise, no latency.
            self.delayed_racket_target_pos_w.copy_(pos)
            self.delayed_racket_target_vel_w.copy_(vel)
            self.delayed_target_normal_cmd.copy_(normal)
            self.delayed_swing_sign.copy_(sign)
            if self._atomic_tts_active:
                # Zero transport delay is explicitly equivalent to live TTS in both atomic modes.
                self.delayed_time_to_strike.copy_(tts)
            if self.planner_revision_enabled:
                self._book_planner_revision_actor_delivery(
                    planner_epoch,
                    planner_task,
                    planner_revision,
                    planner_last_precontact,
                )
        self.metrics["actor_time_to_strike_s"][:] = self.actor_time_to_strike()

    def _book_planner_revision_actor_delivery(
        self,
        control_epoch: torch.Tensor,
        task_id: torch.Tensor,
        task_revision: torch.Tensor,
        last_precontact: torch.Tensor,
    ) -> None:
        """Count a revision only when its complete atomic tuple reaches actor observations."""

        epoch = control_epoch.detach().reshape(-1)
        task = task_id.detach().reshape(-1)
        revision = task_revision.detach().reshape(-1)
        last = last_precontact.detach().reshape(-1)
        expected = self._planner_actor_task_revision.shape
        if (
            epoch.shape != expected
            or task.shape != expected
            or revision.shape != expected
            or last.shape != expected
            or last.dtype != torch.bool
        ):
            raise ValueError("actor-visible planner identity must be one complete per-env tuple")
        changed = (
            (epoch > 0)
            & (task > 0)
            & (
                (epoch != self._planner_actor_control_epoch)
                | (task != self._planner_actor_task_id)
                | (revision != self._planner_actor_task_revision)
            )
        )
        delivered_revision = changed & (revision > 1)
        ledger = self._ensure_exact_behavior_decision_counters()
        ledger["planner_revision_actor_visible_count"].add_(
            delivered_revision.sum(dtype=torch.long)
        )
        ledger["planner_revision_last_precontact_actor_visible_count"].add_(
            (delivered_revision & last & self.pre_strike.detach().bool()).sum(
                dtype=torch.long
            )
        )
        self._planner_actor_control_epoch.copy_(
            torch.where(changed, epoch, self._planner_actor_control_epoch)
        )
        self._planner_actor_task_id.copy_(
            torch.where(changed, task, self._planner_actor_task_id)
        )
        self._planner_actor_task_revision.copy_(
            torch.where(changed, revision, self._planner_actor_task_revision)
        )

    def _reset_actor_target_state(self, env_ids: Sequence[int]) -> None:
        """Start a true episode with a fresh, internally consistent A1 sensor state.

        The runner receives a complete planner command before its first policy step.  Mirror that
        contract by replacing every delayed/held field with the newly sampled command and clearing
        stochastic state that must not cross an episode boundary.  This helper is intentionally not
        used on clip wraps, which are the within-session latency/dropout transitions A1 trains.
        """
        if not self._actor_view_active or len(env_ids) == 0:
            return
        ids = torch.as_tensor(env_ids, dtype=torch.long, device=self.device)
        source_pos = self._planner_visible_pos if self.planner_revision_enabled else self.racket_target_pos_w
        source_vel = self._planner_visible_vel if self.planner_revision_enabled else self.racket_target_vel_w
        source_normal = self._planner_visible_normal if self.planner_revision_enabled else self.target_normal_cmd
        source_tts = self._planner_visible_tts if self.planner_revision_enabled else self.time_to_strike
        if self.planner_revision_enabled:
            source_tts = source_tts.clamp(min=0.0)
        self.delayed_racket_target_pos_w[ids] = source_pos[ids]
        self.delayed_racket_target_vel_w[ids] = source_vel[ids]
        self.delayed_target_normal_cmd[ids] = source_normal[ids]
        self.delayed_swing_sign[ids] = self.swing_sign[ids]
        if self._atomic_tts_active:
            self.delayed_time_to_strike[ids] = source_tts[ids]
        if self._mnoise_ar1_sigma > 0.0:
            self._mnoise_ar1_state[ids] = 0.0
        if self._a1v2_active:
            self._swing_bias[ids] = 0.0
            self._drop_cd[ids] = 0
            self._prev_pre_strike[ids] = True
            self._held_pos[ids] = source_pos[ids]
            self._held_vel[ids] = source_vel[ids]
            self._held_normal[ids] = source_normal[ids]
            self._held_sign[ids] = self.swing_sign[ids]
            if self._atomic_tts_active:
                self._held_tts[ids] = source_tts[ids]
            if self.planner_revision_enabled:
                self._held_planner_epoch[ids] = self._planner_control_epoch[ids]
                self._held_planner_task[ids] = self._planner_task_id[ids]
                self._held_planner_revision[ids] = self._planner_task_revision[ids]
                self._held_planner_last_precontact[ids] = (
                    self._planner_visible_last_precontact[ids]
                )
        if self._actor_ring_steps > 0:
            self._delay_buf_pos[:, ids] = source_pos[ids].unsqueeze(0)
            self._delay_buf_vel[:, ids] = source_vel[ids].unsqueeze(0)
            self._delay_buf_normal[:, ids] = source_normal[ids].unsqueeze(0)
            self._delay_buf_sign[:, ids] = self.swing_sign[ids].unsqueeze(0)
            if self._atomic_tts_active:
                self._delay_buf_tts[:, ids] = source_tts[ids].unsqueeze(0)
            if self.planner_revision_enabled:
                self._delay_buf_planner_epoch[:, ids] = (
                    self._planner_control_epoch[ids].unsqueeze(0)
                )
                self._delay_buf_planner_task[:, ids] = (
                    self._planner_task_id[ids].unsqueeze(0)
                )
                self._delay_buf_planner_revision[:, ids] = (
                    self._planner_task_revision[ids].unsqueeze(0)
                )
                self._delay_buf_planner_last_precontact[:, ids] = (
                    self._planner_visible_last_precontact[ids].unsqueeze(0)
                )
        if self.planner_revision_enabled:
            # A true reset hands the initial revision to the actor immediately;
            # seed the high-water mark without booking it as a same-task revision.
            self._planner_actor_control_epoch[ids] = self._planner_control_epoch[ids]
            self._planner_actor_task_id[ids] = self._planner_task_id[ids]
            self._planner_actor_task_revision[ids] = self._planner_task_revision[ids]

    def _task_first_reset_outcome_masks(
        self, ids: torch.Tensor
    ) -> tuple[torch.Tensor, torch.Tensor]:
        """Return ``(unsafe, terminal_or_timeout)`` for one true-reset transaction."""

        manager = getattr(self._env, "termination_manager", None)
        if manager is None:
            raise RuntimeError("task-first true reset has no termination manager")
        active_terms = set(str(name) for name in getattr(manager, "active_terms", ()))
        missing_unsafe = sorted(
            set(_TASK_FIRST_UNSAFE_TERMINATIONS) - active_terms
        )
        if missing_unsafe:
            raise RuntimeError(
                "task-first requires every unsafe termination to be active; "
                "otherwise the unsafe-failure gate would report a false zero. "
                f"Missing: {missing_unsafe}"
            )
        terminated = self._selected_bool(
            getattr(
                manager,
                "terminated",
                torch.zeros((), dtype=torch.bool, device=self.device),
            ),
            ids,
        )
        timed_out = self._selected_bool(
            getattr(
                manager,
                "time_outs",
                torch.zeros((), dtype=torch.bool, device=self.device),
            ),
            ids,
        )
        unsafe = torch.zeros(len(ids), dtype=torch.bool, device=self.device)
        get_term = getattr(manager, "get_term", None)
        if not callable(get_term):
            raise RuntimeError(
                "task-first termination manager cannot expose robot_hit_table outcomes"
            )
        for term_name in _TASK_FIRST_UNSAFE_TERMINATIONS:
            if term_name in active_terms:
                unsafe |= self._selected_bool(get_term(term_name), ids)
        unsafe &= terminated
        return unsafe, terminated | timed_out

    def _task_first_book_outcomes(
        self,
        action_slots: torch.Tensor,
        ended: torch.Tensor,
        passed_at_strike: torch.Tensor,
        unsafe: torch.Tensor,
        terminal_or_timeout: torch.Tensor,
    ) -> None:
        """Atomically add one disjoint raw-outcome transaction to the action window."""

        count = len(self._task_first_action_order)
        invalid = ended & ((action_slots < 0) | (action_slots >= count))
        if bool(torch.any(invalid)):
            raise RuntimeError("task-first ended attempt has an invalid prior action slot")
        unsafe = unsafe & ended
        successful = ended & passed_at_strike & ~unsafe & ~terminal_or_timeout
        if bool(torch.any(successful & unsafe)):
            raise RuntimeError("task-first success and unsafe outcome masks overlap")
        slots = action_slots.clamp(min=0)
        # Compute all three rows before mutating any of them.  A malformed slot therefore cannot
        # leave a partially committed evidence transaction.
        additions = (
            torch.bincount(slots[ended], minlength=count),
            torch.bincount(slots[successful], minlength=count),
            torch.bincount(slots[unsafe], minlength=count),
        )
        for row, values in enumerate(additions):
            self._task_first_window_counts[row].add_(values)

    def _task_first_start_current_attempts(self, ids: torch.Tensor) -> None:
        """Activate the already-selected motion/task after no old recovery remains."""

        if bool(
            torch.any(
                self._task_first_attempt_active[ids]
                | self._task_first_recovery_pending[ids]
            )
        ):
            raise RuntimeError(
                "task-first cannot start an action while another attempt/recovery owns the env"
            )
        motion = self._motion()
        count = len(self._task_first_action_order)
        new_slots = (
            motion.clip_id[ids]
            if motion._multiseg
            else torch.zeros(len(ids), dtype=torch.long, device=self.device)
        )
        if bool(torch.any((new_slots < 0) | (new_slots >= count))):
            raise RuntimeError("task-first new motion clip lies outside the action manifest")
        self._task_first_attempt_active[ids] = True
        self._task_first_attempt_action[ids] = new_slots
        self._task_first_attempt_success[ids] = False

    def _task_first_close_and_start_attempts(
        self,
        env_ids: torch.Tensor,
        *,
        true_reset: bool,
    ) -> None:
        """Move a wrap into recovery, or close reset outcomes and start the reset task.

        MotionCommand has already selected the next clip when this seam runs.  On a wrap the
        ending action is moved to a pending-recovery ledger and *nothing is booked yet*.  Its
        strike pass becomes success only when the new clip's post-wrap hold expires safely.  A
        true reset during that hold is therefore still charged to the old action, never the new
        clip that happens to be displayed during recovery.
        """

        ids = torch.as_tensor(env_ids, dtype=torch.long, device=self.device).reshape(-1)
        if len(ids) == 0:
            return
        active = self._task_first_attempt_active[ids]
        recovering = self._task_first_recovery_pending[ids]
        if bool(torch.any(active & recovering)):
            raise RuntimeError(
                "task-first attempt and pending recovery cannot own one env simultaneously"
            )

        if not true_reset:
            if bool(torch.any(recovering)):
                raise RuntimeError(
                    "task-first encountered a second wrap before prior recovery completed"
                )
            if bool(torch.any(~active)):
                raise RuntimeError("task-first wrap has no active prior attempt")
            slots = self._task_first_attempt_action[ids]
            count = len(self._task_first_action_order)
            if bool(torch.any((slots < 0) | (slots >= count))):
                raise RuntimeError("task-first active attempt has an invalid prior action slot")
            self._task_first_recovery_pending[ids] = True
            self._task_first_recovery_action[ids] = slots
            self._task_first_recovery_success[ids] = (
                self._task_first_attempt_success[ids]
            )
            self._task_first_attempt_active[ids] = False
            self._task_first_attempt_action[ids] = -1
            self._task_first_attempt_success[ids] = False
            return

        unsafe, terminal_or_timeout = self._task_first_reset_outcome_masks(ids)

        # A reset in the post-wrap hold closes the OLD action's recovery.  The newly selected
        # action has not started yet and contributes no attempt at all.
        pending_ended = recovering & ~self._task_first_restored_recovery_discard[ids]
        self._task_first_book_outcomes(
            self._task_first_recovery_action[ids],
            pending_ended,
            self._task_first_recovery_success[ids],
            unsafe,
            terminal_or_timeout,
        )
        self._task_first_recovery_pending[ids] = False
        self._task_first_recovery_action[ids] = -1
        self._task_first_recovery_success[ids] = False
        self._task_first_restored_recovery_discard[ids] = False

        active_ended = active & ~self._task_first_restored_attempt_discard[ids]
        self._task_first_book_outcomes(
            self._task_first_attempt_action[ids],
            active_ended,
            self._task_first_attempt_success[ids],
            unsafe,
            terminal_or_timeout,
        )
        self._task_first_attempt_active[ids] = False
        self._task_first_attempt_action[ids] = -1
        self._task_first_attempt_success[ids] = False
        self._task_first_restored_attempt_discard[ids] = False
        self._task_first_start_current_attempts(ids)

    def _task_first_finish_recovery_holds(self, in_hold: torch.Tensor) -> None:
        """Commit safely completed recoveries and activate their waiting tasks."""

        if tuple(in_hold.shape) != (self.num_envs,) or in_hold.dtype != torch.bool:
            raise RuntimeError("task-first motion.in_hold must be a per-environment bool tensor")
        finished = self._task_first_recovery_pending & ~in_hold
        ids = torch.where(finished)[0]
        if len(ids) == 0:
            return
        ended = finished[ids] & ~self._task_first_restored_recovery_discard[ids]
        clear = torch.zeros(len(ids), dtype=torch.bool, device=self.device)
        self._task_first_book_outcomes(
            self._task_first_recovery_action[ids],
            ended,
            self._task_first_recovery_success[ids],
            clear,
            clear,
        )
        self._task_first_recovery_pending[ids] = False
        self._task_first_recovery_action[ids] = -1
        self._task_first_recovery_success[ids] = False
        self._task_first_restored_recovery_discard[ids] = False
        self._task_first_start_current_attempts(ids)

    def _task_first_counts_payload(self) -> dict:
        values = self._task_first_window_counts.detach().cpu().tolist()
        return {
            action: {
                name: int(values[row][index])
                for row, name in enumerate(_TASK_FIRST_OUTCOME_NAMES)
            }
            for index, action in enumerate(self._task_first_action_order)
        }

    def _task_first_on_rollout_end(self, step: int) -> None:
        """Advance only when every action has one complete evidence window.

        Arbitrary-N libraries often need several PPO rollouts before the least frequent action
        reaches ``min_attempts``. Pending rollouts neither clear evidence nor advance stall/dwell.
        Once ready, all actions advance atomically and every raw window is cleared together.
        """

        if type(step) is not int or step < 0:
            raise ValueError("task-first rollout step must be a non-negative plain integer")
        if self._task_first_last_rollout_step is not None and step <= self._task_first_last_rollout_step:
            raise RuntimeError(
                "task-first rollout callback must run exactly once in increasing step order"
            )
        counts_payload = self._task_first_counts_payload()
        levels_before = {
            action: self._task_first_curriculum.levels(action)
            for action in self._task_first_action_order
        }
        minimum = int(self._task_first_manifest.gate.min_attempts)
        ready = all(
            counts_payload[action]["attempts"] >= minimum
            for action in self._task_first_action_order
        )
        decisions_payload = []
        status = "pending_evidence"
        if ready:
            evidence = {
                action: self._task_first_outcome_type(**counts_payload[action])
                for action in self._task_first_action_order
            }
            decisions = self._task_first_curriculum.advance(evidence)
            for result in decisions:
                decision = result.decision
                decisions_payload.append(
                    {
                        "action": result.action,
                        "axis": result.axis,
                        "kind": result.kind,
                        "from_level": result.from_level,
                        "to_level": result.to_level,
                        "gate": None
                        if decision is None
                        else {
                            "enough_attempts": decision.enough_attempts,
                            "success_lower": decision.success_lower,
                            "success_upper": decision.success_upper,
                            "unsafe_lower": decision.unsafe_lower,
                            "unsafe_upper": decision.unsafe_upper,
                            "enter_ok": decision.enter_ok,
                            "exit_bad": decision.exit_bad,
                            "enter_blockers": list(decision.enter_blockers),
                            "exit_reasons": list(decision.exit_reasons),
                        },
                    }
                )
            self._task_first_window_counts.zero_()
            status = "advanced"
        levels_after = {
            action: self._task_first_curriculum.levels(action)
            for action in self._task_first_action_order
        }
        receipt = {
            "event": "task_first_curriculum",
            "schema_version": 1,
            "step": step,
            "manifest_sha256": self._task_first_loaded_manifest.file_sha256,
            "action_order": list(self._task_first_action_order),
            "status": status,
            "min_attempts": minimum,
            "counts": counts_payload,
            "levels_before": levels_before,
            "decisions": decisions_payload,
            "levels_after": levels_after,
        }
        print(
            json.dumps(
                receipt,
                sort_keys=True,
                separators=(",", ":"),
                ensure_ascii=False,
                allow_nan=False,
            ),
            flush=True,
        )
        self._task_first_last_rollout_step = step

    def _task_first_exact_resume_state_dict(self) -> dict:
        counts = self._task_first_window_counts.detach().cpu().tolist()
        return {
            "schema_version": _TASK_FIRST_STATE_SCHEMA_VERSION,
            "kind": _TASK_FIRST_STATE_KIND,
            "manifest_sha256": self._task_first_loaded_manifest.file_sha256,
            "action_order": list(self._task_first_action_order),
            "action_uids": list(self._task_first_action_uids),
            "num_envs": int(self.num_envs),
            "curriculum": self._task_first_curriculum.state_dict(),
            "window_counts": {
                name: [int(value) for value in counts[row]]
                for row, name in enumerate(_TASK_FIRST_OUTCOME_NAMES)
            },
            "attempt_latches": {
                "active": [
                    bool(value)
                    for value in self._task_first_attempt_active.detach().cpu().tolist()
                ],
                "action_slot": [
                    int(value)
                    for value in self._task_first_attempt_action.detach().cpu().tolist()
                ],
                "success_at_exact_strike": [
                    bool(value)
                    for value in self._task_first_attempt_success.detach().cpu().tolist()
                ],
            },
            "pending_recovery": {
                "active": [
                    bool(value)
                    for value in self._task_first_recovery_pending.detach().cpu().tolist()
                ],
                "action_slot": [
                    int(value)
                    for value in self._task_first_recovery_action.detach().cpu().tolist()
                ],
                "success_at_exact_strike": [
                    bool(value)
                    for value in self._task_first_recovery_success.detach().cpu().tolist()
                ],
            },
            "last_rollout_step": self._task_first_last_rollout_step,
        }

    def _task_first_load_exact_resume_state_dict(self, state: dict, strict: bool = True) -> None:
        """Restore complete task-first state after validating identity, types and reachability."""

        if strict is not True:
            raise ValueError("task-first exact resume only supports strict=True")
        expected = {
            "schema_version",
            "kind",
            "manifest_sha256",
            "action_order",
            "action_uids",
            "num_envs",
            "curriculum",
            "window_counts",
            "attempt_latches",
            "pending_recovery",
            "last_rollout_step",
        }
        if not isinstance(state, dict) or set(state) != expected:
            raise ValueError(
                f"task-first exact-resume keys must be exactly {sorted(expected)}"
            )
        if type(state["schema_version"]) is not int or state["schema_version"] != _TASK_FIRST_STATE_SCHEMA_VERSION:
            raise ValueError("task-first exact-resume schema_version mismatch")
        if state["kind"] != _TASK_FIRST_STATE_KIND:
            raise ValueError("task-first exact-resume kind mismatch")
        if state["manifest_sha256"] != self._task_first_loaded_manifest.file_sha256:
            raise ValueError("task-first exact-resume manifest SHA-256 mismatch")
        if state["action_order"] != list(self._task_first_action_order):
            raise ValueError("task-first exact-resume action order mismatch")
        if state["action_uids"] != list(self._task_first_action_uids):
            raise ValueError("task-first exact-resume action UID mismatch")
        if type(state["num_envs"]) is not int or state["num_envs"] != self.num_envs:
            raise ValueError("task-first exact-resume environment count mismatch")

        count_state = state["window_counts"]
        if not isinstance(count_state, dict) or set(count_state) != set(_TASK_FIRST_OUTCOME_NAMES):
            raise ValueError("task-first window_counts has invalid keys")
        n_actions = len(self._task_first_action_order)
        count_rows = []
        for name in _TASK_FIRST_OUTCOME_NAMES:
            row = count_state[name]
            if not isinstance(row, list) or len(row) != n_actions:
                raise ValueError(f"task-first window_counts.{name} has invalid shape")
            if any(type(value) is not int or value < 0 for value in row):
                raise ValueError(f"task-first window_counts.{name} must contain non-negative ints")
            count_rows.append(list(row))
        for index in range(n_actions):
            attempts, successes, unsafe = (row[index] for row in count_rows)
            if successes + unsafe > attempts:
                raise ValueError(
                    "task-first window success and unsafe counts must be disjoint attempt subsets"
                )

        latch_state = state["attempt_latches"]
        latch_keys = {"active", "action_slot", "success_at_exact_strike"}
        if not isinstance(latch_state, dict) or set(latch_state) != latch_keys:
            raise ValueError("task-first attempt_latches has invalid keys")
        active = latch_state["active"]
        slots = latch_state["action_slot"]
        success = latch_state["success_at_exact_strike"]
        if not all(isinstance(row, list) and len(row) == self.num_envs for row in (active, slots, success)):
            raise ValueError("task-first attempt latch vectors must match num_envs")
        if any(type(value) is not bool for value in active + success):
            raise ValueError("task-first active/success latches must contain bools")
        if any(type(value) is not int for value in slots):
            raise ValueError("task-first action-slot latches must contain plain ints")
        for index, (is_active, slot, did_succeed) in enumerate(zip(active, slots, success)):
            if is_active:
                if slot < 0 or slot >= n_actions:
                    raise ValueError(f"task-first active attempt {index} has invalid action slot")
            elif slot != -1 or did_succeed:
                raise ValueError(
                    f"task-first inactive attempt {index} must have slot=-1 and success=False"
                )

        recovery_state = state["pending_recovery"]
        if not isinstance(recovery_state, dict) or set(recovery_state) != latch_keys:
            raise ValueError("task-first pending_recovery has invalid keys")
        recovery_active = recovery_state["active"]
        recovery_slots = recovery_state["action_slot"]
        recovery_success = recovery_state["success_at_exact_strike"]
        if not all(
            isinstance(row, list) and len(row) == self.num_envs
            for row in (recovery_active, recovery_slots, recovery_success)
        ):
            raise ValueError("task-first pending-recovery vectors must match num_envs")
        if any(
            type(value) is not bool
            for value in recovery_active + recovery_success
        ):
            raise ValueError("task-first pending-recovery active/success must contain bools")
        if any(type(value) is not int for value in recovery_slots):
            raise ValueError("task-first pending-recovery action slots must contain plain ints")
        for index, (is_active, slot, did_succeed) in enumerate(
            zip(recovery_active, recovery_slots, recovery_success)
        ):
            if is_active:
                if active[index]:
                    raise ValueError(
                        f"task-first env {index} cannot own an attempt and recovery together"
                    )
                if slot < 0 or slot >= n_actions:
                    raise ValueError(
                        f"task-first pending recovery {index} has invalid action slot"
                    )
            elif slot != -1 or did_succeed:
                raise ValueError(
                    f"task-first inactive recovery {index} must have slot=-1 and success=False"
                )
        last_step = state["last_rollout_step"]
        if last_step is not None and (type(last_step) is not int or last_step < 0):
            raise ValueError("task-first last_rollout_step must be null or a non-negative int")
        if not isinstance(state["curriculum"], dict):
            raise ValueError("task-first curriculum state must be a dict")

        # Curriculum validates atomically. It is deliberately loaded only after every other field
        # passed, so a malformed latch cannot partially mutate the state machine.
        self._task_first_curriculum.load_state_dict(state["curriculum"])
        self._task_first_window_counts.copy_(
            torch.tensor(count_rows, dtype=torch.long, device=self.device)
        )
        self._task_first_attempt_active.copy_(
            torch.tensor(active, dtype=torch.bool, device=self.device)
        )
        self._task_first_attempt_action.copy_(
            torch.tensor(slots, dtype=torch.long, device=self.device)
        )
        self._task_first_attempt_success.copy_(
            torch.tensor(success, dtype=torch.bool, device=self.device)
        )
        self._task_first_recovery_pending.copy_(
            torch.tensor(recovery_active, dtype=torch.bool, device=self.device)
        )
        self._task_first_recovery_action.copy_(
            torch.tensor(recovery_slots, dtype=torch.long, device=self.device)
        )
        self._task_first_recovery_success.copy_(
            torch.tensor(recovery_success, dtype=torch.bool, device=self.device)
        )
        self._task_first_restored_attempt_discard.copy_(
            self._task_first_attempt_active
        )
        self._task_first_restored_recovery_discard.copy_(
            self._task_first_recovery_pending
        )
        self._task_first_last_rollout_step = last_step

    def _count_swing_starts(self, env_ids, count_prestrike_falls: bool) -> None:
        """UNCONDITIONAL swing accounting (Phase A wandb fix). Increment-only here; the decay is
        applied once per step in _update_metrics next to the exact accumulators, so
        swing_completion_rate = exact_n_acc / swing_starts_acc shares one EMA timescale.
        NOTE: an episode TIMEOUT mid-swing counts as an uncompleted start (slight deflation,
        ~one boundary swing per 10 s episode) but never as a fall (terminated excludes timeouts)."""
        n = int(len(env_ids))
        if n == 0:
            return
        env_ids_t = torch.as_tensor(env_ids, dtype=torch.long, device=self.device)
        if self._task_first_enabled:
            self._task_first_close_and_start_attempts(
                env_ids_t,
                true_reset=bool(count_prestrike_falls),
            )
        exact_ledger = self._ensure_exact_behavior_decision_counters()
        exact_ledger["swing_start_count"].add_(n)
        self._swing_starts_acc += float(n)
        motion = self._motion()
        bucket_accounting = self._metric_bucket_accounting_enabled(motion)
        bucket_order = tuple(self._clip_names) if bucket_accounting else ()
        metric_dtype = self._swing_start_base_xy.dtype
        metric_tensors = []
        metric_targets: list[tuple[str, int | None]] = []
        if bucket_accounting:
            # per-族累计(spdmix v2 硬绑定四):桶是正/反手两族。legacy 2-clip 族行号==clip_id
            # 逐字节不变;6-clip 下正手 1.0/1.2 变体不再被记进"backhand"桶(clip==1 的老病);
            # 显式命名的 N=1 则把唯一的 clip 0 记进该动作自己的桶。
            fams = self._metric_bucket_rows()[motion.clip_id[env_ids_t]]
            for c in bucket_order:
                metric_tensors.append(
                    (fams == c).sum(dtype=metric_dtype)
                )
                metric_targets.append(("_swing_starts_acc_c", c))
        # --- per-swing SAME-LEDGER rally booking (metric-sync fix; see the rally block in __init__) --
        # The attempt that ENDS at this resample books its start and its returned-latch TOGETHER
        # (same call, same ledger, decayed together in _update_metrics) — returns can never outrun
        # starts. An env's very first resample books nothing (_rally_active False: no attempt
        # existed yet). The ended attempt is attributed to _prev_clip_id, the clip it was actually
        # swinging (motion has already resampled clip_id for the NEW attempt by this point).
        ended = self._rally_active[env_ids_t]
        returned = self._rally_returned[env_ids_t] & ended
        metric_tensors.extend(
            (
                ended.sum(dtype=metric_dtype),
                returned.sum(dtype=metric_dtype),
            )
        )
        metric_targets.extend(
            (
                ("_rally_starts_acc", None),
                ("_rally_returns_acc", None),
            )
        )
        if bucket_accounting:
            ended_fams = self._metric_bucket_rows()[self._prev_clip_id[env_ids_t]]
            for c in bucket_order:
                _csel = ended_fams == c
                metric_tensors.extend(
                    (
                        (ended & _csel).sum(dtype=metric_dtype),
                        (returned & _csel).sum(dtype=metric_dtype),
                    )
                )
                metric_targets.extend(
                    (
                        ("_rally_starts_acc_c", c),
                        ("_rally_returns_acc_c", c),
                    )
                )

        # Rally drift close-out: a WRAP means the previous swing ran to completion — book its base
        # displacement (norm + forward component) from the swing-start stamp to the current base.
        # True resets never close out (the swing was aborted/fallen; the teleport is not drift).
        # Keep this branchless on device: inserting exact zeros for unstamped rows preserves the
        # same three reductions while removing the telemetry-only ``bool(any())`` host barrier.
        if not count_prestrike_falls:  # wrap path (see _resample_is_wrap)
            _stamped = ~self._swing_start_pending[env_ids_t]
            _d = self.base_pos_w[env_ids_t, :2] - self._swing_start_base_xy[env_ids_t]
            _drift = torch.where(
                _stamped,
                torch.norm(_d, dim=-1),
                torch.zeros_like(_d[:, 0]),
            )
            _drift_fwd = torch.where(
                _stamped,
                _d[:, 0],
                torch.zeros_like(_d[:, 0]),
            )
            metric_tensors.extend(
                (
                    _drift.sum(),
                    _drift_fwd.sum(),
                    _stamped.sum(dtype=metric_dtype),
                )
            )
            metric_targets.extend(
                (
                    ("_drift_sum_acc", None),
                    ("_drift_fwd_sum_acc", None),
                    ("_drift_n_acc", None),
                )
            )

        true_pre = None
        post = None
        recovering = None
        if count_prestrike_falls:
            term = self._env.termination_manager.terminated[env_ids_t]
            pre = self.pre_strike[env_ids_t]
            # POST-strike fall = terminated at/after the strike frame (tts <= 0, follow-through) OR
            # during the post-wrap hold (_recover_from_clip latch >= 0: the previous swing's recovery,
            # even though the wrap already flipped pre_strike=True for the NEXT swing). Both are the
            # "hit, then fall while recovering" failure that completion + pre-strike metrics miss.
            rec = self._recover_from_clip[env_ids_t]
            recovering = rec >= 0
            true_pre = term & pre & ~recovering
            post = term & (~pre | recovering)
            metric_tensors.extend(
                (
                    true_pre.sum(dtype=metric_dtype),
                    post.sum(dtype=metric_dtype),
                )
            )
            metric_targets.extend(
                (
                    ("_prestrike_fall_acc", None),
                    ("_poststrike_fall_acc", None),
                )
            )
            if bucket_accounting:
                # Attribute the fall to the clip the env was ON when it fell: pre-strike falls to the
                # _prev_clip_id snapshot (motion already resampled clip_id for the new episode);
                # post-wrap-hold falls to the latched clip whose swing caused the recovery.
                fall_clips = torch.where(
                    recovering, rec, self._prev_clip_id[env_ids_t]
                )
                fall_fams = self._metric_bucket_rows()[fall_clips]
                for c in bucket_order:
                    csel = fall_fams == c
                    metric_tensors.extend(
                        (
                            (true_pre & csel).sum(dtype=metric_dtype),
                            (post & csel).sum(dtype=metric_dtype),
                        )
                    )
                    metric_targets.extend(
                        (
                            ("_prestrike_fall_acc_c", c),
                            ("_poststrike_fall_acc_c", c),
                        )
                    )

        diagnostic_device_telemetry = (
            self._action_ball_diagnostic_device_telemetry_enabled()
        )
        if diagnostic_device_telemetry:
            if len(metric_targets) != len(metric_tensors):
                raise RuntimeError(
                    "diagnostic swing telemetry target width drifted"
                )
            for target, value in zip(metric_targets, metric_tensors):
                self._action_ball_diagnostic_device_telemetry_add(
                    "swing",
                    target,
                    value,
                )
            metric_values = None
        else:
            # Formal/default preserves the historical immediate reporting boundary.
            metric_values = iter(_batched_host_scalar_values(metric_tensors))
            if bucket_accounting:
                for c in bucket_order:
                    self._swing_starts_acc_c[c] += next(metric_values)
            self._rally_starts_acc += next(metric_values)
            self._rally_returns_acc += next(metric_values)
            if bucket_accounting:
                for c in bucket_order:
                    self._rally_starts_acc_c[c] += next(metric_values)
                    self._rally_returns_acc_c[c] += next(metric_values)

        self._rally_active[env_ids_t] = True
        # The NEW attempt starts with the parked wrap-boundary latch, not blank: a strike that
        # fired on this very wrap step belongs to the attempt beginning here (see the guard in
        # _vb_book_strike_step). One-shot — consumed on transfer.
        self._rally_returned[env_ids_t] = self._rally_pending_return[env_ids_t]
        self._rally_pending_return[env_ids_t] = False
        self._close_exact_swing_attempts(env_ids_t)

        if (
            not count_prestrike_falls
            and not diagnostic_device_telemetry
        ):  # wrap path (see _resample_is_wrap)
            assert metric_values is not None
            self._drift_sum_acc += next(metric_values)
            self._drift_fwd_sum_acc += next(metric_values)
            self._drift_n_acc += next(metric_values)
        # Stamp the NEW swing's start lazily (first _update_metrics after this resample): at reset
        # time base_pos_w still caches the PRE-teleport pose.
        self._swing_start_pending[env_ids_t] = True
        if count_prestrike_falls:
            self._book_exact_behavior_terminal_reset(
                env_ids_t, pre_strike=pre, recovering=recovering
            )
            if not diagnostic_device_telemetry:
                assert metric_values is not None
                self._prestrike_fall_acc += next(metric_values)
                self._poststrike_fall_acc += next(metric_values)
                if bucket_accounting:
                    for c in bucket_order:
                        self._prestrike_fall_acc_c[c] += next(metric_values)
                        self._poststrike_fall_acc_c[c] += next(metric_values)
            # True reset: the new episode starts fresh (its stand-start/reset hold is genuine
            # pre-strike preparation, not recovery), so clear the latch for these envs.
            self._recover_from_clip[env_ids_t] = -1

    def _close_exact_swing_attempts(self, env_ids: torch.Tensor) -> None:
        """Close old attempts and start new ones with paired decision-window accounting.

        ``swing_start_count`` remains a useful mechanism/throughput counter, while pruning uses
        ``swing_completion_count / swing_outcome_count``.  The paired counters are written in the
        same call, so a PPO-window boundary cannot create the old false ``strike > start``
        invariant failure.
        """

        ids = torch.as_tensor(env_ids, dtype=torch.long, device=self.device).reshape(-1)
        if len(ids) == 0:
            return
        ledger = self._ensure_exact_behavior_decision_counters()
        ended = self._exact_attempt_active[ids]
        completed = ended & self._exact_attempt_completed[ids]
        ledger["swing_outcome_count"].add_(ended.sum(dtype=torch.long))
        ledger["swing_completion_count"].add_(completed.sum(dtype=torch.long))
        if getattr(self, "planner_revision_enabled", False):
            self._ensure_exact_timing_bucket_state()
            timing_bucket = self._exact_attempt_initial_tts_bucket[ids]
            for bucket_id, bucket_name in enumerate(_PLANNER_INITIAL_TTS_BUCKETS):
                in_bucket = timing_bucket == bucket_id
                ledger[f"planner_initial_tts_{bucket_name}_swing_outcome_count"].add_(
                    (ended & in_bucket).sum(dtype=torch.long)
                )
                ledger[f"planner_initial_tts_{bucket_name}_swing_completion_count"].add_(
                    (completed & in_bucket).sum(dtype=torch.long)
                )
            # The new attempt exists after this call but receives its bucket later in the same
            # resample, when _begin_same_ball_planner_task samples its initial deadline.
            self._exact_attempt_initial_tts_bucket[ids] = -1
        self._exact_attempt_active[ids] = True
        self._exact_attempt_completed[ids] = self._exact_pending_completion[ids]
        self._exact_pending_completion[ids] = False

    def _latch_exact_swing_completion(self, exact_strike: torch.Tensor) -> None:
        """Latch an exact strike onto the attempt that owns the current motion frame."""

        exact = exact_strike.detach().bool()
        wrapped = getattr(self._motion(), "just_resampled", None)
        if wrapped is None:
            self._exact_attempt_completed |= exact
            return
        wrapped = wrapped.detach().bool()
        self._exact_attempt_completed |= exact & ~wrapped
        self._exact_pending_completion |= exact & wrapped

    def _update_footwork_signals(self, racket_dist: torch.Tensor) -> None:
        """Base-FREE footwork-to-strike signals (reward/metric only; NEVER observed). The legs are driven
        to move by racket PROGRESS (reducing the racket->target distance), not by any base target. All
        guards degrade to 0 if a body/sensor cannot resolve, so this can never crash training."""
        data = self.robot.data
        # --- racket-target distance + dense progress (the base-free movement driver) ---
        self.racket_target_distance = racket_dist
        # progress = previous - current distance. Resample/reset steps are not learnable progress:
        # the target and/or reference clip jumped, so reset the baseline and emit exactly zero.
        motion = self._motion()
        reset_progress = self._progress_reset_mask.clone()
        if hasattr(motion, "just_resampled"):
            reset_progress |= motion.just_resampled
        previous_potential = self._prev_racket_dist.clamp(
            min=0.0, max=_RACKET_PROGRESS_POTENTIAL_CAP_M
        )
        current_potential = racket_dist.clamp(
            min=0.0, max=_RACKET_PROGRESS_POTENTIAL_CAP_M
        )
        progress = previous_potential - current_potential
        self.racket_progress = torch.where(reset_progress, torch.zeros_like(progress), progress)
        self._prev_racket_dist = racket_dist.detach()
        self._progress_reset_mask.zero_()
        self.metrics["racket_target_distance"] = racket_dist
        self.metrics["racket_progress"] = self.racket_progress
        self.metrics["racket_progress_prestrike"] = torch.where(
            self.pre_strike, self.racket_progress, torch.zeros_like(self.racket_progress)
        )
        # --- base stability components (training-only) ---
        pg = getattr(data, "projected_gravity_b", None)
        if pg is not None:
            self.proj_grav_xy = torch.norm(pg[:, :2], dim=-1)
        self.base_ang_vel_xy_norm = torch.norm(data.root_ang_vel_b[:, :2], dim=-1)
        self.vertical_speed = torch.abs(data.root_lin_vel_b[:, 2])
        self.metrics["proj_grav_xy"] = self.proj_grav_xy
        self.metrics["base_ang_vel_xy"] = self.base_ang_vel_xy_norm
        self.metrics["base_vertical_speed"] = self.vertical_speed
        # P2.4 (PACE smooth deceleration): mean planar base speed during the approach — the quantity
        # the base_decel_tracking reward shapes toward v_des = clamp(v_gain*dist_xy, 0, v_max).
        # Watch it fall on far targets when the term is enabled (task.rewards.base_decel_weight>0).
        base_speed_xy = torch.norm(data.root_lin_vel_w[:, :2], dim=-1)
        self.metrics["base_speed_xy_prestrike"] = torch.where(
            self.pre_strike, base_speed_xy, torch.zeros_like(base_speed_xy)
        )
        # Rally: planar base speed through the FOLLOW-THROUGH (strike-window exit -> wrap) — the
        # braking window the post_strike_brake reward shapes. Held-write (carries the last
        # in-window value between swings) so the tail-mean reads the typical post-strike speed.
        _brake_win = (~self.pre_strike) & (~self.strike_window)
        self.metrics["post_strike_base_speed_xy"] = torch.where(
            _brake_win, base_speed_xy, self.metrics["post_strike_base_speed_xy"]
        )
        # Rally: cumulative displacement from the env origin (the P7 forward-drift accumulator).
        self.metrics["base_dist_from_origin"] = torch.norm(
            self.base_pos_w[:, :2] - self._env.scene.env_origins[:, :2], dim=-1
        )
        self._update_hold_recovery_metrics(getattr(self._motion(), "in_hold", None))
        # Rally: lazy swing-start stamp (fresh base_pos_w — see __init__ rationale).
        _pend = self._swing_start_pending.unsqueeze(-1)
        self._swing_start_base_xy.copy_(
            torch.where(
                _pend,
                self.base_pos_w[:, :2],
                self._swing_start_base_xy,
            )
        )
        self._swing_start_pending.zero_()
        # --- foot footwork signals (slip² / velocity / drag); feet may STEP, so this is PENALTY-only ---
        if self._foot_idx_robot and self._contact_sensor is not None and self._foot_idx_contact:
            f_force = torch.norm(self._contact_sensor.data.net_forces_w[:, self._foot_idx_contact, :], dim=-1)
            in_contact = (f_force > 10.0).float()  # (E,2)
            f_vel = data.body_lin_vel_w[:, self._foot_idx_robot, :]  # (E,2,3)
            f_xy_speed = torch.norm(f_vel[..., :2], dim=-1)  # (E,2)
            f_speed = torch.norm(f_vel, dim=-1)  # (E,2)
            f_height = data.body_pos_w[:, self._foot_idx_robot, 2]  # (E,2)
            self.foot_slip_sq = (in_contact * f_xy_speed.square()).sum(dim=-1)  # contact * ||v_xy||²
            self.foot_vel_sq = f_speed.square().sum(dim=-1)  # excessive/violent foot motion
            # Phase A fix: the old height gate (f_height < 0.10 m) sat BELOW the planted ankle
            # origin (~0.07 m), so EVERY low step counted as "dragging" — stepping itself was
            # taxed, one of the reasons the policy never learned to move left/right. "Drag" now
            # means lateral speed while the foot is LOADED (in contact) = sliding under load;
            # airborne swing-leg motion is free (foot_vel_sq still bounds violent motion).
            self.foot_drag = (in_contact * f_xy_speed).sum(dim=-1)
            self.metrics["foot_slip_sq"] = self.foot_slip_sq
            self.metrics["foot_vel_mean"] = f_speed.mean(dim=-1)
            self.metrics["foot_lift_rate"] = (1.0 - in_contact).mean(dim=-1)  # 0 = both planted, 1 = airborne
            self.metrics["foot_vel_at_strike"] = torch.where(
                self.strike_window, f_speed.mean(dim=-1), torch.zeros(self.num_envs, device=self.device)
            )
        # --- anti-arm-only: ARM joints near a limit + arm joint velocity (resolve arm joint idx once) ---
        if not getattr(self, "_arm_resolved", False):
            self._arm_resolved = True
            self._arm_joint_idx, self._leg_joint_idx, self._waist_twist_idx = [], [], []
            try:
                self._arm_joint_idx = list(self.robot.find_joints([".*shoulder.*", ".*elbow.*", ".*wrist.*"])[0])
            except Exception:
                pass
            try:
                self._leg_joint_idx = list(self.robot.find_joints([".*hip.*", ".*knee.*", ".*ankle.*"])[0])
            except Exception:
                pass
            # waist YAW+ROLL: the "twist/lean instead of step" DOFs the policy uses to face a lateral
            # target without moving its feet. Penalized (pre-strike) so reaching a far target needs footwork.
            # waist_pitch is EXCLUDED (it is the swing wind-up / natural lean, not a lateral-reach cheat).
            try:
                self._waist_twist_idx = list(self.robot.find_joints(["waist_yaw_joint", "waist_roll_joint"])[0])
            except Exception:
                pass
        limits = getattr(data, "soft_joint_pos_limits", None)
        if limits is None:
            limits = getattr(data, "joint_pos_limits", None)
        if self._arm_joint_idx and limits is not None:
            ai = self._arm_joint_idx
            half = ((limits[:, ai, 1] - limits[:, ai, 0]) * 0.5).clamp(min=1e-6)
            d = torch.minimum(
                data.joint_pos[:, ai] - limits[:, ai, 0], limits[:, ai, 1] - data.joint_pos[:, ai]
            ).clamp(min=0.0)
            self.arm_overreach_frac = ((d / half) < 0.1).float().mean(dim=-1)  # within 10% of a limit
            self.metrics["arm_overreach_frac"] = self.arm_overreach_frac
            self.metrics["arm_joint_vel_max"] = torch.max(torch.abs(data.joint_vel[:, ai]), dim=-1).values
        # --- diagnostic: do the LEGS actually move before the strike? (footwork is happening) ---
        if self._leg_joint_idx:
            leg_vel = torch.max(torch.abs(data.joint_vel[:, self._leg_joint_idx]), dim=-1).values
            self.metrics["leg_joint_vel_max"] = leg_vel
            self.metrics["leg_moving_prestrike"] = torch.where(
                self.pre_strike, (leg_vel > 0.2).float(), torch.zeros(self.num_envs, device=self.device)
            )
        # --- anti twist-instead-of-step: |waist_yaw|+|waist_roll| deviation from the default (neutral,
        #     facing-forward) pose. This is the magnitude the prestrike_waist_twist reward penalizes, so
        #     reaching a lateral target by turning the torso (feet planted) becomes costly -> step instead. ---
        if self._waist_twist_idx:
            wi = self._waist_twist_idx
            self.waist_twist = torch.abs(data.joint_pos[:, wi] - data.default_joint_pos[:, wi]).sum(dim=-1)
            self.metrics["waist_twist_abs"] = self.waist_twist
            self.metrics["waist_twist_prestrike"] = torch.where(
                self.pre_strike, self.waist_twist, torch.zeros(self.num_envs, device=self.device)
            )

    def _update_hold_recovery_metrics(self, in_hold) -> None:
        """Book heading recovery on true hold start/expiry edges.

        A resample can replace a held state with another held state without a boolean transition;
        ``_hold_edge_pending`` turns that into a fresh start while suppressing a false expiry. A
        pending zero-length hold records neither edge. This helper is isolated for CPU boundary
        tests because these ledger semantics are easy to regress inside the larger metrics pass.
        """
        full_mdp_device_metrics = (
            self._action_ball_full_mdp_device_command_metrics_enabled()
        )
        if in_hold is None:
            if full_mdp_device_metrics:
                zero = self._hold_start_yaw.sum() * 0.0
                self._add_action_ball_full_mdp_hold_metric_device_values(
                    (zero, zero, zero, zero, zero)
                )
            return
        in_hold = in_hold.bool()
        pending = self._hold_edge_pending
        expired = self._previous_in_hold & ~in_hold & ~pending
        started = ((~self._previous_in_hold) | pending) & in_hold
        # Compute one yaw row per env, then mask on device.  This replaces the old
        # ``expired.any``/``conditioned.any``/``started.any`` host-controlled branches with one
        # scalar packet while retaining the same edge masks and Python accumulator order.
        quat = self.base_quat_w
        forward_x = 1.0 - 2.0 * (quat[:, 2] ** 2 + quat[:, 3] ** 2)
        forward_y = 2.0 * (
            quat[:, 1] * quat[:, 2] + quat[:, 0] * quat[:, 3]
        )
        yaw_abs = torch.atan2(forward_y, forward_x).abs()
        zero = torch.zeros_like(yaw_abs)
        expiry_yaw = torch.where(expired, yaw_abs, zero)
        conditioned = expired & (
            self._hold_start_yaw > _RECOVERY_START_YAW_THRESHOLD
        )
        spawn_yaw = torch.where(conditioned, self._hold_start_yaw, zero)
        conditioned_expiry_yaw = torch.where(conditioned, yaw_abs, zero)
        metric_scalars = (
            expiry_yaw.sum(),
            expired.sum(dtype=yaw_abs.dtype),
            spawn_yaw.sum(),
            conditioned_expiry_yaw.sum(),
            conditioned.sum(dtype=yaw_abs.dtype),
        )
        if full_mdp_device_metrics:
            self._add_action_ball_full_mdp_hold_metric_device_values(
                metric_scalars
            )
        elif self._action_ball_diagnostic_device_telemetry_enabled():
            targets = (
                ("_heading_expiry_sum_acc", None),
                ("_heading_expiry_n_acc", None),
                ("_recovery_spawn_sum_acc", None),
                ("_recovery_expiry_sum_acc", None),
                ("_recovery_n_acc", None),
            )
            for target, value in zip(targets, metric_scalars):
                self._action_ball_diagnostic_device_telemetry_add(
                    "swing",
                    target,
                    value,
                )
        else:
            self._apply_hold_recovery_host_values(
                _batched_host_scalar_values(metric_scalars)
            )
        self._hold_start_yaw.copy_(
            torch.where(started, yaw_abs, self._hold_start_yaw)
        )

        self._previous_in_hold = in_hold.clone()
        self._hold_edge_pending.zero_()

    def _apply_hold_recovery_host_values(
        self,
        values: Sequence[float],
    ) -> None:
        """Apply the historic five Python-float telemetry increments in exact order."""

        host_values = tuple(values)
        if len(host_values) != 5:
            raise RuntimeError(
                "hold/recovery metric host packet changed width"
            )
        (
            heading_expiry_sum,
            heading_expiry_n,
            recovery_spawn_sum,
            recovery_expiry_sum,
            recovery_n,
        ) = host_values
        self._heading_expiry_sum_acc += heading_expiry_sum
        self._heading_expiry_n_acc += heading_expiry_n
        self._recovery_spawn_sum_acc += recovery_spawn_sum
        self._recovery_expiry_sum_acc += recovery_expiry_sum
        self._recovery_n_acc += recovery_n

    @staticmethod
    def _action_ball_full_mdp_exact_global_metric_attributes() -> tuple[str, ...]:
        return (
            "_exact_n_acc",
            "_exact_pass_comp_acc",
            "_exact_pass_pos_acc",
            "_exact_pass_vel_acc",
            "_exact_pass_5cm_acc",
            "_exact_pass_10cm_acc",
            "_exact_pass_normal_acc",
            "_exact_pos_err_sum",
            "_exact_vel_err_sum",
            "_exact_nrm_err_sum",
        )

    @staticmethod
    def _action_ball_full_mdp_exact_bucket_metric_attributes() -> tuple[str, ...]:
        return (
            "_exact_n_acc_c",
            "_exact_pass_pos_acc_c",
            "_exact_pass_vel_acc_c",
            "_exact_pass_normal_acc_c",
            "_exact_pass_comp_acc_c",
            "_exact_pos_err_sum_c",
            "_exact_vel_err_sum_c",
            "_exact_nrm_err_sum_c",
        )

    @staticmethod
    def _action_ball_full_mdp_hold_metric_attributes() -> tuple[str, ...]:
        return (
            "_heading_expiry_sum_acc",
            "_heading_expiry_n_acc",
            "_recovery_spawn_sum_acc",
            "_recovery_expiry_sum_acc",
            "_recovery_n_acc",
        )

    def _action_ball_full_mdp_device_command_metrics_enabled(self) -> bool:
        """Whether exact/hold telemetry has no control-step host consumer."""

        cfg = getattr(self, "cfg", None)
        return (
            getattr(self, "_action_ball_full_mdp_enabled", None) is True
            and str(getattr(cfg, "target_mode", ""))
            == "action_ball_full_mdp"
            and getattr(self, "_action_ball_enabled", None) is False
            and getattr(self, "_task_first_enabled", None) is False
            and getattr(cfg, "action_ball_diagnostic_unauthorized", None)
            is True
            and getattr(self, "_action_ball_full_mdp_device_r05_owner", None)
            is not None
            and getattr(self, "_action_ball_full_mdp_racket_epoch_owner", None)
            is not None
            and getattr(cfg, "adaptive_sigma", None) is False
            and getattr(cfg, "adaptive_sigma_monotonic", None) is False
            and getattr(cfg, "adaptive_sigma_normal", None) is False
            and getattr(cfg, "virtual_ball", None) is False
            and getattr(cfg, "vb_metrics_only", None) is False
            and getattr(cfg, "shadow_ball", None) is False
            and getattr(cfg, "physical_ball", None) is False
            and getattr(self, "_shadow", None) is None
            and getattr(self, "_physical", None) is None
        )

    def _action_ball_full_mdp_command_metric_order(
        self,
        bucket_order: Sequence[int],
    ) -> tuple[tuple[str, int | None], ...]:
        order = [
            (attribute, None)
            for attribute in self._action_ball_full_mdp_exact_global_metric_attributes()
        ]
        for bucket in tuple(int(value) for value in bucket_order):
            order.extend(
                (attribute, bucket)
                for attribute in self._action_ball_full_mdp_exact_bucket_metric_attributes()
            )
        order.extend(
            (attribute, None)
            for attribute in self._action_ball_full_mdp_hold_metric_attributes()
        )
        return tuple(order)

    def _ensure_action_ball_full_mdp_command_metric_device_state(
        self,
        *,
        bucket_order: Sequence[int],
        like: torch.Tensor,
    ) -> torch.Tensor:
        """Return one contiguous float64 state for both deferred packets."""

        if not torch.is_tensor(like) or like.numel() != 1:
            raise RuntimeError("full-MDP command metric state requires one scalar tensor")
        buckets = tuple(int(value) for value in bucket_order)
        if len(buckets) != len(set(buckets)) or any(
            bucket not in self._clip_names for bucket in buckets
        ):
            raise RuntimeError("full-MDP command metric bucket order differs")
        order = self._action_ball_full_mdp_command_metric_order(buckets)
        state = getattr(
            self,
            "_action_ball_full_mdp_command_metric_device_state",
            None,
        )
        retained_order = getattr(
            self,
            "_action_ball_full_mdp_command_metric_order_retained",
            None,
        )
        if state is None:
            initial = []
            for attribute, bucket in order:
                value = getattr(self, attribute)
                if bucket is not None:
                    value = value[bucket]
                value = float(value)
                if not math.isfinite(value):
                    raise RuntimeError(
                        "full-MDP command metric initial state is non-finite"
                    )
                initial.append(value)
            state = torch.tensor(
                initial,
                dtype=torch.float64,
                device=like.device,
            )
            self._action_ball_full_mdp_command_metric_device_state = state
            self._action_ball_full_mdp_command_metric_order_retained = order
            self._action_ball_full_mdp_command_metric_exact_step_count = 0
            self._action_ball_full_mdp_command_metric_bucket_step_count = 0
            self._action_ball_full_mdp_command_metric_hold_decay_step_count = 0
            self._action_ball_full_mdp_command_metric_hold_add_step_count = 0
        elif (
            retained_order != order
            or not torch.is_tensor(state)
            or state.dtype != torch.float64
            or state.device != like.device
            or tuple(state.shape) != (len(order),)
            or not state.is_contiguous()
        ):
            raise RuntimeError(
                "full-MDP command metric device state identity/shape changed"
            )
        return state

    def _begin_action_ball_full_mdp_exact_metric_device_step(
        self,
        values: Sequence[torch.Tensor],
        *,
        decay: float,
        bucket_order: Sequence[int],
    ) -> torch.Tensor:
        """Apply the global EMA now and retain the bucket row for its old seam."""

        if not math.isfinite(float(decay)) or not 0.0 <= float(decay) <= 1.0:
            raise RuntimeError("full-MDP command metric decay differs")
        scalars = tuple(values)
        buckets = tuple(int(value) for value in bucket_order)
        width = 10 + 8 * len(buckets)
        if len(scalars) != width or not scalars:
            raise RuntimeError("full-MDP exact command metric width differs")
        first = scalars[0]
        for value in scalars:
            if (
                not torch.is_tensor(value)
                or value.numel() != 1
                or value.dtype != first.dtype
                or value.device != first.device
            ):
                raise RuntimeError(
                    "full-MDP exact command metrics require common device scalars"
                )
        state = self._ensure_action_ball_full_mdp_command_metric_device_state(
            bucket_order=buckets,
            like=first,
        )
        row = torch.stack(scalars).detach().to(dtype=torch.float64)
        state[:10].mul_(float(decay)).add_(row[:10])
        self._action_ball_full_mdp_command_metric_exact_step_count += 1
        return row

    def _finish_action_ball_full_mdp_exact_metric_device_step(
        self,
        row: torch.Tensor,
        *,
        decay: float,
        bucket_order: Sequence[int],
    ) -> torch.Tensor:
        """Apply per-bucket EMAs only after the historic completion report."""

        buckets = tuple(int(value) for value in bucket_order)
        width = 10 + 8 * len(buckets)
        state = self._ensure_action_ball_full_mdp_command_metric_device_state(
            bucket_order=buckets,
            like=row[0],
        )
        if (
            not torch.is_tensor(row)
            or row.dtype != torch.float64
            or row.device != state.device
            or tuple(row.shape) != (width,)
        ):
            raise RuntimeError("full-MDP exact command metric row changed")
        if width > 10:
            state[10:width].mul_(float(decay)).add_(row[10:width])
        self._action_ball_full_mdp_command_metric_bucket_step_count += 1
        return state

    def _decay_action_ball_full_mdp_hold_metric_device_state(
        self,
        decay: float,
    ) -> torch.Tensor:
        buckets = tuple(self._clip_names)
        probe = self.metrics["strike_composite_success_exact"].reshape(-1)[0]
        state = self._ensure_action_ball_full_mdp_command_metric_device_state(
            bucket_order=buckets,
            like=probe,
        )
        exact_width = 10 + 8 * len(buckets)
        state[exact_width:].mul_(float(decay))
        self._action_ball_full_mdp_command_metric_hold_decay_step_count += 1
        return state

    def _add_action_ball_full_mdp_hold_metric_device_values(
        self,
        values: Sequence[torch.Tensor],
    ) -> None:
        scalars = tuple(values)
        if len(scalars) != 5:
            raise RuntimeError("full-MDP hold/recovery metric width differs")
        buckets = tuple(self._clip_names)
        state = self._ensure_action_ball_full_mdp_command_metric_device_state(
            bucket_order=buckets,
            like=scalars[0],
        )
        exact_width = 10 + 8 * len(buckets)
        row = torch.stack(scalars).detach().to(dtype=torch.float64)
        state[exact_width:].add_(row)
        self._action_ball_full_mdp_command_metric_hold_add_step_count += 1

    def _publish_action_ball_full_mdp_device_scalar(
        self,
        name: str,
        value: torch.Tensor,
    ) -> None:
        metric = self.metrics.get(name)
        if metric is None:
            return
        if (
            not torch.is_tensor(value)
            or value.numel() != 1
            or value.device != metric.device
        ):
            raise RuntimeError("full-MDP public command metric scalar differs")
        metric.copy_(value.to(dtype=metric.dtype).expand_as(metric))

    def _publish_action_ball_full_mdp_pre_bucket_device_metrics(
        self,
    ) -> None:
        """Preserve the reset-visible one-step bucket/hold publication seams."""

        buckets = tuple(self._clip_names)
        probe = self.metrics["strike_composite_success_exact"].reshape(-1)[0]
        state = self._ensure_action_ball_full_mdp_command_metric_device_state(
            bucket_order=buckets,
            like=probe,
        )
        minimum = float(self.cfg.exact_success_min_count)
        exact_n = state[0]
        swing_n = float(self._swing_starts_acc)
        swing_completion = (
            torch.clamp(exact_n / max(swing_n, 1.0e-6), max=1.0)
            if swing_n >= minimum
            else torch.zeros_like(exact_n)
        )
        self._publish_action_ball_full_mdp_device_scalar(
            "swing_completion_rate", swing_completion
        )
        for ordinal, bucket in enumerate(buckets):
            bucket_n = state[10 + 8 * ordinal]
            bucket_swing_n = float(self._swing_starts_acc_c[bucket])
            bucket_completion = (
                torch.clamp(
                    bucket_n / max(bucket_swing_n, 1.0e-6), max=1.0
                )
                if bucket_swing_n >= minimum
                else torch.zeros_like(bucket_n)
            )
            self._publish_action_ball_full_mdp_device_scalar(
                f"swing_completion_rate_{self._clip_names[bucket]}",
                bucket_completion,
            )
        exact_width = 10 + 8 * len(buckets)
        (
            heading_sum,
            heading_n,
            recovery_spawn_sum,
            recovery_expiry_sum,
            recovery_n,
        ) = state[exact_width:].unbind()
        zero = torch.zeros_like(heading_n)
        heading_scale = torch.where(
            heading_n >= minimum,
            heading_n.clamp_min(1.0e-6).reciprocal(),
            zero,
        )
        recovery_scale = torch.where(
            recovery_n >= minimum,
            recovery_n.clamp_min(1.0e-6).reciprocal(),
            zero,
        )
        for name, value in (
            ("base_heading_abs_at_swing_start", heading_sum * heading_scale),
            ("base_heading_hold_expiry_count", heading_n),
            ("heading_recovery_spawn_yaw", recovery_spawn_sum * recovery_scale),
            ("heading_recovery_expiry_yaw", recovery_expiry_sum * recovery_scale),
            ("heading_recovery_count", recovery_n),
        ):
            self._publish_action_ball_full_mdp_device_scalar(name, value)

    def _publish_action_ball_full_mdp_exact_global_device_metrics(
        self,
    ) -> None:
        buckets = tuple(self._clip_names)
        probe = self.metrics["strike_composite_success_exact"].reshape(-1)[0]
        state = self._ensure_action_ball_full_mdp_command_metric_device_state(
            bucket_order=buckets,
            like=probe,
        )
        minimum = float(self.cfg.exact_success_min_count)
        exact_n = state[0]
        scale = torch.where(
            exact_n >= minimum,
            exact_n.clamp_min(1.0e-6).reciprocal(),
            torch.zeros_like(exact_n),
        )
        for name, value in (
            ("strike_composite_success_exact", state[1] * scale),
            ("strike_pos_pass_exact", state[2] * scale),
            ("strike_vel_pass_exact", state[3] * scale),
            ("exact_strike_pos_success_5cm", state[4] * scale),
            ("exact_strike_pos_success_10cm", state[5] * scale),
            ("strike_normal_pass_exact", state[6] * scale),
            ("exact_strike_sample_count_decayed", exact_n),
        ):
            self._publish_action_ball_full_mdp_device_scalar(name, value)
        for channel in ("pos", "vel", "normal", "composite"):
            self._publish_action_ball_full_mdp_device_scalar(
                f"strike_{channel}_target_eligible_sample_count_decayed",
                exact_n,
            )

    def _publish_action_ball_full_mdp_exact_bucket_device_metrics(
        self,
    ) -> None:
        buckets = tuple(self._clip_names)
        probe = self.metrics["strike_composite_success_exact"].reshape(-1)[0]
        state = self._ensure_action_ball_full_mdp_command_metric_device_state(
            bucket_order=buckets,
            like=probe,
        )
        minimum = float(self.cfg.exact_success_min_count)
        for ordinal, bucket in enumerate(buckets):
            offset = 10 + 8 * ordinal
            values = state[offset : offset + 8]
            bucket_n = values[0]
            scale = torch.where(
                bucket_n >= minimum,
                bucket_n.clamp_min(1.0e-6).reciprocal(),
                torch.zeros_like(bucket_n),
            )
            suffix = self._clip_names[bucket]
            for name, value in (
                (f"strike_pos_pass_exact_{suffix}", values[1] * scale),
                (f"strike_vel_pass_exact_{suffix}", values[2] * scale),
                (f"strike_normal_pass_exact_{suffix}", values[3] * scale),
                (f"strike_composite_success_exact_{suffix}", values[4] * scale),
                (f"racket_pos_error_exact_strike_{suffix}", values[5] * scale),
                (f"racket_vel_error_exact_strike_{suffix}", values[6] * scale),
                (
                    f"racket_normal_error_deg_exact_strike_{suffix}",
                    values[7] * scale,
                ),
            ):
                self._publish_action_ball_full_mdp_device_scalar(name, value)
            for channel in ("pos", "vel", "normal", "composite"):
                self._publish_action_ball_full_mdp_device_scalar(
                    f"strike_{channel}_target_eligible_sample_count_decayed_{suffix}",
                    bucket_n,
                )

    def _materialize_action_ball_full_mdp_command_metrics(
        self,
        expected_step_counts: tuple[int, ...] | None,
    ) -> bool:
        """Synchronize one combined exact+hold state at a PPO/report boundary."""

        state = getattr(
            self,
            "_action_ball_full_mdp_command_metric_device_state",
            None,
        )
        if state is None:
            if expected_step_counts is not None:
                raise RuntimeError(
                    "full-MDP command metric state was not produced before PPO drain"
                )
            return False
        if not self._action_ball_full_mdp_device_command_metrics_enabled():
            raise RuntimeError(
                "full-MDP command metric state survived after its predicate disabled"
            )
        if expected_step_counts is not None and (
            type(expected_step_counts) is not tuple
            or not expected_step_counts
            or any(
                type(count) is not int or count < 1
                for count in expected_step_counts
            )
            or len(set(expected_step_counts)) != len(expected_step_counts)
        ):
            raise RuntimeError("full-MDP command metric expected-step contract differs")
        counts = (
            self._action_ball_full_mdp_command_metric_exact_step_count,
            self._action_ball_full_mdp_command_metric_bucket_step_count,
            self._action_ball_full_mdp_command_metric_hold_decay_step_count,
            self._action_ball_full_mdp_command_metric_hold_add_step_count,
        )
        if len(set(counts)) != 1:
            raise RuntimeError(
                "full-MDP exact/hold command metric step counts differ: "
                + repr(counts)
            )
        count = counts[0]
        if count == 0:
            if expected_step_counts is not None:
                raise RuntimeError("full-MDP command metric PPO span is empty")
            return False
        if expected_step_counts is not None and count not in expected_step_counts:
            raise RuntimeError(
                "full-MDP command metric PPO span differs: "
                f"actual={count}, expected={expected_step_counts}"
            )
        host_values = _batched_host_scalar_values(tuple(state.unbind()))
        order = self._action_ball_full_mdp_command_metric_order_retained
        if len(host_values) != len(order):
            raise RuntimeError("full-MDP command metric host snapshot width differs")
        if any(not math.isfinite(value) for value in host_values):
            raise RuntimeError("full-MDP command metric host snapshot is non-finite")
        for (attribute, bucket), value in zip(order, host_values):
            if bucket is None:
                setattr(self, attribute, value)
            else:
                getattr(self, attribute)[bucket] = value
        n = max(float(self._exact_n_acc), 1.0e-6)
        self._exact_composite_rate = (
            float(self._exact_pass_comp_acc) / n
            if self._exact_n_acc >= float(self.cfg.exact_success_min_count)
            else 0.0
        )
        self._action_ball_full_mdp_command_metric_exact_step_count = 0
        self._action_ball_full_mdp_command_metric_bucket_step_count = 0
        self._action_ball_full_mdp_command_metric_hold_decay_step_count = 0
        self._action_ball_full_mdp_command_metric_hold_add_step_count = 0
        return True

    def _action_ball_diagnostic_device_telemetry_enabled(self) -> bool:
        """Whether pure telemetry may stay device-resident until the PPO boundary."""

        return bool(getattr(self, "_action_ball_enabled", False)) and bool(
            getattr(
                self,
                "_action_ball_diagnostic_unauthorized",
                False,
            )
        )

    def _action_ball_diagnostic_device_telemetry_slot(
        self,
        group: str,
        target: tuple[str, int | None],
        like: torch.Tensor,
    ) -> torch.Tensor:
        """Return one float64 device scalar for a deferred diagnostic metric."""

        if not torch.is_tensor(like) or like.numel() != 1:
            raise RuntimeError(
                "diagnostic telemetry increments must be scalar tensors"
            )
        registry = getattr(
            self,
            "_action_ball_diagnostic_device_telemetry",
            None,
        )
        if registry is None:
            registry = {}
            self._action_ball_diagnostic_device_telemetry = registry
        slots = registry.setdefault(str(group), {})
        slot = slots.get(target)
        if slot is None:
            slot = torch.zeros(
                (),
                dtype=torch.float64,
                device=like.device,
            )
            slots[target] = slot
        elif slot.device != like.device or slot.dtype != torch.float64:
            raise RuntimeError(
                "diagnostic telemetry device/dtype changed during one run"
            )
        return slot

    def _action_ball_diagnostic_device_telemetry_add(
        self,
        group: str,
        target: tuple[str, int | None],
        increment: torch.Tensor,
    ) -> None:
        """Accumulate one pure metric without synchronizing CUDA to Python."""

        slot = self._action_ball_diagnostic_device_telemetry_slot(
            group,
            target,
            increment,
        )
        slot.add_(increment.detach().reshape(()).to(dtype=torch.float64))
        self._action_ball_diagnostic_metrics_pending = True

    def _action_ball_diagnostic_device_telemetry_recur(
        self,
        group: str,
        target: tuple[str, int | None],
        decay: float,
        increment: torch.Tensor,
    ) -> None:
        """Apply ``state = decay*state + increment`` entirely on device."""

        slot = self._action_ball_diagnostic_device_telemetry_slot(
            group,
            target,
            increment,
        )
        slot.mul_(float(decay)).add_(
            increment.detach().reshape(()).to(dtype=torch.float64)
        )
        self._action_ball_diagnostic_metrics_pending = True

    def _decay_action_ball_diagnostic_device_telemetry(
        self,
        group: str,
        decay: float,
    ) -> None:
        """Decay one deferred metric family at its historical cadence."""

        registry = getattr(
            self,
            "_action_ball_diagnostic_device_telemetry",
            {},
        )
        for value in registry.get(str(group), {}).values():
            value.mul_(float(decay))

    def _flush_action_ball_diagnostic_device_telemetry(self) -> bool:
        """Apply every deferred pure metric through one update-boundary D2H."""

        if not bool(
            getattr(
                self,
                "_action_ball_diagnostic_metrics_pending",
                False,
            )
        ):
            return False
        registry = getattr(
            self,
            "_action_ball_diagnostic_device_telemetry",
            {},
        )
        entries = [
            (target, value)
            for group in registry.values()
            for target, value in group.items()
        ]
        if not entries:
            self._action_ball_diagnostic_metrics_pending = False
            return False
        host_values = _batched_host_scalar_values(
            tuple(value for _, value in entries)
        )
        # The slots are first created from the command-manager update, which
        # Isaac Lab executes under ``torch.inference_mode``.  PyTorch therefore
        # brands them as inference tensors; the runner's reporting hook is
        # outside that context.  Keep this no-grad telemetry mutation inside
        # inference mode so the update boundary can clear either tensor kind.
        with torch.inference_mode():
            for ((attribute, clip), device_value), increment in zip(
                entries,
                host_values,
            ):
                current = getattr(self, attribute)
                if clip is None:
                    setattr(self, attribute, current + increment)
                else:
                    current[clip] += increment
                device_value.zero_()
        self._action_ball_diagnostic_metrics_pending = False
        return True

    def _refresh_action_ball_diagnostic_public_metrics(self) -> None:
        """Re-materialize every public metric backed by deferred accumulators.

        This runs only after the update/report boundary has transferred all deferred
        float64 scalars to their historical Python accumulators.  Reward, termination,
        curriculum and exact-behavior decisions never read these presentation metrics.
        """

        metrics = getattr(self, "metrics", None)
        if not isinstance(metrics, dict):
            return

        def publish(name: str, value: float) -> None:
            metric = metrics.get(name)
            if metric is not None:
                # Observation-manager metric buffers may also have been born
                # under inference mode.  Reporting is presentation-only and
                # must support both inference and ordinary tensors.
                with torch.inference_mode():
                    metric.fill_(float(value))

        minimum = float(self.cfg.exact_success_min_count)
        swing_n = self._swing_starts_acc
        swing_denom = max(swing_n, 1.0e-6)
        swing_enough = swing_n >= minimum
        publish(
            "swing_completion_rate",
            min(self._exact_n_acc / swing_denom, 1.0)
            if swing_enough
            else 0.0,
        )
        publish(
            "pre_strike_fall_rate",
            min(self._prestrike_fall_acc / swing_denom, 1.0)
            if swing_enough
            else 0.0,
        )
        publish(
            "post_strike_fall_rate",
            min(self._poststrike_fall_acc / swing_denom, 1.0)
            if swing_enough
            else 0.0,
        )

        drift_denom = max(self._drift_n_acc, 1.0e-6)
        drift_enough = self._drift_n_acc >= minimum
        publish(
            "base_drift_per_swing",
            self._drift_sum_acc / drift_denom if drift_enough else 0.0,
        )
        publish(
            "base_drift_fwd_per_swing",
            self._drift_fwd_sum_acc / drift_denom
            if drift_enough
            else 0.0,
        )
        publish(
            "base_station_offset_at_swing_start",
            self._station_offset_start_sum_acc / drift_denom
            if drift_enough
            else 0.0,
        )

        heading_denom = max(self._heading_expiry_n_acc, 1.0e-6)
        heading_enough = self._heading_expiry_n_acc >= minimum
        publish(
            "base_heading_abs_at_swing_start",
            self._heading_expiry_sum_acc / heading_denom
            if heading_enough
            else 0.0,
        )
        publish(
            "base_heading_hold_expiry_count",
            self._heading_expiry_n_acc,
        )
        recovery_denom = max(self._recovery_n_acc, 1.0e-6)
        recovery_enough = self._recovery_n_acc >= minimum
        publish(
            "heading_recovery_spawn_yaw",
            self._recovery_spawn_sum_acc / recovery_denom
            if recovery_enough
            else 0.0,
        )
        publish(
            "heading_recovery_expiry_yaw",
            self._recovery_expiry_sum_acc / recovery_denom
            if recovery_enough
            else 0.0,
        )
        publish("heading_recovery_count", self._recovery_n_acc)
        if hasattr(self, "_tracking_loss_acc"):
            publish(
                "tracking_loss_rate",
                min(self._tracking_loss_acc / swing_denom, 1.0)
                if swing_enough
                else 0.0,
            )

        rally_denom = max(self._rally_starts_acc, 1.0e-6)
        publish(
            "virtual_return_rate_rally",
            self._rally_returns_acc / rally_denom
            if self._rally_starts_acc >= minimum
            else 0.0,
        )

        vb_exact = self._vb_exact_acc
        vb_hit = self._vb_hit_acc
        vb_exact_denom = max(vb_exact, 1.0e-6)
        vb_hit_denom = max(vb_hit, 1.0e-6)
        vb_exact_enough = vb_exact >= minimum
        vb_hit_enough = vb_hit >= 1.0
        publish(
            "virtual_hit_rate",
            vb_hit / vb_exact_denom if vb_exact_enough else 0.0,
        )
        publish(
            "virtual_net_clear_rate",
            self._vb_net_acc / vb_hit_denom if vb_hit_enough else 0.0,
        )
        publish(
            "virtual_land_valid_rate",
            self._vb_land_valid_acc / vb_hit_denom
            if vb_hit_enough
            else 0.0,
        )
        publish(
            "virtual_land_inbounds_rate",
            self._vb_inb_acc / vb_hit_denom if vb_hit_enough else 0.0,
        )
        publish(
            "virtual_return_rate",
            self._vb_inb_acc / vb_exact_denom
            if vb_exact_enough
            else 0.0,
        )
        if bool(getattr(self.cfg, "rally_legacy_metrics", False)):
            publish(
                "virtual_return_rate_rally_legacy",
                self._vb_inb_acc / swing_denom
                if vb_exact_enough
                else 0.0,
            )

        for clip, clip_name in self._clip_names.items():
            clip_swing = self._swing_starts_acc_c[clip]
            clip_swing_denom = max(clip_swing, 1.0e-6)
            clip_swing_enough = clip_swing >= minimum
            publish(
                f"swing_completion_rate_{clip_name}",
                min(
                    self._exact_n_acc_c[clip] / clip_swing_denom,
                    1.0,
                )
                if clip_swing_enough
                else 0.0,
            )
            publish(
                f"pre_strike_fall_rate_{clip_name}",
                min(
                    self._prestrike_fall_acc_c[clip]
                    / clip_swing_denom,
                    1.0,
                )
                if clip_swing_enough
                else 0.0,
            )
            publish(
                f"post_strike_fall_rate_{clip_name}",
                min(
                    self._poststrike_fall_acc_c[clip]
                    / clip_swing_denom,
                    1.0,
                )
                if clip_swing_enough
                else 0.0,
            )
            if hasattr(self, "_tracking_loss_acc_c"):
                publish(
                    f"tracking_loss_rate_{clip_name}",
                    min(
                        self._tracking_loss_acc_c[clip]
                        / clip_swing_denom,
                        1.0,
                    )
                    if clip_swing_enough
                    else 0.0,
                )
            clip_rally = self._rally_starts_acc_c[clip]
            publish(
                f"virtual_return_rate_rally_{clip_name}",
                self._rally_returns_acc_c[clip]
                / max(clip_rally, 1.0e-6)
                if clip_rally >= minimum
                else 0.0,
            )
            clip_vb_exact = self._vb_exact_acc_c[clip]
            clip_vb_scale = (
                1.0 / max(clip_vb_exact, 1.0e-6)
                if clip_vb_exact >= minimum
                else 0.0
            )
            publish(
                f"virtual_return_rate_{clip_name}",
                self._vb_inb_acc_c[clip] * clip_vb_scale,
            )
            publish(
                f"virtual_hit_rate_{clip_name}",
                self._vb_hit_acc_c[clip] * clip_vb_scale,
            )
            if bool(getattr(self.cfg, "rally_legacy_metrics", False)):
                publish(
                    f"virtual_return_rate_rally_{clip_name}_legacy",
                    self._vb_inb_acc_c[clip] / clip_swing_denom
                    if vb_exact_enough
                    else 0.0,
                )

    def materialize_action_ball_diagnostic_metrics_for_report(
        self,
        *,
        expected_full_mdp_command_metric_step_counts: tuple[int, ...] | None = None,
    ) -> None:
        """One explicit boundary for training logs and consumer-less evaluation."""

        self._materialize_action_ball_full_mdp_command_metrics(
            expected_full_mdp_command_metric_step_counts
        )
        self._flush_diagnostic_hold_recovery_metric_scalars()
        if not self._action_ball_diagnostic_device_telemetry_enabled():
            return
        self._flush_action_ball_diagnostic_device_telemetry()
        self._refresh_action_ball_diagnostic_public_metrics()

    def assert_action_ball_diagnostic_metrics_materialized_for_report(
        self,
    ) -> None:
        """Reject a diagnostic report that skipped the explicit boundary."""

        pending_full_mdp_counts = (
            getattr(
                self,
                "_action_ball_full_mdp_command_metric_exact_step_count",
                0,
            ),
            getattr(
                self,
                "_action_ball_full_mdp_command_metric_bucket_step_count",
                0,
            ),
            getattr(
                self,
                "_action_ball_full_mdp_command_metric_hold_decay_step_count",
                0,
            ),
            getattr(
                self,
                "_action_ball_full_mdp_command_metric_hold_add_step_count",
                0,
            ),
        )
        if any(pending_full_mdp_counts):
            raise RuntimeError(
                "full-MDP command metrics are pending on device; call "
                "materialize_action_ball_diagnostic_metrics_for_report() "
                "before reporting"
            )

        if bool(
            getattr(
                self,
                "_action_ball_diagnostic_metrics_pending",
                False,
            )
        ):
            raise RuntimeError(
                "diagnostic public metrics are pending on device; "
                "call materialize_action_ball_diagnostic_metrics_for_report() "
                "before a consumer-less evaluation reads command.metrics"
            )

    def _flush_diagnostic_hold_recovery_metric_scalars(self) -> None:
        """Drain the final diagnostic rollout step once at the PPO update boundary."""

        pending = tuple(
            getattr(
                self,
                "_diagnostic_hold_recovery_metric_scalars",
                (),
            )
        )
        if not pending:
            return
        self._apply_hold_recovery_host_values(
            _batched_host_scalar_values(pending)
        )
        self._diagnostic_hold_recovery_metric_scalars = ()

    def _book_action_ball_learning_trend(
        self,
        *,
        exact_strike: torch.Tensor,
        nominal_ball_center_w: torch.Tensor,
        capture: torch.Tensor,
        v_plus: torch.Tensor,
        w_plus: torch.Tensor,
        topspin: torch.Tensor,
        topspin_axis_valid: torch.Tensor,
        landing_xy: torch.Tensor,
        landing_valid: torch.Tensor,
        landing_target_xy: torch.Tensor,
    ) -> None:
        """Accumulate one update's causal learning ladder without leaving the device.

        The proximity cohort is the task-valid, active nominal strike tick, whether or not contact
        occurs.  Immediate ball state uses the actual selected-rubber ``capture`` gate rather than
        the later legal-return subset.  Landing values are a second-stage cohort: existing
        ``virtual_capture_count`` is the denominator for landing validity, while these values are
        conditioned on an existing valid landing and a finite frozen target.  This method is
        instrumentation-only; no reward, observation, reset, sampler or phase state reads it.

        The runner persists consumed counters once per completed PPO update.  They are not yet
        exact-resume durable inside an in-flight update: formal checkpoint ordering precedes logger
        consumption and this pending ledger is not part of the exact command state.  No resume
        claim may bridge that gap until ordering plus state round-trip are fixed and tested.
        """

        ledger = self._ensure_exact_behavior_decision_counters()
        active = self._action_ball_attempt_active.detach().bool()
        task_valid = self._action_ball_task_valid.detach().bool()
        nominal = exact_strike.detach().bool() & active & task_valid

        paddle_center_w = self.racket_pos_w.detach()
        nominal_ball_center_w = nominal_ball_center_w.detach()
        paddle_ball_distance = torch.linalg.vector_norm(
            paddle_center_w - nominal_ball_center_w,
            dim=-1,
        )
        distance_finite = (
            nominal
            & torch.isfinite(paddle_center_w).all(dim=-1)
            & torch.isfinite(nominal_ball_center_w).all(dim=-1)
            & torch.isfinite(paddle_ball_distance)
        )
        distance_nonfinite = nominal & ~distance_finite
        safe_distance = torch.where(
            distance_finite,
            paddle_ball_distance,
            torch.zeros_like(paddle_ball_distance),
        )
        safe_distance_f64 = safe_distance.to(dtype=torch.float64)
        ledger[_EXACT_STRIKE_PADDLE_BALL_DISTANCE_COUNT].add_(
            distance_finite.sum(dtype=torch.long)
        )
        ledger[_EXACT_STRIKE_PADDLE_BALL_DISTANCE_NONFINITE_COUNT].add_(
            distance_nonfinite.sum(dtype=torch.long)
        )
        ledger[_EXACT_STRIKE_PADDLE_BALL_DISTANCE_SUM].add_(
            safe_distance_f64.sum()
        )
        ledger[_EXACT_STRIKE_PADDLE_BALL_DISTANCE_SUM_SQ].add_(
            torch.square(safe_distance_f64).sum()
        )

        # Offset bucket ids by one so every excluded row falls into a disposable zero bucket.  One
        # bincount produces the complete fixed histogram; no per-bin host predicate is evaluated.
        distance_bucket = torch.bucketize(
            safe_distance,
            self._exact_strike_paddle_ball_distance_bin_edges_m_t,
            right=False,
        )
        encoded_bucket = torch.where(
            distance_finite,
            distance_bucket + 1,
            torch.zeros_like(distance_bucket),
        )
        distance_histogram = torch.bincount(
            encoded_bucket,
            minlength=len(_EXACT_STRIKE_PADDLE_BALL_DISTANCE_BUCKET_COUNTERS)
            + 1,
        )[1:]
        for counter_name, increment in zip(
            _EXACT_STRIKE_PADDLE_BALL_DISTANCE_BUCKET_COUNTERS,
            distance_histogram.unbind(),
        ):
            ledger[counter_name].add_(increment)

        capture_cohort = capture.detach().bool() & active & task_valid

        def book_vector(
            metric_names: tuple[str, ...],
            values: torch.Tensor,
            cohort: torch.Tensor,
            *,
            finite_count_name: str,
            nonfinite_count_name: str,
        ) -> torch.Tensor:
            values = values.detach()
            finite = cohort & torch.isfinite(values).all(dim=-1)
            selected = torch.where(
                finite.unsqueeze(-1),
                values,
                torch.zeros_like(values),
            ).to(dtype=torch.float64)
            sums = selected.sum(dim=0)
            sums_sq = torch.square(selected).sum(dim=0)
            ledger[finite_count_name].add_(finite.sum(dtype=torch.long))
            ledger[nonfinite_count_name].add_(
                (cohort & ~finite).sum(dtype=torch.long)
            )
            for metric_name, value_sum, value_sum_sq in zip(
                metric_names,
                sums.unbind(),
                sums_sq.unbind(),
            ):
                ledger[f"{metric_name}_sum"].add_(value_sum)
                ledger[f"{metric_name}_sum_sq"].add_(value_sum_sq)
            return finite

        v_plus = v_plus.detach()
        v_plus_speed = torch.linalg.vector_norm(v_plus, dim=-1, keepdim=True)
        v_plus_finite = book_vector(
            _CAPTURE_V_PLUS_METRICS,
            torch.cat((v_plus, v_plus_speed), dim=-1),
            capture_cohort,
            finite_count_name="capture_v_plus_finite_count",
            nonfinite_count_name="capture_v_plus_nonfinite_count",
        )
        w_plus = w_plus.detach()
        w_plus_norm = torch.linalg.vector_norm(w_plus, dim=-1, keepdim=True)
        w_plus_finite = book_vector(
            _CAPTURE_W_PLUS_METRICS,
            torch.cat((w_plus, w_plus_norm), dim=-1),
            capture_cohort,
            finite_count_name="capture_w_plus_finite_count",
            nonfinite_count_name="capture_w_plus_nonfinite_count",
        )

        # Topspin is signed.  Its axis comes from v_plus, so both post-contact vectors must be
        # finite; storing abs(topspin) here would erase the backspin/topspin distinction.
        topspin = topspin.detach()
        topspin_axis_valid = topspin_axis_valid.detach().bool()
        topspin_axis_invalid = (
            capture_cohort
            & v_plus_finite
            & w_plus_finite
            & ~topspin_axis_valid
        )
        topspin_finite = (
            capture_cohort
            & v_plus_finite
            & w_plus_finite
            & topspin_axis_valid
            & torch.isfinite(topspin)
        )
        topspin_other_nonfinite = (
            capture_cohort
            & ~topspin_finite
            & ~topspin_axis_invalid
        )
        safe_topspin = torch.where(
            topspin_finite,
            topspin,
            torch.zeros_like(topspin),
        ).to(dtype=torch.float64)
        ledger["capture_w_plus_topspin_finite_count"].add_(
            topspin_finite.sum(dtype=torch.long)
        )
        ledger["capture_w_plus_topspin_axis_invalid_count"].add_(
            topspin_axis_invalid.sum(dtype=torch.long)
        )
        ledger["capture_w_plus_topspin_nonfinite_count"].add_(
            topspin_other_nonfinite.sum(dtype=torch.long)
        )
        ledger[f"{_CAPTURE_W_PLUS_TOPSPIN_METRIC}_sum"].add_(
            safe_topspin.sum()
        )
        ledger[f"{_CAPTURE_W_PLUS_TOPSPIN_METRIC}_sum_sq"].add_(
            torch.square(safe_topspin).sum()
        )

        landing_xy = landing_xy.detach()
        landing_target_xy = landing_target_xy.detach()
        landing_delta = landing_xy - landing_target_xy
        landing_error = torch.linalg.vector_norm(
            landing_delta,
            dim=-1,
            keepdim=True,
        )
        landing_values = torch.cat(
            (landing_xy, landing_delta, landing_error),
            dim=-1,
        )
        book_vector(
            _CAPTURE_LANDING_METRICS,
            landing_values,
            capture_cohort & landing_valid.detach().bool(),
            finite_count_name="capture_landing_xy_finite_count",
            nonfinite_count_name="capture_landing_xy_nonfinite_count",
        )

    def _vb_evaluate(
        self,
        exact_strike: torch.Tensor,
        pos_err: torch.Tensor,
        *,
        diagnostic_host_scalars: Sequence[torch.Tensor] = (),
    ) -> tuple[float, ...]:
        """Tier-1 at-strike virtual-ball evaluation (rewardDesign.md).

        Runs once per control step from ``_update_metrics`` (rewards/obs read the same fresh
        buffers after ``command_manager.compute()``). Whenever ANY env sits at its exact-strike
        frame, the FULL batch goes through contact + coarse rollout — the cost is kernel-launch
        bound and batch-size independent, so gathering the ~30 striking envs saves nothing
        (verify_tier1 (b)); ``vb_fired`` masks consumption. On strike-free steps the one-shot
        mask is cleared and nothing is computed.
        """
        from whole_body_tracking.tasks.tracking.mdp import virtual_ball as _vb

        current_angular_velocity = None
        exact_any = None
        prefetched_host_scalars: tuple[float, ...] = ()
        if self._action_ball_enabled:
            # RewardManager reads these one-shot caches after command.compute().
            # Clear them on every control step so a strike can never pay twice.
            self._counter_rally_reward_terms.zero_()
            self._counter_rally_accepted.zero_()
            self._counter_rally_legal_first_landing.zero_()
            self._counter_rally_primary_reason_code.fill_(-1)
            from . import racket_contact_geometry as contact_geometry

            active = self._action_ball_attempt_active
            if self._action_ball_diagnostic_unauthorized:
                # Diagnostic runs batch the three fail-fast predicates through one host transfer.
                # Formal/default keeps its historical sequential failure boundary below: orphan
                # exact must raise before motion is read, and identity drift before angular
                # velocity is read.
                orphan_exact = (exact_strike & ~active).any()
                current_clip = self._motion().clip_id.to(
                    dtype=torch.long
                )
                active_identity_drift = active & (
                    (
                        self._action_ball_action_slot
                        != self._action_ball_attempt_action
                    )
                    | (
                        current_clip
                        != self._action_ball_attempt_action
                    )
                )
                (
                    orphan_exact_host,
                    identity_drift_host,
                    exact_any_host,
                    prefetched_host_scalars,
                ) = _action_ball_diagnostic_host_packet(
                    orphan_exact=orphan_exact,
                    identity_drift=active_identity_drift.any(),
                    exact_any=exact_strike.any(),
                    metric_scalars=diagnostic_host_scalars,
                )
                if orphan_exact_host:
                    raise RuntimeError(
                        "ActionBall exact strike has no active attempt"
                    )
                if identity_drift_host:
                    raise RuntimeError(
                        "ActionBall active action identity drifted "
                        "between motion, task, and attempt"
                    )
                exact_any = bool(exact_any_host)
            else:
                if bool((exact_strike & ~active).any()):
                    raise RuntimeError(
                        "ActionBall exact strike has no active attempt"
                    )
                current_clip = self._motion().clip_id.to(
                    dtype=torch.long
                )
                active_identity_drift = active & (
                    (
                        self._action_ball_action_slot
                        != self._action_ball_attempt_action
                    )
                    | (
                        current_clip
                        != self._action_ball_attempt_action
                    )
                )
                if bool(active_identity_drift.any()):
                    raise RuntimeError(
                        "ActionBall active action identity drifted "
                        "between motion, task, and attempt"
                    )
            current_angular_velocity = (
                self._racket_angular_velocity_w()
            )
        if exact_any is None:
            exact_any = bool(exact_strike.any())
        if not exact_any:
            self.vb_fired.zero_()
            if current_angular_velocity is not None:
                self._action_ball_store_virtual_contact_history(
                    current_angular_velocity,
                )
            return prefetched_host_scalars
        if self._vb_params is None:
            self._vb_params = _vb.load_venue_params()
            print(
                f"[RacketTargetCommand] virtual ball ON: venue constants from "
                f"{self._vb_params.source_path} (k_d={self._vb_params.k_d}, "
                f"k_m={self._vb_params.k_m}, e(u_n)={self._vb_params.paddle_e_g1}"
                f"*exp({self._vb_params.paddle_e_g2}*u_n), a_t={self._vb_params.paddle_a_t})",
                flush=True,
            )
        prm = self._vb_params

        v_in, w_in = self.vb_vel_in_w, self.vb_spin_in_w
        if self._action_ball_enabled:
            identity_valid = _vb.action_ball_sweep_identity_valid(
                previous_valid=(
                    self._action_ball_prev_contact_valid
                ),
                previous_action=(
                    self._action_ball_prev_attempt_action
                ),
                current_action=self._action_ball_attempt_action,
                previous_reset_generation=(
                    self._action_ball_prev_reset_generation
                ),
                current_reset_generation=(
                    self._action_ball_reset_generation
                ),
                previous_swing_generation=(
                    self._action_ball_prev_swing_generation
                ),
                current_swing_generation=(
                    self._action_ball_swing_generation
                ),
                attempt_active=(
                    self._action_ball_attempt_active
                ),
            )
            _action_ball_validate_tensor_predicate(
                ~(exact_strike & ~identity_valid),
                "ActionBall swept contact history is missing or belongs "
                "to another action/reset/swing",
                async_validate=self._action_ball_diagnostic_unauthorized,
            )
            step_dt = float(self._env.step_dt)
            if not math.isfinite(step_dt) or step_dt <= 0.0:
                raise RuntimeError(
                    "ActionBall swept contact requires one positive control "
                    "step duration"
                )
            ball_end_w = self._action_ball_ball_contact_target_w
            # Reconstruct only the strike rows, but at the finest formal
            # fitted-MuJoCo step.  The swept helper then uses the endpoint
            # positions/velocities as a cubic Hermite path, eliminating the
            # 0.49 mm gravity chord error of a 20 ms straight segment.
            strike_ids = torch.where(exact_strike)[0]
            ball_start_w = ball_end_w.clone()
            ball_velocity_start_w = v_in.clone()
            strike_ball = ball_end_w[strike_ids]
            strike_velocity = v_in[strike_ids]
            strike_spin = w_in[strike_ids]
            backprop_steps = max(
                1,
                int(
                    math.ceil(
                        step_dt
                        / contact_geometry.SELECTED_FACE_SWEEP_BALL_BACKPROP_MAX_DT_S
                    )
                ),
            )
            backprop_dt = -step_dt / float(backprop_steps)
            for _ in range(backprop_steps):
                strike_ball, strike_velocity = _vb.rk4_step(
                    strike_ball,
                    strike_velocity,
                    strike_spin,
                    backprop_dt,
                    prm,
                )
            ball_start_w[strike_ids] = strike_ball
            ball_velocity_start_w[strike_ids] = strike_velocity
            sign_table = torch.as_tensor(
                self._action_ball_mount_signs,
                dtype=ball_end_w.dtype,
                device=self.device,
            )
            attempt_action = self._action_ball_attempt_action
            invalid_action = active & (
                (attempt_action < 0)
                | (attempt_action >= len(self._action_ball_mount_signs))
            )
            _action_ball_validate_tensor_predicate(
                ~invalid_action,
                "ActionBall active attempt has no selected-face sign",
                async_validate=self._action_ball_diagnostic_unauthorized,
            )
            face_sign = sign_table[
                attempt_action.clamp(
                    min=0,
                    max=len(self._action_ball_mount_signs) - 1,
                )
            ]
            swept = (
                contact_geometry.torch_swept_selected_face_contact(
                    ball_start_w_m=ball_start_w,
                    ball_end_w_m=ball_end_w,
                    ball_velocity_start_w_mps=(
                        ball_velocity_start_w
                    ),
                    ball_velocity_end_w_mps=v_in,
                    racket_site_start_w_m=(
                        self._action_ball_prev_racket_site_w
                    ),
                    racket_site_end_w_m=self.racket_pos_w,
                    racket_quat_start_wxyz=(
                        self._action_ball_prev_racket_quat_w
                    ),
                    racket_quat_end_wxyz=self.racket_quat_w,
                    racket_site_velocity_start_w_mps=(
                        self._action_ball_prev_racket_site_velocity_w
                    ),
                    racket_site_velocity_end_w_mps=(
                        self.racket_lin_vel_w
                    ),
                    racket_angular_velocity_start_w_radps=(
                        self._action_ball_prev_racket_angular_velocity_w
                    ),
                    racket_angular_velocity_end_w_radps=(
                        current_angular_velocity
                    ),
                    face_sign=face_sign,
                    previous_valid=identity_valid,
                    segment_duration_s=step_dt,
                )
            )
            contact_origin_w = swept["ball_center_w_m"]
            v_contact = swept["ball_velocity_w_mps"]
            v_r = swept["contact_point_velocity_w_mps"]
            n_face = swept["physical_face_normal_w"]
        else:
            contact_origin_w = self.racket_pos_w
            v_contact = v_in
            v_r, n_face = self.racket_lin_vel_w, self.racket_normal_w
        # FACE-IDENTITY GATE: compare the convention-matched signed pair BEFORE orient_normal.
        # Under the active face-command contract this is achieved raw mount +Y/A versus demanded
        # raw A.  ``orient_normal`` is sign-invariant and may orient the contact plane for impulse
        # physics, but it must never turn the opposite rubber face into a scored hit.
        if self._action_ball_enabled:
            # Judge the signed selected face at the swept collision, not at
            # the control-step endpoint.  physical-B = raw-A * mount_sign.
            mount_sign = face_sign.unsqueeze(-1)
            face_achieved = n_face * mount_sign
            if self.cfg.face_command:
                face_target = self.target_normal_cmd
                target_physical_b = face_target * mount_sign
            else:
                face_target = self.racket_target_normal_w * mount_sign
                target_physical_b = self.racket_target_normal_w
        else:
            face_achieved, face_target = face_tracking_pair(self)
            if self.cfg.face_command:
                mount_sign = torch.where(
                    torch.sum(
                        self.racket_normal_w * self.racket_normal_raw_w,
                        dim=-1,
                        keepdim=True,
                    )
                    >= 0.0,
                    torch.ones_like(self.racket_normal_w[:, :1]),
                    -torch.ones_like(self.racket_normal_w[:, :1]),
                )
                target_physical_b = self.target_normal_cmd * mount_sign
            else:
                target_physical_b = self.racket_target_normal_w
        signed_face_ok, _signed_face_dot = _vb.signed_face_hemisphere(
            face_achieved,
            face_target,
            achieved_physical_b=n_face,
            target_physical_b=target_physical_b,
        )
        contact_state = _vb.paddle_contact_state(
            v_contact, v_r, n_face, w_in, prm
        )
        if self._action_ball_enabled:
            selected_closing_speed = contact_state[
                "selected_face_closing_speed_mps"
            ]
            normal_speed_consistent = (
                torch.abs(
                    selected_closing_speed
                    - swept["relative_normal_speed_mps"]
                )
                <= _vb.PADDLE_NORMAL_SPEED_PARITY_ABS_TOL_MPS
            )
            selected_side_contact = (
                swept["contact"]
                & (selected_closing_speed > 0.0)
                & normal_speed_consistent
            )
            gate, contact_rejections = (
                _vb.classify_action_ball_contact(
                    exact_strike=exact_strike,
                    # Outcome eligibility is owned by actual selected-rubber contact, finite
                    # fitted state and relative normal speed.  Agreement with a demanded target
                    # face is a separate shaping/diagnostic channel; making it a prerequisite
                    # would deny B/C outcome feedback precisely when the achieved face differs.
                    signed_face_ok=torch.ones_like(signed_face_ok),
                    geometry_contact=selected_side_contact,
                    contact_finite=(
                        swept["finite"] & contact_state["finite"]
                    ),
                    normal_speed_mps=selected_closing_speed,
                    async_validate=(
                        self._action_ball_diagnostic_unauthorized
                    ),
                )
            )
            self.metrics["action_ball_target_face_compatible_at_strike"] = torch.where(
                exact_strike
                & self.action_ball_target_component_valid("face"),
                signed_face_ok.float(),
                self.metrics["action_ball_target_face_compatible_at_strike"],
            )
            # The actual relative normal speed at the swept collision is the
            # fitted-contact support variable.  It replaces the old paddle
            # world-speed projection, which could accept a receding/phantom
            # contact and was not the u_n used by e(u_n).
            approach = selected_closing_speed
            # ``torch.where`` is required before contact/flight evaluation:
            # multiplying a NaN landing by vb_fired=0 later would still poison
            # the reward.  Captured rows keep the exact swept state; every
            # rejected row follows one finite, inert dummy trajectory.
            fallback_local = torch.zeros_like(contact_origin_w)
            fallback_local[:, 0] = float(
                self.cfg.vb_table_near_x
            )
            fallback_local[:, 2] = (
                float(self.cfg.vb_table_surface_z)
                + float(prm.ball_radius)
                + 0.1
            )
            rollout_inputs = (
                _vb.finite_action_ball_rollout_inputs(
                    capture=gate,
                    contact_origin_w_m=contact_origin_w,
                    ball_velocity_w_mps=v_contact,
                    contact_point_velocity_w_mps=v_r,
                    physical_face_normal_w=n_face,
                    ball_spin_w_radps=w_in,
                    fallback_origin_w_m=(
                        self._env.scene.env_origins
                        + fallback_local
                    ),
                    async_validate=(
                        self._action_ball_diagnostic_unauthorized
                    ),
                )
            )
            rollout_origin_w = rollout_inputs[
                "contact_origin_w_m"
            ]
            rollout_v_contact = rollout_inputs[
                "ball_velocity_w_mps"
            ]
            rollout_v_r = rollout_inputs[
                "contact_point_velocity_w_mps"
            ]
            rollout_n_face = rollout_inputs[
                "physical_face_normal_w"
            ]
            rollout_w_in = rollout_inputs[
                "ball_spin_w_radps"
            ]
            rollout_contact_state = _vb.paddle_contact_state(
                rollout_v_contact,
                rollout_v_r,
                rollout_n_face,
                rollout_w_in,
                prm,
            )
        else:
            contact_rejections = None
            n_or = contact_state["normal"]
            approach = torch.sum(v_r * n_or, dim=-1)
            gate = (
                exact_strike
                & signed_face_ok
                & (pos_err < float(self.cfg.vb_capture_radius))
                & (
                    approach
                    > float(self.cfg.vb_min_approach_speed)
                )
            )
            rollout_origin_w = contact_origin_w
            rollout_v_contact = v_contact
            rollout_v_r = v_r
            rollout_n_face = n_face
            rollout_w_in = w_in
            rollout_contact_state = contact_state

        # Achieved-state contact (venue paddle model, e(u_n)) + coarse landing rollout.
        # The rollout must start in the ENV-LOCAL frame: the virtual table landmarks
        # (vb_table_near_x / net / far end) and vb_target_xy are per-env offsets from the env
        # origin, while racket_pos_w is TRUE world frame (env grids span tens of meters at 4096
        # envs — using it raw put every landing ~|env_origin| away from the target; caught in the
        # first vb_warmE14k run: virtual_land_err_m ~62 m). Env grids are pure translations, so
        # velocities, normals, and spins need no correction.
        v_plus, w_plus = _vb.predict_paddle_contact(
            rollout_v_contact,
            rollout_v_r,
            rollout_n_face,
            rollout_w_in,
            prm,
            contact_state=rollout_contact_state,
        )
        land = _vb.coarse_landing(
            rollout_origin_w - self._env.scene.env_origins,
            v_plus,
            w_plus,
            prm,
            # Physical table contact = ball CENTER crossing surface + R (oracle / C++ /
            # landing.py / shadow-ball convention; venue landings were extracted at this
            # plane). Bare surface read the landing ~24 mm long (measured on ball-physics-
            # unify 2026-07-05, ported here so vb and shadow metrics share one convention).
            surface_z=float(self.cfg.vb_table_surface_z) + prm.ball_radius,
            net_x=self._vb_net_x,
            h=float(self.cfg.vb_rollout_h),
            n_steps=int(self.cfg.vb_rollout_steps),
        )
        if self._counter_rally_enabled:
            from whole_body_tracking.tasks.tracking.mdp.counter_rally_torch import (
                counter_rally_outcome_gates_torch,
                counter_rally_reward_raw_torch,
                rollout_counter_rally_torch,
            )

            # The fitted 1 ms rally rollout is much more expensive than the
            # ordinary coarse scorer.  Run it only for actual swept contacts,
            # never for the full environment batch or solver/teacher states.
            contact_ids = torch.where(gate)[0]
            fitted_landing_xy = torch.zeros_like(land["land_xy"])
            fitted_landing_valid = torch.zeros_like(
                land["land_valid"]
            )
            fitted_net_crossed = torch.zeros_like(land["net_valid"])
            fitted_net_clear = torch.zeros_like(land["net_valid"])
            if int(contact_ids.numel()) > 0:
                env_ids = tuple(
                    int(value)
                    for value in contact_ids.detach().cpu().tolist()
                )
                identities = []
                for env_id in env_ids:
                    identity = (
                        self._counter_rally_task_identity_by_env[
                            env_id
                        ]
                    )
                    if (
                        identity is None
                        or identity.objective_profile_sha256
                        != self._counter_rally_objective.sha256
                        or type(identity).from_dict(identity.to_dict())
                        != identity
                    ):
                        raise RuntimeError(
                            "counter-rally contact has no exact installed "
                            "task identity"
                        )
                    identities.append(identity)
                expected_direction = torch.tensor(
                    [
                        identity.return_direction_env_xy
                        for identity in identities
                    ],
                    dtype=rollout_origin_w.dtype,
                    device=self.device,
                )
                expected_speed = torch.tensor(
                    [
                        identity.target_baseline_speed_mps
                        for identity in identities
                    ],
                    dtype=rollout_origin_w.dtype,
                    device=self.device,
                )
                installed_direction = (
                    self._counter_rally_return_direction_env_xy[
                        contact_ids
                    ]
                )
                installed_speed = (
                    self._counter_rally_target_baseline_speed_mps[
                        contact_ids
                    ]
                )
                if not torch.equal(
                    installed_direction, expected_direction
                ) or not torch.equal(installed_speed, expected_speed):
                    raise RuntimeError(
                        "counter-rally installed task values drifted from "
                        "their immutable receipts"
                    )
                objective_shas = tuple(
                    identity.objective_profile_sha256
                    for identity in identities
                )
                counter_outcome = rollout_counter_rally_torch(
                    (
                        rollout_origin_w
                        - self._env.scene.env_origins
                    )[contact_ids],
                    v_plus[contact_ids],
                    w_plus[contact_ids],
                    binding=self._counter_rally_torch_binding,
                    dt_s=0.001,
                    max_time_s=2.0,
                )
                contact_valid = torch.ones(
                    len(env_ids),
                    dtype=torch.bool,
                    device=self.device,
                )
                counter_reward = counter_rally_reward_raw_torch(
                    binding=self._counter_rally_torch_binding,
                    landing_aim_env_xy_m=(
                        self._vb_target_xy_per_env[contact_ids]
                    ),
                    return_direction_env_xy=installed_direction,
                    target_baseline_speed_mps=installed_speed,
                    paddle_contact_valid=contact_valid,
                    task_objective_profile_sha256=objective_shas,
                    outcome=counter_outcome,
                )
                counter_gates = counter_rally_outcome_gates_torch(
                    outcome=counter_outcome,
                    binding=self._counter_rally_torch_binding,
                    landing_aim_env_xy_m=(
                        self._vb_target_xy_per_env[contact_ids]
                    ),
                    return_direction_env_xy=installed_direction,
                    target_baseline_speed_mps=installed_speed,
                    paddle_contact_valid=contact_valid,
                    task_objective_profile_sha256=objective_shas,
                )
                self._counter_rally_reward_terms[
                    contact_ids
                ] = counter_reward
                self._counter_rally_accepted[
                    contact_ids
                ] = counter_gates.accepted
                self._counter_rally_legal_first_landing[
                    contact_ids
                ] = counter_gates.legal_first_landing
                self._counter_rally_primary_reason_code[
                    contact_ids
                ] = counter_gates.primary_reason_code
                fitted_landing_xy[
                    contact_ids
                ] = counter_outcome.first_landing_env_xy_m
                fitted_landing_valid[
                    contact_ids
                ] = counter_outcome.first_landing_valid
                fitted_net_crossed[
                    contact_ids
                ] = counter_outcome.net_crossed
                fitted_net_clear[
                    contact_ids
                ] = counter_outcome.net_clear
            # Downstream generic metrics must describe the same fitted rally
            # that determines curriculum success.  N1 RewardManager terms do
            # not read the ordinary coarse landing output.
            land = dict(land)
            land["land_xy"] = fitted_landing_xy
            land["land_valid"] = fitted_landing_valid
            land["net_valid"] = fitted_net_crossed
        lx, ly = land["land_xy"][:, 0], land["land_xy"][:, 1]
        on_opp = (
            land["land_valid"] & (lx > self._vb_net_x) & (lx <= self._vb_far_x) & (ly.abs() <= self._vb_half_w)
        )
        depth_ok = lx > (self._vb_net_x + float(self.cfg.vb_min_landing_depth))
        net_clear = land["net_valid"] & (land["net_z"] > self._vb_net_top_z + self._vb_ball_r)
        if self._counter_rally_enabled:
            on_opp = self._counter_rally_legal_first_landing
            depth_ok = self._counter_rally_legal_first_landing
            net_clear = fitted_net_clear
        # Outgoing topspin component about t_hat = z_hat x d_hat of the outgoing horizontal
        # direction (Ace-style): omega . t_hat = -w_x*d_y + w_y*d_x.
        if self._action_ball_enabled:
            topspin, topspin_axis_valid = _action_ball_outgoing_topspin(
                v_plus,
                w_plus,
            )
            self._book_action_ball_learning_trend(
                exact_strike=exact_strike,
                nominal_ball_center_w=ball_end_w,
                capture=gate,
                v_plus=v_plus,
                w_plus=w_plus,
                topspin=topspin,
                topspin_axis_valid=topspin_axis_valid,
                landing_xy=land["land_xy"],
                landing_valid=land["land_valid"],
                landing_target_xy=self._vb_target_xy_per_env,
            )
        else:
            # Preserve the historical non-ActionBall path without paying for the diagnostic
            # axis-validity kernels used only by the future ActionBall evidence producer.
            d_xy = v_plus[:, :2]
            d_hat = d_xy / (
                torch.linalg.norm(d_xy, dim=-1, keepdim=True) + 1e-9
            )
            topspin = (
                -w_plus[:, 0] * d_hat[:, 1]
                + w_plus[:, 1] * d_hat[:, 0]
            )

        # One-shot caches consumed by hope_rewards.virtual_* THIS step.
        self.vb_fired = gate
        self.vb_landing_xy = land["land_xy"]
        self.vb_landing_valid = land["land_valid"]
        self.vb_on_opponent = on_opp
        self.vb_depth_ok = depth_ok
        self.vb_net_z = land["net_z"]
        self.vb_net_clear = net_clear
        self.vb_net_crossed = land["net_valid"]
        self.vb_topspin = topspin
        self.vb_spin_out_norm = torch.linalg.norm(w_plus, dim=-1)

        # Sample-weighted EMA rates (hit rate over exact-strike samples; outcome rates over captured
        # hits). NOTE: accumulators only decay on strike-carrying steps — exact at 4096 envs (a
        # strike happens ~every step), slightly stale at small env counts (diagnostics only).
        decay = float(self.cfg.exact_success_decay)
        # Keep the generic virtual-return ledger semantic stable: "legal"
        # means a legal first opponent-table landing in every task mode.
        # Counter-rally's stricter direction/speed acceptance is booked beside
        # it and remains the ActionBall curriculum outcome below.
        _legal = (
            self._counter_rally_legal_first_landing
            if self._counter_rally_enabled
            else gate & net_clear & on_opp
        )
        _counter_accepted = (
            self._counter_rally_accepted
            if self._counter_rally_enabled
            else None
        )
        _motion = self._motion()
        _bucket_metrics = self._metric_bucket_accounting_enabled(_motion)
        _fam = (
            self._metric_bucket_rows()[_motion.clip_id]
            if _bucket_metrics
            else None
        )
        _vb_bucket_values = self._vb_book_strike_step(
            decay,
            exact_strike,
            gate,
            net_clear,
            land["land_valid"],
            _legal,
            contact_rejections=contact_rejections,
            counter_rally_accepted=_counter_accepted,
            metric_bucket_families=_fam,
        )
        enough_e = self._vb_exact_acc >= float(self.cfg.exact_success_min_count)
        enough_h = self._vb_hit_acc >= 1.0
        self.metrics["virtual_hit_rate"][:] = (self._vb_hit_acc / max(self._vb_exact_acc, 1e-6)) if enough_e else 0.0
        self.metrics["virtual_net_clear_rate"][:] = (self._vb_net_acc / max(self._vb_hit_acc, 1e-6)) if enough_h else 0.0
        self.metrics["virtual_land_valid_rate"][:] = (
            (self._vb_land_valid_acc / max(self._vb_hit_acc, 1e-6)) if enough_h else 0.0
        )
        self.metrics["virtual_land_inbounds_rate"][:] = (
            (self._vb_inb_acc / max(self._vb_hit_acc, 1e-6)) if enough_h else 0.0
        )
        # PRIMARY in-training curve (franco 2026-07-06): 上台率 per strike OPPORTUNITY — legal
        # returns (captured hit & net cleared & landed on the opponent half) over EXACT-STRIKE
        # samples. Composes hit-rate x land-rate, so "hit rarely but land those" cannot inflate
        # it the way virtual_land_inbounds_rate (hit-denominator) can. 击球率 = virtual_hit_rate
        # stays the auxiliary; strike_composite is diagnostics. Canonical bookkeeping = MuJoCo.
        self.metrics["virtual_return_rate"][:] = (
            (self._vb_inb_acc / max(self._vb_exact_acc, 1e-6)) if enough_e else 0.0
        )
        # CONTINUOUS-RALLY return rate (franco 2026-07-08 长期追踪): legal returns per swing —
        # falls and never-reached-strike swings count as failures. The trusted curve
        # (virtual_return_rate_rally*) is now computed in _update_metrics from the per-swing
        # SAME-LEDGER counters (metric-sync fix; see the rally block in __init__ and
        # _rally_report). The OLD mixed-ledger readout survives one transition period as *_legacy
        # (written after the per-clip accumulator updates below — the old write points, strike-
        # carrying steps only, frozen between strikes — so it reproduces the old readings exactly
        # for new/old comparison). Its known disease: >1 spikes under synchronized reset queues.
        # Per-side (forehand/backhand) return rate — 反手先行 judging needs the per-side number.
        if _bucket_metrics:
            for _c, _cn in self._clip_names.items():
                (
                    _bucket_exact,
                    _bucket_inb,
                    _bucket_hit,
                ) = _vb_bucket_values[_c]
                if self._action_ball_diagnostic_device_telemetry_enabled():
                    for attribute, increment in (
                        ("_vb_exact_acc_c", _bucket_exact),
                        ("_vb_inb_acc_c", _bucket_inb),
                        ("_vb_hit_acc_c", _bucket_hit),
                    ):
                        values = getattr(self, attribute)
                        values[_c] = decay * values[_c]
                        self._action_ball_diagnostic_device_telemetry_recur(
                            "vb",
                            (attribute, _c),
                            decay,
                            increment,
                        )
                else:
                    self._vb_exact_acc_c[_c] = (
                        decay * self._vb_exact_acc_c[_c] + _bucket_exact
                    )
                    self._vb_inb_acc_c[_c] = (
                        decay * self._vb_inb_acc_c[_c] + _bucket_inb
                    )
                    self._vb_hit_acc_c[_c] = (
                        decay * self._vb_hit_acc_c[_c] + _bucket_hit
                    )
                _n = self._vb_exact_acc_c[_c]
                _scale = (1.0 / max(_n, 1e-6)) if _n >= float(self.cfg.exact_success_min_count) else 0.0
                self.metrics[f"virtual_return_rate_{_cn}"][:] = self._vb_inb_acc_c[_c] * _scale
                self.metrics[f"virtual_hit_rate_{_cn}"][:] = self._vb_hit_acc_c[_c] * _scale
        if self.cfg.rally_legacy_metrics:
            _lg_global, _lg_per_clip = self._rally_legacy_values()
            self.metrics["virtual_return_rate_rally_legacy"][:] = _lg_global
            if _bucket_metrics:
                for _cn in self._clip_names.values():
                    self.metrics[f"virtual_return_rate_rally_{_cn}_legacy"][:] = _lg_per_clip[_cn]
        self.metrics["virtual_approach_speed"] = torch.where(
            exact_strike,
            torch.where(
                torch.isfinite(approach),
                approach,
                torch.zeros_like(approach),
            ),
            self.metrics["virtual_approach_speed"],
        )
        fired_valid = gate & land["land_valid"]
        # Keep this hot path entirely on device.  The former ``bool(any())`` branch forced one
        # CUDA -> host synchronization on every strike-carrying control step.  Mask before the
        # reductions (instead of multiplying by 0) so a rejected row containing NaN/Inf cannot
        # contaminate an otherwise finite selected mean.  With no valid fired row, ``where`` keeps
        # both held metrics exactly as the old branch did.
        fired_valid_count = fired_valid.sum()
        fired_valid_denom = fired_valid_count.clamp_min(1).to(
            dtype=land["land_xy"].dtype
        )
        derr = torch.linalg.norm(
            land["land_xy"] - self._vb_target_xy_per_env, dim=-1
        )
        fired_land_err_mean = torch.where(
            fired_valid,
            derr,
            torch.zeros_like(derr),
        ).sum() / fired_valid_denom
        fired_topspin_revs_mean = torch.where(
            fired_valid,
            topspin / (2.0 * math.pi),
            torch.zeros_like(topspin),
        ).sum() / fired_valid_denom
        has_fired_valid = fired_valid_count > 0
        self.metrics["virtual_land_err_m"][:] = torch.where(
            has_fired_valid,
            fired_land_err_mean,
            self.metrics["virtual_land_err_m"],
        )
        self.metrics["virtual_topspin_revs"][:] = torch.where(
            has_fired_valid,
            fired_topspin_revs_mean,
            self.metrics["virtual_topspin_revs"],
        )
        if current_angular_velocity is not None:
            self._action_ball_store_virtual_contact_history(
                current_angular_velocity,
            )
        return prefetched_host_scalars

    def _vb_book_strike_step(
        self,
        decay: float,
        exact_strike: torch.Tensor,
        gate: torch.Tensor,
        net_clear: torch.Tensor,
        land_valid: torch.Tensor,
        legal: torch.Tensor,
        contact_rejections: dict[str, torch.Tensor] | None = None,
        counter_rally_accepted: torch.Tensor | None = None,
        metric_bucket_families: torch.Tensor | None = None,
    ) -> dict[
        int,
        tuple[
            float | torch.Tensor,
            float | torch.Tensor,
            float | torch.Tensor,
        ],
    ]:
        """EMA booking for THIS strike-carrying step's virtual-ball outcomes + the rally latch.

        Only reached on strike-carrying steps (_vb_evaluate returns early otherwise), so these
        accumulators skip decay on strike-free steps — that schedule asymmetry vs the every-step
        _decay_swing_accounting is one half of the legacy rally disease (the other half is the
        ~1-swing booking phase lag vs _swing_starts_acc). The rally latch on the last line is the
        metric-sync FIX's booking point: it only marks "this swing produced a legal return";
        the actual ledger entry happens at the swing's end in _count_swing_starts.
        """
        bucket_order = (
            tuple(self._clip_names)
            if metric_bucket_families is not None
            else ()
        )
        metric_tensors = [
            exact_strike.sum(dtype=torch.float32),
            gate.sum(dtype=torch.float32),
            (gate & net_clear).sum(dtype=torch.float32),
            (gate & land_valid).sum(dtype=torch.float32),
            legal.sum(dtype=torch.float32),
        ]
        for bucket in bucket_order:
            selected = exact_strike & (
                metric_bucket_families == bucket
            )
            metric_tensors.extend(
                (
                    selected.sum(dtype=torch.float32),
                    (legal & selected).sum(dtype=torch.float32),
                    (gate & selected).sum(dtype=torch.float32),
                )
            )
        diagnostic_device_telemetry = (
            self._action_ball_diagnostic_device_telemetry_enabled()
        )
        if diagnostic_device_telemetry:
            global_targets = (
                ("_vb_exact_acc", None),
                ("_vb_hit_acc", None),
                ("_vb_net_acc", None),
                ("_vb_land_valid_acc", None),
                ("_vb_inb_acc", None),
            )
            for target, increment in zip(
                global_targets,
                metric_tensors[:5],
            ):
                attribute, _ = target
                setattr(
                    self,
                    attribute,
                    float(decay) * getattr(self, attribute),
                )
                self._action_ball_diagnostic_device_telemetry_recur(
                    "vb",
                    target,
                    decay,
                    increment,
                )
            bucket_values = {
                bucket: tuple(
                    metric_tensors[
                        5 + 3 * index:
                        5 + 3 * (index + 1)
                    ]
                )
                for index, bucket in enumerate(bucket_order)
            }
        else:
            metric_values = iter(
                _batched_host_scalar_values(metric_tensors)
            )
            self._vb_exact_acc = (
                decay * self._vb_exact_acc + next(metric_values)
            )
            self._vb_hit_acc = (
                decay * self._vb_hit_acc + next(metric_values)
            )
            self._vb_net_acc = (
                decay * self._vb_net_acc + next(metric_values)
            )
            self._vb_land_valid_acc = (
                decay * self._vb_land_valid_acc + next(metric_values)
            )
            self._vb_inb_acc = (
                decay * self._vb_inb_acc + next(metric_values)
            )
            bucket_values = {
                bucket: tuple(next(metric_values) for _ in range(3))
                for bucket in bucket_order
            }
        self._book_sparse_reward_eligibility(
            exact_strike=exact_strike,
            capture=gate,
            net_clear=gate & net_clear,
            landing_valid=gate & land_valid,
            legal_return=legal,
            book_strike_opportunity=False,
            contact_rejections=contact_rejections,
            counter_rally_accepted=counter_rally_accepted,
        )
        # Rally latch with a wrap-boundary guard: on the step a clip WRAPS, the motion term has
        # already advanced to the NEW clip before this metrics pass, so a strike frame sitting at
        # the swing's entry (strike phase ~0, or rsi_skip_settle_frames landing on the strike
        # offset) fires exact_strike for the NEW attempt while the OLD attempt is still unbooked
        # (_count_swing_starts only runs later, inside _update_command). Latching such a return
        # into _rally_returned would credit it to the OLD rally (cross-rally leakage) AND lose it
        # for the new one. Park it in _rally_pending_return instead; _count_swing_starts books the
        # ended attempt first, then hands the parked latch to the attempt that owns it. Current
        # clips strike mid-swing (phase 0.28-0.50) and never fire at the wrap step — defensive.
        wrapped = getattr(self._motion(), "just_resampled", None)
        if wrapped is None:
            self._rally_returned = self._rally_returned | legal
        else:
            self._rally_returned = self._rally_returned | (legal & ~wrapped)
            self._rally_pending_return = self._rally_pending_return | (legal & wrapped)
        if self._action_ball_enabled:
            # ``gate`` is the actual swept contact against the face selected by
            # this attempt's mounted rubber sign.  Latch it for the whole
            # attempt: a later early terminal/reset must still close one H/C
            # fact, while hidden RESET_WAIT tasks remain outside both.
            hit = gate & self._action_ball_attempt_active
            if self._action_ball_task_wait_schedule is not None:
                hit = hit & self._action_ball_task_valid
            self._action_ball_attempt_hit |= hit
            # The immutable task is graded exactly once at its strike opportunity, then closed at
            # the next wrap/reset.  Ordinary ActionBall grades a legal first landing; exact N=1
            # counter-rally keeps its stricter objective acceptance as the curriculum outcome even
            # though the published virtual-return metrics above retain their narrower landing
            # meaning.
            if counter_rally_accepted is None:
                accepted = legal & self._action_ball_attempt_active
            else:
                accepted = (
                    counter_rally_accepted
                    & self._action_ball_attempt_active
                )
            if self._action_ball_task_wait_schedule is not None:
                accepted = accepted & self._action_ball_task_valid
            self._action_ball_attempt_legal |= accepted
        return bucket_values

    def _book_sparse_reward_eligibility(
        self,
        *,
        exact_strike: torch.Tensor,
        capture: torch.Tensor,
        net_clear: torch.Tensor,
        landing_valid: torch.Tensor,
        legal_return: torch.Tensor,
        book_strike_opportunity: bool = True,
        contact_rejections: dict[str, torch.Tensor] | None = None,
        counter_rally_accepted: torch.Tensor | None = None,
    ) -> None:
        """Book exact, non-decayed sparse-reward counters for one simulator step."""

        task_valid = getattr(self, "_action_ball_task_valid", None)
        if task_valid is not None:
            if task_valid.dtype != torch.bool or task_valid.shape != exact_strike.shape:
                raise RuntimeError(
                    "ActionBall sparse eligibility requires task_valid [num_envs] bool"
                )
            exact_strike = exact_strike & task_valid
            capture = capture & task_valid
            net_clear = net_clear & task_valid
            landing_valid = landing_valid & task_valid
            legal_return = legal_return & task_valid
            if counter_rally_accepted is not None:
                counter_rally_accepted = counter_rally_accepted & task_valid
            if contact_rejections is not None:
                contact_rejections = {
                    name: mask & task_valid
                    for name, mask in contact_rejections.items()
                }

        async_validate = bool(
            getattr(
                self,
                "_action_ball_diagnostic_unauthorized",
                False,
            )
        )
        masks = {
            "virtual_capture_count": capture,
            "virtual_net_clear_count": net_clear,
            "virtual_landing_valid_count": landing_valid,
            "virtual_legal_return_count": legal_return,
        }
        if counter_rally_accepted is not None:
            if (
                counter_rally_accepted.dtype != torch.bool
                or counter_rally_accepted.shape != exact_strike.shape
            ):
                raise ValueError(
                    "counter_rally_accepted_count must be a per-env boolean mask"
                )
            _action_ball_validate_tensor_predicate(
                ~(counter_rally_accepted & ~legal_return),
                "counter-rally acceptance cannot occur without a legal "
                "first opponent-table landing",
                async_validate=async_validate,
            )
            masks["counter_rally_accepted_count"] = (
                counter_rally_accepted
            )
        if contact_rejections is not None:
            if tuple(contact_rejections) != (
                _ACTION_BALL_CONTACT_REJECTION_COUNTERS
            ):
                raise ValueError(
                    "ActionBall contact rejection counter schema mismatch"
                )
            partition = capture.clone()
            for name, mask in contact_rejections.items():
                if mask.dtype != torch.bool or mask.shape != exact_strike.shape:
                    raise ValueError(
                        f"{name} must be a per-env boolean mask"
                    )
                _action_ball_validate_tensor_predicate(
                    ~(partition & mask),
                    "ActionBall capture/rejection ledger overlaps",
                    async_validate=async_validate,
                )
                partition |= mask
            _action_ball_validate_tensor_predicate(
                partition == exact_strike,
                "ActionBall capture/rejection ledger does not conserve "
                "the exact-strike denominator",
                async_validate=async_validate,
            )
            masks.update(contact_rejections)
        if book_strike_opportunity:
            # Exact strike is a timing tick, not an attempted-ball or hit
            # denominator.  Keep the historical key as a compatibility alias
            # for existing A-side receipts; new evidence must use the explicit
            # timing name or the transactional ActionBall H/C ledger.
            masks = {
                _EXACT_STRIKE_TIMING_COUNTER: exact_strike,
                "strike_opportunity_count": exact_strike,
                **masks,
            }
        ledger = getattr(self, "_sparse_reward_eligibility_counters", None)
        if ledger is None:
            names = (
                _EXACT_STRIKE_TIMING_COUNTER,
                "strike_opportunity_count",
                "virtual_capture_count",
                "virtual_net_clear_count",
                "virtual_landing_valid_count",
                "virtual_legal_return_count",
                *_ACTION_BALL_CONTACT_REJECTION_COUNTERS,
            )
            ledger = {name: torch.zeros((), dtype=torch.long, device=self.device) for name in names}
            for family in self._clip_names.values():
                for name in names:
                    ledger[f"{name}_{family}"] = torch.zeros(
                        (), dtype=torch.long, device=self.device
                    )
            self._sparse_reward_eligibility_counters = ledger
        for name, mask in masks.items():
            if mask.dtype != torch.bool or mask.shape != exact_strike.shape:
                raise ValueError(
                    f"{name} must be a per-env boolean mask"
                )
            if name not in ledger:
                ledger[name] = torch.zeros(
                    (), dtype=torch.long, device=mask.device
                )
                for family in self._clip_names.values():
                    ledger[f"{name}_{family}"] = torch.zeros(
                        (), dtype=torch.long, device=mask.device
                    )
            ledger[name].add_(mask.detach().sum(dtype=torch.long))

        self._book_exact_timing_bucket_sparse_events(masks)

        motion = self._motion()
        if self._metric_bucket_accounting_enabled(motion):
            fam_id = self._metric_bucket_rows()[motion.clip_id]
            for family_row, family in self._clip_names.items():
                selected = fam_id == family_row
                for name, mask in masks.items():
                    ledger[f"{name}_{family}"].add_(
                        (mask.detach() & selected).sum(dtype=torch.long)
                    )

    def consume_sparse_reward_eligibility_counters(self) -> dict[str, torch.Tensor]:
        """Snapshot and reset one PPO update's sparse outcome ledger exactly once."""

        if not hasattr(self, "_sparse_reward_eligibility_counters"):
            empty = torch.zeros(self.num_envs, dtype=torch.bool, device=self.device)
            self._book_sparse_reward_eligibility(
                exact_strike=empty,
                capture=empty,
                net_clear=empty,
                landing_valid=empty,
                legal_return=empty,
            )

        snapshot = {
            name: value.detach().clone()
            for name, value in self._sparse_reward_eligibility_counters.items()
        }
        # Reward/command updates can allocate these under inference mode.  Reset under the same
        # mode so the logger never mutates an inference tensor from normal mode.
        with torch.inference_mode():
            for value in self._sparse_reward_eligibility_counters.values():
                value.zero_()
        return snapshot

    def _ensure_strike_window_entry_distance_probe_state(self) -> None:
        """Lazily allocate the diagnostic latch for host-only fixtures and old objects."""

        armed = getattr(self, "_strike_window_entry_armed", None)
        if armed is None:
            # A host-only fixture or an older restored object can first touch this seam from an
            # inference-mode metrics pass.  Allocate a normal tensor deliberately so the later
            # exact-resume loader (normal mode) may restore it without crossing tensor modes.
            with torch.inference_mode(False):
                self._strike_window_entry_armed = torch.ones(
                    self.num_envs, dtype=torch.bool, device=self.device
                )
        elif armed.dtype != torch.bool or tuple(armed.shape) != (self.num_envs,):
            raise RuntimeError(
                "strike-window entry latch must be one boolean per environment"
            )
        edges = getattr(
            self, "_strike_window_entry_distance_bin_edges_m", None
        )
        if edges is None:
            with torch.inference_mode(False):
                self._strike_window_entry_distance_bin_edges_m = torch.tensor(
                    _STRIKE_WINDOW_ENTRY_DISTANCE_BIN_EDGES_M,
                    dtype=torch.float32,
                    device=self.device,
                )
        elif (
            not isinstance(edges, torch.Tensor)
            or tuple(edges.shape)
            != (len(_STRIKE_WINDOW_ENTRY_DISTANCE_BIN_EDGES_M),)
        ):
            raise RuntimeError(
                "strike-window entry distance bin edge tensor has invalid shape"
            )

    def _rearm_strike_window_entry_distance_probe(
        self, env_ids: torch.Tensor
    ) -> None:
        """Rearm exactly the environments receiving a true-reset or wrap target."""

        self._ensure_strike_window_entry_distance_probe_state()
        ids = torch.as_tensor(
            env_ids, dtype=torch.long, device=self.device
        ).reshape(-1)
        self._strike_window_entry_armed[ids] = True

    def _book_strike_window_entry_distance_probe(
        self,
        in_window: torch.Tensor,
        racket_target_distance: torch.Tensor,
    ) -> None:
        """Book one exact distance histogram row at each swing's window entry.

        All operations stay on device until the existing once-per-PPO-update ledger consume.
        The finite bins plus the explicit non-finite counter conserve the entry denominator.
        """

        self._ensure_strike_window_entry_distance_probe_state()
        if (
            not isinstance(in_window, torch.Tensor)
            or in_window.dtype != torch.bool
            or tuple(in_window.shape) != (self.num_envs,)
        ):
            raise ValueError(
                "strike-window entry probe requires one boolean window bit per environment"
            )
        if (
            not isinstance(racket_target_distance, torch.Tensor)
            or tuple(racket_target_distance.shape) != (self.num_envs,)
            or not racket_target_distance.dtype.is_floating_point
        ):
            raise ValueError(
                "strike-window entry probe requires one floating distance per environment"
            )
        entry = in_window.detach() & self._strike_window_entry_armed
        distance = racket_target_distance.detach()
        finite_entry = entry & torch.isfinite(distance)
        bucket_ids = torch.bucketize(
            distance,
            self._strike_window_entry_distance_bin_edges_m.to(
                dtype=distance.dtype
            ),
            right=False,
        )
        ledger = self._ensure_exact_behavior_decision_counters()
        ledger[_STRIKE_WINDOW_ENTRY_DISTANCE_COUNT].add_(
            entry.sum(dtype=torch.long)
        )
        ledger[_STRIKE_WINDOW_ENTRY_DISTANCE_SUM].add_(
            torch.where(
                finite_entry,
                distance.to(dtype=torch.float64),
                torch.zeros_like(distance, dtype=torch.float64),
            ).sum(dtype=torch.float64)
        )
        ledger[_STRIKE_WINDOW_ENTRY_DISTANCE_NONFINITE_COUNT].add_(
            (entry & ~torch.isfinite(distance)).sum(dtype=torch.long)
        )
        for bucket_id, counter_name in enumerate(
            _STRIKE_WINDOW_ENTRY_DISTANCE_BUCKET_COUNTERS
        ):
            ledger[counter_name].add_(
                (finite_entry & (bucket_ids == bucket_id)).sum(
                    dtype=torch.long
                )
            )
        self._strike_window_entry_armed[entry] = False

    def _strike_window_entry_distance_probe_exact_state(self) -> list[bool]:
        """Return the per-env diagnostic latch in JSON-canonical form."""

        self._ensure_strike_window_entry_distance_probe_state()
        return [
            bool(value)
            for value in self._strike_window_entry_armed.detach().cpu().tolist()
        ]

    def _stage_strike_window_entry_distance_probe_exact_state(
        self, value: object
    ) -> torch.Tensor:
        """Strictly validate a checkpoint latch without mutating live state."""

        if (
            not isinstance(value, list)
            or len(value) != self.num_envs
            or any(type(item) is not bool for item in value)
        ):
            raise ValueError(
                "action-ball env_state.strike_window_entry_armed must contain "
                "one boolean per environment"
            )
        return torch.tensor(value, dtype=torch.bool, device=self.device)

    def configure_table_guard_attribution(
        self,
        *,
        component_ids: tuple[str, ...],
        component_owner_names: tuple[str, ...],
        obstacle_roles: tuple[str, ...],
    ) -> None:
        """Install the diagnostic-only first-hit ledger once per run.

        Component indices are the canonical order of the SHA-pinned collision
        artifact.  Keeping one dense device tensor avoids thousands of scalar
        tensors in the physics path; the PPO-boundary consumer expands only
        non-zero cells into ordinary exact-behavior counters.
        """

        # Read the count from the guard that owns the pin instead of keeping a
        # second copy of it here; deferred so module import order is untouched.
        from whole_body_tracking.tasks.tracking.mdp.terminations import (
            _A3_COLLISION_PROXY_COMPONENT_COUNT as A3_TABLE_GUARD_COMPONENT_COUNT,
        )

        component_ids = tuple(component_ids)
        component_owner_names = tuple(component_owner_names)
        obstacle_roles = tuple(obstacle_roles)
        if (
            len(component_ids) != A3_TABLE_GUARD_COMPONENT_COUNT
            or len(component_owner_names) != len(component_ids)
            or len(set(component_ids)) != len(component_ids)
            or any(not isinstance(value, str) or not value for value in component_ids)
            or any(
                not isinstance(value, str) or not value
                for value in component_owner_names
            )
            or obstacle_roles
            != ("top", "keepout", "net", "post_left", "post_right")
        ):
            raise RuntimeError(
                "table-guard attribution requires "
                f"{A3_TABLE_GUARD_COMPONENT_COUNT} pinned components and five "
                "ordered obstacles"
            )
        schema = (component_ids, component_owner_names, obstacle_roles)
        existing = getattr(self, "_table_guard_attribution_schema", None)
        if existing is not None:
            if existing != schema:
                raise RuntimeError(
                    "table-guard attribution schema changed during one run"
                )
            return
        self._table_guard_attribution_schema = schema
        # Item rows: 0..N-1 proxy components, N independent blade, N+1 non-finite.
        self._table_guard_attribution_counts = torch.zeros(
            (
                len(_TABLE_GUARD_ATTRIBUTION_PHASES),
                len(_TABLE_GUARD_ATTRIBUTION_CATEGORIES),
                len(component_ids) + 2,
                len(obstacle_roles),
            ),
            dtype=torch.long,
            device=self.device,
        )

    def configure_table_guard_oracle_first_hit_export(self) -> None:
        """Enable the single-env, diagnostic-only table first-hit export.

        This is deliberately a sidecar to the dense PPO ledger: it is enabled
        only by the teacher-q_des oracle after the normal attribution schema is
        installed.  It stores Python/JSON rows for a finite diagnostic and is
        never read by terminal, reward, observation, sampler, or RNG code.
        """

        if self.num_envs != 1:
            raise RuntimeError(
                "table-guard oracle first-hit export requires num_envs=1"
            )
        if getattr(self, "_table_guard_attribution_schema", None) is None:
            raise RuntimeError(
                "table-guard oracle first-hit export requires configured attribution"
            )
        if getattr(self, "_table_guard_oracle_first_hit_export_enabled", False):
            return
        self._table_guard_oracle_first_hit_export_enabled = True
        self._table_guard_oracle_first_hit_context = None
        self._table_guard_oracle_first_hit_rows = []

    def set_table_guard_oracle_first_hit_context(
        self, *, episode: int, control_step: int
    ) -> None:
        """Attach oracle-owned control coordinates to the next physics record."""

        if not getattr(self, "_table_guard_oracle_first_hit_export_enabled", False):
            raise RuntimeError("table-guard oracle first-hit export is not enabled")
        if (
            type(episode) is not int
            or episode < 0
            or type(control_step) is not int
            or control_step <= 0
        ):
            raise RuntimeError(
                "table-guard oracle first-hit context requires non-negative "
                "episode and positive control_step integers"
            )
        self._table_guard_oracle_first_hit_context = {
            "episode": episode,
            "control_step": control_step,
        }

    def _table_guard_oracle_actual_pose(
        self, *, body_name: str | None, env_index: int
    ) -> tuple[dict | None, str | None]:
        """Snapshot the selected owner's world pose, or state why it is absent."""

        if body_name is None:
            return None, "nonfinite attribution has no trustworthy owner-body pose"
        try:
            body_index = list(self.robot.body_names).index(body_name)
            pos = self.robot.data.body_pos_w[env_index, body_index]
            quat = self.robot.data.body_quat_w[env_index, body_index]
            if not bool(torch.isfinite(pos).all().item()) or not bool(
                torch.isfinite(quat).all().item()
            ):
                return None, "selected owner-body pose is non-finite"
            return {
                "position_w_m": [float(value) for value in pos.detach().cpu().tolist()],
                "quaternion_wxyz": [
                    float(value) for value in quat.detach().cpu().tolist()
                ],
            }, None
        except (AttributeError, ValueError, IndexError, TypeError):
            return None, "selected owner-body pose is unavailable from the command robot"

    def _table_guard_oracle_motion_frame(
        self, env_index: int
    ) -> tuple[int | None, str | None]:
        """Read the live motion frame without making it a terminal input."""

        try:
            return int(self._motion().time_steps[env_index].detach().item()), None
        except (AttributeError, IndexError, TypeError):
            return None, "motion frame is unavailable from the command motion clock"

    def _record_table_guard_oracle_first_hits(
        self,
        *,
        first_hit_mask: torch.Tensor,
        phase: torch.Tensor,
        category: torch.Tensor,
        item: torch.Tensor,
        obstacle: torch.Tensor,
        component_ids: tuple[str, ...],
        owner_names: tuple[str, ...],
        obstacle_roles: tuple[str, ...],
    ) -> None:
        """Copy finite-oracle first hits after their unchanged ledger booking.

        The existing action hook does not expose its physics-substep ordinal to
        the command recorder.  Report that coordinate as explicitly unavailable
        rather than infer one from the control-step timing.
        """

        if not getattr(self, "_table_guard_oracle_first_hit_export_enabled", False):
            return
        context = getattr(self, "_table_guard_oracle_first_hit_context", None)
        if not isinstance(context, dict):
            raise RuntimeError(
                "table-guard oracle first hit has no control-step context"
            )
        hit_indices = torch.nonzero(first_hit_mask, as_tuple=False).detach().cpu()
        if hit_indices.numel() == 0:
            return
        if tuple(hit_indices.shape) != (1, 1):
            raise RuntimeError(
                "single-env table-guard oracle recorded more than one first hit"
            )
        env_index = int(hit_indices[0, 0].item())
        component_count = len(component_ids)
        category_index = int(category[env_index].detach().item())
        item_index = int(item[env_index].detach().item())
        obstacle_index = int(obstacle[env_index].detach().item())
        phase_index = int(phase[env_index].detach().item())
        if item_index < component_count:
            component_id = component_ids[item_index]
            body_name = owner_names[item_index]
            source = "collision_proxy_component"
        elif item_index == component_count:
            component_id = None
            body_name = str(getattr(self.cfg, "racket_body_name", "")) or None
            source = "independent_blade"
        else:
            component_id = None
            body_name = None
            source = "nonfinite_pose"
        pose, pose_unavailable_reason = self._table_guard_oracle_actual_pose(
            body_name=body_name, env_index=env_index
        )
        motion_frame, motion_frame_unavailable_reason = (
            self._table_guard_oracle_motion_frame(env_index)
        )
        self._table_guard_oracle_first_hit_rows.append(
            {
                "episode": context["episode"],
                "control_step": context["control_step"],
                "physics_substep": None,
                "physics_substep_unavailable_reason": (
                    "the existing action-to-command ledger interface does not "
                    "expose a physics-substep ordinal"
                ),
                "motion_frame": motion_frame,
                "motion_frame_unavailable_reason": motion_frame_unavailable_reason,
                "phase": _TABLE_GUARD_ATTRIBUTION_PHASES[phase_index],
                "component_id": component_id,
                "body_name": body_name,
                "obstacle": (
                    "not_applicable"
                    if source == "nonfinite_pose"
                    else obstacle_roles[obstacle_index]
                ),
                "blade_or_proxy": source,
                "exact_vs_conservative": _TABLE_GUARD_ATTRIBUTION_CATEGORIES[
                    category_index
                ],
                "actual_pose_w": pose,
                "actual_pose_unavailable_reason": pose_unavailable_reason,
            }
        )

    def consume_table_guard_oracle_first_hit_rows(self) -> list[dict]:
        """Return-and-clear the finite oracle sidecar without touching the PPO ledger."""

        if not getattr(self, "_table_guard_oracle_first_hit_export_enabled", False):
            raise RuntimeError("table-guard oracle first-hit export is not enabled")
        rows = list(self._table_guard_oracle_first_hit_rows)
        self._table_guard_oracle_first_hit_rows.clear()
        return rows

    @staticmethod
    def _table_guard_assert_device(
        condition: torch.Tensor, message: str
    ) -> None:
        if condition.device.type == "cpu":
            if not bool(condition):
                raise RuntimeError(message)
        else:
            torch._assert_async(condition)

    def record_table_guard_first_hits(
        self,
        first_hit_mask: torch.Tensor,
        attribution,
    ) -> None:
        """Book exactly one body/component, obstacle, class and phase per first hit.

        The action substep latch owns the definition of ``first``.  This method
        merely attributes its newly-positive rows; it cannot change a terminal,
        reward, observation, sampler or RNG state.
        """

        schema = getattr(self, "_table_guard_attribution_schema", None)
        counts = getattr(self, "_table_guard_attribution_counts", None)
        if schema is None or not torch.is_tensor(counts):
            raise RuntimeError("table-guard attribution ledger is not configured")
        component_ids, _owner_names, obstacle_roles = schema
        env_count = self.num_envs
        component_count = len(component_ids)
        obstacle_count = len(obstacle_roles)
        expected_component_shape = (
            env_count,
            component_count,
            obstacle_count,
        )
        expected_blade_shape = (env_count, obstacle_count)
        tensors = {
            "legacy_mask": attribution.legacy_mask,
            "component_conservative_overlap": (
                attribution.component_conservative_overlap
            ),
            "component_exact_overlap": attribution.component_exact_overlap,
            "blade_conservative_overlap": (
                attribution.blade_conservative_overlap
            ),
            "blade_exact_overlap": attribution.blade_exact_overlap,
            "nonfinite": attribution.nonfinite,
        }
        if (
            not torch.is_tensor(first_hit_mask)
            or tuple(first_hit_mask.shape) != (env_count,)
            or first_hit_mask.dtype != torch.bool
            or first_hit_mask.device != counts.device
        ):
            raise RuntimeError(
                "table-guard first-hit mask must be same-device bool [num_envs]"
            )
        for name, value in tensors.items():
            expected_shape = (
                expected_component_shape
                if name.startswith("component_")
                else expected_blade_shape
                if name.startswith("blade_")
                else (env_count,)
            )
            if (
                not torch.is_tensor(value)
                or tuple(value.shape) != expected_shape
                or value.dtype != torch.bool
                or value.device != counts.device
            ):
                raise RuntimeError(
                    f"table-guard attribution {name} has malformed bool shape/device"
                )
        self._table_guard_assert_device(
            torch.all(
                attribution.component_exact_overlap
                <= attribution.component_conservative_overlap
            )
            & torch.all(
                attribution.blade_exact_overlap
                <= attribution.blade_conservative_overlap
            )
            & torch.all(first_hit_mask <= attribution.legacy_mask),
            "table-guard attribution violates exact⊆broad or first⊆terminal",
        )

        category = torch.full(
            (env_count,), -1, dtype=torch.long, device=self.device
        )
        item = torch.full_like(category, -1)
        obstacle = torch.full_like(category, -1)
        pending = first_hit_mask.clone()

        def select_pair(
            candidate: torch.Tensor,
            *,
            category_index: int,
            blade: bool,
        ) -> None:
            nonlocal pending
            flat = candidate.reshape(env_count, -1)
            has = torch.any(flat, dim=1)
            selected = pending & has
            first = torch.argmax(flat.to(dtype=torch.long), dim=1)
            category[selected] = category_index
            if blade:
                item[selected] = component_count
                obstacle[selected] = first[selected]
            else:
                item[selected] = first[selected] // obstacle_count
                obstacle[selected] = first[selected] % obstacle_count
            pending &= ~selected

        # Broken pose data is a fail-safe terminal, not geometry. Among valid
        # rows the terminal is exact OBB-vs-AABB evidence; the independent
        # blade precedes proxy components when both overlap.
        nonfinite = pending & attribution.nonfinite
        category[nonfinite] = 2
        item[nonfinite] = component_count + 1
        obstacle[nonfinite] = 0  # not-applicable sentinel, never named as top
        pending &= ~nonfinite
        select_pair(
            attribution.blade_exact_overlap,
            category_index=1,
            blade=True,
        )
        select_pair(
            attribution.component_exact_overlap,
            category_index=0,
            blade=False,
        )
        self._table_guard_assert_device(
            torch.all(~pending)
            & torch.all((~first_hit_mask) | (category >= 0)),
            "table-guard first-hit ledger could not attribute every terminal row",
        )

        recovery = self._recover_from_clip >= 0
        strike = self.strike_window & ~recovery
        pre = self.pre_strike & ~strike & ~recovery
        post = ~(recovery | strike | pre)
        phase_masks = torch.stack((pre, strike, post, recovery), dim=1)
        self._table_guard_assert_device(
            torch.all(torch.sum(phase_masks, dim=1) == 1),
            "table-guard attribution phases do not partition environments",
        )
        phase = torch.argmax(phase_masks.to(dtype=torch.long), dim=1)
        flat_index = (
            (
                phase * len(_TABLE_GUARD_ATTRIBUTION_CATEGORIES)
                + category.clamp_min(0)
            )
            * counts.shape[2]
            + item.clamp_min(0)
        ) * obstacle_count + obstacle.clamp_min(0)
        additions = torch.bincount(
            flat_index[first_hit_mask], minlength=counts.numel()
        ).reshape_as(counts)
        counts.add_(additions)
        self._record_table_guard_oracle_first_hits(
            first_hit_mask=first_hit_mask,
            phase=phase,
            category=category,
            item=item,
            obstacle=obstacle,
            component_ids=component_ids,
            owner_names=_owner_names,
            obstacle_roles=obstacle_roles,
        )

    def _consume_table_guard_attribution_counts(self) -> dict[str, int]:
        """Expand nonzero diagnostic cells at the existing PPO sync boundary."""

        schema = getattr(self, "_table_guard_attribution_schema", None)
        counts = getattr(self, "_table_guard_attribution_counts", None)
        if schema is None or not torch.is_tensor(counts):
            return {}
        component_ids, owner_names, obstacle_roles = schema
        cpu_counts = counts.detach().to(device="cpu")
        snapshot: dict[str, int] = {
            "table_guard_first_hit_total_count": int(cpu_counts.sum().item())
        }
        for phase_index, category_index, item_index, obstacle_index in (
            torch.nonzero(cpu_counts, as_tuple=False).tolist()
        ):
            value = int(
                cpu_counts[
                    phase_index,
                    category_index,
                    item_index,
                    obstacle_index,
                ].item()
            )
            if item_index < len(component_ids):
                item_name = (
                    f"component_{item_index:02d}_{owner_names[item_index]}"
                )
            elif item_index == len(component_ids):
                item_name = "independent_blade"
            else:
                item_name = "nonfinite_pose"
            obstacle_name = (
                "not_applicable"
                if item_index == len(component_ids) + 1
                else obstacle_roles[obstacle_index]
            )
            key = (
                "table_guard_first_hit_cell_"
                f"{_TABLE_GUARD_ATTRIBUTION_PHASES[phase_index]}_"
                f"{_TABLE_GUARD_ATTRIBUTION_CATEGORIES[category_index]}_"
                f"{item_name}_{obstacle_name}_count"
            )
            snapshot[key] = value
        for index, name in enumerate(_TABLE_GUARD_ATTRIBUTION_CATEGORIES):
            snapshot[f"table_guard_first_hit_category_{name}_count"] = int(
                cpu_counts[:, index].sum().item()
            )
        for index, name in enumerate(_TABLE_GUARD_ATTRIBUTION_PHASES):
            snapshot[f"table_guard_first_hit_phase_{name}_count"] = int(
                cpu_counts[index].sum().item()
            )
        # The physics path can create and update this ledger under inference mode.  The PPO
        # logger consumes it from normal mode, where mutating an inference tensor is forbidden.
        # Reset under the tensor's creation mode after the detached CPU snapshot is complete.
        with torch.inference_mode():
            counts.zero_()
        return snapshot

    @staticmethod
    def _validate_table_guard_attribution_conservation(
        behavior_snapshot: dict[str, torch.Tensor],
        attribution: dict[str, int],
    ) -> None:
        """Prove the diagnostic first-hit ledger equals the raw table terminal ledger."""

        if not attribution:
            return
        reason = behavior_snapshot.get(
            "termination_reason_robot_hit_table_count"
        )
        if not torch.is_tensor(reason) or reason.numel() != 1:
            raise RuntimeError(
                "table-guard attribution has no scalar robot_hit_table terminal reason"
            )
        total = attribution.get("table_guard_first_hit_total_count")
        if type(total) is not int:
            raise RuntimeError(
                "table-guard attribution total must be one integer"
            )
        category_total = sum(
            attribution.get(
                f"table_guard_first_hit_category_{name}_count", -1
            )
            for name in _TABLE_GUARD_ATTRIBUTION_CATEGORIES
        )
        phase_total = sum(
            attribution.get(f"table_guard_first_hit_phase_{name}_count", -1)
            for name in _TABLE_GUARD_ATTRIBUTION_PHASES
        )
        cell_total = sum(
            value
            for key, value in attribution.items()
            if key.startswith("table_guard_first_hit_cell_")
        )
        terminal_total = int(reason.detach().item())
        if not (
            total == terminal_total
            and category_total == total
            and phase_total == total
            and cell_total == total
        ):
            raise RuntimeError(
                "table-guard first-hit/category/phase/cell ledgers do not "
                "conserve with robot_hit_table terminals: "
                f"first={total} terminal={terminal_total} "
                f"category={category_total} phase={phase_total} cell={cell_total}"
            )

    def _ensure_exact_behavior_decision_counters(self) -> dict[str, torch.Tensor]:
        """Create the fixed behavior counters and any configured termination-reason counters."""

        ledger = getattr(self, "_exact_behavior_decision_counters", None)
        if ledger is None:
            ledger = {}
            self._exact_behavior_decision_counters = ledger
        for name in (
            "swing_start_count",
            "swing_outcome_count",
            "swing_completion_count",
            "terminal_reset_count",
            "timeout_reset_count",
            "physical_fall_count",
            "pre_strike_physical_fall_count",
            "post_strike_physical_fall_count",
            "non_physical_terminal_reset_count",
            "ready_tilt_eligible_sample_count",
            "ready_base_speed_eligible_sample_count",
            "ready_station_offset_eligible_sample_count",
            "ready_foot_contact_eligible_sample_count",
            "ready_foot_slip_eligible_sample_count",
            "ready_phase_sample_count",
            "ready_planner_task_entry_sample_count",
            "ready_planner_legacy_hold_violation_count",
            "ready_foot_sensor_unavailable_sample_count",
            "ready_nonfinite_value_count",
            _TASK_WAIT_STARTED_COUNTER,
            _TASK_REVEAL_REACHED_COUNTER,
        ):
            if name not in ledger:
                ledger[name] = torch.zeros((), dtype=torch.long, device=self.device)
        if getattr(self, "_action_ball_enabled", False):
            for name in (
                _STRIKE_WINDOW_ENTRY_DISTANCE_COUNT,
                _STRIKE_WINDOW_ENTRY_DISTANCE_NONFINITE_COUNT,
                *_STRIKE_WINDOW_ENTRY_DISTANCE_BUCKET_COUNTERS,
                _EXACT_STRIKE_PADDLE_BALL_DISTANCE_COUNT,
                _EXACT_STRIKE_PADDLE_BALL_DISTANCE_NONFINITE_COUNT,
                *_EXACT_STRIKE_PADDLE_BALL_DISTANCE_BUCKET_COUNTERS,
                "capture_v_plus_finite_count",
                "capture_v_plus_nonfinite_count",
                "capture_w_plus_finite_count",
                "capture_w_plus_nonfinite_count",
                "capture_w_plus_topspin_finite_count",
                "capture_w_plus_topspin_axis_invalid_count",
                "capture_w_plus_topspin_nonfinite_count",
                "capture_landing_xy_finite_count",
                "capture_landing_xy_nonfinite_count",
            ):
                if name not in ledger:
                    ledger[name] = torch.zeros(
                        (), dtype=torch.long, device=self.device
                    )
        if (
            getattr(self, "_action_ball_enabled", False)
            and _reference_guard_mode(
                getattr(
                    self.cfg,
                    "reference_guard_mode",
                    _REFERENCE_GUARD_PHASE_GATED,
                )
            )
            == _REFERENCE_GUARD_METRICS_ONLY
        ):
            from whole_body_tracking.tasks.tracking.mdp.action_ball_reference_guard import (
                REFERENCE_GUARD_COUNTER_NAMES,
            )

            for name in REFERENCE_GUARD_COUNTER_NAMES:
                if name not in ledger:
                    ledger[name] = torch.zeros(
                        (), dtype=torch.long, device=self.device
                    )
        if self._cq_enabled:  # 类级默认 False 兜底,不必再写 getattr
            # CONTINUOUS question accounting. Goes into the SAME integer ledger the hourly monitor
            # already parses (one HOPE_EXACT_BEHAVIOR_UPDATE_JSON line per PPO update), so a target
            # drought is visible without touching a single line of the monitor.
            # continuous_question_exhausted_rate > 0 is THE anomaly to catch.
            for name in (
                "continuous_question_draw_count",
                "continuous_question_admitted_count",
                "continuous_question_install_count",
                "continuous_question_exhausted_count",
                "continuous_question_refill_count",
                "continuous_question_redraw_round_sum",
                "continuous_question_resid_um_sum",
                "continuous_question_rows_discarded_count",
                "continuous_question_pool_dry_count",
                "continuous_question_pool_underflow_count",
                "continuous_question_reject_face_deg_over_cap_count",
                "continuous_question_reject_exam_holdout_count",
                "continuous_question_closed_loop_um_sum",
                "continuous_question_closed_loop_row_count",
                "continuous_question_closed_loop_fail_count",
            ):
                if name not in ledger:
                    ledger[name] = torch.zeros((), dtype=torch.long, device=self.device)
            # Reason names are stroke_adapt_torch.REASONS verbatim, so a training histogram and a
            # deploy stroke_adapt log can be compared directly.
            from .stroke_adapt_torch import REASONS as _CQ_REASONS

            for _reason in _CQ_REASONS:
                name = f"continuous_question_reject_{_reason}_count"
                if name not in ledger:
                    ledger[name] = torch.zeros((), dtype=torch.long, device=self.device)
            _nb = max(1, int(self.cfg.cq_accept_buckets))
            _nc = len(getattr(self, "_clip_names", {})) or 2
            for _c in range(max(_nc, 8)):
                for _b in range(_nb):
                    for _kind in ("asked", "kept"):
                        name = f"continuous_question_bucket{_c}_{_b}_{_kind}_count"
                        if name not in ledger:
                            ledger[name] = torch.zeros((), dtype=torch.long, device=self.device)
        if getattr(self, "planner_revision_enabled", False):
            for name in (
                "planner_initial_tts_sample_count",
                "planner_initial_tts_sub_0p5_count",
                "planner_initial_tts_exact_0p5_count",
                "planner_initial_tts_above_0p5_count",
                "planner_revision_attempt_count",
                "planner_revision_accepted_count",
                "planner_revision_rejected_count",
                "planner_revision_last_precontact_attempt_count",
                "planner_revision_last_precontact_accepted_count",
                "planner_revision_actor_visible_count",
                "planner_revision_last_precontact_actor_visible_count",
            ):
                if name not in ledger:
                    ledger[name] = torch.zeros((), dtype=torch.long, device=self.device)
            for bucket_name in _PLANNER_INITIAL_TTS_BUCKETS:
                for event_name in (
                    "swing_outcome_count",
                    "swing_completion_count",
                    *_TIMING_BUCKET_SPARSE_EVENTS,
                ):
                    name = f"planner_initial_tts_{bucket_name}_{event_name}"
                    if name not in ledger:
                        ledger[name] = torch.zeros(
                            (), dtype=torch.long, device=self.device
                        )
            mixture = getattr(self, "_planner_initial_tts_mixture", None)
            if mixture is not None:
                for index, _component in enumerate(mixture.components):
                    name = f"planner_initial_tts_component_{index}_count"
                    if name not in ledger:
                        ledger[name] = torch.zeros(
                            (), dtype=torch.long, device=self.device
                        )
        for name in (
            "ready_tilt_rad_sum",
            "ready_base_speed_xy_mps_sum",
            "ready_station_offset_m_sum",
            "ready_foot_contact_fraction_sum",
            "ready_foot_slip_speed_mps_sum",
        ):
            if name not in ledger:
                ledger[name] = torch.zeros((), dtype=torch.float64, device=self.device)
        if getattr(self, "_action_ball_enabled", False):
            for name in (
                _STRIKE_WINDOW_ENTRY_DISTANCE_SUM,
                _EXACT_STRIKE_PADDLE_BALL_DISTANCE_SUM,
                _EXACT_STRIKE_PADDLE_BALL_DISTANCE_SUM_SQ,
            ):
                if name not in ledger:
                    ledger[name] = torch.zeros(
                        (), dtype=torch.float64, device=self.device
                    )
            for metric_name in (
                *_CAPTURE_V_PLUS_METRICS,
                *_CAPTURE_W_PLUS_METRICS,
                _CAPTURE_W_PLUS_TOPSPIN_METRIC,
                *_CAPTURE_LANDING_METRICS,
            ):
                for suffix in ("sum", "sum_sq"):
                    name = f"{metric_name}_{suffix}"
                    if name not in ledger:
                        ledger[name] = torch.zeros(
                            (), dtype=torch.float64, device=self.device
                        )

        termination_manager = getattr(self._env, "termination_manager", None)
        for term_name in tuple(getattr(termination_manager, "active_terms", ())):
            key = f"termination_reason_{term_name}_count"
            if key not in ledger:
                ledger[key] = torch.zeros((), dtype=torch.long, device=self.device)
        # These reason totals and reason-by-phase counters are a fixed producer
        # ABI, not a dynamic reflection of the active TerminationManager list.
        # A reason absent from a run therefore emits an explicit zero instead
        # of silently losing schema coverage at the pre-long gate.
        for reason in _BEHAVIORAL_TERMINATION_PHASE_TERMS:
            reason_key = f"termination_reason_{reason}_count"
            if reason_key not in ledger:
                ledger[reason_key] = torch.zeros(
                    (), dtype=torch.long, device=self.device
                )
            for phase in _PHYSICAL_FALL_ATTRIBUTION_PHASES:
                key = f"termination_reason_{reason}_{phase}_count"
                if key not in ledger:
                    ledger[key] = torch.zeros(
                        (), dtype=torch.long, device=self.device
                    )
        return ledger

    @staticmethod
    def _selected_bool(value, env_ids: torch.Tensor) -> torch.Tensor:
        """Select one manager mask without accepting numeric/non-boolean reason tensors."""

        if not isinstance(value, torch.Tensor):
            value = torch.as_tensor(value, device=env_ids.device)
        value = value.to(device=env_ids.device)
        if value.dtype != torch.bool:
            raise TypeError("termination reason masks must have boolean dtype")
        if value.ndim == 0:
            return value.expand(len(env_ids))
        if value.ndim != 1:
            raise ValueError("termination reason masks must be scalar or one-dimensional")
        return value[env_ids]

    def _book_exact_behavior_terminal_reset(
        self,
        env_ids: torch.Tensor,
        *,
        pre_strike: torch.Tensor,
        recovering: torch.Tensor,
    ) -> None:
        """Attribute true-reset reasons; only absolute balance guards are physical falls.

        ``pre_strike`` is the ending attempt's timing latch.  ``recovering`` wins over that latch:
        a fall during a post-wrap hold belongs to the completed swing's post-strike recovery even
        though the next swing already reports pre-strike timing.
        """

        ledger = self._ensure_exact_behavior_decision_counters()
        tm = getattr(self._env, "termination_manager", None)
        if tm is None or len(env_ids) == 0:
            return
        terminated = self._selected_bool(
            getattr(tm, "terminated", torch.zeros((), dtype=torch.bool, device=self.device)),
            env_ids,
        )
        timed_out = self._selected_bool(
            getattr(tm, "time_outs", torch.zeros((), dtype=torch.bool, device=self.device)),
            env_ids,
        )
        selected_phase_masks = {}
        for name, value in (("pre_strike", pre_strike), ("recovering", recovering)):
            if not isinstance(value, torch.Tensor):
                value = torch.as_tensor(value, device=self.device)
            value = value.to(device=self.device)
            if value.dtype != torch.bool:
                raise TypeError(f"{name} attribution mask must have boolean dtype")
            if value.shape != terminated.shape:
                raise ValueError(
                    f"{name} attribution mask shape {tuple(value.shape)} does not match "
                    f"selected terminations {tuple(terminated.shape)}"
                )
            selected_phase_masks[name] = value
        pre_strike = selected_phase_masks["pre_strike"]
        recovering = selected_phase_masks["recovering"]
        task_valid_source = getattr(self, "_action_ball_task_valid", None)
        if task_valid_source is None:
            # Legacy/non-ActionBall callers have no hidden RESET_WAIT.  Treat
            # their whole attempt as publicly revealed so the fixed phase ABI
            # still conserves without inventing a hidden phase.
            task_valid = torch.ones_like(terminated)
        else:
            task_valid = self._selected_bool(task_valid_source, env_ids)
        reason_masks: dict[str, torch.Tensor] = {}
        get_term = getattr(tm, "get_term", None)
        if callable(get_term):
            for term_name in tuple(getattr(tm, "active_terms", ())):
                mask = self._selected_bool(get_term(term_name), env_ids)
                reason_masks[str(term_name)] = mask

        behavioral_reason_phase_masks: dict[str, dict[str, torch.Tensor]] = {}
        for reason in _BEHAVIORAL_TERMINATION_PHASE_TERMS:
            reason_mask = reason_masks.get(reason, torch.zeros_like(terminated))
            behavioral_reason_phase_masks[reason] = {
                "hidden_wait": reason_mask & ~task_valid,
                "revealed_pre_strike": (
                    reason_mask & task_valid & pre_strike & ~recovering
                ),
                "post_strike": (
                    reason_mask & task_valid & (~pre_strike | recovering)
                ),
            }

        # Commit only after every dynamic reason mask has passed strict dtype/shape selection.
        # A malformed late-listed term must not leave a partially updated decision transaction.
        ledger["terminal_reset_count"].add_(terminated.sum(dtype=torch.long))
        ledger["timeout_reset_count"].add_(timed_out.sum(dtype=torch.long))
        for term_name, mask in reason_masks.items():
            ledger[f"termination_reason_{term_name}_count"].add_(
                mask.sum(dtype=torch.long)
            )
        for reason, phase_masks in behavioral_reason_phase_masks.items():
            for phase, mask in phase_masks.items():
                ledger[f"termination_reason_{reason}_{phase}_count"].add_(
                    mask.sum(dtype=torch.long)
                )

        physical = torch.zeros_like(terminated)
        for term_name in _PHYSICAL_FALL_TERMINATION_TERMS:
            physical |= reason_masks.get(term_name, torch.zeros_like(terminated))
        physical &= terminated
        hard = torch.zeros_like(terminated)
        for term_name in _ACTION_BALL_HARD_TERMINATION_TERMS:
            hard |= reason_masks.get(
                term_name, torch.zeros_like(terminated)
            )
        hard &= terminated
        if (
            getattr(self, "_action_ball_enabled", False)
            and _reference_guard_mode(
                getattr(
                    self.cfg,
                    "reference_guard_mode",
                    _REFERENCE_GUARD_PHASE_GATED,
                )
            )
            == _REFERENCE_GUARD_METRICS_ONLY
        ):
            tracker = getattr(
                self, "_action_ball_reference_guard_metrics", None
            )
            if tracker is None:
                raise RuntimeError(
                    "metrics-only ActionBall hard reset has no "
                    "reference-guard tracker"
                )
            tracker.adjust_hard_overlap(
                env_ids=env_ids,
                hard_mask=hard,
                step_token=getattr(
                    self._env, "common_step_counter", None
                ),
                ledger=ledger,
            )
        true_pre = physical & pre_strike & ~recovering
        post = physical & (~pre_strike | recovering)
        ledger["physical_fall_count"].add_(physical.sum(dtype=torch.long))
        ledger["pre_strike_physical_fall_count"].add_(true_pre.sum(dtype=torch.long))
        ledger["post_strike_physical_fall_count"].add_(post.sum(dtype=torch.long))
        ledger["non_physical_terminal_reset_count"].add_(
            (terminated & ~physical).sum(dtype=torch.long)
        )

    def _book_exact_ready_behavior_samples(self) -> None:
        """Accumulate ready-state balance sums with an explicit denominator per quantity.

        Legacy playback exposes readiness as every hold/recovery step.  Planner-revision playback
        intentionally sets all legacy holds to zero because its initial TTS owns preparation time;
        for that mode, readiness is sampled exactly once on the first metrics tick after each new
        ``(control_epoch, task_id)`` is installed.  This is deliberately named a task-entry sample
        in the ledger, but it is not an in-function instantaneous snapshot of installation.  The
        identity latch is instrumentation-only and never affects observations, rewards, resets,
        sampling, or the phase governor.
        """

        motion = self._motion()
        in_hold = getattr(motion, "in_hold", None)
        if in_hold is None:
            if not getattr(self, "planner_revision_enabled", False):
                return
            eligible = torch.zeros(
                self.num_envs, dtype=torch.bool, device=self.device
            )
        else:
            eligible = in_hold.detach().bool()

        planner_entry = torch.zeros_like(eligible)
        planner_legacy_hold_violation = torch.zeros_like(eligible)
        if getattr(self, "planner_revision_enabled", False):
            if not getattr(motion, "planner_revision_enabled", False):
                raise RuntimeError(
                    "planner ready instrumentation requires the planner-owned motion clock"
                )
            # MotionCommand's constructor already rejects every non-zero legacy hold clock in
            # planner mode.  Keep this device-side runtime witness in case a later state-machine
            # regression nevertheless raises ``in_hold``.  Such a hold must never enter ready
            # denominators: the planner deadline is the sole preparation clock.
            planner_legacy_hold_violation = eligible
            # Unit-test construction may bypass __init__; lazy allocation preserves the same
            # zero/zero sentinel used by the real constructor without weakening live validation.
            if not hasattr(self, "_exact_ready_sampled_control_epoch"):
                self._exact_ready_sampled_control_epoch = torch.zeros(
                    self.num_envs, dtype=torch.long, device=self.device
                )
                self._exact_ready_sampled_task_id = torch.zeros(
                    self.num_envs, dtype=torch.long, device=self.device
                )
            epoch = self._planner_control_epoch.detach()
            task = self._planner_task_id.detach()
            active = motion._planner_active.detach().bool()
            planner_entry = (
                active
                & (epoch > 0)
                & (task > 0)
                & (
                    (epoch != self._exact_ready_sampled_control_epoch)
                    | (task != self._exact_ready_sampled_task_id)
                )
            )
            eligible = planner_entry

        ledger = self._ensure_exact_behavior_decision_counters()
        ledger["ready_phase_sample_count"].add_(eligible.sum(dtype=torch.long))
        ledger["ready_planner_task_entry_sample_count"].add_(
            planner_entry.sum(dtype=torch.long)
        )
        ledger["ready_planner_legacy_hold_violation_count"].add_(
            planner_legacy_hold_violation.sum(dtype=torch.long)
        )
        data = self.robot.data
        tilt = torch.acos(self.metrics["base_upright"].detach().clamp(-1.0, 1.0))
        base_speed = torch.linalg.vector_norm(data.root_lin_vel_w[:, :2].detach(), dim=-1)
        station_offset = torch.linalg.vector_norm(
            (self.base_pos_w[:, :2] - self.base_target_pos_w).detach(), dim=-1
        )

        def book(count_key: str, sum_key: str, values: torch.Tensor) -> None:
            finite = eligible & torch.isfinite(values)
            ledger[count_key].add_(finite.sum(dtype=torch.long))
            ledger[sum_key].add_(
                torch.where(finite, values, torch.zeros_like(values)).sum(dtype=torch.float64)
            )
            ledger["ready_nonfinite_value_count"].add_(
                (eligible & ~torch.isfinite(values)).sum(dtype=torch.long)
            )

        book("ready_tilt_eligible_sample_count", "ready_tilt_rad_sum", tilt)
        book(
            "ready_base_speed_eligible_sample_count",
            "ready_base_speed_xy_mps_sum",
            base_speed,
        )
        book(
            "ready_station_offset_eligible_sample_count",
            "ready_station_offset_m_sum",
            station_offset,
        )

        sensor_ready = bool(
            getattr(self, "_foot_idx_robot", ())
            and getattr(self, "_foot_idx_contact", ())
            and getattr(self, "_contact_sensor", None) is not None
        )
        if sensor_ready:
            contact = self.metrics["foot_contact_frac"].detach()
            slip = self.metrics["foot_slip_speed"].detach()
            book(
                "ready_foot_contact_eligible_sample_count",
                "ready_foot_contact_fraction_sum",
                contact,
            )
            book(
                "ready_foot_slip_eligible_sample_count",
                "ready_foot_slip_speed_mps_sum",
                slip,
            )
        else:
            # A zero foot denominator is ambiguous unless the ledger says whether the phase was
            # absent or the contact sensor was unavailable.  Count the latter explicitly; never
            # fabricate zero contact/slip observations.
            ledger["ready_foot_sensor_unavailable_sample_count"].add_(
                eligible.sum(dtype=torch.long)
            )

        if getattr(self, "planner_revision_enabled", False):
            self._exact_ready_sampled_control_epoch[planner_entry] = (
                self._planner_control_epoch[planner_entry]
            )
            self._exact_ready_sampled_task_id[planner_entry] = (
                self._planner_task_id[planner_entry]
            )

    def consume_exact_behavior_decision_counters(self) -> dict[str, torch.Tensor]:
        """Consume one update's behavior and existing sparse-outcome ledgers as one transaction."""

        # The runner calls this once after rollout and before Live/* reporting.  Materialize both
        # private accumulators and their public metric views at that one ordered boundary.
        self.materialize_action_ball_diagnostic_metrics_for_report()
        ledger = self._ensure_exact_behavior_decision_counters()
        if (
            getattr(self, "_action_ball_enabled", False)
            and _reference_guard_mode(
                getattr(
                    self.cfg,
                    "reference_guard_mode",
                    _REFERENCE_GUARD_PHASE_GATED,
                )
            )
            == _REFERENCE_GUARD_METRICS_ONLY
        ):
            tracker = getattr(
                self, "_action_ball_reference_guard_metrics", None
            )
            if tracker is None:
                raise RuntimeError(
                    "metrics-only ActionBall behavior ledger has no "
                    "reference-guard tracker"
                )
            tracker.validate_conservation(ledger)
        snapshot = {name: value.detach().clone() for name, value in ledger.items()}
        with torch.inference_mode():
            for value in ledger.values():
                value.zero_()
        attribution = self._consume_table_guard_attribution_counts()
        self._validate_table_guard_attribution_conservation(
            snapshot, attribution
        )
        overlap = snapshot.keys() & attribution.keys()
        if overlap:
            raise RuntimeError(
                "exact behavior ledger has duplicate table-guard keys: "
                f"{sorted(overlap)}"
            )
        snapshot.update(attribution)
        sparse = self.consume_sparse_reward_eligibility_counters()
        overlap = snapshot.keys() & sparse.keys()
        if overlap:
            raise RuntimeError(f"exact behavior ledger has duplicate sparse keys: {sorted(overlap)}")
        snapshot.update(sparse)
        return snapshot

    def _rally_legacy_values(self) -> tuple[float, dict]:
        """OLD mixed-ledger rally readout (transition-period *_legacy curves + unit tests).

        numerator _vb_inb_acc: books at exact-strike frames, decays only on strike-carrying steps;
        denominator _swing_starts_acc: books at swing starts, decays every step. Different decay
        schedules + booking phase lag => a synchronized reset queue drives the ratio through 1
        (0.31->1.48 oscillation, 2026-07-08 取证). Kept verbatim for new/old comparison only —
        judge with virtual_return_rate_rally (per-swing same-ledger counters, _rally_report).
        """
        enough_e = self._vb_exact_acc >= float(self.cfg.exact_success_min_count)
        _g = (self._vb_inb_acc / max(self._swing_starts_acc, 1e-6)) if enough_e else 0.0
        _per = {}
        for _c, _cn in self._clip_names.items():
            _per[_cn] = (
                (self._vb_inb_acc_c[_c] / max(self._swing_starts_acc_c[_c], 1e-6)) if enough_e else 0.0
            )
        return _g, _per

    def _decay_swing_accounting(self, decay: float) -> None:
        """Once-per-step decay of ALL swing-denominated ledgers (increments live elsewhere:
        _count_swing_starts for starts/falls/rally pairs, _resample_command for HER replay).
        The per-swing rally pair decays HERE — numerator and denominator on one schedule, which
        together with the paired booking in _count_swing_starts is the metric-sync fix."""
        if self._action_ball_diagnostic_device_telemetry_enabled():
            self._decay_action_ball_diagnostic_device_telemetry(
                "swing",
                decay,
            )
        self._swing_starts_acc = decay * self._swing_starts_acc
        self._prestrike_fall_acc = decay * self._prestrike_fall_acc
        self._poststrike_fall_acc = decay * self._poststrike_fall_acc
        self._resample_n_acc = decay * self._resample_n_acc
        self._replay_n_acc = decay * self._replay_n_acc
        self._rally_starts_acc = decay * self._rally_starts_acc
        self._rally_returns_acc = decay * self._rally_returns_acc
        self._drift_n_acc = decay * self._drift_n_acc
        self._drift_sum_acc = decay * self._drift_sum_acc
        self._drift_fwd_sum_acc = decay * self._drift_fwd_sum_acc
        self._station_offset_start_sum_acc = decay * self._station_offset_start_sum_acc
        if self._action_ball_full_mdp_device_command_metrics_enabled():
            self._decay_action_ball_full_mdp_hold_metric_device_state(decay)
        else:
            self._heading_expiry_sum_acc = decay * self._heading_expiry_sum_acc
            self._heading_expiry_n_acc = decay * self._heading_expiry_n_acc
            self._recovery_spawn_sum_acc = decay * self._recovery_spawn_sum_acc
            self._recovery_expiry_sum_acc = decay * self._recovery_expiry_sum_acc
            self._recovery_n_acc = decay * self._recovery_n_acc
        for _c in self._clip_names:
            self._swing_starts_acc_c[_c] = decay * self._swing_starts_acc_c[_c]
            self._prestrike_fall_acc_c[_c] = decay * self._prestrike_fall_acc_c[_c]
            self._poststrike_fall_acc_c[_c] = decay * self._poststrike_fall_acc_c[_c]
            self._rally_starts_acc_c[_c] = decay * self._rally_starts_acc_c[_c]
            self._rally_returns_acc_c[_c] = decay * self._rally_returns_acc_c[_c]

    def _rally_report(self) -> None:
        """virtual_return_rate_rally* from the per-swing SAME-LEDGER counters (metric-sync fix).

        Start and returned-flag of every ended swing are booked TOGETHER (_count_swing_starts)
        and decayed TOGETHER (_decay_swing_accounting), so returns/starts is a decay-weighted
        average of per-swing 0/1 outcomes: <=1 by construction and equal to the true per-swing
        return rate under ANY reset synchronization. 人话:新算法=每拍一票,回了球记 1 没回记 0,
        比值就是真实上台率,永远不会超过 1。The legacy mixed-ledger curve stays available as
        *_legacy during the transition (see _vb_evaluate / _rally_legacy_values)."""
        _min_n = float(self.cfg.exact_success_min_count)
        _enough = self._rally_starts_acc >= _min_n
        self.metrics["virtual_return_rate_rally"][:] = (
            (self._rally_returns_acc / max(self._rally_starts_acc, 1e-6)) if _enough else 0.0
        )
        if self._metric_bucket_accounting_enabled():
            for _c, _cn in self._clip_names.items():
                _cs = self._rally_starts_acc_c[_c]
                self.metrics[f"virtual_return_rate_rally_{_cn}"][:] = (
                    (self._rally_returns_acc_c[_c] / max(_cs, 1e-6)) if _cs >= _min_n else 0.0
                )

    def _stage1_adaptive_sigma_identity(self) -> dict:
        """Return the complete immutable controller recipe for strict resume."""

        return {
            "source": _ADAPTIVE_SIGMA_SOURCE_STAGE1_CLIP_SITE,
            "source_code": _ADAPTIVE_SIGMA_SOURCE_CODES[
                _ADAPTIVE_SIGMA_SOURCE_STAGE1_CLIP_SITE
            ],
            "error_statistic": "full_phase_rms",
            "sigma_pos_min": float(self.cfg.sigma_pos_min),
            "sigma_pos_max": float(self.cfg.sigma_pos_max),
            "sigma_vel_min": float(self.cfg.sigma_vel_min),
            "sigma_vel_max": float(self.cfg.sigma_vel_max),
            "sigma_normal_min": float(self.cfg.sigma_normal_min),
            "sigma_normal_max": float(self.cfg.sigma_normal_max),
            "sigma_update_every": int(self.cfg.sigma_update_every),
            "sigma_ema_scale": float(self.cfg.sigma_ema_scale),
            "exact_success_decay": float(self.cfg.exact_success_decay),
            "exact_success_min_count": float(self.cfg.exact_success_min_count),
            "strike_window_pos_s": float(self.cfg.strike_window_pos_s),
            "strike_window_wide_s": float(self.cfg.strike_window_wide_s),
        }

    def _stage1_exact_resume_state_dict(self) -> dict:
        """Serialize only the Stage-1 sigma ledger and its reset exclusion latch."""

        self._assert_adaptive_sigma_runtime_identity(
            _ADAPTIVE_SIGMA_SOURCE_STAGE1_CLIP_SITE
        )
        return {
            "schema_version": 2,
            "identity": self._stage1_adaptive_sigma_identity(),
            "sigma": {
                "position": float(self._adaptive_sigma_pos),
                "velocity": float(self._adaptive_sigma_vel),
                "normal": float(self._adaptive_sigma_normal),
            },
            "ema": {
                "position_count": float(self._stage1_sigma_pos_n_acc),
                "position_squared_error_sum": float(
                    self._stage1_sigma_pos_err_sq_sum
                ),
                "velocity_count": float(self._stage1_sigma_vel_n_acc),
                "velocity_squared_error_sum": float(
                    self._stage1_sigma_vel_err_sq_sum
                ),
                "normal_count": float(self._stage1_sigma_nrm_n_acc),
                "normal_squared_error_sum": float(
                    self._stage1_sigma_nrm_err_sq_sum
                ),
            },
            "live_state_initialized": bool(
                self._adaptive_sigma_live_state_initialized
            ),
            "reset_exclusion": self._stage1_sigma_reset_exclusion.detach()
            .cpu()
            .clone(),
        }

    def _stage1_load_exact_resume_state_dict(
        self, state: dict, strict: bool = True
    ) -> None:
        """Restore Stage-1 sigma state only when every identity field matches."""

        if strict is not True or not isinstance(state, dict):
            raise ValueError("Stage-1 exact resume requires strict=True and a dict")
        expected_keys = {
            "schema_version",
            "identity",
            "sigma",
            "ema",
            "live_state_initialized",
            "reset_exclusion",
        }
        if set(state) != expected_keys or state.get("schema_version") != 2:
            raise ValueError("Stage-1 exact-resume state schema is invalid")
        if state.get("identity") != self._stage1_adaptive_sigma_identity():
            raise ValueError("Stage-1 adaptive-sigma controller identity changed")
        sigma = state.get("sigma")
        ema = state.get("ema")
        if not isinstance(sigma, dict) or set(sigma) != {
            "position",
            "velocity",
            "normal",
        }:
            raise ValueError("Stage-1 exact-resume sigma state is invalid")
        expected_ema_keys = {
            "position_count",
            "position_squared_error_sum",
            "velocity_count",
            "velocity_squared_error_sum",
            "normal_count",
            "normal_squared_error_sum",
        }
        if not isinstance(ema, dict) or set(ema) != expected_ema_keys:
            raise ValueError("Stage-1 exact-resume EMA state is invalid")
        numeric = [*sigma.values(), *ema.values()]
        if any(
            isinstance(value, bool)
            or not isinstance(value, (int, float))
            or not math.isfinite(float(value))
            or float(value) < 0.0
            for value in numeric
        ):
            raise ValueError("Stage-1 exact-resume numeric state must be finite and nonnegative")
        sigma_values = {
            "position": float(sigma["position"]),
            "velocity": float(sigma["velocity"]),
            "normal": float(sigma["normal"]),
        }
        for channel, lower, upper in (
            ("position", self.cfg.sigma_pos_min, self.cfg.sigma_pos_max),
            ("velocity", self.cfg.sigma_vel_min, self.cfg.sigma_vel_max),
            ("normal", self.cfg.sigma_normal_min, self.cfg.sigma_normal_max),
        ):
            if not float(lower) <= sigma_values[channel] <= float(upper):
                raise ValueError(
                    f"Stage-1 restored {channel} sigma lies outside its configured bounds"
                )
        initialized = state.get("live_state_initialized")
        if type(initialized) is not bool:
            raise ValueError("Stage-1 live_state_initialized must be an exact bool")
        reset_exclusion = state.get("reset_exclusion")
        if (
            not isinstance(reset_exclusion, torch.Tensor)
            or reset_exclusion.dtype != torch.bool
            or tuple(reset_exclusion.shape) != (self.num_envs,)
        ):
            raise ValueError("Stage-1 reset-exclusion latch shape/dtype changed")

        self._adaptive_sigma_pos = sigma_values["position"]
        self._adaptive_sigma_vel = sigma_values["velocity"]
        self._adaptive_sigma_normal = sigma_values["normal"]
        self._stage1_sigma_pos_n_acc = float(ema["position_count"])
        self._stage1_sigma_pos_err_sq_sum = float(
            ema["position_squared_error_sum"]
        )
        self._stage1_sigma_vel_n_acc = float(ema["velocity_count"])
        self._stage1_sigma_vel_err_sq_sum = float(
            ema["velocity_squared_error_sum"]
        )
        self._stage1_sigma_nrm_n_acc = float(ema["normal_count"])
        self._stage1_sigma_nrm_err_sq_sum = float(
            ema["normal_squared_error_sum"]
        )
        self._adaptive_sigma_live_state_initialized = initialized
        self._stage1_sigma_reset_exclusion.copy_(
            reset_exclusion.to(device=self.device)
        )

    def _assert_adaptive_sigma_runtime_identity(self, source: str) -> None:
        """Fail loudly if a resumed controller belongs to a different source/profile."""

        if source != _ADAPTIVE_SIGMA_SOURCE_STAGE1_CLIP_SITE:
            return
        expected_identity = self._stage1_adaptive_sigma_identity()
        expected = (
            expected_identity["source_code"],
            expected_identity["sigma_pos_min"],
            expected_identity["sigma_pos_max"],
            expected_identity["sigma_vel_min"],
            expected_identity["sigma_vel_max"],
            expected_identity["sigma_normal_min"],
            expected_identity["sigma_normal_max"],
        )
        names = (
            "_adaptive_sigma_source_code",
            "_adaptive_sigma_profile_pos_min",
            "_adaptive_sigma_profile_pos_max",
            "_adaptive_sigma_profile_vel_min",
            "_adaptive_sigma_profile_vel_max",
            "_adaptive_sigma_profile_nrm_min",
            "_adaptive_sigma_profile_nrm_max",
        )
        # Dependency-light tests construct the command with ``__new__``.  Real
        # Stage-1 commands always initialize these fields; populate only that test seam.
        for name, value in zip(names, expected):
            if not hasattr(self, name):
                setattr(self, name, value)
        live = tuple(getattr(self, name) for name in names)
        if live != expected:
            raise RuntimeError(
                "adaptive-sigma checkpoint identity differs from the active source/bounds: "
                f"checkpoint={live!r}, runtime={expected!r}"
            )

    def _resolve_adaptive_sigma_terms(
        self, source: str, normal_on: bool
    ) -> dict[str, dict]:
        """Resolve and validate the complete term set before an atomic width write."""

        required = {
            "racket_position": ("std",),
            "racket_velocity": ("std",),
        }
        if normal_on:
            required["racket_normal"] = ("std",)
        if source == _ADAPTIVE_SIGMA_SOURCE_BALL_EXACT:
            required["racket_strike_success"] = (
                ("std_pos", "std_vel", "std_normal")
                if normal_on
                else ("std_pos", "std_vel")
            )
        resolved: dict[str, dict] = {}
        term_cfgs = {}
        try:
            for term_name, param_names in required.items():
                term_cfg = self._env.reward_manager.get_term_cfg(term_name)
                params = term_cfg.params
                missing = [name for name in param_names if name not in params]
                if missing:
                    raise ValueError(
                        f"reward term {term_name!r} is missing parameters {missing!r}"
                    )
                resolved[term_name] = params
                term_cfgs[term_name] = term_cfg
        except (AttributeError, TypeError, ValueError) as exc:
            raise ValueError(
                "adaptive_sigma_monotonic requires a complete atomic reward-term set "
                "before updating position/velocity/normal widths"
            ) from exc

        if source == _ADAPTIVE_SIGMA_SOURCE_STAGE1_CLIP_SITE:
            expected_funcs = {
                "racket_position": "stage1_clip_racket_position_tracking_exp",
                "racket_velocity": "stage1_clip_racket_velocity_tracking_exp",
                "racket_normal": "stage1_clip_racket_normal_tracking_exp",
            }
            actual_funcs = {
                name: getattr(getattr(term_cfgs[name], "func", None), "__name__", None)
                for name in expected_funcs
            }
            if actual_funcs != expected_funcs:
                raise ValueError(
                    "stage1_clip_site_full_phase_rms adaptive sigma requires the three ball-free "
                    f"clip-site reward functions, got {actual_funcs!r}"
                )
        return resolved

    @staticmethod
    def _adaptive_sigma_live_widths(
        resolved: dict[str, dict], source: str, normal_on: bool
    ) -> tuple[float, float, float | None]:
        """Validate live widths and the legacy additive/product lockstep contract."""

        try:
            live_pos = float(resolved["racket_position"]["std"])
            live_vel = float(resolved["racket_velocity"]["std"])
            live_normal = (
                float(resolved["racket_normal"]["std"]) if normal_on else None
            )
            live_values = [live_pos, live_vel]
            if live_normal is not None:
                live_values.append(live_normal)
            if source == _ADAPTIVE_SIGMA_SOURCE_BALL_EXACT:
                succ = resolved["racket_strike_success"]
                live_succ_pos = float(succ["std_pos"])
                live_succ_vel = float(succ["std_vel"])
                live_values.extend((live_succ_pos, live_succ_vel))
                live_succ_normal = (
                    float(succ["std_normal"]) if normal_on else None
                )
                if live_succ_normal is not None:
                    live_values.append(live_succ_normal)
        except (KeyError, TypeError, ValueError) as exc:
            raise ValueError(
                "adaptive_sigma_monotonic requires finite numeric live reward widths"
            ) from exc
        if not all(math.isfinite(value) and value > 0.0 for value in live_values):
            raise ValueError(
                "adaptive_sigma_monotonic requires finite positive live reward widths"
            )
        if source == _ADAPTIVE_SIGMA_SOURCE_BALL_EXACT and (
            live_pos != live_succ_pos
            or live_vel != live_succ_vel
            or (normal_on and live_normal != live_succ_normal)
        ):
            raise ValueError(
                "adaptive_sigma_monotonic requires additive and strike-success widths "
                "to be exactly lockstep before an atomic update"
            )
        return live_pos, live_vel, live_normal

    @staticmethod
    def _commit_adaptive_sigma_widths(
        resolved: dict[str, dict],
        source: str,
        sigma_pos: float,
        sigma_vel: float,
        sigma_normal: float | None,
    ) -> None:
        """Commit one already-validated three-channel state without partial writes."""

        resolved["racket_position"]["std"] = sigma_pos
        resolved["racket_velocity"]["std"] = sigma_vel
        if sigma_normal is not None:
            resolved["racket_normal"]["std"] = sigma_normal
        if source == _ADAPTIVE_SIGMA_SOURCE_BALL_EXACT:
            succ = resolved["racket_strike_success"]
            succ["std_pos"] = sigma_pos
            succ["std_vel"] = sigma_vel
            if sigma_normal is not None:
                succ["std_normal"] = sigma_normal

    def _prepare_stage1_adaptive_sigma_live_state(
        self, resolved: dict[str, dict]
    ) -> tuple[float, float, float]:
        """Initialize or resume the Stage-1 RewardManager widths before this step's rewards."""

        live_pos, live_vel, live_normal = self._adaptive_sigma_live_widths(
            resolved, _ADAPTIVE_SIGMA_SOURCE_STAGE1_CLIP_SITE, True
        )
        if live_normal is None:
            raise RuntimeError("Stage-1 adaptive sigma lost its required normal width")
        initialized = bool(
            getattr(self, "_adaptive_sigma_live_state_initialized", False)
        )
        if not initialized:
            expected_start = (
                float(self.cfg.sigma_pos_max),
                float(self.cfg.sigma_vel_max),
                float(self.cfg.sigma_normal_max),
            )
            if (live_pos, live_vel, live_normal) != expected_start:
                raise ValueError(
                    "Stage-1 adaptive sigma reward widths must start at the configured maxima: "
                    f"live={(live_pos, live_vel, live_normal)!r}, expected={expected_start!r}"
                )
            self._adaptive_sigma_pos = live_pos
            self._adaptive_sigma_vel = live_vel
            self._adaptive_sigma_normal = live_normal
            self._adaptive_sigma_live_state_initialized = True
            return live_pos, live_vel, live_normal

        saved = (
            float(self._adaptive_sigma_pos),
            float(self._adaptive_sigma_vel),
            float(self._adaptive_sigma_normal),
        )
        if (live_pos, live_vel, live_normal) != saved:
            # A newly constructed RewardManager starts from YAML maxima after checkpoint load.  The
            # restored controller is authoritative; re-apply all three saved widths together before
            # rewards compute.  The source/bounds identity was checked immediately above.
            self._commit_adaptive_sigma_widths(
                resolved,
                _ADAPTIVE_SIGMA_SOURCE_STAGE1_CLIP_SITE,
                saved[0],
                saved[1],
                saved[2],
            )
        return saved

    def _accumulate_stage1_adaptive_sigma_ledger(
        self, values: tuple[float, float, float, float, float, float], decay: float
    ) -> None:
        """Apply ordered ``(count, squared-error-sum)`` pairs to the Stage-1 EMA."""

        (
            pos_count,
            pos_squared_error_sum,
            vel_count,
            vel_squared_error_sum,
            nrm_count,
            nrm_squared_error_sum,
        ) = values
        self._stage1_sigma_pos_n_acc = (
            decay * self._stage1_sigma_pos_n_acc + pos_count
        )
        self._stage1_sigma_pos_err_sq_sum = (
            decay * self._stage1_sigma_pos_err_sq_sum + pos_squared_error_sum
        )
        self._stage1_sigma_vel_n_acc = (
            decay * self._stage1_sigma_vel_n_acc + vel_count
        )
        self._stage1_sigma_vel_err_sq_sum = (
            decay * self._stage1_sigma_vel_err_sq_sum + vel_squared_error_sum
        )
        self._stage1_sigma_nrm_n_acc = (
            decay * self._stage1_sigma_nrm_n_acc + nrm_count
        )
        self._stage1_sigma_nrm_err_sq_sum = (
            decay * self._stage1_sigma_nrm_err_sq_sum + nrm_squared_error_sum
        )

    def _update_adaptive_sigma(self, enough: bool, denom: float) -> None:
        """One monotonic sigma controller fed by an explicit legacy or Stage-1 ledger."""

        if not self.cfg.adaptive_sigma:
            return
        source = _adaptive_sigma_source(self.cfg)
        self._assert_adaptive_sigma_runtime_identity(source)
        normal_on = bool(getattr(self.cfg, "adaptive_sigma_normal", False))
        resolved = None
        live_widths = None
        if source == _ADAPTIVE_SIGMA_SOURCE_STAGE1_CLIP_SITE:
            # Stage-1 is always three-channel and monotonic by cfg validation.  Resolve on every
            # command step so a generic exact-resume restore can re-apply saved live params before
            # RewardManager computes this step.
            resolved = self._resolve_adaptive_sigma_terms(source, True)
            live_widths = self._prepare_stage1_adaptive_sigma_live_state(resolved)
            denoms = (
                max(float(self._stage1_sigma_pos_n_acc), 1.0e-6),
                max(float(self._stage1_sigma_vel_n_acc), 1.0e-6),
                max(float(self._stage1_sigma_nrm_n_acc), 1.0e-6),
            )
            minimum = float(self.cfg.exact_success_min_count)
            enough = all(
                value >= minimum
                for value in (
                    self._stage1_sigma_pos_n_acc,
                    self._stage1_sigma_vel_n_acc,
                    self._stage1_sigma_nrm_n_acc,
                )
            )
            pos_mean = math.sqrt(
                max(self._stage1_sigma_pos_err_sq_sum / denoms[0], 0.0)
            )
            vel_mean = math.sqrt(
                max(self._stage1_sigma_vel_err_sq_sum / denoms[1], 0.0)
            )
            nrm_mean = math.sqrt(
                max(self._stage1_sigma_nrm_err_sq_sum / denoms[2], 0.0)
            )
            for channel, count, rms in (
                ("pos", self._stage1_sigma_pos_n_acc, pos_mean),
                ("vel", self._stage1_sigma_vel_n_acc, vel_mean),
                ("normal", self._stage1_sigma_nrm_n_acc, nrm_mean),
            ):
                self.metrics[f"adaptive_sigma_{channel}_full_phase_count"][:] = count
                self.metrics[f"adaptive_sigma_{channel}_full_phase_error_rms"][:] = rms
        else:
            pos_mean = self._exact_pos_err_sum / denom
            vel_mean = self._exact_vel_err_sum / denom
            nrm_mean = self._exact_nrm_err_sum / denom if normal_on else 0.0

        if enough and self._env.common_step_counter % int(self.cfg.sigma_update_every) == 0:
            sigma_pos = min(
                max(
                    float(self.cfg.sigma_ema_scale) * pos_mean,
                    float(self.cfg.sigma_pos_min),
                ),
                float(self.cfg.sigma_pos_max),
            )
            sigma_vel = min(
                max(
                    float(self.cfg.sigma_ema_scale) * vel_mean,
                    float(self.cfg.sigma_vel_min),
                ),
                float(self.cfg.sigma_vel_max),
            )
            sigma_normal = None
            if normal_on:
                sigma_normal = min(
                    max(
                        float(self.cfg.sigma_ema_scale) * nrm_mean,
                        float(self.cfg.sigma_normal_min),
                    ),
                    float(self.cfg.sigma_normal_max),
                )
            if bool(getattr(self.cfg, "adaptive_sigma_monotonic", False)):
                if resolved is None:
                    resolved = self._resolve_adaptive_sigma_terms(source, normal_on)
                if live_widths is None:
                    live_widths = self._adaptive_sigma_live_widths(
                        resolved, source, normal_on
                    )
                sigma_pos = min(live_widths[0], sigma_pos)
                sigma_vel = min(live_widths[1], sigma_vel)
                if normal_on:
                    if live_widths[2] is None or sigma_normal is None:
                        raise RuntimeError(
                            "adaptive sigma normal channel vanished during atomic update"
                        )
                    sigma_normal = min(live_widths[2], sigma_normal)
                self._commit_adaptive_sigma_widths(
                    resolved, source, sigma_pos, sigma_vel, sigma_normal
                )
            else:
                # Legacy compatibility path: preserve the historical silent no-op for task variants
                # missing old additive/product terms.  Stage-1 cannot enter this branch.
                try:
                    rm = self._env.reward_manager
                    rm.get_term_cfg("racket_position").params["std"] = sigma_pos
                    rm.get_term_cfg("racket_velocity").params["std"] = sigma_vel
                    succ = rm.get_term_cfg("racket_strike_success").params
                    succ["std_pos"] = sigma_pos
                    succ["std_vel"] = sigma_vel
                    if normal_on:
                        rm.get_term_cfg("racket_normal").params["std"] = sigma_normal
                        succ["std_normal"] = sigma_normal
                except ValueError:
                    pass
            self._adaptive_sigma_pos = sigma_pos
            self._adaptive_sigma_vel = sigma_vel
            if normal_on:
                if sigma_normal is None:
                    raise RuntimeError(
                        "adaptive sigma normal channel vanished before state commit"
                    )
                self._adaptive_sigma_normal = sigma_normal
        self.metrics["adaptive_sigma_pos"][:] = self._adaptive_sigma_pos
        self.metrics["adaptive_sigma_vel"][:] = self._adaptive_sigma_vel
        if normal_on:
            self.metrics["adaptive_sigma_normal"][:] = self._adaptive_sigma_normal

    def _update_metrics(self):
        self._ensure_action_ball_runtime_initialized()
        # CommandTerm.compute() runs _update_metrics() BEFORE _update_command(), so refresh the
        # actual racket FK AND the strike timing here (once per step) — metrics, rewards, and
        # observations then all read the same fresh, phase-aligned buffers (rewards/obs read them
        # after the full command_manager.compute()). _compute_strike_timing must run before any
        # exact_strike / strike_window gating below (see its docstring: the old stale read measured
        # the strike one control frame too late).
        self._compute_racket_state()
        self._refresh_strike_timing_for_policy_step(metrics_pass=True)
        origins = self._env.scene.env_origins
        target_validity = (
            self._action_ball_target_validity_mask
            if self._action_ball_enabled
            else (True, True, True)
        )
        target_pos_valid, target_vel_valid, target_face_valid = target_validity
        # commanded base repositioning = distance of the base target from spawn (0 if coupling disabled).
        self.metrics["base_target_offset_norm"] = torch.norm(self.base_target_pos_w - origins[:, :2], dim=-1)
        # Position is intentionally still evaluated for a validity-000 C211 row:
        # internal progress/footwork diagnostics historically consume that norm.
        # Velocity and face, however, have no consumer when their immutable
        # validity columns are false.  Avoid their vector norm, face-frame
        # construction, dot product, clamp, and acos on every policy step while
        # retaining byte-identical zero-valued public metrics below.
        racket_pos_err_vec = self.racket_pos_w - self.racket_target_pos_w
        pos_err = torch.norm(racket_pos_err_vec, dim=-1)
        if target_vel_valid:
            racket_vel_err_vec = self.racket_lin_vel_w - self.racket_target_vel_w
            vel_err = torch.norm(racket_vel_err_vec, dim=-1)
        else:
            racket_vel_err_vec = torch.zeros_like(self.racket_lin_vel_w)
            vel_err = torch.zeros_like(pos_err)
        if target_face_valid:
            measured_normal, target_normal = face_tracking_pair(self)
            cos_ang = torch.sum(measured_normal * target_normal, dim=-1).clamp(
                -1.0, 1.0
            )
            # 弧度值先算(adaptive sigma 第三通道的驱动量纲),度数只是它的展示换算——数值逐字节同旧式。
            normal_err_rad = torch.acos(cos_ang)
            normal_err_deg = normal_err_rad * (180.0 / math.pi)
        else:
            normal_err_rad = torch.zeros_like(pos_err)
            normal_err_deg = torch.zeros_like(pos_err)
        base_err = torch.norm(self.base_pos_w[:, :2] - self.base_target_pos_w, dim=-1)
        base_pos_rel = self.base_pos_w[:, :2] - origins[:, :2]
        base_err_xy = self.base_pos_w[:, :2] - self.base_target_pos_w

        # Diagnostic-only window-entry distribution.  This samples the same fresh FK/target pair
        # as the reward masks, once per swing, before any PPO-window reporting boundary can consume
        # the ledger.  It does not feed any actor/critic input or task transition.
        if self._action_ball_enabled and target_pos_valid:
            self._book_strike_window_entry_distance_probe(
                self.strike_window, pos_err
            )

        # Episode-wide (instantaneous) target errors.  Invalid ablation columns stay numerically
        # inert; the exact eligible-count metrics below distinguish this zero from a perfect score.
        self.metrics["racket_pos_error"] = (
            pos_err if target_pos_valid else torch.zeros_like(pos_err)
        )
        self.metrics["racket_vel_error"] = (
            vel_err if target_vel_valid else torch.zeros_like(vel_err)
        )
        self.metrics["racket_normal_error_deg"] = (
            normal_err_deg
            if target_face_valid
            else torch.zeros_like(normal_err_deg)
        )
        if self.cfg.face_command:
            # Backward-compatible explicit name for dashboards introduced with the face-frame fix.
            self.metrics["face_cmd_normal_error_deg"] = (
                normal_err_deg
                if target_face_valid
                else torch.zeros_like(normal_err_deg)
            )
        self.metrics["base_pos_error"] = base_err
        self.metrics["time_to_strike_s"] = self.time_to_strike
        self.metrics["pre_strike_flag"] = self.pre_strike.float()
        self.metrics["strike_window_hit_rate"] = self.strike_window.float()
        if self.cfg.target_mode == "reference_perturbed":
            self.metrics["ref_perturb_scale"] = torch.full_like(pos_err, self._perturb_scale())
        else:
            self.metrics["ref_perturb_scale"].zero_()
        # Per-axis ERROR components only (which direction is the miss?). The per-axis actual/target
        # state and the speed/normal-cos scalars were dropped as redundant wandb clutter.
        for axis_idx, axis in enumerate(("x", "y")):
            self.metrics[f"base_pos_{axis}"] = base_pos_rel[:, axis_idx]
            self.metrics[f"base_pos_error_{axis}"] = base_err_xy[:, axis_idx]
        for axis_idx, axis in enumerate(("x", "y", "z")):
            self.metrics[f"racket_pos_error_{axis}"] = (
                racket_pos_err_vec[:, axis_idx]
                if target_pos_valid
                else torch.zeros_like(racket_pos_err_vec[:, axis_idx])
            )
            self.metrics[f"racket_vel_error_{axis}"] = (
                racket_vel_err_vec[:, axis_idx]
                if target_vel_valid
                else torch.zeros_like(racket_vel_err_vec[:, axis_idx])
            )

        # Strike-window-gated: hold the value sampled during the most recent strike window. The gating
        # masks come from the previous _update_command (<=1-step / 20 ms lag at 50 Hz — negligible vs
        # the ±strike_window_s window). Between strikes the held value carries to the next reset.
        in_win = self.strike_window
        exact_strike = torch.abs(self.time_to_strike) <= (0.5 * self._env.step_dt + 1e-6)
        if self._action_ball_enabled and self._action_ball_task_wait_schedule is not None:
            # RESET_WAIT may hold a fully installed attempt internally, but it
            # is not a public task opportunity.  Mask before every latch,
            # sparse denominator, virtual outcome, and exact-strike metric.
            exact_strike = exact_strike & self._action_ball_task_valid
        motion = self._motion()
        if motion.retiming_active:
            # R14: float32 clock drift can (~1e-4/swing) land two consecutive tts values inside the
            # ±dt/2 window; latch so one-shot consumers (vb rewards, exact EMAs, achieved-buffer
            # writes) fire once per swing. The latch re-arms at every target resample.
            exact_strike = exact_strike & ~self._exact_fired
            self._exact_fired = self._exact_fired | exact_strike
        if getattr(motion, "event_timing_enabled", False):
            # Unavailable/infeasible rows remain on the scheduler denominator but must not grade a
            # stale previous target merely because its old clip happens to cross zero.  Before the
            # first origin, the normal exact clip strike is accepted and is the sole arming event.
            exact_strike = exact_strike & motion.event_exact_strike_allowed
            motion.record_event_exact_strike(torch.where(exact_strike)[0])
        # This is the existing single exact opportunity after every task-valid,
        # retiming and event-scheduler one-shot gate.  The Racket compute tail
        # binds this exact device bitset to the next physics transition; it
        # never re-derives eligibility from a later target or clock.
        self._capture_action_ball_single_exact_eligibility(exact_strike)
        (
            pos_target_eligible,
            vel_target_eligible,
            face_target_eligible,
            composite_target_eligible,
        ) = _action_ball_target_metric_eligibility(
            exact_strike, target_validity
        )
        self._advance_post_strike_elapsed(exact_strike)
        self._latch_exact_swing_completion(exact_strike)
        self.metrics["exact_strike_hit_rate"] = exact_strike.float()

        # --- DEBUG: swing-through sign verification (cfg.debug_reward_logging) -----------------------
        # err_minus = ||racket_pos - (target - vel*t_to_strike)||  (the CURRENT form used by the reward)
        # err_plus  = ||racket_pos - (target + vel*t_to_strike)||  (the FLIPPED form the user suspected)
        # Held over the strike window / exact strike so the reset-mean reports the in-window value. Expect
        # err_minus_win < err_plus_win (sign correct) and err_minus_exact ~= err_plus_exact (t~0 collapse).
        if self.cfg.debug_reward_logging:
            _ttf = self.time_to_strike.unsqueeze(-1)
            _tp_minus = self.racket_target_pos_w - self.racket_target_vel_w * _ttf
            _tp_plus = self.racket_target_pos_w + self.racket_target_vel_w * _ttf
            _err_minus = torch.norm(self.racket_pos_w - _tp_minus, dim=-1)
            _err_plus = torch.norm(self.racket_pos_w - _tp_plus, dim=-1)
            _debug_window_eligible = in_win & target_pos_valid & target_vel_valid
            _debug_exact_eligible = (
                exact_strike & target_pos_valid & target_vel_valid
            )
            self.metrics["dbg_err_minus_win"] = torch.where(
                _debug_window_eligible,
                _err_minus,
                self.metrics["dbg_err_minus_win"],
            )
            self.metrics["dbg_err_plus_win"] = torch.where(
                _debug_window_eligible,
                _err_plus,
                self.metrics["dbg_err_plus_win"],
            )
            self.metrics["dbg_err_minus_exact"] = torch.where(
                _debug_exact_eligible,
                _err_minus,
                self.metrics["dbg_err_minus_exact"],
            )
            self.metrics["dbg_err_plus_exact"] = torch.where(
                _debug_exact_eligible,
                _err_plus,
                self.metrics["dbg_err_plus_exact"],
            )
        self.metrics["racket_pos_error_exact_strike"] = torch.where(
            pos_target_eligible,
            pos_err,
            self.metrics["racket_pos_error_exact_strike"],
        )
        self.metrics["racket_vel_error_exact_strike"] = torch.where(
            vel_target_eligible,
            vel_err,
            self.metrics["racket_vel_error_exact_strike"],
        )
        self.metrics["racket_normal_error_deg_exact_strike"] = torch.where(
            face_target_eligible,
            normal_err_deg,
            self.metrics["racket_normal_error_deg_exact_strike"],
        )
        # --- CONDITIONAL exact-strike success (the trustworthy, undiluted metric) -------------------
        # Old bug: strike_composite_success_exact was a per-env HELD value (last exact-strike result,
        # else init 0). CommandTerm.reset() logs mean(metric[env_ids]) over the RESETTING envs then zeros
        # them, so every env that reset without ever registering an exact-strike frame contributed 0 ->
        # the logged value was ~10x diluted vs the true conditional pass rate (raw probe ~0.32 logged
        # ~0.03), and the success-gated curriculum never advanced off ref_perturb_curriculum_start.
        # Fix: report the fraction of *exact-strike samples* that pass each threshold as a sample-weighted
        # EMA, broadcast to every env, so the reset-mean, the curriculum's .mean(), and the per-env value
        # all equal the conditional rate. pos/vel/normal are also logged separately.
        pass_pos = (
            (pos_err < self.cfg.strike_success_pos_thresh)
            & pos_target_eligible
        )
        pass_vel = (
            (vel_err < self.cfg.strike_success_vel_thresh)
            & vel_target_eligible
        )
        pass_normal = (
            (normal_err_deg < self.cfg.strike_success_normal_thresh_deg)
            & face_target_eligible
        )
        pass_comp = (
            pass_pos
            & pass_vel
            & pass_normal
            & composite_target_eligible
        )
        if self._task_first_enabled:
            task_success = (
                pass_comp
                & (base_err < float(self.cfg.task_first_base_success_thresh_m))
                & self._task_first_attempt_active
            )
            self._task_first_attempt_success |= task_success
        decay = float(self.cfg.exact_success_decay)
        # 5/10 cm position buckets on the exact-strike sample (NOT the window-exit frame).
        _pass_5cm = (pos_err < 0.05) & pos_target_eligible
        _pass_10cm = (pos_err < 0.10) & pos_target_eligible
        # Reuse the existing exact sparse strike denominator for unconditional swing completion.
        # Virtual-ball evaluation below adds only its downstream outcomes, so a strike is booked
        # exactly once whether virtual rewards are enabled or not.
        _no_sparse_outcome = torch.zeros_like(exact_strike)
        self._book_sparse_reward_eligibility(
            exact_strike=exact_strike,
            capture=_no_sparse_outcome,
            net_clear=_no_sparse_outcome,
            landing_valid=_no_sparse_outcome,
            legal_return=_no_sparse_outcome,
        )
        # Stage-1 sigma evidence is deliberately derived from the ball-free aligned official clip
        # site, never from ``racket_target_*`` above.  Reuse the reward helper so reward and
        # curriculum cannot drift onto different control points.  Every policy-controlled full-clip
        # sample contributes a count and squared error; RMS prevents a minority of large phase
        # errors from disappearing as quickly as they do under an arithmetic mean.  The six scalars
        # join the existing ordered host packet and therefore add no synchronization boundary.
        _stage1_sigma_metric_tensors: tuple[torch.Tensor, ...] = ()
        if (
            self.cfg.adaptive_sigma
            and _adaptive_sigma_source(self.cfg)
            == _ADAPTIVE_SIGMA_SOURCE_STAGE1_CLIP_SITE
        ):
            from .hope_rewards import stage1_clip_racket_tracking_errors

            (
                _stage1_pos_err,
                _stage1_nrm_err,
                _stage1_vel_err,
            ) = stage1_clip_racket_tracking_errors(self)
            # A reference-state reset can place the robot exactly on the teacher before the actor
            # has produced an action.  Counting that sample would collapse sigma from reset quality,
            # not policy quality (especially with Stage-1's 75% reference initialization).  One
            # policy-controlled step is the minimum causal eligibility.  Ready holds are repeated
            # copies of frame zero rather than clip coverage, and the first post-wrap bookkeeping
            # step is likewise excluded even though wrap_teleport is off in the reviewed recipe.
            _stage1_eligible = ~(
                motion.just_resampled
                | motion.in_hold
                | self._stage1_sigma_reset_exclusion
            )
            _stage1_full_phase_mask_f = _stage1_eligible.to(dtype=pos_err.dtype)
            _stage1_sigma_metric_tensors = (
                _stage1_full_phase_mask_f.sum(),
                (_stage1_pos_err.square() * _stage1_full_phase_mask_f).sum(),
                _stage1_full_phase_mask_f.sum(),
                (_stage1_vel_err.square() * _stage1_full_phase_mask_f).sum(),
                _stage1_full_phase_mask_f.sum(),
                (_stage1_nrm_err.square() * _stage1_full_phase_mask_f).sum(),
            )
            # The latch excludes exactly one command/metrics step after each true reset.
            self._stage1_sigma_reset_exclusion.zero_()

        # Build the exact-metric reductions before VirtualBall so an unauthorized diagnostic can
        # append them to the host packet it already needs for exact-any and identity validation.
        # Formal/default execution still reads the same ordered reductions after VirtualBall.
        _exact_metric_tensors = [
            # Counts are reduced directly in the error dtype so the entire ordered batch can be
            # stacked and copied once.  At the supported environment counts (<=8192), sums of
            # boolean 0/1 values are exact in float32 (well below 2**24), so this exposes exactly
            # the same Python float as the former int64 ``float(sum())``.
            exact_strike.sum(dtype=pos_err.dtype),
            pass_comp.sum(dtype=pos_err.dtype),
            pass_pos.sum(dtype=pos_err.dtype),
            pass_vel.sum(dtype=pos_err.dtype),
            _pass_5cm.sum(dtype=pos_err.dtype),
            _pass_10cm.sum(dtype=pos_err.dtype),
            pass_normal.sum(dtype=pos_err.dtype),
            (pos_err * pos_target_eligible).sum(),
            (vel_err * vel_target_eligible).sum(),
            (normal_err_rad * face_target_eligible).sum(),
        ]
        _exact_metric_tensors.extend(_stage1_sigma_metric_tensors)
        _exact_metric_bucket_order = ()
        if self._metric_bucket_accounting_enabled(motion):
            _exact_metric_bucket_order = tuple(self._clip_names)
            _exact_metric_families = self._metric_bucket_rows()[motion.clip_id]
            for _c in _exact_metric_bucket_order:
                _sel = exact_strike & (_exact_metric_families == _c)
                _sel_pos = _sel & target_pos_valid
                _sel_vel = _sel & target_vel_valid
                _sel_face = _sel & target_face_valid
                _sel_pos_f = _sel_pos.float()
                _sel_vel_f = _sel_vel.float()
                _sel_face_f = _sel_face.float()
                _exact_metric_tensors.extend(
                    (
                        _sel.sum(dtype=pos_err.dtype),
                        (pass_pos & _sel).sum(dtype=pos_err.dtype),
                        (pass_vel & _sel).sum(dtype=pos_err.dtype),
                        (pass_normal & _sel).sum(dtype=pos_err.dtype),
                        (pass_comp & _sel).sum(dtype=pos_err.dtype),
                        (pos_err * _sel_pos_f).sum(),
                        (vel_err * _sel_vel_f).sum(),
                        (normal_err_deg * _sel_face_f).sum(),
                    )
                )
        _prefetched_diagnostic_host_values: tuple[float, ...] = ()
        # Tier-1 virtual-ball at-strike evaluation (one-shot buffers consumed by the virtual_*
        # reward terms after this compute()); no-op (and vb_fired stays False) when disabled.
        # vb_metrics_only runs the same evaluation purely for the virtual_*_rate curves (the
        # reward stack of such tasks has no virtual_* terms, so the caches go unread).
        if self.cfg.virtual_ball or self.cfg.vb_metrics_only:
            _prefetched_diagnostic_host_values = self._vb_evaluate(
                exact_strike,
                pos_err,
                diagnostic_host_scalars=(
                    tuple(_exact_metric_tensors)
                    if self._action_ball_enabled
                    and self._action_ball_diagnostic_unauthorized
                    else ()
                ),
            )
        # SHADOW physical ball (metrics-only): runs AFTER _vb_evaluate so this step's capture gate
        # (vb_fired) and the fresh per-env analytic landing prediction can be consumed/snapshotted.
        if self._shadow is not None:
            self._shadow.update(exact_strike)
        # PHYSICAL ball truth instrument (metrics-only): same seam/ordering as the shadow driver —
        # serve scheduling, exact-strike serve-accuracy measurement, park drive. Off = no-op branch.
        if self._physical is not None:
            self._physical.update(exact_strike)
        # The fresh diagnostic FullMDP graph has no adaptive/curriculum/scorer
        # consumer for these EMA scalars.  Its global recurrence runs here on
        # float64 device state; its bucket recurrence remains at the historical
        # later seam.  Formal/default and every consumer-bearing recipe retain
        # the immediate Python-double path below.
        _full_mdp_device_command_metrics = (
            self._action_ball_full_mdp_device_command_metrics_enabled()
        )
        _full_mdp_exact_metric_row = None
        if _full_mdp_device_command_metrics:
            if _prefetched_diagnostic_host_values or _stage1_sigma_metric_tensors:
                raise RuntimeError(
                    "full-MDP deferred command metrics gained an immediate consumer"
                )
            _full_mdp_exact_metric_row = (
                self._begin_action_ball_full_mdp_exact_metric_device_step(
                    _exact_metric_tensors,
                    decay=decay,
                    bucket_order=_exact_metric_bucket_order,
                )
            )
            if not _exact_metric_bucket_order:
                self._finish_action_ball_full_mdp_exact_metric_device_step(
                    _full_mdp_exact_metric_row,
                    decay=decay,
                    bucket_order=(),
                )
            _exact_metric_bucket_values = {}
        else:
            if _prefetched_diagnostic_host_values:
                _exact_metric_width = len(_exact_metric_tensors)
                if len(_prefetched_diagnostic_host_values) != _exact_metric_width:
                    raise RuntimeError(
                        "diagnostic metric host packet changed width"
                    )
                _exact_metric_values = iter(
                    _prefetched_diagnostic_host_values
                )
            else:
                _exact_metric_values = iter(
                    _batched_host_scalar_values(_exact_metric_tensors)
                )
            self._exact_n_acc = decay * self._exact_n_acc + next(_exact_metric_values)
            self._exact_pass_comp_acc = (
                decay * self._exact_pass_comp_acc + next(_exact_metric_values)
            )
            self._exact_pass_pos_acc = (
                decay * self._exact_pass_pos_acc + next(_exact_metric_values)
            )
            self._exact_pass_vel_acc = (
                decay * self._exact_pass_vel_acc + next(_exact_metric_values)
            )
            self._exact_pass_5cm_acc = (
                decay * self._exact_pass_5cm_acc + next(_exact_metric_values)
            )
            self._exact_pass_10cm_acc = (
                decay * self._exact_pass_10cm_acc + next(_exact_metric_values)
            )
            self._exact_pass_normal_acc = (
                decay * self._exact_pass_normal_acc + next(_exact_metric_values)
            )
            self._exact_pos_err_sum = (
                decay * self._exact_pos_err_sum + next(_exact_metric_values)
            )
            self._exact_vel_err_sum = (
                decay * self._exact_vel_err_sum + next(_exact_metric_values)
            )
            self._exact_nrm_err_sum = (
                decay * self._exact_nrm_err_sum + next(_exact_metric_values)
            )
            if _stage1_sigma_metric_tensors:
                self._accumulate_stage1_adaptive_sigma_ledger(
                    tuple(next(_exact_metric_values) for _ in range(6)), decay
                )
            # Preserve the historic update order: per-clip swing-completion
            # reads the previous bucket state, then exact-quality applies this row.
            _exact_metric_bucket_values = {
                _c: tuple(next(_exact_metric_values) for _ in range(8))
                for _c in _exact_metric_bucket_order
            }
        # UNCONDITIONAL swing accounting: decay the start/fall accumulators at the SAME per-step
        # rate as the exact accumulators (increments happen in _count_swing_starts), then report
        #   swing_completion_rate = exact-strike arrivals / swing starts   (falls count against it)
        #   pre_strike_fall_rate  = pre-strike terminations / swing starts
        # These are the honest companions to the CONDITIONAL composite below, whose denominator
        # only contains exact-strike samples (pre-strike falls are invisible to it).
        self._decay_swing_accounting(decay)
        if _full_mdp_device_command_metrics:
            self._publish_action_ball_full_mdp_pre_bucket_device_metrics()
        # Per-swing SAME-LEDGER rally rate (metric-sync fix): reported here, every step, right
        # after the paired counters decayed together. See _rally_report for the invariants.
        if self.cfg.virtual_ball or self.cfg.vb_metrics_only:
            self._rally_report()
        _s_denom = max(self._swing_starts_acc, 1e-6)
        _s_enough = self._swing_starts_acc >= float(self.cfg.exact_success_min_count)
        if not _full_mdp_device_command_metrics:
            self.metrics["swing_completion_rate"][:] = min(self._exact_n_acc / _s_denom, 1.0) if _s_enough else 0.0
        self.metrics["pre_strike_fall_rate"][:] = min(self._prestrike_fall_acc / _s_denom, 1.0) if _s_enough else 0.0
        self.metrics["post_strike_fall_rate"][:] = (
            min(self._poststrike_fall_acc / _s_denom, 1.0) if _s_enough else 0.0
        )
        # Rally drift ratios: denominator = completed (wrapped) swings, NOT all starts.
        _d_denom = max(self._drift_n_acc, 1e-6)
        _d_enough = self._drift_n_acc >= float(self.cfg.exact_success_min_count)
        self.metrics["base_drift_per_swing"][:] = (self._drift_sum_acc / _d_denom) if _d_enough else 0.0
        self.metrics["base_drift_fwd_per_swing"][:] = (self._drift_fwd_sum_acc / _d_denom) if _d_enough else 0.0
        self.metrics["base_station_offset_at_swing_start"][:] = (
            (self._station_offset_start_sum_acc / _d_denom) if _d_enough else 0.0
        )
        if not _full_mdp_device_command_metrics:
            heading_denom = max(self._heading_expiry_n_acc, 1e-6)
            heading_enough = self._heading_expiry_n_acc >= float(self.cfg.exact_success_min_count)
            self.metrics["base_heading_abs_at_swing_start"][:] = (
                self._heading_expiry_sum_acc / heading_denom if heading_enough else 0.0
            )
            self.metrics["base_heading_hold_expiry_count"][:] = self._heading_expiry_n_acc

            recovery_denom = max(self._recovery_n_acc, 1e-6)
            recovery_enough = self._recovery_n_acc >= float(self.cfg.exact_success_min_count)
            self.metrics["heading_recovery_spawn_yaw"][:] = (
                self._recovery_spawn_sum_acc / recovery_denom if recovery_enough else 0.0
            )
            self.metrics["heading_recovery_expiry_yaw"][:] = (
                self._recovery_expiry_sum_acc / recovery_denom if recovery_enough else 0.0
            )
            # Consumers gate on this count before interpreting a zero error.
            self.metrics["heading_recovery_count"][:] = self._recovery_n_acc
        # HER replay diagnostics: fraction of resampled targets drawn from the achieved buffer
        # (~achieved_target_mix_prob once the per-clip buffers pass achieved_min_fill).
        self.metrics["achieved_replay_frac"][:] = (
            self._replay_n_acc / max(self._resample_n_acc, 1e-6)
            if self._resample_n_acc >= float(self.cfg.exact_success_min_count)
            else 0.0
        )
        for _c, _cn in self._clip_names.items():
            _cd = max(self._swing_starts_acc_c[_c], 1e-6)
            _ce = self._swing_starts_acc_c[_c] >= float(self.cfg.exact_success_min_count)
            if not _full_mdp_device_command_metrics:
                self.metrics[f"swing_completion_rate_{_cn}"][:] = (
                    min(self._exact_n_acc_c[_c] / _cd, 1.0) if _ce else 0.0
                )
            # Fall attribution uses _prev_clip_id (the clip during the fall) while starts use the NEW
            # clip; with uniform clip resampling the denominators match in expectation.
            self.metrics[f"pre_strike_fall_rate_{_cn}"][:] = (
                min(self._prestrike_fall_acc_c[_c] / _cd, 1.0) if _ce else 0.0
            )
            self.metrics[f"post_strike_fall_rate_{_cn}"][:] = (
                min(self._poststrike_fall_acc_c[_c] / _cd, 1.0) if _ce else 0.0
            )

        # --- R-b envelope-violation accounting (cfg.track_envelope_violation; default OFF) --------
        # The envelope no longer terminates under envelope_as_penalty, so terminated-based fall
        # metrics go blind to it — count it here instead. Same z-only expressions as the removed
        # terminations (bad_anchor_pos_z_only / bad_motion_body_pos_z_only), same EMA
        # timescale/denominator as pre_strike_fall_rate: tracking_loss_rate = violation RISING
        # EDGES per swing start; envelope_violated_frac = per-step violation fraction (挂机 monitor).
        if self._envelope_track:
            _em = self._motion()
            if self._envelope_body_idx is None:
                _names = list(self.cfg.envelope_body_names)
                _missing = [n for n in _names if n not in _em.cfg.body_names]
                if _missing:
                    raise ValueError(
                        f"RacketTargetCommand.track_envelope_violation: envelope body name(s) "
                        f"{_missing} not in motion.cfg.body_names {_em.cfg.body_names} — the "
                        "tracking_loss accounting would silently watch the wrong bodies.")
                self._envelope_body_idx = [i for i, n in enumerate(_em.cfg.body_names) if n in _names]
            _eth = float(self.cfg.envelope_threshold)
            _anchor_viol = (_em.anchor_pos_w[:, -1] - _em.robot_anchor_pos_w[:, -1]).abs() > _eth
            _bidx = self._envelope_body_idx
            _body_viol = torch.any(
                (_em.body_pos_relative_w[:, _bidx, -1] - _em.robot_body_pos_w[:, _bidx, -1]).abs() > _eth,
                dim=-1,
            )
            _viol = (_anchor_viol | _body_viol) & ~_em.in_hold
            _rising = _viol & ~self._prev_envelope_viol
            self._prev_envelope_viol = _viol
            _rising_count = _rising.sum(dtype=pos_err.dtype)
            if self._action_ball_diagnostic_device_telemetry_enabled():
                self._tracking_loss_acc = (
                    decay * self._tracking_loss_acc
                )
                self._action_ball_diagnostic_device_telemetry_recur(
                    "tracking",
                    ("_tracking_loss_acc", None),
                    decay,
                    _rising_count,
                )
            else:
                self._tracking_loss_acc = (
                    decay * self._tracking_loss_acc
                    + float(_rising_count)
                )
            self.metrics["envelope_violated_frac"] = _viol.float()
            self.metrics["tracking_loss_rate"][:] = (
                min(self._tracking_loss_acc / _s_denom, 1.0) if _s_enough else 0.0
            )
            if self._metric_bucket_accounting_enabled(_em):
                _rfam = self._metric_bucket_rows()[_em.clip_id]
                for _c, _cn in self._clip_names.items():
                    _bucket_rising = (
                        _rising & (_rfam == _c)
                    ).sum(dtype=pos_err.dtype)
                    if self._action_ball_diagnostic_device_telemetry_enabled():
                        self._tracking_loss_acc_c[_c] = (
                            decay * self._tracking_loss_acc_c[_c]
                        )
                        self._action_ball_diagnostic_device_telemetry_recur(
                            "tracking",
                            ("_tracking_loss_acc_c", _c),
                            decay,
                            _bucket_rising,
                        )
                    else:
                        self._tracking_loss_acc_c[_c] = (
                            decay * self._tracking_loss_acc_c[_c]
                            + float(_bucket_rising)
                        )
                    _cd = max(self._swing_starts_acc_c[_c], 1e-6)
                    _ce = self._swing_starts_acc_c[_c] >= float(self.cfg.exact_success_min_count)
                    self.metrics[f"tracking_loss_rate_{_cn}"][:] = (
                        min(self._tracking_loss_acc_c[_c] / _cd, 1.0) if _ce else 0.0
                    )

        _minimum_target_count = float(self.cfg.exact_success_min_count)
        if _full_mdp_device_command_metrics:
            self._publish_action_ball_full_mdp_exact_global_device_metrics()
            # The predicate proves adaptive sigma and the reference-perturb
            # controller are both off, so these host arguments reach only the
            # no-op head of _update_adaptive_sigma below.
            _composite_target_enough = False
            _composite_target_denom = 1.0
        else:
            (
                _pos_target_count,
                _vel_target_count,
                _face_target_count,
                _composite_target_count,
            ) = _action_ball_target_metric_eligible_counts(
                self._exact_n_acc, target_validity
            )
            _pos_target_enough = _pos_target_count >= _minimum_target_count
            _vel_target_enough = _vel_target_count >= _minimum_target_count
            _face_target_enough = _face_target_count >= _minimum_target_count
            _composite_target_enough = (
                _composite_target_count >= _minimum_target_count
            )
            _pos_target_denom = max(_pos_target_count, 1e-6)
            _vel_target_denom = max(_vel_target_count, 1e-6)
            _face_target_denom = max(_face_target_count, 1e-6)
            _composite_target_denom = max(_composite_target_count, 1e-6)
            self._exact_composite_rate = (
                self._exact_pass_comp_acc / _composite_target_denom
                if _composite_target_enough
                else 0.0
            )
            # Broadcast in place so reset() zeros are refreshed before the next reset logs them.
            self.metrics["strike_composite_success_exact"][:] = self._exact_composite_rate
            self.metrics["strike_pos_pass_exact"][:] = (
                self._exact_pass_pos_acc / _pos_target_denom
                if _pos_target_enough
                else 0.0
            )
            self.metrics["strike_vel_pass_exact"][:] = (
                self._exact_pass_vel_acc / _vel_target_denom
                if _vel_target_enough
                else 0.0
            )
            self.metrics["strike_normal_pass_exact"][:] = (
                self._exact_pass_normal_acc / _face_target_denom
                if _face_target_enough
                else 0.0
            )
            self.metrics["exact_strike_pos_success_5cm"][:] = (
                self._exact_pass_5cm_acc / _pos_target_denom
                if _pos_target_enough
                else 0.0
            )
            self.metrics["exact_strike_pos_success_10cm"][:] = (
                self._exact_pass_10cm_acc / _pos_target_denom
                if _pos_target_enough
                else 0.0
            )
        # Distribution of position error over THIS step's exact-strike samples (p90 + mean), broadcast.
        _ex_errs = pos_err[pos_target_eligible]
        if _ex_errs.numel() > 0:
            self.metrics["exact_strike_pos_err_mean"][:] = _ex_errs.mean()
            self.metrics["exact_strike_pos_err_p90"][:] = torch.quantile(_ex_errs, 0.90)
        if not _full_mdp_device_command_metrics:
            self.metrics["exact_strike_sample_count_decayed"][:] = self._exact_n_acc
            for _channel, _count in (
                ("pos", _pos_target_count),
                ("vel", _vel_target_count),
                ("normal", _face_target_count),
                ("composite", _composite_target_count),
            ):
                self.metrics[
                    f"strike_{_channel}_target_eligible_sample_count_decayed"
                ][:] = _count
        # --- per-clip (forehand/backhand) breakdown of the exact-strike pass rates + errors -----------
        # Same sample-weighted EMA as the global block above, selected by the motion command's clip_id so
        # wandb shows each swing separately. pass_pos/vel/normal already include `& exact_strike`.
        # Multiseg uses its family/per-action buckets; an explicitly named N=1 uses its sole action
        # bucket.  Only an unnamed legacy single-clip run leaves these at 0.
        _motion = self._motion()
        if self._metric_bucket_accounting_enabled(_motion):
            # 按族分桶(legacy 2-clip 族行号==clip_id 逐字节不变;6-clip 下"forehand"桶=正手
            # 三档合计,"backhand"桶=反手三档合计,不再把正手 1.0 档记成反手);
            # 显式命名 N=1 的唯一行就是 action_id 自己。
            _fam = self._metric_bucket_rows()[_motion.clip_id]
            if _full_mdp_device_command_metrics:
                if _full_mdp_exact_metric_row is None:
                    raise RuntimeError(
                        "full-MDP exact command metric row was not retained"
                    )
                self._finish_action_ball_full_mdp_exact_metric_device_step(
                    _full_mdp_exact_metric_row,
                    decay=decay,
                    bucket_order=_exact_metric_bucket_order,
                )
                self._publish_action_ball_full_mdp_exact_bucket_device_metrics()
            for _c, _cn in self._clip_names.items():
                if _full_mdp_device_command_metrics:
                    continue
                (
                    _bucket_n,
                    _bucket_pass_pos,
                    _bucket_pass_vel,
                    _bucket_pass_normal,
                    _bucket_pass_comp,
                    _bucket_pos_err,
                    _bucket_vel_err,
                    _bucket_nrm_err,
                ) = _exact_metric_bucket_values[_c]
                self._exact_n_acc_c[_c] = (
                    decay * self._exact_n_acc_c[_c] + _bucket_n
                )
                self._exact_pass_pos_acc_c[_c] = (
                    decay * self._exact_pass_pos_acc_c[_c] + _bucket_pass_pos
                )
                self._exact_pass_vel_acc_c[_c] = (
                    decay * self._exact_pass_vel_acc_c[_c] + _bucket_pass_vel
                )
                self._exact_pass_normal_acc_c[_c] = (
                    decay * self._exact_pass_normal_acc_c[_c]
                    + _bucket_pass_normal
                )
                self._exact_pass_comp_acc_c[_c] = (
                    decay * self._exact_pass_comp_acc_c[_c] + _bucket_pass_comp
                )
                self._exact_pos_err_sum_c[_c] = (
                    decay * self._exact_pos_err_sum_c[_c] + _bucket_pos_err
                )
                self._exact_vel_err_sum_c[_c] = (
                    decay * self._exact_vel_err_sum_c[_c] + _bucket_vel_err
                )
                self._exact_nrm_err_sum_c[_c] = (
                    decay * self._exact_nrm_err_sum_c[_c] + _bucket_nrm_err
                )
                _n = self._exact_n_acc_c[_c]
                (
                    _pos_n,
                    _vel_n,
                    _face_n,
                    _comp_n,
                ) = _action_ball_target_metric_eligible_counts(
                    _n, target_validity
                )
                _pos_scale = (
                    1.0 / max(_pos_n, 1e-6)
                    if _pos_n >= _minimum_target_count
                    else 0.0
                )
                _vel_scale = (
                    1.0 / max(_vel_n, 1e-6)
                    if _vel_n >= _minimum_target_count
                    else 0.0
                )
                _face_scale = (
                    1.0 / max(_face_n, 1e-6)
                    if _face_n >= _minimum_target_count
                    else 0.0
                )
                _comp_scale = (
                    1.0 / max(_comp_n, 1e-6)
                    if _comp_n >= _minimum_target_count
                    else 0.0
                )
                self.metrics[f"strike_pos_pass_exact_{_cn}"][:] = (
                    self._exact_pass_pos_acc_c[_c] * _pos_scale
                )
                self.metrics[f"strike_vel_pass_exact_{_cn}"][:] = (
                    self._exact_pass_vel_acc_c[_c] * _vel_scale
                )
                self.metrics[f"strike_normal_pass_exact_{_cn}"][:] = (
                    self._exact_pass_normal_acc_c[_c] * _face_scale
                )
                self.metrics[f"strike_composite_success_exact_{_cn}"][:] = (
                    self._exact_pass_comp_acc_c[_c] * _comp_scale
                )
                self.metrics[f"racket_pos_error_exact_strike_{_cn}"][:] = (
                    self._exact_pos_err_sum_c[_c] * _pos_scale
                )
                self.metrics[f"racket_vel_error_exact_strike_{_cn}"][:] = (
                    self._exact_vel_err_sum_c[_c] * _vel_scale
                )
                self.metrics[f"racket_normal_error_deg_exact_strike_{_cn}"][:] = (
                    self._exact_nrm_err_sum_c[_c] * _face_scale
                )
                for _channel, _count in (
                    ("pos", _pos_n),
                    ("vel", _vel_n),
                    ("normal", _face_n),
                    ("composite", _comp_n),
                ):
                    self.metrics[
                        f"strike_{_channel}_target_eligible_sample_count_decayed_{_cn}"
                    ][:] = _count
            # --- HER achieved-target buffer WRITE ---------------------------------------------------
            # Record the racket state the policy ACTUALLY produced at this step's exact-strike frames
            # (pos env-origin-relative, vel world). Alive envs only by construction: terminated envs
            # were reset before the command computes, so their state never lands here. Gated on the mix
            # prob so the buffers cost nothing when replay is off.
            # This is a sampler/replay mutation, not telemetry.  Preserve the historical
            # multisegment-only HER contract even though named N=1 metric accounting is now live.
            if (
                getattr(_motion, "_multiseg", False)
                and self.cfg.achieved_target_mix_prob > 0.0
            ):
                for _c in self._clip_names:
                    _bidx = torch.where(exact_strike & (_fam == _c))[0]
                    _m = int(_bidx.numel())
                    if _m == 0:
                        continue
                    _size = self._ach_pos[_c].shape[0]
                    _rows = (self._ach_ptr[_c] + torch.arange(_m, device=self.device)) % _size
                    self._ach_pos[_c][_rows] = self.racket_pos_w[_bidx] - origins[_bidx]
                    self._ach_vel[_c][_rows] = self.racket_lin_vel_w[_bidx]
                    self._ach_spd[_c][_rows] = _motion.speed_scale[_bidx]
                    self._ach_ptr[_c] = int((self._ach_ptr[_c] + _m) % _size)
                    self._ach_fill[_c] = min(self._ach_fill[_c] + _m, _size)
            for _c, _cn in self._clip_names.items():
                self.metrics[f"achieved_buffer_fill_{_cn}"][:] = float(self._ach_fill[_c])
        # Per-axis position error AT the exact strike frame (which axis is the miss?). The position-only
        # strike_success_exact was dropped — strike_pos_pass_exact above is the same signal, undiluted.
        _axis_err_exact = torch.abs(self.racket_pos_w - self.racket_target_pos_w)
        for _ai, _ax in enumerate(("x", "y", "z")):
            self.metrics[f"racket_pos_error_{_ax}_exact_strike"] = torch.where(
                pos_target_eligible,
                _axis_err_exact[:, _ai],
                self.metrics[f"racket_pos_error_{_ax}_exact_strike"],
            )
        # P2.3 SMASH-style ADAPTIVE TRACKING SIGMA — 摘到 _update_adaptive_sigma(可 host 单测
        # 直接驱动),此处仅按原节拍调用;行为与旧内联块逐字节一致。
        self._update_adaptive_sigma(
            _composite_target_enough, _composite_target_denom
        )
        # A1 target latency diagnostic: constant broadcast, refreshed every step because
        # CommandTerm.reset() zeros metric entries of resetting envs before logging them.
        # (midswing_resample_count is written per step in _update_command while the feature is on.)
        self.metrics["target_delay_steps_in_effect"][:] = float(self._delay_steps)

        # Success-gated curriculum: widen the perturbation only once the smoothed CONDITIONAL exact-strike
        # composite success (fraction of exact-strike samples passing all three thresholds) clears the bar.
        if self.cfg.target_mode == "reference_perturbed" and self.cfg.ref_perturb_success_gated:
            if (
                self._curr_perturb_scale < 1.0
                and _composite_target_enough
                and self._exact_composite_rate > self.cfg.ref_perturb_advance_threshold
            ):
                self._curr_perturb_scale = min(
                    1.0, self._curr_perturb_scale + float(self.cfg.ref_perturb_advance_rate)
                )
        self.metrics["racket_pos_error_at_strike"] = torch.where(
            in_win & target_pos_valid,
            pos_err,
            self.metrics["racket_pos_error_at_strike"],
        )
        self.metrics["racket_vel_error_at_strike"] = torch.where(
            in_win & target_vel_valid,
            vel_err,
            self.metrics["racket_vel_error_at_strike"],
        )
        self.metrics["racket_normal_error_deg_at_strike"] = torch.where(
            in_win & target_face_valid,
            normal_err_deg,
            self.metrics["racket_normal_error_deg_at_strike"],
        )
        self.metrics["strike_success"] = torch.where(
            in_win & target_pos_valid,
            (pos_err < self.cfg.strike_success_pos_thresh).float(),
            self.metrics["strike_success"],
        )
        # Base target is tracked before the strike, so log that error during the pre-strike phase.
        self.metrics["base_pos_error_pre_strike"] = torch.where(
            self.pre_strike, base_err, self.metrics["base_pos_error_pre_strike"]
        )

        # Swing-quality detail held at the most recent strike: actual/target paddle speed and the
        # per-axis position error (which direction is the miss?).
        racket_speed = torch.norm(self.racket_lin_vel_w, dim=-1)
        target_speed = torch.norm(self.racket_target_vel_w, dim=-1)
        axis_err = torch.abs(self.racket_pos_w - self.racket_target_pos_w)
        self.metrics["racket_speed_at_strike"] = torch.where(
            in_win, racket_speed, self.metrics["racket_speed_at_strike"]
        )
        self.metrics["racket_target_speed_at_strike"] = torch.where(
            in_win & target_vel_valid,
            target_speed,
            self.metrics["racket_target_speed_at_strike"],
        )
        self.metrics["racket_pos_error_x_at_strike"] = torch.where(
            in_win & target_pos_valid,
            axis_err[:, 0],
            self.metrics["racket_pos_error_x_at_strike"],
        )
        self.metrics["racket_pos_error_y_at_strike"] = torch.where(
            in_win & target_pos_valid,
            axis_err[:, 1],
            self.metrics["racket_pos_error_y_at_strike"],
        )
        self.metrics["racket_pos_error_z_at_strike"] = torch.where(
            in_win & target_pos_valid,
            axis_err[:, 2],
            self.metrics["racket_pos_error_z_at_strike"],
        )
        # Window-exit-held (kept for continuity; the trustworthy contact-frame version is
        # exact_strike_pos_success_5cm/10cm, computed on the exact-strike mask above).
        self.metrics["strike_success_5cm_window_exit"] = torch.where(
            in_win & target_pos_valid,
            (pos_err < 0.05).float(),
            self.metrics["strike_success_5cm_window_exit"],
        )
        self.metrics["strike_success_10cm_window_exit"] = torch.where(
            in_win & target_pos_valid,
            (pos_err < 0.10).float(),
            self.metrics["strike_success_10cm_window_exit"],
        )

        # Robot-health diagnostics (episode-wide, instantaneous).
        data = self.robot.data
        self.metrics["base_height"] = data.root_pos_w[:, 2]
        self.metrics["base_upright"] = matrix_from_quat(self.base_quat_w)[:, 2, 2]  # 1.0 = perfectly upright
        self.metrics["joint_vel_abs_max"] = torch.max(torch.abs(data.joint_vel), dim=-1).values
        # --- stability diagnostics: absolute base roll/pitch + foot contact/slip --------------------
        # Resolve foot body indices + the contact sensor once (robust to USD Link/link casing; degrades
        # gracefully to 0 if absent so it can never crash training).
        if not getattr(self, "_stab_resolved", False):
            self._stab_resolved = True
            self._foot_idx_robot, self._foot_idx_contact, self._contact_sensor = [], [], None
            try:
                self._foot_idx_robot = list(self.robot.find_bodies([".*ankle_roll.*"])[0])
            except Exception:
                pass
            try:
                cs = self._env.scene.sensors["contact_forces"]
                self._contact_sensor = cs
                self._foot_idx_contact = list(cs.find_bodies([".*ankle_roll.*"])[0])
            except Exception:
                pass
        _roll, _pitch, _ = euler_xyz_from_quat(self.base_quat_w)
        # wrap to (-180, 180] so a level base reads ~0 (euler_xyz_from_quat can return [0, 2pi))
        self.metrics["base_roll_deg"] = torch.rad2deg(torch.atan2(torch.sin(_roll), torch.cos(_roll)))
        self.metrics["base_pitch_deg"] = torch.rad2deg(torch.atan2(torch.sin(_pitch), torch.cos(_pitch)))
        if self._foot_idx_robot and self._contact_sensor is not None and self._foot_idx_contact:
            f_force = torch.norm(self._contact_sensor.data.net_forces_w[:, self._foot_idx_contact, :], dim=-1)  # (E,2)
            in_contact = (f_force > 10.0).float()  # 10 N = the sensor's force_threshold
            self.metrics["foot_contact_frac"] = in_contact.mean(dim=-1)  # 1.0 = both feet planted
            self.feet_contact_frac = self.metrics["foot_contact_frac"]  # clean attr for feet_contact reward
            f_speed = torch.norm(data.body_lin_vel_w[:, self._foot_idx_robot, :2], dim=-1)  # horizontal (E,2)
            _slip_sum = (f_speed * in_contact).sum(dim=-1)  # sum over feet of horizontal speed while in contact
            # metric = MEAN slip over the contacting feet (m/s; planted foot should be ~0).
            self.metrics["foot_slip_speed"] = _slip_sum / in_contact.sum(dim=-1).clamp(min=1.0)
            # reward signal = SUM over feet (so both slipping feet are penalized); pre_strike-gated in the reward.
            self.foot_slip_in_contact = _slip_sum
        # footwork-to-strike signals (racket progress, foot slip²/vel/drag, arm overreach, strike stability)
        self._update_footwork_signals(pos_err)
        if self._has_jpos_limits:
            limits = getattr(data, "soft_joint_pos_limits", None)
            if limits is None:
                limits = data.joint_pos_limits
            half_span = ((limits[..., 1] - limits[..., 0]) * 0.5).clamp(min=1e-6)
            dist = torch.minimum(data.joint_pos - limits[..., 0], limits[..., 1] - data.joint_pos).clamp(min=0.0)
            self.metrics["joint_pos_near_limit_frac"] = ((dist / half_span) < 0.1).float().mean(dim=-1)
        if self._has_torque:
            tau_abs = torch.abs(data.applied_torque)
            self.metrics["joint_torque_abs_mean"] = torch.mean(tau_abs, dim=-1)
            self.metrics["joint_torque_abs_max"] = torch.max(tau_abs, dim=-1).values
        act = getattr(self._env.action_manager, "action", None)
        if act is not None:
            a_abs = torch.abs(act)
            self.metrics["action_abs_mean"] = torch.mean(a_abs, dim=-1)
            self.metrics["action_abs_max"] = torch.max(a_abs, dim=-1).values
            prev_act = getattr(self._env.action_manager, "prev_action", None)
            if prev_act is not None:
                delta_abs = torch.abs(act - prev_act)
                self.metrics["action_delta_abs_mean"] = torch.mean(delta_abs, dim=-1)
                self.metrics["action_delta_abs_max"] = torch.max(delta_abs, dim=-1).values
            else:
                self.metrics["action_delta_abs_mean"].zero_()
                self.metrics["action_delta_abs_max"].zero_()

        # Instrumentation only: hold/recovery phase sums and denominators for this simulator step.
        # These tensors are never read by observations, rewards, resets, curricula or sampling.
        self._book_exact_ready_behavior_samples()

    # ------------------------------------------------------------------ #
    # Observation helpers (base-relative quantities)
    # ------------------------------------------------------------------ #
    def action_ball_target_component_valid(self, component: str) -> bool:
        """Return the run-constant N1 ablation validity bit.

        Legacy/non-ActionBall modes retain all three components.  The value is deliberately a
        Python bool: the first fixed-question ablation runs one recipe per process, so allocating
        an N-env tensor would add work without adding information.
        """

        indices = {"position": 0, "velocity": 1, "face": 2}
        if component not in indices:
            raise ValueError(
                "target component must be 'position', 'velocity', or 'face'"
            )
        if not bool(getattr(self, "_action_ball_enabled", False)):
            return True
        return bool(
            getattr(
                self,
                "_action_ball_target_validity_mask",
                (True, True, True),
            )[indices[component]]
        )

    def racket_target_pos_b(self) -> torch.Tensor:
        """Desired racket position relative to the base (yaw-heading frame). HITTER actor obs.

        PRIVILEGED: uses ``base_pos_w`` (world base position). Mocap streams the base pose at 300 Hz
        during play, but that link is not bridged into the deploy front-end, so this term is fabricated
        at deploy; base-position-freedom is a deliberate robustness choice. Used by the `full` obs mode;
        the deploy-parity mode (legacy task name: `real_sensor_only`) replaces it with
        :meth:`racket_target_pos_b_rel`.
        """
        value = quat_rotate_inverse(
            yaw_quat(self.base_quat_w),
            self.racket_target_pos_w - self.base_pos_w,
        )
        if not self.action_ball_target_component_valid("position"):
            return torch.zeros_like(value)
        return value

    def racket_target_pos_b_rel(self) -> torch.Tensor:
        """Desired racket position relative to the CURRENT racket (FK), in the yaw-heading frame.

        DEPLOY-HONEST (no world base position): expanding the rotation, the base position cancels::

            R_yaw^T (target_w - racket_w) = R_yaw^T(target_w - base_w) - R_yaw^T(racket_w - base_w)
                                          = (target in base frame) - (racket FK in base frame)

        Both terms are computable on the real robot from the planner's target + racket forward
        kinematics (joint encoders), WITHOUT a fabricated base pose. Replaces
        :meth:`racket_target_pos_b` in the deploy-parity observation mode (legacy task name:
        ``real_sensor_only``).

        A1: reads the ACTOR-visible target view (delayed/jittered when the A1 knobs are on;
        the live tensor itself otherwise — byte-identical default). This method backs the
        deploy-parity ACTOR obs only; the critic's :meth:`racket_target_pos_b` stays live.
        """
        value = quat_rotate_inverse(
            yaw_quat(self.base_quat_w),
            self.actor_racket_target_pos_w() - self.racket_pos_w,
        )
        if not self.action_ball_target_component_valid("position"):
            return torch.zeros_like(value)
        return value

    # --- A1 ACTOR-visible target accessors (delayed/jittered view; live aliases when off) ------- #
    def actor_racket_target_pos_w(self) -> torch.Tensor:
        """ACTOR-visible desired racket position (world): the A1 delayed/jittered view when target
        latency/jitter is enabled, else the live tensor itself (zero-overhead alias). Rewards,
        metrics, and the privileged critic keep reading the TRUE live ``racket_target_pos_w``."""
        value = self.delayed_racket_target_pos_w
        if not self.action_ball_target_component_valid("position"):
            return torch.zeros_like(value)
        return value

    def actor_racket_target_vel_w(self) -> torch.Tensor:
        """ACTOR-visible desired racket velocity (world). See :meth:`actor_racket_target_pos_w`."""
        value = self.delayed_racket_target_vel_w
        if not self.action_ball_target_component_valid("velocity"):
            return torch.zeros_like(value)
        return value

    def actor_swing_sign(self) -> torch.Tensor:
        """ACTOR-visible swing sign (forehand +1 / backhand -1), delayed with the target when A1
        latency is on (the swing-type flag rides the same planner->runner message as the target)."""
        return self.delayed_swing_sign

    def actor_target_normal_cmd(self) -> torch.Tensor:
        """Actor-visible demanded face normal from the same atomic A1 message as pos/vel/sign."""
        value = self.delayed_target_normal_cmd
        if not self.action_ball_target_component_valid("face"):
            return torch.zeros_like(value)
        return value

    def actor_time_to_strike(self) -> torch.Tensor:
        """Actor-visible TTS from the configured planner-tuple timing convention.

        The default ``live`` branch returns the live tensor itself (not a copy), preserving the
        historical observation path.  Atomic delayed modes return the materialized ring output;
        rewards, exact-strike gates, physics and the privileged critic never call this accessor.
        """
        if self._delay_tts_mode == "live" and not self.planner_revision_enabled:
            return self.time_to_strike
        return self.delayed_time_to_strike

    def actor_time_to_teacher_start_s(self) -> torch.Tensor:
        """Exact time until the selected action's teacher leaves ready.

        ActionBall freezes one action identity before sampling the incoming
        ball.  MotionCommand owns the resulting pre-swing wait and phase
        governor, so the actor consumes that live clock directly instead of
        relearning it from TTS, target speed and the action one-hot.
        """

        # ObservationManager asks every producer for its shape immediately
        # after CommandManager construction, before the first environment
        # reset.  ActionBall deliberately delays its cross-command binding
        # until this post-construction seam, so initialize it here before
        # reading MotionCommand's timing tensor.  The inactive construction
        # row is exactly zero; the first reset resolves the real receipt time.
        self._ensure_action_ball_runtime_initialized()
        return self._motion().action_ball_pre_swing_wait_remaining_s.to(
            dtype=self.time_to_strike.dtype
        )

    def _target_xy_err_b(self, target_xy_w: torch.Tensor) -> torch.Tensor:
        """(world XY target − current base XY) rotated into the yaw-heading base frame — the shared
        math behind both station-style obs terms (Hitter base_target_pos_b / R10c station anchor)."""
        delta_xy = target_xy_w - self.base_pos_w[:, :2]
        delta = torch.cat([delta_xy, torch.zeros(self.num_envs, 1, device=self.device)], dim=-1)
        return quat_rotate_inverse(yaw_quat(self.base_quat_w), delta)[:, :2]

    def base_target_pos_b(self) -> torch.Tensor:
        """Desired base XY position relative to the current base (yaw-heading frame). HITTER actor obs."""
        return self._target_xy_err_b(self.base_target_pos_w)

    def station_anchor_err_b(self) -> torch.Tensor:
        """R10c 站位锚误差(2 维,actor obs,station_obs 旗标):世界系常数锚点 − 当前 base XY,
        旋进 yaw-heading base 系。与 Hitter 的 base_target_pos_b 同一套数学(见 _target_xy_err_b),
        区别只在目标:这里是 reset 常数(env origin + 偏移 = 出生点),不是采样出来的奖励站位。
        部署侧同 Hitter:mocap base 位置可算相对 Δ,掉 mocap 喂 Δ=0 优雅退化成"没漂"。"""
        return self._target_xy_err_b(self.station_anchor_pos_w)

    # --- HITTER Table-I exact accessors (hitter_pure contract, 2026-07-07) ----------------------- #
    # The paper expresses target vectors in the WORLD frame and gives the actor the base forward
    # vector e_base,x separately (instead of pre-rotating into the heading frame). Deploy sources:
    # position differences = planner target − mocap base position (both in the mocap/table world
    # frame, no rotation needed); e_base,x = IMU orientation after the runner's yaw-align-at-engage.
    def base_forward_xy(self) -> torch.Tensor:
        """Base forward unit vector e_base,x, world-frame xy (HITTER Table I)."""
        fwd = quat_apply(
            self.base_quat_w,
            torch.tensor([1.0, 0.0, 0.0], device=self.device).expand(self.num_envs, 3),
        )[:, :2]
        return fwd / (torch.norm(fwd, dim=-1, keepdim=True) + 1e-6)

    def base_target_delta_xy_w(self) -> torch.Tensor:
        """Target base position p̂_base,xy − p_base,xy, WORLD frame (HITTER Table I)."""
        return self.base_target_pos_w - self.base_pos_w[:, :2]

    def racket_target_rel_base_w(self) -> torch.Tensor:
        """Target racket position relative to the base, WORLD frame (HITTER Table I / §V-B-1:
        "the racket position relative to the base ... expressed in the world frame").
        A1: reads the ACTOR-visible target view (delayed/jittered when the knobs are on)."""
        return self.actor_racket_target_pos_w() - self.base_pos_w

    # ------------------------------------------------------------------ #
    # Debug visualization (no-op stubs; targets are world-frame buffers).
    # ------------------------------------------------------------------ #
    def _set_debug_vis_impl(self, debug_vis: bool):
        pass

    def _debug_vis_callback(self, event):
        pass


@configclass
class RacketTargetCommandCfg(CommandTermCfg):
    """Configuration for :class:`RacketTargetCommand`."""

    class_type: type = RacketTargetCommand

    asset_name: str = MISSING
    motion_command_name: str = "motion"

    # The target is re-sampled per swing (on clip wrap / reset), not on a fixed time schedule,
    # so disable the base CommandTerm time-based resampling.
    resampling_time_range: tuple[float, float] = (1.0e9, 1.0e9)

    # --- racket mount FK ---
    racket_body_name: str = "pingpang_red_Link"
    wrist_body_name: str = "right_wrist_yaw_Link"
    # Exact official pingpang_red_joint / MJCF right_racket-site transform.
    # The old value came from pingbang_ball_joint and was 1.49 um away; tiny in
    # magnitude, but it prevented a literal single-point Isaac/MuJoCo/C++ contract.
    mount_offset: tuple[float, float, float] = (0.21021, 0.032078, 0.032036)
    # Fixed wrist->racket rotation (w, x, y, z); only used in the wrist_offset FK fallback. Identity
    # for the A3 ping-pong URDF (all mount joints are rpy=0). Set non-identity if the mount tilts the
    # paddle relative to the wrist frame.
    mount_quat: tuple[float, float, float, float] = (1.0, 0.0, 0.0, 0.0)
    mount_normal_axis: int = 1  # racket-local +Y is the face normal (red/hitting face; confirmed in Step 11)
    mount_normal_sign: float = 1.0  # +1 = red/forehand face; -1 = black/backhand face
    # 每 clip 一个击球面符号(franco 2026-07-09 拍板:"哪面拍子超前就是哪面"——正反手各用固定的一面)。
    # 病根(M3b 判死取证,= jiayi origin/hitter b7b7dfc 同病):统一正反手策略里两个挥拍用的是拍子
    # 相反的两面(正手=红面/+Y,反手=黑面/−Y),单一标量符号让反手的拍面目标(normal_mode="velocity")
    # 永不可达——+Y 面在反手挥拍里永远不超前,拍面误差被钉在 ~115-137°,综合成功清零(pos/vel 其实
    # 都过),考卷 CF 换拍面=1.000 就是这个签名。设 (正手符号, 反手符号) 例 (1.0, -1.0),顺序 =
    # motion_file 的 clip 顺序(同 strike_phase_per_clip)。空 () = 全部 clip 用标量 mount_normal_sign
    # (默认,现役行为逐位不变)。表长和加载 clip 数不一致、或出现 ±1 以外的值,当场报错(fail-loud,
    # 见 _mount_signs_cfg)。每个 clip 的建议符号用 scripts/suggest_face_sign.py 离线算(触球帧 n·v)。
    mount_normal_sign_per_clip: tuple = ()
    # Source for full-phase clip/paddle imitation. ``robot_fk`` is the legacy reconstruction from
    # retargeted A3 body poses. ``measured_channel`` requires the schema-4 physical blade-center,
    # signed-face and butt-to-blade arrays in every loaded motion NPZ and never falls back to FK.
    motion_teacher_racket_source: str = "robot_fk"

    # --- strike timing (fraction of the reference clip where the paddle meets the ball) ---
    strike_phase: float = 0.46  # HITTER clip: strike at frame 43/94 ≈ 0.46
    # Unified multi-clip (HITTER forehand+backhand single policy): per-clip strike phase, aligned with the
    # MotionLoader segment order (i.e. the order of motion files: forehand, backhand). Empty -> use the
    # scalar strike_phase for every clip. e.g. (0.36, 0.74) for forehand_new + backhand_new.
    strike_phase_per_clip: tuple = ()
    strike_window_s: float = 0.1  # half-window; goal-racket reward active within ±strike_window_s
    # 1c SPLIT strike windows (reward_staged_design 2026-07-08 §② C1; defaults None = both fall
    # back to strike_window_s, byte-identical single-window behavior). When set:
    #   strike_window_pos_s  — TIGHT half-window for racket_position (+ the position factor of
    #                          racket_strike_success): contact must be precise (SMASH 0.02 s).
    #   strike_window_wide_s — WIDE half-window for racket_normal / racket_velocity (SMASH ±0.1 s:
    #                          face+velocity get slack, damping wrist-accel spikes / sim2real gap).
    # The legacy strike_window (strike_window_s) keeps gating the strike-stability penalties and
    # the strike_window_hit_rate metric. 人话:触点要准(紧窗),挥向挥速给余量(宽窗)。
    strike_window_pos_s: float | None = None
    strike_window_wide_s: float | None = None
    strike_success_pos_thresh: float = 0.075  # m; "strike_success" metric = fraction of strikes with racket pos error below this
    strike_success_vel_thresh: float = 0.5  # m/s; exact-strike racket velocity acceptance threshold
    strike_success_normal_thresh_deg: float = 15.0  # deg; exact-strike face-normal acceptance threshold

    # --- nominal stance (offset of the base from the env origin) ---
    base_nominal_offset: tuple[float, float, float] = (0.0, 0.0, 0.93)

    # --- target generation mode ---
    # "uniform": independent box sampling from the *_range fields below (legacy; the boxes are
    #   PLACEHOLDERS not tied to the swing, so the imitated swing's racket may never pass through them).
    # "reference_perturbed": target = the reference swing's racket state AT the strike frame (pos/vel/
    #   normal, computed by the same FK as the actual racket) + a curriculum-scaled uniform perturbation.
    #   Reachable by construction (a perfect imitator scores exactly); the *_range fields are ignored.
    # "hitter_pure": HITTER-faithful (arXiv:2508.21043 §V-B-1 + §IV-C, 2026-07-07): base station sampled
    #   INDEPENDENTLY from base_target_*_range (a STATION BOX, not jitter); racket target on a striking
    #   plane FIXED RELATIVE to the commanded station (racket_pos_range_per_clip = STATION-RELATIVE x/y
    #   offsets, z absolute); face-normal target from normal_mode ("velocity" = paper impact model) —
    #   NEVER the reference-clip normal. No HER, no reference_reach coupling, no curriculum.
    # "task_first": choose an action/clip first, then sample position, scalar speed, raw +Y/A-frame
    #   face and base task around THAT action's manifest-bound reference strike. Each action owns
    #   independent position->speed->face->base levels and a prior-action outcome ledger.
    # "action_ball": choose/freeze the motion action at true reset, sample that action's incoming
    #   ball/base domain, and solve a task with the action's prototype direction fixed.  Solver
    #   rejection is upstream of policy attempts; only an admitted ball/task receipt is installed.
    target_mode: str = "reference_perturbed"
    task_first_manifest_path: str = ""
    task_first_manifest_sha256: str = ""
    task_first_base_success_thresh_m: float = 0.10
    action_ball_manifest_path: str = ""
    action_ball_manifest_sha256: str = ""
    # Immutable policy/runner recipe identity used by curriculum evidence.  A changing live
    # checkpoint is not silently called held-out evidence; launch tooling must pin the intended
    # training/evaluation policy identity explicitly.
    action_ball_policy_contract_sha256: str = ""
    # Formal curriculum authority comes only from one reviewed, tracked JSON receipt.  The file
    # digest pins exact bytes; the canonical 11-key document digest is recomputed and must be in
    # action_ball_evaluation.py's immutable trust set.
    action_ball_evaluator_launch_receipt_path: str = ""
    action_ball_evaluator_launch_receipt_file_sha256: str = ""
    # Formal V4 evaluation runs out-of-process (normally training GPU0 and
    # evaluator GPU1) through one append-only request/evidence/ACK namespace.
    # All four paths/identities are hard-contract inputs; diagnostic runs may
    # leave them empty but can never advance curriculum.
    action_ball_sidecar_launch_receipt_path: str = ""
    action_ball_sidecar_launch_receipt_file_sha256: str = ""
    action_ball_drain_reset_launch_receipt_path: str = ""
    action_ball_drain_reset_launch_receipt_file_sha256: str = ""
    action_ball_evaluation_inbox_root: str = ""
    action_ball_evaluation_owner_id: str = ""
    action_ball_evaluation_run_id: str = ""
    action_ball_frozen_eval_interval_updates: int = 100
    # Franco 2026-07-28 approved DIAGNOSTIC bypass.  True skips the two code
    # trust sets and the certificate chain (canonical motion admission +
    # code-pinned evaluator launch receipt) and binds a diagnostic evaluator
    # authority instead; every artifact the run leaves (hard contract, stdout
    # receipts, exact-resume state, run name) is branded
    # diagnostic_unauthorized=true, and formal/export paths reject the brand
    # fail-loud.  Default false = byte-identical formal behavior.
    action_ball_diagnostic_unauthorized: bool = False
    # ActionBall-only reference envelope policy. ``phase_gated`` is the exact
    # historical behavior: anchor_pos / anchor_ori / ee_body_pos terminate
    # center-phase episodes and are disabled after center. ``metrics_only``
    # keeps all three raw predicates and their per-step evidence ledger alive
    # but returns False to the TerminationManager for those three terms. It
    # never alters base/table/q_des/actual-joint hard safety. Non-ActionBall
    # tasks may only use the default.
    reference_guard_mode: str = _REFERENCE_GUARD_PHASE_GATED
    action_ball_seed: int = 0
    # Optional curriculum-owned literal level-zero question.  The sampler and
    # RNG still run on every reset and consume their normal fixed draw budget,
    # but while all 32 domain levels are exactly zero every physical field is
    # pinned to the profile center.  Any promoted arm restores the manifest's
    # ordinary initial/max support.  This is not a tape or a frozen curriculum.
    action_ball_initial_center_single_question: bool = False
    # Fresh A211/C211-only pre-task reveal schedule.  Historical ActionBall
    # leaves keep this disabled and therefore retain their byte-for-byte timing.
    # The enabled schedule is integer-tick and content addressed by
    # ``action_ball_task_wait.ActionBallTaskWaitSchedule``; changing any value
    # is a new policy/normalizer/checkpoint lineage.
    action_ball_task_wait_enabled: bool = False
    action_ball_task_wait_policy_dt_s: float = 0.02
    action_ball_task_wait_seed: int = 20260804
    action_ball_task_wait_min_wait_ticks: int = 5
    action_ball_task_wait_max_wait_ticks: int = 25
    action_ball_task_wait_episode_horizon_ticks: int = 500
    action_ball_task_wait_required_active_ticks: int = 200
    action_ball_pool_refill_rows: int = 16
    action_ball_fixed_direction: bool = True
    # ``online_solver`` preserves the historical path. ``immutable_tape`` remains the diagnostic
    # N1 target-ablation fixture. ``banded_question_bank`` is a draft current_lm/111 cache: it
    # resolves an exact levels/action/profile/solver block and indexes a precomputed row, but remains
    # diagnostic-only until its question tape and future birth/base coverage close exactly. Validity
    # is ordered [position, velocity, face].
    action_ball_target_source: str = "online_solver"
    # Keep curriculum/sampler/RNG ownership unchanged, but reuse the deterministic
    # numeric solver answer while the complete emitted question is byte-identical.
    # This is useful for fixed-center N1: the first row is solved, later resets
    # hit the bounded per-action cache.  A changed level/stratum/base/ball/aim or
    # physics/motion/solver pin is a natural miss; equal distribution parameters
    # alone never authorize reuse.
    action_ball_reuse_exact_question_until_semantics_change: bool = False
    action_ball_immutable_tape_path: str = ""
    action_ball_immutable_tape_sha256: str = ""
    action_ball_banded_question_bank_path: str = ""
    action_ball_banded_question_bank_sha256: str = ""
    action_ball_target_recipe: str = "current_lm"
    action_ball_target_validity_mask: tuple = (True, True, True)
    # Whether Isaac observation-group noise may be applied to target-derived actor columns.
    # Immutable fixed-question ablations require False: otherwise an invalid zero-filled target
    # position can be repopulated by ObsTerm noise after the accessor returns.
    action_ball_target_observation_noise: bool = True
    # Owner-side seam for the full-key, same-transition exact-strike fact.
    # This is deliberately default-off: enabling it is valid only in a
    # constructed env that also installs the unique post-physics DoneTerm, all
    # nine named RewardTerm consumers, and the runner boundary/checkpoint
    # hooks.  Receipt-free immutable fixed views are rejected rather than
    # assigned a synthetic task identity.
    action_ball_strike_fact_device_enabled: bool = False

    # reference_perturbed perturbation (final half-extents; scaled 0->1 by the curriculum below).
    ref_perturb_pos: tuple[float, float, float] = (0.15, 0.20, 0.15)  # m, per-axis half-range
    ref_perturb_vel: tuple[float, float, float] = (1.0, 1.0, 0.8)  # m/s, per-axis half-range
    ref_perturb_normal: float = 0.30  # face-normal jitter magnitude (added then renormalized)
    # Curriculum: perturbation half-extents ramp from `start`*final to 1.0*final.
    # Success-gated mode (default): `_curr_perturb_scale` starts at `ref_perturb_curriculum_start` and
    # only advances (by `ref_perturb_advance_rate` per control step) once the smoothed exact-strike
    # composite success exceeds `ref_perturb_advance_threshold` — keeps the strike error inside the
    # racket reward kernel's responsive band until the policy demonstrably hits, then widens.
    # Open-loop fallback (success_gated=False): ramp over `ref_perturb_curriculum_steps` control steps
    # (env.common_step_counter); set steps<=0 to disable the ramp (always full).
    ref_perturb_curriculum_steps: int = 30000
    ref_perturb_curriculum_start: float = 0.05
    ref_perturb_success_gated: bool = True
    ref_perturb_advance_threshold: float = 0.30  # widen once smoothed exact-strike composite success > this
    ref_perturb_advance_rate: float = 1.0e-5  # scale increment per control step while above threshold

    # --- reference velocity scaling (stage slow -> fast hitting) ---
    # The sampled racket-velocity target is `ref_vel_scale * reference_vel + perturbation`. The reference
    # forehand clip strikes at ~6 m/s; set <1.0 to train a slower, more controllable hit FIRST (e.g. 0.6
    # -> ~3.6 m/s) and ramp back to 1.0 once the slow strike is accurate. NOTE: at scale!=1.0 the target
    # velocity no longer equals the imitated swing's velocity, so a perfect imitator no longer matches it
    # exactly (the "reachable by construction" guarantee holds for position/normal, not scaled velocity).
    ref_vel_scale: float = 1.0

    # --- clean reference strike velocity (denoise the target velocity) ---
    # The motion's stored body_lin_vel_w is a finite-difference (torch.gradient) of the 30->50 fps
    # interpolated joint trajectory propagated through FK (see scripts/csv_to_npz.py). At the fast,
    # high-jerk racket tip those FD/interpolation errors accumulate to ~1 m/s and are INCONSISTENT with
    # the position trajectory (stored-vel vs central-diff-of-pos differ ~1.1 m/s near the strike). Since
    # the racket-velocity reward target is essentially the reference velocity, that ~1 m/s noise is the
    # floor on racket_vel_error_exact_strike (velEx parked ~0.74 regardless of reward tuning).
    # When True, the cached strike target velocity is recomputed from the FINAL racket FK position
    # (body_pos_w, the same FK as the actual racket) by a centered finite difference over +-window frames,
    # which is consistent with the position the policy actually tracks and rejects single-frame jitter.
    # The legacy False path mixed a COM velocity with a link/site position and
    # is now rejected at runtime; the field remains only to fail old configs
    # loudly instead of silently changing their meaning.
    clean_reference_strike_velocity: bool = True
    clean_strike_vel_window: int = 2  # half-window (frames) for the centered finite difference (try 2 or 3)

    # --- debug logging (sign verification + raw/gated reward kernels) ---
    # When True, RacketTargetCommand logs dbg_err_{minus,plus}_{win,exact} (swing-through sign check) and
    # the reward terms log dbg_{racket_pos,racket_vel,racket_normal,base}_{raw,gated}. Pure logging; no
    # behaviour change. Turn off for production runs (extra wandb scalars).
    debug_reward_logging: bool = False

    # --- R-b envelope-violation accounting (reward_staged_design 2026-07-08 §⑥ R-b细则) ---------
    # True (set by train.py's terminations.envelope_as_penalty translation) -> the command term
    # counts tracking-envelope violations that no longer terminate: tracking_loss_rate
    # (violation rising edges / swing starts, same EMA timescale as pre_strike_fall_rate; per-clip
    # variants too) + envelope_violated_frac (per-step violation fraction — the挂机/loafing
    # monitor). Threshold/bodies mirror TerminationsCfg.anchor_pos/ee_body_pos exactly. Default
    # False = no new metrics, byte-identical logging.
    track_envelope_violation: bool = False
    envelope_threshold: float = 0.25  # m; z-only error, same value the removed terminations used
    # A3 names (mixed casing is INTENTIONAL — matches the URDF; see robots/agibot_a3.py) = the
    # exact list AgibotA3FlatEnvCfg.__post_init__ pins into terminations.ee_body_pos
    # (A3_FEET_BODIES + A3_HAND_BODIES). Resolved against motion.cfg.body_names with a loud
    # error on a missing name.
    envelope_body_names: tuple = (
        "left_ankle_roll_Link", "right_ankle_roll_Link", "left_wrist_yaw_Link", "right_wrist_yaw_Link",
    )

    # --- conditional exact-strike success metric (logging + curriculum gating) ---
    # The logged strike_*_pass_exact / strike_composite_success_exact are a sample-weighted EMA of the
    # exact-strike pass rate: acc = decay*acc + this-step-count each control step. decay ~0.99 gives a
    # ~100-step (~2 s @ 50 Hz) memory; higher = smoother but slower to reflect the current policy. The
    # rate (and the curriculum) only trust it once `exact_success_min_count` decayed samples accumulate.
    exact_success_decay: float = 0.99
    exact_success_min_count: float = 50.0
    # --- metric-sync fix (2026-07-09, correctness — no ablation arm) ---------------------------
    # virtual_return_rate_rally* now uses per-swing SAME-LEDGER counting: at each swing's END the
    # attempt's start and its "returned legally" flag book together and decay together, so the
    # rate is <=1 by construction and immune to synchronized reset queues (the 0.31->1.48
    # oscillation, 2026-07-08 取证定案). This flag additionally keeps the OLD mixed-ledger curves
    # alive under the same names + `_legacy` suffix for one transition period of new/old
    # comparison; flip to False to stop emitting them once the transition ends.
    # 人话:上台率曲线换了记账法(恒<=1);这个开关只控制"旧算法对照曲线(_legacy)还要不要发"。
    rally_legacy_metrics: bool = True

    # --- P2.3 SMASH-style adaptive tracking sigma (coarse-to-fine reward kernel widths) ---
    # When on, every `sigma_update_every` control steps the racket_position/racket_velocity reward
    # stds (and racket_strike_success's std_pos/std_vel) are set to
    #   clamp(sigma_ema_scale * decayed_mean_exact_strike_error, sigma_min, sigma_max)
    # so the exp kernel always brackets the CURRENT operating error band. Replaces the hand-run
    # 1.8 -> 1.0 -> 0.8 -> 0.5 velocity-std curriculum. sigma_*_max should match the task YAML's
    # starting stds; sigma_*_min should sit at the acceptance thresholds (0.075 m / 0.5 m/s).
    adaptive_sigma: bool = False
    # PBHC/KungfuBot-style compatibility mode.  False preserves the historical behavior above;
    # True applies sigma_new=min(sigma_current, clamp(EMA error)) and makes the enabled reward-term
    # update atomic/fail-loud so a later bad window cannot widen or partially update the kernels.
    adaptive_sigma_monotonic: bool = False
    # Error-ledger authority.  The historical/default source grades the sampled racket target at
    # one exact-strike frame.  Stage-1 has no ball-conditioned target: its dedicated source grades
    # the aligned official clip site over every policy-controlled full-clip sample and uses RMS.
    # Keeping this explicit prevents a ball-free recipe from silently contracting sigma from the
    # unrelated legacy ``racket_target_*`` buffers.
    adaptive_sigma_source: str = _ADAPTIVE_SIGMA_SOURCE_BALL_EXACT
    sigma_update_every: int = 500
    sigma_ema_scale: float = 1.0
    sigma_pos_min: float = 0.075
    sigma_pos_max: float = 0.20
    sigma_vel_min: float = 0.5
    sigma_vel_max: float = 1.0
    # 第三通道:拍面法向 sigma(弧度)。SMASH 是 pos/ori/vel 三路一起自适应收紧的;只收
    # pos/vel 会让拍面奖励随 pos 收紧被静默弱化最多 ~7x(reward_redesign_20260725 §2)。
    # True 时 racket_normal.std 与 racket_strike_success.std_normal 一起按 exact-strike
    # 面角误差(弧度)的同一路衰减 EMA 锁步更新:clamp(sigma_ema_scale * mean_err_rad,
    # min, max)。min=0.262(15° 验收线),max=0.52(~2x 验收 = 起步宽度)。默认 False =
    # 逐字节不变;单开(adaptive_sigma=False)在构造期 fail-loud(_validate_adaptive_sigma_cfg)。
    adaptive_sigma_normal: bool = False
    sigma_normal_min: float = 0.262
    sigma_normal_max: float = 0.52

    # --- A1 target latency & time-variance (mocap->planner->runner realism; roadmap A1) -------------
    # MOTIVATION: training otherwise hands the actor a PERFECT, instantly-updated target, while the
    # real loop (mocap -> planner -> runner) delivers it LATE (transport + planning latency), NOISY
    # (ball-prediction error that shrinks as the strike approaches — SMASH Eq. 14), and REFINED
    # mid-swing (the planner re-plans WHERE, not WHEN). PACE injects sensor delays for the same
    # reason. Without this, the mocap-closed-loop deployment faces out-of-distribution target
    # dynamics. Scope: ONLY the ACTOR-visible planner tuple is degraded; rewards, true timing,
    # metrics/gates, the privileged critic, and the achieved-target-replay write use live values.
    # ALL defaults OFF => byte-identical baseline (delay==0 aliases the live target tensors;
    # target_delay_tts_mode="live" returns the live TTS tensor; jitter/prob==0 draw no RNG).
    # actor sees atomic pos/vel/face-command/swing_sign this many 50 Hz steps late。
    # planner_revision_enabled 时语义升级为"耦合传输"(2026-07-25,取代旧 NO-LAUNCH 守卫):
    # 延迟改发生在修订"提交"侧——生成于 t 的修订元组(pos/vel/normal/tts,原子)t+d 才提交给
    # 相位调度器,接受记账 / 调度器 desired_tts / actor 元组同吃一条延迟流(mocap→relay 语义);
    # actor 端不再叠观测延迟环。BEGIN(任务安装)保持即时。要求 target_delay_tts_mode 为
    # source_timestamp_compensated(或显式阴性对照 uncompensated);'live' fail-loud。
    target_delay_steps: int = 0
    # Actor-visible TTS convention:
    #   live                         historical behavior; target fields can be delayed but TTS is live.
    #   source_timestamp_compensated TTS rides the same delayed tuple, then the runner-equivalent
    #                                source timestamp correction subtracts delay_steps * step_dt.
    #   uncompensated                TTS rides the tuple without correction (explicit stale-TTS
    #                                negative control; diagnoses "planner says wait" failures).
    # With delay_steps=0 both atomic modes are numerically equivalent to live.  Reward/critic/strike
    # masks always use ``time_to_strike`` and are unaffected by this actor-only switch.
    target_delay_tts_mode: str = "live"
    # SMASH-style tts-decaying gaussian noise on the ACTOR-visible target, drawn ONCE per step on the
    # ring-buffer push (determinism within a step): per-step std = knob * clamp(time_to_strike, 0, 1),
    # i.e. the knob is the std at time_to_strike >= 1 s, decaying to 0 at the strike (prediction
    # convergence). Units: m (pos) / m/s (vel).
    target_jitter_pos_per_s: float = 0.0
    # Calibrated mocap MEASUREMENT noise on the actor-visible target position (m). Venue fit
    # 2026-07-03 (`capture.position_noise`): white 0.0019, ar1 marginal 0.0052, rho/frame 0.946
    # @300 Hz -> 0.946**6 = 0.717 per 50 Hz policy step. Defaults OFF.
    target_noise_white: float = 0.0
    target_noise_ar1_sigma: float = 0.0
    target_noise_ar1_rho: float = 0.717
    # A1 v2 — the three Ace-style sensor defects the mocap link actually has (venue capture fit:
    # occlusion gaps concentrate at contacts, gap_p50 10 ms / racket occlusion ~30 ms; re-lock
    # after a contact carries a fresh systematic bias). All default OFF.
    target_dropout_prob: float = 0.0        # per-step P(frame lost) -> actor view holds last value
    target_post_strike_dropout_s: float = 0.0  # forced hold-last window right after each strike (s)
    target_bias_per_swing: float = 0.0      # m: constant bias per swing, resampled at swing start
    target_jitter_vel_per_s: float = 0.0
    # Mid-swing target refinement: each control step, envs with pre_strike AND time_to_strike >
    # midswing_resample_tts_floor re-draw their target (position/velocity/normal via the existing
    # sampling path) with this per-step probability. Strike timing is untouched (same strike step),
    # no swing start is counted, and the racket-progress baseline is reset so the target jump creates
    # no fake progress.
    midswing_resample_prob: float = 0.0
    midswing_resample_tts_floor: float = 0.3  # s; no refinement inside the last `floor` seconds before the strike

    # Replacement for truth-redrawing midswing_resample: one physical ball keeps one immutable
    # task identity while the actor receives bounded, atomically revised planner estimates every
    # policy step.  All fields are installed from one task.planner_revision block by train.py;
    # manually enabling only one command term fails closed at runtime.
    planner_revision_enabled: bool = False
    planner_revision_profile: dict | None = None
    planner_revision_initial_tts_range_s: tuple[float, float] = (0.5, 1.5)
    planner_revision_initial_tts_mixture: dict | None = None
    planner_revision_position_std_m: float = 0.0
    planner_revision_velocity_std_mps: float = 0.0
    planner_revision_normal_std_rad: float = 0.0
    planner_revision_tts_std_s: float = 0.0

    # --- Tier-1 VIRTUAL INCOMING BALL + at-strike landing evaluation (rewardDesign.md) -----------
    # Per swing, a virtual incoming ball (v_in, omega_in) is sampled that BY CONSTRUCTION arrives at
    # the racket target point at the strike time. On the exact-strike frame, the achieved racket FK
    # state is pushed through the venue-fitted paddle contact model (virtual_ball.predict_paddle_
    # contact, e(u_n) restitution) and a coarse RK4 landing rollout; the cached outcome buffers feed
    # the one-shot virtual_* reward terms in hope_rewards.py. No obs change; 175-D contract untouched.
    virtual_ball: bool = False
    # METRICS-ONLY virtual ball (franco 2026-07-06 "训练的时候以上台率为准"): run the same
    # per-swing ball sampling + at-strike contact/landing evaluation PURELY for the
    # virtual_*_rate metrics (in-training 上台率/击球率 curves) on tasks whose reward stack has
    # no virtual_* terms (DeployParity / Hitter). No reward change; the vb_* one-shot caches are
    # simply never consumed. Default OFF (the per-swing sampling consumes RNG, so byte-exact
    # reproducibility of old runs is preserved); pinned ON in the jiayi-lineage task YAMLs.
    vb_metrics_only: bool = False
    # Incoming-ball velocity box (world/env frame, m/s; -x = toward the robot). Kept inside the venue
    # fit's validity envelope (ball speed 1-7 m/s); vertical component ~near-apex-to-descending.
    vb_vel_x_range: tuple[float, float] = (-4.5, -2.0)
    vb_vel_y_range: tuple[float, float] = (-0.6, 0.6)
    vb_vel_z_range: tuple[float, float] = (-1.0, 0.5)
    # OPTIONAL PER-CLIP incoming-ball velocity boxes, shaped exactly like racket_vel_range_per_clip:
    # a tuple indexed by clip_id of ((x_lo,x_hi),(y_lo,y_hi),(z_lo,z_hi)). None -> the shared
    # vb_vel_*_range box for every clip (BACKWARD COMPATIBLE, byte-identical to today).
    # 人话:这是"给挡球喂快球、给拉球喂慢球"的开关。拍速和来球速度大约 1:1 互相替代(实测相关
    # 系数 -0.61),所以每个动作有自己的最佳来球速度;一个全局球箱会把某些动作的峰值排除在外
    # ——bh_loop_c 在自己速度下峰值 5.12 m/s、而球箱是 2.0-4.6,分数 0.150,就是这么来的。
    # Length is checked against the loaded clip count at construction (fail-loud, like
    # strike_phase_per_clip); two rows expand through clip_family_per_clip like the racket boxes.
    vb_vel_range_per_clip: tuple | None = None
    # Incoming spin: per-axis uniform (rad/s). 50 rad/s ~ 8 rev/s per axis keeps |omega| inside the
    # quaternion-validated 0-15 rev/s envelope.
    vb_spin_abs_max: float = 50.0
    # OPTIONAL PER-CLIP |spin| ceiling (rad/s), one per loaded clip. None -> the scalar above for
    # every clip. A block answering heavy topspin and a loop answering a float serve are different
    # regimes, and the ball box is what decides which one a stroke ever meets.
    vb_spin_abs_max_per_clip: tuple | None = None
    # REFERENCE-STRIKE RETURN GATE. > 0 -> at construction, each bound strike frame is scored with
    # the repo's OWN NumPy return scorer (scripts/virtual_return_scorer.py, the same contact +
    # landing contract the in-training metric uses) against balls drawn from THAT CLIP'S OWN
    # incoming regime; a clip whose legal-return fraction falls below this raises, naming the clip
    # and the rate. 0.0 = gate off (the default, byte-identical to today).
    reference_return_gate_min_rate: float = 0.0
    reference_return_gate_samples: int = 256
    reference_return_gate_seed: int = 0
    # Escape hatch for the "landing/net rewards need a solved answer" construction gate.
    allow_unbanked_landing_rewards: bool = False
    # virtual_spin reward semantics: "topspin" = Ace-style outgoing-topspin generation (ball
    # quality); "minimize" = stage-1 placement-first mode (franco 2026-07-04) — reward CANCELING
    # the incoming spin, kernel exp(-|omega_out|^2 / vb_spin_min_sigma^2) on the outgoing spin
    # magnitude, same legal-landing gate. Sigma in rad/s (10 ~ 1.6 rev/s residual).
    vb_spin_mode: str = "topspin"
    vb_spin_min_sigma: float = 10.0
    # CAPTURE GATE: the virtual contact only evaluates when (a) the racket center is within this
    # distance of the ball (= racket 0.075 + ball 0.020, the v0 real-hit radius) at the exact-strike
    # frame, and (b) the paddle is actively moving INTO the ball along the oriented contact normal
    # faster than vb_min_approach_speed (kills the phantom-block / retreating-racket exploit,
    # verify_tier1 (c)3 — a stationary wall-block scores nothing).
    vb_capture_radius: float = 0.095
    vb_min_approach_speed: float = 0.3
    # Virtual table placement in the env frame. The _hopex clips are HOPE +X aligned with the root at
    # the env origin, so the HOPE convention (robot ~0.5 m behind its table end, centered on the
    # width) puts the near table edge at x = +0.5 and the surface at z = +0.76 above the env origin.
    # Net/far-end/half-width follow from the ITTF table (geometry.py): net at near_x + 1.37 etc.
    vb_table_near_x: float = 0.5
    vb_table_surface_z: float = 0.76
    # Landing target on the opponent half (env frame). Default = P2 half center (near_x + 2.055, 0).
    vb_target_x: float = 2.555
    vb_target_y: float = 0.0
    # Reward shaping constants (read by hope_rewards.virtual_*).
    vb_landing_sigma: float = 0.3     # m — Gaussian width on ||landing_xy - target_xy|| (v0 parity)
    vb_net_margin: float = 0.12      # m — target clearance above the net top (v0 pass_net parity)
    vb_net_sigma: float = 0.10       # m — Gaussian width on the net-clearance error
    vb_spin_ref: float = 250.0       # rad/s (~40 rev/s) — full-credit outgoing topspin (Ace-style)
    vb_min_landing_depth: float = 0.3  # m past the net for the in-bounds bonus (dink guard, verify (c)1)
    # Coarse rollout resolution (verify_tier1 (b): h=10 ms, 1.0 s horizon covers 1-7 m/s shots).
    vb_rollout_h: float = 0.01
    vb_rollout_steps: int = 100

    # --- SHADOW physical ball + table (flag-gated, METRICS-ONLY; defaults OFF = byte-identical) --
    # shadow_ball=True spawns one real PhysX ball per env (scene entity "shadow_ball", attached by
    # hope_env_cfg.attach_shadow_ball_scene / the train.py override translation; sphere R/mass from
    # configs/ball_physics_venue.yaml) driven by shadow_ball.ShadowBallDriver: kinematic linear
    # incoming flight to the question contact point, the SAME venue paddle-contact model as the
    # reward path at a captured strike, then dynamic PhysX flight with the venue aero wrench per
    # physics substep and engine-integrated landing metrics (shadow_land_x/y, shadow_hit_count,
    # shadow_miss_count, shadow_vs_virtual_land_err vs the analytic vb prediction). PURE
    # MEASUREMENT: never read by rewards/observations/bank-target logic; requires virtual_ball=True
    # (loud error otherwise). Honesty notes + mechanisms: shadow_ball.py module docstring.
    shadow_ball: bool = False
    # shadow_table=True additionally (a) enables the shadow ball's collider and (b) places the
    # table_tennis static table collider (+ visual USD mesh) at the tracking task's virtual-table
    # pose (near edge x=vb_table_near_x, surface z=vb_table_surface_z, centered on y=0), with the
    # same multiplicative-restitution materials table_tennis uses — so the shadow ball physically
    # bounces where the virtual table is. No net collider (the vb model gates the net
    # analytically). Requires shadow_ball=True.
    shadow_table: bool = False

    # --- PHYSICAL ball + table — Phase A TRUTH INSTRUMENT (flag-gated, METRICS-ONLY; default ----
    # OFF = byte-identical). physical_ball=True spawns one real PhysX ball per env (scene entity
    # "pb_ball") + a real static table collider ("pb_table", + visual USD), attached by
    # hope_env_cfg.attach_physical_ball_scene / the env-cfg physical_ball flag / the train.py
    # task.physical_ball translation, and driven by physical_ball.PhysicalBallManager: each
    # swing's question incoming ball is realized physically — reverse-integrated venue-model
    # launch (arrives at the question contact point with the question incoming velocity exactly
    # at the strike frame), PhysX flight + per-substep venue aero wrench, CODE-DRIVEN fitted
    # table bounce (venue contact.table params), robot pass-through unless the evaluator-only,
    # content-addressed Phase-B rider sets ``physical_ball_impulse`` dynamically. Metrics:
    # pb_serve_err_m /
    # pb_serve_vel_err at the exact-strike frame + serve/bounce/landing counts. PURE MEASUREMENT:
    # never read by rewards/observations/bank-target logic; consumes NO RNG; requires
    # virtual_ball=True (loud error otherwise). Full honesty notes: physical_ball.py docstring.
    physical_ball: bool = False

    # --- reachable racket-target workspace (offsets from the env origin, world frame, meters) ---
    # Used only by target_mode="uniform". PLACEHOLDER ranges (not the reference strike point).
    racket_pos_x_range: tuple[float, float] = (0.25, 0.55)
    racket_pos_y_range: tuple[float, float] = (-0.45, 0.45)
    # Unified multi-clip: |y| sampling range; the SIGN is set per clip (forehand on -y, backhand on +y,
    # per forehand_on_negative_y) so forehand/backhand target regions are non-overlapping (HITTER §IV).
    racket_pos_y_abs_range: tuple[float, float] = (0.05, 0.45)
    racket_pos_z_range: tuple[float, float] = (0.70, 1.15)

    # --- desired racket velocity (world frame, m/s) ---
    racket_vel_x_range: tuple[float, float] = (1.5, 4.0)
    racket_vel_y_range: tuple[float, float] = (-1.0, 1.0)
    racket_vel_z_range: tuple[float, float] = (0.0, 1.5)
    # Optional PER-CLIP velocity boxes (uniform mode + unified multi-clip only). None -> use the SHARED
    # racket_vel_*_range above for every clip (BACKWARD COMPATIBLE: old behavior, nothing changes). When
    # set, it is a tuple indexed by clip_id (0=forehand, 1=backhand — same order as strike_phase_per_clip /
    # the command's _clip_names), each entry ((x_lo,x_hi),(y_lo,y_hi),(z_lo,z_hi)). Reason: the forehand and
    # backhand reference clips have DIFFERENT natural strike speeds (~2.6 vs ~2.0 m/s at the racket), so a
    # single shared box overshoots the slower backhand and its strike can never satisfy the velocity gate.
    # Confirmed by the MuJoCo per-clip eval probe: lowering only the backhand target box raised backhand
    # composite 0.32->0.79 (deterministic) / 0.39->0.77 (dither) with forehand byte-identical.
    racket_vel_range_per_clip: tuple | None = None
    # Escape hatch for the construction-time gate that requires every per-clip velocity box to have
    # x_lo > 0 (+x is toward the opponent, so a non-positive floor lets the sampler command a return
    # that never crosses the net). True = the box is deliberately non-forward (e.g. a block/drop study).
    allow_non_forward_target_velocity: bool = False

    # OPTIONAL per-clip racket target-POSITION boxes (uniform mode, unified multi-clip policy). None ->
    # use the shared racket_pos_x_range + |y|-sign + racket_pos_z_range box for every clip (BACKWARD
    # COMPATIBLE: old behavior, nothing changes). When set, it is a tuple indexed by clip_id (0=forehand,
    # 1=backhand — same order as strike_phase_per_clip), each entry ((x_lo,x_hi),(y_lo,y_hi),(z_lo,z_hi))
    # added to the env origin. NOTE the y range is SIGNED here and used directly, so it REPLACES the
    # shared |y|-sign logic. Reason: each clip's strike frame can sit at a different height/depth/lateral
    # offset, so a shared box can make one clip's strike-frame position unreachable. Per-clip boxes let
    # each clip's target track its own reference strike point.
    racket_pos_range_per_clip: tuple | None = None

    # ORDERED per-clip NAMES (clip_id -> human name), from train.py's ``racket.clip_names``. Empty
    # -> the legacy two family names, and per-clip metric buckets stay FAMILY buckets, byte-identical.
    # 人话:动作库不再只有"正手/反手"两个名字。给了这张表,每个 clip 就有自己的指标桶
    # (virtual_return_rate_<name>),同族的两个动作(拉/挡)不会再共用一个桶——正手回球率
    # 0.0000 藏在 45% 的合计里,就是共用桶造成的。
    clip_names_per_clip: tuple = ()

    # --- HER-style achieved-target replay (uniform mode + unified multi-clip only) -------------------
    # On-policy-compatible hindsight relabeling (Ace/HER, adapted for PPO): true retroactive relabeling is
    # observation-inconsistent here (the target is in the actor obs every step), so instead the NEXT
    # swing's target is drawn, with probability `achieved_target_mix_prob`, from a per-clip ring buffer of
    # racket states the policy ACTUALLY produced at previous exact-strike frames (pos env-origin-relative,
    # vel world). Every replayed target is reachable-by-demonstration — it kills the "the box asks for a
    # point the taught swing never passes through" mismatch without moving the box. Mixture (not pure
    # replay) + jitter + clamping into the per-clip box inflated by `achieved_clamp_inflate` (clamp
    # applies only when per-clip boxes are configured — the unified task always sets them) prevent the
    # target distribution from collapsing onto what the policy already does or drifting far from the
    # training workspace. NOTE the deploy-side target clips must be re-synced to the training boxes
    # whenever the boxes change (they are hand-maintained in pp_policy.hpp / imitate_presets.py).
    # 0.0 = OFF (backward compatible: pure box sampling). TRAIN-ONLY: eval entry points force this to
    # 0.0 so checkpoints are always scored on the pure box distribution. The buffer only fills at
    # exact-strike frames of envs that are still alive, so fallen approaches never contribute targets.
    achieved_target_mix_prob: float = 0.0
    achieved_buffer_size: int = 4096  # per-clip ring buffer capacity (entries)
    achieved_min_fill: int = 256  # replay only once a clip's buffer holds at least this many entries
    achieved_jitter_pos: float = 0.03  # m, uniform per-axis jitter added to a replayed position
    achieved_jitter_vel: float = 0.15  # m/s, uniform per-axis jitter added to a replayed velocity
    achieved_clamp_inflate: float = 0.20  # clamp replayed targets into the per-clip box inflated by this fraction

    # --- desired racket face normal ---
    normal_mode: str = "velocity"  # "velocity" (n = v/|v|) or "sampled"
    racket_normal_x_range: tuple[float, float] = (0.5, 1.0)
    racket_normal_y_range: tuple[float, float] = (-0.3, 0.3)
    racket_normal_z_range: tuple[float, float] = (-0.3, 0.3)

    # --- Stage-1 question bank + face-command channel (defaults OFF; byte-identical baseline) -------
    # Path to an offline bank npz (scripts/gen_stage1_questions.py): per clip a FIXED contact point
    # plus an atomic incoming-ball + inverse-solved answer tuple. Non-empty -> every target
    # resample (reset / wrap / mid-swing) OVERRIDES the sampled incoming velocity/spin and target
    # pos/vel/normal from one bank row; the A1 delay/noise injectors act
    # downstream unchanged. Bank positions are tracking-env-frame (world = env_origin + pos).
    # Empty (default) = OFF: the sampling paths above run untouched, target_normal_cmd stays zeros.
    question_bank: str = ""
    # Explicit reproducibility escape hatch for pre-schema-v2 banks. New research runs must
    # keep this false so missing incoming-spin/provenance cannot be silently inferred.
    question_bank_allow_legacy: bool = False
    # Re-anchor the racket_normal reward (and racket_strike_success through it) onto the demanded
    # target_normal_cmd instead of the clip-locked racket_target_normal_w (the clip-locked face is
    # the 0%-return root cause — eval mode B 2026-07-05). Exact/composite metrics use the same
    # pairing as the reward; the critic reference lane remains unchanged. False = old path.
    face_command: bool = False
    # Reward/critic/metric face pairing. ``shared_plus_y`` is the production A-frame convention;
    # ``legacy_signed_vs_A`` is an explicit diagnostic continuation of the pre-fix mismatch.
    face_command_pairing: str = "shared_plus_y"

    # --- CONTINUOUS question production (owner ruling: 离散题库是考试用的,训练必须连续采样) ----
    # ONE switch: ``target_mode: "solved"``. Everything else below is derived or fail-closed, so
    # there is no second thing an agent has to remember to turn on. The producer is a
    # PRODUCER-CONSUMER BUFFER, not a pool and not a small bank: one batched solve fills it, a
    # cursor hands rows out WITHOUT REPLACEMENT, and a spent row is discarded forever. Statistically
    # identical to solving at every reset; ~1.5% of iteration time instead of ~160% (the solver is
    # kernel-launch bound, so the fix is to make the call RARE, not small).
    cq_buffer_rows: int = 8192          # rows kept per clip; one refill measured at ~258 ms @8192
    cq_overdraw: float = 1.45           # first-pass overdraw (a 2nd call costs full price; this is free)
    cq_n_iters: int = 12                # 100% solve at 12; 4 halves the wall at a visible resid cost
    cq_tol_m: float = 0.02
    cq_speed_budget: float = 3.4        # pp_policy.hpp:234 gate_speed_max - margin (deploy's own number)
    cq_max_redraw_rounds: int = 3
    cq_max_face_deg: float = 35.0       # face-vs-clip-face cap (shipped banks: p50 7.8-9.1, max 20.3)
    # DEFAULT 0.0, NOT the producer's own 50.0: every schema-v3 bank hard-asserts
    # incoming_spin_mode=='zero', so a non-zero default would smuggle a spin regime no shipped
    # calibration has ever covered in on a plumbing change. Opening spin is its own arm.
    cq_spin_abs_max: float = 0.0
    # Aim is a POINT, not a range. The landing reward (hope_rewards.virtual_landing), the
    # virtual_land_err_m metric and the physical ball's return-flight target all read ONE fixed
    # _vb_target_xy; a per-env aim would have the ball solved for A and graded at B with nothing
    # asserting. None -> (vb_target_x, vb_target_y). Unlock by making _vb_target_xy per-env FIRST.
    cq_aim_xy: tuple | None = None
    # Incoming-ball velocity box, per LOADED clip, (num_clips, 3, 2). Required under "solved".
    cq_vel_range_per_clip: tuple | None = None
    # Hold the exam split OUT of training: reject drawn balls whose question_split(v_in) says
    # "exam" (stage1_question_bank.EXAM_FRAC). Costs ~20% more draws and keeps the repo invariant
    # that no trained question IS an exam question — without it a paired exam comparison can grade
    # a policy on balls it trained on.
    cq_exam_holdout: bool = True
    # Dedicated RNG stream for the question draw, so it is reproducible independently of every
    # other sampler's consumption pattern (generate() threads a torch.Generator all the way down).
    cq_seed: int = 0x51501234
    cq_accept_buckets: int = 4          # |v_in_x| bins for the per-regime accept ledger
    cq_max_exhausted_frac: float = 0.10     # above this a refill WARNs with the full histogram
    cq_abort_exhausted_frac: float = 0.50   # above this it raises
    cq_min_accept_rate: float = 0.05    # a bucket below this with enough asks is a config error
    cq_closed_loop_rows: int = 256      # rows re-rolled through the SCORER's own call per refill
    cq_closed_loop_max_err_m: float = 0.10  # the schema's own bound (stage1_question_bank.py:402)
    # CONTRACT ANCHOR: one same-family schema-v3 train bank, loaded and validated but NEVER trained
    # on. It restores what a continuous arm otherwise loses — the physics contract SHA, the runtime
    # motion contract (motion SHA / seg_len / strike_phase), clip-order authority — and it is the
    # boot parity gate's data (K of its stored balls replayed through the live solver).
    cq_anchor_bank: str = ""
    # Exam paper for scripts/judge.sh. Read FIRST, before the legacy question_bank string-replace,
    # so a continuous arm needs no operator memory and no --exam-bank.
    exam_bank: str = ""

    # --- desired base XY target (offsets from the env origin, world frame, meters) ---
    base_target_x_range: tuple[float, float] = (-0.10, 0.10)
    base_target_y_range: tuple[float, float] = (-0.35, 0.35)
    # Weak base->racket coupling (UNIFORM mode only). base_couple_blend = fraction of the racket target's
    # sideways (Y) offset that the base target shifts toward; clamped to ±base_couple_max_offset meters.
    # 0.0 = disabled (spawn-only). Conservative because no walking reference exists (it fights leg imitation).
    base_couple_blend: float = 0.0
    base_couple_max_offset: float = 0.20
    # UNIFORM-mode base-target derivation (HITTER §V-B-1 alignment, 2026-07-05):
    #   "blend"           — legacy: spawn + weak Y blend above (BASE-FREE tasks leave this the default).
    #   "reference_reach" — HITTER separate-commands scheme: base_target = racket_target_xy −
    #                       (reference base→racket strike offset, per clip). Standing AT the commanded
    #                       station puts the racket target at the clip's reference reach — the striking
    #                       plane is fixed RELATIVE TO THE COMMANDED BASE (HITTER's "0.4 m in front"),
    #                       and footwork (mostly lateral) is driven by the base channel, not by
    #                       stretching at a deep world point. base_target_*_range then acts as a JITTER
    #                       around the coupled station (widen y to train y-reach diversity).
    # Sim2real: the paired actor obs (base_target_pos_b) is a RELATIVE Δxy in the yaw-heading frame —
    # deployable from mocap base position (300 Hz, position-only) without any absolute world frame; if
    # mocap drops, feeding Δ=0 degrades gracefully to "already at station" (today's BASE-FREE behavior).
    base_couple_mode: str = "blend"

    # --- R10c 站位锚(station_obs 旗标的数据源;franco 2026-07-09) ---------------------------------
    # 世界系常数锚点相对 env origin 的 XY 偏移(米)。默认 (0,0) = 出生点本身(固定点阶段 clip 已
    # 重落地,frame-0 root xy ≈ origin)。想把"该站的位置"挪开出生点时用它覆盖(如 S2b 身补课程)。
    # 只喂观测 station_anchor_err_b,不进奖励;env 侧开关见 hope_env_cfg.station_obs / train.py
    # racket.station_obs。
    station_anchor_offset_xy: tuple[float, float] = (0.0, 0.0)

    # --- swing-type convention ---
    forehand_on_negative_y: bool = True  # right arm holds the paddle: target on -Y side -> forehand (+1)
